    async def _validate_specific_entities(
        self, dut_id: str, entity_type: str, entity_names: List[str], **kwargs
    ) -> Dict[str, Any]:
        """
        Validate specific entities by name.

        The implementation uses ``dut_id``, ``entity_type``, ``entity_names``,
        and ``kwargs`` to validate specific entities by name. Every required
        invariant is checked before a successful value is returned; invalid
        input follows the function's explicit exception path. Owned asynchronous
        work is awaited before return, so completion does not leave an
        unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            entity_names: Entries supplied as ``entity_names`` without
                transferring container ownership.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``reason``, and ``context``
            fields.
        """
        try:
            entity_policy = discovery_entity_policy(entity_type)
            if entity_policy is None:
                return {
                    "success": False,
                    "reason": f"Unsupported entity type: {entity_type}",
                    "context": {"filtered_entities": []},
                }
            discovery_method = getattr(self, entity_policy.facade_getter)
            discovered_entities = await discovery_method(dut_id)

            if not discovered_entities:
                return {
                    "success": False,
                    "reason": f"No {entity_type} found",
                    "context": {"filtered_entities": []},
                }

            # Get configured URI for the entity type
            entity_uri = self.get_configured_uri(dut_id, entity_policy.uri_key)
            filtered_entities = []

            for entity_id in discovered_entities:
                # Check if this entity matches any of the specified names
                if entity_id in entity_names:
                    entity_uri_full = f"{entity_uri}/{entity_id}"
                    success, entity_data, _ = await self.dispatch_request(
                        dut_id, "GET", entity_uri_full
                    )

                    if success:
                        filtered_entities.append(
                            {
                                "id": entity_id,
                                "model": entity_data.get("Model", ""),
                                "name": entity_data.get("Name", ""),
                                "discovery_source": "specific_selection",
                            }
                        )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Validated {len(filtered_entities)} specific {entity_type}: {[e['id'] for e in filtered_entities]}",
                dut_id,
            )

            return {
                "success": True,
                "context": {
                    "filtered_entities": filtered_entities,
                    "entity_count": len(filtered_entities),
                    "entity_type": entity_type,
                    "discovery_method": "specific_selection",
                },
            }

        except Exception as e:
            return {
                "success": False,
                "reason": str(e),
                "context": {"filtered_entities": []},
            }

    async def _validate_by_baseboard(
        self,
        dut_id: str,
        entity_type: str,
        baseboard_filter: str = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Validate entities based on baseboard configuration.

        The implementation uses ``dut_id``, ``entity_type``,
        ``baseboard_filter``, and ``kwargs`` to validate entities based on
        baseboard configuration. Every required invariant is checked before a
        successful value is returned; invalid input follows the function's
        explicit exception path. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            baseboard_filter: Optional baseboard filter; ``None`` selects the
                function's default behavior.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``reason``, and ``context``
            fields.
        """
        try:
            # Get DUT config to check baseboard type
            dut_config = self.dut_manager.get_dut_config(dut_id)
            target_baseboard = dut_config.get("TargetBaseboard", "")

            entity_policy = discovery_entity_policy(entity_type)
            if entity_policy is None:
                return {
                    "success": False,
                    "reason": f"Unsupported entity type: {entity_type}",
                    "context": {"filtered_entities": []},
                }
            discovery_method = getattr(self, entity_policy.facade_getter)
            discovered_entities = await discovery_method(dut_id)

            if not discovered_entities:
                return {
                    "success": False,
                    "reason": f"No {entity_type} found",
                    "context": {"filtered_entities": []},
                }

            # Get configured URI for the entity type
            entity_uri = self.get_configured_uri(dut_id, entity_policy.uri_key)
            filtered_entities = []

            # Preserve the legacy chassis default while centralizing the two
            # configurable Systems/Managers prefix names in entity policy.
            hgx_prefix = (
                "HGX"
                if entity_type == "Chassis"
                else dut_config.get(entity_policy.prefix_key, "HGX")
            )

            for entity_id in discovered_entities:
                entity_uri_full = f"{entity_uri}/{entity_id}"
                success, entity_data, _ = await self.dispatch_request(
                    dut_id, "GET", entity_uri_full
                )

                if success:
                    model = entity_data.get("Model", "")
                    is_hgx = hgx_prefix in model

                    # Apply baseboard filtering
                    include_entity = False
                    if baseboard_filter == "HGX" or baseboard_filter == "hgx":
                        include_entity = is_hgx
                    elif baseboard_filter == "non-HGX" or baseboard_filter == "non_hgx":
                        include_entity = not is_hgx
                    elif baseboard_filter == "all" or baseboard_filter is None:
                        include_entity = True
                    else:
                        # Check if baseboard filter matches target baseboard
                        include_entity = (
                            baseboard_filter.lower() in target_baseboard.lower()
                        )

                    if include_entity:
                        filtered_entities.append(
                            {
                                "id": entity_id,
                                "model": model,
                                "name": entity_data.get("Name", ""),
                                "discovery_source": "baseboard_filter",
                                "is_hgx": is_hgx,
                                "target_baseboard": target_baseboard,
                            }
                        )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Filtered {entity_type} by baseboard '{baseboard_filter}': {len(filtered_entities)} entities found",
                dut_id,
            )

            return {
                "success": True,
                "context": {
                    "filtered_entities": filtered_entities,
                    "entity_count": len(filtered_entities),
                    "entity_type": entity_type,
                    "baseboard_filter": baseboard_filter,
                    "target_baseboard": target_baseboard,
                },
            }

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Error in _validate_by_baseboard: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "reason": f"Validation error: {str(e)}",
                "context": {"filtered_entities": []},
            }

    async def _validate_entities_dynamic(
        self,
        dut_id: str,
        entity_type: str = "Chassis",
        filter_criteria: Dict[str, Any] = None,
        output_variable: str = None,
        baseboard_patterns: Dict[str, List[str]] = None,
        baseboard_aware: bool = False,
        baseboard_filtering: Dict[str, str] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Generic validation method for all entity types with dynamic filtering.

        The implementation uses ``dut_id``, ``entity_type``,
        ``filter_criteria``, ``output_variable``, and ``baseboard_patterns`` to
        generic validation method for all entity types with dynamic filtering.
        Owned asynchronous work is awaited before return, so completion does not
        leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            filter_criteria: Optional filter criteria; ``None`` selects the
                function's default behavior.
            output_variable: Optional output variable; ``None`` selects the
                function's default behavior.
            baseboard_patterns: Optional baseboard patterns; ``None`` selects
                the function's default behavior.
            baseboard_aware: Whether baseboard aware is enabled or required for
                this operation.
            baseboard_filtering: Optional baseboard filtering; ``None`` selects
                the function's default behavior.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``reason``, and ``context``
            fields.
        """
        try:
            entity_policy = discovery_entity_policy(entity_type)
            if entity_policy is None:
                return {
                    "success": False,
                    "reason": f"Unsupported entity type: {entity_type}",
                    "context": {output_variable: []},
                }

            uri_base = self.get_configured_uri(dut_id, entity_policy.uri_key)
            discovery_method = getattr(self, entity_policy.facade_getter)

            # Get all discovered entities
            discovered_entities = await discovery_method(dut_id)

            if not discovered_entities:
                return {
                    "success": False,
                    "reason": f"No {entity_type} found",
                    "context": {output_variable: []},
                }

            # Some platforms expose the same child collection on many chassis.
            # Allow a collector to narrow the candidates for one specific
            # baseboard while preserving the existing all-chassis behavior for
            # every baseboard without an explicit mapping. The normal
            # filter_criteria checks still run for every retained candidate.
            active_baseboard_patterns: List[str] = []
            if baseboard_patterns:
                dut_config = self.dut_manager.get_dut_config(dut_id)
                target_baseboard = dut_config.get("baseboard") or dut_config.get(
                    "TargetBaseboard", ""
                )
                active_baseboard_patterns = configured_baseboard_patterns(
                    baseboard_patterns,
                    target_baseboard,
                )

                if active_baseboard_patterns:
                    entities_before_prefilter = list(discovered_entities)
                    discovered_entities = [
                        entity_id
                        for entity_id in discovered_entities
                        if self._matches_pattern(entity_id, active_baseboard_patterns)
                    ]
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Baseboard ID prefilter for {target_baseboard}: "
                        f"{len(discovered_entities)}/{len(entities_before_prefilter)} "
                        f"{entity_type.lower()} matched {active_baseboard_patterns}",
                        dut_id,
                    )

            filtered_uris = []
            validation_failures = []
            filter_criteria = filter_criteria or {}

            id_policy = DynamicIdPolicy.from_filter_criteria(filter_criteria)

            # Get DUT baseboard for filtering if baseboard_aware is enabled
            dut_baseboard = None
            effective_filter_mode = "hgx_only"  # Default
            if baseboard_aware and baseboard_filtering:
                dut_config = self.dut_manager.get_dut_config(dut_id)
                dut_baseboard = dut_config.get("baseboard", "")
                effective_filter_mode = resolve_baseboard_filter_mode(
                    dut_baseboard,
                    baseboard_filtering,
                )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Baseboard filtering enabled for {entity_type}: baseboard={dut_baseboard}, filter_mode={effective_filter_mode}",
                    dut_id,
                )

            # Discovery results are authoritative.  A catalog may declare exact
            # fallback IDs for firmware that omits known resources from its
            # collection, but generic runtime code must not guess a topology or
            # impose a hidden device-count ceiling.
            if id_policy.patterns:
                matching_discovered = [
                    entity_id
                    for entity_id in discovered_entities
                    if id_policy.matches(entity_id)
                ]
                fallback_entity_ids = id_policy.fallback_entity_ids(filter_criteria)

                if not matching_discovered and fallback_entity_ids:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"No {entity_type.lower()} matching patterns "
                        f"{id_policy.raw_patterns} found in discovery; probing "
                        "catalog-declared fallback_entity_ids",
                        dut_id,
                    )

                    # Probe only exact candidates supplied by the catalog.
                    enumerated_entities = []
                    seen_attempts = set()
                    for potential_id in fallback_entity_ids:
                        if potential_id in seen_attempts:
                            continue
                        seen_attempts.add(potential_id)
                        entity_uri = f"{uri_base}/{potential_id}"
                        success, _, _ = await self.dispatch_request(
                            dut_id, "GET", entity_uri
                        )
                        if success:
                            enumerated_entities.append(potential_id)
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Enumerated {entity_type.lower()}: {potential_id}",
                                dut_id,
                            )

                    if enumerated_entities:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {len(enumerated_entities)} {entity_type.lower()} via enumeration: {enumerated_entities}",
                            dut_id,
                        )
                        discovered_entities = (
                            list(discovered_entities) + enumerated_entities
                        )

            for entity_id in discovered_entities:
                # Apply baseboard filtering first if enabled
                if baseboard_aware and baseboard_filtering:
                    is_hgx = entity_id.upper().startswith("HGX_")
                    if skip_entity_for_baseboard_filter(
                        entity_id,
                        effective_filter_mode,
                    ):
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Skipping {entity_type.lower()} {entity_id} due to baseboard filter (mode={effective_filter_mode}, is_hgx={is_hgx})",
                            dut_id,
                        )
                        continue

                entity_uri = f"{uri_base}/{entity_id}"

                id_pattern_matches = bool(
                    id_policy.patterns and id_policy.matches(entity_id)
                )
                requires_entity_data = any(
                    key in filter_criteria
                    for key in id_policy.requires_entity_data_keys
                )
                success, entity_data, metadata = await self.dispatch_request(
                    dut_id, "GET", entity_uri
                )

                if not success:
                    if (
                        id_policy.patterns
                        and not requires_entity_data
                        and id_pattern_matches
                    ):
                        target_uri = entity_uri
                        if "target_uri" in filter_criteria:
                            target_uri = filter_criteria["target_uri"].format(
                                **{entity_policy.id_placeholder: entity_id}
                            )
                        filtered_uris.append(target_uri)
                        failure_detail = (
                            entity_data
                            if entity_data not in (None, "")
                            else "request failed without response details"
                        )
                        await self._log_runtime(
                            "WARNING",
                            "RedfishService",
                            f"Detail GET failed for matching {entity_type.lower()} {entity_uri}; "
                            f"preserving target for execution accounting: {failure_detail}",
                            dut_id,
                        )
                    elif not id_policy.patterns or id_pattern_matches:
                        status = self._http_status_from_response(entity_data, metadata)
                        validation_failures.append(
                            f"Failed to validate {entity_uri}: HTTP {status or 'unknown'}"
                        )
                    continue

                include_entity = False

                # Check ID pattern first (if specified). When check_path is also
                # configured, both criteria must match before the entity is
                # included.
                if id_pattern_matches and "check_path" not in filter_criteria:
                    if "target_uri" in filter_criteria:
                        target_uri = filter_criteria["target_uri"].format(
                            **{entity_policy.id_placeholder: entity_id}
                        )
                        filtered_uris.append(target_uri)
                    else:
                        filtered_uris.append(entity_uri)
                    include_entity = True
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Found {entity_type.lower()} matching ID pattern(s) {id_policy.raw_patterns}: {entity_id}",
                        dut_id,
                    )
                    continue

                if (
                    id_policy.patterns
                    and "check_path" in filter_criteria
                    and not id_pattern_matches
                ):
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"{entity_type} {entity_id} does not match ID pattern(s) {id_policy.raw_patterns}, skipping",
                        dut_id,
                    )
                    continue

                # Check for specific path in entity data
                if "check_path" in filter_criteria:
                    check_path = filter_criteria["check_path"]
                    if check_path in entity_data:
                        # Use custom target URI if specified, otherwise use default entity URI
                        if "target_uri" in filter_criteria:
                            target_uri = filter_criteria["target_uri"].format(
                                **{entity_policy.id_placeholder: entity_id}
                            )
                            filtered_uris.append(target_uri)
                        else:
                            filtered_uris.append(entity_uri)
                        include_entity = True
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {entity_type.lower()} with {check_path}: {entity_id}",
                            dut_id,
                        )
                    else:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"{entity_type} {entity_id} does not have {check_path}, skipping",
                            dut_id,
                        )

                # Check OEM data for keywords
                elif "oem_keywords" in filter_criteria:
                    oem_keywords = filter_criteria["oem_keywords"]
                    oem_path = filter_criteria.get("oem_path", [])

                    # Navigate to OEM data
                    oem_data = entity_data.get("Oem", {})
                    for path_part in oem_path:
                        oem_data = oem_data.get(path_part, {})

                    # Check for keywords in OEM data
                    oem_data_str = str(oem_data).lower()
                    if any(keyword.lower() in oem_data_str for keyword in oem_keywords):
                        filtered_uris.append(entity_uri)
                        include_entity = True
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {entity_type.lower()} with OEM keywords {oem_keywords}: {entity_id}",
                            dut_id,
                        )
                    else:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"{entity_type} {entity_id} does not contain OEM keywords {oem_keywords}, skipping",
                            dut_id,
                        )

                # Check model keywords
                elif "model_keywords" in filter_criteria:
                    model_keywords = filter_criteria["model_keywords"]
                    model = entity_data.get("Model", "").lower()
                    if any(keyword.lower() in model for keyword in model_keywords):
                        filtered_uris.append(entity_uri)
                        include_entity = True
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {entity_type.lower()} with model keywords {model_keywords}: {entity_id}",
                            dut_id,
                        )
                    else:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"{entity_type} {entity_id} model '{model}' does not match keywords {model_keywords}, skipping",
                            dut_id,
                        )

                # Check name keywords
                elif "name_keywords" in filter_criteria:
                    name_keywords = filter_criteria["name_keywords"]
                    name = entity_data.get("Name", "").lower()
                    if any(keyword.lower() in name for keyword in name_keywords):
                        filtered_uris.append(entity_uri)
                        include_entity = True
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {entity_type.lower()} with name keywords {name_keywords}: {entity_id}",
                            dut_id,
                        )
                    else:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"{entity_type} {entity_id} name '{name}' does not match keywords {name_keywords}, skipping",
                            dut_id,
                        )

                elif not filter_criteria:
                    # No filters provided at all, include all entities
                    filtered_uris.append(entity_uri)
                    include_entity = True
                else:
                    # Filters were provided but none matched; skip this entity
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"{entity_type} {entity_id} did not match filter criteria {filter_criteria}, skipping",
                        dut_id,
                    )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Found {len(filtered_uris)} {entity_type.lower()} with filter criteria: {filter_criteria}",
                dut_id,
            )

            return await self._entity_validation_result(
                {
                    output_variable: filtered_uris,
                    f"{entity_type.lower()}_count": len(filtered_uris),
                    "filter_criteria": filter_criteria,
                },
                len(filtered_uris),
                validation_failures,
            )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Error in _validate_entities_dynamic: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "reason": f"Validation error: {str(e)}",
                "context": {output_variable: []},
            }

    async def _derive_uri_suffixes(
        self,
        dut_id: str,
        source_list: Union[str, List[str]] = None,
        output_variable: str = None,
        suffix: str = "",
        strip_trailing_slash: bool = True,
        ensure_unique: bool = True,
        include_uri_patterns: List[str] = None,
        exclude_uri_patterns: List[str] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Derive a new list of URIs by appending a suffix to each source URI.

        The implementation uses ``dut_id``, ``source_list``,
        ``output_variable``, ``suffix``, and ``strip_trailing_slash`` to derive
        a new list of URIs by appending a suffix to each source URI. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            source_list: Optional source list; ``None`` selects the function's
                default behavior.
            output_variable: Optional output variable; ``None`` selects the
                function's default behavior.
            suffix: Text supplied as suffix in the format accepted by this
                function.
            strip_trailing_slash: Whether strip trailing slash is enabled or
                required for this operation.
            ensure_unique: Whether ensure unique is enabled or required for this
                operation.
            include_uri_patterns: Validated remote resource identifier used for
                include URI patterns.
            exclude_uri_patterns: Validated remote resource identifier used for
                exclude URI patterns.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``reason``, and ``context``
            fields.
        """

        def _resolve_source_uris(
            source: Union[str, List[str], None], context: Dict[str, Any]
        ) -> List[str]:
            """
            Resolve source URIs.

            The implementation uses ``source`` and ``context`` to resolve source
            URIs.

            Args:
                source: Optional source; ``None`` selects the function's default
                    behavior.
                context: Runtime context carrying state shared across this
                    operation.

            Returns:
                The source URIs returned in operation-defined order.
            """
            if isinstance(source, list):
                return source

            if isinstance(source, str):
                var_name = source
                if source.startswith("${") and source.endswith("}"):
                    var_name = source[2:-1]
                return context.get(var_name, []) or []

            return context.get("source_list", []) or []

        try:
            if not output_variable:
                return {
                    "success": False,
                    "reason": "output_variable must be provided for _derive_uri_suffixes",
                    "context": {},
                }

            source_uris = _resolve_source_uris(source_list, kwargs)

            derived_uris: List[str] = []
            skipped_uri_count = 0
            if source_uris:
                for uri in source_uris:
                    if not isinstance(uri, str):
                        continue

                    if include_uri_patterns and not any(
                        re.search(pattern, uri, re.IGNORECASE)
                        for pattern in include_uri_patterns
                    ):
                        skipped_uri_count += 1
                        continue

                    if exclude_uri_patterns and any(
                        re.search(pattern, uri, re.IGNORECASE)
                        for pattern in exclude_uri_patterns
                    ):
                        skipped_uri_count += 1
                        continue

                    normalized_uri = uri.rstrip("/") if strip_trailing_slash else uri

                    if suffix:
                        if suffix.startswith("/"):
                            derived_uri = f"{normalized_uri}{suffix}"
                        else:
                            derived_uri = f"{normalized_uri}/{suffix}"
                    else:
                        derived_uri = normalized_uri

                    derived_uris.append(derived_uri)

            if ensure_unique:
                seen = set()
                unique_derived = []
                for uri in derived_uris:
                    if uri not in seen:
                        seen.add(uri)
                        unique_derived.append(uri)
                derived_uris = unique_derived

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Derived {len(derived_uris)} URIs (suffix='{suffix}') from {len(source_uris)} source URIs; skipped {skipped_uri_count}",
                dut_id,
            )

            return {
                "success": True,
                "context": {
                    output_variable: derived_uris,
                    "source_uri_count": len(source_uris),
                    "derived_uri_count": len(derived_uris),
                    "skipped_uri_count": skipped_uri_count,
                    "suffix": suffix,
                },
            }

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Error in _derive_uri_suffixes: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "reason": f"URI derivation error: {str(e)}",
                "context": {output_variable if output_variable else "derived_uris": []},
            }

    async def _validate_chassis_dynamic(self, dut_id: str, **kwargs) -> Dict[str, Any]:
        """
        Backward compatibility wrapper for chassis dynamic validation.

        After applying local validation, the function forwards ``dut_id`` and
        ``kwargs`` to ``self._validate_entities_dynamic`` and preserves its
        return and exception contract. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing chassis dynamic.
        """
        return await self._validate_entities_dynamic(
            dut_id, entity_type="Chassis", **kwargs
        )

