    async def _discover_dot_trusted_component_uris(
        self,
        dut_id: str,
        output_variable: str = "dot_trusted_component_uris",
        chassis_id_pattern: Union[str, List[str]] = r"^HGX_CPU_[0-9]+$",
        target_uri: str = "/redfish/v1/Chassis/{chassis_id}/TrustedComponents",
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Discover CPU DOT TrustedComponents collection URIs.

        R56 must not rely on the parent Chassis resource being readable: some
        systems can return 5xx for /Chassis/HGX_CPU_x while the child
        /TrustedComponents collection is available.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            output_variable: Text supplied as output variable in the format
                accepted by this function.
            chassis_id_pattern: Entries supplied as ``chassis_id_pattern``
                without transferring container ownership.
            target_uri: Validated remote resource identifier used for target
                URI.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``reason``, and ``context``
            fields.
        """
        try:
            chassis_base_uri = self.get_configured_uri(dut_id, "Chassis")
            discovered_chassis = await self.get_discovered_chassis(dut_id)
            discovered_chassis = discovered_chassis or []

            if isinstance(chassis_id_pattern, (list, tuple, set)):
                raw_patterns = [str(pattern) for pattern in chassis_id_pattern]
            else:
                raw_patterns = [str(chassis_id_pattern)]

            compiled_patterns = [re.compile(pattern) for pattern in raw_patterns]

            def _matches_chassis_pattern(chassis_id: str) -> bool:
                """
                Return whether ``chassis_id`` matches chassis pattern.

                After applying local validation, the function forwards
                ``chassis_id`` to ``any`` and preserves its return and exception
                contract.

                Args:
                    chassis_id: Stable chassis identifier used to correlate
                        configuration, logs, and results.

                Returns:
                    Whether ``chassis_id`` matches chassis pattern.
                """
                return any(pattern.search(chassis_id) for pattern in compiled_patterns)

            candidate_chassis: List[str] = []
            skipped_chassis: List[str] = []
            discovery_truncation_messages: List[str] = []

            def _add_candidate(chassis_id: str) -> None:
                """
                Add candidate.

                The implementation uses ``chassis_id`` to add candidate.

                Args:
                    chassis_id: Stable chassis identifier used to correlate
                        configuration, logs, and results.
                """
                if not chassis_id:
                    return
                if _matches_chassis_pattern(chassis_id):
                    if chassis_id not in candidate_chassis:
                        candidate_chassis.append(chassis_id)
                elif chassis_id not in skipped_chassis:
                    skipped_chassis.append(chassis_id)

            for chassis_id in discovered_chassis:
                _add_candidate(str(chassis_id))

            (
                chassis_collection_success,
                chassis_collection_data,
                _,
            ) = await self.dispatch_request(
                dut_id,
                "GET",
                chassis_base_uri,
                error_context="discover DOT chassis candidates",
            )

            if chassis_collection_success and isinstance(chassis_collection_data, dict):
                raw_members = chassis_collection_data.get("Members", [])
                try:
                    members, source_count, truncated = bound_redfish_collection_members(
                        raw_members,
                        field_name="DOT Chassis collection Members",
                        limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                    )
                except ValueError:
                    members = []
                    discovery_truncation_messages.append(
                        "DOT Chassis collection returned an invalid Members list"
                    )
                else:
                    if truncated:
                        discovery_truncation_messages.append(
                            "DOT Chassis collection advertised "
                            f"{source_count} members; processing the first "
                            f"{self.MAX_FOLLOWED_COLLECTION_MEMBERS} within the "
                            "safe request-amplification limit"
                        )
                for member in members:
                    if not isinstance(member, dict):
                        continue
                    member_uri = member.get("@odata.id", "")
                    chassis_id = member_uri.rstrip("/").split("/")[-1]
                    _add_candidate(chassis_id)
            elif not candidate_chassis:
                reason = (
                    f"Failed to fetch Chassis collection for DOT discovery and no "
                    f"discovered chassis candidates were available: {chassis_collection_data}"
                )
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    reason,
                    dut_id,
                )
                return {
                    "success": False,
                    "reason": reason,
                    "context": {output_variable: []},
                }
            else:
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    (
                        "Failed to fetch Chassis collection during DOT discovery; "
                        f"falling back to discovered chassis list: {chassis_collection_data}"
                    ),
                    dut_id,
                )

            bounded_candidates, candidate_count, candidates_truncated = (
                bound_redfish_collection_members(
                    candidate_chassis,
                    field_name="DOT candidate chassis",
                    limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                )
            )
            candidate_chassis = [str(candidate) for candidate in bounded_candidates]
            if candidates_truncated:
                discovery_truncation_messages.append(
                    f"DOT discovery produced {candidate_count} candidate chassis; "
                    f"processing the first {self.MAX_FOLLOWED_COLLECTION_MEMBERS} "
                    "within the safe request-amplification limit"
                )

            for truncation_message in discovery_truncation_messages:
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    truncation_message,
                    dut_id,
                )
                await self._log_collection_failure(
                    dut_id,
                    "dot_discovery",
                    chassis_base_uri,
                    truncation_message,
                )

            trusted_component_uris: List[str] = []
            unavailable_targets: List[str] = []
            validation_failures: List[str] = []

            for chassis_id in candidate_chassis:
                trusted_components_uri = target_uri.format(chassis_id=chassis_id)
                success, trusted_components_data, metadata = (
                    await self.dispatch_request(
                        dut_id,
                        "GET",
                        trusted_components_uri,
                        error_context=(
                            f"discover DOT TrustedComponents for chassis {chassis_id}"
                        ),
                    )
                )

                if success and isinstance(trusted_components_data, dict):
                    trusted_component_uris.append(trusted_components_uri)
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        (
                            "Discovered DOT TrustedComponents collection for "
                            f"{chassis_id}: {trusted_components_uri}"
                        ),
                        dut_id,
                    )
                    continue

                unavailable_targets.append(trusted_components_uri)
                status = self._http_status_from_response(
                    trusted_components_data, metadata
                )
                if status != 404:
                    validation_failures.append(
                        f"Failed to validate {trusted_components_uri}: HTTP {status or 'unknown'}"
                    )
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    (
                        "Skipping DOT TrustedComponents collection for "
                        f"{chassis_id}: {trusted_components_data}"
                    ),
                    dut_id,
                )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                (
                    f"Discovered {len(trusted_component_uris)} DOT TrustedComponents "
                    f"collections from {len(candidate_chassis)} candidate chassis"
                ),
                dut_id,
            )

            result = await self._entity_validation_result(
                {
                    output_variable: trusted_component_uris,
                    "dot_trusted_component_uri_count": len(trusted_component_uris),
                    "dot_candidate_chassis": candidate_chassis,
                    "dot_unavailable_targets": unavailable_targets,
                    "dot_skipped_chassis": skipped_chassis,
                    "dot_chassis_id_patterns": raw_patterns,
                    "dot_discovery_truncation_messages": (
                        discovery_truncation_messages
                    ),
                },
                len(trusted_component_uris),
                validation_failures,
            )
            if discovery_truncation_messages and not validation_failures:
                result.update(
                    {
                        "status": "partial",
                        "reason": "; ".join(discovery_truncation_messages),
                    }
                )
            return result

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Error in _discover_dot_trusted_component_uris: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "reason": f"DOT TrustedComponents discovery error: {str(e)}",
                "context": {output_variable: []},
            }

    """
    Discovery
    """

    async def get_discovered_systems(self, dut_id: str) -> List[str]:
        """
        Get discovered system IDs from dynamic discovery.

        The implementation uses ``dut_id`` to get discovered system IDs from
        dynamic discovery. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            The discovered systems returned in operation-defined order.
        """
        if not self.dut_manager:
            return []

        discovery = RedfishDiscoveryAdapter(lambda: self.dut_manager)
        systems = await discovery.get_resource_members(dut_id, "Systems")

        # Log what systems were found
        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"get_discovered_systems for {dut_id}: found {len(systems)} systems: {systems}",
            dut_id,
        )

        return systems

