    async def _execute_with_error_handling(
        self, dut_id: str, operation_name: str, operation_func, *args, **kwargs
    ) -> Dict[str, Any]:
        """
        Common error handling wrapper (DRY pattern).

        The implementation uses ``dut_id``, ``operation_name``,
        ``operation_func``, ``args``, and ``kwargs`` to common error handling
        wrapper (DRY pattern). Owned asynchronous work is awaited before return,
        so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            operation_name: Stable operation name used for lookup and
                operator-facing diagnostics.
            operation_func: Operation func consumed while the function attempts
                to common error handling wrapper (DRY pattern).
            args: Additional positional values forwarded in caller-provided
                order.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing execute with error handling.
        """
        try:
            await self._log_runtime(
                "INFO", "RedfishService", f"Starting {operation_name}", dut_id
            )

            result = await operation_func(*args, **kwargs)

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Completed {operation_name} successfully",
                dut_id,
            )

            return result
        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Failed {operation_name}: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[str(e)],
                operation_name=operation_name,
                additional_context={"operation_name": operation_name},
            )

    def _is_404_error(self, response: Any) -> bool:
        """
        Classify legacy absence responses without normalizing a full body.

        The implementation uses ``response`` to classify legacy absence
        responses without normalizing a full body. Remote I/O uses the
        configured transport policy and returns only after its response or
        failure has been observed.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.

        Returns:
            Whether the classify legacy absence responses without normalizing a
            full body operation succeeds.
        """

        http_status = self._http_status_from_response(response)
        if http_status is not None:
            if 500 <= http_status <= 599:
                return False
            if http_status == 404:
                return True

        markers = (
            "resourcenotfound",
            "resourcemissingaturi",
            "resourceaturiunauthorized",
            "not found",
            "missing",
            "unauthorized",
        )
        if type(response) is dict:
            if dict.__len__(response) == 0:
                return True
            error_info = dict.get(response, "error")
            if type(error_info) is not dict:
                return False
            error_code = dict.get(error_info, "code")
            if type(error_code) is str:
                code_preview = error_code[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS].casefold()
                if "404" in code_preview or any(
                    marker in code_preview for marker in markers[:3]
                ):
                    return True
            error_message = dict.get(error_info, "message")
            if type(error_message) is str:
                message_preview = error_message[
                    :_DIAGNOSTIC_LOG_TEXT_MAX_CHARS
                ].casefold()
                return any(marker in message_preview for marker in markers)
            return False
        if type(response) is str:
            response_preview = response[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS].casefold()
            return any(marker in response_preview for marker in markers)
        return False

    @staticmethod
    def _http_status_from_response(
        response: Any, metadata: Any = None
    ) -> Optional[int]:
        """
        Extract an HTTP status without serializing an arbitrary response.

        The implementation uses ``response`` and ``metadata`` to extract an HTTP
        status without serializing an arbitrary response. Remote I/O uses the
        configured transport policy and returns only after its response or
        failure has been observed.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional metadata; ``None`` selects the function's default
                behavior.

        Returns:
            The numeric HTTP status from response value, or ``None`` when the
            requested value is unavailable.
        """

        def bounded_status(value: Any) -> Optional[int]:
            """
            Return the bounded status.

            The implementation uses ``value`` to produce the bounded status.

            Args:
                value: Value object whose ``strip`` state is read while
                    performing bounded status.

            Returns:
                The numeric bounded status value, or ``None`` when the requested
                value is unavailable.
            """
            if type(value) is int:
                return value if 100 <= value <= 599 else None
            if type(value) is str and len(value) <= 8:
                stripped = value.strip()
                if stripped.isascii() and stripped.isdecimal():
                    parsed = int(stripped)
                    return parsed if 100 <= parsed <= 599 else None
            return None

        direct_status = bounded_status(metadata)
        if direct_status is not None:
            return direct_status
        if type(metadata) in {dict, _RequestTimingMetadata}:
            for key in ("http_status", "status_code", "status"):
                status = bounded_status(dict.get(metadata, key))
                if status is not None:
                    return status

        if type(response) is dict:
            for key in (
                "http_status",
                "HTTPStatus",
                "status_code",
                "StatusCode",
            ):
                status = bounded_status(dict.get(response, key))
                if status is not None:
                    return status

        if type(response) is not str:
            return None
        match = re.search(
            r"\bHTTP(?:/\d(?:\.\d)?)?\s*[: ]\s*(\d{3})\b",
            response[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS],
            re.I,
        )
        if match is None:
            return None
        status = int(match.group(1))
        return status if 100 <= status <= 599 else None

    @classmethod
    def _redfish_get_failure_is_retryable(
        cls, response: Any, metadata: Any = None
    ) -> bool:
        """
        Return whether a failed Redfish GET may succeed when attempted again.

        Explicit client errors are terminal except for the standard transient
        timeout, too-early, and rate-limit statuses. Server errors and failures
        without an authoritative status remain retryable because the transport
        may have failed before a response was received. A bounded Redfish
        resource-absence body is terminal even when transport metadata omitted
        the numeric status.

        Args:
            response: Failed Redfish response body or transport diagnostic.
            metadata: Optional response metadata containing the HTTP status.

        Returns:
            Whether the failed GET is eligible for another attempt.
        """
        status = cls._http_status_from_response(response, metadata)
        if status is not None:
            return status in {408, 425, 429} or 500 <= status <= 599
        return not cls._is_redfish_resource_absent(response, metadata)

    @classmethod
    def _is_redfish_resource_absent(cls, response: Any, metadata: Any = None) -> bool:
        """
        Return true only for an explicit 404/ResourceNotFound response.

        The implementation uses ``response`` and ``metadata`` to produce true
        only for an explicit 404/ResourceNotFound response.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional metadata; ``None`` selects the function's default
                behavior.

        Returns:
            Whether the true only for an explicit 404/ResourceNotFound response
            operation succeeds.
        """
        status = cls._http_status_from_response(response, metadata)
        if status is not None:
            return status == 404

        markers = (
            "resourcenotfound",
            "resourcemissingaturi",
            "resource not found",
        )
        traversable_names = {
            "error",
            "code",
            "message",
            "messageid",
            "messages",
            "extendedinfo",
            "@message.extendedinfo",
            "oem",
        }

        def contains_marker(value: Any, depth: int) -> bool:
            """
            Return the contains marker.

            The implementation uses ``value`` and ``depth`` to produce the
            contains marker. Filesystem effects remain confined to the
            caller-selected paths and the owning resource lifecycle.

            Args:
                value: Value object whose ``casefold`` state is read while
                    performing contains marker.
                depth: Numeric depth used while the operation performs bounded
                    accounting.

            Returns:
                Whether the contains marker operation succeeds.
            """
            value_type = type(value)
            if value_type is str:
                preview = value[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS].casefold()
                return any(marker in preview for marker in markers)
            if depth <= 0:
                return False
            if value_type is dict:
                for index, (name, item) in enumerate(dict.items(value)):
                    if index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                        break
                    if (
                        type(name) is not str
                        or len(name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS
                    ):
                        continue
                    normalized_name = name.casefold().replace("_", "")
                    if normalized_name in traversable_names and contains_marker(
                        item, depth - 1
                    ):
                        return True
                return False
            if value_type in {list, tuple}:
                iterator = (
                    list.__iter__(value)
                    if value_type is list
                    else tuple.__iter__(value)
                )
                for index, item in enumerate(iterator):
                    if index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                        break
                    if contains_marker(item, depth - 1):
                        return True
            return False

        return contains_marker(response, 3)

    def _matches_filter(
        self, data: Dict[str, Any], filter_criteria: Dict[str, Any]
    ) -> bool:
        """
        Check if data matches filter criteria.

        The implementation uses ``data`` and ``filter_criteria`` to check if
        data matches filter criteria. Every required invariant is checked before
        a successful value is returned; invalid input follows the function's
        explicit exception path.

        Args:
            data: Mapping supplying fields for if data matches filter criteria.
            filter_criteria: Mapping supplying fields for if data matches filter
                criteria.

        Returns:
            Whether the if data matches filter criteria operation succeeds.
        """
        for key, expected_value in filter_criteria.items():
            if key not in data:
                return False
            if data[key] != expected_value:
                return False
        return True

    def _find_pattern_matches(self, data: Dict[str, Any], pattern: str) -> List[str]:
        """
        Find pattern matches in data.

        The implementation uses ``data`` and ``pattern`` to find pattern matches
        in data.

        Args:
            data: Mapping supplying fields for find pattern matches in data.
            pattern: Text supplied as pattern in the format accepted by this
                function.

        Returns:
            The validated ``matches``.
        """
        matches = []

        def search_recursive(obj, path=""):
            """
            Search nested response data for matching scalar values.

            The implementation uses ``obj`` and ``path`` to search nested
            response data for matching scalar values.

            Args:
                obj: Object whose ``items`` state is read while
                    performing search nested response data for matching scalar
                    values.
                path: filesystem location used as the path for this operation.
            """
            if isinstance(obj, dict):
                for key, value in obj.items():
                    current_path = f"{path}.{key}" if path else key
                    search_recursive(value, current_path)
            elif isinstance(obj, list):
                for i, item in enumerate(obj):
                    current_path = f"{path}[{i}]"
                    search_recursive(item, current_path)
            elif isinstance(obj, str):
                if re.search(pattern, obj, re.IGNORECASE):
                    matches.append(f"{path}: {obj}")

        search_recursive(data)
        return matches

    async def _get_platform_info(self, dut_id: str) -> Dict[str, Any]:
        """
        Get platform information.

        The implementation uses ``dut_id`` to get platform information. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            A mapping containing the ``platform_type`` fields.
        """
        try:
            # First check DUT config for baseboard type
            dut = self.dut_manager.get_dut(dut_id)
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Platform detection: DUT object type: {type(dut)}",
                dut_id,
            )

            if dut and hasattr(dut, "config"):
                baseboard = dut.config.get("baseboard", "")
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Platform detection: found baseboard '{baseboard}' in DUT config",
                    dut_id,
                )

                if baseboard:
                    # Return the canonical configured baseboard.  Consumers such as
                    # log processing own their routing policy in catalog metadata;
                    # platform names must not be classified here in runtime code.
                    return {"platform_type": baseboard}
            else:
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    "Platform detection: DUT config not accessible",
                    dut_id,
                )

            # Fallback: Get root to determine platform
            success, root_data, _ = await self.dispatch_request(dut_id, "GET", "")

            if success:
                # Try to determine platform from root data
                if "Oem" in root_data:
                    return {"platform_type": "OEM"}
                elif "Systems" in root_data:
                    return {"platform_type": "Standard"}
                else:
                    return {"platform_type": "Unknown"}
            else:
                return {"platform_type": "Unknown"}
        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Failed to get platform info: {e}",
                dut_id,
            )
            return {"platform_type": "Unknown"}

    """
    Task Management
    """

    @staticmethod
    def _canonical_archive_receipt_is_well_formed(record: Any) -> bool:
        """
        Return whether a persisted receipt is safe to retain and extend.

        After applying local validation, the function forwards ``record`` to
        ``canonical_receipt_is_well_formed`` and preserves its return and
        exception contract.

        Args:
            record: Record evaluated while performing persisted receipt is safe
                to retain and extend.

        Returns:
            Whether a persisted receipt is safe to retain and extend.
        """

        return canonical_receipt_is_well_formed(record)

    @staticmethod
    def _atomic_write_diagnostic_bytes(path: Path, data: bytes) -> None:
        """
        Replace one diagnostic file durably without exposing partial JSON.

        The implementation uses ``path`` and ``data`` to replace one diagnostic
        file durably without exposing partial JSON.

        Args:
            path: filesystem location used as the path for this operation.
            data: Bounded byte sequence supplied as data.
        """

        atomic_write_bytes(path, data)

    def _write_bounded_diagnostic_history(
        self,
        file_path: Path,
        safe_data: Dict[str, Any],
        file_type: str,
    ) -> None:
        """
        Validate, sanitize, and publish one bounded diagnostic history update.

        The async owner holds the destination lock until this worker finishes.
        Every retained record is revalidated under the current redaction policy;
        no parsed history or payload is cached between calls. The established
        record and byte limits, malformed-history recovery, and atomic writer
        remain authoritative.

        Args:
            file_path: Destination selected by the collector artifact owner.
            safe_data: Already bounded new record to append after retained history.
            file_type: Diagnostic format whose evidence fields require restoration.

        Raises:
            OSError: If the final atomic publication cannot complete.
            ValueError: If the publication destination violates its file contract.

        Side Effects:
            Replaces the diagnostic JSON array after bounded preparation.
        """

        # Load existing data or create a new array while holding the
        # complete read-modify-write lock.
        existing_data: List[Dict[str, Any]] = []
        if file_path.exists() or file_path.is_symlink():
            try:
                file_stat = file_path.lstat()
                if not stat.S_ISREG(file_stat.st_mode):
                    raise ValueError("diagnostic destination must be a regular file")
                if file_stat.st_size > _DIAGNOSTIC_ARRAY_MAX_BYTES:
                    raise ValueError("diagnostic history exceeds byte limit")
                raw_history = read_diagnostic_bytes(
                    file_path, max_bytes=_DIAGNOSTIC_ARRAY_MAX_BYTES
                )
                loaded_data = json.loads(raw_history.decode("utf-8"))
                if type(loaded_data) is not list:
                    raise ValueError("diagnostic history is not a JSON array")
                retained = loaded_data[-(_DIAGNOSTIC_ARRAY_MAX_RECORDS - 1) :]
                for item in retained:
                    if type(item) is not dict:
                        continue
                    bounded = self._bounded_diagnostic_log_value(
                        item,
                        depth=2,
                    )
                    if type(bounded) is dict:
                        restored = self._restore_canonical_archive_evidence(
                            item,
                            bounded,
                        )
                        restored = self._restore_bounded_diagnostic_structure_evidence(
                            item,
                            restored,
                            file_type,
                        )
                        existing_data.append(
                            self._restore_bounded_task_message_evidence(
                                item,
                                restored,
                                file_type,
                            )
                        )
            except (
                json.JSONDecodeError,
                UnicodeDecodeError,
                OSError,
                TypeError,
                ValueError,
            ):
                existing_data = []

        existing_data.append(safe_data)
        existing_data = existing_data[-_DIAGNOSTIC_ARRAY_MAX_RECORDS:]

        encoding_options = {
            "ensure_ascii": True,
            "separators": (",", ":"),
        }
        encoded = json.dumps(existing_data, **encoding_options)
        while len(encoded) > _DIAGNOSTIC_ARRAY_MAX_BYTES and len(existing_data) > 1:
            existing_data.pop(0)
            encoded = json.dumps(existing_data, **encoding_options)
        if len(encoded) > _DIAGNOSTIC_ARRAY_MAX_BYTES:
            existing_data = [
                {
                    "content": "omitted",
                    "reason": ("diagnostic record exceeded artifact byte limit"),
                }
            ]
            encoded = json.dumps(existing_data, **encoding_options)

        self._atomic_write_diagnostic_bytes(
            file_path,
            encoded.encode("utf-8"),
        )

    async def _append_to_diagnostic_json_array(
        self,
        dut_id: str,
        data: Dict[str, Any],
        function_tag: str,
        file_type: str,  # "diagnostic_responses", "diagnostic_errors", "task_completions"
        collector_id: str,
    ) -> str:
        """
        Append data to a JSON array file, creating the file if it doesn't exist.

        The implementation uses ``dut_id``, ``data``, ``function_tag``,
        ``file_type``, and ``collector_id`` to append data to a JSON array file,
        creating the file if it doesn't exist. History reads, redaction, encoding,
        and publication run in a bounded owned worker. Cancellation waits for
        that worker before releasing the destination lock. It updates
        ``_diagnostic_file_locks`` on the instance as part of
        that state transition. Filesystem effects remain confined to the
        caller-selected paths and the owning resource lifecycle. If the function
        cannot append data to a JSON array file, creating the file if it doesn't
        exist, its exception reaches the caller instead of being converted into
        a successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            data: Mapping supplying fields for append data to a JSON array file,
                creating the file if it doesn't exist.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            file_type: Text supplied as file type in the format accepted by this
                function.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.

        Returns:
            The canonical append to diagnostic JSON array text.

        Raises:
            ValueError: If refusing to persist malformed archive receipt; the
                diagnostic destination is not a regular file; diagnostic history
                exceeds byte limit; or diagnostic history is not a JSON array.
        """
        timing_operation_id = None
        safe_data = self._bounded_diagnostic_log_value(data, depth=2)
        if type(safe_data) is not dict:
            safe_data = {"record": safe_data}
        safe_data = self._restore_canonical_archive_evidence(data, safe_data)
        safe_data = self._restore_bounded_diagnostic_structure_evidence(
            data,
            safe_data,
            file_type,
        )
        safe_data = self._restore_bounded_task_message_evidence(
            data,
            safe_data,
            file_type,
        )
        strict_receipt = file_type == "archive_validation"
        if strict_receipt and not self._canonical_archive_receipt_is_well_formed(
            safe_data
        ):
            raise ValueError("refusing to persist malformed archive receipt")
        try:
            # Generate filename
            filename = f"diagnostic/{file_type}_{function_tag}.json"

            # Use the existing logger infrastructure to get the proper DUT directory
            # This ensures we're in the correct collector folder structure
            # CRITICAL FIX: Use original collector ID for file path determination to prevent cross-contamination
            original_collector_id = await self._get_original_collector_id(
                dut_id, collector_id
            )
            file_collector_id = (
                original_collector_id
                if original_collector_id != "unknown"
                else collector_id
            )

            group = self._get_collector_group(file_collector_id)
            if self.logger:
                file_path = await self.logger.create_collector_log_file(
                    dut_id, group, file_collector_id, filename
                )
            else:
                # Fallback if logger not available
                file_path = Path(filename)

            if self.timing_manager:
                timing_operation_id = self.timing_manager.start_operation(
                    "artifact_persistence",
                    filename,
                    metadata={"artifact_kind": file_type},
                    compact_artifact_on_limit=True,
                )

            file_path = Path(file_path)
            diagnostic_locks = getattr(self, "_diagnostic_file_locks", None)
            if not isinstance(diagnostic_locks, dict):
                diagnostic_locks = {}
                self._diagnostic_file_locks = diagnostic_locks
            diagnostic_lock = diagnostic_locks.setdefault(
                str(file_path.absolute()),
                Lock(),
            )
            async with diagnostic_lock:
                if strict_receipt:
                    await self._run_blocking_redfish_operation(
                        append_canonical_receipt,
                        file_path,
                        safe_data,
                        max_records=_DIAGNOSTIC_ARRAY_MAX_RECORDS,
                        max_bytes=_DIAGNOSTIC_ARRAY_MAX_BYTES,
                    )
                    if self.timing_manager:
                        self.timing_manager.end_operation(
                            timing_operation_id,
                            artifact_path=str(file_path),
                        )
                    return str(file_path)

                await self._run_blocking_redfish_operation(
                    self._write_bounded_diagnostic_history,
                    file_path,
                    safe_data,
                    file_type,
                )

            if self.timing_manager:
                self.timing_manager.end_operation(
                    timing_operation_id,
                    artifact_path=str(file_path),
                )

            return str(file_path)

        except Exception as e:
            if self.timing_manager:
                self.timing_manager.end_operation(
                    timing_operation_id,
                    status="error",
                    error=str(e),
                )
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Failed to append to {file_type} array: {str(e)}",
                dut_id,
            )
            if strict_receipt:
                raise
            # Fallback to individual file using existing infrastructure
            return await self._save_data_to_file_with_pattern(
                dut_id,
                safe_data,
                function_tag,
                output_pattern=f"diagnostic/{file_type}_{function_tag}_fallback.json",
                substitutions={},
                collector_id=collector_id,
            )

    async def _dispatch_task_status_with_deadline(
        self,
        dut_id: str,
        task_uri: str,
        deadline: float,
        poll_interval: float,
    ) -> Tuple[bool, Any, Dict[str, Any], bool]:
        """
        Fetch task status through the diagnostic orchestration boundary.

        After applying local validation, the function forwards ``dut_id``,
        ``task_uri``, ``deadline``, and ``poll_interval`` to
        ``_dispatch_task_status_with_deadline`` and preserves its return and
        exception contract. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            task_uri: Validated remote resource identifier used for task URI.
            deadline: Absolute monotonic deadline after which the operation must
                stop.
            poll_interval: Maximum duration in seconds allowed for poll
                interval.

        Returns:
            A tuple containing the fields that represent dispatch task status
            with deadline.
        """
        return await self._diagnostic_runner()._dispatch_task_status_with_deadline(
            dut_id, task_uri, deadline, poll_interval
        )

    @staticmethod
    async def _sleep_with_task_monitor_deadline(delay: float, deadline: float) -> bool:
        """
        Sleep no longer than the task-monitor budget and report time remaining.

        The implementation uses ``delay`` and ``deadline`` to sleep no longer
        than the task-monitor budget and report time remaining. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            delay: Numeric delay used while the operation performs bounded
                accounting.
            deadline: Absolute monotonic deadline after which the operation must
                stop.

        Returns:
            Whether the sleep no longer than the task-monitor budget and report
            time remaining operation succeeds.
        """
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return False
        await asyncio.sleep(min(max(float(delay), 0.0), remaining))
        return time.monotonic() < deadline

    @staticmethod
    def _response_header_value(metadata: Any, header_name: str) -> Optional[Any]:
        """
        Read a response header from bounded dispatch metadata.

        Some injected/legacy request adapters return headers directly in the
        metadata mapping. Supporting that shape keeps task monitoring compatible
        without exposing any header that dispatch did not retain.

        Args:
            metadata: Metadata consumed while the function attempts to read a
                response header from bounded dispatch metadata.
            header_name: Stable header name used for lookup and operator-facing
                diagnostics.

        Returns:
            The validated ``value``, or ``None`` when no value qualifies.
        """
        if type(metadata) not in {dict, _RequestTimingMetadata}:
            return None

        header_sources = []
        response_headers = dict.get(metadata, "response_headers")
        if type(response_headers) is dict:
            header_sources.append(response_headers)
        # Some injected/legacy request adapters return headers directly in the
        # metadata mapping. Supporting that shape keeps task monitoring
        # compatible without exposing any header that dispatch did not retain.
        header_sources.append(metadata)

        expected = header_name.casefold()
        for headers in header_sources:
            for name, value in dict.items(headers):
                if (
                    type(name) is str
                    and len(name) <= _DIAGNOSTIC_FIELD_NAME_MAX_CHARS
                    and name.casefold() == expected
                ):
                    return value
        return None

    @staticmethod
    def _parse_retry_after_seconds(value: Any) -> Optional[float]:
        """
        Compatibility delegate for bounded Retry-After policy.

        After applying local validation, the function forwards ``value`` to
        ``parse_retry_after_seconds`` and preserves its return and exception
        contract.

        Args:
            value: Value evaluated while performing compatibility delegate for
                bounded Retry-After policy.

        Returns:
            The numeric retry after seconds, or ``None`` when the requested
            value is unavailable.
        """
        return parse_retry_after_seconds(value)

    @classmethod
    def _retry_after_from_metadata(cls, metadata: Any) -> Optional[float]:
        """
        Return a safe Retry-After delta from request metadata, if present.

        After applying local validation, the function forwards ``metadata`` to
        ``cls._parse_retry_after_seconds`` and preserves its return and
        exception contract.

        Args:
            metadata: Metadata consumed while the function attempts to produce a
                safe Retry-After delta from request metadata, if present.

        Returns:
            The numeric retry after from metadata value, or ``None`` when the
            requested value is unavailable.
        """
        return cls._parse_retry_after_seconds(
            cls._response_header_value(metadata, "Retry-After")
        )

    @classmethod
    def _diagnostic_response_headers(cls, metadata: Any) -> Dict[str, Any]:
        """
        Return the async-operation headers needed for diagnostic evidence.

        The implementation uses ``metadata`` to produce the async-operation
        headers needed for diagnostic evidence.

        Args:
            metadata: Metadata consumed while the function attempts to produce
                the async-operation headers needed for diagnostic evidence.

        Returns:
            The validated ``headers``.
        """
        headers: Dict[str, Any] = {}
        for name in ("Location", "Retry-After", "TaskMonitor"):
            value = cls._response_header_value(metadata, name)
            if type(value) is str:
                headers[name] = value[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS]
            elif type(value) is int and int.bit_length(value) <= 256:
                headers[name] = str(value)
            elif type(value) is float and math.isfinite(value):
                headers[name] = str(value)
        return headers

    @staticmethod
    def _is_sensitive_diagnostic_name(name: Any) -> bool:
        """
        Return whether a field or header name can carry secret material.

        The implementation uses ``name`` to determine whether a field or header
        name can carry secret material.

        Args:
            name: Stable name used for lookup and operator-facing diagnostics.

        Returns:
            Whether a field or header name can carry secret material.
        """
        if type(name) is not str or len(name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
            return True
        normalized = re.sub(r"[^a-z0-9]+", "-", name.strip().lower())
        return any(
            marker in normalized
            for marker in (
                "authorization",
                "cookie",
                "token",
                "secret",
                "api-key",
                "apikey",
                "csrf",
                "password",
                "passwd",
                "session",
                "credential",
                "private-key",
                "signature",
            )
        )

    @staticmethod
    def _is_diagnostic_uri_name(name: Any) -> bool:
        """
        Return whether a structured evidence field is expected to hold a URI.

        The implementation uses ``name`` to determine whether a structured
        evidence field is expected to hold a URI.

        Args:
            name: Stable name used for lookup and operator-facing diagnostics.

        Returns:
            Whether a structured evidence field is expected to hold a URI.
        """
        if type(name) is not str or len(name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
            return False
        normalized = re.sub(r"[^a-z0-9]+", "-", name.strip().lower()).strip("-")
        return normalized in {
            "location",
            "content-location",
            "uri",
            "url",
            "odata-id",
            "odata-nextlink",
            "taskmonitor",
            "href",
        } or normalized.endswith(("uri", "url"))

    def _sanitize_diagnostic_text(self, value: Any) -> str:
        """
        Sanitize free-form text before writing diagnostic evidence.

        After applying local validation, the function forwards ``value`` to
        ``re.sub`` and preserves its return and exception contract.

        Args:
            value: Value evaluated while performing sanitize free-form text
                before writing diagnostic evidence.

        Returns:
            The canonical diagnostic text.
        """
        text = str(value)
        sanitizer_candidates = [
            getattr(getattr(self, "logger", None), "sanitizer", None),
            getattr(getattr(self, "orchestrator", None), "sanitizer", None),
            getattr(
                getattr(
                    getattr(self, "orchestrator", None),
                    "sanitized_console",
                    None,
                ),
                "sanitizer",
                None,
            ),
        ]
        for sanitizer in sanitizer_candidates:
            sanitize = getattr(sanitizer, "sanitize", None)
            if not callable(sanitize):
                continue
            try:
                sanitized = sanitize(text)
            except Exception:
                continue
            if isinstance(sanitized, str):
                text = sanitized

        # Diagnostic JSON writers bypass runtime logging, so keep a final
        # structural guard even when no configured sanitizer is available.
        text = re.sub(
            r"(?im)\b(location|content-location)(\s*:\s*)([^\s,;\"']+)",
            lambda match: (
                f"{match.group(1)}{match.group(2)}"
                f"{self._sanitize_diagnostic_uri(match.group(3)) or '<redacted-uri>'}"
            ),
            text,
        )
        text = re.sub(
            r"(?i)\b(bearer|basic)\s+[^\s,;\"']+",
            r"\1 <redacted>",
            text,
        )
        text = re.sub(
            r"(?ix)([\"'][^\"']*(?:authorization|cookie|token|secret|"
            r"api[-_]?key|csrf|password|passwd|session|credential|"
            r"private[-_]?key|signature)[^\"']*[\"']\s*:\s*)"
            r"(?:\"[^\"]*\"|'[^']*'|[^,}\]\r\n]+)",
            r'\1"<redacted>"',
            text,
        )
        text = re.sub(
            r"(?i)\b(authorization|proxy-authorization|cookie|set-cookie|"
            r"x-auth-token|x-api-key|api-key|access-token|password|passwd|secret|"
            r"credential|private-key|signature)"
            r"(\s*[:=]\s*)([^\r\n,;]+)",
            r"\1\2<redacted>",
            text,
        )
        text = re.sub(
            r"(?i)(?<![a-z0-9])(/redfish/[^\s\"'<>),}\]]+\?" r"[^\s\"'<>),}\]]+)",
            lambda match: (
                self._sanitize_diagnostic_uri(match.group(1)) or "<redacted-uri>"
            ),
            text,
        )
        return re.sub(
            r"(?i)https?://[^\s\"'<>),}\]]+",
            lambda match: (
                self._sanitize_diagnostic_uri(match.group(0)) or "<redacted-url>"
            ),
            text,
        )

    def _bounded_diagnostic_log_text(self, value: Any) -> str:
        """
        Return a tiny scalar preview without parsing or copying full payloads.

        The implementation uses ``value`` to produce a tiny scalar preview
        without parsing or copying full payloads.

        Args:
            value: Value evaluated while performing tiny scalar preview without
                parsing or copying full payloads.

        Returns:
            The canonical bounded diagnostic log text.
        """

        value_type = type(value)
        if value_type is str:
            raw_text = value
        elif value_type is int:
            bit_length = int.bit_length(value)
            if bit_length > _DIAGNOSTIC_LOG_MAX_INTEGER_BITS:
                return f"<integer omitted bits={bit_length}>"
            raw_text = str(value)
        elif value is None or value_type in {bool, float}:
            raw_text = str(value)
        elif isinstance(value, BaseException):
            arguments = BaseException.args.__get__(value, BaseException)
            raw_text = next(
                (item for item in arguments[:4] if type(item) is str and item),
                self._bounded_type_name(value),
            )
        else:
            return f"<{self._bounded_type_name(value)} omitted>"

        preview = raw_text[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS]
        sanitized = self._sanitize_diagnostic_text(preview)
        if len(raw_text) > _DIAGNOSTIC_LOG_TEXT_MAX_CHARS:
            sanitized += f"<truncated chars={len(raw_text)}>"
        return sanitized

    def _bounded_diagnostic_log_value(self, value: Any, depth: int = 2) -> Any:
        """
        Build an independently small value for runtime logging only.

        Capture publication receives the original built-in value and performs
        its own incremental structural sanitization in the worker pool. This
        helper must never parse JSON-looking text or invoke extension hooks.

        Args:
            value: Entries supplied as ``value`` and processed in
                caller-provided order.
            depth: Numeric depth used while the operation performs bounded
                accounting.

        Returns:
            The bounded diagnostic log value selected by the operation.
        """

        value_type = type(value)
        if value is None or value_type in {bool, float}:
            return value
        if value_type is int:
            bit_length = int.bit_length(value)
            if bit_length > _DIAGNOSTIC_LOG_MAX_INTEGER_BITS:
                return {
                    "type": "integer",
                    "bit_length": bit_length,
                    "content": "omitted",
                }
            return value
        if value_type is str:
            return self._bounded_diagnostic_log_text(value)
        if value_type in {bytes, bytearray, memoryview}:
            return {
                "type": "bytes",
                "size_bytes": memoryview(value).nbytes,
                "content": "omitted",
            }
        if value_type is StreamedRedfishBody:
            return StreamedRedfishBody.capture_metadata(value)
        if depth <= 0:
            return "<nested content omitted>"
        if value_type is dict:
            bounded: Dict[str, Any] = {}
            total = dict.__len__(value)
            for index, (raw_key, item) in enumerate(dict.items(value)):
                if index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                    break
                if type(raw_key) is not str:
                    key = f"<unsupported-field-name-{index}>"
                    bounded[key] = "<value omitted>"
                    continue
                if len(raw_key) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
                    bounded[f"<oversized-field-name-{index}>"] = "<value omitted>"
                    continue
                key = self._bounded_diagnostic_log_text(raw_key)
                if self._is_sensitive_diagnostic_name(raw_key):
                    bounded[key] = "<redacted>"
                elif self._is_diagnostic_uri_name(raw_key) and type(item) is str:
                    bounded[key] = self._bounded_diagnostic_uri(item)
                else:
                    bounded[key] = self._bounded_diagnostic_log_value(item, depth - 1)
            if total > _DIAGNOSTIC_LOG_MAX_ITEMS:
                bounded["<omitted-items>"] = total - _DIAGNOSTIC_LOG_MAX_ITEMS
            return bounded
        if value_type in {list, tuple}:
            total = list.__len__(value) if value_type is list else tuple.__len__(value)
            iterator = (
                list.__iter__(value) if value_type is list else tuple.__iter__(value)
            )
            bounded_items = []
            for index, item in enumerate(iterator):
                if index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                    break
                bounded_items.append(
                    self._bounded_diagnostic_log_value(item, depth - 1)
                )
            if total > _DIAGNOSTIC_LOG_MAX_ITEMS:
                bounded_items.append(
                    {"omitted_items": total - _DIAGNOSTIC_LOG_MAX_ITEMS}
                )
            return bounded_items
        return {
            "type": self._bounded_type_name(value),
            "content": "omitted",
        }

    @staticmethod
    def _bounded_type_name(value: Any) -> str:
        """
        Read a class name without invoking a custom metaclass hook.

        The implementation uses ``value`` to read a class name without invoking
        a custom metaclass hook. Parsing or I/O must finish before the validated
        representation is made available to the caller.

        Args:
            value: Value evaluated while performing class name without invoking
                a custom metaclass hook.

        Returns:
            The canonical bounded type name.
        """

        value_type = type(value)
        try:
            raw_name = type.__getattribute__(value_type, "__name__")
        except (AttributeError, TypeError):
            return "object"
        if type(raw_name) is not str:
            return "object"
        safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "-", raw_name)[:96]
        return safe_name or "object"

    def _bounded_safe_response_headers(self, value: Any) -> Dict[str, str]:
        """
        Return only fixed-width, sanitized capture copies of safe headers.

        The implementation uses ``value`` to produce only fixed-width, sanitized
        capture copies of safe headers.

        Args:
            value: Entries supplied as ``value`` and processed in
                caller-provided order.

        Returns:
            A mapping containing bounded safe response headers.
        """

        if type(value) is not dict:
            return {}
        safe: Dict[str, str] = {}
        for index, (raw_name, item) in enumerate(dict.items(value)):
            if index >= _CAPTURE_AUXILIARY_SCAN_MAX_ITEMS:
                break
            if type(raw_name) is not str:
                continue
            if len(raw_name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
                continue
            normalized = raw_name.casefold()
            if normalized not in {
                "content-length",
                "content-type",
                "location",
                "retry-after",
                "taskmonitor",
            }:
                continue
            if self._is_sensitive_diagnostic_name(raw_name):
                continue
            if normalized in {"location", "taskmonitor"} and type(item) is str:
                safe[raw_name] = self._bounded_diagnostic_uri(item) or ""
            else:
                safe[raw_name] = self._bounded_diagnostic_log_text(item)
        return safe

    def _bounded_capture_auxiliary_mapping(self, value: Any) -> Dict[str, Any]:
        """
        Copy at most a fixed number of legacy retry metadata fields.

        The implementation uses ``value`` to copy at most a fixed number of
        legacy retry metadata fields.

        Args:
            value: Entries supplied as ``value`` and processed in
                caller-provided order.

        Returns:
            A mapping containing bounded capture auxiliary mapping.
        """

        if type(value) is not dict:
            return {}
        bounded: Dict[str, Any] = {}
        for index, (raw_name, item) in enumerate(dict.items(value)):
            if (
                index >= _CAPTURE_AUXILIARY_SCAN_MAX_ITEMS
                or len(bounded) >= _CAPTURE_AUXILIARY_MAX_ITEMS
            ):
                break
            if type(raw_name) is not str:
                continue
            if len(raw_name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
                continue
            if self._is_sensitive_diagnostic_name(raw_name):
                continue
            bounded[self._bounded_diagnostic_log_text(raw_name)] = (
                self._bounded_diagnostic_log_value(item)
            )
        return bounded

    def _bounded_result_metadata(self, value: Any) -> Dict[str, Any]:
        """
        Preserve a fixed-width public metadata prefix without a full copy.

        The implementation uses ``value`` to preserve a fixed-width public
        metadata prefix without a full copy.

        Args:
            value: Entries supplied as ``value`` and processed in
                caller-provided order.

        Returns:
            A mapping containing bounded result metadata.
        """

        if type(value) is not dict:
            return {}
        bounded: Dict[str, Any] = {}
        for index, (raw_name, item) in enumerate(dict.items(value)):
            if index >= _CAPTURE_AUXILIARY_MAX_ITEMS:
                break
            if type(raw_name) is str:
                if len(raw_name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
                    continue
                if self._is_sensitive_diagnostic_name(raw_name):
                    bounded[raw_name] = "<redacted>"
                elif self._is_diagnostic_uri_name(raw_name) and type(item) is str:
                    bounded[raw_name] = self._bounded_diagnostic_uri(item)
                else:
                    bounded[raw_name] = self._bounded_diagnostic_log_value(item)
        if dict.__len__(value) > len(bounded):
            bounded["metadata_truncated"] = True
        return bounded

