    @staticmethod
    def _bounded_nonnegative_integer(value: Any) -> Optional[int]:
        """
        Parse a small non-negative integer without converting a large scalar.

        The implementation uses ``value`` to parse a small non-negative integer
        without converting a large scalar. Parsing or I/O must finish before the
        validated representation is made available to the caller.

        Args:
            value: Value object whose ``strip`` state is read while performing
                small non-negative integer without converting a large scalar.

        Returns:
            The numeric bounded nonnegative integer value, or ``None`` when the
            requested value is unavailable.
        """

        if type(value) is int:
            return value if value >= 0 and int.bit_length(value) <= 256 else None
        if type(value) is not str or len(value) > 32:
            return None
        candidate = value.strip()
        if not candidate.isascii() or not candidate.isdecimal():
            return None
        return int(candidate)

    def _bounded_task_check_value(self, field_name: Any, value: Any) -> Any:
        """
        Normalize one explicitly supported task-monitor metadata field.

        The implementation uses ``field_name`` and ``value`` to normalize one
        explicitly supported task-monitor metadata field. The source value keeps
        its ownership while the normalized representation is returned
        separately.

        Args:
            field_name: Field label included in validation failures for the
                selected input.
            value: Value evaluated while performing one explicitly supported
                task-monitor metadata field.

        Returns:
            The bounded task check value selected by the operation.
        """

        if field_name == "TaskState":
            return self._bounded_task_state(value)
        if field_name == "TaskStatus":
            return self._bounded_task_status(value)
        if field_name == "PercentComplete":
            return self._bounded_task_percent_complete(value)
        return None

    @staticmethod
    def _bounded_task_message_id(value: Any) -> Optional[str]:
        """
        Return a syntactically shaped, fixed-width Redfish MessageId.

        The implementation uses ``value`` to produce a syntactically shaped,
        fixed-width Redfish MessageId.

        Args:
            value: Value object whose ``strip`` state is read while performing
                syntactically shaped, fixed-width Redfish MessageId.

        Returns:
            The validated ``candidate``, or ``None`` when no value qualifies.
        """

        if type(value) is not str or len(value) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
            return None
        candidate = value.strip()
        if not re.fullmatch(r"[A-Za-z0-9_-]+(?:\.[A-Za-z0-9_-]+)+", candidate):
            return None
        return candidate

    def _bounded_task_messages(
        self,
        value: Any,
        *,
        include_diagnostic_text: bool,
    ) -> Tuple[List[Dict[str, Any]], int]:
        """
        Project standard Redfish task messages into bounded evidence.

        The projection retains at most the configured diagnostic item limit and
        never follows OEM or other nested extensions. Free-form diagnostic text
        is included only when the caller explicitly requests it; every retained
        scalar is length-bounded and sanitized before it leaves this boundary.

        Args:
            value: Candidate Redfish ``Messages`` array supplied by a remote
                task resource.
            include_diagnostic_text: Whether to retain sanitized ``Message``,
                ``Resolution``, ``MessageArgs``, and ``RelatedProperties``
                fields in addition to fixed-width identity and severity fields.

        Returns:
            A pair containing the bounded message list and the number of source
            entries beyond the configured item limit.
        """

        if type(value) is not list:
            return [], 0

        total = list.__len__(value)
        messages: List[Dict[str, Any]] = []
        messages_omitted = max(0, total - _DIAGNOSTIC_LOG_MAX_ITEMS)
        for index, message in enumerate(list.__iter__(value)):
            if index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                break
            if type(message) is not dict:
                messages_omitted += 1
                continue

            safe_message: Dict[str, Any] = {}
            message_id = self._bounded_task_message_id(dict.get(message, "MessageId"))
            if message_id is not None:
                safe_message["MessageId"] = message_id
            for severity_name in ("MessageSeverity", "Severity"):
                severity = self._bounded_task_status(dict.get(message, severity_name))
                if severity is not None:
                    safe_message[severity_name] = severity

            if include_diagnostic_text:
                for text_name in ("Message", "Resolution"):
                    text_value = dict.get(message, text_name)
                    if type(text_value) is str:
                        safe_message[text_name] = self._bounded_diagnostic_log_text(
                            text_value
                        )

                for list_name, omitted_name in (
                    ("MessageArgs", "message_args_omitted"),
                    ("RelatedProperties", "related_properties_omitted"),
                ):
                    raw_items = dict.get(message, list_name)
                    if type(raw_items) is not list:
                        continue
                    safe_items = []
                    items_omitted = max(
                        0,
                        list.__len__(raw_items) - _DIAGNOSTIC_LOG_MAX_ITEMS,
                    )
                    for item_index, item in enumerate(list.__iter__(raw_items)):
                        if item_index >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                            break
                        if type(item) is str:
                            safe_items.append(self._bounded_diagnostic_log_text(item))
                        else:
                            items_omitted += 1
                    if safe_items:
                        safe_message[list_name] = safe_items
                    previously_omitted = self._bounded_nonnegative_integer(
                        dict.get(message, omitted_name)
                    )
                    omitted = max(items_omitted, previously_omitted or 0)
                    if omitted:
                        safe_message[omitted_name] = omitted

            if safe_message:
                messages.append(safe_message)
            else:
                messages_omitted += 1

        return messages, messages_omitted

    def _bounded_sensitive_response_capture(self, value: Any) -> Dict[str, Any]:
        """
        Allowlist a bounded task response that cannot echo body content.

        The implementation uses ``value`` to allowlist a bounded task response
        that cannot echo body content.

        Args:
            value: Value evaluated while performing allowlist a bounded task
                response that cannot echo body content.

        Returns:
            A mapping containing bounded sensitive response capture.
        """

        if type(value) is not dict:
            result: Dict[str, Any] = {
                "type": self._bounded_type_name(value),
                "content": "omitted",
            }
            if type(value) in {bytes, str}:
                result["length"] = len(value)
            return result

        safe: Dict[str, Any] = {}
        for key in ("@odata.id", "Id", "TaskMonitor"):
            item = dict.get(value, key)
            if item is not None:
                if self._is_diagnostic_uri_name(key) and type(item) is str:
                    safe[key] = self._bounded_diagnostic_uri(item)
                else:
                    safe[key] = self._bounded_diagnostic_log_value(item, depth=1)

        raw_task_state = dict.get(value, "TaskState")
        if raw_task_state is not None:
            safe["TaskState"] = self._bounded_task_state(raw_task_state) or "<omitted>"
        raw_task_status = dict.get(value, "TaskStatus")
        if raw_task_status is not None:
            safe["TaskStatus"] = (
                self._bounded_task_status(raw_task_status) or "<omitted>"
            )
        raw_percent_complete = dict.get(value, "PercentComplete")
        if raw_percent_complete is not None:
            bounded_percent = self._bounded_task_percent_complete(raw_percent_complete)
            safe["PercentComplete"] = (
                bounded_percent if bounded_percent is not None else "<omitted>"
            )

        raw_messages = dict.get(value, "Messages")
        if type(raw_messages) is list:
            messages, messages_omitted = self._bounded_task_messages(
                raw_messages,
                include_diagnostic_text=False,
            )
            if messages or not raw_messages:
                safe["Messages"] = messages
            if messages_omitted:
                safe["messages_omitted"] = messages_omitted
        safe["content"] = "omitted"
        return safe

    def _bounded_task_response_summary(
        self,
        response: Any,
        metadata: Any = None,
    ) -> Dict[str, Any]:
        """
        Return metadata-only task evidence without copying a response body.

        The implementation uses ``response`` and ``metadata`` to produce
        metadata-only task evidence without copying a response body.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional metadata; ``None`` selects the function's default
                behavior.

        Returns:
            The validated ``summary``.
        """

        summary = self._bounded_sensitive_response_capture(response)
        http_status = self._http_status_from_response(response, metadata)
        if http_status is not None:
            summary["http_status"] = http_status
        response_type = type(response)
        if response_type is dict:
            summary["field_count"] = dict.__len__(response)
        elif response_type in {list, tuple}:
            summary["item_count"] = (
                list.__len__(response)
                if response_type is list
                else tuple.__len__(response)
            )
        elif response_type in {str, bytes, bytearray, memoryview}:
            summary["length"] = (
                len(response)
                if response_type in {str, bytes, bytearray}
                else memoryview(response).nbytes
            )
        return summary

    def _bounded_task_artifact_response_summary(
        self,
        response: Any,
        metadata: Any = None,
    ) -> Dict[str, Any]:
        """
        Return bounded task artifact evidence with useful message details.

        The base task summary keeps arbitrary response bodies omitted. This
        artifact-specific projection adds only sanitized standard Redfish
        message fields so persisted task histories remain useful for debugging
        without copying Payload, OEM, or other nested response content.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional transport metadata used to retain the bounded
                HTTP status.

        Returns:
            A bounded task response summary suitable for diagnostic artifacts.
        """

        summary = self._bounded_task_response_summary(response, metadata)
        if type(response) is not dict:
            return summary

        # Preserve the original size metadata when revalidating a summary that
        # was already projected at this boundary. Recomputing ``field_count``
        # from the summary itself would otherwise corrupt its meaning on every
        # append to the same history file.
        if dict.get(response, "content") == "omitted":
            response_type = dict.get(response, "type")
            if type(response_type) is str:
                summary["type"] = self._bounded_diagnostic_log_text(response_type)
            for count_name in ("field_count", "item_count", "length"):
                count = self._bounded_nonnegative_integer(
                    dict.get(response, count_name)
                )
                if count is not None:
                    summary[count_name] = count
        raw_messages = dict.get(response, "Messages")
        previously_omitted = self._bounded_nonnegative_integer(
            dict.get(response, "messages_omitted")
        )
        if type(raw_messages) is not list:
            if previously_omitted:
                summary["messages_omitted"] = previously_omitted
            return summary

        messages, messages_omitted = self._bounded_task_messages(
            raw_messages,
            include_diagnostic_text=True,
        )
        if messages or not raw_messages:
            summary["Messages"] = messages
        else:
            summary.pop("Messages", None)
        omitted = max(messages_omitted, previously_omitted or 0)
        if omitted:
            summary["messages_omitted"] = omitted
        return summary

    def _bounded_named_diagnostic_fields(
        self,
        value: Any,
        field_names: Tuple[str, ...],
        *,
        depth: int = 1,
    ) -> Dict[str, Any]:
        """
        Project a fixed set of diagnostic evidence fields through the bounder.

        Only exact built-in mappings are inspected. The caller supplies a
        static field allowlist for one project-owned evidence schema, while the
        shared diagnostic normalizer continues to redact sensitive names,
        sanitize URIs and text, and enforce structural limits.

        Args:
            value: Candidate mapping containing project-owned diagnostic
                evidence.
            field_names: Exact field names allowed in the returned mapping.
            depth: Structural depth available to the selected field values.

        Returns:
            A bounded mapping containing only recognized fields.
        """

        if type(value) is not dict or depth <= 0:
            return {}
        bounded: Dict[str, Any] = {}
        for index, field_name in enumerate(field_names):
            if index >= _CAPTURE_AUXILIARY_MAX_ITEMS:
                break
            if type(field_name) is not str or not dict.__contains__(value, field_name):
                continue
            item = dict.get(value, field_name)
            if self._is_sensitive_diagnostic_name(field_name):
                bounded[field_name] = "<redacted>"
            elif self._is_diagnostic_uri_name(field_name) and type(item) is str:
                bounded[field_name] = self._bounded_diagnostic_uri(item)
            else:
                bounded[field_name] = self._bounded_diagnostic_log_value(
                    item,
                    depth=depth - 1,
                )
        return bounded

    def _bounded_persisted_request_payload_summary(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate an allowlisted request summary for diagnostic persistence.

        The projection retains only diagnostic selector fields and size/type
        metadata emitted by :meth:`_bounded_request_payload_summary`. Selector
        arrays receive one local structural level so their bounded string items
        survive the outer record's independent depth limit.

        Args:
            value: Candidate preprojected request payload summary.

        Returns:
            A bounded, idempotent request payload summary.
        """

        summary = self._bounded_named_diagnostic_fields(
            value,
            (
                "DiagnosticDataType",
                "OEMDiagnosticDataType",
                "DiagnosticDataTypes",
                "SelectDataTypes",
                "type",
                "length",
                "field_count",
            ),
            depth=2,
        )
        summary["content"] = "omitted"
        return summary

    def _bounded_persisted_response_body_summary(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate metadata-only response-body evidence for persistence.

        Body previews remain unconditionally absent. Type, length, truncation,
        and task metadata are retained only through their existing bounded
        projections; arbitrary response body fields are never copied.

        Args:
            value: Candidate response-body summary emitted by
                :meth:`_response_body_summary`.

        Returns:
            A bounded metadata-only response-body summary.
        """

        summary = self._bounded_named_diagnostic_fields(
            value,
            ("type", "length", "truncated", "size_bytes", "note"),
            depth=1,
        )
        if type(value) is dict and dict.__contains__(value, "preview"):
            summary["preview"] = None
        raw_task_summary = dict.get(value, "summary") if type(value) is dict else None
        if type(raw_task_summary) is dict:
            task_summary = self._bounded_task_response_summary(raw_task_summary)
            if dict.get(raw_task_summary, "content") == "omitted":
                response_type = dict.get(raw_task_summary, "type")
                if type(response_type) is str:
                    task_summary["type"] = self._bounded_diagnostic_log_text(
                        response_type
                    )
                for count_name in ("field_count", "item_count", "length"):
                    count = self._bounded_nonnegative_integer(
                        dict.get(raw_task_summary, count_name)
                    )
                    if count is not None:
                        task_summary[count_name] = count
                messages_omitted = self._bounded_nonnegative_integer(
                    dict.get(raw_task_summary, "messages_omitted")
                )
                if messages_omitted:
                    task_summary["messages_omitted"] = messages_omitted
            summary["summary"] = task_summary
        return summary

    def _bounded_persisted_download_attempt(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate one project-owned attachment download attempt.

        Scalar retry/timing fields are allowlisted. Headers, body metadata, and
        transport retry details are independently reprojected through their
        owning sanitizers so no raw response body or authentication material is
        introduced by restoring the structured attempt.

        Args:
            value: Candidate attachment attempt evidence mapping.

        Returns:
            A bounded attachment attempt mapping.
        """

        attempt = self._bounded_named_diagnostic_fields(
            value,
            (
                "attempt",
                "success",
                "http_status",
                "request_timeout_seconds",
                "request_duration_seconds",
                "declared_content_length_bytes",
                "attachment_size_bytes",
                "max_attachment_size_bytes",
                "retryable",
                "will_retry",
                "retry_after_seconds",
                "retry_delay_seconds",
                "terminal_reason",
                "readiness_remaining_seconds",
                "collector_remaining_seconds",
                "timestamp",
                "archive_validation_error",
            ),
            depth=1,
        )
        if type(value) is not dict:
            return attempt

        raw_response = dict.get(value, "response")
        if raw_response is None and dict.__contains__(value, "response"):
            attempt["response"] = None
        elif type(raw_response) is dict:
            attempt["response"] = self._bounded_named_diagnostic_fields(
                raw_response,
                ("type", "size_bytes", "note"),
                depth=1,
            )

        raw_headers = dict.get(value, "response_headers")
        if type(raw_headers) is dict:
            attempt["response_headers"] = self._sanitize_response_headers(raw_headers)
        raw_body_summary = dict.get(value, "response_body_summary")
        if type(raw_body_summary) is dict:
            attempt["response_body_summary"] = (
                self._bounded_persisted_response_body_summary(raw_body_summary)
            )
        raw_retry_details = dict.get(value, "transport_retry_details")
        if type(raw_retry_details) is dict:
            attempt["transport_retry_details"] = (
                self._bounded_capture_auxiliary_mapping(raw_retry_details)
            )
        raw_archive_error = dict.get(value, "archive_validation_error")
        if type(raw_archive_error) is str:
            attempt["archive_validation_error"] = self._bounded_diagnostic_log_text(
                raw_archive_error
            )
        return attempt

    def _bounded_persisted_download_attempts(
        self,
        value: Any,
    ) -> Tuple[List[Dict[str, Any]], int]:
        """
        Revalidate a bounded prefix of attachment download attempts.

        Existing omission sentinels are recognized so repeated appends do not
        lose the original omitted count. Non-mapping entries consume the same
        fixed scan budget but are not copied into the returned history.

        Args:
            value: Candidate list of attachment attempt evidence mappings.

        Returns:
            A pair containing the bounded attempts and omitted-entry count.
        """

        if type(value) is not list:
            return [], 0
        attempts: List[Dict[str, Any]] = []
        omitted = 0
        source_entries = 0
        total = list.__len__(value)
        scan_count = min(total, _DIAGNOSTIC_LOG_MAX_ITEMS + 1)
        for index in range(scan_count):
            item = list.__getitem__(value, index)
            if (
                type(item) is dict
                and dict.__len__(item) == 1
                and dict.__contains__(item, "omitted_items")
            ):
                prior_omitted = self._bounded_nonnegative_integer(
                    dict.get(item, "omitted_items")
                )
                omitted = max(omitted, prior_omitted or 0)
                continue
            source_entries += 1
            if source_entries > _DIAGNOSTIC_LOG_MAX_ITEMS:
                omitted += 1
                continue
            if type(item) is dict:
                attempts.append(self._bounded_persisted_download_attempt(item))
            else:
                omitted += 1
        omitted += total - scan_count
        return attempts, omitted

    def _bounded_persisted_attachment_retry_details(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate bounded attachment retry policy and attempt evidence.

        Scalar policy fields are copied from a fixed allowlist. The attempt
        list is independently capped and carries a stable omission count so a
        later append cannot expand or silently flatten the retained history.

        Args:
            value: Candidate retry-details mapping from attachment failure
                evidence.

        Returns:
            A bounded retry-details mapping with a capped attempt history.
        """

        details = self._bounded_named_diagnostic_fields(
            value,
            (
                "attempt_count",
                "configured_max_attempts",
                "readiness_timeout_seconds",
                "poll_interval_seconds",
                "terminal_reason",
            ),
            depth=1,
        )
        if type(value) is not dict:
            return details
        attempts, newly_omitted = self._bounded_persisted_download_attempts(
            dict.get(value, "attempts")
        )
        if attempts or type(dict.get(value, "attempts")) is list:
            details["attempts"] = attempts
        previously_omitted = self._bounded_nonnegative_integer(
            dict.get(value, "attempts_omitted")
        )
        omitted = max(newly_omitted, previously_omitted or 0)
        if omitted:
            details["attempts_omitted"] = omitted
        return details

    def _bounded_persisted_attachment_failure(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate structured attachment failure evidence for persistence.

        The returned schema contains only project-authored task, URI, size,
        HTTP, retry, and placeholder-only reproduction fields. Each nested
        component is passed through its dedicated bounded projection.

        Args:
            value: Candidate attachment failure evidence mapping.

        Returns:
            A bounded attachment failure evidence mapping.
        """

        failure = self._bounded_named_diagnostic_fields(
            value,
            (
                "task_id",
                "task_state",
                "task_status",
                "task_percent_complete",
                "resolved_entry_uri",
                "attachment_uri",
                "download_target_uri",
                "attachment_resolution_source",
                "advertised_attachment_size_bytes",
                "entry_advertised_attachment_size_bytes",
                "declared_content_length_bytes",
                "http_status",
            ),
            depth=1,
        )
        if type(value) is not dict:
            return failure

        raw_headers = dict.get(value, "response_headers")
        if type(raw_headers) is dict:
            failure["response_headers"] = self._sanitize_response_headers(raw_headers)
        raw_body_summary = dict.get(value, "response_body_summary")
        if type(raw_body_summary) is dict:
            failure["response_body_summary"] = (
                self._bounded_persisted_response_body_summary(raw_body_summary)
            )
        raw_retry_details = dict.get(value, "retry_details")
        if type(raw_retry_details) is dict:
            failure["retry_details"] = self._bounded_persisted_attachment_retry_details(
                raw_retry_details
            )
        raw_curl_equivalent = dict.get(value, "curl_equivalent")
        if type(raw_curl_equivalent) is dict:
            failure["curl_equivalent"] = self._bounded_named_diagnostic_fields(
                raw_curl_equivalent,
                ("argv", "command", "note"),
                depth=2,
            )
        return failure

    def _bounded_task_failure_artifact_summary(
        self,
        value: Any,
    ) -> Dict[str, Any]:
        """
        Revalidate task-failure evidence for a persisted diagnostic artifact.

        Generic failure projections remain metadata-only. This artifact-specific
        projection may retain sanitized standard Redfish message text supplied
        by runtime failure context while continuing to omit OEM extensions and
        arbitrary response content.

        Args:
            value: Candidate task-failure evidence mapping.

        Returns:
            A bounded task-failure artifact summary.
        """

        summary = self._bounded_task_failure_summary(value)
        if type(value) is not dict:
            return summary
        raw_messages = dict.get(value, "messages")
        previously_omitted = self._bounded_nonnegative_integer(
            dict.get(value, "messages_omitted")
        )
        if type(raw_messages) is list:
            messages, newly_omitted = self._bounded_task_messages(
                raw_messages,
                include_diagnostic_text=True,
            )
            if messages or not raw_messages:
                summary["messages"] = messages
            omitted = max(newly_omitted, previously_omitted or 0)
            if omitted:
                summary["messages_omitted"] = omitted
        elif previously_omitted:
            summary["messages_omitted"] = previously_omitted

        raw_response = dict.get(value, "response")
        if raw_response is None:
            raw_response = dict.get(value, "response_summary")
        if type(raw_response) is dict:
            summary["response_summary"] = self._bounded_task_artifact_response_summary(
                raw_response
            )
        return summary

    def _restore_bounded_diagnostic_structure_evidence(
        self,
        source: Dict[str, Any],
        bounded: Dict[str, Any],
        file_type: str,
    ) -> Dict[str, Any]:
        """
        Restore known prebounded structures after outer record normalization.

        The generic diagnostic writer intentionally keeps a shallow default for
        unrecognized data. This method selectively reprojects only structures
        produced by the diagnostic request, task failure, and attachment
        evidence builders, preventing their arrays and nested mappings from
        becoming omission markers during append or history revalidation.

        Args:
            source: Original diagnostic record before generic bounding.
            bounded: Independently bounded record receiving known structures.
            file_type: Diagnostic artifact kind selecting valid field schemas.

        Returns:
            The supplied bounded record with recognized structures restored.

        Side Effects:
            Mutates recognized fields in ``bounded``.
        """

        if type(source) is not dict or type(bounded) is not dict:
            return bounded
        if file_type == "diagnostic_requests":
            payload_names = ("payload_summary",)
        elif file_type in {"diagnostic_responses", "diagnostic_errors"}:
            payload_names = ("request_payload_summary",)
        else:
            payload_names = ()
        for payload_name in payload_names:
            raw_payload = dict.get(source, payload_name)
            if type(raw_payload) is dict:
                bounded[payload_name] = self._bounded_persisted_request_payload_summary(
                    raw_payload
                )

        if file_type not in {"diagnostic_responses", "diagnostic_errors"}:
            return bounded

        if file_type == "diagnostic_responses":
            bounded.update(
                self._bounded_named_diagnostic_fields(
                    source,
                    (
                        "request_uri",
                        "response_status",
                        "http_status",
                        "response_headers",
                        "location",
                        "retry_after",
                        "selected_monitor_uri",
                        "monitor_uri_candidates",
                        "dump_location",
                        "resolved_entry_uri",
                        "attachment_uri",
                        "download_target_uri",
                        "attachment_resolution_source",
                        "advertised_attachment_size_bytes",
                        "entry_advertised_attachment_size_bytes",
                        "declared_content_length_bytes",
                        "attachment_size_bytes",
                        "success",
                        "data_type",
                        "data_size",
                        "task_id",
                        "task_state",
                        "task_status",
                        "task_percent_complete",
                        "entity_type",
                        "entity_id",
                        "log_service",
                        "step",
                        "download_attempt_count",
                        "timestamp",
                        "saved_file",
                        "error",
                    ),
                    depth=2,
                )
            )

        raw_attempts = dict.get(source, "download_attempts")
        if type(raw_attempts) is list:
            attempts, newly_omitted = self._bounded_persisted_download_attempts(
                raw_attempts
            )
            bounded["download_attempts"] = attempts
            previously_omitted = self._bounded_nonnegative_integer(
                dict.get(source, "download_attempts_omitted")
            )
            omitted = max(newly_omitted, previously_omitted or 0)
            if omitted:
                bounded["download_attempts_omitted"] = omitted

        body_summary_names = (
            ("response_body_summary",)
            if file_type == "diagnostic_responses"
            else ("dump_data",)
        )
        for body_summary_name in body_summary_names:
            raw_body_summary = dict.get(source, body_summary_name)
            if type(raw_body_summary) is dict:
                bounded[body_summary_name] = (
                    self._bounded_persisted_response_body_summary(raw_body_summary)
                )

        raw_attachment_failure = dict.get(source, "attachment_failure")
        if type(raw_attachment_failure) is dict:
            bounded["attachment_failure"] = self._bounded_persisted_attachment_failure(
                raw_attachment_failure
            )
        if file_type == "diagnostic_errors":
            raw_task_failure = dict.get(source, "task_failure")
            if type(raw_task_failure) is dict:
                bounded["task_failure"] = self._bounded_task_failure_artifact_summary(
                    raw_task_failure
                )
        return bounded

    def _restore_bounded_task_message_evidence(
        self,
        source: Dict[str, Any],
        bounded: Dict[str, Any],
        file_type: str,
    ) -> Dict[str, Any]:
        """
        Restore allowlisted task responses after generic record bounding.

        Diagnostic array records are deliberately normalized to two structural
        levels. Task message objects sit one level deeper, so this method
        selectively reprojects only standard, bounded task and message fields
        for task, response, and error artifacts. Other nested response content
        remains omitted.

        Args:
            source: Original task diagnostic record before generic bounding.
            bounded: Independently bounded record that receives safe message
                evidence.
            file_type: Diagnostic artifact kind selecting the recognized task
                response fields.

        Returns:
            The supplied bounded record with any qualifying task message
            evidence restored.

        Side Effects:
            Mutates qualifying nested response mappings in ``bounded``.
        """

        if type(source) is not dict or type(bounded) is not dict:
            return bounded
        if file_type == "task_status_updates":
            response_names = ("response_summary", "response_data")
        elif file_type == "task_completions":
            response_names = ("completion_response",)
        elif file_type == "diagnostic_responses":
            response_names = ("response_summary",)
        elif file_type == "diagnostic_errors":
            response_names = ("response_summary", "task_completion")
        else:
            return bounded

        for response_name in response_names:
            source_response = dict.get(source, response_name)
            if type(source_response) is not dict:
                continue
            bounded[response_name] = self._bounded_task_artifact_response_summary(
                source_response
            )
        return bounded

    def _bounded_response_metadata_summary(
        self,
        response: Any,
        metadata: Any = None,
    ) -> Dict[str, Any]:
        """
        Describe an arbitrary Redfish body without retaining any body value.

        The implementation uses ``response`` and ``metadata`` to describe an
        arbitrary Redfish body without retaining any body value.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional metadata; ``None`` selects the function's default
                behavior.

        Returns:
            The validated ``summary``.
        """

        response_type = type(response)
        summary: Dict[str, Any] = {
            "type": self._bounded_type_name(response),
            "content": "omitted",
        }
        http_status = self._http_status_from_response(response, metadata)
        if http_status is not None:
            summary["http_status"] = http_status
        if response_type is dict:
            summary["field_count"] = dict.__len__(response)
        elif response_type is list:
            summary["item_count"] = list.__len__(response)
        elif response_type is tuple:
            summary["item_count"] = tuple.__len__(response)
        elif response_type in {str, bytes, bytearray}:
            summary["length"] = len(response)
        elif response_type is memoryview:
            summary["length"] = memoryview(response).nbytes
        elif response_type is StreamedRedfishBody:
            summary["size_bytes"] = response.size_bytes
        return summary

    def _bounded_response_metadata_text(
        self,
        response: Any,
        metadata: Any = None,
    ) -> str:
        """
        Return a deterministic, body-independent response log fragment.

        After applying local validation, the function forwards ``response`` and
        ``metadata`` to ``json.dumps`` and preserves its return and exception
        contract.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            metadata: Optional metadata; ``None`` selects the function's default
                behavior.

        Returns:
            The canonical bounded response metadata text.
        """

        return json.dumps(
            self._bounded_response_metadata_summary(response, metadata),
            sort_keys=True,
            separators=(",", ":"),
        )

    def _bounded_task_failure_summary(self, value: Any) -> Dict[str, Any]:
        """
        Normalize legacy/current task failures to a metadata-only allowlist.

        The implementation uses ``value`` to normalize legacy/current task
        failures to a metadata-only allowlist. The source value keeps its
        ownership while the normalized representation is returned separately.
        Remote I/O uses the configured transport policy and returns only after
        its response or failure has been observed.

        Args:
            value: Value evaluated while performing legacy/current task failures
                to a metadata-only allowlist.

        Returns:
            A mapping containing bounded task failure summary.
        """

        if type(value) is not dict:
            return {}
        summary: Dict[str, Any] = {}
        task_id = dict.get(value, "task_id")
        if task_id is not None:
            summary["task_id"] = self._bounded_diagnostic_log_text(task_id)
        state = self._bounded_task_state(dict.get(value, "state"))
        if state is not None:
            summary["state"] = state
        status = self._bounded_task_status(dict.get(value, "status"))
        if status is not None:
            summary["status"] = status
        messages = dict.get(value, "messages")
        if type(messages) is not list and messages is not None:
            messages = [messages]
        if messages is not None:
            safe_messages = self._bounded_sensitive_response_capture(
                {"Messages": messages}
            ).get("Messages", [])
            if safe_messages or not messages:
                summary["messages"] = safe_messages
        for name in ("monitor_uri", "monitor_uris"):
            item = dict.get(value, name)
            if name == "monitor_uri":
                safe_uri = self._bounded_diagnostic_uri(item)
                if safe_uri is not None:
                    summary[name] = safe_uri
            elif type(item) is list:
                summary[name] = [
                    safe_uri
                    for uri in list.__iter__(item[:_DIAGNOSTIC_LOG_MAX_ITEMS])
                    if (safe_uri := self._bounded_diagnostic_uri(uri)) is not None
                ]
        response = dict.get(value, "response")
        if response is not None:
            summary["response_summary"] = self._bounded_task_response_summary(response)
        elif type(dict.get(value, "response_summary")) is dict:
            summary["response_summary"] = self._bounded_diagnostic_log_value(
                dict.get(value, "response_summary"), depth=2
            )
        return summary

    def _bounded_request_payload_summary(self, payload: Any) -> Dict[str, Any]:
        """
        Retain only non-secret diagnostic selectors from a request payload.

        The implementation uses ``payload`` to retain only non-secret diagnostic
        selectors from a request payload.

        Args:
            payload: Payload consumed while the function attempts to retain only
                non-secret diagnostic selectors from a request payload.

        Returns:
            A mapping containing bounded request payload summary.
        """

        if type(payload) is not dict:
            summary: Dict[str, Any] = {
                "type": self._bounded_type_name(payload),
                "content": "omitted",
            }
            payload_type = type(payload)
            if payload_type in {str, bytes, bytearray}:
                summary["length"] = len(payload)
            elif payload_type is memoryview:
                summary["length"] = memoryview(payload).nbytes
            return summary
        summary: Dict[str, Any] = {}
        for name in (
            "DiagnosticDataType",
            "OEMDiagnosticDataType",
            "DiagnosticDataTypes",
            "SelectDataTypes",
        ):
            value = dict.get(payload, name)
            if value is not None:
                summary[name] = self._bounded_diagnostic_log_value(value, depth=1)
        summary["field_count"] = dict.__len__(payload)
        summary["content"] = "omitted"
        return summary

    def _sanitize_diagnostic_value(self, value: Any, depth: int = 5) -> Any:
        """
        Compatibility wrapper for the fixed-width diagnostic normalizer.

        After applying local validation, the function forwards ``value`` and
        ``depth`` to ``self._bounded_diagnostic_log_value`` and preserves its
        return and exception contract.

        Args:
            value: Value evaluated while performing compatibility wrapper for
                the fixed-width diagnostic normalizer.
            depth: Numeric depth used while the operation performs bounded
                accounting.

        Returns:
            The diagnostic value selected by the operation.
        """

        bounded_depth = min(2, max(0, depth)) if type(depth) is int else 0
        return self._bounded_diagnostic_log_value(value, bounded_depth)

    def _sanitize_response_headers(self, headers: Any) -> Dict[str, str]:
        """
        Return a fixed-width header mapping with secret values removed.

        The implementation uses ``headers`` to produce a fixed-width header
        mapping with secret values removed.

        Args:
            headers: Entries supplied as ``headers`` and processed in
                caller-provided order.

        Returns:
            A mapping containing response headers.
        """
        if type(headers) is not dict:
            return {}
        sanitized: Dict[str, str] = {}
        for index, (name, value) in enumerate(dict.items(headers)):
            if (
                index >= _CAPTURE_AUXILIARY_SCAN_MAX_ITEMS
                or len(sanitized) >= _CAPTURE_AUXILIARY_MAX_ITEMS
            ):
                break
            if type(name) is not str or len(name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS:
                continue
            if self._is_sensitive_diagnostic_name(name):
                sanitized[name] = "<redacted>"
            elif name.strip().lower() in {"location", "content-location"}:
                sanitized[name] = self._bounded_diagnostic_uri(value) or ""
            else:
                sanitized[name] = self._bounded_diagnostic_log_text(value)
        return sanitized

    def _response_headers_from_metadata(self, metadata: Any) -> Dict[str, str]:
        """
        Extract sanitized HTTP headers from bounded dispatch metadata.

        The implementation uses ``metadata`` to extract sanitized HTTP headers
        from bounded dispatch metadata.

        Args:
            metadata: Metadata consumed while the function attempts to extract
                sanitized HTTP headers from bounded dispatch metadata.

        Returns:
            A mapping containing response headers from metadata.
        """
        if type(metadata) not in {dict, _RequestTimingMetadata}:
            return {}
        headers = dict.get(metadata, "response_headers")
        http_response = dict.get(metadata, "http_response")
        if headers is None and type(http_response) is dict:
            headers = dict.get(http_response, "headers")
        return self._sanitize_response_headers(headers)

    @staticmethod
    def _content_length_from_headers(headers: Dict[str, Any]) -> Optional[int]:
        """
        Parse a non-negative Content-Length case-insensitively.

        The implementation uses ``headers`` to parse a non-negative
        Content-Length case-insensitively. Parsing or I/O must finish before the
        validated representation is made available to the caller.

        Args:
            headers: Mapping supplying fields for non-negative Content-Length
                case-insensitively.

        Returns:
            The numeric content length from headers value, or ``None`` when the
            requested value is unavailable.
        """
        if type(headers) is not dict:
            return None
        for index, (name, value) in enumerate(dict.items(headers)):
            if index >= _CAPTURE_AUXILIARY_SCAN_MAX_ITEMS:
                break
            if (
                type(name) is not str
                or len(name) > _DIAGNOSTIC_FIELD_NAME_MAX_CHARS
                or name.casefold() != "content-length"
            ):
                continue
            if type(value) is str:
                if len(value) > 32:
                    return None
                raw_value: Any = value.strip()
            elif type(value) is int and int.bit_length(value) <= 256:
                raw_value = value
            else:
                return None
            try:
                parsed = int(raw_value)
                return parsed if parsed >= 0 else None
            except (TypeError, ValueError):
                return None
        return None

    def _response_body_summary(
        self, response: Any, limit: int = 2000
    ) -> Dict[str, Any]:
        """
        Build metadata-only evidence without retaining a body preview.

        The implementation uses ``response`` and ``limit`` to build
        metadata-only evidence without retaining a body preview.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            limit: Numeric limit used while the operation performs bounded
                accounting.

        Returns:
            A mapping containing the ``type``, ``length``, ``preview``,
            ``truncated``, and ``size_bytes`` fields.
        """
        _ = limit
        if response is None:
            return {"type": "none", "length": 0, "preview": None, "truncated": False}
        if type(response) is StreamedRedfishBody:
            return {
                "type": "streamed_body",
                "size_bytes": response.size_bytes,
                "preview": None,
                "truncated": False,
                "note": "binary content omitted",
            }
        if type(response) in {bytes, bytearray, memoryview}:
            return {
                "type": "bytes",
                "size_bytes": (
                    len(response)
                    if type(response) in {bytes, bytearray}
                    else memoryview(response).nbytes
                ),
                "preview": None,
                "truncated": False,
                "note": "binary content omitted",
            }
        response_type = type(response)
        value_type = "json" if response_type in {dict, list, tuple} else "text"
        length = len(response) if response_type in {str, list, tuple, dict} else None
        return {
            "type": value_type,
            "length": length,
            "preview": None,
            "truncated": bool(length),
            "summary": self._bounded_task_response_summary(response),
        }

    def _sanitize_diagnostic_uri(self, uri: Any) -> Optional[str]:
        """
        Remove URL userinfo and replace the complete query for evidence.

        After applying local validation, the function forwards ``uri`` to
        ``_canonical_uri_sanitizer`` and preserves its return and exception
        contract.

        Args:
            uri: Validated remote resource identifier used for URI.

        Returns:
            The canonical diagnostic URI text, or ``None`` when the requested
            value is unavailable.
        """

        return _canonical_uri_sanitizer(self._sanitize_diagnostic_text, uri)

    def _bounded_diagnostic_uri(self, value: Any) -> Optional[str]:
        """
        Sanitize only a fixed-width exact string URI preview.

        The implementation uses ``value`` to sanitize only a fixed-width exact
        string URI preview.

        Args:
            value: Value evaluated while performing sanitize only a fixed-width
                exact string URI preview.

        Returns:
            The validated ``sanitized``, or ``None`` when no value qualifies.
        """

        if type(value) is not str or not value:
            return None
        sanitized = _bounded_uri_preview(
            self._sanitize_diagnostic_uri,
            value,
            max_chars=_DIAGNOSTIC_LOG_TEXT_MAX_CHARS,
        )
        if sanitized is None:
            return None
        sanitized = sanitized[:_DIAGNOSTIC_LOG_TEXT_MAX_CHARS]
        if len(value) > _DIAGNOSTIC_LOG_TEXT_MAX_CHARS:
            sanitized += f"<truncated chars={len(value)}>"
        return sanitized

    def _diagnostic_uri_evidence(self, value: Any) -> str:
        """
        Return one fail-closed URI rendering for logs and evidence.

        The implementation uses ``value`` to produce one fail-closed URI
        rendering for logs and evidence.

        Args:
            value: Value evaluated while performing one fail-closed URI
                rendering for logs and evidence.

        Returns:
            Whether the one fail-closed URI rendering for logs and evidence
            operation succeeds.
        """

        return self._bounded_diagnostic_uri(value) or "<omitted-uri>"

    def _diagnostic_uri_list_evidence(self, values: Any) -> List[str]:
        """
        Return bounded URI copies without modifying live request targets.

        The implementation uses ``values`` to produce bounded URI copies without
        modifying live request targets.

        Args:
            values: Mapping supplying fields for bounded URI copies without
                modifying live request targets.

        Returns:
            The diagnostic URI list evidence returned in operation-defined
            order.
        """

        if type(values) not in {list, tuple}:
            return []
        safe_values = [
            self._diagnostic_uri_evidence(value)
            for value in values[:_DIAGNOSTIC_LOG_MAX_ITEMS]
        ]
        if len(values) > _DIAGNOSTIC_LOG_MAX_ITEMS:
            safe_values.append(
                f"<omitted-uris count={len(values) - _DIAGNOSTIC_LOG_MAX_ITEMS}>"
            )
        return safe_values

    def _diagnostic_uri_keyed_mapping(self, value: Any) -> Dict[str, Any]:
        """
        Copy a bounded attachment map with only sanitized, unique URI keys.

        The implementation uses ``value`` to copy a bounded attachment map with
        only sanitized, unique URI keys.

        Args:
            value: Entries supplied as ``value`` and processed in
                caller-provided order.

        Returns:
            A mapping containing diagnostic URI keyed mapping.
        """

        if type(value) is not dict:
            return {}
        safe: Dict[str, Any] = {}
        item_limit = min(
            self.MAX_FOLLOWED_COLLECTION_MEMBERS,
            _DIAGNOSTIC_LOG_MAX_ITEMS,
        )
        for index, (raw_uri, item) in enumerate(dict.items(value)):
            if index >= item_limit:
                omission_key = "<omitted-uri-items>"
                duplicate = 2
                while omission_key in safe:
                    omission_key = f"<omitted-uri-items duplicate={duplicate}>"
                    duplicate += 1
                safe[omission_key] = dict.__len__(value) - item_limit
                break
            base_key = (
                self._diagnostic_uri_evidence(raw_uri)
                if type(raw_uri) is str
                else f"<invalid-uri-key-{index}>"
            )
            key = base_key
            duplicate = 2
            while key in safe:
                key = f"{base_key} <duplicate={duplicate}>"
                duplicate += 1
            safe[key] = self._bounded_diagnostic_log_value(item, depth=2)
        return safe

    @staticmethod
    def _uri_has_attachment_path(uri: Any) -> bool:
        """
        Return whether the URI path ends in the Redfish attachment segment.

        The implementation uses ``uri`` to determine whether the URI path ends
        in the Redfish attachment segment.

        Args:
            uri: Validated remote resource identifier used for URI.

        Returns:
            Whether the URI path ends in the Redfish attachment segment.
        """
        try:
            return urlsplit(str(uri)).path.endswith("/attachment")
        except (TypeError, ValueError):
            return str(uri).split("?", 1)[0].split("#", 1)[0].endswith("/attachment")

    @classmethod
    def _entry_uri_from_attachment_uri(cls, uri: Any) -> str:
        """
        Remove a terminal attachment path while preserving query placement.

        The implementation uses ``uri`` to remove a terminal attachment path
        while preserving query placement.

        Args:
            uri: Validated remote resource identifier used for URI.

        Returns:
            The canonical entry URI from attachment URI text.
        """
        raw_uri = str(uri)
        try:
            parts = urlsplit(raw_uri)
            if not parts.path.endswith("/attachment"):
                return raw_uri
            return urlunsplit(
                (
                    parts.scheme,
                    parts.netloc,
                    parts.path[: -len("/attachment")],
                    parts.query,
                    parts.fragment,
                )
            )
        except (TypeError, ValueError):
            return raw_uri

    @classmethod
    def _append_attachment_uri(cls, uri: Any) -> str:
        """
        Append /attachment to the URI path before a query or fragment.

        The implementation uses ``uri`` to append /attachment to the URI path
        before a query or fragment.

        Args:
            uri: Validated remote resource identifier used for URI.

        Returns:
            The canonical append attachment URI text.
        """
        raw_uri = str(uri)
        if cls._uri_has_attachment_path(raw_uri):
            return raw_uri
        try:
            parts = urlsplit(raw_uri)
            return urlunsplit(
                (
                    parts.scheme,
                    parts.netloc,
                    parts.path.rstrip("/") + "/attachment",
                    parts.query,
                    parts.fragment,
                )
            )
        except (TypeError, ValueError):
            return raw_uri.rstrip("/") + "/attachment"

    def _attachment_reproduction_context(
        self,
        attachment_uri: Any,
        timeout_seconds: Any,
        base_uri: Any = None,
        scheme_hint: Any = None,
    ) -> Dict[str, Any]:
        """
        Build a curl-equivalent command containing placeholders only.

        The implementation uses ``attachment_uri``, ``timeout_seconds``,
        ``base_uri``, and ``scheme_hint`` to build a curl-equivalent command
        containing placeholders only.

        Args:
            attachment_uri: Validated remote resource identifier used for
                attachment URI.
            timeout_seconds: Maximum duration in seconds allowed for timeout
                seconds.
            base_uri: Validated remote resource identifier used for base URI.
            scheme_hint: Optional scheme hint; ``None`` selects the function's
                default behavior.

        Returns:
            A mapping containing the ``argv``, ``command``, and ``note`` fields.
        """
        safe_uri = self._sanitize_diagnostic_uri(attachment_uri) or "/redfish/v1"
        scheme = ""
        try:
            uri_parts = urlsplit(safe_uri)
            scheme = uri_parts.scheme.lower()
            path_and_query = urlunsplit(
                ("", "", uri_parts.path or "/", uri_parts.query, "")
            )
        except ValueError:
            path_and_query = safe_uri if safe_uri.startswith("/") else f"/{safe_uri}"
        if not path_and_query.startswith("/"):
            path_and_query = f"/{path_and_query}"
        normalized_scheme_hint = str(scheme_hint).lower()
        if scheme not in {"http", "https"} and normalized_scheme_hint in {
            "http",
            "https",
        }:
            scheme = normalized_scheme_hint
        if scheme not in {"http", "https"} and base_uri:
            try:
                scheme = urlsplit(str(base_uri)).scheme.lower()
            except ValueError:
                scheme = ""
        if scheme not in {"http", "https"}:
            scheme = "<redfish-scheme>"
        reproduction_url = f"{scheme}://<redfish-host>{path_and_query}"
        try:
            max_time = max(1, int(float(timeout_seconds)))
        except (TypeError, ValueError):
            max_time = 300
        argv = [
            "curl",
            "--request",
            "GET",
            "--location",
            "--insecure",
            "--max-time",
            str(max_time),
            "--user",
            "<REDFISH_USERNAME>:<REDFISH_PASSWORD>",
            "--output",
            "<OUTPUT_FILE>",
            reproduction_url,
        ]
        return {
            "argv": argv,
            "command": shlex.join(argv),
            "note": (
                "Host and credentials are placeholders; no Authorization, cookie, "
                "or session-token values were captured."
            ),
        }

    def _select_task_monitor_uris(
        self,
        dut_id: str,
        task_id: str,
        response: Any,
        response_metadata: Any,
    ) -> List[str]:
        """
        Select safe task-monitor candidates in Redfish contract order.

        ``Location`` is authoritative for asynchronous operations. Firmware in
        the field also returns a distinct body ``TaskMonitor`` and a shorter-
        lived task resource, so both are retained as bounded fallbacks.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            task_id: Stable task identifier used to correlate configuration,
                logs, and results.
            response: Transport response governed by the configured
                authentication and trust policy.
            response_metadata: Response metadata consumed while the function
                attempts to select safe task-monitor candidates in Redfish
                contract order.

        Returns:
            The validated ``selected``.
        """
        candidates: List[Any] = [
            self._response_header_value(response_metadata, "Location"),
            dict.get(response, "TaskMonitor") if type(response) is dict else None,
            dict.get(response, "@odata.id") if type(response) is dict else None,
        ]
        compatibility_task_uri = self._compose_task_resource_uri(dut_id, task_id)
        if compatibility_task_uri:
            candidates.append(compatibility_task_uri)

        # The anchor must be the host the request is actually sent to. It comes
        # from the connection info that builds the request URL; a host derived
        # from normalize_redfish_uri is always None because that helper returns
        # a path, which silently discarded every absolute candidate.
        expected_host = self._resolve_request_host(dut_id)

        selected: List[str] = []
        for candidate in candidates:
            if (
                type(candidate) is not str
                or len(candidate) > _DIAGNOSTIC_LOG_TEXT_MAX_CHARS
            ):
                continue
            candidate = candidate.strip()
            if not candidate or candidate in selected:
                continue
            if not validate_redfish_uri(candidate, expected_host=expected_host):
                continue
            if self._task_id_from_task_service_uri(dut_id, candidate) is None:
                continue
            selected.append(candidate)
        return selected

    @staticmethod
    def _is_task_monitor_uri(uri: Any) -> bool:
        """
        Compatibility delegate for TaskMonitor URI classification.

        After applying local validation, the function forwards ``uri`` to
        ``is_task_monitor_uri`` and preserves its return and exception contract.

        Args:
            uri: Validated remote resource identifier used for URI.

        Returns:
            Whether the compatibility delegate for TaskMonitor URI
            classification operation succeeds.
        """
        return is_task_monitor_uri(
            uri,
            max_text_chars=_DIAGNOSTIC_LOG_TEXT_MAX_CHARS,
        )

    def _normalize_task_monitor_response(
        self,
        response: Any,
        response_metadata: Any,
        monitor_uri: Any,
    ) -> Any:
        """
        Translate the HTTP TaskMonitor lifecycle into the task-shaped contract.

        A TaskMonitor returns HTTP 202 while the asynchronous operation is still
        running. When the operation finishes, it returns the original operation
        response instead of a Task resource, so that terminal response commonly
        has a Location or ``@odata.id`` but no ``TaskState``.

        Downstream dump resolution historically consumes a completed Task
        object. Preserve that contract by adding the inferred state and copying
        the safe terminal Location into ``Payload.HttpHeaders``.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            response_metadata: Response metadata consumed while the function
                attempts to translate the HTTP TaskMonitor lifecycle into the
                task-shaped contract.
            monitor_uri: Validated remote resource identifier used for monitor
                URI.

        Returns:
            The task monitor response value selected by the operation.
        """
        http_status = self._http_status_from_response(response, response_metadata)
        location = self._response_header_value(response_metadata, "Location")
        normalization = normalize_task_monitor_response(
            response,
            http_status=http_status,
            monitor_uri=monitor_uri,
            location=location,
            max_text_chars=_DIAGNOSTIC_LOG_TEXT_MAX_CHARS,
            max_headers=_DIAGNOSTIC_LOG_MAX_ITEMS,
        )
        if not normalization.applied:
            return normalization.response

        # Preserve the private facade's historical identity and mutation contract
        # while keeping policy evaluation itself side-effect free.
        if type(response) is dict:
            response.update(normalization.response)
            return response
        return normalization.response

    async def _wait_for_task_completion(
        self,
        dut_id: str,
        task_id: str,
        max_retries: int = 50,
        function_tag: str = "",
        entity_context: Dict[str, Any] = None,
        **kwargs,
    ) -> Optional[Dict[str, Any]]:
        """
        Wait for completion through the diagnostic orchestration boundary.

        After applying local validation, the function forwards ``dut_id``,
        ``task_id``, ``max_retries``, ``function_tag``, and ``entity_context``
        to ``_wait_for_task_completion`` and preserves its return and exception
        contract. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            task_id: Stable task identifier used to correlate configuration,
                logs, and results.
            max_retries: Upper bound enforced for max retries; the consuming
                boundary rejects or truncates values that exceed it.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            entity_context: Optional entity context; ``None`` selects the
                function's default behavior.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing wait for task completion, or ``None`` when the
            requested value is unavailable.
        """
        return await self._diagnostic_runner()._wait_for_task_completion(
            dut_id,
            task_id,
            max_retries=max_retries,
            function_tag=function_tag,
            entity_context=entity_context,
            **kwargs,
        )

