    @staticmethod
    def _split_path_tokens(path: str) -> List[Union[str, int]]:
        """
        Return the split path tokens.

        The implementation uses ``path`` to produce the split path tokens.

        Args:
            path: filesystem location used as the path for this operation.

        Returns:
            The split path tokens returned in operation-defined order.
        """
        if not path:
            return []

        tokens: List[Union[str, int]] = []
        buffer: List[str] = []
        i = 0
        length = len(path)

        while i < length:
            char = path[i]

            if char == "[":
                end_idx = path.find("]", i)
                if end_idx == -1:
                    buffer.append(char)
                    i += 1
                    continue

                # Flush current buffer as string token
                if buffer:
                    tokens.append("".join(buffer))
                    buffer.clear()

                index_str = path[i + 1 : end_idx]
                if index_str.isdigit():
                    tokens.append(int(index_str))

                i = end_idx + 1
                continue

            if char == ".":
                if buffer and "@" in buffer:
                    buffer.append(char)
                else:
                    if buffer:
                        tokens.append("".join(buffer))
                        buffer.clear()
                i += 1
                continue

            buffer.append(char)
            i += 1

        if buffer:
            tokens.append("".join(buffer))

        return tokens

    def _extract_nested_value(self, data: Any, path: Any) -> Any:
        """
        Extract nested value.

        The implementation uses ``data`` and ``path`` to extract nested value.

        Args:
            data: Data consumed while the function attempts to extract nested
                value.
            path: filesystem location used as the path for this operation.

        Returns:
            The validated ``current``.
        """
        if data is None or path is None:
            return None

        if isinstance(path, (list, tuple)):
            tokens = list(path)
        else:
            tokens = self._split_path_tokens(path)
        current: Any = data

        for token in tokens:
            if isinstance(token, int):
                if isinstance(current, list) and 0 <= token < len(current):
                    current = current[token]
                else:
                    return None
            else:
                if isinstance(current, dict) and token in current:
                    current = current[token]
                else:
                    return None

        return current

    @staticmethod
    def _resolve_placeholder(value: Any, context: Dict[str, Any]) -> Any:
        """
        Resolve simple ${var_name} placeholders using the provided context.

        The implementation uses ``value`` and ``context`` to resolve simple
        ${var_name} placeholders using the provided context.

        Args:
            value: Value object whose ``endswith`` and ``startswith`` state is
                read while performing simple ${var_name} placeholders using the
                provided context.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The placeholder value selected by the operation.
        """
        if isinstance(value, str):
            if value.startswith("${") and value.endswith("}"):
                key = value[2:-1]
                return context.get(key, value)
        return value

    def _get_dut_baseboard_name(self, dut_id: str) -> Optional[str]:
        """
        Helper to fetch baseboard name for a DUT.

        The implementation uses ``dut_id`` to helper to fetch baseboard name for
        a DUT.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            The canonical DUT baseboard name, or ``None`` when the requested
            value is unavailable.
        """
        try:
            dut = None
            if hasattr(self, "dut_manager") and self.dut_manager:
                dut = self.dut_manager.get_dut(dut_id)
            if dut and hasattr(dut, "config"):
                return dut.config.get("baseboard")

            # Fallback to DUT config lookup
            dut_config = (
                self.dut_manager.get_dut_config(dut_id)
                if hasattr(self, "dut_manager")
                else {}
            )
            return dut_config.get("baseboard")
        except Exception:
            return None

    async def _should_apply_dynamic_discovery(
        self,
        dut_id: str,
        collector_name: str,
        collector_id: str,
        function_tag: str,
        discovery_config: Dict[str, Any],
        collector_def: Optional[Dict[str, Any]] = None,
    ) -> Tuple[bool, Optional[str]]:
        """
        Determine whether a dynamic discovery entry should be applied for the DUT.

        Collector applicability is consulted only after ID/function filters,
        preserving the existing short-circuit and extension behavior.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            discovery_config: Discovery config governing dynamic discovery entry
                should be applied for the DUT.
            collector_def: Optional collector def; ``None`` selects the
                function's default behavior.

        Returns:
            A tuple containing ``success flag`` and ``baseboard name`` in that
            order.
        """
        baseboard_name = self._get_dut_baseboard_name(dut_id)
        policy = DiscoveryApplicabilityPolicy.from_config(discovery_config, None)
        decision = policy.evaluate_identity(
            collector_name=collector_name,
            collector_id=collector_id,
            function_tag=function_tag,
        )
        if not decision.applies:
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                decision.reason,
                dut_id,
            )
            return False, baseboard_name

        if not policy.apply_when:
            return True, baseboard_name

        # Collector applicability is consulted only after ID/function filters,
        # preserving the existing short-circuit and extension behavior.
        policy = DiscoveryApplicabilityPolicy.from_config(
            discovery_config,
            collector_def,
        )
        required_baseboards = policy.required_baseboards()
        resolved_baseboard_type = None
        matching_baseboard_groups: List[str] = []
        uses_collector_applicability = bool(
            policy.apply_when
            and policy.apply_when.get("use_applicable_baseboards")
            and required_baseboards
        )
        if uses_collector_applicability and baseboard_name:
            baseboard_manager = None
            if (
                hasattr(self, "dut_manager")
                and self.dut_manager
                and hasattr(self.dut_manager, "_get_baseboard_manager")
            ):
                baseboard_manager = self.dut_manager._get_baseboard_manager()

            if baseboard_manager:
                candidate_type = baseboard_manager.get_baseboard_type(baseboard_name)
                if isinstance(candidate_type, str):
                    resolved_baseboard_type = candidate_type

                required_values = (
                    [required_baseboards]
                    if isinstance(required_baseboards, str)
                    else list(required_baseboards)
                )
                normalized_baseboard = baseboard_name.strip().casefold()
                for required in required_values:
                    if not isinstance(required, str):
                        continue
                    members = baseboard_manager.get_baseboards_in_group(required)
                    if isinstance(members, list) and any(
                        isinstance(member, str)
                        and member.strip().casefold() == normalized_baseboard
                        for member in members
                    ):
                        matching_baseboard_groups.append(required)
            elif hasattr(self, "dut_manager") and self.dut_manager:
                dut_config = self.dut_manager.get_dut_config(dut_id)
                if isinstance(dut_config, dict):
                    candidate_type = dut_config.get("baseboard_type")
                    if isinstance(candidate_type, str):
                        resolved_baseboard_type = candidate_type

        decision = policy.evaluate_baseboards(
            collector_name=collector_name,
            baseboard_name=baseboard_name,
            required_baseboards=required_baseboards,
            baseboard_type=resolved_baseboard_type,
            matching_groups=matching_baseboard_groups,
        )
        if not decision.applies:
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                decision.reason,
                dut_id,
            )
            return False, baseboard_name

        baseboard_groups = policy.configured_baseboard_groups()
        if not baseboard_groups and policy.derives_applicable_baseboard_groups():
            derived_groups: List[str] = []
            baseboard_manager = None
            if (
                hasattr(self, "dut_manager")
                and self.dut_manager
                and hasattr(self.dut_manager, "_get_baseboard_manager")
            ):
                baseboard_manager = self.dut_manager._get_baseboard_manager()

            if baseboard_manager:
                for candidate in policy.applicable_baseboards:
                    group_name = baseboard_manager.get_baseboard_type(candidate)
                    if group_name:
                        derived_groups.append(group_name)

            if derived_groups:
                baseboard_groups = derived_groups

        decision = policy.evaluate_baseboard_groups(
            collector_name=collector_name,
            baseboard_name=baseboard_name,
            baseboard_type=None,
            required_groups=baseboard_groups,
        )
        if baseboard_groups and not baseboard_name:
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                decision.reason,
                dut_id,
            )
            return False, baseboard_name

        if baseboard_groups:
            baseboard_manager = None
            if (
                hasattr(self, "dut_manager")
                and self.dut_manager
                and hasattr(self.dut_manager, "_get_baseboard_manager")
            ):
                baseboard_manager = self.dut_manager._get_baseboard_manager()

            baseboard_type = None
            if baseboard_manager:
                baseboard_type = baseboard_manager.get_baseboard_type(baseboard_name)
            elif hasattr(self, "dut_manager") and self.dut_manager:
                dut_config = self.dut_manager.get_dut_config(dut_id)
                baseboard_type = dut_config.get("baseboard_type")

            decision = policy.evaluate_baseboard_groups(
                collector_name=collector_name,
                baseboard_name=baseboard_name,
                baseboard_type=baseboard_type,
                required_groups=baseboard_groups,
            )
            if not decision.applies:
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    decision.reason,
                    dut_id,
                )
                return False, baseboard_name

        return True, baseboard_name

    def _apply_discovered_value(
        self,
        current_value: Optional[Union[str, List[str]]],
        discovered_value: Optional[Union[str, List[str]]],
        behavior: str,
        deduplicate: bool = False,
    ) -> Optional[Union[str, List[str]]]:
        """
        Apply discovered value.

        After applying local validation, the function forwards
        ``current_value``, ``discovered_value``, ``behavior``, and
        ``deduplicate`` to ``apply_discovered_value`` and preserves its return
        and exception contract.

        Args:
            current_value: Entries supplied as ``current_value`` without
                transferring container ownership.
            discovered_value: Entries supplied as ``discovered_value`` without
                transferring container ownership.
            behavior: Text supplied as behavior in the format accepted by this
                function.
            deduplicate: Whether deduplicate is enabled or required for this
                operation.

        Returns:
            The canonical discovered value, or ``None`` when the requested value
            is unavailable.
        """
        return apply_discovered_value(
            current_value,
            discovered_value,
            behavior,
            deduplicate=deduplicate,
        )

    async def _perform_dynamic_uri_discovery(
        self,
        dut_id: str,
        collector_name: str,
        discovery_config: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Optional[Union[str, List[str]]]:
        """
        Execute a dynamic URI discovery workflow based on configuration.

        The implementation uses ``dut_id``, ``collector_name``,
        ``discovery_config``, and ``context`` to execute a dynamic URI discovery
        workflow based on configuration. Terminal status is emitted only after
        dynamic URI discovery workflow based on configuration and its owned
        cleanup have completed. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            discovery_config: Discovery config governing dynamic URI discovery
                workflow based on configuration.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The canonical perform dynamic URI discovery text, or ``None`` when
            the requested value is unavailable.
        """
        strategy = discovery_config.get("strategy", "registry_member")
        config_name = discovery_config.get("name") or strategy

        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"Starting dynamic URI discovery '{config_name}' using strategy '{strategy}'",
            dut_id,
        )

        if strategy != "registry_member":
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"Unsupported dynamic discovery strategy '{strategy}' for {collector_name}",
                dut_id,
            )
            return None

        base_uri = self._resolve_placeholder(
            discovery_config.get("base_uri", "/redfish/v1/Registries"), context
        )
        if not isinstance(base_uri, str) or not base_uri:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Dynamic discovery '{config_name}' missing valid base_uri",
                dut_id,
            )
            return None

        bypass_cache = discovery_config.get("bypass_cache", True)
        success, registries_data, _ = await self.dispatch_request(
            dut_id, "GET", base_uri, bypass_cache=bypass_cache
        )

        if not success or not isinstance(registries_data, dict):
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                (
                    f"Dynamic discovery '{config_name}' failed to fetch base URI {base_uri}: "
                    f"{registries_data}"
                ),
                dut_id,
            )
            return None

        members_path = discovery_config.get("members_path", "Members")
        members = (
            registries_data.get("Members")
            if members_path in (None, "", "Members")
            else self._extract_nested_value(registries_data, members_path)
        )

        if not isinstance(members, list):
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                (
                    f"Dynamic discovery '{config_name}' expected a list at path '{members_path}' "
                    f"but received {type(members).__name__}"
                ),
                dut_id,
            )
            return None

        match_field = discovery_config.get("match_field", "@odata.id")
        match_type = discovery_config.get("match_type", "contains").lower()
        match_value_config = discovery_config.get("match_value")
        match_values_config = discovery_config.get("match_values")

        resolved_match_values: List[str] = []
        if match_values_config:
            if isinstance(match_values_config, list):
                for val in match_values_config:
                    resolved = self._resolve_placeholder(val, context)
                    if isinstance(resolved, str):
                        resolved_match_values.append(resolved)
        elif match_value_config:
            resolved = self._resolve_placeholder(match_value_config, context)
            if isinstance(resolved, str):
                resolved_match_values.append(resolved)

        match_regex = discovery_config.get("match_regex")
        match_case_insensitive = discovery_config.get("case_insensitive", True)
        return_multiple = discovery_config.get("return_multiple", False)

        discovered_results: List[str] = []

        for member in members:
            if not isinstance(member, dict):
                continue

            candidate_value = self._extract_nested_value(member, match_field)
            if candidate_value is None:
                continue

            if not registry_member_matches(
                candidate_value,
                match_type=match_type,
                match_values=resolved_match_values,
                match_regex=match_regex,
                case_insensitive=match_case_insensitive,
            ):
                continue

            follow_up_config = discovery_config.get("follow_up")
            final_value: Optional[Union[str, List[str]]] = None

            if follow_up_config:
                request_path = follow_up_config.get("request_path", "@odata.id")
                request_uri = self._extract_nested_value(member, request_path)

                if not isinstance(request_uri, str):
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        (
                            f"Dynamic discovery '{config_name}' could not resolve follow-up URI "
                            f"using path '{request_path}'"
                        ),
                        dut_id,
                    )
                    continue

                request_method = follow_up_config.get("method", "GET").upper()
                follow_bypass_cache = follow_up_config.get("bypass_cache", True)

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    (
                        f"Dynamic discovery '{config_name}' follow-up request: "
                        f"{request_method} {request_uri}"
                    ),
                    dut_id,
                )

                follow_success, follow_data, _ = await self.dispatch_request(
                    dut_id,
                    request_method,
                    request_uri,
                    bypass_cache=follow_bypass_cache,
                )

                if not follow_success or not isinstance(follow_data, (dict, list)):
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        (
                            f"Dynamic discovery '{config_name}' follow-up request failed: "
                            f"{follow_data}"
                        ),
                        dut_id,
                    )
                    continue

                value_path = follow_up_config.get("value_path")
                if value_path:
                    final_value = self._extract_nested_value(follow_data, value_path)
                else:
                    final_value = follow_data
            else:
                value_path = discovery_config.get("value_path", match_field)
                final_value = self._extract_nested_value(member, value_path)

            if isinstance(final_value, list) and not final_value:
                final_value = None

            if final_value is None:
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    (
                        f"Dynamic discovery '{config_name}' matched entry but could not extract "
                        f"final value using configured paths."
                    ),
                    dut_id,
                )
                continue

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Dynamic discovery '{config_name}' produced value: {final_value}",
                dut_id,
            )

            discovered_results.append(final_value)  # type: ignore[arg-type]

            if not return_multiple:
                break

        if not discovered_results:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"Dynamic discovery '{config_name}' did not yield any results",
                dut_id,
            )
            return None

        if return_multiple:
            return flatten_discovery_results(discovered_results)

        return discovered_results[0]

    async def _get_dut_config(self, dut_id: str) -> Dict[str, Any]:
        """
        Get DUT configuration from the DUT manager.

        The implementation uses ``dut_id`` to get DUT configuration from the DUT
        manager. Owned asynchronous work is awaited before return, so completion
        does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            A mapping containing DUT config.
        """
        try:
            if hasattr(self, "dut_manager") and self.dut_manager:
                return self.dut_manager.get_dut_config(dut_id)
            return {}
        except Exception as e:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Failed to get DUT config: {str(e)}",
                dut_id,
            )
            return {}

    async def _build_redfish_time_filter(self, dut_id: str) -> str:
        """
        Build Redfish time filter.

        The implementation uses ``dut_id`` to build Redfish time filter. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            The canonical Redfish time filter text.
        """
        if not self.orchestrator or not self.orchestrator.config_manager:
            return ""
        try:
            tool_config = self.orchestrator.config_manager.get_tool_config()
            if not tool_config.get("streaming_only", False):
                return ""

            stream_begin, stream_end = normalize_stream_window(
                tool_config.get("stream_begin", "24"),
                tool_config.get("stream_end", "0"),
            )
            filter_expression = (
                f"Created ge '{format_redfish_stream_timestamp(stream_begin)}' and "
                f"Created le '{format_redfish_stream_timestamp(stream_end)}'"
            )
            return "$filter=" + quote(filter_expression, safe="'():,-.")
        except Exception as e:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"Failed to build time filter: {e}",
                dut_id,
            )
            return ""

    async def _append_streaming_time_filter(self, dut_id: str, uri: str) -> str:
        """
        Append the normalized Redfish time filter to a URI.

        The implementation uses ``dut_id`` and ``uri`` to append the normalized
        Redfish time filter to a URI. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri: Validated remote resource identifier used for URI.

        Returns:
            The canonical append streaming time filter text.
        """
        time_filter = await self._build_redfish_time_filter(dut_id)
        if not time_filter:
            return uri
        separator = "&" if "?" in uri else "?"
        return f"{uri}{separator}{time_filter}"

    def _extract_entity_id_from_uri(
        self, uri: str, entity_type: Optional[str] = None
    ) -> Union[Dict[str, str], str]:
        """
        Extract entity identifiers from a Redfish URI.

        Behavior:

        - If entity_type is provided, return a single ID string for that entity
          type (e.g., "Chassis" -> chassis_id string). Falls back to "unknown"
          if not found.
        - If entity_type is None, return a dict mapping known entity
          placeholders to IDs using ENTITY_URI_TO_PLACEHOLDER.

        Args:
            uri: Validated remote resource identifier used for URI.
            entity_type: Optional entity type; ``None`` selects the function's
                default behavior.

        Returns:
            The canonical entity identifier from URI text.
        """
        # When a specific entity type is requested, return a single ID string
        if entity_type:
            # Handle common Redfish entity collections explicitly
            if entity_type in ("Chassis", "Systems", "Managers"):
                token = f"/{entity_type}/"
                if token in uri:
                    parts = uri.split(token)
                    if len(parts) > 1:
                        entity_id = parts[1].split("/")[0]
                        if entity_id:
                            return entity_id

            # Generic fallback: find the segment after the entity type
            uri_parts = uri.split("/")
            for i, part in enumerate(uri_parts):
                if part.lower() == entity_type.lower() and i + 1 < len(uri_parts):
                    return uri_parts[i + 1]

            # If all else fails, return a default string
            return "unknown"

        # No entity_type: return a dict mapping placeholders to IDs
        entity_ids: Dict[str, str] = {}

        for entity_path, entity_var in ENTITY_URI_TO_PLACEHOLDER.items():
            if entity_path in uri:
                # Extract ID from URI (e.g., /Chassis/HGX_GPU_0/... -> HGX_GPU_0)
                parts = uri.split(entity_path)
                if len(parts) > 1:
                    # Get the part after entity_path and extract the ID
                    remaining = parts[1]
                    entity_id = remaining.split("/")[0]
                    if entity_id:
                        entity_ids[entity_var] = entity_id

        return entity_ids

    async def _log_collection_start(self, dut_id: str, collection_type: str, uri: str):
        """
        Log collection start.

        The implementation uses ``dut_id``, ``collection_type``, and ``uri`` to
        log collection start. Owned asynchronous work is awaited before return,
        so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collection_type: Text supplied as collection type in the format
                accepted by this function.
            uri: Validated remote resource identifier used for URI.
        """
        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"Starting {collection_type} collection from: {uri}",
            dut_id,
        )

