    async def _get_log_service_uris_legacy(
        self, dut_id: str, entity_type: str, log_service_filter: Dict[str, Any]
    ) -> List[str]:
        """
        Get log service URIs for legacy platforms.

        The implementation uses ``dut_id``, ``entity_type``, and
        ``log_service_filter`` to get log service URIs for legacy platforms.
        Owned asynchronous work is awaited before return, so completion does not
        leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service_filter: Mapping supplying fields for get log service
                URIs for legacy platforms.

        Returns:
            The log service URIs legacy returned in operation-defined order.
        """
        try:
            # Get entities first
            entity_uri = self.get_configured_uri(dut_id, entity_type)
            success, entities_response, _ = await self.dispatch_request(
                dut_id, "GET", entity_uri
            )

            if not success:
                return []

            entities = entities_response.get("Members", [])
            log_service_uris = []

            for entity in entities:
                entity_id = entity.get("@odata.id", "").split("/")[-1]

                # Get log services for this entity
                entity_base_uri = self.get_configured_uri(dut_id, entity_type)
                log_services_uri = f"{entity_base_uri}/{entity_id}/LogServices"
                success, log_services_response, _ = await self.dispatch_request(
                    dut_id, "GET", log_services_uri
                )

                if success:
                    log_services = log_services_response.get("Members", [])

                    for log_service in log_services:
                        service_id = log_service.get("@odata.id", "").split("/")[-1]

                        # Check if this service matches the filter
                        id_contains = log_service_filter.get("id_contains", [])
                        if isinstance(id_contains, dict):
                            id_contains = id_contains.get("anyOf", [])

                        if any(contains in service_id for contains in id_contains):
                            entity_base_uri = self.get_configured_uri(
                                dut_id, entity_type
                            )
                            entries_uri = f"{entity_base_uri}/{entity_id}/LogServices/{service_id}/Entries"
                            log_service_uris.append(entries_uri)

            return log_service_uris

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Failed to get legacy log service URIs: {str(e)}",
                dut_id,
            )
            return []

    async def _resolve_source_log_directory(
        self,
        dut_id: str,
        source_logs: str,
        processing_config: Optional[Dict[str, Any]] = None,
        collector_id: str = "",
        collector_name: str = "",
        warn_if_missing: bool = True,
    ) -> Optional[_OpenedSourceLogDirectory]:
        """
        Resolve the artifact directory used by a derived log collector.

        The implementation uses ``dut_id``, ``source_logs``,
        ``processing_config``, ``collector_id``, and ``collector_name`` to
        resolve the artifact directory used by a derived log collector. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind. Filesystem effects remain confined to the
        caller-selected paths and the owning resource lifecycle. If the function
        cannot resolve the artifact directory used by a derived log collector,
        its exception reaches the caller instead of being converted into a
        successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            source_logs: Text supplied as source logs in the format accepted by
                this function.
            processing_config: Optional Processing config governing artifact
                directory used by a derived log collector.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            warn_if_missing: Whether warn if missing is enabled or required for
                this operation.

        Returns:
            The validated ``opened_source``, or ``None`` when no value
            qualifies.

        Raises:
            _SourceLogPolicyError: If source artifact directory could not be
                opened safely.
        """
        output_dir = await self._get_output_directory(dut_id)
        if not output_dir:
            if warn_if_missing:
                await self._log_runtime(
                    "WARN",
                    "RedfishService",
                    "Output directory unavailable; source logs cannot be reused",
                    dut_id,
                )
            return None

        if output_dir == "/tmp":
            await self._log_runtime(
                "WARN",
                "RedfishService",
                "Using fallback output directory, may not find expected files",
                dut_id,
            )

        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"Current working directory: {os.getcwd()}, output_dir: {output_dir}",
            dut_id,
        )

        # Configured source directories must win over the current collector
        # directory, which may already exist but contain no source artifacts.
        configured_dirs = (
            processing_config.get("possible_source_directories")
            if processing_config
            else None
        )
        defaults: List[str] = []
        if collector_id and collector_name:
            defaults.append(f"Redfish_{collector_id}_{collector_name}")
        defaults.extend(
            [
                f"Redfish_{source_logs}",
                f"Redfish_{source_logs.replace('_', '')}",
            ]
        )
        possible_source_dirs = _source_log_directory_candidates(
            configured_dirs,
            defaults=defaults,
        )
        dut_component = _source_log_directory_component(
            dut_id,
            field_name="DUT identifier",
        )
        full_source_dirs = [
            Path(output_dir) / dut_component / "redfish" / source_dir
            for source_dir in possible_source_dirs
        ]
        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"Looking for source logs in directories: {full_source_dirs}",
            dut_id,
        )

        for full_dir in full_source_dirs:
            try:
                opened_source = _open_source_log_directory_no_links(full_dir)
            except FileNotFoundError:
                continue
            except _SourceLogPolicyError:
                raise
            except OSError as error:
                raise _SourceLogPolicyError(
                    "source artifact directory could not be opened safely"
                ) from error
            else:
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Found source log directory: {full_dir}",
                    dut_id,
                )
                return opened_source

        if warn_if_missing:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Source log directory not found. Tried: {possible_source_dirs}",
                dut_id,
            )
        return None

    @staticmethod
    def _is_source_event_log_filename(filename: str) -> bool:
        """
        Return whether a source artifact can contain EventLog members.

        The implementation uses ``filename`` to determine whether a source
        artifact can contain EventLog members.

        Args:
            filename: Text supplied as filename in the format accepted by this
                function.

        Returns:
            Whether a source artifact can contain EventLog members.
        """
        lowered = filename.lower()
        return (
            lowered.endswith(".json")
            and "_additional_data" not in lowered
            and "eventlog" in lowered
        )

    def _source_collector_terminal_no_data(
        self,
        dut_id: str,
        processing_config: Optional[Dict[str, Any]],
    ) -> bool:
        """
        Return whether a configured source collector proved an empty data set.

        Reuse is opt-in and accepts only the structured terminal state stored by
        the run logger. Free-form reason text, filesystem status projections,
        and failed or incomplete source results never suppress fallback I/O.

        Args:
            dut_id: Stable DUT identifier used to correlate the source result.
            processing_config: Optional derived-collector policy containing the
                source collector identifier and no-data reuse opt-in.

        Returns:
            Whether the same run recorded a trusted expected-no-data result for
            the configured source collector.
        """

        if (
            not isinstance(processing_config, dict)
            or processing_config.get("reuse_source_terminal_no_data") is not True
        ):
            return False
        source_collector = processing_config.get("source_collector")
        if (
            not isinstance(source_collector, str)
            or not source_collector
            or source_collector != source_collector.strip()
            or ":" in source_collector
            or len(source_collector.encode("utf-8", errors="surrogateescape")) > 255
        ):
            return False

        logger = getattr(self, "logger", None)
        collector_results = getattr(logger, "collector_results", None)
        if not isinstance(collector_results, dict):
            return False
        source_result = collector_results.get(f"{dut_id}:{source_collector}")
        if (
            not isinstance(source_result, dict)
            or source_result.get("status") != "skipped"
        ):
            return False
        if source_result.get("failure_category") not in {None, ""}:
            return False

        context = source_result.get("context")
        if not isinstance(context, dict):
            return False
        error_messages = context.get("error_messages", [])
        return (
            context.get("classification") == "expected_no_data"
            and context.get("no_data_collected") is True
            and context.get("intentional_evidence_only_skip") is True
            and context.get("failure_category") in {None, ""}
            and isinstance(error_messages, list)
            and not error_messages
        )

    async def _source_log_artifacts_available(
        self,
        dut_id: str,
        source_logs: str,
        processing_config: Optional[Dict[str, Any]] = None,
        collector_id: str = "",
        collector_name: str = "",
        source_read_budget: Optional[_SourceLogReadBudget] = None,
    ) -> bool:
        """
        Return whether a prior collector produced a usable EventLog artifact.

        The implementation uses ``dut_id``, ``source_logs``,
        ``processing_config``, ``collector_id``, and ``collector_name`` to
        determine whether a prior collector produced a usable EventLog artifact.
        Owned asynchronous work is awaited before return, so completion does not
        leave an unobserved task behind. Cleanup in the ``finally`` path runs
        for successful, failed, and cancelled execution.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            source_logs: Text supplied as source logs in the format accepted by
                this function.
            processing_config: Optional Processing config governing prior
                collector produced a usable EventLog artifact.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            source_read_budget: Optional source read budget; ``None`` selects
                the function's default behavior.

        Returns:
            Whether a prior collector produced a usable EventLog artifact.
        """
        budget = source_read_budget or self._new_source_log_read_budget(dut_id)
        source_log_dir: Optional[_OpenedSourceLogDirectory] = None
        try:
            source_log_dir = await self._resolve_source_log_directory(
                dut_id,
                source_logs,
                processing_config,
                collector_id,
                collector_name,
                warn_if_missing=False,
            )
            if not source_log_dir:
                return False

            source_paths = _list_source_log_files_bounded(
                source_log_dir,
                maximum_entries=self.MAX_SOURCE_LOG_FILES,
            )
            paths_by_name = {path.name: path for path in source_paths}
            status_path = paths_by_name.get("status.json")
            if status_path is not None:
                try:
                    source_status = _read_source_log_json(
                        status_path,
                        budget=budget,
                        source_log_dir=source_log_dir,
                    )
                    if isinstance(source_status, list) and source_status:
                        source_status = source_status[-1]
                    status_value = (
                        source_status.get("status")
                        if isinstance(source_status, dict)
                        else None
                    )
                    if status_value and str(status_value).lower() not in {
                        "success",
                        "degraded",
                        "complete",
                        "completed",
                    }:
                        return False
                except _SourceLogJSONError:
                    return False

            for source_path in source_paths:
                if not self._is_source_event_log_filename(source_path.name):
                    continue
                try:
                    source_data = _read_source_log_json(
                        source_path,
                        budget=budget,
                        source_log_dir=source_log_dir,
                    )
                except _SourceLogJSONError:
                    continue
                if isinstance(source_data, dict) and isinstance(
                    source_data.get("Members"), list
                ):
                    return True
            return False
        except _SourceLogPolicyError:
            raise
        except Exception as exc:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Unable to inspect source log artifacts: {exc}",
                dut_id,
            )
            return False
        finally:
            if source_log_dir is not None:
                source_log_dir.close()

    async def _load_source_additional_data_cache(
        self,
        dut_id: str,
        source_logs: str,
        processing_config: Optional[Dict[str, Any]] = None,
        collector_id: str = "",
        collector_name: str = "",
        requested_uris: Optional[List[str]] = None,
        source_read_budget: Optional[_SourceLogReadBudget] = None,
    ) -> Dict[str, bytes]:
        """
        Load requested non-empty attachments persisted by a source collector.

        The implementation uses ``dut_id``, ``source_logs``,
        ``processing_config``, ``collector_id``, and ``collector_name`` to load
        requested non-empty attachments persisted by a source collector. Parsing
        or I/O must finish before the validated representation is made available
        to the caller. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind. If the function
        cannot load requested non-empty attachments persisted by a source
        collector, its exception reaches the caller instead of being converted
        into a successful result. Cleanup in the ``finally`` path runs for
        successful, failed, and cancelled execution.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            source_logs: Text supplied as source logs in the format accepted by
                this function.
            processing_config: Optional Processing config governing requested
                non-empty attachments persisted by a source collector.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            requested_uris: Validated remote resource identifier used for
                requested URIs.
            source_read_budget: Optional source read budget; ``None`` selects
                the function's default behavior.

        Returns:
            A mapping containing source additional data cache.

        Raises:
            _SourceLogPolicyError: If requested source attachment URI limit
                exceeded; canonical source attachment failed base64 decoding; or
                source attachment decoded size changed unexpectedly.
        """
        cached_attachments: Dict[str, bytes] = {}
        budget = source_read_budget or self._new_source_log_read_budget(dut_id)
        source_log_dir: Optional[_OpenedSourceLogDirectory] = None
        requested_uri_set: Optional[set[str]] = None
        if requested_uris is not None:
            requested_uri_set = set()
            for uri in requested_uris:
                if not uri:
                    continue
                if len(requested_uri_set) >= self.MAX_SOURCE_LOG_RETAINED_ENTRIES:
                    raise _SourceLogPolicyError(
                        "requested source attachment URI limit exceeded"
                    )
                requested_uri_set.add(str(uri))
        try:
            source_log_dir = await self._resolve_source_log_directory(
                dut_id,
                source_logs,
                processing_config,
                collector_id,
                collector_name,
                warn_if_missing=False,
            )
            if not source_log_dir:
                return cached_attachments

            source_paths = _list_source_log_files_bounded(
                source_log_dir,
                maximum_entries=self.MAX_SOURCE_LOG_FILES,
            )
            for source_path in source_paths:
                lowered = source_path.name.lower()
                if not lowered.endswith(".json") or "_additional_data" not in lowered:
                    continue
                try:
                    serialized_attachments = _read_source_log_json(
                        source_path,
                        budget=budget,
                        source_log_dir=source_log_dir,
                    )
                except _SourceLogJSONError:
                    continue
                if not isinstance(serialized_attachments, dict):
                    continue

                for uri, envelope in serialized_attachments.items():
                    budget.reserve_scanned_item()
                    if not isinstance(uri, str) or not isinstance(envelope, dict):
                        continue
                    if requested_uri_set is not None and uri not in requested_uri_set:
                        continue
                    if uri in cached_attachments:
                        continue
                    if envelope.get("encoding") != "base64" or not isinstance(
                        envelope.get("value"), str
                    ):
                        continue
                    encoded = envelope["value"]
                    decoded_size = _canonical_base64_decoded_size(encoded)
                    if decoded_size is None or decoded_size <= 0:
                        continue
                    expected_length = envelope.get("length")
                    if (
                        isinstance(expected_length, int)
                        and not isinstance(expected_length, bool)
                        and expected_length != decoded_size
                    ):
                        continue
                    budget.reserve_attachment(decoded_size)
                    try:
                        payload = base64.b64decode(encoded, validate=True)
                    except (binascii.Error, ValueError, TypeError):
                        raise _SourceLogPolicyError(
                            "canonical source attachment failed base64 decoding"
                        )
                    if len(payload) != decoded_size:
                        raise _SourceLogPolicyError(
                            "source attachment decoded size changed unexpectedly"
                        )
                    cached_attachments[uri] = payload

            if cached_attachments:
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Loaded {len(cached_attachments)} cached source attachments",
                    dut_id,
                )
            return cached_attachments
        except _SourceLogPolicyError:
            raise
        except Exception as exc:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Unable to load cached source attachments: {exc}",
                dut_id,
            )
            return cached_attachments
        finally:
            if source_log_dir is not None:
                source_log_dir.close()

    async def _find_filtered_entries_in_source_logs(
        self,
        dut_id: str,
        source_logs: str,
        entry_filter: Dict[str, Any],
        processing_config: Dict[str, Any] = None,
        collector_id: str = "",
        collector_name: str = "",
        source_read_budget: Optional[_SourceLogReadBudget] = None,
    ) -> List[Dict[str, Any]]:
        """
        Find filtered entries in source log files.

        Process each JSON file that looks like a log file.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            source_logs: Text supplied as source logs in the format accepted by
                this function.
            entry_filter: Mapping supplying fields for find filtered entries in
                source log files.
            processing_config: Optional Processing config governing find
                filtered entries in source log files.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            source_read_budget: Optional source read budget; ``None`` selects
                the function's default behavior.

        Returns:
            The filtered entries in source logs returned in operation-defined
            order.
        """
        budget = source_read_budget or self._new_source_log_read_budget(dut_id)
        source_log_dir: Optional[_OpenedSourceLogDirectory] = None
        try:
            source_log_dir = await self._resolve_source_log_directory(
                dut_id,
                source_logs,
                processing_config,
                collector_id,
                collector_name,
            )
            if not source_log_dir:
                return []

            all_filtered_entries = []

            source_paths = _list_source_log_files_bounded(
                source_log_dir,
                maximum_entries=self.MAX_SOURCE_LOG_FILES,
            )

            # Process each JSON file that looks like a log file
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Found {len(source_paths)} source files to process",
                dut_id,
            )

            # The pagination flow saves both an initial response and page files.
            # The initial response can be byte-for-byte identical to page 1, so
            # do not process it when a page for the same entity is present.
            paged_entity_ids = set()
            for source_path in source_paths:
                page_match = re.search(
                    r"_eventlog_(.+?)_page\d+(?:_|\.json)",
                    source_path.name.lower(),
                )
                if page_match:
                    paged_entity_ids.add(page_match.group(1))

            seen_entry_ids = set()
            for source_path in source_paths:
                filename = source_path.name
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Processing source file: {filename}",
                    dut_id,
                )

                if not self._is_source_event_log_filename(filename):
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Skipping {filename}: not an EventLog JSON source file",
                        dut_id,
                    )
                    continue

                initial_metadata_match = re.search(
                    r"_initial_metadata_(.+)\.json$", filename.lower()
                )
                if (
                    initial_metadata_match
                    and initial_metadata_match.group(1) in paged_entity_ids
                ):
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Skipping {filename}: matching paginated event log exists",
                        dut_id,
                    )
                    continue

                try:
                    log_data = _read_source_log_json(
                        source_path,
                        budget=budget,
                        source_log_dir=source_log_dir,
                    )

                    # Validate basic JSON structure
                    if not isinstance(log_data, dict) or "Members" not in log_data:
                        continue

                    if not isinstance(log_data["Members"], list):
                        continue

                    # Filter entries based on criteria
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Processing {len(log_data['Members'])} entries from {filename}",
                        dut_id,
                    )

                    for entry in log_data["Members"]:
                        budget.reserve_scanned_item()
                        if not isinstance(entry, dict):
                            continue
                        if self._entry_matches_filter(entry, entry_filter):
                            odata_id = entry.get("@odata.id")
                            entry_id = entry.get("Id")
                            stable_id = None
                            if odata_id not in (None, ""):
                                stable_id = ("odata", str(odata_id))
                            elif entry_id not in (None, ""):
                                page_scope_match = re.search(
                                    r"_eventlog_(.+?)_page\d+",
                                    filename,
                                    re.IGNORECASE,
                                )
                                metadata_scope_match = re.search(
                                    r"_eventlog_initial_metadata_(.+?)\.json$",
                                    filename,
                                    re.IGNORECASE,
                                )
                                scope_match = page_scope_match or metadata_scope_match
                                source_scope = (
                                    scope_match.group(1) if scope_match else filename
                                )
                                stable_id = ("id", source_scope, str(entry_id))

                            if stable_id is not None:
                                if stable_id in seen_entry_ids:
                                    continue
                                seen_entry_ids.add(stable_id)
                            budget.reserve_retained_entry()
                            all_filtered_entries.append(entry)
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"Found matching entry with ID: {entry.get('Id', 'unknown')}",
                                dut_id,
                            )

                except _SourceLogPolicyError:
                    raise
                except _SourceLogJSONError as e:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        f"Error processing source log file {filename}: {str(e)}",
                        dut_id,
                    )
                    continue

            return all_filtered_entries

        except _SourceLogPolicyError:
            raise
        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Failed to find filtered entries in source logs: {str(e)}",
                dut_id,
            )
            return []
        finally:
            if source_log_dir is not None:
                source_log_dir.close()

    def _entry_matches_filter(
        self, entry: Dict[str, Any], entry_filter: Dict[str, Any]
    ) -> bool:
        """
        Check if an entry matches the filter criteria.

        Supports multiple filter types:

        - "exists": Check if field exists and is not None/empty.
        - "equals": Exact value match (default).
        - "contains": String contains match.
        - "regex": Regular expression match.
        - "in": Value is in list.
        - "not_in": Value is not in list.
        - "greater_than": Numeric comparison.
        - "less_than": Numeric comparison.
        - "greater_than_equal": Numeric comparison.
        - "less_than_equal": Numeric comparison.

        Args:
            entry: Mapping supplying fields for if an entry matches the filter
                criteria.
            entry_filter: Mapping supplying fields for if an entry matches the
                filter criteria.

        Returns:
            Whether the if an entry matches the filter criteria operation
            succeeds.
        """
        try:
            for filter_key, filter_config in entry_filter.items():
                entry_value = entry.get(filter_key)

                # Handle simple string value (backward compatibility)
                if isinstance(filter_config, str):
                    if filter_config == "exists":
                        # Check if the field exists and is not None/empty
                        if entry_value is None or entry_value == "":
                            return False
                    else:
                        # Exact value match (default behavior)
                        if entry_value != filter_config:
                            return False
                    continue

                # Handle filter object with operator
                if isinstance(filter_config, dict):
                    operator = filter_config.get("operator", "equals")
                    value = filter_config.get("value")

                    if operator == "exists":
                        if entry_value is None or entry_value == "":
                            return False
                    elif operator == "equals":
                        if entry_value != value:
                            return False
                    elif operator == "contains":
                        if not isinstance(entry_value, str) or value not in entry_value:
                            return False
                    elif operator == "regex":
                        if not isinstance(entry_value, str) or not re.search(
                            value, entry_value
                        ):
                            return False
                    elif operator == "in":
                        if entry_value not in value:
                            return False
                    elif operator == "not_in":
                        if entry_value in value:
                            return False
                    elif operator == "greater_than":
                        if (
                            not isinstance(entry_value, (int, float))
                            or entry_value <= value
                        ):
                            return False
                    elif operator == "less_than":
                        if (
                            not isinstance(entry_value, (int, float))
                            or entry_value >= value
                        ):
                            return False
                    elif operator == "greater_than_equal":
                        if (
                            not isinstance(entry_value, (int, float))
                            or entry_value < value
                        ):
                            return False
                    elif operator == "less_than_equal":
                        if (
                            not isinstance(entry_value, (int, float))
                            or entry_value > value
                        ):
                            return False
                    else:
                        # Unknown operator, default to exact match
                        if entry_value != value:
                            return False
                else:
                    # Fallback to exact match
                    if entry_value != filter_config:
                        return False

            return True

        except Exception:
            return False

    async def _execute_fallback_collection(
        self,
        dut_id: str,
        fallback_config: Dict[str, Any],
        function_tag: str,
        processing_config: Dict[str, Any] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Execute fallback collection when source logs are not found.

        The implementation uses ``dut_id``, ``fallback_config``,
        ``function_tag``, ``processing_config``, and ``kwargs`` to execute
        fallback collection when source logs are not found. Terminal status is
        emitted only after fallback collection when source logs are not found
        and its owned cleanup have completed. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            fallback_config: Fallback config governing fallback collection when
                source logs are not found.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            processing_config: Optional Processing config governing fallback
                collection when source logs are not found.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing execute fallback collection.
        """
        try:
            owner_collector = kwargs.get("collector_id")
            if not isinstance(owner_collector, str) or not owner_collector.strip():
                reason = "collector_id is required for fallback artifact ownership"
                await self._log_runtime("ERROR", "RedfishService", reason, dut_id)
                return {"success": False, "reason": reason, "output_files": []}
            owner_collector = owner_collector.strip()

            source_collector = (processing_config or {}).get("source_collector")
            if not isinstance(source_collector, str) or not source_collector.strip():
                reason = (
                    "processing_config.source_collector is required for fallback "
                    "source resolution"
                )
                await self._log_runtime("ERROR", "RedfishService", reason, dut_id)
                return {"success": False, "reason": reason, "output_files": []}
            source_collector = source_collector.strip()

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Executing fallback collection: {fallback_config.get('collection_type', 'unknown')}",
                dut_id,
            )

            # Extract fallback configuration
            collection_type = fallback_config.get("collection_type", "paginated")
            entity_type = fallback_config.get("entity_type", "Systems")
            log_service = fallback_config.get("log_service", "EventLog")
            fallback_function_tag = fallback_config.get(
                "function_tag", "fallback_collection"
            )
            additional_data_callback = fallback_config.get(
                "additional_data_callback", False
            )
            additional_data_pattern = fallback_config.get("additional_data_pattern", "")
            collection_level_handling = fallback_config.get(
                "collection_level_handling", {}
            )
            output_pattern = fallback_config.get("output_pattern", "")

            # Execute the fallback collection using the unified function
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Fallback collection: function_tag='{fallback_function_tag}', entity_type='{entity_type}', log_service='{log_service}'",
                dut_id,
            )
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Fallback collection config: {fallback_config}",
                dut_id,
            )
            # The collector that requested the fallback owns every resulting
            # artifact. ``source_collector`` identifies the data source only;
            # using it as the owner caused R21 CPER fallbacks to leak into R1.
            fallback_config_with_id = fallback_config.copy()
            fallback_config_with_id["collector_id"] = owner_collector
            if owner_collector != source_collector:
                owner_function_tag = (
                    f"Redfish_{owner_collector}_{function_tag}_fallback"
                )
                fallback_config_with_id["function_tag"] = owner_function_tag
                source_prefix = f"Redfish_{source_collector}_"
                owner_prefix = f"{owner_function_tag}_"
                for pattern_key in ("output_pattern", "additional_data_pattern"):
                    pattern = fallback_config_with_id.get(pattern_key)
                    if isinstance(pattern, str) and pattern.startswith(source_prefix):
                        fallback_config_with_id[pattern_key] = (
                            owner_prefix + pattern[len(source_prefix) :]
                        )

            return await self.collect_redfish_unified(dut_id, **fallback_config_with_id)

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Fallback collection failed: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "reason": f"Fallback collection failed: {str(e)}",
                "output_files": [],
            }

