    def _apply_diagnostic_concurrency_scope(
        self,
        dut_id: str,
        collector_id: Any,
        diagnostic_concurrency: Any,
        target_baseboard: Any,
        kwargs: Dict[str, Any],
    ) -> None:
        """
        Install one catalog-authorized internal diagnostic lifecycle scope.

        The scope is derived only from validated catalog metadata and the
        concrete DUT baseboard. Direct Redfish routes may receive an isolated
        collector scope so firmware-compatible dump types can overlap. Shared
        HMC routes retain the existing physical-endpoint lock and therefore
        discard the scope.

        Args:
            dut_id: Stable DUT identifier used for platform and HMC resolution.
            collector_id: Collector identity included in the isolated scope.
            diagnostic_concurrency: Optional catalog concurrency profile.
            target_baseboard: Optional concrete baseboard already resolved by
                the calling diagnostic hook.
            kwargs: Mutable internal arguments forwarded to the diagnostic
                runner.

        Raises:
            ValueError: If an explicit catalog profile is malformed.

        Side Effects:
            Replaces or removes ``_diagnostic_domain_scope`` in ``kwargs``.
        """

        kwargs.pop("_diagnostic_domain_scope", None)
        if diagnostic_concurrency in (None, "", {}):
            return

        baseboard_name = target_baseboard
        if not isinstance(baseboard_name, str) or not baseboard_name.strip():
            dut_config = self.dut_manager.get_dut_config(dut_id)
            if isinstance(dut_config, Mapping):
                baseboard_name = dut_config.get("baseboard")
            else:
                baseboard_name = getattr(dut_config, "baseboard", None)

        baseboard_manager = None
        manager_getter = getattr(self.dut_manager, "_get_baseboard_manager", None)
        if callable(manager_getter):
            baseboard_manager = manager_getter()
        bounded_collector_id = str(collector_id)[:128]
        diagnostic_cohort = resolve_redfish_diagnostic_concurrency_cohort(
            diagnostic_concurrency,
            baseboard_name=baseboard_name,
            baseboard_manager=baseboard_manager,
            context=f"collector {bounded_collector_id}",
        )
        shared_hmc_key = self._hmc_diagnostic_lock_key(dut_id)
        if diagnostic_cohort is not None and not (
            isinstance(shared_hmc_key, str) and shared_hmc_key
        ):
            kwargs["_diagnostic_domain_scope"] = (
                f"{diagnostic_cohort}:{bounded_collector_id}"
            )

    @staticmethod
    def _diagnostic_task_uri(
        entity_type: str,
        entity_id: str,
        log_service: str,
        *,
        use_actions_segment: bool = True,
    ) -> str:
        """
        Build the one shared diagnostic-task URI boundary, including R43.

        The implementation uses ``entity_type``, ``entity_id``, ``log_service``,
        and ``use_actions_segment`` to build the one shared diagnostic-task URI
        boundary, including R43.

        Args:
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            log_service: Text supplied as log service in the format accepted by
                this function.
            use_actions_segment: Whether use actions segment is enabled or
                required for this operation.

        Returns:
            The canonical diagnostic task URI text.
        """
        action_path = (
            "Actions/LogService.CollectDiagnosticData"
            if use_actions_segment
            else "LogService.CollectDiagnosticData"
        )
        return f"{entity_type}/{entity_id}/LogServices/{log_service}/{action_path}"

