    async def _process_entities_common(
        self, dut_id: str, entities: Dict[str, Any], processor_func, **kwargs
    ) -> List[Any]:
        """
        Common entity processing loop (DRY pattern).

        The implementation uses ``dut_id``, ``entities``, ``processor_func``,
        and ``kwargs`` to common entity processing loop (DRY pattern). Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entities: Mapping supplying fields for common entity processing loop
                (DRY pattern).
            processor_func: Processor func consumed while the function attempts
                to common entity processing loop (DRY pattern).
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            The validated ``results``.
        """
        results = []
        for entity in entities.get("Members", []):
            entity_id = entity.get("@odata.id", "").split("/")[-1]
            result = await processor_func(dut_id, entity_id, **kwargs)
            results.append(result)
        return results

    def _get_skip_amount(
        self,
        collection_level: str,
        collection_level_handling: Optional[Dict[str, Any]] = None,
    ) -> int:
        """
        Common collection level skip amount calculator (DRY pattern).

        The implementation uses ``collection_level`` and
        ``collection_level_handling`` to common collection level skip amount
        calculator (DRY pattern).

        Args:
            collection_level: Text supplied as collection level in the format
                accepted by this function.
            collection_level_handling: Optional collection level handling;
                ``None`` selects the function's default behavior.

        Returns:
            The numeric skip amount value.
        """
        if collection_level_handling and collection_level in collection_level_handling:
            try:
                configured_limit = int(collection_level_handling[collection_level])
            except (TypeError, ValueError):
                return 0
            return max(0, configured_limit)

        return 0

    def _get_entity_id_key(self, entity_type: str) -> str:
        """
        Return entity identifier key.

        The implementation uses ``entity_type`` to produce entity identifier
        key.

        Args:
            entity_type: Text supplied as entity type in the format accepted by
                this function.

        Returns:
            The canonical entity identifier key text.
        """
        return "system_id" if entity_type == "Systems" else "manager_id"

    async def upload_sensitive_multipart_file(
        self,
        dut_id: str,
        uri: str,
        file_path: Path,
        size_bytes: int,
        sha256: str,
        *,
        field_name: str = "File",
        remote_filename: str = "payload.bin",
        timeout: int = 300,
        error_context: str = "sensitive multipart upload",
    ) -> Tuple[bool, Union[dict, str, bytes, StreamedRedfishBody], dict]:
        """
        Upload a file without exposing its path or contents to captures.

        The request is intentionally issued with zero retries. When a response
        is lost, callers must reconcile the resulting state before deciding
        whether another state-modifying request is safe.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri: Validated remote resource identifier used for URI.
            file_path: filesystem location used as the file path for this
                operation.
            size_bytes: Numeric size bytes used while the operation performs
                bounded accounting.
            sha256: Text supplied as SHA-256 in the format accepted by this
                function.
            field_name: Field label included in validation failures for the
                selected input.
            remote_filename: Text supplied as remote filename in the format
                accepted by this function.
            timeout: Maximum duration allowed before the operation is cancelled
                or fails.
            error_context: Text supplied as error context in the format accepted
                by this function.

        Returns:
            A tuple containing the fields that represent upload sensitive
            multipart file.
        """
        body = SensitiveMultipartBody(
            file_path=Path(file_path),
            size_bytes=size_bytes,
            sha256=sha256,
            field_name=field_name,
            remote_filename=remote_filename,
        )
        return await self.dispatch_request(
            dut_id=dut_id,
            method="POST",
            uri=uri,
            body=body,
            timeout=timeout,
            bypass_cache=True,
            retry_count=0,
            error_context=error_context,
        )

    async def dispatch_request(
        self,
        dut_id: str,
        method: str = "GET",
        uri: str = "",
        body: Any = None,
        get_raw_content: bool = False,
        error_context: str = "",
        timeout: int = 300,
        bypass_cache: bool = False,
        retry_count: int = 3,  # Default retry count, can be overridden by collector definition
        expected_http_statuses: Any = None,
        multipart_parts: Optional[List[Dict[str, Any]]] = None,
        persistent_post_reservation: PersistentPostReservation | None = None,
        raw_content_max_bytes: Optional[int] = None,
    ) -> Tuple[bool, Union[dict, str, bytes, StreamedRedfishBody], dict]:
        """
        Dispatch Redfish API request to BMC server.

        A subclass is still sensitive, but none of its extension code is trusted
        to build diagnostic metadata.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            method: Text supplied as method in the format accepted by this
                function.
            uri: Validated remote resource identifier used for URI.
            body: Optional body; ``None`` selects the function's default
                behavior.
            get_raw_content: Whether get raw content is enabled or required for
                this operation.
            error_context: Text supplied as error context in the format accepted
                by this function.
            timeout: Maximum duration allowed before the operation is cancelled
                or fails.
            bypass_cache: Whether bypass cache is enabled or required for this
                operation.
            retry_count: Numeric retry count used by the operation's bounded
                accounting.
            expected_http_statuses: Optional expected HTTP statuses; ``None``
                selects the function's default behavior.
            multipart_parts: Optional multipart parts; ``None`` selects the
                function's default behavior.
            persistent_post_reservation: Optional persistent post reservation;
                ``None`` selects the function's default behavior.
            raw_content_max_bytes: Upper bound enforced for raw content max
                bytes; the consuming boundary rejects or truncates values that
                exceed it.

        Returns:
            A tuple containing ``success flag``, ``status or message text``, and
            ``dict`` in that order.
        """
        full_uri = uri
        safe_uri = self._bounded_diagnostic_uri(uri) or ""
        safe_error_context = self._bounded_diagnostic_log_text(error_context)
        response_header_names = {
            "content-length",
            "content-type",
            "location",
            "retry-after",
            "taskmonitor",
        }
        body_type = type(body)
        sensitive_body = isinstance(body, SensitiveMultipartBody)
        if body_type is SensitiveMultipartBody:
            capture_body = SensitiveMultipartBody.safe_summary(body)
        elif sensitive_body:
            # A subclass is still sensitive, but none of its extension code is
            # trusted to build diagnostic metadata.
            capture_body = {
                "kind": "multipart",
                "content": "omitted",
                "reason": "untrusted sensitive body subtype",
            }
        elif body_type is NonReplayableJSONBody:
            # Preserve the original mapping without the legacy dict() copy.
            # The canonical spool accepts only exact built-ins and never calls
            # extension capture hooks.
            capture_body = body.payload
        else:
            capture_body = body
        safe_capture_body = self._bounded_diagnostic_log_value(capture_body)

        timing_operation_id = None
        timing_status = "error"
        timing_metadata: Dict[str, Any] = {}
        timing_size_bytes = None
        normalized_expected_statuses = normalize_expected_http_statuses(
            expected_http_statuses
        )
        if self.timing_manager:
            timing_operation_id = self.timing_manager.start_operation(
                "redfish_request",
                f"{method.upper()} {safe_uri}",
                metadata={
                    "method": method.upper(),
                    "raw_content": bool(get_raw_content),
                    "bypass_cache": bool(bypass_cache),
                },
            )

        try:
            # Get DUT for URI normalization (for logging full URIs)
            dut = request_controller_dut(self.dut_manager.get_dut(dut_id))
            full_uri = dut.normalize_redfish_uri(uri)
            safe_full_uri = self._bounded_diagnostic_uri(full_uri) or ""

            # Log request start for better debugging of concurrent requests
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Starting {method} request to {safe_full_uri} "
                f"(timeout={timeout}s, max_retries={retry_count})",
                dut_id,
            )

            # Use the DUT manager for all Redfish requests (handles URI normalization, auth, retry, etc.)
            request_options = {}
            if normalized_expected_statuses:
                request_options["expected_http_statuses"] = sorted(
                    normalized_expected_statuses
                )
            if multipart_parts:
                request_options["multipart_parts"] = multipart_parts
            if persistent_post_reservation is not None:
                request_options["persistent_post_reservation"] = (
                    persistent_post_reservation
                )
            if raw_content_max_bytes is not None:
                request_options["raw_content_max_bytes"] = raw_content_max_bytes
            (
                success,
                response,
                error_details,
                response_aux,
            ) = await self.dut_manager.execute_redfish_request(
                dut_id,
                method,
                uri,
                body,
                timeout,
                get_raw_content,
                bypass_cache,
                retry_count,
                **request_options,
            )

            if type(error_details) is _RedfishErrorMetadata:
                oversized_error_bodies = list(error_details._oversized_error_bodies)
                raw_dropped_evidence = error_details._oversized_error_evidence_dropped
                raw_evidence_limits = error_details._oversized_error_evidence_limits
                error_details = dict(error_details)
            else:
                oversized_error_bodies = []
                raw_dropped_evidence = 0
                raw_evidence_limits = ()
            dropped_evidence = (
                raw_dropped_evidence
                if isinstance(raw_dropped_evidence, int)
                and not isinstance(raw_dropped_evidence, bool)
                and raw_dropped_evidence > 0
                else 0
            )
            # Exact ownership avoids invoking untrusted mapping-subclass methods.
            if type(error_details) is dict:  # noqa: E721
                legacy_evidence = dict.get(error_details, "_oversized_error_body")
                if isinstance(legacy_evidence, TruncatedRedfishErrorBody):
                    error_details = dict(error_details)
                    error_details.pop("_oversized_error_body", None)
                    oversized_error_bodies.append(legacy_evidence)
            oversized_error_bodies = [
                item
                for item in oversized_error_bodies
                if isinstance(item, TruncatedRedfishErrorBody)
            ]
            oversized_evidence_capture = [
                item.capture_payload() for item in oversized_error_bodies
            ]
            if sensitive_body and oversized_error_bodies:
                oversized_evidence_capture = [
                    {
                        "metadata": item.capture_metadata(),
                        "retained_body": {
                            "publication": "omitted_sensitive_request",
                            "reason": "request body may be reflected by response",
                        },
                    }
                    for item in oversized_error_bodies
                ]
            oversized_evidence_metadata: Optional[Dict[str, Any]] = None
            if oversized_error_bodies:
                if (
                    isinstance(raw_evidence_limits, tuple)
                    and len(raw_evidence_limits) == 2
                    and all(
                        isinstance(value, int)
                        and not isinstance(value, bool)
                        and value > 0
                        for value in raw_evidence_limits
                    )
                ):
                    aggregate_max_bytes, max_responses = raw_evidence_limits
                else:
                    aggregate_max_bytes = sum(
                        item.evidence_limit_bytes for item in oversized_error_bodies
                    )
                    max_responses = len(oversized_error_bodies)
                oversized_evidence_metadata = {
                    "responses": [
                        item.capture_metadata() for item in oversized_error_bodies
                    ],
                    "dropped_response_count": dropped_evidence,
                    "limits": {
                        "per_response_max_bytes": max(
                            item.evidence_limit_bytes for item in oversized_error_bodies
                        ),
                        "aggregate_max_bytes": aggregate_max_bytes,
                        "max_responses": max_responses,
                    },
                    "supporting_artifact": (
                        "diagnostic/redfish_request_response_log.json"
                    ),
                    "artifact_path_status_field": (
                        "context.request_response_capture.artifact_path"
                    ),
                }
                if not isinstance(error_details, dict):
                    error_details = {}
                error_details["oversized_error_evidence"] = oversized_evidence_metadata

            request_capture_info = {
                "method": method,
                "uri": safe_full_uri,
                "original_uri": safe_uri,
                "body": capture_body,
                "timeout": timeout,
                "bypass_cache": bypass_cache,
                "get_raw_content": get_raw_content,
                "retry_count": retry_count,
                "error_context": safe_error_context,
            }
            if multipart_parts:
                request_capture_info["multipart_parts"] = [
                    {
                        "name": part.get("name"),
                        "content_type": part.get("content_type"),
                        "filename": part.get("filename")
                        or (
                            Path(part["file_path"]).name
                            if part.get("file_path")
                            else None
                        ),
                        "source": ("file" if part.get("file_path") else "value"),
                    }
                    for part in multipart_parts
                ]

            response_auxiliary = project_response_auxiliary(
                response_aux,
                response_header_names=response_header_names,
                max_scan_items=_CAPTURE_AUXILIARY_SCAN_MAX_ITEMS,
                max_retry_items=_CAPTURE_AUXILIARY_MAX_ITEMS,
                max_field_name_chars=_DIAGNOSTIC_FIELD_NAME_MAX_CHARS,
                max_header_chars=_REDFISH_RESPONSE_HEADER_MAX_CHARS,
                max_header_integer_bits=_REDFISH_RESPONSE_HEADER_MAX_INTEGER_BITS,
                is_sensitive_name=self._is_sensitive_diagnostic_name,
            )
            response_headers = response_auxiliary.response_headers
            response_retry_details = response_auxiliary.retry_details
            safe_response_headers = self._bounded_safe_response_headers(
                response_headers
            )
            safe_response_retry_details = self._bounded_capture_auxiliary_mapping(
                response_retry_details
            )

            if not success:
                # Use the detailed error information from DUT manager
                # Include request body/payload in error logs for POST/PUT/PATCH requests
                body_log = ""
                if sensitive_body and method.upper() in ["POST", "PUT", "PATCH"]:
                    body_log = " | Request body: <sensitive multipart body omitted>"
                elif safe_capture_body and method.upper() in ["POST", "PUT", "PATCH"]:
                    try:
                        body_str = (
                            json.dumps(safe_capture_body, indent=2)
                            if isinstance(safe_capture_body, dict)
                            else str(safe_capture_body)
                        )
                        body_log = f" | Request body: {body_str}"
                    except Exception:
                        body_log = f" | Request body: {safe_capture_body}"

                http_status = self._http_status_from_response(response, error_details)
                expected_http_miss = http_status in normalized_expected_statuses
                if sensitive_body:
                    original_error_details = error_details
                    error_details = {
                        key: dict.get(original_error_details, key)
                        for key in (
                            "http_status",
                            "uri",
                            "method",
                            "outcome_indeterminate",
                            "replay_suppressed",
                            "client_error",
                            "max_retries_exceeded",
                            "oversized_error_evidence",
                        )
                        if type(original_error_details) is dict
                        and dict.get(original_error_details, key) is not None
                    }
                    error_details["error_message"] = "sensitive request failed"
                    response = self._bounded_sensitive_response_capture(response)
                has_error_details = (
                    type(error_details) is dict and dict.__len__(error_details) > 0
                )
                if expected_http_miss:
                    timing_status = "expected_miss"
                    timing_metadata.update(
                        {
                            "http_status": http_status,
                            "expected_http_status": True,
                        }
                    )
                    error_uri = (
                        dict.get(error_details, "uri", full_uri)
                        if type(error_details) is dict
                        else full_uri
                    )
                    error_uri = self._bounded_diagnostic_uri(error_uri) or ""
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Expected optional Redfish probe miss ({method} {error_uri}): "
                        f"HTTP {http_status}{body_log}",
                        dut_id,
                    )
                elif has_error_details:
                    timing_status = "error"
                    # error_details already contains 'uri' field from DUT manager (normalized)
                    error_uri = dict.get(error_details, "uri", full_uri)
                    error_uri = self._bounded_diagnostic_uri(error_uri) or ""
                    error_message = self._bounded_diagnostic_log_text(
                        dict.get(error_details, "error_message", response)
                    )
                    error_status = self._bounded_diagnostic_log_text(
                        dict.get(error_details, "http_status", "Unknown")
                    )
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Failed to {safe_error_context} ({method} {error_uri}): "
                        f"HTTP {error_status} - "
                        f"{error_message}{body_log}",
                        dut_id,
                    )
                else:
                    timing_status = "error"
                    error_details = await self._extract_error_details_async(
                        self._bounded_diagnostic_log_value(response),
                        dut_id,
                        f"Failed to {safe_error_context} ({method} {safe_full_uri}): "
                        f"{body_log}",
                    )

                response_capture = {
                    "success": False,
                    # The canonical worker sanitizes this mapping directly
                    # into its private spool without retaining or copying it.
                    "error": error_details,
                }
                if safe_response_headers:
                    response_capture["response_headers"] = safe_response_headers
                if safe_response_retry_details:
                    response_capture["retry_info"] = safe_response_retry_details
                if response is not None and response is not error_details:
                    response_capture["raw_response"] = response
                if oversized_evidence_capture:
                    response_capture["oversized_error_evidence"] = (
                        oversized_evidence_capture
                    )
                await self._record_redfish_request_capture(
                    dut_id,
                    request_capture_info,
                    response_capture,
                    self._safe_transport_metadata(error_details),
                )
                failure_metadata = self._bounded_result_metadata(error_details)
                # Status drives caller-owned readiness/retry policy.  Preserve it
                # explicitly even when the public metadata prefix is truncated
                # before reaching the DUT manager's ``http_status`` field.
                if http_status is not None:
                    failure_metadata["http_status"] = http_status
                if oversized_evidence_metadata is not None:
                    failure_metadata["oversized_error_evidence"] = (
                        oversized_evidence_metadata
                    )
                if response_headers:
                    failure_metadata["response_headers"] = response_headers
                return (
                    False,
                    response,
                    _RequestTimingMetadata(
                        failure_metadata,
                        timing_operation_id=timing_operation_id,
                    ),
                )

            # Log successful binary downloads
            if get_raw_content and type(response) in {bytes, StreamedRedfishBody}:
                timing_size_bytes = len(response)
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Successfully downloaded {len(response)} bytes for "
                    f"{safe_error_context}",
                    dut_id,
                )

            transport_metadata = self._safe_transport_metadata(error_details)
            if oversized_evidence_metadata is not None:
                transport_metadata["oversized_error_evidence"] = (
                    oversized_evidence_metadata
                )
            timing_metadata.update(transport_metadata)
            response_capture: Dict[str, Any] = {
                "success": True,
                "transport": transport_metadata,
            }
            if get_raw_content and type(response) in {bytes, StreamedRedfishBody}:
                # The canonical spool emits bounded binary metadata directly;
                # do not build a second response representation here.
                response_capture["data"] = response
            elif sensitive_body:
                response_capture["data"] = self._bounded_sensitive_response_capture(
                    response
                )
            else:
                response_capture["data"] = response
            if safe_response_headers:
                response_capture["response_headers"] = safe_response_headers
            if safe_response_retry_details:
                # Preserve compatibility with injected/legacy DUT managers
                # whose fourth tuple element is retry metadata.
                response_capture["retry_info"] = safe_response_retry_details
            if oversized_evidence_capture:
                response_capture["oversized_error_evidence"] = (
                    oversized_evidence_capture
                )

            timing_status = "success"

            await self._record_redfish_request_capture(
                dut_id,
                request_capture_info,
                response_capture,
                transport_metadata,
            )

            response_metadata = _RequestTimingMetadata(
                {
                    **transport_metadata,
                    **(
                        {"response_headers": response_headers}
                        if response_headers
                        else {}
                    ),
                },
                timing_operation_id=timing_operation_id,
            )
            return True, response, response_metadata

        except asyncio.CancelledError:
            timing_status = "cancelled"
            timing_metadata["exception_type"] = "CancelledError"
            raise
        except Exception as e:
            exception_type = self._bounded_type_name(e)
            timing_metadata["exception_type"] = exception_type
            exception_message = (
                "sensitive request failed"
                if sensitive_body
                else self._bounded_diagnostic_log_text(e)
            )
            exception_request_capture = {
                "method": method,
                "uri": self._bounded_diagnostic_uri(full_uri) or "",
                "original_uri": safe_uri,
                "body": capture_body,
                "timeout": timeout,
                "bypass_cache": bypass_cache,
                "get_raw_content": get_raw_content,
                "retry_count": retry_count,
                "error_context": safe_error_context,
            }
            exception_response_capture = {
                "success": False,
                "error": {
                    "type": exception_type,
                    "message": exception_message,
                },
            }
            await self._record_redfish_request_capture(
                dut_id,
                exception_request_capture,
                exception_response_capture,
            )
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in {safe_error_context}: {exception_message}",
                dut_id,
            )
            return (
                False,
                exception_message,
                _RequestTimingMetadata(
                    {"error": "exception", "message": exception_message},
                    timing_operation_id=timing_operation_id,
                ),
            )
        finally:
            if self.timing_manager:
                self.timing_manager.end_operation(
                    timing_operation_id,
                    status=timing_status,
                    size_bytes=timing_size_bytes,
                    metadata=timing_metadata,
                )

    async def _concurrent_redfish_requests(
        self,
        dut_id: str,
        requests: List[Tuple[str, str]],  # List of (uri, error_context) tuples
        max_concurrent: int = None,
        get_raw_content: bool = False,
        raw_content_max_bytes: Optional[int] = None,
    ) -> List[Tuple[bool, Any]]:
        """
        Execute multiple Redfish requests concurrently with rate limiting.

        After applying local validation, the function forwards ``dut_id``,
        ``requests``, ``max_concurrent``, and ``get_raw_content`` to
        ``transport.concurrent_get_requests`` and preserves its return and
        exception contract. Terminal status is emitted only after multiple
        Redfish requests concurrently with rate limiting and its owned cleanup
        have completed. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            requests: Entries supplied as ``requests`` without transferring
                container ownership.
            max_concurrent: Upper bound enforced for max concurrent; the
                consuming boundary rejects or truncates values that exceed it.
            get_raw_content: Whether get raw content is enabled or required for
                this operation.
            raw_content_max_bytes: Optional byte ceiling forwarded to each raw
                response read; ``None`` selects the transport default.

        Returns:
            The concurrent Redfish requests returned in operation-defined order.
        """
        transport = RedfishTransport(
            dispatch=self.dispatch_request,
            log_runtime=self._log_runtime,
        )
        configured_max = self._runtime_boundary(
            dut_id, "redfish_max_concurrent_requests"
        )
        return await transport.concurrent_get_requests(
            dut_id,
            requests,
            max_concurrent=(
                configured_max
                if max_concurrent is None
                else min(max_concurrent, configured_max)
            ),
            get_raw_content=get_raw_content,
            raw_content_max_bytes=raw_content_max_bytes,
        )

    async def _concurrent_entity_processing(
        self,
        dut_id: str,
        entities: List[Dict[str, Any]],
        processor_func,
        max_concurrent: int = None,
        **kwargs,
    ) -> List[Any]:
        """
        Process multiple entities concurrently.

        The implementation uses ``dut_id``, ``entities``, ``processor_func``,
        ``max_concurrent``, and ``kwargs`` to process multiple entities
        concurrently. Terminal status is emitted only after multiple entities
        concurrently and its owned cleanup have completed. Owned asynchronous
        work is awaited before return, so completion does not leave an
        unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entities: Mapping supplying fields for multiple entities
                concurrently.
            processor_func: Processor func consumed while the function attempts
                to process multiple entities concurrently.
            max_concurrent: Upper bound enforced for max concurrent; the
                consuming boundary rejects or truncates values that exceed it.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            The validated ``processed_results``.

        Raises:
            asyncio.CancelledError: If an entity worker is cancelled; the
                cancellation is propagated after the owned gather observes
                every worker outcome.
        """
        configured_max = self._runtime_boundary(
            dut_id, "redfish_max_concurrent_entities"
        )
        if (
            not isinstance(max_concurrent, int)
            or isinstance(max_concurrent, bool)
            or max_concurrent <= 0
        ):
            max_concurrent = configured_max
        else:
            max_concurrent = min(max_concurrent, configured_max)
        from time import time

        start_time = time()
        entity_count = len(entities)

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"Starting concurrent processing of {entity_count} entities with max_concurrent={max_concurrent}",
            dut_id,
        )

        semaphore = Semaphore(max_concurrent)

        async def _process_entity(entity: Dict[str, Any]) -> Any:
            """
            Process entity.

            After applying local validation, the function forwards ``entity`` to
            ``processor_func`` and preserves its return and exception contract.
            Terminal status is emitted only after entity and its owned cleanup
            have completed. Owned asynchronous work is awaited before return, so
            completion does not leave an unobserved task behind.

            Args:
                entity: Mapping supplying fields for entity.

            Returns:
                The process entity value selected by the operation.
            """
            async with semaphore:
                entity_id = entity.get("@odata.id", "").split("/")[-1]
                return await processor_func(dut_id, entity_id, **kwargs)

        # Create tasks for all entities
        tasks = [_process_entity(entity) for entity in entities]

        # Execute all tasks concurrently
        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Handle any exceptions
        processed_results = []
        successful_count = 0
        for i, result in enumerate(results):
            if isinstance(result, asyncio.CancelledError):
                raise result
            if isinstance(result, BaseException):
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    "Entity processing " f"{i + 1} failed with {type(result).__name__}",
                    dut_id,
                )
                processed_results.append(None)
            else:
                processed_results.append(result)
                successful_count += 1

        end_time = time()
        duration = end_time - start_time

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"Concurrent processing completed: {successful_count}/{entity_count} successful in {duration:.2f}s",
            dut_id,
        )

        return processed_results

    async def _log_redfish_request(
        self,
        dut_id: str,
        method: str,
        url: str,
        body: Any = None,
        headers: Dict[str, str] = None,
        timeout: int = 60,
    ) -> None:
        """
        Log Redfish request details similar to legacy code.

        The implementation uses ``dut_id``, ``method``, ``url``, ``body``, and
        ``headers`` to log Redfish request details similar to legacy code. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            method: Text supplied as method in the format accepted by this
                function.
            url: Validated remote resource identifier used for URL.
            body: Optional body; ``None`` selects the function's default
                behavior.
            headers: Optional headers; ``None`` selects the function's default
                behavior.
            timeout: Maximum duration allowed before the operation is cancelled
                or fails.
        """
        try:
            # Don't log repetitive task polling
            if "/TaskService/Tasks/" in url:
                return

            request_summary = json.dumps(
                self._bounded_request_payload_summary(body),
                sort_keys=True,
                separators=(",", ":"),
            )
            header_summary = json.dumps(
                self._bounded_safe_response_headers(headers),
                sort_keys=True,
                separators=(",", ":"),
            )
            request_log = (
                f"Redfish request: {method} {self._bounded_diagnostic_uri(url)} | "
                f"Body metadata: {request_summary} | Headers: {header_summary} | "
                f"Timeout: {timeout}s"
            )
            await self._log_runtime("INFO", "RedfishService", request_log, dut_id)

        except Exception as e:
            # Best effort logging
            safe_error = self._bounded_diagnostic_log_text(e)
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Failed to log request details: {safe_error}",
                dut_id,
            )

    async def _log_redfish_response(
        self,
        dut_id: str,
        method: str,
        url: str,
        success: bool,
        response_data: Any = None,
        status_code: int = None,
        error_message: str = None,
    ) -> None:
        """
        Log Redfish response details similar to legacy code.

        The implementation uses ``dut_id``, ``method``, ``url``, ``success``,
        and ``response_data`` to log Redfish response details similar to legacy
        code. Owned asynchronous work is awaited before return, so completion
        does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            method: Text supplied as method in the format accepted by this
                function.
            url: Validated remote resource identifier used for URL.
            success: Whether success is enabled or required for this operation.
            response_data: Optional response data; ``None`` selects the
                function's default behavior.
            status_code: Optional status code; ``None`` selects the function's
                default behavior.
            error_message: Optional error message; ``None`` selects the
                function's default behavior.
        """
        try:
            # Don't log repetitive task polling
            if "/TaskService/Tasks/" in url:
                return

            if success:
                if status_code and status_code >= 200 and status_code < 300:
                    # Success case - log minimal info since content is saved to file
                    response_log = f"Redfish response: {method} {url} | Status: {status_code} | Success"

                    # For task responses, log task state
                    if type(response_data) is dict and "TaskState" in response_data:
                        task_id = self._bounded_diagnostic_log_text(
                            dict.get(response_data, "Id", "Unknown")
                        )
                        task_state = (
                            self._bounded_task_state(
                                dict.get(response_data, "TaskState")
                            )
                            or "Unknown"
                        )
                        percent_complete = self._bounded_task_percent_complete(
                            dict.get(response_data, "PercentComplete")
                        )
                        response_log += (
                            f" | Task {task_id}: {task_state} "
                            f"({percent_complete if percent_complete is not None else 'unknown'}%)"
                        )

                    await self._log_runtime(
                        "INFO", "RedfishService", response_log, dut_id
                    )
                else:
                    # Non-2xx status retains metadata only. The canonical
                    # request capture owns the detailed response body.
                    response_log = f"Redfish response: {method} {url} | Status: {status_code} | Error"
                    response_log += " | Response metadata: " + (
                        self._bounded_response_metadata_text(
                            response_data,
                            status_code,
                        )
                    )
                    await self._log_runtime(
                        "ERROR", "RedfishService", response_log, dut_id
                    )
            else:
                # Failed request - log error details
                error_log = f"Redfish response: {method} {url} | Failed"
                if error_message:
                    error_log += " | Error metadata: present"
                error_log += " | Response metadata: " + (
                    self._bounded_response_metadata_text(response_data, status_code)
                )
                await self._log_runtime("ERROR", "RedfishService", error_log, dut_id)

        except Exception as e:
            # Best effort logging
            safe_error = self._bounded_diagnostic_log_text(e)
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"Failed to log response details: {safe_error}",
                dut_id,
            )

    """
    Handles
    """

    async def _handle_get_collection(
        self, dut_id: str, uri_list: List[str], function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Handle simple GET request collections.

        Each URI in ``uri_list`` is fetched independently. A failed URI does not
        abort the remaining URIs: failures are accumulated and the overall
        status is derived from how many URIs succeeded — ``success`` when all
        succeed, ``partial`` when some succeed, and ``error`` only when every
        URI fails (which preserves the prior behavior for the single-URI case).

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle get collection.
        """

        async def _get_collection_and_save():
            """
            Return collection and save.

            Raw downloads must bypass cache so a prior JSON/text read of the
            same URI cannot be reused in place of the binary payload.

            Returns:
                Collection and save.
            """
            output_files = []
            diagnostic_files = []
            error_messages: List[str] = []
            probe_errors: List[str] = []
            metadata_only = bool(kwargs.get("metadata_only", False))

            complete_on_empty_targets = kwargs.get("complete_on_empty_targets", False)
            get_raw_content = kwargs.get("get_raw_content", False)
            # Raw downloads must bypass cache so a prior JSON/text read of the same URI
            # cannot be reused in place of the binary payload.
            bypass_cache = kwargs.get("bypass_cache", False) or get_raw_content

            # If there are no URIs and the collector allows empty targets, treat as complete
            if not uri_list and complete_on_empty_targets:
                return await self._create_standardized_collector_result(
                    dut_id=dut_id,
                    collector_id=kwargs.get("collector_id", function_tag),
                    successful_operations=1,
                    total_operations=1,
                    output_files=[],
                    error_messages=[],
                    operation_name="get_collection",
                    additional_context={
                        "uris_processed": uri_list,
                        "successful_count": 0,
                        "reason": "No URIs to collect; treating as complete (empty targets allowed)",
                    },
                )

            # Phase 1: fetch all responses before writing any files.
            collected = []  # list of (uri, data, extracted_ids, request timing token)
            for uri in uri_list:
                if kwargs.get("streaming_time_filtered", False):
                    uri = await self._append_streaming_time_filter(dut_id, uri)
                await self._log_collection_start(dut_id, "GET", uri)

                success, data, request_metadata = await self.dispatch_request(
                    dut_id,
                    "GET",
                    uri,
                    get_raw_content=get_raw_content,
                    bypass_cache=bypass_cache,
                )

                if (
                    success
                    and get_raw_content
                    and isinstance(data, (bytes, bytearray, StreamedRedfishBody))
                    and len(data) == 0
                ):
                    # A successful HTTP status with an empty attachment is not a
                    # successful collection. In particular, HostLogger may
                    # return HTTP 200 with a zero-byte body when no archive was
                    # produced; publishing that file would create a false pass.
                    detail = "empty raw response body"
                    if isinstance(data, StreamedRedfishBody):
                        data.cleanup()
                    await self._log_collection_failure(dut_id, "GET", uri, detail)
                    error_messages.append(
                        f"Empty response body: {uri} returned HTTP success with a "
                        "zero-byte body; the device produced no content for this "
                        "resource"
                    )
                elif success:
                    extracted_ids = self._extract_entity_id_from_uri(uri)
                    if extracted_ids:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Extracted entity IDs from URI: {extracted_ids}",
                            dut_id,
                        )
                    collected.append(
                        (
                            uri,
                            data,
                            extracted_ids,
                            self._request_timing_operation_id(request_metadata),
                        )
                    )
                else:
                    # Do not fail the whole collection on a single failed URI.
                    # When a collector probes multiple alternate URIs (e.g. the same
                    # resource under two possible system sources), an absent/404 URI
                    # must not mask a valid sibling. Record the error and keep going;
                    # status is derived from successful vs total below (error only when
                    # every URI fails, partial when some fail, success when all pass).
                    await self._log_collection_failure(dut_id, "GET", uri, str(data))
                    failure = f"GET request failed: {uri} - {data}"
                    if metadata_only:
                        probe_errors.append(failure)
                    else:
                        error_messages.append(failure)

            # Phase 2: write results.
            # When multiple URIs would produce the same filename (output_pattern has no
            # entity placeholder), combine all responses into a single dict keyed by
            # entity ID rather than overwriting on each iteration.
            output_pattern, substitutions, filtered_kwargs = (
                self._extract_output_pattern_params(kwargs)
            )
            entity_placeholders = {
                "system_id",
                "manager_id",
                "chassis_id",
                "entity_id",
            }
            pattern_str = output_pattern or ""
            has_entity_placeholder = any(
                f"{{{p}}}" in pattern_str for p in entity_placeholders
            )
            # Combining streamed bodies would reintroduce unbounded memory (or
            # base64 disk amplification). Publish each exact body instead.
            needs_combine = (
                not get_raw_content
                and len(collected) > 1
                and not has_entity_placeholder
            )

            if needs_combine:
                combined = {}
                for uri, data, extracted_ids, _ in collected:
                    key = (
                        extracted_ids.get("system_id")
                        or extracted_ids.get("manager_id")
                        or extracted_ids.get("chassis_id")
                        or uri
                    )
                    combined[key] = data

                file_path = await self._save_data_with_common_pattern(
                    dut_id,
                    combined,
                    f"{function_tag}_response",
                    output_pattern=output_pattern,
                    substitutions=substitutions.copy(),
                    request_timing_operation_ids=[
                        token for _, _, _, token in collected if token
                    ],
                    **filtered_kwargs,
                )
                if file_path:
                    if metadata_only:
                        diagnostic_files.append(file_path)
                    else:
                        output_files.append(file_path)
                    for uri, _, _, _ in collected:
                        await self._log_collection_success(
                            dut_id, "GET", uri, file_path
                        )
                else:
                    error_messages.append(
                        "Failed to publish combined GET response artifact"
                    )
            else:
                for raw_index, (
                    uri,
                    data,
                    extracted_ids,
                    request_timing_token,
                ) in enumerate(collected, start=1):
                    subs = substitutions.copy()
                    subs.update(extracted_ids)
                    effective_output_pattern = output_pattern
                    if (
                        get_raw_content
                        and len(collected) > 1
                        and not has_entity_placeholder
                    ):
                        uri_suffix = hashlib.sha256(uri.encode("utf-8")).hexdigest()[
                            :12
                        ]
                        base_pattern = output_pattern or f"{function_tag}_response.bin"
                        stem, suffix = os.path.splitext(base_pattern)
                        effective_output_pattern = (
                            f"{stem}_{raw_index}_{uri_suffix}{suffix}"
                        )
                    file_path = await self._save_data_with_common_pattern(
                        dut_id,
                        data,
                        f"{function_tag}_response",
                        output_pattern=effective_output_pattern,
                        substitutions=subs,
                        request_timing_operation_ids=request_timing_token,
                        **filtered_kwargs,
                    )
                    if file_path:
                        if metadata_only:
                            diagnostic_files.append(file_path)
                        else:
                            output_files.append(file_path)
                        await self._log_collection_success(
                            dut_id, "GET", uri, file_path
                        )
                    else:
                        if isinstance(data, StreamedRedfishBody):
                            data.cleanup()
                        error_messages.append(
                            f"Failed to publish GET response artifact: {uri}"
                        )

            # When combining, every collected response is a success even though they
            # produced a single output file. Count responses, not files.
            successful_ops = (
                len(collected) if needs_combine or metadata_only else len(output_files)
            )
            metadata_context: Dict[str, Any] = {}
            if metadata_only:
                metadata_context = {
                    "status": "skipped",
                    "reason": "Metadata probe completed; no primary artifact expected",
                    "metadata_only": True,
                    "probe_errors": probe_errors,
                    "diagnostic_files": diagnostic_files,
                }
            return await self._create_standardized_collector_result(
                dut_id=dut_id,
                collector_id=kwargs.get("collector_id", function_tag),
                successful_operations=successful_ops,
                total_operations=len(uri_list),
                output_files=output_files,
                error_messages=error_messages,
                operation_name="get_collection",
                additional_context={
                    "uris_processed": uri_list,
                    "successful_count": successful_ops,
                    "failed_count": len(error_messages) + len(probe_errors),
                    **metadata_context,
                },
            )

        return await self._execute_with_error_handling(
            dut_id,
            f"GET collection for {function_tag}",
            _get_collection_and_save,
        )

    async def _handle_paginated_collection(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        function_tag: str,
        additional_data_callback: bool,
        collection_level_handling: Optional[Dict[str, Any]],
        uri_list: List[str],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Handle paginated log collections.

        Check if uri_pattern is provided in kwargs (for R32 case).

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Mapping supplying fields for paginated
                log collections.
            uri_list: Validated remote resource identifier used for URI list.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle paginated collection.
        """
        await self._log_collection_start(
            dut_id, "paginated", f"{entity_type}/{log_service}"
        )

        try:
            # Check if uri_pattern is provided in kwargs (for R32 case)
            uri_pattern = kwargs.get("uri_pattern")

            # Use existing paginated logic but make it work with URI patterns
            if uri_list:
                # Custom URI patterns provided
                return await self._collect_paginated_from_uris(
                    dut_id,
                    uri_list,
                    function_tag,
                    additional_data_callback,
                    collection_level_handling,
                    **kwargs,
                )
            elif uri_pattern:
                # URI pattern provided (like R32) - pass it to entity-based collection
                kwargs["uri_pattern"] = uri_pattern
                return await self._collect_paginated_from_entities(
                    dut_id,
                    entity_type,
                    log_service,
                    function_tag,
                    additional_data_callback,
                    collection_level_handling,
                    **kwargs,
                )
            else:
                # Standard entity-based collection
                return await self._collect_paginated_from_entities(
                    dut_id,
                    entity_type,
                    log_service,
                    function_tag,
                    additional_data_callback,
                    collection_level_handling,
                    **kwargs,
                )
        except Exception as e:
            await self._log_collection_failure(
                dut_id, "paginated", f"{entity_type}/{log_service}", str(e)
            )
            return await self._create_standardized_collector_result(
                dut_id=dut_id,
                collector_id=kwargs.get("collector_id", f"{entity_type}_{log_service}"),
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[f"Exception in paginated collection: {str(e)}"],
                operation_name="paginated_collection",
                additional_context={
                    "entity_type": entity_type,
                    "log_service": log_service,
                    "error_type": type(e).__name__,
                },
            )

    async def _collect_paginated_from_uris(
        self,
        dut_id: str,
        uri_list: List[str],
        function_tag: str,
        additional_data_callback: bool,
        collection_level_handling: Optional[Dict[str, Any]],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect paginated data from custom URI patterns.

        After applying local validation, the function forwards ``dut_id``,
        ``uri_list``, ``function_tag``, ``additional_data_callback``, and
        ``collection_level_handling`` to
        ``self._create_standardized_collector_result`` and preserves its return
        and exception contract. Terminal status is emitted only after paginated
        data from custom URI patterns and its owned cleanup have completed.
        Owned asynchronous work is awaited before return, so completion does not
        leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Mapping supplying fields for paginated
                data from custom URI patterns.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing paginated from URIs.
        """
        output_files = []
        failed_uris = []
        successful_uris = []
        entity_type = kwargs.get("entity_type")

        for uri in uri_list:
            await self._log_collection_start(dut_id, "paginated_uri", uri)

            # Extract entity info from URI for compatibility
            uri_parts = uri.split("/")
            entity_id = "unknown"
            for i, part in enumerate(uri_parts):
                if part in ["Systems", "Managers", "Chassis"] and i + 1 < len(
                    uri_parts
                ):
                    entity_id = uri_parts[i + 1]
                    break

            # Use existing optimized pagination logic
            result = await self._collect_optimized_paginated_logs(
                dut_id,
                "Custom",
                entity_id,
                "Logs",
                function_tag,
                additional_data_callback,
                collection_level_handling,
                uri_pattern=uri,
                retry_count=kwargs.get("retry_count", 3),
                **kwargs,
            )

            # Extract files from standardized result
            collected_files = result.get("output_files", [])

            if collected_files:
                output_files.extend(collected_files)
                successful_uris.append(uri)
                await self._log_collection_success(
                    dut_id,
                    "paginated_uri",
                    uri,
                    f"{len(collected_files)} files",
                )
            else:
                failed_uris.append(uri)
                await self._log_collection_failure(
                    dut_id, "paginated_uri", uri, "No files collected"
                )

        # Determine overall success based on results
        successful_operations = len(successful_uris)
        total_operations = len(uri_list)
        error_messages = [f"Failed URI: {uri}" for uri in failed_uris]

        return await self._create_standardized_collector_result(
            dut_id=dut_id,
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="paginated_uri_collection",
            additional_context={
                "custom_uris_processed": len(uri_list),
                "successful_uris": successful_uris,
                "failed_uris": failed_uris,
            },
        )

    async def _collect_paginated_from_entities(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        function_tag: str,
        additional_data_callback: bool,
        collection_level_handling: Optional[Dict[str, Any]],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect paginated data from standard entity-based approach.

        The implementation uses ``dut_id``, ``entity_type``, ``log_service``,
        ``function_tag``, and ``additional_data_callback`` to collect paginated
        data from standard entity-based approach. Terminal status is emitted
        only after paginated data from standard entity-based approach and its
        owned cleanup have completed. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Mapping supplying fields for paginated
                data from standard entity-based approach.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            The validated ``result``.
        """
        # Use the original collect_redfish_paginated_logs method to ensure all logic is preserved
        # This maintains backward compatibility and ensures additional_data_callback works correctly
        result = await self._collect_redfish_paginated_logs(
            dut_id,
            entity_type,
            log_service,
            function_tag,
            additional_data_callback,
            collection_level_handling,
            **kwargs,
        )

        # Add logging for the result
        if result.get("success"):
            await self._log_collection_success(
                dut_id,
                "paginated_entities",
                f"{entity_type}/{log_service}",
                f"{len(result.get('output_files', []))} files",
            )
        else:
            reason = result.get("reason")
            if not reason:
                reason = f"Paginated entities collection failed for {entity_type}/{log_service} - no specific error reason provided in result"
            await self._log_collection_failure(
                dut_id,
                "paginated_entities",
                f"{entity_type}/{log_service}",
                reason,
            )

        return result

    async def _get_custom_uris_from_config(
        self,
        dut_id: str,
        entity_id: str,
        uri_key: str,
        entity_type: str = None,
    ) -> List[str]:
        """
        Get custom URIs from configuration with entity_id substitution.

        This is a generic approach that works for any URI configuration key.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            uri_key: Validated remote resource identifier used for URI key.
            entity_type: Optional entity type; ``None`` selects the function's
                default behavior.

        Returns:
            The custom URIs from config returned in operation-defined order.
        """
        try:
            # Check DUT-level configuration first (highest priority)
            dut_config = self.dut_manager.get_dut_config(dut_id)
            dut_uris = dut_config.get(uri_key, None)

            if uri_key in dut_config:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using DUT-level custom URIs for {entity_id} from {uri_key}: {dut_uris}",
                    dut_id,
                )
                return self._process_user_defined_uris(dut_uris, entity_id, entity_type)

            # Check tool-level configuration (medium priority)
            orchestrator = getattr(self, "orchestrator", None)
            if orchestrator and hasattr(orchestrator, "config_manager"):
                tool_config = orchestrator.config_manager.get_tool_config()
            else:
                tool_config = self.dut_manager.tool_config
            tool_uris = tool_config.get(uri_key, None)

            if tool_uris:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using tool-level custom URIs for {entity_id} from {uri_key}: {tool_uris}",
                    dut_id,
                )
                return self._process_user_defined_uris(
                    tool_uris, entity_id, entity_type
                )

            return []

        except Exception as e:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"Could not load custom URI configuration for {uri_key}: {e}",
                dut_id,
            )
            return []

    def _process_user_defined_uris(
        self, uris_config, entity_id: str, entity_type: str = None
    ) -> List[str]:
        """
        Process user defined URIs.

        The implementation uses ``uris_config``, ``entity_id``, and
        ``entity_type`` to process user defined URIs. Terminal status is emitted
        only after user defined URIs and its owned cleanup have completed.
        Filesystem effects remain confined to the caller-selected paths and the
        owning resource lifecycle.

        Args:
            uris_config: Validated remote resource identifier used for URIs
                config.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            entity_type: Optional entity type; ``None`` selects the function's
                default behavior.

        Returns:
            The process user defined URIs returned in operation-defined order.
        """
        if not uris_config:
            return []

        # Convert single string to list
        if isinstance(uris_config, str):
            uris_config = [uris_config]

        # Filter out empty strings and process each URI
        processed_uris = []
        for uri in uris_config:
            if uri and isinstance(uri, str):
                processed_uri = uri

                # Smart substitution based on entity type
                if entity_type:
                    # Use entity-type specific substitution
                    if entity_type.lower() == "systems":
                        processed_uri = processed_uri.replace("{system_id}", entity_id)
                    elif entity_type.lower() == "managers":
                        processed_uri = processed_uri.replace("{manager_id}", entity_id)
                    elif entity_type.lower() == "chassis":
                        processed_uri = processed_uri.replace("{chassis_id}", entity_id)

                # Always support generic {entity_id} substitution
                processed_uri = processed_uri.replace("{entity_id}", entity_id)

                # Legacy support for backward compatibility
                processed_uri = processed_uri.replace("{system_id}", entity_id)
                processed_uri = processed_uri.replace("{manager_id}", entity_id)
                processed_uri = processed_uri.replace("{chassis_id}", entity_id)

                processed_uris.append(processed_uri)

        return processed_uris

    async def _collect_custom_uris(
        self,
        dut_id: str,
        entity_type: str,
        entity_id: str,
        custom_uris: List[str],
        function_tag: str,
        log_service: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect data from custom URIs using paginated collection logic.

        Generate filename based on URI (matching legacy behavior).

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            custom_uris: Validated remote resource identifier used for custom
                URIs.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing custom URIs.
        """
        output_files = []
        error_messages = []
        successful_operations = 0
        has_degraded_result = False
        has_partial_result = False
        total_operations = len(custom_uris)

        for i, uri in enumerate(custom_uris):
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Collecting {log_service} from custom URI {i + 1}/{total_operations}: {uri}",
                dut_id,
            )

            # Generate filename based on URI (matching legacy behavior)
            uri_safe = (
                "_".join(uri.split("/")[-3:-1]).replace("?", "_").replace("&", "_")
            )
            output_file = f"{function_tag}_{log_service.lower()}_{entity_id}_uri_{i}_{uri_safe}.json"

            # Use the existing paginated collection logic for each custom URI
            # Pass the entity_type from collector definition and use custom URI as pattern
            # Set _processing_custom_uris flag to prevent infinite recursion
            custom_kwargs = kwargs.copy()
            custom_kwargs["_processing_custom_uris"] = True
            result = await self._collect_optimized_paginated_logs(
                dut_id=dut_id,
                entity_type=entity_type,  # Use entity_type from collector definition
                entity_id=entity_id,
                log_service=log_service,
                function_tag=function_tag,
                uri_pattern=uri,  # Use custom URI as pattern
                retry_count=kwargs.get("retry_count", 3),
                **custom_kwargs,
            )

            # Extract results from standardized response
            child_status = result.get("status")
            if child_status in ["success", "degraded", "partial"]:
                successful_operations += 1
                output_files.extend(result.get("output_files", []))
                if child_status in {"degraded", "partial"}:
                    if child_status == "degraded":
                        has_degraded_result = True
                    else:
                        has_partial_result = True
                    partial_reason = result.get(
                        "reason", "Custom URI collection was incomplete"
                    )
                    error_messages.append(f"Custom URI {uri}: {partial_reason}")
            else:
                error_messages.append(
                    f"Failed to collect from custom URI {uri}: {result.get('reason', 'Unknown error')}"
                )

        if successful_operations == 0:
            aggregate_status = "error"
        elif has_partial_result or successful_operations < total_operations:
            aggregate_status = "partial"
        elif has_degraded_result:
            aggregate_status = "degraded"
        else:
            aggregate_status = "success"

        # Create standardized result
        return await self._create_standardized_collector_result(
            dut_id=dut_id,
            collector_id=kwargs.get(
                "collector_id", f"custom_{log_service.lower()}_{entity_id}"
            ),
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="custom_uri_collection",
            additional_context={
                "entity_type": entity_type,
                "entity_id": entity_id,
                "log_service": log_service,
                "custom_uris": custom_uris,
                "status": aggregate_status,
                **(
                    {"reason": "; ".join(error_messages)}
                    if aggregate_status == "degraded"
                    else {}
                ),
            },
        )

    async def _create_collection_table(
        self,
        dut_id: str,
        collection_data: Dict[str, Any],
        function_tag: str,
        table_properties: List[str],
        output_pattern: str,
        substitutions: Dict[str, str],
        collector_id: str = "",
        table_title: str = "Collection Table",
        **kwargs,
    ) -> List[str]:
        """
        Create a table from collection data with specified properties.

        This is a generalized method that can be used by any collector that
        wants table output. Uses the existing v2.0 file creation infrastructure.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collection_data: Mapping supplying fields for table from collection
                data with specified properties.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            table_properties: Entries supplied as ``table_properties`` without
                transferring container ownership.
            output_pattern: Text supplied as output pattern in the format
                accepted by this function.
            substitutions: Mapping supplying fields for table from collection
                data with specified properties.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            table_title: Text supplied as table title in the format accepted by
                this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            The collection table returned in operation-defined order.
        """
        output_files = []

        try:
            # Import tabulate for table formatting
            from tabulate import tabulate

            inventory_members = collection_data.get("Members", [])
            if not isinstance(inventory_members, list):
                inventory_members = []

            # Define property list (Id and Version are always included for firmware, customizable for others)
            if not table_properties:
                prop_list = ["Id", "Version"]  # Default properties
            else:
                # Remove duplicates and ensure Id is first if present
                unique_props = list(dict.fromkeys(table_properties))
                if "Id" in unique_props:
                    unique_props.remove("Id")
                    prop_list = ["Id"] + unique_props
                else:
                    prop_list = unique_props

            table_data = []
            table_data_json = []

            # Process each member to get detailed properties
            for component in inventory_members:
                component_uri = component.get("@odata.id", "")
                if not component_uri:
                    continue

                # Get detailed component data
                success, response, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    component_uri,
                    error_context=f"get component {component_uri}",
                )

                if not success:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Could not fetch component {component_uri}: {response}",
                        dut_id,
                    )
                    continue

                # Extract properties
                entry = {}
                for prop in prop_list:
                    entry[prop] = response.get(prop, "")

                table_data_json.append(entry)
                table_data.append(list(entry.values()))

            if not table_data:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No {table_title.lower()} data found to create table",
                    dut_id,
                )
                return output_files

            # Create text table content
            table_content = f"{table_title}:\n\n"
            table_content += tabulate(table_data, prop_list, tablefmt="outline") + "\n"

            text_file = await self._save_data_with_common_pattern(
                dut_id,
                table_content,
                f"{function_tag}_table",
                output_pattern=f"{function_tag}.txt",
                substitutions=substitutions,
                collector_id=collector_id,
                **kwargs,
            )
            if text_file:
                output_files.append(text_file)

            json_file = await self._save_data_with_common_pattern(
                dut_id,
                table_data_json,
                f"{function_tag}_table",
                output_pattern=f"{function_tag}.json",
                substitutions=substitutions,
                collector_id=collector_id,
                **kwargs,
            )
            if json_file:
                output_files.append(json_file)

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Created {table_title.lower()} with {len(table_data)} entries",
                dut_id,
            )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Error creating {table_title.lower()}: {e}",
                dut_id,
            )

        return output_files

    async def _handle_collection_with_members(
        self, dut_id: str, uri_list: List[str], function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Handle collection with members.

        Define collection name for summary generation (matching host service
        pattern).

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle collection with members.
        """
        output_files = []
        failed_collections = []
        successful_collections = []
        partial_collections = []
        success_bearing_partial_collections = []
        member_successes = 0
        member_failures = 0
        additional_member_successes = 0
        additional_member_failures = 0
        linked_member_successes = 0
        linked_member_failures = 0
        skip_if_no_matching_members = bool(
            kwargs.get("skip_if_no_matching_members", False)
        )
        complete_on_empty_matches = bool(kwargs.get("complete_on_empty_matches", False))
        matching_members_found = 0

        try:
            request_delay = self._normalize_collection_request_delay(
                kwargs.get("request_delay", 1)
            )
        except ValueError:
            request_delay = 1.0
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                (
                    "Invalid collection request delay; using the safe "
                    "one-second default."
                ),
                dut_id,
            )

        # Define collection name for summary generation (matching host service pattern)
        collection_name = f"{function_tag} Collection"

        # ``complete_on_empty_matches`` only applies after a collection endpoint
        # was queried successfully and returned zero matching Members.  An empty
        # target list has no such evidence and must retain the normal not-run /
        # failure semantics unless the collector explicitly opts into
        # ``complete_on_empty_targets``.
        complete_on_empty_targets = kwargs.get("complete_on_empty_targets", False)
        if not uri_list and complete_on_empty_targets:
            reason_msg = (
                f"No collection_with_members targets found for {function_tag}; "
                "treating as complete"
            )
            await self._log_runtime(
                "INFO",
                "RedfishService",
                reason_msg,
                dut_id,
            )
            result = await self._create_standardized_collector_result(
                dut_id=dut_id,
                collector_id=kwargs.get("collector_id", function_tag),
                successful_operations=1,
                total_operations=1,
                output_files=[],
                error_messages=[],
                operation_name="collection_with_members",
                additional_context={
                    "collections_processed": 0,
                    "successful_collections": [],
                    "partial_collections": [],
                    "failed_collections": [],
                    "status": "success",
                    "reason": reason_msg,
                },
            )
            result["status_override"] = "success"
            result["reason_override"] = reason_msg
            return result

        # Check if this is a table format request (for firmware inventory)
        format_output = kwargs.get("format_output", "")
        is_table_format = format_output == "table"

        # Get table properties from collector definition with DUT config override
        table_properties = []
        if is_table_format:
            # Start with default properties from collector definition
            table_properties = kwargs.get("table_properties", [])
            if not isinstance(table_properties, list):
                table_properties = []

            # Check for DUT-level and tool-level configuration override
            config_key = kwargs.get("table_config_key", "")
            if config_key:
                try:
                    dut_config = self.dut_manager.get_dut_config(dut_id)
                    dut_override_props = dut_config.get(config_key, [])

                    # Check DUT-level configuration first (highest priority).
                    # An explicit empty list clears lower configured sources
                    # and retains the collector-defined defaults.
                    if config_key in dut_config and isinstance(
                        dut_override_props, list
                    ):
                        if dut_override_props:
                            table_properties = dut_override_props
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Using DUT-level table properties from {config_key}: {table_properties}",
                                dut_id,
                            )
                    else:
                        # Fall back to tool-level configuration (medium priority)
                        # Get tool config from the orchestrator's configuration manager
                        orchestrator = getattr(self, "orchestrator", None)
                        if orchestrator and hasattr(orchestrator, "config_manager"):
                            tool_config = orchestrator.config_manager.get_tool_config()
                        else:
                            tool_config = self.dut_manager.tool_config
                        tool_override_props = tool_config.get(config_key, [])
                        if (
                            isinstance(tool_override_props, list)
                            and tool_override_props
                        ):
                            table_properties = tool_override_props
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Using tool-level table properties from {config_key}: {table_properties}",
                                dut_id,
                            )
                        else:
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"No override found for {config_key}, using collector defaults: {table_properties}",
                                dut_id,
                            )
                except Exception as e:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Could not load config for table properties override: {e}",
                        dut_id,
                    )

        # Retry configuration
        max_retries = kwargs.get(
            "retry_count", 2
        )  # Default 2 retries for failed collections
        retry_delay = 5  # 5 seconds between retries

        def _append_output_suffix(pattern: Optional[str], suffix: str) -> Optional[str]:
            """
            Append a suffix before the filename extension when present.

            The implementation uses ``pattern`` and ``suffix`` to append a
            suffix before the filename extension when present.

            Args:
                pattern: Text supplied as pattern in the format accepted by this
                    function.
                suffix: Text supplied as suffix in the format accepted by this
                    function.

            Returns:
                The canonical append output suffix text.
            """
            if not pattern or not suffix:
                return pattern
            if "." in pattern:
                stem, extension = pattern.rsplit(".", 1)
                return f"{stem}{suffix}.{extension}"
            return f"{pattern}{suffix}"

        def _attempt_count_text(count: int) -> str:
            """
            Format an observed request-attempt count for an error reason.

            The returned wording records the number of network requests that
            actually occurred, which may be lower than the configured retry
            ceiling when a terminal response stops the loop early.

            Args:
                count: Number of request attempts actually performed.

            Returns:
                A singular or plural human-readable attempt count.
            """
            noun = "attempt" if count == 1 else "attempts"
            return f"{count} {noun}"

        for collection_uri in uri_list:
            await self._log_collection_start(dut_id, "collection", collection_uri)

            # Add small delay between requests to prevent BMC overload
            if (
                len(successful_collections) > 0
                or len(partial_collections) > 0
                or len(failed_collections) > 0
            ):
                await asyncio.sleep(request_delay)

            # Try collection with retries
            success = False
            collection_data = None
            collection_request_metadata: Dict[str, Any] = {}
            last_error = None
            collection_attempts = 0

            for retry_attempt in range(max_retries + 1):
                collection_attempts = retry_attempt + 1
                if retry_attempt > 0:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Retrying collection for {collection_uri} (attempt {retry_attempt + 1}/{max_retries + 1})",
                        dut_id,
                    )
                    await asyncio.sleep(retry_delay)

                (
                    success,
                    collection_data,
                    collection_request_metadata,
                ) = await self.dispatch_request(
                    dut_id,
                    "GET",
                    collection_uri,
                    error_context=f"get collection from {collection_uri}",
                )

                if success:
                    break
                else:
                    last_error = collection_data
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Collection attempt {retry_attempt + 1} failed for {collection_uri}: {collection_data}",
                        dut_id,
                    )
                    if not self._redfish_get_failure_is_retryable(
                        collection_data, collection_request_metadata
                    ):
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Not retrying terminal collection response for {collection_uri}",
                            dut_id,
                        )
                        break

            if not success:
                error_msg = (
                    f"Collection failed for {collection_uri} after "
                    f"{_attempt_count_text(collection_attempts)}: {last_error}"
                )
                failed_collections.append(error_msg)
                await self._log_collection_failure(
                    dut_id, "collection", collection_uri, str(last_error)
                )
                continue

            raw_members = (
                collection_data.get("Members", [])
                if isinstance(collection_data, dict)
                else []
            )
            collection_member_error: Optional[str] = None
            collection_members_valid = True
            try:
                members, source_member_count, members_truncated = (
                    bound_redfish_collection_members(
                        raw_members,
                        field_name=f"collection {collection_uri} Members",
                        limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                    )
                )
            except ValueError:
                members = []
                source_member_count = 0
                members_truncated = False
                collection_members_valid = False
                collection_member_error = (
                    f"Collection {collection_uri} returned an invalid Members list"
                )
            if members_truncated:
                collection_member_error = (
                    f"Collection {collection_uri} advertised {source_member_count} "
                    f"members; processing the first "
                    f"{self.MAX_FOLLOWED_COLLECTION_MEMBERS} within the safe "
                    "request-amplification limit"
                )
            matching_members_found += len(members)

            # Extract output pattern parameters using common function
            output_pattern, substitutions, filtered_kwargs = (
                self._extract_output_pattern_params(kwargs)
            )

            # Extract entity IDs from the collection_uri for substitutions
            # URI formats:
            #   /redfish/v1/Chassis/{chassis_id}/LogServices/XID/Entries
            #   /redfish/v1/Systems/{system_id}/LogServices/EventLog/Entries
            #   /redfish/v1/Managers/{manager_id}/LogServices/Journal/Entries
            # Extract entity IDs from collection URI for placeholder substitution
            extracted_ids = self._extract_entity_id_from_uri(collection_uri)
            substitutions.update(extracted_ids)

            if extracted_ids:
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Extracted entity IDs from collection URI: {extracted_ids}",
                    dut_id,
                )

            collection_saved = False
            collection_has_nested_failures = False
            if collection_member_error:
                failed_collections.append(collection_member_error)
                collection_has_nested_failures = True
                await self._log_collection_failure(
                    dut_id,
                    "collection",
                    collection_uri,
                    collection_member_error,
                )

            # Handle table format for any collection
            if is_table_format:
                # Create collection table instead of individual member files
                collector_id = kwargs.get("collector_id", "")
                table_title = kwargs.get(
                    "table_title",
                    f"{function_tag.replace('_', ' ').title()} Table",
                )
                table_files = await self._create_collection_table(
                    dut_id,
                    collection_data,
                    function_tag,
                    table_properties,
                    output_pattern,
                    substitutions,
                    collector_id,
                    table_title,
                )
                output_files.extend(table_files)
                if table_files:
                    collection_saved = True
                    await self._log_collection_success(
                        dut_id,
                        "collection",
                        collection_uri,
                        f"Created {len(table_files)} table files",
                    )
                else:
                    error_msg = f"Collection save failed for {collection_uri}: no table files created"
                    failed_collections.append(error_msg)
                    collection_has_nested_failures = True
                    await self._log_collection_failure(
                        dut_id,
                        "collection",
                        collection_uri,
                        "No table files created",
                    )
            else:
                # Save collection summary using common function (original behavior)
                collection_file = await self._save_data_with_common_pattern(
                    dut_id,
                    collection_data,
                    function_tag,
                    output_pattern=output_pattern,
                    substitutions={
                        **substitutions,
                        "member_id": "root",
                        "task_id": "root",
                        "index": "root",
                        "report_id": "collection_summary",
                    },
                    request_timing_operation_ids=self._request_timing_operation_id(
                        collection_request_metadata
                    ),
                    **filtered_kwargs,
                )
                if collection_file:
                    output_files.append(collection_file)
                    collection_saved = True
                    await self._log_collection_success(
                        dut_id, "collection", collection_uri, collection_file
                    )
                else:
                    error_msg = f"Collection save failed for {collection_uri}: no output file generated"
                    failed_collections.append(error_msg)
                    collection_has_nested_failures = True
                    await self._log_collection_failure(
                        dut_id,
                        "collection",
                        collection_uri,
                        "No output file generated",
                    )

            # Process members (skip for table format as members are processed in table creation)
            if not is_table_format:
                for i, member in enumerate(members):
                    # Apply the catalog-owned pacing policy between sequential
                    # member requests. Request overlap remains disabled here.
                    if i > 0:
                        await asyncio.sleep(request_delay)

                    # Use member_uri_pattern if provided, otherwise use the member's @odata.id
                    member_uri_pattern = kwargs.get("member_uri_pattern", "")
                    if member_uri_pattern:
                        # Extract member ID from the member's @odata.id (this is the chassis ID)
                        member_odata_id = member.get("@odata.id", "")
                        chassis_id = (
                            member_odata_id.split("/")[-1]
                            if member_odata_id
                            else f"member_{i}"
                        )

                        # Build URI using the pattern and chassis ID
                        member_uri = member_uri_pattern.replace(
                            "{chassis_id}", chassis_id
                        )
                        # Use chassis_id as member_id for file naming
                        member_id = chassis_id
                    else:
                        member_uri = member.get("@odata.id", "")
                        member_id = (
                            member_uri.split("/")[-1] if member_uri else f"member_{i}"
                        )

                    if member_uri and not validate_redfish_uri(member_uri):
                        continue
                    if (
                        member_uri
                        and not member_uri_pattern
                        and not redfish_uri_is_collection_member(
                            member_uri, collection_uri
                        )
                    ):
                        # Response-derived only: a catalog-authored
                        # member_uri_pattern is not required to sit beneath the
                        # collection it was discovered from.
                        await self._log_runtime(
                            "WARNING",
                            "RedfishService",
                            "Skipping advertised member that is not beneath "
                            f"collection {collection_uri}",
                            dut_id,
                        )
                        continue
                    if member_uri:
                        # Try member collection with retries
                        member_success = False
                        member_data = None
                        member_request_metadata: Dict[str, Any] = {}
                        member_last_error = None
                        member_attempts = 0

                        for member_retry_attempt in range(max_retries + 1):
                            member_attempts = member_retry_attempt + 1
                            if member_retry_attempt > 0:
                                await self._log_runtime(
                                    "WARNING",
                                    "RedfishService",
                                    f"Retrying member collection for {member_uri} (attempt {member_retry_attempt + 1}/{max_retries + 1})",
                                    dut_id,
                                )
                                await asyncio.sleep(retry_delay)

                            (
                                member_success,
                                member_data,
                                member_request_metadata,
                            ) = await self.dispatch_request(
                                dut_id,
                                "GET",
                                member_uri,
                                error_context=f"get member {member_uri}",
                            )

                            if member_success:
                                break
                            else:
                                member_last_error = member_data
                                await self._log_runtime(
                                    "WARNING",
                                    "RedfishService",
                                    f"Member collection attempt {member_retry_attempt + 1} failed for {member_uri}: {member_data}",
                                    dut_id,
                                )
                                if not self._redfish_get_failure_is_retryable(
                                    member_data, member_request_metadata
                                ):
                                    await self._log_runtime(
                                        "DEBUG",
                                        "RedfishService",
                                        f"Not retrying terminal member response for {member_uri}",
                                        dut_id,
                                    )
                                    break

                        if member_success:
                            # member_id was already set correctly above when building the URI
                            # Extract report_id from the member data if available (like original implementation)
                            report_id = member_data.get("Id", member_id)

                            # Check if member_uri_pattern is provided and extract variable name
                            member_uri_pattern = kwargs.get("member_uri_pattern", "")
                            if (
                                member_uri_pattern
                                and "{chassis_id}" in member_uri_pattern
                            ):
                                # Use chassis_id for substitutions when member_uri_pattern contains {chassis_id}
                                member_substitutions = {
                                    **substitutions,
                                    "chassis_id": member_id,
                                    "member_id": member_id,
                                    "task_id": member_id,
                                    "index": str(i),
                                    "report_id": report_id,
                                }
                            else:
                                # Default substitutions
                                member_substitutions = {
                                    **substitutions,
                                    "member_id": member_id,
                                    "task_id": member_id,
                                    "index": str(i),
                                    "report_id": report_id,
                                }

                            member_file = await self._save_data_with_common_pattern(
                                dut_id,
                                member_data,
                                function_tag,
                                output_pattern=output_pattern,
                                substitutions=member_substitutions,
                                request_timing_operation_ids=self._request_timing_operation_id(
                                    member_request_metadata
                                ),
                                **filtered_kwargs,
                            )
                            if member_file:
                                output_files.append(member_file)
                                member_successes += 1
                                await self._log_collection_success(
                                    dut_id, "member", member_uri, member_file
                                )
                            else:
                                member_failures += 1
                                collection_has_nested_failures = True
                                error_msg = f"Member save failed for {member_uri}: no output file generated"
                                failed_collections.append(error_msg)
                                await self._log_collection_failure(
                                    dut_id,
                                    "member",
                                    member_uri,
                                    "No output file generated",
                                )

                            # Handle additional member collections (e.g., CertChain for certificates)
                            additional_collections = kwargs.get(
                                "additional_member_collections", []
                            )
                            if additional_collections and isinstance(
                                additional_collections, list
                            ):
                                await self._log_runtime(
                                    "DEBUG",
                                    "RedfishService",
                                    f"Processing {len(additional_collections)} additional member collections for {member_uri}",
                                    dut_id,
                                )

                                # Smart filtering: Check if this member actually has certificate data
                                # before trying to collect additional certificate endpoints
                                should_collect_additional = True
                                if "Certificates" in member_uri and "CertChain" in str(
                                    additional_collections
                                ):
                                    # Check if the member data indicates certificates are available
                                    members_count = member_data.get(
                                        "Members@odata.count", 0
                                    )
                                    if members_count == 0:
                                        await self._log_runtime(
                                            "DEBUG",
                                            "RedfishService",
                                            f"Skipping additional certificate collection for {member_uri} - no certificate members (count: {members_count})",
                                            dut_id,
                                        )
                                        should_collect_additional = False

                                if should_collect_additional:
                                    for additional_config in additional_collections:
                                        if not isinstance(additional_config, dict):
                                            continue

                                        additional_uri_pattern = additional_config.get(
                                            "uri_pattern", ""
                                        )
                                        additional_suffix = additional_config.get(
                                            "output_suffix", ""
                                        )
                                        linked_resources = additional_config.get(
                                            "linked_resources", []
                                        )

                                        if not additional_uri_pattern:
                                            continue

                                        # Build the additional URI using the same substitutions
                                        additional_uri = additional_uri_pattern
                                        for (
                                            key,
                                            value,
                                        ) in member_substitutions.items():
                                            additional_uri = additional_uri.replace(
                                                f"{{{key}}}", str(value)
                                            )

                                        await self._log_runtime(
                                            "DEBUG",
                                            "RedfishService",
                                            f"Collecting additional member data from: {additional_uri}",
                                            dut_id,
                                        )

                                        # Try to collect additional member data with retries
                                        additional_success = False
                                        additional_data = None
                                        additional_request_metadata: Dict[str, Any] = {}
                                        additional_last_error = None
                                        additional_attempts = 0

                                        # Use reduced retries for certificate endpoints that often fail
                                        additional_max_retries = max_retries
                                        if "CertChain" in additional_uri:
                                            additional_max_retries = min(
                                                1, max_retries
                                            )  # Only 1 retry for CertChain
                                            await self._log_runtime(
                                                "DEBUG",
                                                "RedfishService",
                                                f"Using reduced retries ({additional_max_retries}) for certificate endpoint: {additional_uri}",
                                                dut_id,
                                            )

                                        for additional_retry_attempt in range(
                                            additional_max_retries + 1
                                        ):
                                            additional_attempts = (
                                                additional_retry_attempt + 1
                                            )
                                            if additional_retry_attempt > 0:
                                                await self._log_runtime(
                                                    "WARNING",
                                                    "RedfishService",
                                                    f"Retrying additional collection for {additional_uri} (attempt {additional_retry_attempt + 1}/{additional_max_retries + 1})",
                                                    dut_id,
                                                )
                                                await asyncio.sleep(retry_delay)

                                            (
                                                additional_success,
                                                additional_data,
                                                additional_request_metadata,
                                            ) = await self.dispatch_request(
                                                dut_id,
                                                "GET",
                                                additional_uri,
                                                error_context=f"get additional member data {additional_uri}",
                                            )

                                            if additional_success:
                                                break

                                            additional_last_error = additional_data
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                f"Additional collection attempt {additional_retry_attempt + 1} failed for {additional_uri}: {additional_data}",
                                                dut_id,
                                            )
                                            if not self._redfish_get_failure_is_retryable(
                                                additional_data,
                                                additional_request_metadata,
                                            ):
                                                await self._log_runtime(
                                                    "DEBUG",
                                                    "RedfishService",
                                                    "Not retrying terminal additional-member "
                                                    f"response for {additional_uri}",
                                                    dut_id,
                                                )
                                                break

                                        if not additional_success:
                                            # Log additional collection failure but don't fail the main collection
                                            error_msg = (
                                                "Additional member collection failed for "
                                                f"{additional_uri} after "
                                                f"{_attempt_count_text(additional_attempts)}: "
                                                f"{additional_last_error}"
                                            )
                                            failed_collections.append(error_msg)
                                            additional_member_failures += 1
                                            collection_has_nested_failures = True
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                error_msg,
                                                dut_id,
                                            )
                                            continue

                                        additional_output_pattern = (
                                            _append_output_suffix(
                                                output_pattern,
                                                additional_suffix,
                                            )
                                        )

                                        additional_file = await self._save_data_with_common_pattern(
                                            dut_id,
                                            additional_data,
                                            function_tag,
                                            output_pattern=additional_output_pattern,
                                            substitutions=member_substitutions,
                                            request_timing_operation_ids=self._request_timing_operation_id(
                                                additional_request_metadata
                                            ),
                                            **filtered_kwargs,
                                        )
                                        if additional_file:
                                            output_files.append(additional_file)
                                            additional_member_successes += 1
                                            await self._log_collection_success(
                                                dut_id,
                                                "additional_member",
                                                additional_uri,
                                                additional_file,
                                            )
                                        else:
                                            error_msg = f"Additional member save failed for {additional_uri}: no output file generated"
                                            failed_collections.append(error_msg)
                                            additional_member_failures += 1
                                            collection_has_nested_failures = True
                                            await self._log_collection_failure(
                                                dut_id,
                                                "additional_member",
                                                additional_uri,
                                                "No output file generated",
                                            )

                                        if linked_resources and isinstance(
                                            linked_resources, list
                                        ):
                                            for linked_resource in linked_resources:
                                                if not isinstance(
                                                    linked_resource, dict
                                                ):
                                                    continue

                                                linked_uri_path = linked_resource.get(
                                                    "uri_path"
                                                )
                                                linked_suffix = linked_resource.get(
                                                    "output_suffix", ""
                                                )

                                                if not linked_uri_path:
                                                    continue

                                                linked_uri = self._extract_nested_value(
                                                    additional_data,
                                                    linked_uri_path,
                                                )

                                                if not linked_uri:
                                                    await self._log_runtime(
                                                        "DEBUG",
                                                        "RedfishService",
                                                        f"Skipping linked resource for {additional_uri}: path {linked_uri_path} not found",
                                                        dut_id,
                                                    )
                                                    continue

                                                if not validate_redfish_uri(linked_uri):
                                                    await self._log_runtime(
                                                        "DEBUG",
                                                        "RedfishService",
                                                        f"Skipping invalid linked resource URI: {linked_uri}",
                                                        dut_id,
                                                    )
                                                    continue

                                                await self._log_runtime(
                                                    "DEBUG",
                                                    "RedfishService",
                                                    f"Collecting linked member data from: {linked_uri}",
                                                    dut_id,
                                                )

                                                linked_success = False
                                                linked_data = None
                                                linked_request_metadata: Dict[
                                                    str, Any
                                                ] = {}
                                                linked_last_error = None
                                                linked_attempts = 0

                                                for linked_retry_attempt in range(
                                                    max_retries + 1
                                                ):
                                                    linked_attempts = (
                                                        linked_retry_attempt + 1
                                                    )
                                                    if linked_retry_attempt > 0:
                                                        await self._log_runtime(
                                                            "WARNING",
                                                            "RedfishService",
                                                            f"Retrying linked collection for {linked_uri} (attempt {linked_retry_attempt + 1}/{max_retries + 1})",
                                                            dut_id,
                                                        )
                                                        await asyncio.sleep(retry_delay)

                                                    (
                                                        linked_success,
                                                        linked_data,
                                                        linked_request_metadata,
                                                    ) = await self.dispatch_request(
                                                        dut_id,
                                                        "GET",
                                                        linked_uri,
                                                        error_context=f"get linked member data {linked_uri}",
                                                    )

                                                    if linked_success:
                                                        break

                                                    linked_last_error = linked_data
                                                    await self._log_runtime(
                                                        "WARNING",
                                                        "RedfishService",
                                                        f"Linked collection attempt {linked_retry_attempt + 1} failed for {linked_uri}: {linked_data}",
                                                        dut_id,
                                                    )
                                                    if not self._redfish_get_failure_is_retryable(
                                                        linked_data,
                                                        linked_request_metadata,
                                                    ):
                                                        await self._log_runtime(
                                                            "DEBUG",
                                                            "RedfishService",
                                                            "Not retrying terminal linked-member "
                                                            f"response for {linked_uri}",
                                                            dut_id,
                                                        )
                                                        break

                                                if not linked_success:
                                                    linked_member_failures += 1
                                                    collection_has_nested_failures = (
                                                        True
                                                    )
                                                    failed_collections.append(
                                                        "Linked member collection failed for "
                                                        f"{linked_uri} after "
                                                        f"{_attempt_count_text(linked_attempts)}: "
                                                        f"{linked_last_error}"
                                                    )
                                                    await self._log_runtime(
                                                        "WARNING",
                                                        "RedfishService",
                                                        "Linked member collection failed for "
                                                        f"{linked_uri} after "
                                                        f"{_attempt_count_text(linked_attempts)}: "
                                                        f"{linked_last_error}",
                                                        dut_id,
                                                    )
                                                    continue

                                                linked_output_pattern = (
                                                    _append_output_suffix(
                                                        additional_output_pattern,
                                                        linked_suffix,
                                                    )
                                                )

                                                linked_file = await self._save_data_with_common_pattern(
                                                    dut_id,
                                                    linked_data,
                                                    function_tag,
                                                    output_pattern=linked_output_pattern,
                                                    substitutions=member_substitutions,
                                                    request_timing_operation_ids=self._request_timing_operation_id(
                                                        linked_request_metadata
                                                    ),
                                                    **filtered_kwargs,
                                                )
                                                if linked_file:
                                                    output_files.append(linked_file)
                                                    linked_member_successes += 1
                                                    await self._log_collection_success(
                                                        dut_id,
                                                        "linked_member",
                                                        linked_uri,
                                                        linked_file,
                                                    )
                                                else:
                                                    error_msg = f"Linked member save failed for {linked_uri}: no output file generated"
                                                    failed_collections.append(error_msg)
                                                    linked_member_failures += 1
                                                    collection_has_nested_failures = (
                                                        True
                                                    )
                                                    await self._log_collection_failure(
                                                        dut_id,
                                                        "linked_member",
                                                        linked_uri,
                                                        "No output file generated",
                                                    )
                                else:
                                    await self._log_runtime(
                                        "DEBUG",
                                        "RedfishService",
                                        f"Skipped additional member collections for {member_uri} due to smart filtering",
                                        dut_id,
                                    )
                        else:
                            # Add specific error message for member collection failure
                            error_msg = (
                                f"Member collection failed for {member_uri} after "
                                f"{_attempt_count_text(member_attempts)}: "
                                f"{member_last_error}"
                            )
                            failed_collections.append(error_msg)
                            member_failures += 1
                            collection_has_nested_failures = True
                            await self._log_collection_failure(
                                dut_id,
                                "member",
                                member_uri,
                                str(member_last_error),
                            )

            if collection_saved:
                if collection_has_nested_failures:
                    partial_collections.append(collection_uri)
                    if collection_members_valid:
                        success_bearing_partial_collections.append(collection_uri)
                else:
                    successful_collections.append(collection_uri)

        # Determine overall success based on results
        successful_operations = len(successful_collections)
        partial_operations = len(partial_collections)
        total_operations = len(uri_list)
        error_messages = (
            failed_collections  # failed_collections already contains error messages
        )

        # If no collections succeeded and no specific error messages, add a generic one
        if successful_operations == 0 and not error_messages:
            error_messages = [
                f"All collection operations failed for {len(uri_list)} URIs"
            ]

        # Calculate certificate-specific statistics if this is a certificate collection
        cert_successful = 0
        cert_failed = 0
        cert_skipped = 0
        additional_details = {}
        summary_successful_operations = successful_operations + len(
            success_bearing_partial_collections
        )
        summary_failed_operations = max(
            0, total_operations - summary_successful_operations
        )

        if partial_operations:
            additional_details["status_note_override"] = (
                f"Partial success: {summary_successful_operations}/"
                f"{total_operations} collection target(s) produced artifacts; "
                f"{partial_operations} target(s) had nested sub-resource "
                "failures."
            )

        if "certificates" in function_tag.lower() or "cert" in function_tag.lower():
            cert_successful = len([f for f in output_files if "_certchain.json" in f])
            cert_failed = len([f for f in failed_collections if "CertChain" in f])
            cert_skipped = len(
                [f for f in failed_collections if "no certificate members" in f]
            )

            additional_details = {
                "Certificate chains collected": cert_successful,
                "Certificate chains failed": cert_failed,
                "Certificate chains skipped (no certificates)": cert_skipped,
            }

        # Check if summary generation is enabled
        generate_summary = kwargs.get("generate_summary", True)
        summary_format = kwargs.get("summary_format", "both")
        collector_config = kwargs.get("collector_config", {})
        summary_messages = collector_config.get("summary_messages", {})

        if generate_summary:
            # Add custom summary message based on results
            if summary_messages:
                if summary_successful_operations == 0 and total_operations > 0:
                    custom_message = summary_messages.get(
                        "failure", "Collection failed"
                    )
                elif partial_operations > 0 or (
                    summary_successful_operations < total_operations
                ):
                    custom_message = summary_messages.get(
                        "partial_success",
                        "Collection completed with some failures",
                    )
                elif (
                    summary_successful_operations == total_operations
                    and total_operations > 0
                ):
                    custom_message = summary_messages.get(
                        "success", "Collection completed successfully"
                    )
                elif total_operations == 0:
                    custom_message = summary_messages.get(
                        "empty_results", "No operations performed"
                    )
                else:
                    custom_message = summary_messages.get(
                        "no_certificates", "No certificates found"
                    )

                additional_details["Summary"] = custom_message

            # Handle summary generation using helper function
            output_files = await self._handle_collection_summary_generation(
                dut_id=dut_id,
                function_tag=function_tag,
                collection_name=collection_name,
                total_operations=total_operations,
                successful_operations=summary_successful_operations,
                failed_operations=summary_failed_operations,
                output_files=output_files,
                additional_details=additional_details,
                kwargs=kwargs,
                collection_type="collection_with_members",
                ignore_empty_results=True,
            )

        # Prepare additional context with certificate-specific details
        additional_context = {
            "collections_processed": len(uri_list),
            "successful_collections": successful_collections,
            "partial_collections": partial_collections,
            "failed_collections": failed_collections,
            "member_requests_successful": member_successes,
            "member_requests_failed": member_failures,
            "additional_member_requests_successful": additional_member_successes,
            "additional_member_requests_failed": additional_member_failures,
            "linked_member_requests_successful": linked_member_successes,
            "linked_member_requests_failed": linked_member_failures,
            "request_delay_seconds": request_delay,
        }

        if not uri_list and not complete_on_empty_targets:
            # A summary records why discovery produced no collection targets; it
            # is evidence of a skip, not primary data that can promote the
            # collector to success during finalization.
            additional_context["intentional_evidence_only_skip"] = True

        if skip_if_no_matching_members:
            additional_context["matching_members_found"] = matching_members_found
            if (
                matching_members_found == 0
                and successful_collections
                and not partial_collections
                and not failed_collections
            ):
                empty_reason = (
                    f"No member resources found for {function_tag}; "
                    "endpoint query completed successfully"
                )
                additional_context.update(
                    {
                        "status": (
                            "success" if complete_on_empty_matches else "skipped"
                        ),
                        "reason": empty_reason,
                    }
                )
                if not complete_on_empty_matches:
                    additional_context["intentional_evidence_only_skip"] = True

        if partial_operations > 0 and total_operations > 0:
            partial_reason = f"Partial success: {summary_successful_operations}/{total_operations} collection_with_members targets produced artifacts; {partial_operations} had nested sub-resource failures."
            if error_messages:
                partial_reason += "\n" + self._format_error_messages(
                    error_messages, "collection_with_members", is_partial=True
                )
            additional_context.update({"status": "partial", "reason": partial_reason})

        # Add certificate-specific details if this is a certificate collection
        if "certificates" in function_tag.lower() or "cert" in function_tag.lower():
            additional_context.update(
                {
                    "certificate_chains_collected": cert_successful,
                    "certificate_chains_failed": cert_failed,
                    "certificate_chains_skipped": cert_skipped,
                }
            )

        return await self._create_standardized_collector_result(
            dut_id=dut_id,
            # A valid target that persisted its collection document completed
            # the top-level operation even when a nested member raced away or
            # failed. An invalid Members envelope remains diagnostic-only and
            # cannot become success merely because its raw root was retained.
            successful_operations=summary_successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="collection_with_members",
            additional_context=additional_context,
        )

    @staticmethod
    def _normalize_collection_request_delay(value: Any) -> float:
        """
        Validate the pacing delay for sequential collection-member requests.

        The collector catalog may lower the legacy one-second delay for
        read-only endpoints without enabling request overlap. A finite upper
        bound prevents malformed or user-supplied catalog data from creating
        an unbounded sleep.

        Args:
            value: Catalog-provided delay in seconds.

        Returns:
            The validated delay as a floating-point number of seconds.

        Raises:
            ValueError: If the delay is boolean, non-numeric, non-finite,
                negative, or greater than 30 seconds.
        """

        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("request delay must be a number")
        normalized = float(value)
        if not math.isfinite(normalized) or normalized < 0 or normalized > 30:
            raise ValueError("request delay must be finite and between 0 and 30")
        return normalized

    async def _handle_existing_dumps_collection(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Handle existing dumps collection.

        Filter presence is authoritative even when validation found no entities.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle existing dumps collection.
        """
        try:
            output_files = []
            metadata_files = []
            failed_entities = []
            successful_entities = []
            partial_entities = []
            error_messages = []

            entity_uri = self.get_configured_uri(dut_id, entity_type)
            await self._log_collection_start(dut_id, "existing_dumps", entity_uri)

            # Filter presence is authoritative even when validation found no entities.
            filtered_systems = kwargs.get("filtered_systems")
            filtered_managers = kwargs.get("filtered_managers")
            filtered_chassis = kwargs.get("filtered_chassis")

            if filtered_systems is not None and entity_type == "Systems":
                # Use filtered systems from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_systems)} filtered systems from validation: {[sys['id'] for sys in filtered_systems]}",
                    dut_id,
                )
                entity_ids = [sys["id"] for sys in filtered_systems]
            elif filtered_managers is not None and entity_type == "Managers":
                # Use filtered managers from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_managers)} filtered managers from validation: {[mgr['id'] for mgr in filtered_managers]}",
                    dut_id,
                )
                entity_ids = [mgr["id"] for mgr in filtered_managers]
            elif filtered_chassis is not None and entity_type == "Chassis":
                # Use filtered chassis from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_chassis)} filtered chassis from validation: {[chassis['id'] for chassis in filtered_chassis]}",
                    dut_id,
                )
                entity_ids = [chassis["id"] for chassis in filtered_chassis]
            else:
                # Get entities - fallback to fetching all entities
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No filtered {entity_type.lower()} found in context, fetching all {entity_type}",
                    dut_id,
                )
                success, entities, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    entity_uri,
                    error_context=f"get {entity_type}",
                )

                if not success:
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[f"Failed to get {entity_type}: {entities}"],
                        operation_name="entity_discovery",
                        additional_context={"entity_type": entity_type},
                    )

                raw_entity_members = (
                    entities.get("Members", []) if isinstance(entities, dict) else []
                )
                try:
                    entity_members, source_count, truncated = (
                        bound_redfish_collection_members(
                            raw_entity_members,
                            field_name=f"{entity_type} discovery Members",
                            limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                        )
                    )
                except ValueError:
                    entity_members = []
                    error_messages.append(
                        f"{entity_type} discovery returned an invalid Members list"
                    )
                else:
                    if truncated:
                        error_messages.append(
                            f"{entity_type} discovery advertised {source_count} "
                            f"members; processing the first "
                            f"{self.MAX_FOLLOWED_COLLECTION_MEMBERS} within the "
                            "safe request-amplification limit"
                        )
                entity_ids = [
                    entity.get("@odata.id", "").split("/")[-1]
                    for entity in entity_members
                    if isinstance(entity, dict)
                ]

            if not entity_ids:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[f"No {entity_type} found"],
                    operation_name="existing_dumps_collection",
                    additional_context={"entity_type": entity_type},
                )

            # Process entities concurrently for better performance
            async def _process_entity_dumps(
                dut_id: str, entity_id: str, **kwargs
            ) -> Tuple[List[str], List[str], List[str], str]:
                """
                Process entity dumps.

                The implementation uses ``dut_id``, ``entity_id``, and
                ``kwargs`` to process entity dumps. Terminal status is emitted
                only after entity dumps and its owned cleanup have completed.
                Owned asynchronous work is awaited before return, so completion
                does not leave an unobserved task behind.

                Args:
                    dut_id: Stable DUT identifier used to correlate
                        configuration, logs, and results.
                    entity_id: Stable entity identifier used to correlate
                        configuration, logs, and results.
                    kwargs: Additional named values forwarded without changing
                        their keys.

                Returns:
                    A tuple containing ``entity output files``, ``entity
                    metadata files``, ``entity error messages``, and ``status
                    value`` in that order. The status is ``success``,
                    ``partial``, or ``error``.
                """
                entity_output_files = []
                entity_metadata_files = []
                entity_error_messages = []

                await self._log_collection_start(
                    dut_id, "entity_dumps", f"{entity_type}/{entity_id}"
                )

                # Get dump service
                entity_base_uri = self.get_configured_uri(dut_id, entity_type)
                success, dump_service, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    f"{entity_base_uri}/{entity_id}/LogServices/{log_service}",
                    error_context=f"get dump service for {entity_type} {entity_id}",
                )

                if not success:
                    await self._log_collection_failure(
                        dut_id,
                        "entity_dumps",
                        f"{entity_type}/{entity_id}",
                        "Dump service not found",
                    )
                    return (
                        entity_output_files,
                        entity_metadata_files,
                        entity_error_messages,
                        "error",
                    )

                # Add small delay between dump service and entries requests
                await asyncio.sleep(
                    1
                )  # 1000ms delay between dump service and entries requests

                # Get dump entries
                success, dump_entries, entries_metadata = await self.dispatch_request(
                    dut_id,
                    "GET",
                    f"{entity_base_uri}/{entity_id}/LogServices/{log_service}/Entries",
                    error_context=f"get dump entries for {entity_type} {entity_id}",
                )

                if success:
                    # Extract output pattern parameters using common function
                    output_pattern, substitutions, filtered_kwargs = (
                        self._extract_output_pattern_params(kwargs)
                    )

                    # Save entries list using entries_pattern
                    entries_file = await self._save_data_with_common_pattern(
                        dut_id,
                        dump_entries,
                        "entries",
                        output_pattern=kwargs.get("entries_pattern", ""),
                        substitutions={
                            **substitutions,
                            "manager_id": entity_id,
                        },
                        request_timing_operation_ids=self._request_timing_operation_id(
                            entries_metadata
                        ),
                        **filtered_kwargs,
                    )
                    if entries_file:
                        entity_metadata_files.append(entries_file)
                        await self._log_collection_success(
                            dut_id,
                            "entries",
                            f"{entity_type}/{entity_id}",
                            entries_file,
                        )
                    else:
                        entity_error_messages.append(
                            f"Failed to save dump entries metadata for {entity_type} {entity_id}"
                        )

                    # Collect all dump entries with AdditionalDataURI for binary download
                    dump_entries_with_attachments = []
                    raw_dump_members = (
                        dump_entries.get("Members", [])
                        if isinstance(dump_entries, dict)
                        else []
                    )
                    try:
                        dump_members, source_count, truncated = (
                            bound_redfish_collection_members(
                                raw_dump_members,
                                field_name=(
                                    f"{entity_type} {entity_id} dump entry Members"
                                ),
                                limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                            )
                        )
                    except ValueError:
                        dump_members = []
                        entity_error_messages.append(
                            f"Dump entries for {entity_type} {entity_id} returned "
                            "an invalid Members list"
                        )
                    else:
                        if truncated:
                            entity_error_messages.append(
                                f"Dump entries for {entity_type} {entity_id} "
                                f"advertised {source_count} members; processing "
                                f"the first {self.MAX_FOLLOWED_COLLECTION_MEMBERS} "
                                "within the safe request-amplification limit"
                            )
                    for member in dump_members:
                        if not isinstance(member, dict):
                            entity_error_messages.append(
                                f"Dump entries for {entity_type} {entity_id} "
                                "contained a non-object member"
                            )
                            continue
                        additional_data_uri = member.get("AdditionalDataURI")
                        if additional_data_uri:
                            dump_entries_with_attachments.append(
                                {
                                    "entry_id": member.get("Id", "unknown"),
                                    "attachment_uri": additional_data_uri,
                                    "entry_data": member,
                                }
                            )
                        else:
                            entity_error_messages.append(
                                f"Dump entry {member.get('Id', 'unknown')} for "
                                f"{entity_type} {entity_id} has no AdditionalDataURI"
                            )

                    if dump_entries_with_attachments:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Found {len(dump_entries_with_attachments)} dump entries with attachments for {entity_type} {entity_id}",
                            dut_id,
                        )

                        # Make concurrent requests for binary dump attachments
                        attachment_tasks = []
                        for entry in dump_entries_with_attachments:
                            task = self.dispatch_request(
                                dut_id,
                                "GET",
                                entry["attachment_uri"],
                                get_raw_content=True,
                                error_context=f"get binary dump from {entry['attachment_uri']}",
                            )
                            attachment_tasks.append(task)

                        # Existing dump attachments are multi-megabyte transfers. Use the
                        # dump-specific boundary so a generic Redfish request burst cannot
                        # overload a BMC while the transport owns bounded retry/backoff.
                        semaphore = self._get_dut_semaphore(dut_id, "dumps")

                        async def limited_request(task):
                            """
                            Return the limited request.

                            The implementation uses ``task`` to produce the
                            limited request. Owned asynchronous work is awaited
                            before return, so completion does not leave an
                            unobserved task behind.

                            Args:
                                task: Task consumed while the function attempts
                                    to produce the limited request.

                            Returns:
                                The validated ``task``.
                            """
                            async with semaphore:
                                return await task

                        limited_tasks = [
                            limited_request(task) for task in attachment_tasks
                        ]
                        attachment_results = await asyncio.gather(
                            *limited_tasks, return_exceptions=True
                        )

                        # Process results and save binary files
                        for i, result in enumerate(attachment_results):
                            # Handle exceptions from asyncio.gather with return_exceptions=True
                            if isinstance(result, Exception):
                                entry = dump_entries_with_attachments[i]
                                entry_id = entry["entry_id"]
                                await self._log_runtime(
                                    "WARN",
                                    "RedfishService",
                                    f"Failed to download binary dump for {entity_type}/{entity_id}/{entry_id}: {str(result)}",
                                    dut_id,
                                )
                                entity_error_messages.append(
                                    f"Failed to download binary dump for "
                                    f"{entity_type}/{entity_id}/{entry_id}"
                                )
                                continue

                            # Unpack successful results
                            try:
                                success, binary_data, metadata = result
                                entry = dump_entries_with_attachments[i]
                                entry_id = entry["entry_id"]
                                if success and isinstance(
                                    binary_data, (bytes, StreamedRedfishBody)
                                ):
                                    timestamped_output_pattern = (
                                        self._add_utc_timestamp_to_archive_pattern(
                                            output_pattern
                                        )
                                    )
                                    # Save binary dump file using common function
                                    dump_file = await self._save_data_with_common_pattern(
                                        dut_id,
                                        binary_data,
                                        f"dump_{entry_id}",
                                        output_pattern=timestamped_output_pattern,
                                        substitutions={
                                            **substitutions,
                                            "entry_id": entry_id,
                                            "manager_id": entity_id,
                                        },
                                        request_timing_operation_ids=self._request_timing_operation_id(
                                            metadata
                                        ),
                                        **filtered_kwargs,
                                    )
                                    if dump_file:
                                        entity_output_files.append(dump_file)
                                        await self._log_collection_success(
                                            dut_id,
                                            "binary_dump",
                                            f"{entity_type}/{entity_id}/{entry_id}",
                                            dump_file,
                                        )
                                    else:
                                        if isinstance(binary_data, StreamedRedfishBody):
                                            binary_data.cleanup()
                                        entity_error_messages.append(
                                            f"Failed to save binary dump for "
                                            f"{entity_type}/{entity_id}/{entry_id}"
                                        )
                                else:
                                    entity_error_messages.append(
                                        f"Failed to download binary dump for "
                                        f"{entity_type}/{entity_id}/{entry_id}"
                                    )
                            except (ValueError, TypeError) as e:
                                entry = dump_entries_with_attachments[i]
                                entry_id = entry["entry_id"]
                                await self._log_runtime(
                                    "WARN",
                                    "RedfishService",
                                    f"Failed to unpack result for {entity_type}/{entity_id}/{entry_id}: {str(e)}",
                                    dut_id,
                                )
                                entity_error_messages.append(
                                    f"Failed to process binary dump response for "
                                    f"{entity_type}/{entity_id}/{entry_id}"
                                )
                # Entries metadata is supporting evidence, not a substitute for
                # requested dump attachments.  An entity with at least one saved
                # attachment and at least one failed attachment is still useful,
                # but must be reported as partial rather than promoted to success
                # or collapsed into a total failure.  A genuinely empty entries
                # collection remains a metadata-only success.
                if entity_output_files and entity_error_messages:
                    entity_status = "partial"
                elif entity_output_files or (
                    entity_metadata_files and not entity_error_messages
                ):
                    entity_status = "success"
                else:
                    entity_status = "error"
                return (
                    entity_output_files,
                    entity_metadata_files,
                    entity_error_messages,
                    entity_status,
                )

            # Process each entity
            for i, entity_id in enumerate(entity_ids):
                # Add delay between entity processing to prevent BMC overload
                if i > 0:
                    await asyncio.sleep(1)  # 1000ms delay between entities

                (
                    entity_files,
                    entity_metadata_files,
                    entity_errors,
                    entity_status,
                ) = await _process_entity_dumps(dut_id, entity_id, **kwargs)
                output_files.extend(entity_files)
                metadata_files.extend(entity_metadata_files)
                error_messages.extend(entity_errors)
                if entity_status == "success":
                    successful_entities.append(entity_id)
                elif entity_status == "partial":
                    partial_entities.append(entity_id)
                else:
                    failed_entities.append(entity_id)

            # Use the base collector's standardized result function
            successful_operations = len(successful_entities) + len(partial_entities)
            total_operations = len(entity_ids)
            for entity_id in failed_entities:
                if not any(
                    entity_type in message and entity_id in message
                    for message in error_messages
                ):
                    error_messages.append(f"Entity {entity_id} failed")

            additional_context = {
                "entity_type": entity_type,
                "entities_processed": len(entity_ids),
                "successful_entities": successful_entities,
                "partial_entities": partial_entities,
                "failed_entities": failed_entities,
                "metadata_files": metadata_files,
            }
            if partial_entities:
                additional_context["status"] = "partial"

            return await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="entities",
                additional_context=additional_context,
            )

        except Exception as e:
            entity_uri = self.get_configured_uri(dut_id, entity_type)
            await self._log_collection_failure(
                dut_id, "existing_dumps", entity_uri, str(e)
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[f"Exception in existing dumps collection: {str(e)}"],
                operation_name="existing_dumps_collection",
                additional_context={"entity_type": entity_type},
            )

    async def _handle_sequential_collection(
        self, dut_id: str, uri_list: List[str], function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Handle sequential data collection.

        Extract output pattern parameters using common function.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle sequential collection.
        """
        output_files = []
        failed_uris = []
        successful_uris = []

        for i, uri in enumerate(uri_list):
            await self._log_collection_start(dut_id, "sequential", uri)

            success, data, request_metadata = await self.dispatch_request(
                dut_id, "GET", uri
            )

            if success:
                # Extract output pattern parameters using common function
                output_pattern, substitutions, filtered_kwargs = (
                    self._extract_output_pattern_params(kwargs)
                )

                # Use common data saving function with sequence-specific substitutions
                file_path = await self._save_data_with_common_pattern(
                    dut_id,
                    data,
                    function_tag,
                    output_pattern=output_pattern,
                    substitutions={
                        **substitutions,
                        "sequence": str(i + 1),
                        "index": str(i),
                    },
                    request_timing_operation_ids=self._request_timing_operation_id(
                        request_metadata
                    ),
                    **filtered_kwargs,
                )

                if file_path:
                    output_files.append(file_path)
                    successful_uris.append(uri)
                    await self._log_collection_success(
                        dut_id, "sequential", uri, file_path
                    )
                else:
                    failed_uris.append(f"Failed to save data for {uri}")
                    await self._log_collection_failure(
                        dut_id, "sequential", uri, "Failed to save data"
                    )
            else:
                failed_uris.append(f"GET request failed for {uri}: {data}")
                await self._log_collection_failure(dut_id, "sequential", uri, str(data))

        # Determine overall success based on results
        successful_operations = len(successful_uris)
        total_operations = len(uri_list)
        error_messages = failed_uris  # failed_uris already contains error messages

        return await self._create_standardized_collector_result(
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="sequential_collection",
            additional_context={
                "sequence_count": len(uri_list),
                "successful_uris": successful_uris,
                "failed_uris": failed_uris,
            },
        )

    async def _handle_uri_list_collection(
        self,
        dut_id: str,
        entity_type: str,
        uri_list: List[str],
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Handle URI list collection.

        Extract output pattern parameters using common function.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle URI list collection.
        """
        output_files = []
        diagnostic_files = []
        failed_uris = []
        successful_uris = []
        absent_uris = []

        for i, uri in enumerate(uri_list):
            if kwargs.get("streaming_time_filtered", False):
                uri = await self._append_streaming_time_filter(dut_id, uri)
            await self._log_collection_start(dut_id, "uri_list", uri)

            success, data, request_metadata = await self.dispatch_request(
                dut_id, "GET", uri
            )

            if success:
                if not self._has_meaningful_response_body(data):
                    empty_body_message = (
                        f"GET returned an empty response body for {uri}"
                    )
                    failed_uris.append(empty_body_message)
                    await self._log_collection_failure(
                        dut_id, "uri_list", uri, "Empty response body"
                    )
                    continue

                # Extract output pattern parameters using common function
                output_pattern, substitutions, filtered_kwargs = (
                    self._extract_output_pattern_params(kwargs)
                )

                # Extract entity ID from URI for substitutions
                entity_id = self._extract_entity_id_from_uri(uri, entity_type)

                # Use common data saving function with URI-specific substitutions
                # Create substitutions dict with null check for entity_type
                uri_substitutions = {
                    **substitutions,
                    "log_id": str(i),
                    "index": str(i),
                    "uri": uri,
                }

                # Populate canonical entity placeholders ({chassis_id},
                # {manager_id}, {system_id}) parsed from the URI so output_pattern
                # placeholders resolve regardless of entity_type pluralization
                # (entity_type.lower() yields "managers_id"/"systems_id", which
                # would not match singular placeholders).
                uri_substitutions.update(self._extract_entity_id_from_uri(uri))

                # Only add entity_type-based substitution if entity_type is not None
                if entity_type:
                    uri_substitutions[f"{entity_type.lower()}_id"] = entity_id

                certificate_value = (
                    data.get("CertificateString") if isinstance(data, dict) else None
                )
                certificate_absent = isinstance(
                    certificate_value, str
                ) and certificate_value.strip().lower() in {
                    "certicate not found",
                    "certificate not found",
                }
                if certificate_absent:
                    diagnostic_pattern = output_pattern or f"{function_tag}_{i}.json"
                    if not diagnostic_pattern.startswith("diagnostic/"):
                        diagnostic_pattern = f"diagnostic/{diagnostic_pattern}"
                    file_path = await self._save_data_with_common_pattern(
                        dut_id,
                        data,
                        function_tag,
                        output_pattern=diagnostic_pattern,
                        substitutions=uri_substitutions,
                        request_timing_operation_ids=(
                            self._request_timing_operation_id(request_metadata)
                        ),
                        **filtered_kwargs,
                    )
                    if file_path:
                        diagnostic_files.append(file_path)
                        absent_uris.append(uri)
                    else:
                        failed_uris.append(
                            f"Failed to save certificate absence evidence for {uri}"
                        )
                    continue

                file_path = await self._save_data_with_common_pattern(
                    dut_id,
                    data,
                    function_tag,
                    output_pattern=output_pattern,
                    substitutions=uri_substitutions,
                    request_timing_operation_ids=self._request_timing_operation_id(
                        request_metadata
                    ),
                    **filtered_kwargs,
                )

                if file_path:
                    output_files.append(file_path)
                    successful_uris.append(uri)
                    await self._log_collection_success(
                        dut_id, "uri_list", uri, file_path
                    )
                else:
                    failed_uris.append(f"Failed to save data for {uri}")
                    await self._log_collection_failure(
                        dut_id, "uri_list", uri, "Failed to save data"
                    )
            else:
                failed_uris.append(f"GET request failed for {uri}: {data}")
                await self._log_collection_failure(dut_id, "uri_list", uri, str(data))

        # Handle empty URI list case - this should be treated as "skipped" not "error"
        if not uri_list:
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[],
                operation_name="uri_list_collection",
                additional_context={
                    "entity_type": entity_type,
                    "uri_count": 0,
                    "status": "skipped",
                    "reason": "No URIs provided in configuration - collector skipped",
                },
            )

        # Determine overall success based on results
        successful_operations = len(successful_uris)
        total_operations = len(uri_list)
        error_messages = failed_uris  # failed_uris already contains error messages

        absence_context: Dict[str, Any] = {}
        if absent_uris and not successful_uris and not failed_uris:
            absence_context = {
                "status": "skipped",
                "reason": "Certificate chain is not present on the target",
            }

        return await self._create_standardized_collector_result(
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="uri_list_collection",
            additional_context={
                "entity_type": entity_type,
                "uri_count": len(uri_list),
                "successful_uris": successful_uris,
                "failed_uris": failed_uris,
                "absent_uris": absent_uris,
                "diagnostic_files": diagnostic_files,
                **absence_context,
            },
        )

    @staticmethod
    def _is_expand_unsupported(response_body: Any) -> bool:
        """
        Return True if a Redfish error body says ``$expand`` is unsupported.

        Detects DSP0266 ``Base.1.x.QueryParameterValueFormatError`` and
        ``QueryNotSupportedOnResource`` responses that specifically reference
        ``$expand`` — a generic QueryParameterValueFormatError about ``$select``
        or ``$filter`` must NOT trigger the fallback, since that fallback only
        knows how to emulate ``$expand``.

        Handles both parsed JSON (``dict``) and the ``"{status}: {body}"``
        string form that ``dispatch_request`` returns on some failure paths.

        Args:
            response_body: Response body object whose ``get`` state is read
                while performing true if a Redfish error body says ``$expand``
                is unsupported.

        Returns:
            Whether the true if a Redfish error body says ``$expand`` is
            unsupported operation succeeds.
        """
        # Quick path for stringified bodies.
        if isinstance(response_body, str):
            body = response_body
            if "$expand" not in body:
                return False
            return (
                "QueryParameterValueFormatError" in body or "QueryNotSupported" in body
            )
        if not isinstance(response_body, dict):
            return False

        err_raw = response_body.get("error")
        err = err_raw if isinstance(err_raw, dict) else {}
        code = str(err.get("code", "") or "")
        message = str(err.get("message", "") or "")

        # ExtendedInfo is authoritative — its MessageArgs identifies the
        # offending query parameter directly.
        for info in err.get("@Message.ExtendedInfo") or []:
            if not isinstance(info, dict):
                continue
            msg_id = str(info.get("MessageId", "") or "")
            if (
                "QueryParameterValueFormatError" in msg_id
                or "QueryNotSupported" in msg_id
            ):
                args = info.get("MessageArgs") or []
                if any("$expand" in str(a) for a in args):
                    return True

        # Fallback path: top-level code matches AND the human-readable message
        # mentions $expand. Required to avoid false positives on $select/$filter.
        if (
            "QueryParameterValueFormatError" in code or "QueryNotSupported" in code
        ) and "$expand" in message:
            return True

        return False

    def _should_fallback_expand_failure(
        self,
        response_body: Any,
        request_metadata: Any,
    ) -> bool:
        """
        Return whether ``auto`` mode may emulate a failed ``$expand`` request.

        Explicit Redfish query-unsupported responses remain the primary signal.
        Some BMCs advertise ``$expand`` but return a server or gateway failure
        only for deeper expansion levels. After the unexpanded base resource has
        succeeded, the bounded reference walker is a safe equivalent recovery
        for those query-local 500, 501, 502, and 504 responses. A 503 remains a
        hard failure because it normally indicates broader service unavailability;
        authentication, authorization, throttling, and unrelated client errors
        also remain fail closed.

        Args:
            response_body: Parsed or textual response returned by the failed
                expanded request.
            request_metadata: Request metadata that may carry the HTTP status.

        Returns:
            Whether the caller may replace the failed expanded query with the
            bounded Redfish reference walk.
        """
        if self._is_expand_unsupported(response_body):
            return True
        return self._http_status_from_response(
            response_body,
            request_metadata,
        ) in {500, 501, 502, 504}

    async def _probe_expand_support(self, dut_id: str) -> bool:
        """
        Probe the resolved service root once per DUT for ``$expand`` support.

        Caches the verdict on the DUT object as ``_expand_supported`` so that
        subsequent expand-style collectors on the same DUT can short-circuit.
        Also captures ``ExpandQuery.MaxLevels`` (when advertised) on the DUT as
        ``_expand_max_levels`` so callers can clamp requested levels against the
        BMC's declared ceiling. ``None`` means "not advertised".

        Defaults to ``True`` when the probe is inconclusive, so we still attempt
        the real ``$expand`` query and only fall back if it actually fails.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.

        Returns:
            Whether the probe the resolved service root once per DUT for
            ``$expand`` support operation succeeds.

        Raises:
            RuntimeError: If expand capability probing lacks a URI configuration
                manager.
        """
        try:
            dut = self.dut_manager.get_dut(dut_id)
        except Exception:
            dut = None

        if dut is not None:
            cached = getattr(dut, "_expand_supported", None)
            if cached is not None:
                return bool(cached)

        supported = True
        max_levels: Optional[int] = None
        try:
            if not self.dut_manager or not self.dut_manager.uri_config_manager:
                raise RuntimeError(
                    "Expand capability probing requires a URI configuration manager"
                )
            service_root = self.dut_manager.uri_config_manager.get_service_root(dut_id)
            ok, root, _ = await self.dispatch_request(
                dut_id,
                "GET",
                service_root,
                error_context="probe ProtocolFeaturesSupported.ExpandQuery",
            )
            if ok and isinstance(root, dict):
                features = root.get("ProtocolFeaturesSupported")
                if isinstance(features, dict):
                    expand = features.get("ExpandQuery")
                    if isinstance(expand, dict):
                        # DSP0266: a BMC that advertises ExpandQuery with both
                        # Levels=False and ExpandAll falsy cannot satisfy our
                        # ``$expand=*($levels=N)`` form.
                        if expand.get("Levels") is False and not expand.get(
                            "ExpandAll"
                        ):
                            supported = False
                        raw_max = expand.get("MaxLevels")
                        # DSP0266 requires MaxLevels to be an int >= 1 when
                        # advertised; tolerate bool sneaking in as int.
                        if (
                            isinstance(raw_max, int)
                            and not isinstance(raw_max, bool)
                            and raw_max >= 1
                        ):
                            max_levels = raw_max
            elif not ok and self._is_expand_unsupported(root):
                supported = False
        except Exception as exc:  # pragma: no cover - defensive
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Could not probe ExpandQuery support (treating as supported): {exc}",
                dut_id,
            )

        if dut is not None:
            try:
                dut._expand_supported = supported
                dut._expand_max_levels = max_levels
            except Exception:  # pragma: no cover - DUT object may be a Mock
                pass

        if not supported:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                "ServiceRoot reports $expand is not supported on this BMC; "
                "expand collectors will fall back to a Redfish reference walk.",
                dut_id,
            )
        elif max_levels is not None:
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"BMC advertises ExpandQuery.MaxLevels={max_levels}; "
                "requested levels above this will be clamped.",
                dut_id,
            )
        return supported

    async def _resolve_effective_expand_level(
        self, dut_id: str, requested_level: int
    ) -> int:
        """
        Clamp a requested expand level against the BMC's advertised ceiling.

        Reads ``_expand_max_levels`` cached on the DUT by
        ``_probe_expand_support``. When the BMC advertises a ``MaxLevels`` and
        the requested level exceeds it, return the advertised ceiling and log a
        one-time clamp notice. When ``MaxLevels`` is not advertised, pass the
        requested value through unchanged — the BMC will honor or reject it, and
        the reactive fallback in ``_handle_expand_collection`` handles the
        rejection path.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            requested_level: Numeric requested level used while the operation
                performs bounded accounting.

        Returns:
            The numeric effective expand level value.
        """
        if not isinstance(requested_level, int) or requested_level < 1:
            return 1

        try:
            dut = self.dut_manager.get_dut(dut_id)
        except Exception:
            return requested_level

        max_levels = getattr(dut, "_expand_max_levels", None) if dut else None
        if not isinstance(max_levels, int) or max_levels < 1:
            return requested_level

        if requested_level <= max_levels:
            return requested_level

        # Clamp + log once per DUT per requested-level combination so callers
        # spamming the same value don't flood the log.
        clamp_log_key = (max_levels, requested_level)
        already_logged = getattr(dut, "_expand_clamp_logged", set()) if dut else set()
        if clamp_log_key not in already_logged:
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Requested expand level {requested_level} exceeds BMC-advertised "
                f"MaxLevels={max_levels}; clamping to {max_levels}.",
                dut_id,
            )
            if dut is not None:
                try:
                    already_logged.add(clamp_log_key)
                    dut._expand_clamp_logged = already_logged
                except Exception:  # pragma: no cover - DUT object may be a Mock
                    pass
        return max_levels

    async def _emulate_expand_via_member_walk(
        self,
        dut_id: str,
        collection_data: Any,
        expand_level: int,
    ) -> Tuple[Any, int, int, int]:
        """
        Synthesize the payload ``$expand=*($levels=N)`` would have produced.

        Walks bare ``@odata.id`` references from the already-fetched base
        resource and replaces each reference with the body of an individual GET.
        This supports both collection resources with ``Members`` and individual
        resources such as a Chassis or PowerSubsystem. For ``expand_level > 1``,
        it recurses into nested references up to ``expand_level`` levels deep,
        mirroring what ``$expand=*($levels=N)`` would have inlined.

        Cycle detection: a per-call visited-URI set prevents loops in the
        Redfish graph (Chassis ↔ Systems ↔ Managers commonly cross-link).

        Natural-depth detection: ``max_depth_reached`` reports the deepest level
        at which we actually replaced a link with its body. If this is less than
        ``expand_level`` it means the graph bottomed out before the requested
        depth — callers may want to log that.

        Returns ``(synthesized_payload, fetched_count,
        attempted_reference_count, max_depth_reached)``.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collection_data: Collection data object whose ``get`` state is read
                while performing synthesize the payload ``$expand=*($levels=N)``
                would have produced.
            expand_level: Numeric expand level used while the operation performs
                bounded accounting.

        Returns:
            A tuple containing ``returned value``, ``integer count``, ``integer
            count``, and ``integer count`` in that order.
        """
        if not isinstance(collection_data, dict):
            return collection_data, 0, 0, 0

        synthesized = copy.deepcopy(collection_data)
        depth = max(1, int(expand_level) if isinstance(expand_level, int) else 1)
        visited: set[str] = set()
        # Pre-mark the base collection URI when known so we don't re-fetch it
        # if it appears as a nested @odata.id deeper in the graph.
        base_self = collection_data.get("@odata.id")
        if isinstance(base_self, str):
            visited.add(base_self)

        fetched_counter = [0]
        attempted_counter = [0]
        skipped_counter = [0]
        max_depth = [0]
        request_limit = self.MAX_FOLLOWED_COLLECTION_MEMBERS
        retained_byte_limit = self._resolved_structured_response_limit(dut_id)
        try:
            retained_bytes = [
                len(
                    json.dumps(
                        synthesized,
                        ensure_ascii=False,
                        separators=(",", ":"),
                    ).encode("utf-8")
                )
            ]
        except (TypeError, ValueError):
            retained_bytes = [retained_byte_limit + 1]

        async def _walk(node: Any, remaining_depth: int) -> Any:
            """
            Replace any @odata.id reference in ``node`` with its fetched body.

            Walks the tree shape-preservingly: dicts/lists are traversed,
            scalars are returned as-is. When a dict has a bare ``@odata.id``
            pointing at a URI we haven't fetched yet, GET it and recurse into
            the body with ``remaining_depth - 1``.

            Args:
                node: Node object whose ``get``, ``items``, and ``keys`` state
                    is read while performing replace any @odata.id reference in
                    ``node`` with its fetched body.
                remaining_depth: Numeric remaining depth used while the
                    operation performs bounded accounting.

            Returns:
                The walk value selected by the operation.
            """
            if remaining_depth <= 0:
                return node

            if isinstance(node, list):
                return [await _walk(item, remaining_depth) for item in node]

            if not isinstance(node, dict):
                return node

            # A "bare reference" is a dict whose only meaningful key (besides
            # the optional @odata.type) is @odata.id pointing at another
            # resource. We only chase bare references — already-expanded
            # bodies (those with payload fields beyond @odata.id) are recursed
            # into in place so deeper nested refs still get fetched.
            ref_uri = node.get("@odata.id") if isinstance(node, dict) else None
            payload_keys = [
                k
                for k in node.keys()
                if k not in ("@odata.id", "@odata.type", "@odata.context")
            ]

            if isinstance(ref_uri, str) and not payload_keys:
                if ref_uri in visited:
                    # A duplicate or cyclic back-link is already represented
                    # by the body fetched at its first occurrence. Leaving the
                    # later link as an @odata.id is intentional cycle
                    # suppression, not an unresolved fetch. Counting it as a
                    # failure makes complete cyclic Redfish graphs report
                    # partial even when every network request succeeded.
                    return node  # cycle — leave the reference unexpanded
                visited.add(ref_uri)
                if (
                    attempted_counter[0] >= request_limit
                    or retained_bytes[0] >= retained_byte_limit
                ):
                    skipped_counter[0] += 1
                    return node
                attempted_counter[0] += 1
                ok, body, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    ref_uri,
                    error_context=f"emulate-expand ref {ref_uri}",
                )
                if not ok or not isinstance(body, dict):
                    return node  # leave the unfetched reference as-is
                try:
                    body_size = len(
                        json.dumps(
                            body,
                            ensure_ascii=False,
                            separators=(",", ":"),
                        ).encode("utf-8")
                    )
                except (TypeError, ValueError):
                    return node
                if retained_bytes[0] + body_size > retained_byte_limit:
                    return node
                retained_bytes[0] += body_size
                fetched_counter[0] += 1
                achieved = depth - remaining_depth + 1
                if achieved > max_depth[0]:
                    max_depth[0] = achieved
                # Recurse into the fetched body for the remaining depth.
                return await _walk(body, remaining_depth - 1)

            # Already-expanded body: walk its fields for nested refs.
            return {
                key: await _walk(value, remaining_depth) for key, value in node.items()
            }

        synthesized = await _walk(synthesized, depth)
        members = synthesized.get("Members") if isinstance(synthesized, dict) else None
        if isinstance(members, list) and "Members@odata.count" in synthesized:
            synthesized["Members@odata.count"] = len(members)
        return (
            synthesized,
            fetched_counter[0],
            attempted_counter[0] + skipped_counter[0],
            max_depth[0],
        )

    async def _handle_expand_collection(
        self,
        dut_id: str,
        uri_list: List[str],
        expand_level: int,
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Handle expand with traversal collection.

        When the BMC does not support ``$expand=*($levels=N)`` (controlled by
        ``DUTConfig.EXPAND_FALLBACK_MODE``), this method either skips the
        ``$expand`` attempt entirely or detects rejections reactively and falls
        back to a Redfish reference walk that synthesizes an equivalent payload.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            expand_level: Numeric expand level used while the operation performs
                bounded accounting.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle expand collection.
        """
        output_files: List[str] = []
        failed_uris: List[str] = []
        partial_uris: List[str] = []
        successful_uris: List[str] = []
        entity_type = kwargs.get("entity_type")
        fallback_count = 0
        skip_if_no_matching_members = bool(
            kwargs.get("skip_if_no_matching_members", False)
        )
        complete_on_empty_matches = bool(kwargs.get("complete_on_empty_matches", False))
        matching_members_found = 0
        collector_definition = kwargs.get("collector_def")
        configured_retry_count = (
            collector_definition.get("retry_count", 3)
            if isinstance(collector_definition, dict)
            else 3
        )
        if (
            not isinstance(configured_retry_count, int)
            or isinstance(configured_retry_count, bool)
            or configured_retry_count < 0
        ):
            configured_retry_count = 3

        # Resolve fallback mode with explicit precedence:
        #   per-DUT override (DUTConfig)  >  tool-level (Config)  >  "auto"
        # DUTConfig.EXPAND_FALLBACK_MODE is Optional[str] = None so "absent at
        # the DUT level" is distinguishable from an explicit setting.
        dut_config: Dict[str, Any] = {}
        try:
            dut_config = self.dut_manager.get_dut_config(dut_id) or {}
        except Exception:
            dut_config = {}

        mode_raw = dut_config.get("EXPAND_FALLBACK_MODE")
        if not mode_raw:
            tool_config: Dict[str, Any] = {}
            try:
                orchestrator = getattr(self, "orchestrator", None)
                if orchestrator and hasattr(orchestrator, "config_manager"):
                    tool_config = orchestrator.config_manager.get_tool_config() or {}
                else:
                    tool_config = getattr(self.dut_manager, "tool_config", {}) or {}
            except Exception:
                tool_config = {}
            mode_raw = tool_config.get("EXPAND_FALLBACK_MODE")

        mode = str(mode_raw or "auto").strip().lower()
        if mode not in ("auto", "never", "always"):
            mode = "auto"

        if mode == "always":
            expand_supported = False
        elif mode == "auto":
            expand_supported = await self._probe_expand_support(dut_id)
        else:  # "never" — preserve legacy behavior
            expand_supported = True

        # Probe-guarded clamping against ExpandQuery.MaxLevels. The probe only
        # ran in "auto" mode; in "never"/"always" modes we either trust the
        # caller or skip the BMC entirely, so clamping doesn't apply.
        if mode == "auto":
            effective_level = await self._resolve_effective_expand_level(
                dut_id, expand_level
            )
        else:
            effective_level = expand_level
        level_clamped = effective_level != expand_level

        for base_uri in uri_list:
            await self._log_collection_start(dut_id, "expand", base_uri)
            unresolved_fallback_references = 0

            # Fetch the base collection or individual resource before expanding.
            (
                success,
                collection_data,
                collection_request_metadata,
            ) = await self.dispatch_request(
                dut_id,
                "GET",
                base_uri,
                error_context=f"get base collection from {base_uri}",
                expected_http_statuses=[404],
            )

            if not success:
                failed_uris.append(
                    f"Base collection failed for {base_uri}: {collection_data}"
                )
                if (
                    self._http_status_from_response(
                        collection_data, collection_request_metadata
                    )
                    != 404
                ):
                    await self._log_collection_failure(
                        dut_id, "expand", base_uri, str(collection_data)
                    )
                continue

            filtered_collection_data = (
                await self._filter_collection_members_by_skip_config(
                    dut_id, collection_data, entity_type, base_uri
                )
            )
            original_members = (
                collection_data.get("Members")
                if isinstance(collection_data, dict)
                else None
            )
            filtered_members = (
                filtered_collection_data.get("Members")
                if isinstance(filtered_collection_data, dict)
                else None
            )
            if (
                isinstance(original_members, list)
                and isinstance(filtered_members, list)
                and len(filtered_members) == 0
                and len(original_members) > 0
            ):
                output_pattern, substitutions, filtered_kwargs = (
                    self._extract_output_pattern_params(kwargs)
                )
                file_path = await self._save_data_with_common_pattern(
                    dut_id,
                    filtered_collection_data,
                    function_tag,
                    output_pattern=output_pattern,
                    substitutions={
                        **substitutions,
                        **self._extract_entity_id_from_uri(base_uri),
                        "expand_level": str(effective_level),
                    },
                    request_timing_operation_ids=self._request_timing_operation_id(
                        collection_request_metadata
                    ),
                    **filtered_kwargs,
                )
                if file_path:
                    output_files.append(file_path)
                    successful_uris.append(base_uri)
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Skipped expanded query for {base_uri}: all members are excluded by skip config",
                        dut_id,
                    )
                continue

            used_fallback = False
            expanded_data: Any = None
            expanded_request_metadata: Dict[str, Any] = {}

            if expand_supported:
                expand_query = f"$expand=*($levels={effective_level})"
                expanded_uri = f"{base_uri}?{expand_query}"
                (
                    ok,
                    expanded_data,
                    expanded_request_metadata,
                ) = await self.dispatch_request(
                    dut_id,
                    "GET",
                    expanded_uri,
                    error_context=f"get expanded data from {base_uri}",
                    expected_http_statuses=[404],
                    # Auto mode treats the first query-local failure as the
                    # capability signal for the equivalent bounded walk. Four
                    # full request windows before that recovery can consume
                    # twenty minutes at the default 300-second timeout. Never
                    # mode retains the collector's governed retry behavior.
                    retry_count=(0 if mode == "auto" else configured_retry_count),
                )
                if (
                    mode == "auto"
                    and not ok
                    and configured_retry_count > 0
                    and not self._should_fallback_expand_failure(
                        expanded_data,
                        expanded_request_metadata,
                    )
                    and self._redfish_get_failure_is_retryable(
                        expanded_data,
                        expanded_request_metadata,
                    )
                ):
                    # The first zero-retry attempt keeps query-local fallback
                    # bounded. A non-fallback transient failure still owns the
                    # collector's remaining retry budget. Subtract the attempt
                    # already consumed so total request attempts match the
                    # configured ``retry_count + 1`` contract.
                    (
                        ok,
                        expanded_data,
                        expanded_request_metadata,
                    ) = await self.dispatch_request(
                        dut_id,
                        "GET",
                        expanded_uri,
                        error_context=f"get expanded data from {base_uri}",
                        expected_http_statuses=[404],
                        retry_count=configured_retry_count - 1,
                    )
                expand_error_details = expanded_request_metadata
                if not ok:
                    # In "never" mode we preserve legacy behavior: any $expand
                    # failure is an error, no fallback. In "auto" mode we
                    # detect $expand-specific rejection and fall back.
                    if mode != "never" and self._should_fallback_expand_failure(
                        expanded_data,
                        expand_error_details,
                    ):
                        # Latch the verdict at the DUT level so later base_uris
                        # (and later collectors on this DUT) skip the failed call.
                        expand_supported = False
                        try:
                            dut = self.dut_manager.get_dut(dut_id)
                            if dut is not None:
                                dut._expand_supported = False
                        except Exception:
                            pass
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"BMC could not complete $expand for {base_uri}; "
                            "falling back to a Redfish reference walk for this and "
                            "subsequent collectors",
                            dut_id,
                        )
                    elif (
                        self._http_status_from_response(
                            expanded_data, expand_error_details
                        )
                        == 404
                    ):
                        failed_uris.append(f"Expand failed for {base_uri}: HTTP 404")
                        continue
                    else:
                        error_parts = []
                        http_status = (
                            expand_error_details.get("http_status")
                            if isinstance(expand_error_details, dict)
                            else None
                        )
                        if http_status is not None:
                            error_parts.append(f"HTTP {http_status}")

                        redfish_error = (
                            expanded_data.get("error")
                            if isinstance(expanded_data, dict)
                            else None
                        )
                        if isinstance(redfish_error, dict):
                            error_code = redfish_error.get("code")
                            error_message = redfish_error.get("message")
                            if error_code:
                                error_parts.append(str(error_code))
                            if error_message:
                                error_parts.append(str(error_message))

                        if not error_parts:
                            fallback_error = str(expanded_data)
                            if len(fallback_error) > 500:
                                fallback_error = f"{fallback_error[:497]}..."
                            error_parts.append(fallback_error)

                        error_summary = "; ".join(error_parts)
                        partial_members = (
                            expanded_data.get("Members")
                            if isinstance(expanded_data, dict)
                            else None
                        )
                        if isinstance(partial_members, list) and partial_members:
                            partial_data = (
                                await self._filter_collection_members_by_skip_config(
                                    dut_id, expanded_data, entity_type, base_uri
                                )
                            )
                            filtered_partial_members = (
                                partial_data.get("Members", [])
                                if isinstance(partial_data, dict)
                                else []
                            )
                            if isinstance(filtered_partial_members, list):
                                matching_members_found += len(filtered_partial_members)

                            output_pattern, substitutions, filtered_kwargs = (
                                self._extract_output_pattern_params(kwargs)
                            )
                            file_path = await self._save_data_with_common_pattern(
                                dut_id,
                                partial_data,
                                function_tag,
                                output_pattern=output_pattern,
                                substitutions={
                                    **substitutions,
                                    **self._extract_entity_id_from_uri(base_uri),
                                    "expand_level": str(effective_level),
                                },
                                request_timing_operation_ids=self._request_timing_operation_id(
                                    expanded_request_metadata
                                ),
                                **filtered_kwargs,
                            )
                            if file_path:
                                output_files.append(file_path)
                                partial_uris.append(base_uri)
                                failed_uris.append(
                                    f"Expand returned partial data for {base_uri}: "
                                    f"{error_summary} "
                                    f"({len(partial_members)} members retained)"
                                )
                                await self._log_collection_failure(
                                    dut_id,
                                    "expand",
                                    base_uri,
                                    f"{error_summary}; partial response retained in "
                                    f"{file_path}",
                                )
                                continue

                        failed_uris.append(
                            f"Expand failed for {base_uri}: {error_summary}"
                        )
                        await self._log_collection_failure(
                            dut_id, "expand", base_uri, error_summary
                        )
                        continue

            if not expand_supported:
                (
                    expanded_data,
                    fetched,
                    total_references,
                    max_depth_reached,
                ) = await self._emulate_expand_via_member_walk(
                    dut_id, filtered_collection_data, effective_level
                )
                used_fallback = True
                unresolved_fallback_references = max(total_references - fetched, 0)
                if fetched == 0 and total_references > 0:
                    failed_uris.append(
                        f"Expand fallback failed for {base_uri}: no references "
                        f"fetched ({total_references} attempted)"
                    )
                    await self._log_collection_failure(
                        dut_id,
                        "expand",
                        base_uri,
                        f"reference walk fetched 0/{total_references} references",
                    )
                    continue
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Emulated $expand for {base_uri} via reference walk "
                    f"({fetched}/{total_references} references)",
                    dut_id,
                )
                # When MaxLevels wasn't advertised and the emulator bottomed
                # out before the requested depth, report the natural limit so
                # the operator knows the BMC's graph simply doesn't go deeper.
                if (
                    effective_level > 1
                    and max_depth_reached < effective_level
                    and total_references > 0
                ):
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Expand emulation for {base_uri} bottomed out at "
                        f"depth {max_depth_reached} (requested {effective_level}); "
                        "no further @odata.id references to expand.",
                        dut_id,
                    )

            # Apply skip-config filter on the (real or synthesized) payload
            # and save with the same pattern as the success path.
            expanded_data = await self._filter_collection_members_by_skip_config(
                dut_id, expanded_data, entity_type, base_uri
            )
            expanded_members = (
                expanded_data.get("Members", [])
                if isinstance(expanded_data, dict)
                else []
            )
            if isinstance(expanded_members, list):
                matching_members_found += len(expanded_members)
            output_pattern, substitutions, filtered_kwargs = (
                self._extract_output_pattern_params(kwargs)
            )
            file_path = await self._save_data_with_common_pattern(
                dut_id,
                expanded_data,
                function_tag,
                output_pattern=output_pattern,
                substitutions={
                    **substitutions,
                    **self._extract_entity_id_from_uri(base_uri),
                    "expand_level": str(effective_level),
                },
                request_timing_operation_ids=(
                    None
                    if used_fallback
                    else self._request_timing_operation_id(expanded_request_metadata)
                ),
                **filtered_kwargs,
            )
            if file_path:
                output_files.append(file_path)
                if used_fallback and unresolved_fallback_references:
                    partial_uris.append(base_uri)
                    failure_reason = (
                        f"Expand fallback returned partial data for {base_uri}: "
                        f"{unresolved_fallback_references}/{total_references} references "
                        "remain unresolved"
                    )
                    failed_uris.append(failure_reason)
                    await self._log_collection_failure(
                        dut_id, "expand", base_uri, failure_reason
                    )
                else:
                    successful_uris.append(base_uri)
                    if used_fallback:
                        fallback_count += 1
                    await self._log_collection_success(
                        dut_id, "expand", base_uri, file_path
                    )
            else:
                persistence_failure = (
                    f"Expanded data persistence failed for {base_uri}: "
                    "no output file was generated"
                )
                failed_uris.append(persistence_failure)
                await self._log_collection_failure(
                    dut_id,
                    "expand",
                    base_uri,
                    "No output file was generated",
                )

        successful_operations = len(successful_uris)
        total_operations = len(uri_list)
        error_messages = failed_uris

        additional_context: Dict[str, Any] = {
            "expand_level": effective_level,
            "expand_level_requested": expand_level,
            "base_uris": len(uri_list),
            "successful_uris": successful_uris,
            "partial_uris": partial_uris,
            "failed_uris": failed_uris,
        }
        if partial_uris:
            partial_reason = (
                f"Partial success: {successful_operations}/{total_operations} "
                "expand_collection target(s) completed cleanly; "
                f"{len(partial_uris)}/{total_operations} additional target(s) "
                "returned usable data with Redfish errors."
            )
            if error_messages:
                partial_reason += "\n" + "\n".join(
                    f"  • {error}" for error in error_messages
                )
            additional_context.update(
                {
                    "status": "partial",
                    "reason": partial_reason,
                    "partial_operations": len(partial_uris),
                }
            )
        if skip_if_no_matching_members:
            additional_context["matching_members_found"] = matching_members_found
        if level_clamped:
            additional_context["expand_level_clamped"] = True
        if fallback_count:
            additional_context["fallback_reason"] = (
                f"expand_unavailable; emulated via reference walk "
                f"({fallback_count}/{total_operations})"
            )

        if (
            skip_if_no_matching_members
            and matching_members_found == 0
            and successful_uris
            and not failed_uris
        ):
            empty_status = "success" if complete_on_empty_matches else "skipped"
            additional_context.update(
                {
                    "status": empty_status,
                    "reason": (
                        f"No member resources found for {function_tag}; "
                        "endpoint query completed successfully"
                    ),
                }
            )
            if not complete_on_empty_matches:
                additional_context["intentional_evidence_only_skip"] = True
            return await self._create_standardized_collector_result(
                successful_operations=(
                    successful_operations if complete_on_empty_matches else 0
                ),
                total_operations=(total_operations if complete_on_empty_matches else 0),
                output_files=output_files,
                error_messages=[],
                operation_name="expand_collection",
                additional_context=additional_context,
            )

        # If nothing succeeded and every failure is a 404/not-found, the target
        # resource simply isn't present on this platform - treat as "skipped"
        # rather than "error" (mirrors the absent-resource handling used for
        # uri_list collections and log-service collections).
        if (
            successful_operations == 0
            and not partial_uris
            and error_messages
            and all(
                "404" in error
                or "not found" in error.lower()
                or "not supported" in error.lower()
                or "resourcemissingaturi" in error.lower()
                or "resource missing" in error.lower()
                for error in error_messages
            )
        ):
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Expand target(s) not available for {function_tag} - treating as skipped",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                # A 404-only result proves the requested platform capability is
                # absent; it is not an attempted collector failure.  Skip
                # accounting must therefore remain 0/0 or the standardized
                # boundary correctly rejects the contradictory skip override.
                total_operations=0,
                output_files=output_files,
                error_messages=[],
                operation_name="expand_collection",
                additional_context={
                    "expand_level": expand_level,
                    "base_uris": len(uri_list),
                    "successful_uris": successful_uris,
                    "failed_uris": failed_uris,
                    "status": "skipped",
                    "reason": f"Expand target(s) not available for {function_tag} - collector skipped",
                },
            )

        return await self._create_standardized_collector_result(
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="expand_collection",
            additional_context=additional_context,
        )

    async def _filter_collection_members_by_skip_config(
        self,
        dut_id: str,
        collection_data: Any,
        entity_type: Optional[str],
        base_uri: str,
    ) -> Any:
        """
        Apply configured Redfish entity skip lists to expanded collection payloads.

        The implementation uses ``dut_id``, ``collection_data``,
        ``entity_type``, and ``base_uri`` to apply configured Redfish entity
        skip lists to expanded collection payloads. Owned asynchronous work is
        awaited before return, so completion does not leave an unobserved task
        behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collection_data: Collection data object whose ``get`` state is read
                while performing apply configured Redfish entity skip lists to
                expanded collection payloads.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            base_uri: Validated remote resource identifier used for base URI.

        Returns:
            The filter collection members by skip config value selected by the
            operation.
        """
        if not isinstance(collection_data, dict):
            return collection_data

        members = collection_data.get("Members")
        if not isinstance(members, list):
            return collection_data

        normalized_entity_type = str(entity_type or "").strip().lower()
        base_uri_lower = str(base_uri or "").lower()
        if normalized_entity_type == "systems" or "/systems" in base_uri_lower:
            id_type = "system"
        elif normalized_entity_type == "managers" or "/managers" in base_uri_lower:
            id_type = "manager"
        elif normalized_entity_type == "chassis" or "/chassis" in base_uri_lower:
            id_type = "chassis"
        else:
            return collection_data

        member_ids = []
        for member in members:
            if isinstance(member, dict):
                member_uri = str(member.get("@odata.id") or "")
                member_id = str(member.get("Id") or "")
                if member_uri:
                    member_id = member_uri.rstrip("/").split("/")[-1]
                member_ids.append(member_id)
            else:
                member_ids.append("")

        dut_config = self.dut_manager.get_dut_config(dut_id)
        filtered_ids = filter_ids(member_ids, id_type, dut_config)
        if len(filtered_ids) == len(member_ids):
            return collection_data

        filtered_id_set = set(filtered_ids)
        filtered_data = copy.deepcopy(collection_data)
        filtered_data["Members"] = [
            member
            for member, member_id in zip(filtered_data.get("Members", []), member_ids)
            if member_id in filtered_id_set
        ]
        if "Members@odata.count" in filtered_data:
            filtered_data["Members@odata.count"] = len(filtered_data["Members"])

        await log_filtered_ids(member_ids, filtered_ids, id_type, self.logger, dut_id)
        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"Filtered expanded {entity_type or base_uri} members from {member_ids} to {filtered_ids}",
            dut_id,
        )
        return filtered_data

    async def _handle_chassis_with_filter_collection(
        self, dut_id: str, uri_list: List[str], function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Handle chassis with filter collection.

        After applying local validation, the function forwards ``dut_id``,
        ``uri_list``, ``function_tag``, and ``kwargs`` to
        ``self._create_standardized_collector_result`` and preserves its return
        and exception contract. Terminal status is emitted only after chassis
        with filter collection and its owned cleanup have completed. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_list: Validated remote resource identifier used for URI list.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle chassis with filter collection.
        """
        output_files = []
        failed_chassis = []
        successful_chassis = []
        total_chassis_operations = 0

        filter_criteria = kwargs.get("filter_criteria", {})

        for collection_uri in uri_list:
            await self._log_collection_start(dut_id, "chassis_filter", collection_uri)

            # Get chassis collection
            success, collection_data, _ = await self.dispatch_request(
                dut_id,
                "GET",
                collection_uri,
                error_context=f"get chassis collection from {collection_uri}",
            )

            if not success:
                total_chassis_operations += 1
                failed_chassis.append(
                    f"Chassis collection failed for {collection_uri}: {collection_data}"
                )
                await self._log_collection_failure(
                    dut_id,
                    "chassis_filter",
                    collection_uri,
                    str(collection_data),
                )
                continue

            # Process individual chassis
            raw_members = (
                collection_data.get("Members", [])
                if isinstance(collection_data, dict)
                else []
            )
            try:
                members, source_count, truncated = bound_redfish_collection_members(
                    raw_members,
                    field_name=f"Chassis collection {collection_uri} Members",
                    limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                )
            except ValueError:
                members = []
                source_count = 1
                truncated = False
                failed_chassis.append(
                    f"Chassis collection {collection_uri} returned an invalid "
                    "Members list"
                )
            total_chassis_operations += source_count
            if truncated:
                failed_chassis.append(
                    f"Chassis collection {collection_uri} advertised "
                    f"{source_count} members; processing the first "
                    f"{self.MAX_FOLLOWED_COLLECTION_MEMBERS} within the safe "
                    "request-amplification limit"
                )
            for member in members:
                if not isinstance(member, dict):
                    failed_chassis.append(
                        f"Chassis collection {collection_uri} contained a "
                        "non-object member"
                    )
                    continue
                chassis_uri = member.get("@odata.id", "")
                if chassis_uri and not validate_redfish_uri(chassis_uri):
                    continue
                if chassis_uri:
                    chassis_id = chassis_uri.split("/")[-1]

                    # Get individual chassis data
                    (
                        chassis_success,
                        chassis_data,
                        chassis_request_metadata,
                    ) = await self.dispatch_request(
                        dut_id,
                        "GET",
                        chassis_uri,
                        error_context=f"get chassis data from {chassis_uri}",
                    )

                    if chassis_success:
                        # Apply filter criteria if provided
                        if filter_criteria:
                            # Filter the data based on criteria
                            filtered_data = self._apply_chassis_filter(
                                chassis_data, filter_criteria
                            )
                        else:
                            filtered_data = chassis_data

                        if filtered_data:
                            # Extract output pattern parameters using common function
                            output_pattern, substitutions, filtered_kwargs = (
                                self._extract_output_pattern_params(kwargs)
                            )

                            # Use common data saving function with chassis_id substitution
                            file_path = await self._save_data_with_common_pattern(
                                dut_id,
                                filtered_data,
                                function_tag,
                                output_pattern=output_pattern,
                                substitutions={
                                    **substitutions,
                                    "chassis_id": chassis_id,
                                },
                                request_timing_operation_ids=self._request_timing_operation_id(
                                    chassis_request_metadata
                                ),
                                **filtered_kwargs,
                            )

                            if file_path:
                                output_files.append(file_path)
                                successful_chassis.append(chassis_id)
                                await self._log_collection_success(
                                    dut_id,
                                    "chassis_filter",
                                    chassis_uri,
                                    file_path,
                                )
                    else:
                        failed_chassis.append(
                            f"Chassis data failed for {chassis_uri}: {chassis_data}"
                        )
                        await self._log_collection_failure(
                            dut_id,
                            "chassis_filter",
                            chassis_uri,
                            str(chassis_data),
                        )

        # Determine overall success based on results
        successful_operations = len(successful_chassis)
        total_operations = total_chassis_operations
        error_messages = (
            failed_chassis  # failed_chassis already contains error messages
        )

        return await self._create_standardized_collector_result(
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=output_files,
            error_messages=error_messages,
            operation_name="chassis_filter_collection",
            additional_context={
                "filter_criteria": filter_criteria,
                "chassis_processed": len(uri_list),
                "successful_chassis": successful_chassis,
                "failed_chassis": failed_chassis,
            },
        )

    def _apply_chassis_filter(
        self, data: Dict[str, Any], filter_criteria: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Apply filter criteria to chassis data.

        For now, return the data as-is This can be enhanced with specific
        filtering logic based on requirements.

        Args:
            data: Mapping supplying fields for apply filter criteria to chassis
                data.
            filter_criteria: Mapping supplying fields for apply filter criteria
                to chassis data.

        Returns:
            A mapping containing chassis filter.
        """
        # Simple filter implementation - can be enhanced based on specific needs
        if not data or not filter_criteria:
            return data

        # For now, return the data as-is
        # This can be enhanced with specific filtering logic based on requirements
        return data

    async def _handle_log_processing_collection(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Handle log processing collection (e.g., CPER logs from SEL logs).

        The implementation uses ``dut_id``, ``entity_type``, ``log_service``,
        ``function_tag``, and ``kwargs`` to handle log processing collection
        (e.g., CPER logs from SEL logs). Terminal status is emitted only after
        log processing collection (e.g., CPER logs from SEL logs) and its owned
        cleanup have completed. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind. Remote
        I/O uses the configured transport policy and returns only after its
        response or failure has been observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle log processing collection.
        """
        try:
            output_files = []
            status_list = []
            error_messages = []
            source_read_budget = self._new_source_log_read_budget(dut_id)
            source_context = {}

            processing_config = kwargs.get("processing_config", {})
            source_logs = processing_config.get("source_logs")
            entry_filter = processing_config.get("entry_filter", {})
            legacy_platforms = processing_config.get("legacy_platforms", [])
            legacy_collection = processing_config.get("legacy_collection", {})
            collector_id = kwargs.get(
                "collector_id", ""
            )  # Extract collector_id from kwargs
            collector_name = kwargs.get("collector_name", function_tag)

            # Check if this is a legacy platform
            platform_info = await self._get_platform_info(dut_id)
            platform_type = platform_info.get("platform_type", "unknown")

            # Use legacy_platforms from processing_config if available, otherwise use default
            if processing_config and "legacy_platforms" in processing_config:
                legacy_platforms = processing_config["legacy_platforms"]

            is_legacy = any(legacy in platform_type for legacy in legacy_platforms)

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Platform detection: platform_type='{platform_type}', legacy_platforms={legacy_platforms}, is_legacy={is_legacy}",
                dut_id,
            )

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Log processing: platform_type='{platform_type}', is_legacy={is_legacy}",
                dut_id,
            )

            if is_legacy:
                # For legacy platforms, collect directly from fault logs
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    "Legacy platform detected. Collecting logs directly from fault logs.",
                    dut_id,
                )

                # Use legacy collection configuration from processing_config
                legacy_collection_config = (
                    processing_config.get("legacy_collection", {})
                    if processing_config
                    else {}
                )
                uri_pattern = legacy_collection_config.get("uri_pattern", "")
                log_service_filter = legacy_collection_config.get(
                    "log_service_filter", {}
                )

                # Get log service URIs
                log_service_uris = await self._get_log_service_uris_legacy(
                    dut_id, entity_type, log_service_filter
                )

                if not log_service_uris:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        f"No {log_service} log URIs found for legacy platform",
                        dut_id,
                    )
                    return await self._create_no_data_skipped_result(
                        log_service=log_service,
                        reason=f"No {log_service} log URIs found",
                        output_files=[],
                        operation_name="log_processing_collection",
                        additional_context={
                            "platform_type": platform_type,
                        },
                    )

                # Process each log service URI
                for log_uri in log_service_uris:
                    success, response, request_metadata = await self.dispatch_request(
                        dut_id, "GET", log_uri
                    )

                    if success:
                        # Extract entity IDs from URI
                        uri_parts = log_uri.split("/")
                        entity_id = uri_parts[4] if len(uri_parts) > 4 else "unknown"
                        service_id = uri_parts[6] if len(uri_parts) > 6 else "unknown"

                        # Save the log entries
                        json_filename = f"{function_tag}_{log_service.lower()}_logs_{entity_id}_{service_id}.json"
                        json_file = await self._save_data_with_common_pattern(
                            dut_id,
                            response,
                            function_tag,
                            output_pattern=json_filename,
                            substitutions={
                                "entity_id": entity_id,
                                "service_id": service_id,
                            },
                            request_timing_operation_ids=self._request_timing_operation_id(
                                request_metadata
                            ),
                            collector_id=collector_id,
                        )

                        if json_file:
                            output_files.append(json_file)
                            status_list.append(True)

                            # Process individual log entries
                            entries = response.get("Members", [])
                            for entry in entries:
                                entry_type = entry.get("DiagnosticDataType", "")
                                if entry_type == log_service:
                                    entry_id = entry.get("Id")
                                    entry_uri = entry.get("AdditionalDataURI")

                                    if entry_uri and entry_id:
                                        # Fetch binary log data
                                        (
                                            entry_success,
                                            entry_data,
                                            entry_request_metadata,
                                        ) = await self.dispatch_request(
                                            dut_id,
                                            "GET",
                                            entry_uri,
                                            get_raw_content=True,
                                            raw_content_max_bytes=self._resolved_attachment_limit(
                                                dut_id
                                            ),
                                        )

                                        if entry_success:
                                            binary_filename = f"{function_tag}_{log_service.lower()}_logs_{entity_id}_{service_id}_{entry_id}.tar.xz"
                                            try:
                                                (
                                                    entry_data,
                                                    _,
                                                    binary_filename,
                                                    _,
                                                ) = self._prepare_cper_attachment_for_save(
                                                    entry_data, binary_filename
                                                )
                                                binary_file = await self._save_data_with_common_pattern(
                                                    dut_id,
                                                    entry_data,
                                                    function_tag,
                                                    output_pattern=binary_filename,
                                                    substitutions={
                                                        "entity_id": entity_id,
                                                        "service_id": service_id,
                                                        "entry_id": entry_id,
                                                    },
                                                    request_timing_operation_ids=self._request_timing_operation_id(
                                                        entry_request_metadata
                                                    ),
                                                    collector_id=collector_id,
                                                )
                                            except Exception as error:
                                                status_list.append(False)
                                                error_messages.append(
                                                    f"Failed to prepare or save {log_service} "
                                                    f"attachment {entry_uri} "
                                                    f"({type(error).__name__})"
                                                )
                                                continue

                                            if binary_file:
                                                output_files.append(binary_file)
                                                status_list.append(True)
                                            else:
                                                status_list.append(False)
                                                error_messages.append(
                                                    f"Failed to save {log_service} attachment {entry_uri}"
                                                )
                                        else:
                                            status_list.append(False)
                                            error_messages.append(
                                                f"Failed to fetch {log_service} attachment {entry_uri}"
                                            )
                    else:
                        status_list.append(False)

                        # Create error log file for failed log service URI
                        error_log_path = await self._create_error_log_file(
                            dut_id=dut_id,
                            collector_id=kwargs.get("collector_id"),
                            error_message=f"Failed to get log service URI: {log_uri}",
                            context={
                                "log_uri": log_uri,
                                "log_service": log_service,
                                "entity_type": entity_type,
                                "operation": "log_service_uri_request",
                            },
                        )

                        # Add error log file to output files
                        if error_log_path:
                            output_files.append(error_log_path)

            else:
                # For non-legacy platforms, process from source logs
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Non-legacy platform detected. Processing {log_service} entries from {source_logs}.",
                    dut_id,
                )

                # Find source log files
                source_entries = await self._find_filtered_entries_in_source_logs(
                    dut_id,
                    source_logs,
                    entry_filter,
                    processing_config,
                    collector_id=collector_id,
                    collector_name=collector_name,
                    source_read_budget=source_read_budget,
                )

                if source_entries:
                    requested_attachment_uris = [
                        entry.get("AdditionalDataURI")
                        for entry in source_entries
                        if isinstance(entry, dict) and entry.get("AdditionalDataURI")
                    ]
                    cached_additional_data = (
                        await self._load_source_additional_data_cache(
                            dut_id,
                            source_logs,
                            processing_config,
                            collector_id=collector_id,
                            collector_name=collector_name,
                            requested_uris=requested_attachment_uris,
                            source_read_budget=source_read_budget,
                        )
                    )
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Found {len(source_entries)} {log_service} entries in source logs",
                        dut_id,
                    )

                    # Create consolidated log file
                    entity_base_uri = self.get_configured_uri(dut_id, entity_type)
                    consolidated_response = {
                        "@odata.id": f"{entity_base_uri}/System/LogServices/{log_service}/Entries",
                        "@odata.type": "#LogEntryCollection.LogEntryCollection",
                        "Description": f"Collection of {log_service} Log Entries",
                        "Members": source_entries,
                        "Members@odata.count": len(source_entries),
                        "Name": f"{log_service} Log Entries",
                    }

                    # Save consolidated log file
                    json_filename = f"{function_tag}_{log_service.lower()}_logs.json"
                    json_file = await self._save_data_with_common_pattern(
                        dut_id,
                        consolidated_response,
                        function_tag,
                        output_pattern=json_filename,
                    )

                    if json_file:
                        output_files.append(json_file)
                        status_list.append(True)

                        # Process individual entries for binary data
                        for entry in source_entries:
                            entry_id = entry.get("Id")
                            entry_uri = entry.get("AdditionalDataURI")

                            if entry_uri and entry_id:
                                entry_request_metadata = None
                                if entry_uri in cached_additional_data:
                                    entry_success = True
                                    entry_data = cached_additional_data[entry_uri]
                                    await self._log_runtime(
                                        "INFO",
                                        "RedfishService",
                                        (
                                            "Reusing cached source attachment for "
                                            f"{entry_uri}"
                                        ),
                                        dut_id,
                                    )
                                else:
                                    # A missing or malformed cache entry must
                                    # preserve the direct Redfish fallback.
                                    (
                                        entry_success,
                                        entry_data,
                                        entry_request_metadata,
                                    ) = await self.dispatch_request(
                                        dut_id,
                                        "GET",
                                        entry_uri,
                                        get_raw_content=True,
                                        raw_content_max_bytes=self._resolved_attachment_limit(
                                            dut_id
                                        ),
                                    )

                                if entry_success:
                                    binary_filename = f"{function_tag}_{log_service.lower()}_logs_{entry_id}.tar.xz"
                                    try:
                                        (
                                            entry_data,
                                            _,
                                            binary_filename,
                                            _,
                                        ) = self._prepare_cper_attachment_for_save(
                                            entry_data, binary_filename
                                        )
                                        binary_file = await self._save_data_with_common_pattern(
                                            dut_id,
                                            entry_data,
                                            function_tag,
                                            output_pattern=binary_filename,
                                            substitutions={"entry_id": entry_id},
                                            request_timing_operation_ids=self._request_timing_operation_id(
                                                entry_request_metadata
                                            ),
                                            collector_id=collector_id,
                                        )
                                    except Exception as error:
                                        status_list.append(False)
                                        error_messages.append(
                                            f"Failed to prepare or save {log_service} "
                                            f"attachment {entry_uri} "
                                            f"({type(error).__name__})"
                                        )
                                        continue

                                    if binary_file:
                                        output_files.append(binary_file)
                                        status_list.append(True)
                                    else:
                                        status_list.append(False)
                                        error_messages.append(
                                            f"Failed to save {log_service} attachment {entry_uri}"
                                        )
                                else:
                                    status_list.append(False)
                                    error_messages.append(
                                        f"Failed to fetch {log_service} attachment {entry_uri}"
                                    )
                else:
                    # Try fallback collection if configured
                    fallback_config = (
                        processing_config.get("fallback_collection")
                        if processing_config
                        else None
                    )
                    source_terminal_no_data_reused = False
                    source_artifacts_available = (
                        await self._source_log_artifacts_available(
                            dut_id,
                            source_logs,
                            processing_config,
                            collector_id=collector_id,
                            collector_name=collector_name,
                            source_read_budget=source_read_budget,
                        )
                    )
                    if source_artifacts_available:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            (
                                f"No {log_service} entries found in completed "
                                "source artifacts; skipping redundant fallback "
                                "collection."
                            ),
                            dut_id,
                        )
                        fallback_config = None
                    elif self._source_collector_terminal_no_data(
                        dut_id, processing_config
                    ):
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            (
                                f"Source collector recorded expected no data for "
                                f"{source_logs}; skipping redundant fallback "
                                "collection."
                            ),
                            dut_id,
                        )
                        fallback_config = None
                        source_terminal_no_data_reused = True
                    if fallback_config:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"No {log_service} entries found in source logs. Attempting fallback collection.",
                            dut_id,
                        )

                        # Execute fallback collection
                        fallback_result = await self._execute_fallback_collection(
                            dut_id,
                            fallback_config,
                            function_tag,
                            processing_config,
                            collector_id=collector_id,
                        )

                        if fallback_result["success"]:
                            fallback_source_config = dict(processing_config or {})
                            if collector_id and collector_name:
                                fallback_source_config[
                                    "possible_source_directories"
                                ] = [f"Redfish_{collector_id}_{collector_name}"]

                            # Try to find entries again after fallback collection
                            source_entries = (
                                await self._find_filtered_entries_in_source_logs(
                                    dut_id,
                                    source_logs,
                                    entry_filter,
                                    fallback_source_config,
                                    collector_id=collector_id,
                                    collector_name=collector_name,
                                    source_read_budget=source_read_budget,
                                )
                            )

                            if fallback_result.get("status") in {"partial", "degraded"}:
                                # An empty subset cannot establish platform-wide absence.
                                if not source_entries:
                                    return {
                                        **fallback_result,
                                        "reason": f"No {log_service} entries found in the collected subset; "
                                        f"source collection incomplete: {fallback_result['reason']}",
                                    }
                                source_context = {
                                    "status": fallback_result["status"],
                                    "reason": f"Processed {log_service} entries from incomplete source data: "
                                    f"{fallback_result['reason']}",
                                }
                                error_messages.extend(
                                    fallback_result.get("context", {}).get(
                                        "error_messages", []
                                    )
                                )

                            if source_entries:
                                requested_attachment_uris = [
                                    entry.get("AdditionalDataURI")
                                    for entry in source_entries
                                    if isinstance(entry, dict)
                                    and entry.get("AdditionalDataURI")
                                ]
                                cached_additional_data = (
                                    await self._load_source_additional_data_cache(
                                        dut_id,
                                        source_logs,
                                        fallback_source_config,
                                        collector_id=collector_id,
                                        collector_name=collector_name,
                                        requested_uris=requested_attachment_uris,
                                        source_read_budget=source_read_budget,
                                    )
                                )
                                await self._log_runtime(
                                    "INFO",
                                    "RedfishService",
                                    f"Found {len(source_entries)} {log_service} entries after fallback collection",
                                    dut_id,
                                )

                                # Process the entries (same logic as above)
                                entity_base_uri = self.get_configured_uri(
                                    dut_id, entity_type
                                )
                                consolidated_response = {
                                    "@odata.id": f"{entity_base_uri}/System/LogServices/{log_service}/Entries",
                                    "@odata.type": "#LogEntryCollection.LogEntryCollection",
                                    "Description": f"Collection of {log_service} Log Entries",
                                    "Members": source_entries,
                                    "Members@odata.count": len(source_entries),
                                    "Name": f"{log_service} Log Entries",
                                }

                                json_filename = (
                                    f"{function_tag}_{log_service.lower()}_logs.json"
                                )
                                json_file = await self._save_data_with_common_pattern(
                                    dut_id,
                                    consolidated_response,
                                    function_tag,
                                    output_pattern=json_filename,
                                    collector_id=collector_id,
                                )

                                if json_file:
                                    output_files.append(json_file)
                                    status_list.append(True)

                                    # Process individual entries for binary data
                                    for entry in source_entries:
                                        entry_id = entry.get("Id")
                                        entry_uri = entry.get("AdditionalDataURI")

                                        if entry_uri and entry_id:
                                            if entry_uri in cached_additional_data:
                                                entry_success = True
                                                entry_data = cached_additional_data[
                                                    entry_uri
                                                ]
                                                await self._log_runtime(
                                                    "INFO",
                                                    "RedfishService",
                                                    (
                                                        "Reusing cached source "
                                                        "attachment for "
                                                        f"{entry_uri}"
                                                    ),
                                                    dut_id,
                                                )
                                            else:
                                                (
                                                    entry_success,
                                                    entry_data,
                                                    _,
                                                ) = await self.dispatch_request(
                                                    dut_id,
                                                    "GET",
                                                    entry_uri,
                                                    get_raw_content=True,
                                                    raw_content_max_bytes=self._resolved_attachment_limit(
                                                        dut_id
                                                    ),
                                                )

                                            if entry_success:
                                                binary_filename = f"{function_tag}_{log_service.lower()}_logs_{entry_id}.tar.xz"
                                                try:
                                                    (
                                                        entry_data,
                                                        _,
                                                        binary_filename,
                                                        _,
                                                    ) = self._prepare_cper_attachment_for_save(
                                                        entry_data, binary_filename
                                                    )
                                                    binary_file = await self._save_data_with_common_pattern(
                                                        dut_id,
                                                        entry_data,
                                                        function_tag,
                                                        output_pattern=binary_filename,
                                                        substitutions={
                                                            "entry_id": entry_id
                                                        },
                                                        collector_id=collector_id,
                                                    )
                                                except Exception as error:
                                                    status_list.append(False)
                                                    error_messages.append(
                                                        f"Failed to prepare or save "
                                                        f"{log_service} attachment "
                                                        f"{entry_uri} "
                                                        f"({type(error).__name__})"
                                                    )
                                                    continue

                                                if binary_file:
                                                    output_files.append(binary_file)
                                                    status_list.append(True)
                                                else:
                                                    status_list.append(False)
                                                    error_messages.append(
                                                        f"Failed to save {log_service} attachment {entry_uri}"
                                                    )
                                            else:
                                                status_list.append(False)
                                                error_messages.append(
                                                    f"Failed to fetch {log_service} attachment {entry_uri}"
                                                )
                            else:
                                await self._log_runtime(
                                    "INFO",
                                    "RedfishService",
                                    f"No {log_service} entries found even after fallback collection - this is normal if no {log_service} events occurred",
                                    dut_id,
                                )

                                # Generate a report file indicating no CPER entries were found
                                no_entries_report = {
                                    "info": f"{log_service} log collection completed",
                                    "status": "no_entries_found",
                                    "reason": f"No {log_service} entries found - this is normal if no {log_service} events occurred",
                                    "collection_method": "log_processing",
                                    "source_logs": source_logs,
                                    "entry_filter": entry_filter,
                                    "fallback_collection_attempted": True,
                                    "timestamp": datetime.now().isoformat(),
                                    "note": f"This is expected behavior when no {log_service} events have occurred on the system",
                                }

                                report_filename = f"{function_tag}_{log_service.lower()}_no_entries_report.json"
                                report_file = await self._save_data_with_common_pattern(
                                    dut_id,
                                    no_entries_report,
                                    function_tag,
                                    output_pattern=report_filename,
                                    collector_id=collector_id,
                                )

                                return await self._create_no_data_success_result(
                                    log_service=log_service,
                                    reason=(
                                        f"No {log_service} entries found - this is "
                                        f"normal if no {log_service} events occurred"
                                    ),
                                    output_files=([report_file] if report_file else []),
                                    operation_name="log_processing_collection",
                                    additional_context={
                                        "fallback_collection_attempted": True,
                                    },
                                )
                        else:
                            fallback_reason = fallback_result.get("reason")
                            if not fallback_reason:
                                fallback_reason = f"Fallback collection for {log_service} logs failed - no specific error reason provided in fallback result"
                            await self._log_runtime(
                                "WARN",
                                "RedfishService",
                                f"Fallback collection failed: {fallback_reason}",
                                dut_id,
                            )
                            return await self._create_standardized_collector_result(
                                successful_operations=0,
                                total_operations=1,
                                output_files=[],
                                error_messages=[
                                    f"Fallback collection failed: {fallback_reason}"
                                ],
                                operation_name="log_processing_collection",
                                additional_context={
                                    "log_service": log_service,
                                    "fallback_attempted": True,
                                },
                            )
                    else:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"No {log_service} entries found in source logs and no fallback collection configured - this is normal if no {log_service} events occurred",
                            dut_id,
                        )

                        # Generate a report file indicating no CPER entries were found
                        no_entries_report = {
                            "info": f"{log_service} log collection completed",
                            "status": "no_entries_found",
                            "reason": f"No {log_service} entries found - this is normal if no {log_service} events occurred",
                            "collection_method": "log_processing",
                            "source_logs": source_logs,
                            "entry_filter": entry_filter,
                            "fallback_collection_attempted": False,
                            "timestamp": datetime.now().isoformat(),
                            "note": f"This is expected behavior when no {log_service} events have occurred on the system",
                        }

                        report_filename = f"{function_tag}_{log_service.lower()}_no_entries_report.json"
                        report_file = await self._save_data_with_common_pattern(
                            dut_id,
                            no_entries_report,
                            function_tag,
                            output_pattern=report_filename,
                            collector_id=collector_id,
                        )

                        return await self._create_no_data_success_result(
                            log_service=log_service,
                            reason=(
                                f"No {log_service} entries found - this is normal "
                                f"if no {log_service} events occurred"
                            ),
                            output_files=[report_file] if report_file else [],
                            operation_name="log_processing_collection",
                            additional_context={
                                "fallback_collection_attempted": False,
                                "source_terminal_no_data_reused": (
                                    source_terminal_no_data_reused
                                ),
                            },
                        )

            successful_operations = len([s for s in status_list if s])
            total_operations = len(status_list) if status_list else 1
            if source_context and (not status_list or not all(status_list)):
                source_context = {"status": "partial"}

            return await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="log_processing_collection",
                additional_context={
                    "log_service": log_service,
                    "reason": f"Processed {len(output_files)} {log_service} log files",
                    **source_context,
                },
            )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Log processing collection failed: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Log processing failed: {str(e)}"],
                operation_name="log_processing_collection",
                additional_context={
                    "log_service": log_service,
                    "error_type": type(e).__name__,
                },
            )

    async def _create_no_data_skipped_result(
        self,
        log_service: str,
        reason: str,
        output_files: List[str] = None,
        operation_name: str = "collection",
        additional_context: Dict[str, Any] = None,
    ) -> Dict[str, Any]:
        """
        Create a skipped result for expected no-data collectors.

        After applying local validation, the function forwards ``log_service``,
        ``reason``, ``output_files``, ``operation_name``, and
        ``additional_context`` to ``self._create_standardized_collector_result``
        and preserves its return and exception contract. Owned asynchronous work
        is awaited before return, so completion does not leave an unobserved
        task behind.

        Args:
            log_service: Text supplied as log service in the format accepted by
                this function.
            reason: Text supplied as reason in the format accepted by this
                function.
            output_files: Optional output files; ``None`` selects the function's
                default behavior.
            operation_name: Stable operation name used for lookup and
                operator-facing diagnostics.
            additional_context: Optional additional context; ``None`` selects
                the function's default behavior.

        Returns:
            A mapping containing no data skipped result.
        """
        context = {
            "log_service": log_service,
            "status": "skipped",
            "reason": reason,
            "no_data_collected": True,
            "classification": "expected_no_data",
            "intentional_evidence_only_skip": True,
        }
        if additional_context:
            context.update(additional_context)

        return await self._create_standardized_collector_result(
            successful_operations=0,
            total_operations=0,
            output_files=output_files or [],
            error_messages=[],
            operation_name=operation_name,
            additional_context=context,
        )

    async def _create_no_data_success_result(
        self,
        log_service: str,
        reason: str,
        output_files: List[str] = None,
        operation_name: str = "collection",
        additional_context: Dict[str, Any] = None,
    ) -> Dict[str, Any]:
        """
        Create a successful applicable result documenting a valid empty set.

        The implementation uses ``log_service``, ``reason``, ``output_files``,
        ``operation_name``, and ``additional_context`` to create a successful
        applicable result documenting a valid empty set. Owned asynchronous work
        is awaited before return, so completion does not leave an unobserved
        task behind.

        Args:
            log_service: Text supplied as log service in the format accepted by
                this function.
            reason: Text supplied as reason in the format accepted by this
                function.
            output_files: Optional output files; ``None`` selects the function's
                default behavior.
            operation_name: Stable operation name used for lookup and
                operator-facing diagnostics.
            additional_context: Optional additional context; ``None`` selects
                the function's default behavior.

        Returns:
            A mapping containing no data success result.
        """
        saved_outputs = [path for path in (output_files or []) if path]
        context = {
            "log_service": log_service,
            "reason": reason,
            "no_data_collected": True,
            "classification": "expected_no_data",
        }
        if additional_context:
            context.update(additional_context)

        if not saved_outputs:
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[
                    f"Failed to save the no-entry report for {log_service}"
                ],
                operation_name=operation_name,
                additional_context=context,
            )

        context["status"] = "success"
        return await self._create_standardized_collector_result(
            successful_operations=1,
            total_operations=1,
            output_files=saved_outputs,
            error_messages=[],
            operation_name=operation_name,
            additional_context=context,
        )

    async def _handle_collector_error(
        self,
        dut_id: str,
        collector_name: str,
        error_message: str,
        skip_condition: bool = False,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Common error handling for collectors (DRY pattern).

        The implementation uses ``dut_id``, ``collector_name``,
        ``error_message``, ``skip_condition``, and ``kwargs`` to common error
        handling for collectors (DRY pattern). Owned asynchronous work is
        awaited before return, so completion does not leave an unobserved task
        behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            error_message: Text supplied as error message in the format accepted
                by this function.
            skip_condition: Whether skip condition is enabled or required for
                this operation.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing handle collector error.
        """
        if skip_condition:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"{collector_name}: Skipping due to {error_message}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Skipped: {error_message}"],
                operation_name="collection",
                additional_context={
                    "collector_name": collector_name,
                    "status": "skipped",
                    "reason": f"Skipped: {error_message}",
                },
            )
        else:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"{collector_name}: {error_message}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[error_message],
                operation_name="collection",
                additional_context={
                    "collector_name": collector_name,
                    "status": "error",
                },
            )

    async def _handle_collector_exception(
        self, dut_id: str, collector_name: str, e: Exception
    ) -> Dict[str, Any]:
        """
        Common exception handler for collectors (DRY pattern).

        After applying local validation, the function forwards ``dut_id``,
        ``collector_name``, and ``e`` to
        ``self._create_standardized_collector_result`` and preserves its return
        and exception contract. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            e: E consumed while the function attempts to common exception
                handler for collectors (DRY pattern).

        Returns:
            A mapping containing handle collector exception.
        """
        await self._log_collector_failure(dut_id, collector_name, str(e))
        return await self._create_standardized_collector_result(
            successful_operations=0,
            total_operations=1,
            output_files=[],
            error_messages=[str(e)],
            operation_name="collection",
            additional_context={"collector_name": collector_name},
        )

    async def _handle_collector_result(
        self, dut_id: str, collector_name: str, result: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Common result handler for collectors (DRY pattern).

        The implementation uses ``dut_id``, ``collector_name``, and ``result``
        to common result handler for collectors (DRY pattern). Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            result: Mapping supplying fields for common result handler for
                collectors (DRY pattern).

        Returns:
            The validated ``result``.
        """
        if result["success"]:
            await self._log_collector_success(
                dut_id, collector_name, result.get("context", {})
            )
        else:
            await self._log_collector_failure(
                dut_id, collector_name, "No successful collections"
            )
        return result

    async def generate_streaming_csv(
        self, dut_id: str, function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Generate streaming csv.

        The implementation uses ``dut_id``, ``function_tag``, and ``kwargs`` to
        generate streaming csv. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.
        Filesystem effects remain confined to the caller-selected paths and the
        owning resource lifecycle.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing the ``success``, ``output_files``,
            ``csv_skipped``, and ``csv_no_events`` fields.
        """
        collector_id = kwargs.get("collector_id", "")
        output_dir = await self._get_output_directory(dut_id)

        collector_name = kwargs.get("collector_name", function_tag)
        collector_dir_name = f"Redfish_{collector_id}_{collector_name}"
        collector_dir = Path(output_dir) / dut_id / "redfish" / collector_dir_name

        if not collector_dir.exists():
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"CSV generation skipped: directory not found {collector_dir}",
                dut_id,
            )
            return {"success": True, "output_files": [], "csv_skipped": True}

        all_events = []
        for json_file in sorted(collector_dir.glob("*.json")):
            if (
                "metadata" in json_file.name
                or "status" in json_file.name
                or "diagnostic" in json_file.name
            ):
                continue
            try:
                data = json.loads(json_file.read_text(encoding="utf-8"))
                members = data.get("Members", [])
                all_events.extend(members)
            except Exception:
                continue

        if not all_events:
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"CSV generation: no events found for {collector_id}",
                dut_id,
            )
            return {"success": True, "output_files": [], "csv_no_events": True}

        all_events.sort(key=lambda e: e.get("Created", ""))

        csv_filename = f"{collector_id}_events.csv"
        if self.orchestrator and self.orchestrator.config_manager:
            try:
                tool_config = self.orchestrator.config_manager.get_tool_config()
                if tool_config.get("streaming_only", False):
                    stream_begin, stream_end = normalize_stream_window(
                        tool_config.get("stream_begin", "24"),
                        tool_config.get("stream_end", "0"),
                    )
                    csv_filename = append_stream_window_to_filename(
                        csv_filename,
                        format_stream_window_component(stream_begin),
                        format_stream_window_component(stream_end),
                    )
            except Exception:
                pass

        events_csv = collector_dir / csv_filename
        persistence_timing_id = None
        if self.timing_manager:
            persistence_timing_id = self.timing_manager.start_operation(
                "artifact_persistence",
                csv_filename,
                metadata={"source": "redfish_streaming_csv"},
                compact_artifact_on_limit=True,
            )
        try:
            with open(events_csv, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(
                    [
                        "Timestamp",
                        "Id",
                        "Severity",
                        "MessageId",
                        "Message",
                        "Resolution",
                    ]
                )
                for event in all_events:
                    writer.writerow(
                        [
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(event.get("Created", ""))
                            ),
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(event.get("Id", ""))
                            ),
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(
                                    event.get("Severity", "")
                                )
                            ),
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(
                                    event.get("MessageId", "")
                                )
                            ),
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(event.get("Message", ""))
                            ),
                            _neutralize_csv_formula(
                                self._sanitize_diagnostic_text(
                                    event.get("Resolution", "")
                                )
                            ),
                        ]
                    )
        except BaseException as exc:
            if self.timing_manager:
                self.timing_manager.end_operation(
                    persistence_timing_id,
                    status=(
                        "cancelled"
                        if isinstance(exc, asyncio.CancelledError)
                        else "error"
                    ),
                    error=(
                        "CancelledError"
                        if isinstance(exc, asyncio.CancelledError)
                        else str(exc)
                    ),
                )
            raise
        if self.timing_manager:
            self.timing_manager.end_operation(
                persistence_timing_id,
                artifact_path=str(events_csv),
            )
        csv_files = [str(events_csv)]

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"Generated {len(csv_files)} CSV files with {len(all_events)} events for {collector_id}",
            dut_id,
        )
        return {"success": True, "output_files": csv_files}

    async def collect_redfish_unified(
        self,
        dut_id: str,
        collection_type: str,  # "get", "paginated", "collection", "sequential", "uri_list", "expand"
        uri_patterns: Union[str, List[str]] = None,
        entity_type: str = None,
        log_service: str = None,
        function_tag: str = "",
        additional_data_callback: bool = False,
        collection_level_handling: Optional[Dict[str, Any]] = None,
        expand_level: int = 1,
        filter_criteria: Optional[Dict[str, Any]] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Unified Redfish collection method that handles all core collection patterns.

        Get configurable expand level if this is an expand collection.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collection_type: Text supplied as collection type in the format
                accepted by this function.
            uri_patterns: Validated remote resource identifier used for URI
                patterns.
            entity_type: Optional entity type; ``None`` selects the function's
                default behavior.
            log_service: Optional log service; ``None`` selects the function's
                default behavior.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Optional collection level handling;
                ``None`` selects the function's default behavior.
            expand_level: Numeric expand level used while the operation performs
                bounded accounting.
            filter_criteria: Optional filter criteria; ``None`` selects the
                function's default behavior.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing Redfish unified.
        """
        controller_policy = kwargs.pop("redfish_controller", None)
        if controller_policy is not None:
            controller_result = None
            try:
                dut = self.dut_manager.get_dut(dut_id)
                controller = resolve_collector_controller(controller_policy, dut.config)
                async with redfish_controller_scope(dut, controller):
                    controller_result = await self.collect_redfish_unified(
                        dut_id,
                        collection_type=collection_type,
                        uri_patterns=uri_patterns,
                        entity_type=entity_type,
                        log_service=log_service,
                        function_tag=function_tag,
                        additional_data_callback=additional_data_callback,
                        collection_level_handling=collection_level_handling,
                        expand_level=expand_level,
                        filter_criteria=filter_criteria,
                        **kwargs,
                    )
                return controller_result
            except Exception as error:
                retained = (controller_result or {}).get("context", {})
                output_files = list(
                    dict.fromkeys(
                        (controller_result or {}).get("output_files", [])
                        + retained.get("output_files", [])
                    )
                )
                successful = retained.get("successful_operations", 0)
                message = f"Redfish controller setup or cleanup failed: {error}"
                await self._log_runtime("ERROR", "RedfishService", message, dut_id)
                return await self._create_standardized_collector_result(
                    successful_operations=successful,
                    total_operations=retained.get("total_operations", 0) + 1,
                    output_files=output_files,
                    error_messages=[*retained.get("error_messages", []), message],
                    operation_name="redfish_unified_collection",
                    additional_context={
                        "collection_type": collection_type,
                        "function_tag": function_tag,
                        "error_type": type(error).__name__,
                        "status": "partial" if successful else "error",
                    },
                )

        collector_name = f"{function_tag}_{collection_type}"
        collector_def = kwargs.get("collector_def", {})

        # Get configurable expand level if this is an expand collection
        if collection_type == "expand":
            dut_config = self.dut_manager.get_dut_config(dut_id)
            explicit_config_keys = {}
            try:
                dut = self.dut_manager.get_dut(dut_id)
                explicit_config_keys = getattr(dut, "explicit_config_keys", {}) or {}
            except Exception:
                explicit_config_keys = {}
            expand_level = get_expand_level(
                kwargs.get("collector_id", ""),
                collector_def,
                dut_config,
                expand_level,
                explicit_config_keys=explicit_config_keys,
            )

        # Extract retry_count from collector definition in kwargs
        retry_count = 3  # Default retry count
        if "collector_def" in kwargs and kwargs["collector_def"]:
            retry_count = kwargs["collector_def"].get("retry_count", 3)

        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"collect_redfish_unified called with: function_tag='{function_tag}', collection_type='{collection_type}', collector_name='{collector_name}', retry_count={retry_count}",
            dut_id,
        )

        # Debug: Log all kwargs to see what parameters are being passed
        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"All kwargs received: {list(kwargs.keys())}",
            dut_id,
        )

        # Debug: Log additional_member_collections specifically
        additional_collections = kwargs.get("additional_member_collections", [])
        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"additional_member_collections parameter: {additional_collections}",
            dut_id,
        )
        collector_id = kwargs.get("collector_id", "")
        try:
            await self._log_collector_start(
                dut_id, collector_name, collector_id=collector_id
            )

            dynamic_discovery_entries = kwargs.get("dynamic_uri_discovery")
            if dynamic_discovery_entries:
                if not isinstance(dynamic_discovery_entries, list):
                    dynamic_discovery_entries = [dynamic_discovery_entries]

                resolved_uri_patterns: Optional[Union[str, List[str]]] = uri_patterns
                resolved_uri_list: Optional[Union[str, List[str]]] = kwargs.get(
                    "uri_list"
                )

                for discovery_entry in dynamic_discovery_entries:
                    if not isinstance(discovery_entry, dict):
                        await self._log_runtime(
                            "WARNING",
                            "RedfishService",
                            f"Skipping invalid dynamic_uri_discovery entry (expected dict): {discovery_entry}",
                            dut_id,
                        )
                        continue

                    (
                        should_apply,
                        baseboard_name,
                    ) = await self._should_apply_dynamic_discovery(
                        dut_id,
                        collector_name,
                        collector_id,
                        function_tag,
                        discovery_entry,
                        collector_def,
                    )

                    if not should_apply:
                        continue

                    context: Dict[str, Any] = {
                        **kwargs,
                        "collector_id": collector_id,
                        "collector_name": collector_name,
                        "function_tag": function_tag,
                        "collection_type": collection_type,
                        "baseboard": baseboard_name,
                    }

                    if (
                        baseboard_name
                        and hasattr(self, "dut_manager")
                        and self.dut_manager
                    ):
                        baseboard_manager = None
                        if hasattr(self.dut_manager, "_get_baseboard_manager"):
                            baseboard_manager = (
                                self.dut_manager._get_baseboard_manager()
                            )
                        if baseboard_manager:
                            baseboard_type = baseboard_manager.get_baseboard_type(
                                baseboard_name
                            )
                            if baseboard_type:
                                context.setdefault("baseboard_type", baseboard_type)

                    discovered_value = await self._perform_dynamic_uri_discovery(
                        dut_id, collector_name, discovery_entry, context
                    )

                    if discovered_value is None:
                        continue

                    target = discovery_entry.get("target", "uri_patterns")
                    behavior = discovery_entry.get("behavior", "override")
                    if isinstance(behavior, str):
                        behavior = behavior.lower()
                    else:
                        behavior = "override"

                    deduplicate = discovery_entry.get("deduplicate", False)

                    if target == "uri_list":
                        resolved_uri_list = self._apply_discovered_value(
                            resolved_uri_list,
                            discovered_value,
                            behavior,
                            deduplicate,
                        )
                    else:
                        resolved_uri_patterns = self._apply_discovered_value(
                            resolved_uri_patterns,
                            discovered_value,
                            behavior,
                            deduplicate,
                        )

                uri_patterns = resolved_uri_patterns
                if resolved_uri_list is not None:
                    kwargs["uri_list"] = resolved_uri_list

                kwargs.pop("dynamic_uri_discovery", None)

            uri_list_from_kwargs = kwargs.get("uri_list")
            if uri_list_from_kwargs:
                if isinstance(uri_list_from_kwargs, str):
                    if uri_list_from_kwargs.startswith(
                        "${"
                    ) and uri_list_from_kwargs.endswith("}"):
                        var_name = uri_list_from_kwargs[2:-1]
                        if var_name in kwargs:
                            uri_list_value = kwargs[var_name]
                            if isinstance(uri_list_value, list):
                                uri_list = uri_list_value
                            else:
                                uri_list = [uri_list_value] if uri_list_value else []
                        else:
                            uri_list = [uri_list_from_kwargs]
                    else:
                        uri_list = [uri_list_from_kwargs]
                elif isinstance(uri_list_from_kwargs, list):
                    uri_list = uri_list_from_kwargs
                else:
                    uri_list = []
                kwargs.pop("uri_list", None)
            else:
                uri_list_key = kwargs.get("uri_list_key")
                if uri_list_key:
                    try:
                        dut_config = self.dut_manager.get_dut_config(dut_id)
                        dut_uri_list = dut_config.get(uri_list_key, [])

                        if isinstance(dut_uri_list, list) and dut_uri_list:
                            uri_list = dut_uri_list
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Using DUT-level URI list from {uri_list_key}: {uri_list}",
                                dut_id,
                            )
                        else:
                            orchestrator = getattr(self, "orchestrator", None)
                            if orchestrator and hasattr(orchestrator, "config_manager"):
                                tool_config = (
                                    orchestrator.config_manager.get_tool_config()
                                )
                            else:
                                tool_config = self.dut_manager.tool_config
                            tool_uri_list = (
                                []
                                if uri_list_key in dut_config
                                else tool_config.get(uri_list_key, [])
                            )
                            if isinstance(tool_uri_list, list) and tool_uri_list:
                                uri_list = tool_uri_list
                                await self._log_runtime(
                                    "INFO",
                                    "RedfishService",
                                    f"Using tool-level URI list from {uri_list_key}: {uri_list}",
                                    dut_id,
                                )
                            else:
                                await self._log_runtime(
                                    "WARNING",
                                    "RedfishService",
                                    f"No URI list found for {uri_list_key} in DUT or tool config - collector will be skipped",
                                    dut_id,
                                )
                                return await self._create_standardized_collector_result(
                                    dut_id=dut_id,
                                    collector_id=kwargs.get(
                                        "collector_id", function_tag
                                    ),
                                    successful_operations=0,
                                    total_operations=0,
                                    output_files=[],
                                    error_messages=[
                                        "No URIs provided in configuration - collector skipped"
                                    ],
                                    operation_name="uri_list_collection",
                                    additional_context={"uri_list_key": uri_list_key},
                                )
                    except Exception as e:
                        await self._log_runtime(
                            "WARNING",
                            "RedfishService",
                            f"Could not load URI list configuration for {uri_list_key}: {e}",
                            dut_id,
                        )
                        return await self._create_standardized_collector_result(
                            dut_id=dut_id,
                            collector_id=kwargs.get("collector_id", function_tag),
                            successful_operations=0,
                            total_operations=0,
                            output_files=[],
                            error_messages=[
                                f"Configuration error for {uri_list_key}: {e}"
                            ],
                            operation_name="uri_list_collection",
                            additional_context={"uri_list_key": uri_list_key},
                        )
                else:
                    if isinstance(uri_patterns, str):
                        uri_list = [uri_patterns]
                    elif isinstance(uri_patterns, list):
                        uri_list = uri_patterns
                    else:
                        uri_list = []

                filtered_systems = kwargs.get("filtered_systems")
                filtered_managers = kwargs.get("filtered_managers")
                filtered_chassis = kwargs.get("filtered_chassis")
                entity_map = {
                    "Systems": filtered_systems,
                    "Managers": filtered_managers,
                    "Chassis": filtered_chassis,
                }

                def filtered_entities_state(
                    entities: Any,
                ) -> Optional[bool]:
                    """
                    Return the filtered entities state.

                    The implementation uses ``entities`` to produce the filtered
                    entities state.

                    Args:
                        entities: Entities consumed while the function attempts
                            to produce the filtered entities state.

                    Returns:
                        Whether the filtered entities state operation succeeds,
                        or ``None`` when the decision is unavailable.
                    """
                    if entities is None:
                        return None
                    if isinstance(entities, list):
                        return len(entities) > 0
                    if hasattr(entities, "__next__"):
                        return True
                    try:
                        return True if len(entities) > 0 else None
                    except TypeError:
                        return None

                entity_states = {
                    entity: filtered_entities_state(entities)
                    for entity, entities in entity_map.items()
                }

                has_placeholder = uri_list and any("{" in uri for uri in uri_list)
                all_uris_str = " ".join(uri_list) if has_placeholder else ""
                placeholder_types = [
                    entity
                    for entity, placeholder in (
                        ("Systems", "{system_id}"),
                        ("Managers", "{manager_id}"),
                        ("Chassis", "{chassis_id}"),
                    )
                    if placeholder in all_uris_str
                ]
                fallback_type = placeholder_types[0] if placeholder_types else None
                matching_filter_is_empty = (
                    len(placeholder_types) == 1
                    and entity_states.get(fallback_type) is False
                )

                if has_placeholder and matching_filter_is_empty:
                    uri_list = []
                elif has_placeholder and any(
                    state is True for state in entity_states.values()
                ):
                    selected_type = next(
                        (
                            candidate_type
                            for candidate_type in (
                                entity_type,
                                "Systems",
                                "Managers",
                                "Chassis",
                            )
                            if entity_states.get(candidate_type) is True
                        ),
                        None,
                    )
                    entities = entity_map[selected_type]
                    expanded = []
                    for ent in entities:
                        eid = ent["id"] if isinstance(ent, dict) else ent
                        expanded.extend(
                            self._process_user_defined_uris(uri_list, eid, entity_type)
                        )
                    if expanded:
                        uri_list = expanded
                elif has_placeholder and self.dut_manager:
                    if fallback_type:
                        member_ids = await self.dut_manager.get_resource_members(
                            dut_id, fallback_type
                        )
                        if member_ids:
                            expanded = []
                            for mid in member_ids:
                                expanded.extend(
                                    self._process_user_defined_uris(
                                        uri_list, mid, fallback_type
                                    )
                                )
                            if expanded:
                                uri_list = expanded

                if (
                    uri_list
                    and self.dut_manager
                    and self.dut_manager.uri_config_manager
                ):
                    uri_list = [
                        self.dut_manager.uri_config_manager._apply_prefix_override(
                            uri, dut_id
                        )
                        for uri in uri_list
                    ]

            if collection_type == "get":
                return await self._handle_get_collection(
                    dut_id, uri_list, function_tag, **kwargs
                )
            elif collection_type == "paginated":
                return await self._handle_paginated_collection(
                    dut_id,
                    entity_type,
                    log_service,
                    function_tag,
                    additional_data_callback,
                    collection_level_handling,
                    uri_list,
                    **kwargs,
                )
            elif collection_type == "existing_dumps":
                return await self._handle_existing_dumps_collection(
                    dut_id, entity_type, log_service, function_tag, **kwargs
                )
            elif collection_type == "collection":
                return await self._handle_collection_with_members(
                    dut_id, uri_list, function_tag, **kwargs
                )
            elif collection_type == "sequential":
                return await self._handle_sequential_collection(
                    dut_id, uri_list, function_tag, **kwargs
                )
            elif collection_type == "uri_list":
                return await self._handle_uri_list_collection(
                    dut_id, entity_type, uri_list, function_tag, **kwargs
                )
            elif collection_type == "expand":
                return await self._handle_expand_collection(
                    dut_id,
                    uri_list,
                    expand_level,
                    function_tag,
                    entity_type=entity_type,
                    **kwargs,
                )
            elif collection_type == "chassis_with_filter":
                return await self._handle_chassis_with_filter_collection(
                    dut_id, uri_list, function_tag, **kwargs
                )
            elif collection_type == "log_processing":
                return await self._handle_log_processing_collection(
                    dut_id, entity_type, log_service, function_tag, **kwargs
                )
            else:
                error_msg = f"Unknown collection_type: {collection_type}"
                await self._log_runtime("ERROR", "RedfishService", error_msg, dut_id)
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[error_msg],
                    operation_name="redfish_unified_collection",
                    additional_context={
                        "collection_type": collection_type,
                        "function_tag": function_tag,
                        "status": "error",
                    },
                )
        except Exception as e:
            error_msg = f"Exception in collect_redfish_unified for collection_type '{collection_type}': {str(e)}"
            await self._log_runtime("ERROR", "RedfishService", error_msg, dut_id)
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[error_msg],
                operation_name="redfish_unified_collection",
                additional_context={
                    "collection_type": collection_type,
                    "function_tag": function_tag,
                    "error_type": type(e).__name__,
                    "status": "error",
                },
            )

    async def _collect_redfish_paginated_logs(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        function_tag: str,
        additional_data_callback: bool = False,
        collection_level_handling: Optional[Dict[str, Any]] = None,
        uri_pattern: Optional[str] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Original paginated logs collection method with full additional data support.

        Check if we have validation results with filtered entities.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Optional collection level handling;
                ``None`` selects the function's default behavior.
            uri_pattern: Validated remote resource identifier used for URI
                pattern.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing Redfish paginated logs.
        """
        collector_name = f"{function_tag}_{entity_type}_{log_service}"
        collector_id = kwargs.get("collector_id", collector_name)
        runtime_budget = self._current_runtime_budget(str(collector_id))
        if (
            runtime_budget is not None
            and runtime_budget.source == "catalog.runtime_budget"
        ):
            pagination_budget = runtime_budget.policies.get("pagination", {})
        else:
            pagination_budget = {}
        requested_entity_concurrency = pagination_budget.get(
            "max_concurrent_entities", 1
        )
        if (
            not isinstance(requested_entity_concurrency, int)
            or isinstance(requested_entity_concurrency, bool)
            or requested_entity_concurrency <= 0
        ):
            requested_entity_concurrency = 1
        entity_concurrency = min(
            requested_entity_concurrency,
            self._runtime_boundary(dut_id, "redfish_max_concurrent_entities"),
        )
        entity_worker_kwargs = dict(kwargs)
        collect_all_pages = entity_worker_kwargs.pop("collect_all_pages", False)
        retry_count = entity_worker_kwargs.pop("retry_count", 3)
        entity_worker_kwargs.pop("uri_pattern", None)
        entity_worker_kwargs.pop("max_concurrent", None)

        try:
            await self._log_collector_start(
                dut_id, collector_name, collector_id=collector_id
            )

            # Check if we have validation results with filtered entities
            filtered_systems = kwargs.get("filtered_systems", [])
            filtered_managers = kwargs.get("filtered_managers", [])
            filtered_chassis = kwargs.get("filtered_chassis", [])

            if entity_type == "Systems" and "filtered_systems" in kwargs:
                # Use filtered systems from validation
                system_ids_for_log = [sys["id"] for sys in filtered_systems]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_systems)} filtered systems from validation: {system_ids_for_log}",
                    dut_id,
                )
                entity_ids = [sys["id"] for sys in filtered_systems]

                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_system_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "system", dut_config)
                if len(entity_ids) != len(original_system_ids):
                    await log_filtered_ids(
                        original_system_ids,
                        entity_ids,
                        "system",
                        self.logger,
                        dut_id,
                    )

                systems_uri = self.get_configured_uri(dut_id, "Systems")
                entities = {
                    "Members": [
                        {"@odata.id": f"{systems_uri}/{sys_id}"}
                        for sys_id in entity_ids
                    ]
                }
            elif entity_type == "Managers" and "filtered_managers" in kwargs:
                # Use filtered managers from validation
                manager_ids_for_log = [mgr["id"] for mgr in filtered_managers]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_managers)} filtered managers from validation: {manager_ids_for_log}",
                    dut_id,
                )
                entity_ids = [mgr["id"] for mgr in filtered_managers]

                # Apply ID filtering based on DUT configuration
                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_manager_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "manager", dut_config)

                # Log filtered IDs if any were filtered
                if len(entity_ids) != len(original_manager_ids):
                    await log_filtered_ids(
                        original_manager_ids,
                        entity_ids,
                        "manager",
                        self.logger,
                        dut_id,
                    )

                managers_uri = self.get_configured_uri(dut_id, "Managers")
                entities = {
                    "Members": [
                        {"@odata.id": f"{managers_uri}/{mgr_id}"}
                        for mgr_id in entity_ids
                    ]
                }
            elif entity_type == "Chassis" and "filtered_chassis" in kwargs:
                # Use filtered chassis from validation
                chassis_ids_for_log = [chassis["id"] for chassis in filtered_chassis]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_chassis)} filtered chassis from validation: {chassis_ids_for_log}",
                    dut_id,
                )
                entity_ids = [chassis["id"] for chassis in filtered_chassis]

                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_chassis_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "chassis", dut_config)
                if len(entity_ids) != len(original_chassis_ids):
                    await log_filtered_ids(
                        original_chassis_ids,
                        entity_ids,
                        "chassis",
                        self.logger,
                        dut_id,
                    )

                chassis_uri = self.get_configured_uri(dut_id, "Chassis")
                entities = {
                    "Members": [
                        {"@odata.id": f"{chassis_uri}/{chassis_id}"}
                        for chassis_id in entity_ids
                    ]
                }
            else:
                # Get entities - dut_manager handles URI construction automatically
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No filtered {entity_type.lower()} found in context, fetching all {entity_type}",
                    dut_id,
                )
                entity_uri = self.get_configured_uri(dut_id, entity_type)
                success, entities, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    entity_uri,
                    error_context=f"get {entity_type}",
                )

                if not success:
                    return await self._handle_collector_error(
                        dut_id,
                        collector_name,
                        f"Failed to get {entity_type}: {entities}",
                    )

            output_files = []
            all_status_list = []
            all_collected_files = []
            error_messages = []
            skipped_entities = []  # Track entities that were skipped
            pagination_entity_summaries = []
            degraded_pagination_results = []
            partial_pagination_results = []
            failed_pagination_results = []
            usable_pagination_results = 0
            request_timeout_observed = False

            def _bounded_pagination_evidence(
                entity_id: Any, reason: Any, fallback: str
            ) -> Dict[str, str]:
                """
                Return sanitizer-safe, bounded child-result evidence.

                The implementation uses ``entity_id``, ``reason``, and
                ``fallback`` to produce sanitizer-safe, bounded child-result
                evidence.

                Args:
                    entity_id: Stable entity identifier used to correlate
                        configuration, logs, and results.
                    reason: Reason consumed while the function attempts to
                        produce sanitizer-safe, bounded child-result evidence.
                    fallback: Text supplied as fallback in the format accepted
                        by this function.

                Returns:
                    A mapping containing the ``entity_id`` and ``reason``
                    fields.
                """

                evidence_reason = (
                    fallback
                    if reason is None or (type(reason) is str and not reason)
                    else reason
                )
                return {
                    "entity_id": self._bounded_diagnostic_log_text(entity_id),
                    "reason": self._bounded_diagnostic_log_text(evidence_reason),
                }

            def _bounded_pagination_reason(
                prefix: str,
                evidence_groups: List[Tuple[str, List[Dict[str, str]]]],
            ) -> str:
                """
                Render every evidence class within the diagnostic text bound.

                The implementation uses ``prefix`` and ``evidence_groups`` to
                render every evidence class within the diagnostic text bound.
                The source value keeps its ownership while the normalized
                representation is returned separately.

                Args:
                    prefix: Text supplied as prefix in the format accepted by
                        this function.
                    evidence_groups: Mapping supplying fields for every evidence
                        class within the diagnostic text bound.

                Returns:
                    The canonical bounded pagination reason text.
                """

                populated_groups = [
                    (label, evidence) for label, evidence in evidence_groups if evidence
                ]
                if not populated_groups:
                    return self._bounded_diagnostic_log_text(prefix)

                separators_size = 3 * (len(populated_groups) - 1)
                available = max(
                    len(populated_groups),
                    _DIAGNOSTIC_LOG_TEXT_MAX_CHARS - len(prefix) - separators_size,
                )
                group_budget = max(1, available // len(populated_groups))
                rendered_groups = []
                for label, evidence in populated_groups:
                    bounded_items = evidence[:_DIAGNOSTIC_LOG_MAX_ITEMS]
                    rendered = self._bounded_diagnostic_log_text(
                        f"{label}: "
                        + "; ".join(
                            f"{item['entity_id']}: {item['reason']}"
                            for item in bounded_items
                        )
                    )
                    omitted = len(evidence) - len(bounded_items)
                    if omitted:
                        rendered += f"; <omitted items={omitted}>"
                    if len(rendered) > group_budget:
                        marker = f"<truncated chars={len(rendered)}>"
                        retained = max(0, group_budget - len(marker))
                        rendered = f"{rendered[:retained]}{marker}"
                    rendered_groups.append(rendered)

                return f"{prefix}{' | '.join(rendered_groups)}"

            # Process entities concurrently for better performance
            async def _process_entity_logs(
                dut_id: str, entity_id: str, **kwargs
            ) -> Dict[str, Any]:
                # _collect_optimized_paginated_logs now returns a standardized collector result
                """
                Process entity logs.

                The implementation uses ``dut_id``, ``entity_id``, and
                ``kwargs`` to process entity logs. Terminal status is emitted
                only after entity logs and its owned cleanup have completed.
                Owned asynchronous work is awaited before return, so completion
                does not leave an unobserved task behind.

                Args:
                    dut_id: Stable DUT identifier used to correlate
                        configuration, logs, and results.
                    entity_id: Stable entity identifier used to correlate
                        configuration, logs, and results.
                    kwargs: Additional named values forwarded without changing
                        their keys.

                Returns:
                    The validated ``result``.
                """
                result = await self._collect_optimized_paginated_logs(
                    dut_id,
                    entity_type,
                    entity_id,
                    log_service,
                    function_tag,
                    additional_data_callback,
                    collection_level_handling,
                    collect_all_pages=collect_all_pages,
                    uri_pattern=uri_pattern,
                    retry_count=retry_count,
                    **kwargs,
                )

                # Return the standardized result directly
                return result

            # Extract entity IDs from members
            members = entities.get("Members", [])
            entity_ids = []
            entity_members = []
            for member in members:
                odata_id = member.get("@odata.id", "")
                if odata_id:
                    entity_id = odata_id.split("/")[-1]
                    entity_ids.append(entity_id)
                    entity_members.append(member)

            entity_results = await self._concurrent_entity_processing(
                dut_id,
                entity_members,
                _process_entity_logs,
                max_concurrent=entity_concurrency,
                **entity_worker_kwargs,
            )

            # Reduce results in source-entity order so aggregation and emitted
            # evidence remain deterministic even when requests overlap.
            for entity_id, result in zip(entity_ids, entity_results):
                if not isinstance(result, dict):
                    result = {
                        "success": False,
                        "status": "error",
                        "reason": (
                            "Paginated entity processing failed before a "
                            "collector result was produced"
                        ),
                        "context": {"status_list": [False], "output_files": []},
                    }

                # Extract data from standardized result
                context = result.get("context", {})
                status = result.get("status", "success")
                if (
                    isinstance(context, dict)
                    and context.get("exception_type") == "TimeoutError"
                ):
                    request_timeout_observed = True

                pagination_summary_keys = (
                    "raw_rows_observed",
                    "raw_rows_collected",
                    "snapshot_boundary_rows_discarded",
                    "unique_rows_collected",
                    "duplicate_rows",
                    "initial_total_entries",
                    "requested_target_entries",
                    "target_max_entries",
                    "entries_omitted_by_policy",
                    "entries_not_collected",
                    "collection_scope",
                    "requested_scope_complete",
                    "requested_cursor_scope_complete",
                    "requested_entry_target_complete",
                    "initial_snapshot_complete",
                    "policy_scope_note",
                    "pagination_consistency",
                    "pagination_offset_continuity",
                    "pagination_sparse_cursor_detected",
                    "pagination_cursor_gap_count",
                    "pagination_cursor_gap_positions",
                    "pagination_cursor_gap_max_positions",
                    "pagination_cursor_gap_evidence",
                    "pagination_sparse_cursor_degraded_reason",
                    "snapshot_boundary",
                    "snapshot_watermark_field",
                    "snapshot_watermark_valid",
                    "snapshot_watermark_error",
                    "pagination_shortfall",
                    "snapshot_drift",
                    "snapshot_growth_observed",
                    "snapshot_regression_observed",
                    "snapshot_drift_reconciled",
                    "snapshot_drift_unreconciled",
                    "snapshot_members_error",
                    "snapshot_page_count_error",
                    "pagination_continuity_error",
                    "page_count",
                    "pagination_stop_reason",
                    "pagination_complete",
                    "additional_data_attachment_policy",
                    "additional_data_attachments_discovered",
                    "additional_data_attachments_attempted",
                    "additional_data_attachments_collected",
                    "additional_data_attachments_failed",
                    "additional_data_attachment_manifest",
                )
                if any(key in context for key in pagination_summary_keys):
                    pagination_entity_summaries.append(
                        {
                            "entity_id": entity_id,
                            **{
                                key: context[key]
                                for key in pagination_summary_keys
                                if key in context
                            },
                        }
                    )

                # Initialize additional_data to avoid UnboundLocalError in error cases
                additional_data = {}
                additional_data_owned_by_worker = False

                # Add detailed logging for result processing
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"UNIFIED_RESULT_DEBUG: {entity_type} {entity_id} - result={result}, status={status}",
                    dut_id,
                )

                # Handle success, degraded, partial, error, and skipped results.
                if status == "skipped":
                    all_status_list.append(True)  # Treat skipped as successful
                    skipped_entities.append(
                        entity_id
                    )  # Track that this entity was skipped
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Skipped collection for {entity_type} {entity_id}: {result.get('reason', 'Unknown reason')}",
                        dut_id,
                    )
                elif status in ["success", "degraded", "partial"]:
                    # Extract data from standardized usable results.
                    usable_pagination_results += 1
                    status_list = context.get(
                        "status_list", [True]
                    )  # Default to success
                    collected_files = context.get("output_files", [])
                    additional_data = context.get("additional_data", {})
                    additional_data_owned_by_worker = bool(
                        context.get("additional_data_owned_by_worker", False)
                    )

                    # Extend status list and collected files
                    all_status_list.extend(status_list)
                    all_collected_files.extend(collected_files)

                    if status in {"degraded", "partial"}:
                        partial_evidence = _bounded_pagination_evidence(
                            entity_id,
                            result.get("reason"),
                            f"Incomplete paginated collection for {entity_type} {entity_id}",
                        )
                        result_bucket = (
                            degraded_pagination_results
                            if status == "degraded"
                            else partial_pagination_results
                        )
                        result_bucket.append(partial_evidence)
                        error_messages.append(
                            f"{entity_type} {partial_evidence['entity_id']}: "
                            f"{partial_evidence['reason']}"
                        )

                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Adding {len(collected_files)} files from {entity_type} {entity_id} to all_collected_files: {collected_files}",
                        dut_id,
                    )
                else:
                    # Handle failure case (status == "error")
                    all_status_list.append(False)
                    failure_evidence = _bounded_pagination_evidence(
                        entity_id,
                        result.get("reason"),
                        "Unknown error",
                    )
                    failed_pagination_results.append(failure_evidence)
                    error_messages.append(
                        f"{entity_type} {failure_evidence['entity_id']}: "
                        f"{failure_evidence['reason']}"
                    )

                    # Create error log file for failed operations
                    error_log_path = await self._create_error_log_file(
                        dut_id=dut_id,
                        collector_id=collector_name,
                        error_message=failure_evidence["reason"],
                        context={
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "operation": "paginated_logs_collection",
                            "result": result,
                        },
                    )

                    # Add error log file to output files
                    if error_log_path:
                        all_collected_files.append(error_log_path)

                # Check for error in additional_data (now handled in the result structure above)
                # Additional data error handling is now done in the standardized result

                # Handle additional data if callback is enabled
                if (
                    additional_data_callback
                    and additional_data
                    and not additional_data_owned_by_worker
                ):
                    # Debug logging
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Processing additional data for {entity_type} {entity_id}: {len(additional_data)} attachments",
                        dut_id,
                    )

                    additional_data_pattern = kwargs.get("additional_data_pattern", "")
                    if additional_data_pattern:
                        # Use the additional data pattern with proper substitutions
                        additional_filename = self.substitute_output_pattern_variables(
                            additional_data_pattern,
                            {
                                self._get_entity_id_key(entity_type): entity_id,
                            },
                            f"{function_tag}_{entity_type}_{entity_id}_additional_data.json",
                        )
                    else:
                        additional_filename = f"{function_tag}_{entity_type}_{entity_id}_additional_data.json"

                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Saving additional data to: {additional_filename}",
                        dut_id,
                    )

                    additional_file = await self._save_data_to_file_with_pattern(
                        dut_id,
                        additional_data,
                        additional_filename,
                        additional_data_pattern=additional_data_pattern,
                        substitutions={
                            self._get_entity_id_key(entity_type): entity_id,
                            "entity_id": entity_id,
                        },
                        collector_id=kwargs.get("collector_id"),
                    )

                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Additional data save result: {additional_file}",
                        dut_id,
                    )

                    if additional_file:
                        all_collected_files.append(additional_file)
                    else:
                        error_message = (
                            f"Failed to save additional data for {entity_type} "
                            f"{entity_id}"
                        )
                        all_status_list.append(False)
                        error_messages.append(error_message)
                        failed_pagination_results.append(
                            _bounded_pagination_evidence(
                                entity_id,
                                error_message,
                                "Failed to save additional paginated data",
                            )
                        )
                        await self._log_runtime(
                            "ERROR",
                            "RedfishService",
                            error_message,
                            dut_id,
                        )
                elif additional_data_owned_by_worker:
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        "Additional data aggregate already persisted by pagination "
                        f"worker for entity {entity_id}",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Additional data callback disabled or no additional data for entity {entity_id}",
                        dut_id,
                    )

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"About to extend output_files with {len(all_collected_files)} files from all_collected_files: {all_collected_files}",
                dut_id,
            )
            output_files.extend(all_collected_files)
            diagnostic_files = []
            non_diagnostic_files = []
            artifact_root = getattr(self.logger, "base_log_dir", None)
            for file_path in output_files:
                if self._is_diagnostic_capture_file(
                    file_path,
                    bundle_root=artifact_root,
                ) or self._is_error_artifact_file(
                    file_path,
                    bundle_root=artifact_root,
                ):
                    diagnostic_files.append(file_path)
                else:
                    non_diagnostic_files.append(file_path)
            output_files = non_diagnostic_files
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"output_files now has {len(output_files)} total files: {output_files}",
                dut_id,
            )

            # Create standardized result in one call
            successful_collections = len([s for s in all_status_list if s])
            total_collections = len(all_status_list)
            all_successful_entities_empty = bool(entity_ids) and (
                successful_collections == total_collections
                and not error_messages
                and len(pagination_entity_summaries) == len(entity_ids)
                and all(
                    summary.get("unique_rows_collected") == 0
                    for summary in pagination_entity_summaries
                )
            )

            # Handle the case where no collections were attempted (e.g., no entries in EventLog)
            # as an expected no-data outcome, not a successful data collection.
            if total_collections == 0 and usable_pagination_results == 0:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No collections attempted for {entity_type} {log_service} - treating as expected no-data",
                    dut_id,
                )
                result = await self._create_no_data_skipped_result(
                    log_service=log_service,
                    reason=f"No {log_service} entries found for {entity_type} - expected no-data",
                    output_files=output_files,
                    operation_name="collections",
                    additional_context={
                        "entities_processed": len(entity_ids),
                        "successful_collections": 0,
                        "total_collections": 0,
                    },
                )
            elif (
                successful_collections == 0
                and total_collections > 0
                and usable_pagination_results == 0
            ):
                # All collections failed - check if this is due to service not being available
                # If all errors are 404s, treat as "skipped" rather than "error"
                all_404_errors = all(
                    "404" in error
                    or "not found" in error.lower()
                    or "not supported" in error.lower()
                    for error in error_messages
                )

                # Check if all errors are pagination-related (502, 503, etc.)
                all_pagination_errors = all(
                    any(
                        pagination_error in error.lower()
                        for pagination_error in [
                            "502",
                            "503",
                            "504",
                            "bad gateway",
                            "service unavailable",
                            "gateway timeout",
                            "timeout",
                            "connection refused",
                        ]
                    )
                    for error in error_messages
                )

                if all_404_errors:
                    # Contract: the collector ran because it is applicable for
                    # this baseboard, so the service is guaranteed present. A
                    # 404 on every entity is a contract violation reported as an
                    # error, not a skip.
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"{log_service} service not available for {entity_type}; "
                        f"collector is applicable for this baseboard - treating as error",
                        dut_id,
                    )
                    result = await self._create_standardized_collector_result(
                        dut_id=dut_id,
                        collector_id=kwargs.get(
                            "collector_id", f"{entity_type}_{log_service}"
                        ),
                        successful_operations=0,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": 0,
                            "total_collections": total_collections,
                            "service_not_available": True,
                            "status": "error",
                            "reason": (
                                f"{log_service} service not available for {entity_type} "
                                f"but collector is applicable for this baseboard"
                            ),
                        },
                    )
                elif all_pagination_errors:
                    # This branch is reached only when no collection succeeded.
                    # Diagnostic/error evidence must not promote it to partial.
                    status = "error"
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Pagination errors for {log_service} on {entity_type} - treating as {status} with {len(output_files)} primary files collected",
                        dut_id,
                    )

                    # Create detailed error message with specific URIs and retry information
                    detailed_error_msg = f"Pagination errors (502/503) occurred for {log_service} on {entity_type}. "
                    detailed_error_msg += (
                        "Error details saved to JSON files for manual investigation."
                    )

                    result = await self._create_standardized_collector_result(
                        dut_id=dut_id,
                        collector_id=kwargs.get(
                            "collector_id", f"{entity_type}_{log_service}"
                        ),
                        successful_operations=0,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": len(output_files),
                            "total_collections": total_collections,
                            "pagination_errors": True,
                            "status": status,
                            "reason": detailed_error_msg,
                        },
                    )
                else:
                    # Real errors occurred
                    result = await self._create_standardized_collector_result(
                        successful_operations=successful_collections,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                        },
                    )
            else:
                usable_with_explicit_failure = bool(
                    usable_pagination_results and failed_pagination_results
                )
                if partial_pagination_results or usable_with_explicit_failure:
                    partial_reason = _bounded_pagination_reason(
                        "Partial paginated log collection: ",
                        [
                            ("partial", partial_pagination_results),
                            ("degraded", degraded_pagination_results),
                            ("failed", failed_pagination_results),
                        ],
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=successful_collections,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                            "partial_pagination_results": partial_pagination_results,
                            "degraded_pagination_results": degraded_pagination_results,
                            "failed_pagination_results": failed_pagination_results,
                            "pagination_entity_summaries": pagination_entity_summaries,
                            "status": "partial",
                            "reason": partial_reason,
                        },
                    )
                elif degraded_pagination_results:
                    degraded_reason = _bounded_pagination_reason(
                        "Degraded paginated log collection: ",
                        [("degraded", degraded_pagination_results)],
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=successful_collections,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                            "degraded_pagination_results": degraded_pagination_results,
                            "pagination_entity_summaries": pagination_entity_summaries,
                            "status": "degraded",
                            "reason": degraded_reason,
                        },
                    )
                elif all_successful_entities_empty:
                    empty_collections = len(pagination_entity_summaries)
                    empty_reason = (
                        f"Successfully completed {successful_collections}/{total_collections} "
                        f"{log_service} collections; no entries found across "
                        f"{empty_collections} {entity_type.lower()} resource(s)"
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=successful_collections,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=[],
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                            "no_data_collected": True,
                            "empty_collections": empty_collections,
                            "status": "success",
                            "reason": empty_reason,
                        },
                    )
                # Check if all entities were skipped
                elif skipped_entities and len(skipped_entities) == len(entity_ids):
                    # Contract: the collector ran because it is applicable for
                    # this baseboard, so the service is guaranteed present on the
                    # (post-filter) entities it targets. Every entity lacking the
                    # service is a contract violation reported as an error.
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"All {entity_type} entities lack {log_service} but collector "
                        f"is applicable for this baseboard - treating as error",
                        dut_id,
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=(
                            error_messages
                            or [
                                f"{log_service} not available on any {entity_type} entity "
                                f"({', '.join(skipped_entities)})"
                            ]
                        ),
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                            "skipped_entities": skipped_entities,
                            "status": "error",
                            "reason": (
                                f"All {entity_type} entities lack {log_service} but "
                                f"collector is applicable for this baseboard"
                            ),
                        },
                    )
                else:
                    result = await self._create_standardized_collector_result(
                        successful_operations=successful_collections,
                        total_operations=total_collections,
                        output_files=output_files,
                        error_messages=error_messages,
                        operation_name="collections",
                        additional_context={
                            "entities_processed": len(entity_ids),
                            "successful_collections": successful_collections,
                            "total_collections": total_collections,
                        },
                    )

            if (
                request_timeout_observed
                and isinstance(result, dict)
                and result.get("status") in {"degraded", "partial", "error"}
            ):
                # Entity results are aggregated into one collector result. Keep
                # the trusted timeout classifier signal across that boundary;
                # free-form failure text remains diagnostic-only evidence.
                result.setdefault("context", {})["exception_type"] = "TimeoutError"
            if pagination_entity_summaries and isinstance(result, dict):
                result.setdefault("context", {}).setdefault(
                    "pagination_entity_summaries", pagination_entity_summaries
                )
            if diagnostic_files and isinstance(result, dict):
                result_diagnostic_files = result.setdefault("context", {}).setdefault(
                    "diagnostic_files", []
                )
                for file_path in diagnostic_files:
                    if file_path not in result_diagnostic_files:
                        result_diagnostic_files.append(file_path)
            if isinstance(result, dict):
                result.setdefault("context", {})["pagination_entity_concurrency"] = {
                    "requested": requested_entity_concurrency,
                    "effective": (
                        min(entity_concurrency, len(entity_ids)) if entity_ids else 0
                    ),
                    "entities": len(entity_ids),
                }

            return await self._handle_collector_result(dut_id, collector_name, result)

        except Exception as e:
            return await self._handle_collector_exception(dut_id, collector_name, e)

    @staticmethod
    def _paginated_log_entry_key(entry: Any) -> str:
        """
        Return a stable identity for deduplicating paginated log entries.

        After applying local validation, the function forwards ``entry`` to
        ``paginated_log_entry_key`` and preserves its return and exception
        contract.

        Args:
            entry: Entry evaluated while performing stable identity for
                deduplicating paginated log entries.

        Returns:
            The canonical paginated log entry key text.
        """
        return paginated_log_entry_key(entry)

    @staticmethod
    def _redfish_created_timestamp(entry: Any) -> Optional[float]:
        """
        Return a UTC timestamp for a valid Redfish ``Created`` value.

        After applying local validation, the function forwards ``entry`` to
        ``redfish_created_timestamp`` and preserves its return and exception
        contract.

        Args:
            entry: Entry evaluated while performing UTC timestamp for a valid
                Redfish ``Created`` value.

        Returns:
            The numeric Redfish created timestamp value, or ``None`` when the
            requested value is unavailable.
        """
        return redfish_created_timestamp(entry)

    @classmethod
    def _additional_data_attachment_sort_key(
        cls, uri: str, entry: Any
    ) -> Tuple[int, float, str]:
        """
        Order valid timestamps newest-first, then use URI deterministically.

        After applying local validation, the function forwards ``uri`` and
        ``entry`` to ``additional_data_attachment_sort_key`` and preserves its
        return and exception contract.

        Args:
            uri: Validated remote resource identifier used for URI.
            entry: Entry evaluated while performing order valid timestamps
                newest-first, then use URI deterministically.

        Returns:
            A tuple containing the fields that represent additional data
            attachment sort key.
        """
        return additional_data_attachment_sort_key(
            uri,
            entry,
            timestamp_getter=cls._redfish_created_timestamp,
        )

    async def _collect_optimized_paginated_logs(
        self,
        dut_id: str,
        entity_type: str,
        entity_id: str,
        log_service: str,
        function_tag: str,
        additional_data_callback: bool = False,
        collection_level_handling: Optional[Dict[str, Any]] = None,
        uri_pattern: Optional[str] = None,
        retry_count: int = 3,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect optimized paginated logs.

        The implementation uses ``dut_id``, ``entity_type``, ``entity_id``,
        ``log_service``, and ``function_tag`` to collect optimized paginated
        logs. Terminal status is emitted only after optimized paginated logs and
        its owned cleanup have completed. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.
        Filesystem effects remain confined to the caller-selected paths and the
        owning resource lifecycle. Remote I/O uses the configured transport
        policy and returns only after its response or failure has been observed.
        If the function cannot collect optimized paginated logs, its exception
        reaches the caller instead of being converted into a successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            log_service: Text supplied as log service in the format accepted by
                this function.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            additional_data_callback: Whether additional data callback is
                enabled or required for this operation.
            collection_level_handling: Optional collection level handling;
                ``None`` selects the function's default behavior.
            uri_pattern: Validated remote resource identifier used for URI
                pattern.
            retry_count: Numeric retry count used by the operation's bounded
                accounting.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing optimized paginated logs.

        Raises:
            ValueError: If unsupported additional_data_manifest_mode:
                ``additional_data_manifest_mode``.
        """
        try:
            # Initialize collection variables
            collected_files = []
            output_pattern = kwargs.get("output_pattern", "")
            resolved_collector_id = kwargs.get(
                "collector_id"
            ) or await self._get_original_collector_id(
                dut_id, self._get_current_collector_id()
            )
            runtime_budget = self._current_runtime_budget(str(resolved_collector_id))
            if (
                runtime_budget is not None
                and runtime_budget.source != "catalog.runtime_budget"
            ):
                runtime_budget = None
            pagination_budget = (
                runtime_budget.policies.get("pagination", {})
                if runtime_budget is not None
                else {}
            )
            configured_members_per_page = pagination_budget.get(
                "max_members_per_page",
                self.MAX_PAGINATED_PAGE_MEMBERS,
            )
            if (
                not isinstance(configured_members_per_page, int)
                or isinstance(configured_members_per_page, bool)
                or configured_members_per_page <= 0
            ):
                configured_members_per_page = self.MAX_PAGINATED_PAGE_MEMBERS
            max_members_per_page = min(
                configured_members_per_page,
                self.MAX_PAGINATED_PAGE_MEMBERS,
            )
            pagination_consistency = pagination_budget.get(
                "consistency", "bounded_live_window"
            )
            initial_snapshot_consistency = pagination_consistency == "initial_snapshot"
            pagination_offset_continuity = pagination_budget.get(
                "offset_continuity", "exact"
            )
            if pagination_offset_continuity not in {"exact", "monotonic"}:
                pagination_offset_continuity = "exact"
            allow_forward_offset_gaps = pagination_offset_continuity == "monotonic"
            request_timeout = (
                runtime_budget.operation_timeout_seconds
                if runtime_budget is not None
                else await self._resolve_collector_timeout(
                    dut_id,
                    kwargs,
                    default_timeout=300,
                    collector_id=str(resolved_collector_id),
                    explicit_timeout_keys=("request_timeout", "timeout"),
                    explicit_timeout_sources=[kwargs],
                )
            )
            if runtime_budget is not None:
                retry_count = runtime_budget.max_retries
            entity_id_key = self._get_entity_id_key(entity_type)
            base_substitutions = {
                entity_id_key: entity_id,
                "entity_id": entity_id,
            }
            additional_data_manifest_mode = kwargs.get("additional_data_manifest_mode")
            if additional_data_manifest_mode not in {None, "all_advertised"}:
                raise ValueError(
                    "Unsupported additional_data_manifest_mode: "
                    f"{additional_data_manifest_mode!r}"
                )
            tracked_attachment_callback = bool(
                additional_data_callback
                and additional_data_manifest_mode == "all_advertised"
            )

            # Get collection level and determine skip amount
            collection_level = kwargs.get("collection_level", "L3")
            collect_all_pages = kwargs.get("collect_all_pages", False)

            # Get configurable nextLink field name (default to standard Redfish)
            next_link_field = kwargs.get("next_link_field", "Members@odata.nextLink")
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Using nextLink field: '{next_link_field}' for {entity_type} {entity_id}",
                dut_id,
            )

            # Use common skip amount calculator
            if collect_all_pages:
                skip_amount = 0
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"COLLECT_ALL_PAGES flag enabled: collecting all pages from beginning for {entity_type} {entity_id}",
                    dut_id,
                )
            else:
                skip_amount = self._get_skip_amount(
                    collection_level, collection_level_handling
                )
                if skip_amount > 0:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using explicit collection level {collection_level} entry window: newest {skip_amount} entries for {entity_type} {entity_id}",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"No entry window configured for collection level {collection_level}; collecting the complete initial snapshot for {entity_type} {entity_id}",
                        dut_id,
                    )

            collect_complete_snapshot = collect_all_pages or skip_amount <= 0

            # Build the base URI for the log service
            if uri_pattern:
                base_uri = uri_pattern.replace("{entity_id}", entity_id)
            else:
                entity_base_uri = self.get_configured_uri(dut_id, entity_type)
                base_uri = (
                    f"{entity_base_uri}/{entity_id}/LogServices/{log_service}/Entries"
                )

            # Check for custom URIs in configuration (generic approach)
            # Skip this check if we're already processing custom URIs to avoid infinite recursion
            custom_uri_key = kwargs.get("custom_uri_key")
            if custom_uri_key and not kwargs.get("_processing_custom_uris", False):
                # Check for custom URIs in configuration
                custom_uris = await self._get_custom_uris_from_config(
                    dut_id, entity_id, custom_uri_key, entity_type
                )
                if custom_uris:
                    # Use custom URIs instead of default service
                    return await self._collect_custom_uris(
                        dut_id,
                        entity_type,
                        entity_id,
                        custom_uris,
                        function_tag,
                        log_service,
                        **kwargs,
                    )

            # For PostCodes log service, check if the service exists before accessing Entries
            if log_service == "PostCodes":
                if uri_pattern:
                    # Extract the service URI from the pattern by removing "/Entries"
                    log_service_uri = uri_pattern.replace(
                        "{entity_id}", entity_id
                    ).replace("/Entries", "")
                else:
                    log_service_uri = (
                        f"{entity_base_uri}/{entity_id}/LogServices/{log_service}"
                    )
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Checking PostCodes service existence: GET {log_service_uri} for {entity_type} {entity_id}",
                    dut_id,
                )

                (
                    service_success,
                    service_response,
                    service_metadata,
                ) = await self.dispatch_request(
                    dut_id,
                    "GET",
                    log_service_uri,
                    error_context=f"check {log_service} service for {entity_type} {entity_id}",
                    bypass_cache=True,
                    retry_count=retry_count,
                )

                if not service_success:
                    entity_type_singular = entity_type.lower().rstrip("s")
                    # Contract: the collector ran because it is applicable for
                    # this baseboard, so the PostCodes service is guaranteed
                    # present. A 404 is therefore a contract violation (a real
                    # firmware/platform gap or an inaccurate catalog
                    # applicability) and is reported as an error, not a skip.
                    missing_reason = (
                        f"PostCodes service is not available on this "
                        f"{entity_type_singular} type"
                    )
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"{missing_reason} ({entity_id}); collector is applicable "
                        f"for this baseboard - treating as error",
                        dut_id,
                    )

                    # Create a JSON file documenting the missing PostCodes service
                    info_response = {
                        "info": "PostCodes service check attempted",
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "service_uri": log_service_uri,
                        "status": "error",
                        "reason": missing_reason,
                        "error_details": self._bounded_response_metadata_summary(
                            service_response,
                            service_metadata,
                        ),
                        "timestamp": datetime.now().isoformat(),
                        "note": f"This {entity_type_singular} type does not support PostCodes service via Redfish",
                    }

                    output_file = (
                        "diagnostic/"
                        f"{function_tag}_postcodes_service_check_{entity_id}.json"
                    )
                    file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        info_response,
                        output_file,
                        filename=kwargs.get("filename", ""),
                        substitutions={"entity_id": entity_id},
                        collector_id=kwargs.get("collector_id"),
                    )
                    return await self._create_standardized_collector_result(
                        dut_id=dut_id,
                        collector_id=kwargs.get(
                            "collector_id",
                            f"{entity_type}_{entity_id}_{log_service}",
                        ),
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[
                            f"{missing_reason} (GET {log_service_uri}); response metadata="
                            + self._bounded_response_metadata_text(
                                service_response,
                                service_metadata,
                            )
                        ],
                        operation_name="service_check",
                        additional_context={
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "log_service": log_service,
                            "service_not_available": True,
                            "diagnostic_files": [file_path] if file_path else [],
                            "status": "error",
                            "reason": missing_reason,
                        },
                    )

            # Streaming filters must be part of the initial snapshot request so
            # count/skip calculations describe the same window we paginate.
            unfiltered_base_uri = base_uri
            base_uri = await self._append_streaming_time_filter(dut_id, base_uri)
            streaming_time_filtered = base_uri != unfiltered_base_uri

            # Log the initial request URI for debugging
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"INITIAL_REQUEST_URI: GET {base_uri} for {entity_type} {entity_id}",
                dut_id,
            )

            # Get initial response to determine total entries
            initial_request_start_time = time.time()
            success, response, initial_request_metadata = await self.dispatch_request(
                dut_id,
                "GET",
                base_uri,
                error_context=f"fetch {log_service} Logs for {entity_type} {entity_id}",
                timeout=request_timeout,
                bypass_cache=True,
                retry_count=retry_count,
            )
            initial_request_duration = time.time() - initial_request_start_time

            if not success:
                response_metadata_text = self._bounded_response_metadata_text(
                    response,
                    initial_request_metadata,
                )
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Initial request failed for {log_service} logs on "
                    f"{entity_type} {entity_id}; response metadata="
                    f"{response_metadata_text}",
                    dut_id,
                )

                # Check if this is a 404 (URI not found) - this is not a failure, just informational
                is_404_error = self._is_404_error(response)
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"404 check result for {log_service} logs on {entity_type} {entity_id}: {is_404_error}",
                    dut_id,
                )

                if is_404_error:
                    entity_type_singular = entity_type.lower().rstrip("s")
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"{log_service} logs are not supported on this {entity_type_singular} type ({entity_id})",
                        dut_id,
                    )

                    # Create a JSON file documenting that logs are not available
                    info_response = {
                        "info": f"{log_service} log collection attempted",
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "uri": base_uri,
                        "status": "not_supported",
                        "reason": f"{log_service} logs appear to not be supported on this {entity_type_singular} type",
                        "error_details": (
                            self._bounded_response_metadata_summary(
                                response,
                                initial_request_metadata,
                            )
                        ),
                        "timestamp": datetime.now().isoformat(),
                        "note": f"This {entity_type_singular} type does not support {log_service} log collection via Redfish",
                    }

                    output_file = (
                        f"{function_tag}_{log_service.lower()}_entries_{entity_id}.json"
                    )
                    fault_log_diagnostic = log_service == "FaultLog"
                    if fault_log_diagnostic:
                        output_file = f"diagnostic/{output_file}"
                    file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        info_response,
                        output_file,
                        filename=kwargs.get("filename", ""),
                        substitutions={"entity_id": entity_id},
                        collector_id=kwargs.get("collector_id"),
                    )
                    return await self._create_standardized_collector_result(
                        dut_id=dut_id,
                        collector_id=kwargs.get(
                            "collector_id",
                            f"{entity_type}_{entity_id}_{log_service}",
                        ),
                        successful_operations=0,
                        total_operations=1,
                        output_files=(
                            []
                            if fault_log_diagnostic
                            else [file_path] if file_path else []
                        ),
                        error_messages=[
                            f"{log_service} logs are not supported on this {entity_type_singular} type"
                        ],
                        operation_name="404_handling",
                        additional_context={
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "log_service": log_service,
                            "service_not_available": True,
                            **(
                                {"diagnostic_files": ([file_path] if file_path else [])}
                                if fault_log_diagnostic
                                else {}
                            ),
                            "status": "error",
                            "reason": f"{log_service} logs are not supported on this {entity_type_singular} type",
                        },
                    )
                else:
                    error_msg = (
                        f"Failed to collect {log_service} logs for {entity_type} "
                        f"{entity_id}; response metadata={response_metadata_text}"
                    )
                    request_failure_context = {
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "log_service": log_service,
                        "error_type": "request_failure",
                    }
                    if (
                        isinstance(initial_request_metadata, dict)
                        and dict.get(initial_request_metadata, "error")
                        == "request_timeout"
                    ):
                        # Terminal projection deliberately recomputes categories
                        # from structured evidence. Preserve the transport's
                        # timeout identity using the classifier's stable
                        # serialized-exception signal instead of parsing a
                        # response or diagnostic message.
                        request_failure_context["exception_type"] = "TimeoutError"
                    return await self._create_standardized_collector_result(
                        dut_id=dut_id,
                        collector_id=kwargs.get(
                            "collector_id",
                            f"{entity_type}_{entity_id}_{log_service}",
                        ),
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[error_msg],
                        operation_name="request_failure",
                        additional_context=request_failure_context,
                    )

            if type(response) is not dict:
                stop_reason = (
                    PaginationStopReason.SNAPSHOT_INITIAL_RESPONSE_INVALID.value
                )
                response_metadata_text = self._bounded_response_metadata_text(
                    response,
                    initial_request_metadata,
                )
                reason = (
                    "Initial paginated Redfish response was not a collection "
                    f"object; stop reason was {stop_reason}."
                )
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    f"{reason} Response metadata={response_metadata_text}",
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    dut_id=dut_id,
                    collector_id=resolved_collector_id
                    or f"{entity_type}_{entity_id}_{log_service}",
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[reason],
                    operation_name="initial_snapshot_validation",
                    additional_context={
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "log_service": log_service,
                        "pagination_consistency": pagination_consistency,
                        "snapshot_watermark_valid": False,
                        "snapshot_watermark_error": stop_reason,
                        "pagination_stop_reason": stop_reason,
                        "pagination_complete": False,
                        "page_count": 0,
                        "page_status_list": [],
                        "status": "error",
                        "reason": reason,
                    },
                )

            # Save the initial metadata response
            initial_metadata_file = await self._save_data_to_file_with_pattern(
                dut_id,
                response,
                f"{function_tag}_{log_service.lower()}_initial_metadata_{entity_id}.json",
                filename=kwargs.get("filename", ""),
                substitutions={"entity_id": entity_id},
                collector_id=kwargs.get("collector_id"),
                request_timing_operation_ids=self._request_timing_operation_id(
                    initial_request_metadata
                ),
            )

            if initial_metadata_file:
                collected_files.append(initial_metadata_file)
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Saved initial metadata for {entity_type} {entity_id} to: {initial_metadata_file}",
                    dut_id,
                )

            # Extract total entries count
            snapshot_watermark_field = None
            if "Members@odata.count" in response:
                snapshot_watermark_field = "Members@odata.count"
            elif "@odata.count" in response:
                snapshot_watermark_field = "@odata.count"
            raw_total_entries = (
                response.get(snapshot_watermark_field)
                if snapshot_watermark_field is not None
                else None
            )
            advertised_total_entries = self._bounded_nonnegative_integer(
                raw_total_entries
            )
            total_entries = advertised_total_entries
            initial_members = response.get("Members")
            initial_next_link = response.get(next_link_field)
            streaming_window_count_rebased = bool(
                streaming_time_filtered
                and collect_complete_snapshot
                and isinstance(initial_members, list)
                and initial_next_link in (None, "")
                and advertised_total_entries is not None
                and advertised_total_entries > len(initial_members)
                and len(initial_members) < max_members_per_page
            )
            if streaming_window_count_rebased:
                # Some BMCs apply the Created filter to Members but keep the
                # collection-wide count. A terminal, locally untruncated page
                # is the complete filtered window; retaining the unfiltered
                # count as the target would manufacture a pagination shortfall.
                # An advertised nextLink or a page at our local member ceiling
                # deliberately prevents rebasing so genuine truncation remains
                # fail closed.
                total_entries = len(initial_members)
            snapshot_end_offset = total_entries
            snapshot_watermark_error = None
            if initial_snapshot_consistency and snapshot_end_offset is None:
                snapshot_watermark_error = (
                    PaginationStopReason.SNAPSHOT_WATERMARK_MISSING.value
                    if snapshot_watermark_field is None
                    else PaginationStopReason.SNAPSHOT_WATERMARK_INVALID.value
                )

            await self._log_runtime(
                "ERROR" if snapshot_watermark_error else "INFO",
                "RedfishService",
                f"Initial {log_service} response for {entity_type} {entity_id}: "
                f"collection count "
                f"{'rejected' if snapshot_watermark_error else 'observed'}; "
                f"count_available={snapshot_end_offset is not None}",
                dut_id,
            )

            # Calculate collection parameters
            page_size = 100  # Standard page size
            start_skip = 0
            estimated_pages = None
            max_entries_to_collect = None

            if collection_level and skip_amount > 0 and total_entries is not None:
                # Calculate start_skip for collection level (like legacy code)
                start_skip = max(0, total_entries - skip_amount)
                entries_to_collect = total_entries - start_skip
                max_entries_to_collect = entries_to_collect
                estimated_pages = max(
                    1, (entries_to_collect + page_size - 1) // page_size
                )

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Level {collection_level} collection for {entity_type} {entity_id}: collecting {entries_to_collect} entries from skip={start_skip} (estimated {estimated_pages} pages)",
                    dut_id,
                )
            else:
                # Collect all available entries
                entries_to_collect = total_entries if total_entries else None
                if collect_complete_snapshot and snapshot_end_offset is not None:
                    max_entries_to_collect = max(0, snapshot_end_offset)
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Collecting all available entries for {entity_type} {entity_id}",
                    dut_id,
                )

            # Initialize collection variables
            # Keep a first-seen, deduplicated logical view. The request capture
            # retains the bounded raw response; an initial-snapshot primary page
            # is projected to the immutable positional watermark before it is
            # persisted or used for attachment discovery. Offset pagination
            # against a live log can otherwise include appended records or repeat
            # records as entries are inserted while collection is in progress.
            all_entries = []
            seen_entry_keys = set()
            raw_rows_collected = 0
            raw_rows_observed = 0
            duplicate_rows = 0
            snapshot_boundary_rows_discarded = 0
            snapshot_drift = False
            snapshot_growth_observed = False
            snapshot_regression_observed = False
            page_member_limit_truncated = False
            page_members_omitted_by_limit = 0
            snapshot_members_error = None
            snapshot_page_count_error = None
            pagination_continuity_error = None
            pagination_cursor_gap_count = 0
            pagination_cursor_gap_positions = 0
            pagination_cursor_gap_max_positions = 0
            pagination_cursor_gap_evidence: List[Dict[str, int]] = []
            attachment_entries_by_uri: Dict[str, Dict[str, Any]] = {}
            shared_attachment_budget = kwargs.get("_attachment_follow_budget")
            if not isinstance(shared_attachment_budget, dict):
                shared_attachment_budget = {"used": 0}
            try:
                shared_attachment_budget["used"] = max(
                    0,
                    min(
                        int(shared_attachment_budget.get("used", 0)),
                        self.MAX_FOLLOWED_ADDITIONAL_DATA_ATTACHMENTS,
                    ),
                )
            except (TypeError, ValueError):
                shared_attachment_budget["used"] = 0

            reserved_attachment_uris: set[str] = set()
            omitted_attachment_uris: set[str] = set()
            invalid_attachment_uri_seen = False
            attachment_limit_reported = False

            def validate_attachment_uri(raw_uri: Any) -> Optional[str]:
                """
                Validate a BMC-advertised attachment before task creation.

                After applying local validation, the function forwards
                ``raw_uri`` to ``validate_redfish_request_uri`` and preserves
                its return and exception contract. Every required invariant is
                checked before a successful value is returned; invalid input
                follows the function's explicit exception path.

                Args:
                    raw_uri: Validated remote resource identifier used for raw
                        URI.

                Returns:
                    The canonical attachment URI text, or ``None`` when the
                    requested value is unavailable.
                """

                nonlocal invalid_attachment_uri_seen
                try:
                    return validate_redfish_request_uri(
                        raw_uri,
                        context="AdditionalDataURI",
                    )
                except (RedfishTopologyProfileError, TypeError, ValueError):
                    if not invalid_attachment_uri_seen:
                        invalid_attachment_uri_seen = True
                        attachment_status_list.append(False)
                        attachment_error_messages.append(
                            "Invalid AdditionalDataURI was rejected before request "
                            "task creation"
                        )
                    return None

            def reserve_attachment_uris(uris: List[Any]) -> List[str]:
                """
                Reserve safe URIs from the collector-wide attachment budget.

                The implementation uses ``uris`` to reserve safe URIs from the
                collector-wide attachment budget.

                Args:
                    uris: Validated remote resource identifier used for URIs.

                Returns:
                    The validated ``selected_uris``.
                """

                nonlocal attachment_limit_reported
                selected_uris: List[str] = []
                for raw_uri in uris:
                    uri = validate_attachment_uri(raw_uri)
                    if uri is None:
                        continue
                    if (
                        uri in reserved_attachment_uris
                        or uri in omitted_attachment_uris
                        or uri in attachment_dispositions
                    ):
                        continue
                    if (
                        shared_attachment_budget["used"]
                        >= self.MAX_FOLLOWED_ADDITIONAL_DATA_ATTACHMENTS
                    ):
                        omitted_attachment_uris.add(uri)
                        if tracked_attachment_callback:
                            attachment_dispositions[uri] = {
                                "disposition": "omitted_safe_limit",
                            }
                        if not attachment_limit_reported:
                            attachment_limit_reported = True
                            attachment_status_list.append(False)
                            attachment_error_messages.append(
                                "AdditionalDataURI request fan-out exceeded the "
                                f"collector-wide safe limit of "
                                f"{self.MAX_FOLLOWED_ADDITIONAL_DATA_ATTACHMENTS}; "
                                "remaining attachments were omitted"
                            )
                        continue
                    shared_attachment_budget["used"] += 1
                    reserved_attachment_uris.add(uri)
                    selected_uris.append(uri)
                return selected_uris

            def record_attachment_entries(entries: List[Any]) -> None:
                """
                Retain one ordering representative for each attachment URI.

                The implementation uses ``entries`` to retain one ordering
                representative for each attachment URI.

                Args:
                    entries: Entries supplied as ``entries`` without
                        transferring container ownership.
                """

                if not tracked_attachment_callback:
                    return
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    raw_uri = entry.get("AdditionalDataURI")
                    if raw_uri in (None, ""):
                        continue
                    uri = validate_attachment_uri(raw_uri)
                    if uri is None:
                        continue
                    existing = attachment_entries_by_uri.get(uri)
                    if existing is None or (
                        self._additional_data_attachment_sort_key(uri, entry)
                        < self._additional_data_attachment_sort_key(uri, existing)
                    ):
                        attachment_entries_by_uri[uri] = entry

            def add_page_entries(entries: List[Any]) -> List[Any]:
                """
                Accumulate unique entries in first-seen order.

                The implementation uses ``entries`` to accumulate unique entries
                in first-seen order.

                Args:
                    entries: Entries supplied as ``entries`` without
                        transferring container ownership.

                Returns:
                    The validated ``unique_page_entries``.
                """
                nonlocal raw_rows_collected, duplicate_rows
                record_attachment_entries(entries)
                unique_page_entries: List[Any] = []
                for entry in entries:
                    raw_rows_collected += 1
                    entry_key = self._paginated_log_entry_key(entry)
                    if entry_key in seen_entry_keys:
                        duplicate_rows += 1
                        continue
                    seen_entry_keys.add(entry_key)
                    all_entries.append(entry)
                    unique_page_entries.append(entry)
                return unique_page_entries

            def prepare_page_artifact(
                page_response: Dict[str, Any],
            ) -> Tuple[
                Dict[str, Any],
                List[Any],
                int,
                int,
                bool,
                Optional[PaginationStopReason],
            ]:
                """
                Bound one persisted page to the declared initial snapshot.

                The request-capture path has already observed the unmodified
                transport response. Primary page artifacts, attachment
                discovery, and collection counters must only consume records
                inside the initial positional boundary.

                Args:
                    page_response: Mapping supplying fields for bound one
                        persisted page to the declared initial snapshot.

                Returns:
                    A tuple containing ``metadata mapping``, ``selected
                    entries``, ``integer count``, ``integer count``, ``status
                    flag``, and ``page contract stop reason`` in that order.
                """

                nonlocal raw_rows_observed
                nonlocal snapshot_boundary_rows_discarded
                nonlocal snapshot_drift
                nonlocal snapshot_growth_observed
                nonlocal snapshot_regression_observed
                nonlocal page_member_limit_truncated
                nonlocal page_members_omitted_by_limit

                page_contract_stop_reason = None
                if initial_snapshot_consistency:
                    if "Members" not in page_response:
                        page_contract_stop_reason = (
                            PaginationStopReason.SNAPSHOT_MEMBERS_MISSING
                        )
                    elif not isinstance(page_response.get("Members"), list):
                        page_contract_stop_reason = (
                            PaginationStopReason.SNAPSHOT_MEMBERS_INVALID
                        )
                    elif "Members@odata.count" not in page_response:
                        page_contract_stop_reason = (
                            PaginationStopReason.SNAPSHOT_PAGE_COUNT_MISSING
                        )
                    elif (
                        self._bounded_nonnegative_integer(
                            page_response.get("Members@odata.count")
                        )
                        is None
                    ):
                        page_contract_stop_reason = (
                            PaginationStopReason.SNAPSHOT_PAGE_COUNT_INVALID
                        )

                for count_field in ("Members@odata.count", "@odata.count"):
                    if count_field not in page_response:
                        continue
                    page_advertised_count = self._bounded_nonnegative_integer(
                        page_response.get(count_field)
                    )
                    if (
                        streaming_window_count_rebased
                        and page_advertised_count == advertised_total_entries
                    ):
                        continue
                    if (
                        page_advertised_count is None
                        or snapshot_end_offset is None
                        or page_advertised_count == snapshot_end_offset
                    ):
                        continue
                    snapshot_drift = True
                    if page_advertised_count > snapshot_end_offset:
                        snapshot_growth_observed = True
                    else:
                        snapshot_regression_observed = True

                raw_entries = page_response.get("Members")
                if not isinstance(raw_entries, list):
                    return (
                        page_response,
                        [],
                        0,
                        0,
                        False,
                        page_contract_stop_reason,
                    )

                bounded_page_entries, observed_entries, members_truncated = (
                    bound_redfish_collection_members(
                        raw_entries,
                        field_name=f"{log_service} paginated Members",
                        limit=max_members_per_page,
                    )
                )
                raw_rows_observed += observed_entries
                if members_truncated:
                    omitted_entries = observed_entries - len(bounded_page_entries)
                    page_member_limit_truncated = True
                    page_members_omitted_by_limit += omitted_entries
                    snapshot_drift = True
                    snapshot_growth_observed = True
                if (
                    not initial_snapshot_consistency
                    or snapshot_end_offset is None
                    or max_entries_to_collect is None
                ):
                    artifact_response = page_response
                    if members_truncated:
                        artifact_response = dict(page_response)
                        artifact_response["Members"] = bounded_page_entries
                    return (
                        artifact_response,
                        bounded_page_entries,
                        observed_entries,
                        observed_entries - len(bounded_page_entries),
                        False,
                        page_contract_stop_reason,
                    )

                remaining_rows = max(0, max_entries_to_collect - raw_rows_collected)
                bounded_entries = bounded_page_entries[:remaining_rows]
                discarded_entries = observed_entries - len(bounded_entries)
                snapshot_boundary_rows_discarded += discarded_entries
                if discarded_entries:
                    snapshot_drift = True
                    snapshot_growth_observed = True
                row_boundary_reached = observed_entries >= remaining_rows

                artifact_response = dict(page_response)
                artifact_response["Members"] = bounded_entries
                for count_field in ("Members@odata.count", "@odata.count"):
                    if (
                        self._bounded_nonnegative_integer(
                            page_response.get(count_field)
                        )
                        is not None
                    ):
                        artifact_response[count_field] = snapshot_end_offset

                next_link = page_response.get(next_link_field)
                if row_boundary_reached or next_link_reaches_snapshot_end(
                    next_link, snapshot_end_offset
                ):
                    artifact_response.pop(next_link_field, None)

                return (
                    artifact_response,
                    bounded_entries,
                    observed_entries,
                    discarded_entries,
                    row_boundary_reached,
                    page_contract_stop_reason,
                )

            additional_data = {}
            additional_data_request_timing_operation_ids: List[str] = []
            attachment_dispositions: Dict[str, Dict[str, Any]] = {}
            attachment_status_list: List[bool] = []
            attachment_error_messages: List[str] = []
            additional_data_metrics: Dict[str, Any] = {}
            generic_additional_data_attempts = 0
            page_files = []
            status_list = (
                []
            )  # Status per page - important for partial success determination

            async def collect_tracked_attachments(uris: List[str]) -> None:
                """
                Collect each not-yet-attempted URI exactly once.

                The implementation uses ``uris`` to collect each
                not-yet-attempted URI exactly once. Terminal status is emitted
                only after each not-yet-attempted URI exactly once and its owned
                cleanup have completed. Owned asynchronous work is awaited
                before return, so completion does not leave an unobserved task
                behind.

                Args:
                    uris: Validated remote resource identifier used for URIs.
                """

                pending_uris = reserve_attachment_uris(
                    list(
                        dict.fromkeys(
                            uri for uri in uris if uri not in attachment_dispositions
                        )
                    )
                )
                if not pending_uris:
                    return

                results = await self._concurrent_redfish_requests(
                    dut_id,
                    [
                        (
                            uri,
                            "get additional data from "
                            f"{self._diagnostic_uri_evidence(uri)}",
                        )
                        for uri in pending_uris
                    ],
                    max_concurrent=3,
                    get_raw_content=True,
                    raw_content_max_bytes=self._resolved_attachment_limit(dut_id),
                )
                for index, uri in enumerate(pending_uris):
                    result = results[index] if index < len(results) else None
                    success = bool(
                        isinstance(result, (list, tuple))
                        and len(result) >= 2
                        and result[0]
                    )
                    response = (
                        result[1]
                        if isinstance(result, (list, tuple)) and len(result) >= 2
                        else "No response returned"
                    )
                    request_timing_operation_id = (
                        self._request_timing_operation_id(result[2])
                        if isinstance(result, (list, tuple)) and len(result) >= 3
                        else None
                    )
                    attachment_status_list.append(success)
                    if success:
                        additional_data[uri] = response
                        if request_timing_operation_id:
                            additional_data_request_timing_operation_ids.append(
                                request_timing_operation_id
                            )
                        attachment_dispositions[uri] = {"disposition": "collected"}
                        continue

                    response_metadata_text = self._bounded_response_metadata_text(
                        response
                    )
                    error = (
                        "AdditionalDataURI download failed for "
                        f"{self._diagnostic_uri_evidence(uri)}; "
                        f"response metadata={response_metadata_text}"
                    )
                    attachment_error_messages.append(error)
                    attachment_dispositions[uri] = {
                        "disposition": "failed",
                        "response_summary": self._bounded_response_metadata_summary(
                            response
                        ),
                    }

            page_timings = []  # Track timing for each page
            page = 1
            max_pages = pagination_budget.get("max_pages")
            if max_pages is None:
                max_pages = self._get_optional_tool_config_int("max_pagination_pages")
            if max_pages is None:
                max_pages = DEFAULT_MAX_PAGINATION_PAGES
            pagination_started_at = time.monotonic()

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"=== STARTING SIMPLE PAGINATION FOR {entity_type} {entity_id} ===",
                dut_id,
            )
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Total entries: {total_entries}, Target skip: {start_skip}, Collection level: {collection_level}",
                dut_id,
            )

            # Pagination approach - use $skip if specified
            current_uri = base_uri

            if start_skip > 0:
                separator = "&" if "?" in base_uri else "?"
                current_uri = f"{base_uri}{separator}$skip={start_skip}"
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Starting pagination with skip={start_skip} for {entity_type} {entity_id}",
                    dut_id,
                )
            else:
                current_uri = base_uri
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Starting pagination from beginning for {entity_type} {entity_id}",
                    dut_id,
                )

            # Simple pagination loop
            page_count = 0
            page_retry_count = 0  # Track retries at pagination level
            max_page_retries = int(pagination_budget.get("max_retries_per_page", 2))
            max_duplicate_url_retries = self._get_tool_config_int(
                "max_duplicate_url_retries", 3
            )
            pagination_stop_reason = snapshot_watermark_error
            retry_delay = float(pagination_budget.get("page_retry_backoff_seconds", 2))
            if (
                runtime_budget is not None
                and runtime_budget.enforce_wall_timeout
                and runtime_budget.wall_timeout_seconds is not None
            ):
                pagination_deadline_seconds = runtime_budget.wall_timeout_seconds
            else:
                configured_deadline = pagination_budget.get("deadline_seconds")
                if (
                    isinstance(configured_deadline, (int, float))
                    and not isinstance(configured_deadline, bool)
                    and math.isfinite(float(configured_deadline))
                    and float(configured_deadline) > 0
                ):
                    pagination_deadline_seconds = float(configured_deadline)
                else:
                    per_page_projection = float(request_timeout) * float(
                        retry_count + 1
                    ) + retry_delay * float(max_page_retries)
                    pagination_deadline_seconds = max(
                        per_page_projection * float(max_pages),
                        float(request_timeout),
                    )
            pagination_deadline = pagination_started_at + pagination_deadline_seconds
            current_page_retry = 0  # Track retries for current page
            page_state = PaginationPageState(
                current_uri=None if snapshot_watermark_error else current_uri,
                current_offset=start_skip if initial_snapshot_consistency else None,
                stop_reason=(
                    PaginationStopReason(snapshot_watermark_error)
                    if snapshot_watermark_error
                    else None
                ),
            )
            pending_initial_page_response = (
                response
                if (initial_snapshot_consistency or streaming_window_count_rebased)
                and start_skip == 0
                and snapshot_watermark_error is None
                else None
            )
            pending_initial_page_metadata = initial_request_metadata
            pending_initial_page_duration = initial_request_duration

            def next_link_uri_is_valid(uri: Any, **_kwargs: Any) -> bool:
                """
                Return whether an advertised next link may be followed.

                The link must pass the host-bound response-URI policy and must
                still address the collection it was returned from. A page of a
                different resource is rejected rather than rewritten, so the
                walk stops with the caller's existing suspicious-next-link stop
                reason and the pages already collected are retained.

                Args:
                    uri: Validated remote resource identifier used for URI.
                    _kwargs: Additional named values forwarded without changing
                        their keys.

                Returns:
                    Whether the next link URI is valid operation succeeds.
                """
                if not validate_redfish_uri(
                    uri,
                    expected_host=self._get_connection_host(dut_id),
                ):
                    return False
                return redfish_uri_targets_collection(
                    self._response_uri_request_target(uri),
                    base_uri,
                )

            snapshot_continuity_stop_reasons = {
                PaginationStopReason.SNAPSHOT_OFFSET_GAP,
                PaginationStopReason.SNAPSHOT_OFFSET_NON_PROGRESS,
                PaginationStopReason.SNAPSHOT_OFFSET_OVERLAP,
                PaginationStopReason.SNAPSHOT_OFFSET_UNVERIFIABLE,
            }

            def record_snapshot_continuity_error(
                state: PaginationPageState,
                next_link: Any,
                observed_rows: int,
            ) -> None:
                """
                Retain bounded numeric evidence for one continuity stop.

                The implementation uses ``state``, ``next_link``, and
                ``observed_rows`` to retain bounded numeric evidence for one
                continuity stop.

                Args:
                    state: State object whose ``current_offset``,
                        ``stop_reason``, and ``value`` state is read while
                        performing retain bounded numeric evidence for one
                        continuity stop.
                    next_link: Next link consumed while the function attempts to
                        retain bounded numeric evidence for one continuity stop.
                    observed_rows: Numeric observed rows used while the
                        operation performs bounded accounting.
                """

                nonlocal pagination_continuity_error
                if state.stop_reason not in snapshot_continuity_stop_reasons:
                    return
                current_offset = state.current_offset
                expected_next_offset = (
                    current_offset + observed_rows
                    if type(current_offset) is int and current_offset >= 0
                    else None
                )
                pagination_continuity_error = {
                    "reason": state.stop_reason.value,
                    "current_offset": current_offset,
                    "observed_rows": observed_rows,
                    "expected_next_offset": expected_next_offset,
                    "observed_next_offset": pagination_skip_offset(next_link),
                }

            def record_sparse_cursor_gap(
                previous_state: PaginationPageState,
                advanced_state: PaginationPageState,
                next_link: Any,
                observed_rows: int,
            ) -> None:
                """
                Retain bounded evidence for one accepted sparse server cursor.

                Exact continuity remains the default. In catalog-reviewed
                monotonic mode, a valid server link may advance farther than
                the number of returned members. The function records only
                numeric evidence and never changes the cursor decision.

                Args:
                    previous_state: Pagination state before consuming the
                        response-advertised next link.
                    advanced_state: Pagination state after validating the next
                        link and applying the configured continuity policy.
                    next_link: Response-advertised URI evaluated by the
                        pagination state machine.
                    observed_rows: Number of members returned by the current
                        page before local snapshot-window trimming.
                """

                nonlocal pagination_cursor_gap_count
                nonlocal pagination_cursor_gap_positions
                nonlocal pagination_cursor_gap_max_positions

                if not allow_forward_offset_gaps:
                    return
                if advanced_state.stop_reason not in {
                    None,
                    PaginationStopReason.SNAPSHOT_BOUNDARY,
                }:
                    return
                if not next_link_uri_is_valid(next_link):
                    return
                current_offset = previous_state.current_offset
                next_offset = pagination_skip_offset(next_link)
                if (
                    type(current_offset) is not int
                    or current_offset < 0
                    or type(observed_rows) is not int
                    or observed_rows < 0
                    or type(next_offset) is not int
                ):
                    return
                expected_next_offset = current_offset + observed_rows
                if next_offset <= expected_next_offset:
                    return
                gap_positions = next_offset - expected_next_offset
                pagination_cursor_gap_count += 1
                pagination_cursor_gap_positions += gap_positions
                pagination_cursor_gap_max_positions = max(
                    pagination_cursor_gap_max_positions,
                    gap_positions,
                )
                if len(pagination_cursor_gap_evidence) < _DIAGNOSTIC_LOG_MAX_ITEMS:
                    pagination_cursor_gap_evidence.append(
                        {
                            "page": previous_state.page_count,
                            "current_offset": current_offset,
                            "observed_rows": observed_rows,
                            "expected_next_offset": expected_next_offset,
                            "observed_next_offset": next_offset,
                            "gap_positions": gap_positions,
                        }
                    )

            def record_snapshot_page_contract_error(
                stop_reason: Optional[PaginationStopReason],
                *,
                page_number: int,
                response_mode: PaginationNextLinkMode,
            ) -> None:
                """
                Retain bounded evidence for one malformed primary page.

                The implementation uses ``stop_reason``, ``page_number``, and
                ``response_mode`` to retain bounded evidence for one malformed
                primary page.

                Args:
                    stop_reason: Stop reason object whose ``value`` state is
                        read while performing retain bounded evidence for one
                        malformed primary page.
                    page_number: Numeric page number used while the operation
                        performs bounded accounting.
                    response_mode: Response mode object whose ``value`` state is
                        read while performing retain bounded evidence for one
                        malformed primary page.
                """

                nonlocal pagination_stop_reason
                nonlocal snapshot_members_error
                nonlocal snapshot_page_count_error
                member_stop_reasons = {
                    PaginationStopReason.SNAPSHOT_MEMBERS_INVALID,
                    PaginationStopReason.SNAPSHOT_MEMBERS_MISSING,
                }
                count_stop_reasons = {
                    PaginationStopReason.SNAPSHOT_PAGE_COUNT_INVALID,
                    PaginationStopReason.SNAPSHOT_PAGE_COUNT_MISSING,
                }
                if stop_reason not in member_stop_reasons | count_stop_reasons:
                    return
                pagination_stop_reason = stop_reason.value
                evidence = {
                    "page": page_number,
                    "reason": stop_reason.value,
                    "response_mode": response_mode.value,
                    "required_field": (
                        "Members"
                        if stop_reason in member_stop_reasons
                        else "Members@odata.count"
                    ),
                }
                if (
                    stop_reason in member_stop_reasons
                    and snapshot_members_error is None
                ):
                    snapshot_members_error = evidence
                elif (
                    stop_reason in count_stop_reasons
                    and snapshot_page_count_error is None
                ):
                    snapshot_page_count_error = evidence

            while True:
                if time.monotonic() >= pagination_deadline:
                    pagination_stop_reason = (
                        PaginationStopReason.DEADLINE_EXCEEDED.value
                    )
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        "Stopping pagination for "
                        f"{entity_type} {entity_id}: the configured "
                        f"{pagination_deadline_seconds:g}-second pagination "
                        "deadline was exhausted",
                        dut_id,
                    )
                    break
                page_state = begin_pagination_page(
                    page_state,
                    retrying_current_page=current_page_retry > 0,
                    max_pages=max_pages,
                )
                if not page_state.can_request:
                    if page_state.stop_reason is not None:
                        pagination_stop_reason = page_state.stop_reason.value
                    break
                current_uri = page_state.current_uri
                page_count = page_state.page_count
                page_start_time = time.time()
                if pending_initial_page_response is not None:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        "Using the initial snapshot response as page 1 for "
                        f"{entity_type} {entity_id}",
                        dut_id,
                    )
                    success = True
                    response = pending_initial_page_response
                    page_request_metadata = pending_initial_page_metadata
                    page_duration = pending_initial_page_duration
                    pending_initial_page_response = None
                else:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Fetching page {page_count} for {entity_type} {entity_id}: {current_uri}",
                        dut_id,
                    )

                    # Log the exact URI for manual reproduction
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"EXACT_URI_FOR_CURL: GET {current_uri}",
                        dut_id,
                    )

                    # Fetch the current page
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Making request: GET {current_uri} (retry_count={retry_count})",
                        dut_id,
                    )

                    success, response, page_request_metadata = (
                        await self.dispatch_request(
                            dut_id,
                            "GET",
                            current_uri,
                            error_context=(
                                f"fetch page {page_count} for {entity_type} {entity_id}"
                            ),
                            timeout=request_timeout,
                            bypass_cache=True,
                            retry_count=retry_count,
                        )
                    )

                    page_duration = time.time() - page_start_time
                page_response_summary = self._bounded_response_metadata_summary(
                    response,
                    page_request_metadata,
                )
                page_response_metadata_text = json.dumps(
                    page_response_summary,
                    sort_keys=True,
                    separators=(",", ":"),
                )

                # Log the response details
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Page {page_count} response: success={success}; "
                    f"metadata={page_response_metadata_text}",
                    dut_id,
                )

                if not success:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Failed to fetch page {page_count} for {entity_type} "
                        f"{entity_id}; response metadata={page_response_metadata_text}",
                        dut_id,
                    )

                    # Save the failed response for debugging purposes
                    failed_response_data = {
                        "error_type": "request_failed",
                        "success": success,
                        "response_summary": page_response_summary,
                        "page_count": page_count,
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "log_service": log_service,
                        "timestamp": time.time(),
                    }

                    if current_page_retry > 0:
                        failed_response_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_retry{current_page_retry}_failed.json"
                    else:
                        failed_response_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_failed.json"
                    failed_file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        failed_response_data,
                        failed_response_file,
                        filename=kwargs.get("filename", ""),
                        substitutions={"entity_id": entity_id},
                        collector_id=kwargs.get("collector_id"),
                    )

                    if failed_file_path:
                        collected_files.append(failed_file_path)
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Saved failed response for page {page_count} to: {failed_file_path}",
                            dut_id,
                        )

                    # Save detailed error information for debugging
                    error_details = {
                        "page_count": page_count,
                        "uri": current_uri,
                        "response_summary": page_response_summary,
                        "retry_count": page_retry_count,
                        "max_retries": max_page_retries,
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "log_service": log_service,
                        "timestamp": time.time(),
                    }

                    # Save error details to a specific error file
                    if current_page_retry > 0:
                        error_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_retry{current_page_retry}_error_details.json"
                    else:
                        error_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_error_details.json"
                    error_file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        error_details,
                        error_file,
                        filename=kwargs.get("filename", ""),
                        substitutions={"entity_id": entity_id},
                        collector_id=kwargs.get("collector_id"),
                    )

                    if error_file_path:
                        collected_files.append(error_file_path)
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Saved error details for page {page_count} to: {error_file_path}",
                            dut_id,
                        )

                    # Even if the request failed, preserve collection-shaped JSON.
                    # Initial-snapshot structural validation below remains fail closed.
                    if (
                        type(response) is str
                        and len(response) <= _DIAGNOSTIC_ARRAY_MAX_BYTES
                        and response.startswith("HTTP 502:")
                    ):
                        # Extract the actual response content after "HTTP 502: "
                        response_content = response[9:]  # Remove "HTTP 502: " prefix
                        try:
                            parsed_response = json.loads(response_content)
                            if isinstance(parsed_response, dict) and (
                                "Members" in parsed_response
                                or (
                                    initial_snapshot_consistency
                                    and "Members@odata.count" in parsed_response
                                )
                            ):
                                (
                                    artifact_response,
                                    entries,
                                    observed_entries_in_page,
                                    discarded_entries_in_page,
                                    row_boundary_reached,
                                    page_contract_stop_reason,
                                ) = prepare_page_artifact(parsed_response)
                                record_snapshot_page_contract_error(
                                    page_contract_stop_reason,
                                    page_number=page_count,
                                    response_mode=PaginationNextLinkMode.SALVAGED_502,
                                )
                                await self._log_runtime(
                                    "INFO",
                                    "RedfishService",
                                    f"Page {page_count}: Got 502 but response contains "
                                    "collection evidence with "
                                    f"{observed_entries_in_page} "
                                    "observed entries",
                                    dut_id,
                                )

                                # Save the collection-shaped response despite the 502.
                                output_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_502_error.json"
                                file_path = await self._save_data_to_file_with_pattern(
                                    dut_id,
                                    artifact_response,
                                    output_file,
                                    filename=kwargs.get("filename", ""),
                                    substitutions={"entity_id": entity_id},
                                    collector_id=kwargs.get("collector_id"),
                                    request_timing_operation_ids=self._request_timing_operation_id(
                                        page_request_metadata
                                    ),
                                )

                                if file_path:
                                    collected_files.append(file_path)
                                    page_files.append(file_path)
                                    await self._log_runtime(
                                        "INFO",
                                        "RedfishService",
                                        f"Saved page {page_count} (502 collection evidence) to: {file_path}",
                                        dut_id,
                                    )

                                    # Process the entries from this response
                                    if isinstance(entries, list):
                                        entries_in_page = len(entries)
                                        unique_page_entries = add_page_entries(entries)
                                        unique_entries_in_page = len(
                                            unique_page_entries
                                        )
                                        duplicate_entries_in_page = (
                                            entries_in_page - unique_entries_in_page
                                        )
                                        await self._log_runtime(
                                            "INFO",
                                            "RedfishService",
                                            f"Page {page_count} (502): observed "
                                            f"{observed_entries_in_page} raw entries, "
                                            f"retained {entries_in_page} for collection, "
                                            f"{unique_entries_in_page} unique "
                                            f"({duplicate_entries_in_page} duplicates; "
                                            f"{discarded_entries_in_page} beyond the "
                                            "snapshot boundary; "
                                            f"totals: {raw_rows_collected} raw, {len(all_entries)} unique)",
                                            dut_id,
                                        )

                                        status_list.append(
                                            True
                                        )  # Mark as successful since we got data
                                        page_timings.append(
                                            {
                                                "page": page_count,
                                                "entries": entries_in_page,
                                                "observed_entries": observed_entries_in_page,
                                                "snapshot_boundary_rows_discarded": discarded_entries_in_page,
                                                "unique_entries": unique_entries_in_page,
                                                "duplicate_entries": duplicate_entries_in_page,
                                                "duration": page_duration,
                                                "status": True,
                                                "file": file_path,
                                                "note": "502 collection evidence saved",
                                            }
                                        )

                                        if page_contract_stop_reason is not None:
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                "Stopping initial-snapshot pagination "
                                                f"for {entity_type} {entity_id}: "
                                                f"page {page_count} did not provide a "
                                                "valid required collection structure "
                                                f"({pagination_stop_reason})",
                                                dut_id,
                                            )
                                            break

                                        if (
                                            initial_snapshot_consistency
                                            and row_boundary_reached
                                        ):
                                            await self._log_runtime(
                                                "INFO",
                                                "RedfishService",
                                                f"Page {page_count} (502): reached "
                                                "the initial snapshot row boundary "
                                                f"at {snapshot_end_offset}",
                                                dut_id,
                                            )
                                            pagination_stop_reason = (
                                                PaginationStopReason.SNAPSHOT_BOUNDARY.value
                                            )
                                            break

                                        if (
                                            max_entries_to_collect is not None
                                            and len(all_entries)
                                            >= max_entries_to_collect
                                        ):
                                            await self._log_runtime(
                                                "INFO",
                                                "RedfishService",
                                                f"Reached collection level limit for {entity_type} {entity_id}: "
                                                f"collected {len(all_entries)} unique entries "
                                                f"(limit: {max_entries_to_collect} for {collection_level})",
                                                dut_id,
                                            )
                                            pagination_stop_reason = "target_reached"
                                            break

                                        # Check for next link
                                        next_uri = parsed_response.get(next_link_field)
                                        previous_page_state = page_state
                                        page_state = progress_pagination_next_link(
                                            page_state,
                                            next_uri,
                                            mode=PaginationNextLinkMode.SALVAGED_502,
                                            snapshot_end_offset=snapshot_end_offset,
                                            max_repeated_next_links=(
                                                max_duplicate_url_retries
                                            ),
                                            expected_host=None,
                                            uri_validator=next_link_uri_is_valid,
                                            enforce_snapshot_continuity=(
                                                initial_snapshot_consistency
                                            ),
                                            allow_forward_offset_gaps=(
                                                allow_forward_offset_gaps
                                            ),
                                            observed_rows=observed_entries_in_page,
                                        )
                                        record_sparse_cursor_gap(
                                            previous_page_state,
                                            page_state,
                                            next_uri,
                                            observed_entries_in_page,
                                        )
                                        current_uri = page_state.current_uri
                                        if page_state.stop_reason is not None:
                                            pagination_stop_reason = (
                                                page_state.stop_reason.value
                                            )

                                        if (
                                            page_state.stop_reason
                                            is PaginationStopReason.SNAPSHOT_BOUNDARY
                                        ):
                                            await self._log_runtime(
                                                "INFO",
                                                "RedfishService",
                                                f"Page {page_count} (502): stopping before nextLink at or beyond initial snapshot end ({snapshot_end_offset}): {next_uri}",
                                                dut_id,
                                            )
                                            break
                                        if (
                                            page_state.stop_reason
                                            is PaginationStopReason.REPEATED_NEXT_LINK
                                        ):
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                f"Stopping pagination for {entity_type} {entity_id}: duplicate nextLink repeated {page_state.repeated_next_link_count} times: {next_uri}",
                                                dut_id,
                                            )
                                            break
                                        if (
                                            page_state.stop_reason
                                            in snapshot_continuity_stop_reasons
                                        ):
                                            record_snapshot_continuity_error(
                                                page_state,
                                                next_uri,
                                                observed_entries_in_page,
                                            )
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                "Stopping initial-snapshot pagination "
                                                f"for {entity_type} {entity_id}: "
                                                f"{pagination_stop_reason}",
                                                dut_id,
                                            )
                                            break
                                        if (
                                            page_state.stop_reason
                                            is PaginationStopReason.SUSPICIOUS_NEXT_LINK
                                        ):
                                            await self._log_runtime(
                                                "WARNING",
                                                "RedfishService",
                                                f"Rejecting suspicious nextLink URI: {next_uri}",
                                                dut_id,
                                            )
                                        elif (
                                            page_state.stop_reason
                                            is PaginationStopReason.END_OF_COLLECTION
                                        ):
                                            await self._log_runtime(
                                                "INFO",
                                                "RedfishService",
                                                f"Page {page_count} (502): no next link, stopping pagination",
                                                dut_id,
                                            )
                                            break
                                        elif page_state.can_request:
                                            page_retry_count = 0
                                            current_page_retry = 0
                                            await self._log_runtime(
                                                "INFO",
                                                "RedfishService",
                                                f"Page {page_count} (502): continuing with next link: {current_uri}",
                                                dut_id,
                                            )
                                            continue
                                else:
                                    status_list.append(False)
                                    page_timings.append(
                                        {
                                            "page": page_count,
                                            "entries": 0,
                                            "duration": page_duration,
                                            "status": False,
                                            "error": "Failed to save page artifact",
                                        }
                                    )
                        except (json.JSONDecodeError, Exception) as e:
                            await self._log_runtime(
                                "ERROR",
                                "RedfishService",
                                f"Page {page_count}: Failed to parse 502 response as JSON: {e}",
                                dut_id,
                            )

                    # Handle failed request - simple retry with 5-second delay
                    if response != "retry" and page_retry_count < max_page_retries:
                        page_retry_count += 1
                        current_page_retry += 1

                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            f"Page {page_count}: Request failed with metadata "
                            f"{page_response_metadata_text}; retrying "
                            f"{page_retry_count}/{max_page_retries} - waiting "
                            f"{retry_delay}s",
                            dut_id,
                        )
                        await asyncio.sleep(retry_delay)

                        # Try the same page again
                        continue

                    # Check if this is a retry signal from DUT manager
                    if response == "retry":
                        page_retry_count += 1
                        current_page_retry += 1
                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            f"Page {page_count}: Received retry signal from DUT manager for {entity_type} {entity_id} - this indicates server error (HTTP 5xx) (retry {page_retry_count}/{max_page_retries})",
                            dut_id,
                        )

                        if page_retry_count <= max_page_retries:
                            # Simple retry with 2-second delay for retry signals
                            # This handles cases where the BMC is temporarily overloaded

                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Page {page_count}: Retry signal from DUT manager {page_retry_count}/{max_page_retries} - waiting {retry_delay}s",
                                dut_id,
                            )
                            await asyncio.sleep(retry_delay)

                            # Try the same page again
                            continue
                        else:
                            # Exhausted pagination-level retries - mark this page as failed and continue
                            status_list.append(False)
                            error_msg = f"HTTP 502 Bad Gateway - BMC server error (possibly pagination limit exceeded with skip={skip_amount}, exhausted {max_page_retries} retries)"

                            # Create error log file for failed pagination
                            error_log_path = await self._create_error_log_file(
                                dut_id=dut_id,
                                collector_id=kwargs.get("collector_id"),
                                error_message=error_msg,
                                context={
                                    "entity_type": entity_type,
                                    "entity_id": entity_id,
                                    "log_service": log_service,
                                    "page": page_count,
                                    "skip_amount": skip_amount,
                                    "operation": "pagination_retry_exhausted",
                                },
                            )

                            # Add error log file to output files
                            if error_log_path:
                                collected_files.append(error_log_path)

                            page_timings.append(
                                {
                                    "page": page_count,
                                    "entries": 0,  # No entries collected for failed page
                                    "duration": page_duration,
                                    "status": False,
                                    "error": error_msg,
                                }
                            )
                            await self._log_runtime(
                                "WARN",
                                "RedfishService",
                                f"Page {page_count}: Exhausted pagination-level retries for {entity_type} {entity_id} - continuing to next page",
                                dut_id,
                            )
                            # Continue to next page instead of breaking (following legacy code pattern)
                    else:
                        # Non-retry failure - mark as failed
                        status_list.append(False)
                        # Generic evidence is metadata-only; detailed body bytes
                        # remain solely in the canonical request capture.
                        if response == "retry":
                            error_msg = f"HTTP 502 Bad Gateway - BMC server error (possibly pagination limit exceeded with skip={skip_amount})"
                        else:
                            error_msg = (
                                "Pagination request failed; response metadata="
                                f"{page_response_metadata_text}"
                            )

                        # Create error log file for failed pagination
                        error_log_path = await self._create_error_log_file(
                            dut_id=dut_id,
                            collector_id=kwargs.get("collector_id"),
                            error_message=error_msg,
                            context={
                                "entity_type": entity_type,
                                "entity_id": entity_id,
                                "log_service": log_service,
                                "page": page_count,
                                "skip_amount": skip_amount,
                                "response_summary": page_response_summary,
                                "operation": "pagination_request_failed",
                            },
                        )

                        # Add error log file to output files
                        if error_log_path:
                            collected_files.append(error_log_path)

                        page_timings.append(
                            {
                                "page": page_count,
                                "entries": 0,  # No entries collected for failed page
                                "duration": page_duration,
                                "status": False,
                                "error": error_msg,
                            }
                        )

                        # Continue to next page if possible (only if we have a nextLink)
                        next_uri = (
                            response.get(next_link_field)
                            if response and isinstance(response, dict)
                            else None
                        )
                        previous_page_state = page_state
                        page_state = progress_pagination_next_link(
                            page_state,
                            next_uri,
                            mode=PaginationNextLinkMode.FAILED_RESPONSE,
                            snapshot_end_offset=snapshot_end_offset,
                            max_repeated_next_links=max_duplicate_url_retries,
                            expected_host=None,
                            uri_validator=next_link_uri_is_valid,
                            enforce_snapshot_continuity=(initial_snapshot_consistency),
                            allow_forward_offset_gaps=allow_forward_offset_gaps,
                            observed_rows=0,
                        )
                        record_sparse_cursor_gap(
                            previous_page_state,
                            page_state,
                            next_uri,
                            0,
                        )
                        current_uri = page_state.current_uri
                        if page_state.stop_reason is not None:
                            pagination_stop_reason = page_state.stop_reason.value

                        if (
                            page_state.stop_reason
                            is PaginationStopReason.REPEATED_NEXT_LINK
                        ):
                            await self._log_runtime(
                                "WARNING",
                                "RedfishService",
                                f"Stopping pagination for {entity_type} {entity_id}: duplicate nextLink repeated {page_state.repeated_next_link_count} times: {next_uri}",
                                dut_id,
                            )
                            break
                        if page_state.stop_reason in snapshot_continuity_stop_reasons:
                            record_snapshot_continuity_error(
                                page_state,
                                next_uri,
                                0,
                            )
                            await self._log_runtime(
                                "WARNING",
                                "RedfishService",
                                "Stopping initial-snapshot pagination after a "
                                f"failed request: {pagination_stop_reason}",
                                dut_id,
                            )
                            break
                        if (
                            page_state.stop_reason
                            is PaginationStopReason.SUSPICIOUS_NEXT_LINK
                        ):
                            await self._log_runtime(
                                "WARNING",
                                "RedfishService",
                                f"Rejecting suspicious nextLink URI: {next_uri}",
                                dut_id,
                            )
                            break
                        if page_state.can_request:
                            current_page_retry = 0  # Reset retry count for new page
                            continue
                        if (
                            page_state.stop_reason
                            is PaginationStopReason.REQUEST_FAILED
                        ):
                            # No nextLink available - stop pagination (following legacy code pattern)
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Page {page_count}: No nextLink available, stopping pagination for {entity_type} {entity_id}",
                                dut_id,
                            )
                            break

                # Get entries from this page
                entries = []  # Initialize entries to empty list by default

                if type(response) is not dict:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Page {page_count} response is not a dictionary; "
                        f"metadata={page_response_metadata_text}",
                        dut_id,
                    )
                    status_list.append(False)
                    # Provide body-independent error metadata.
                    if response == "retry":
                        error_msg = f"HTTP 502 Bad Gateway - BMC server error (possibly pagination limit exceeded with skip={skip_amount})"
                    else:
                        error_msg = (
                            "Unexpected pagination response format; response metadata="
                            f"{page_response_metadata_text}"
                        )

                    # Create error log file for failed pagination
                    error_log_path = await self._create_error_log_file(
                        dut_id=dut_id,
                        collector_id=kwargs.get("collector_id"),
                        error_message=error_msg,
                        context={
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "log_service": log_service,
                            "page": page_count,
                            "skip_amount": skip_amount,
                            "response_summary": page_response_summary,
                            "operation": "pagination_response_format_error",
                        },
                    )

                    # Add error log file to output files
                    if error_log_path:
                        collected_files.append(error_log_path)

                    page_timings.append(
                        {
                            "page": page_count,
                            "duration": page_duration,
                            "status": False,
                            "error": error_msg,
                        }
                    )

                    # Non-dict response (like "retry") - mark as failed and stop
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Page {page_count}: Non-dict response with metadata "
                        f"{page_response_metadata_text}; stopping pagination",
                        dut_id,
                    )
                    pagination_stop_reason = "invalid_response"
                    break

                (
                    artifact_response,
                    entries,
                    observed_entries_in_page,
                    discarded_entries_in_page,
                    row_boundary_reached,
                    page_contract_stop_reason,
                ) = prepare_page_artifact(response)
                record_snapshot_page_contract_error(
                    page_contract_stop_reason,
                    page_number=page_count,
                    response_mode=PaginationNextLinkMode.SUCCESS,
                )

                entries_in_page = len(entries)
                unique_page_entries = add_page_entries(entries)
                unique_entries_in_page = len(unique_page_entries)
                duplicate_entries_in_page = entries_in_page - unique_entries_in_page
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Page {page_count}: observed {observed_entries_in_page} raw "
                    f"entries, retained {entries_in_page} for collection, "
                    f"{unique_entries_in_page} unique "
                    f"({duplicate_entries_in_page} duplicates; "
                    f"{discarded_entries_in_page} beyond the snapshot boundary; "
                    f"totals: {raw_rows_collected} raw, {len(all_entries)} unique)",
                    dut_id,
                )

                # Save this page to file
                if current_page_retry > 0:
                    output_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}_retry{current_page_retry}.json"
                else:
                    output_file = f"{function_tag}_{log_service.lower()}_{entity_id}_page{page_count}.json"
                page_substitutions = {
                    **base_substitutions,
                    "page": page_count,
                    "total": "unknown",
                }
                file_path = await self._save_data_to_file_with_pattern(
                    dut_id,
                    artifact_response,
                    output_file,
                    filename=kwargs.get("filename", ""),
                    output_pattern=output_pattern or output_file,
                    substitutions=page_substitutions,
                    collector_id=resolved_collector_id,
                    request_timing_operation_ids=self._request_timing_operation_id(
                        page_request_metadata
                    ),
                )

                if file_path:
                    collected_files.append(file_path)
                    page_files.append(file_path)
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Saved page {page_count} to: {file_path}",
                        dut_id,
                    )

                page_saved = bool(file_path)
                status_list.append(page_saved)
                page_timings.append(
                    {
                        "page": page_count,
                        "entries": entries_in_page,
                        "observed_entries": observed_entries_in_page,
                        "snapshot_boundary_rows_discarded": discarded_entries_in_page,
                        "unique_entries": unique_entries_in_page,
                        "duplicate_entries": duplicate_entries_in_page,
                        "duration": page_duration,
                        "status": page_saved,
                        "file": file_path,
                        **(
                            {}
                            if page_saved
                            else {"error": "Failed to save page artifact"}
                        ),
                    }
                )

                # Reset retry counter on successful page
                page_retry_count = 0

                if page_contract_stop_reason is not None:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        "Stopping initial-snapshot pagination for "
                        f"{entity_type} {entity_id}: page {page_count} did not "
                        "provide a valid required collection structure "
                        f"({pagination_stop_reason})",
                        dut_id,
                    )
                    break

                # Process additional data if callback provided
                if additional_data_callback and unique_page_entries:
                    if tracked_attachment_callback:
                        # Preserve page-local request timing while tracking raw
                        # page entries so repeated URIs are fetched exactly once.
                        await collect_tracked_attachments(
                            [
                                entry.get("AdditionalDataURI")
                                for entry in entries
                                if isinstance(entry, dict)
                                and isinstance(entry.get("AdditionalDataURI"), str)
                                and entry.get("AdditionalDataURI").strip()
                            ]
                        )
                        additional_data_uris = []
                    else:
                        additional_data_uris = reserve_attachment_uris(
                            [
                                entry.get("AdditionalDataURI")
                                for entry in unique_page_entries
                                if isinstance(entry, dict)
                                and entry.get("AdditionalDataURI")
                            ]
                        )

                    # Collect all additional data URIs for this page
                    if additional_data_uris:
                        generic_additional_data_attempts += len(additional_data_uris)
                        # Make concurrent requests for additional data with limited concurrency
                        additional_requests = [
                            (
                                uri,
                                "get additional data from "
                                f"{self._diagnostic_uri_evidence(uri)}",
                            )
                            for uri in additional_data_uris
                        ]

                        # Limit concurrent requests to prevent BMC overload
                        additional_results = await self._concurrent_redfish_requests(
                            dut_id,
                            additional_requests,
                            max_concurrent=3,  # Reduced from DEFAULT_MAX_CONCURRENT_REQUESTS
                            get_raw_content=True,
                            raw_content_max_bytes=self._resolved_attachment_limit(
                                dut_id
                            ),
                        )

                        # Process every requested URI, including a missing result.
                        for i, additional_uri in enumerate(additional_data_uris):
                            result = (
                                additional_results[i]
                                if i < len(additional_results)
                                else None
                            )
                            additional_success = bool(
                                isinstance(result, (list, tuple))
                                and len(result) >= 2
                                and result[0]
                            )
                            additional_response = (
                                result[1]
                                if isinstance(result, (list, tuple))
                                and len(result) >= 2
                                else "No response returned"
                            )
                            attachment_status_list.append(additional_success)
                            if additional_success:
                                additional_data[additional_uri] = additional_response
                            else:
                                attachment_error_messages.append(
                                    "AdditionalDataURI download failed for "
                                    f"{self._diagnostic_uri_evidence(additional_uri)}: "
                                    f"{self._bounded_response_metadata_text(additional_response)}"
                                )

                if initial_snapshot_consistency and row_boundary_reached:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        "Reached the initial snapshot row boundary for "
                        f"{entity_type} {entity_id}: retained "
                        f"{raw_rows_collected}/{max_entries_to_collect} raw rows "
                        f"and {len(all_entries)} unique entries",
                        dut_id,
                    )
                    pagination_stop_reason = (
                        PaginationStopReason.SNAPSHOT_BOUNDARY.value
                    )
                    break

                # Check if we've reached the collection level limit
                if (
                    max_entries_to_collect is not None
                    and len(all_entries) >= max_entries_to_collect
                ):
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Reached collection level limit for {entity_type} {entity_id}: "
                        f"collected {len(all_entries)} unique entries "
                        f"(limit: {max_entries_to_collect} for {collection_level})",
                        dut_id,
                    )
                    pagination_stop_reason = "target_reached"
                    break

                # Get next page URI from response
                next_link = (
                    response.get(next_link_field)
                    if response and isinstance(response, dict)
                    else None
                )
                previous_page_state = page_state
                page_state = progress_pagination_next_link(
                    page_state,
                    next_link,
                    mode=PaginationNextLinkMode.SUCCESS,
                    snapshot_end_offset=snapshot_end_offset,
                    max_repeated_next_links=max_duplicate_url_retries,
                    expected_host=None,
                    uri_validator=next_link_uri_is_valid,
                    enforce_snapshot_continuity=initial_snapshot_consistency,
                    allow_forward_offset_gaps=allow_forward_offset_gaps,
                    observed_rows=observed_entries_in_page,
                )
                record_sparse_cursor_gap(
                    previous_page_state,
                    page_state,
                    next_link,
                    observed_entries_in_page,
                )
                current_uri = page_state.current_uri
                if page_state.stop_reason is not None:
                    pagination_stop_reason = page_state.stop_reason.value

                if page_state.stop_reason is PaginationStopReason.SNAPSHOT_BOUNDARY:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Stopping pagination for {entity_type} {entity_id} before nextLink at or beyond initial snapshot end ({snapshot_end_offset}): {next_link}",
                        dut_id,
                    )
                    break
                if page_state.stop_reason is PaginationStopReason.REPEATED_NEXT_LINK:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Stopping pagination for {entity_type} {entity_id}: duplicate nextLink repeated {page_state.repeated_next_link_count} times: {next_link}",
                        dut_id,
                    )
                    break
                if page_state.stop_reason in snapshot_continuity_stop_reasons:
                    record_snapshot_continuity_error(
                        page_state,
                        next_link,
                        observed_entries_in_page,
                    )
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        "Stopping initial-snapshot pagination for "
                        f"{entity_type} {entity_id}: {pagination_stop_reason}",
                        dut_id,
                    )
                    break
                if page_state.stop_reason is PaginationStopReason.SUSPICIOUS_NEXT_LINK:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Rejecting suspicious nextLink URI: {next_link}",
                        dut_id,
                    )
                    break
                if page_state.can_request:
                    current_page_retry = 0
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Next page URI: {current_uri}",
                        dut_id,
                    )
                elif page_state.stop_reason is PaginationStopReason.END_OF_COLLECTION:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"No more pages available for {entity_type} {entity_id}",
                        dut_id,
                    )
                    break

                # Add delay between pages to prevent BMC overload
                # Use moderate delays for BMC rate limiting - reduced for faster execution
                page_delay = 1  # 1 second between pages (reduced from 3)
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Waiting {page_delay}s before next page to respect BMC rate limits",
                    dut_id,
                )
                await asyncio.sleep(page_delay)

            if tracked_attachment_callback:
                ordered_attachments = sorted(
                    attachment_entries_by_uri.items(),
                    key=lambda item: self._additional_data_attachment_sort_key(
                        item[0], item[1]
                    ),
                )
                advertised_uris = [uri for uri, _ in ordered_attachments]

                # This collects only any URI not already handled page-locally,
                # for example an attachment found in a salvaged 502 page.
                await collect_tracked_attachments(advertised_uris)

                discovered_attachments = len(ordered_attachments)
                collected_attachments = sum(
                    disposition.get("disposition") == "collected"
                    for disposition in attachment_dispositions.values()
                )
                failed_attachments = sum(
                    disposition.get("disposition") == "failed"
                    for disposition in attachment_dispositions.values()
                )
                omitted_attachments = sum(
                    disposition.get("disposition") == "omitted_safe_limit"
                    for disposition in attachment_dispositions.values()
                )
                attempted_attachments = collected_attachments + failed_attachments
                discovered_reconciled = discovered_attachments == attempted_attachments
                attempted_reconciled = (
                    attempted_attachments == collected_attachments + failed_attachments
                )

                manifest_entries = []
                for uri, entry in ordered_attachments:
                    disposition = attachment_dispositions.get(
                        uri, {"disposition": "failed", "error": "not attempted"}
                    )
                    manifest_entry = {
                        "uri": self._diagnostic_uri_evidence(uri),
                        "created": (
                            entry.get("Created")
                            if isinstance(entry.get("Created"), str)
                            else None
                        ),
                        **disposition,
                    }
                    manifest_entries.append(manifest_entry)

                attachment_manifest = {
                    "schema_version": 1,
                    "collector_id": resolved_collector_id,
                    "entity_type": entity_type,
                    "entity_id": entity_id,
                    "log_service": log_service,
                    "policy": {
                        "mode": "all_advertised",
                        # Publish the cap even when the current response stays
                        # below it. Consumers can then distinguish a bounded
                        # witness from an implementation with no request-
                        # amplification policy at all.
                        "safe_request_limit": (
                            self.MAX_FOLLOWED_ADDITIONAL_DATA_ATTACHMENTS
                        ),
                    },
                    "counts": {
                        "discovered": discovered_attachments,
                        "attempted": attempted_attachments,
                        "collected": collected_attachments,
                        "failed": failed_attachments,
                        **(
                            {"omitted": omitted_attachments}
                            if omitted_attachments
                            else {}
                        ),
                    },
                    "reconciliation": {
                        "discovered_equals_attempted": discovered_reconciled,
                        "attempted_equals_collected_plus_failed": (
                            attempted_reconciled
                        ),
                    },
                    "attachments": manifest_entries,
                }

                additional_data_pattern = kwargs.get("additional_data_pattern", "")
                if isinstance(
                    additional_data_pattern, str
                ) and additional_data_pattern.endswith(".json"):
                    manifest_pattern = f"{additional_data_pattern[:-5]}_manifest.json"
                else:
                    manifest_pattern = (
                        f"{function_tag}_{entity_type}_{entity_id}_"
                        "additional_data_manifest.json"
                    )
                manifest_filename = self.substitute_output_pattern_variables(
                    manifest_pattern,
                    base_substitutions,
                    (
                        f"{function_tag}_{entity_type}_{entity_id}_"
                        "additional_data_manifest.json"
                    ),
                )
                manifest_file = await self._save_data_to_file_with_pattern(
                    dut_id,
                    attachment_manifest,
                    manifest_filename,
                    output_pattern=manifest_pattern,
                    substitutions=base_substitutions,
                    collector_id=resolved_collector_id,
                )
                if manifest_file:
                    collected_files.append(manifest_file)
                else:
                    attachment_status_list.append(False)
                    attachment_error_messages.append(
                        "Failed to persist AdditionalDataURI disposition "
                        f"manifest for {entity_type} {entity_id}"
                    )

                additional_data_metrics = {
                    "additional_data_attachment_policy": "all_advertised",
                    "additional_data_attachments_discovered": (discovered_attachments),
                    "additional_data_attachments_attempted": (attempted_attachments),
                    "additional_data_attachments_collected": (collected_attachments),
                    "additional_data_attachments_failed": failed_attachments,
                    # Stable summary aliases used by the generic pagination
                    # integrity contract.
                    "additional_data_attempts": attempted_attachments,
                    "additional_data_failures": failed_attachments,
                    "additional_data_attachments_omitted_by_policy": (
                        omitted_attachments
                    ),
                    "additional_data_attachment_reconciliation": {
                        "discovered_equals_attempted": discovered_reconciled,
                        "attempted_equals_collected_plus_failed": (
                            attempted_reconciled
                        ),
                    },
                    "additional_data_attachment_manifest": manifest_file,
                }
            elif generic_additional_data_attempts:
                additional_data_metrics = {
                    "additional_data_attempts": generic_additional_data_attempts,
                    "additional_data_failures": sum(
                        not status for status in attachment_status_list
                    ),
                    "additional_data_attachments_omitted_by_policy": len(
                        omitted_attachment_uris
                    ),
                }

            # Persist the raw attachment aggregate exactly once while it is
            # local. Build the bounded metadata-only evidence before consuming
            # the one-shot owners, then clear the raw mapping before the
            # standardized result recursively freezes its context.
            additional_data_artifact = None
            additional_data_owned_by_worker = bool(
                additional_data_callback and additional_data
            )
            if additional_data_owned_by_worker:
                additional_data_pattern = kwargs.get("additional_data_pattern", "")
                if additional_data_pattern:
                    additional_filename = self.substitute_output_pattern_variables(
                        additional_data_pattern,
                        base_substitutions,
                        (
                            f"{function_tag}_{entity_type}_{entity_id}_"
                            "additional_data.json"
                        ),
                    )
                else:
                    additional_filename = (
                        f"{function_tag}_{entity_type}_{entity_id}_"
                        "additional_data.json"
                    )
                additional_data_artifact = await self._save_data_to_file_with_pattern(
                    dut_id,
                    additional_data,
                    additional_filename,
                    additional_data_pattern=additional_data_pattern,
                    substitutions=base_substitutions,
                    collector_id=resolved_collector_id,
                    request_timing_operation_ids=(
                        additional_data_request_timing_operation_ids
                    ),
                )
                additional_data = {}
                if additional_data_artifact:
                    collected_files.append(additional_data_artifact)
                else:
                    attachment_status_list.append(False)
                    attachment_error_messages.append(
                        "Failed to persist AdditionalDataURI aggregate for "
                        f"{entity_type} {entity_id}"
                    )

            unique_rows_collected = len(all_entries)
            if (
                pagination_stop_reason is None
                and max_pages is not None
                and page_count >= max_pages
            ):
                pagination_stop_reason = "max_pages"
            if page_member_limit_truncated and pagination_stop_reason in {
                None,
                PaginationStopReason.END_OF_COLLECTION.value,
                PaginationStopReason.SNAPSHOT_BOUNDARY.value,
                "target_reached",
            }:
                pagination_stop_reason = "page_member_limit"
            if (
                collect_complete_snapshot
                and duplicate_rows > 0
                and pagination_stop_reason
                in {
                    None,
                    PaginationStopReason.END_OF_COLLECTION.value,
                    PaginationStopReason.SNAPSHOT_BOUNDARY.value,
                    "target_reached",
                }
            ):
                pagination_stop_reason = "duplicate_entries"

            requested_target_entries = (
                snapshot_end_offset
                if collect_complete_snapshot
                else (skip_amount if skip_amount > 0 else None)
            )
            target_max_entries = max_entries_to_collect
            entries_omitted_by_policy = start_skip
            entries_not_collected = (
                max(0, snapshot_end_offset - unique_rows_collected)
                if snapshot_end_offset is not None
                else None
            )
            target_was_available_initially = bool(
                target_max_entries is not None
                and (
                    collect_complete_snapshot
                    or (
                        requested_target_entries is not None
                        and total_entries is not None
                        and total_entries >= requested_target_entries
                    )
                )
            )
            policy_limited_collection = entries_omitted_by_policy > 0
            requested_cursor_scope_incomplete = bool(
                any(not status for status in status_list)
                or pagination_stop_reason
                in {
                    "deadline_exceeded",
                    "duplicate_entries",
                    "invalid_response",
                    "max_pages",
                    "page_member_limit",
                    "repeated_next_link",
                    "request_failed",
                    "snapshot_initial_response_invalid",
                    "snapshot_offset_gap",
                    "snapshot_offset_non_progress",
                    "snapshot_offset_overlap",
                    "snapshot_offset_unverifiable",
                    "snapshot_members_invalid",
                    "snapshot_members_missing",
                    "snapshot_page_count_invalid",
                    "snapshot_page_count_missing",
                    "snapshot_watermark_invalid",
                    "snapshot_watermark_missing",
                    "suspicious_next_link",
                }
            )
            expected_entries = (
                target_max_entries
                if target_max_entries is not None
                else snapshot_end_offset
            )
            pagination_shortfall = bool(
                expected_entries is not None
                and unique_rows_collected < expected_entries
            )
            requested_cursor_scope_complete = bool(
                not requested_cursor_scope_incomplete
                and pagination_stop_reason
                in {
                    PaginationStopReason.END_OF_COLLECTION.value,
                    PaginationStopReason.SNAPSHOT_BOUNDARY.value,
                    "target_reached",
                }
            )
            sparse_cursor_scope_complete = bool(
                allow_forward_offset_gaps
                and pagination_cursor_gap_count > 0
                and requested_cursor_scope_complete
            )
            requested_entry_scope_incomplete = bool(
                target_was_available_initially
                and target_max_entries is not None
                and unique_rows_collected < target_max_entries
            )
            hard_requested_scope_failure = bool(
                requested_cursor_scope_incomplete
                or (
                    requested_entry_scope_incomplete
                    and not sparse_cursor_scope_complete
                )
            )
            pagination_incomplete = bool(
                policy_limited_collection or hard_requested_scope_failure
            )
            requested_scope_complete = bool(
                not requested_cursor_scope_incomplete
                and not requested_entry_scope_incomplete
                and pagination_cursor_gap_count == 0
                and not (initial_snapshot_consistency and duplicate_rows > 0)
            )
            full_snapshot_incomplete = bool(
                pagination_incomplete
                or pagination_shortfall
                or duplicate_rows > 0
                or pagination_cursor_gap_count > 0
            )
            # A live count change cannot prove membership stability: Redfish
            # provides no snapshot token or ordering guarantee here. Even when
            # the projected cardinality reaches the initial target, newest-first
            # insertion can substitute a new row for an original one. Preserve
            # bounded artifacts, but fail the snapshot closed instead of claiming
            # that count equality reconciled its contents.
            snapshot_drift_reconciled = False
            unreconciled_snapshot_drift = snapshot_drift

            # Print timing summary table for this entity
            if page_timings:
                total_time = sum(page.get("duration", 0) for page in page_timings)
                total_entries_from_pages = sum(
                    page.get("entries", 0) for page in page_timings
                )
                avg_time_per_page = total_time / len(page_timings)
                avg_time_per_entry = (
                    total_time / total_entries_from_pages
                    if total_entries_from_pages > 0
                    else 0
                )

                summary_lines = []
                summary_lines.append("=" * 80)
                summary_lines.append(
                    f"TIMING SUMMARY FOR {entity_type.upper()} {entity_id}"
                )
                summary_lines.append("=" * 80)
                summary_lines.append(f"Log service: {log_service}")
                summary_lines.append(f"Collection level: {collection_level}")
                summary_lines.append(f"Skip amount: {skip_amount}")
                summary_lines.append(f"Start skip position: {start_skip}")
                summary_lines.append(f"Total entries available: {total_entries}")
                summary_lines.append(f"Total pages: {len(page_timings)}")
                summary_lines.append(f"Target max entries: {target_max_entries}")
                summary_lines.append(f"Raw rows observed: {raw_rows_observed}")
                summary_lines.append(f"Raw rows collected: {raw_rows_collected}")
                summary_lines.append(
                    "Rows discarded at initial snapshot boundary: "
                    f"{snapshot_boundary_rows_discarded}"
                )
                summary_lines.append(f"Unique rows collected: {unique_rows_collected}")
                summary_lines.append(f"Duplicate rows: {duplicate_rows}")
                summary_lines.append(
                    f"Entries omitted by explicit policy: {entries_omitted_by_policy}"
                )
                summary_lines.append(
                    f"Initial snapshot entries not collected: {entries_not_collected}"
                )
                summary_lines.append(
                    f"Pagination complete: {not pagination_incomplete}"
                )
                summary_lines.append(f"Total time: {total_time:.2f}s")
                summary_lines.append(f"Average time per page: {avg_time_per_page:.2f}s")
                summary_lines.append(
                    f"Average time per entry: {avg_time_per_entry:.4f}s"
                )
                summary_lines.append("")

                # Print detailed table
                summary_lines.append(
                    f"{'Page':<6} {'Entries':<8} {'Duration':<10} {'Status':<8} {'File'}"
                )
                summary_lines.append(
                    f"{'-' * 6} {'-' * 8} {'-' * 10} {'-' * 8} {'-' * 50}"
                )
                for page in page_timings:
                    status_str = "SUCCESS" if page.get("status", False) else "FAILED"
                    entries_str = str(page.get("entries", 0))
                    duration_str = f"{page.get('duration', 0):.2f}"
                    file_str = (
                        os.path.basename(page.get("file", ""))
                        if page.get("file")
                        else "N/A"
                    )
                    summary_lines.append(
                        f"{page['page']:<6} {entries_str:<8} {duration_str:<10} {status_str:<8} {file_str}"
                    )
                summary_lines.append("=" * 80)

                # Log the timing summary
                for line in summary_lines:
                    await self._log_runtime("INFO", "RedfishService", line, dut_id)

            # Post-processing: Fix filenames with actual total pages
            actual_total_pages = len(page_files)
            if actual_total_pages > 0:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Collected {actual_total_pages} pages for {entity_type} {entity_id}. Updating filenames to reflect actual total.",
                    dut_id,
                )

                # Rename files to use actual total
                renamed_files = []
                page_file_set = set(page_files)
                for file_path in collected_files:
                    try:
                        old_path = file_path
                        if old_path not in page_file_set:
                            renamed_files.append(file_path)
                            continue

                        # Replace "unknown" or any existing total with actual total
                        new_path = re.sub(
                            r"_page(\d+)_of_[^/]+\.json$",
                            f"_page\\1_of_{actual_total_pages}.json",
                            str(old_path),
                        )
                        if new_path == str(old_path):
                            new_path = re.sub(
                                r"_page(\d+)\.json$",
                                f"_page\\1_of_{actual_total_pages}.json",
                                str(old_path),
                            )

                        if self.logger and resolved_collector_id:
                            new_basename = self.logger._apply_stream_window_to_filename(
                                resolved_collector_id,
                                os.path.basename(new_path),
                            )
                            new_path = os.path.join(
                                os.path.dirname(new_path), new_basename
                            )

                        if os.path.exists(old_path) and old_path != new_path:
                            os.rename(old_path, new_path)
                            renamed_files.append(new_path)
                            if self.timing_manager:
                                try:
                                    self.timing_manager.remap_current_collector_artifact_path(
                                        old_path, new_path
                                    )
                                except Exception as timing_error:
                                    await self._log_runtime(
                                        "WARNING",
                                        "RedfishService",
                                        f"Failed to remap timing artifact after renaming {os.path.basename(old_path)}: {timing_error}",
                                        dut_id,
                                    )
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Renamed {os.path.basename(old_path)} to {os.path.basename(new_path)}",
                                dut_id,
                            )
                        else:
                            renamed_files.append(file_path)
                    except Exception as e:
                        await self._log_runtime(
                            "ERROR",
                            "RedfishService",
                            f"Failed to rename file {file_path}: {str(e)}",
                            dut_id,
                        )
                        renamed_files.append(file_path)

                collected_files = renamed_files

            # Final summary
            total_collected = unique_rows_collected
            successful_files = len([f for f in collected_files if f])

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Completed paginated log collection for {entity_type} {entity_id}: "
                f"{raw_rows_observed} raw rows observed, {raw_rows_collected} "
                f"retained, {snapshot_boundary_rows_discarded} discarded at the "
                f"initial snapshot boundary, {unique_rows_collected} unique rows, "
                f"{duplicate_rows} duplicates, {successful_files} files saved, "
                f"{page_count} pages processed",
                dut_id,
            )

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"FINAL collected_files list for {entity_type} {entity_id}: {len(collected_files)} files: {collected_files}",
                dut_id,
            )

            # Use the base collector's standardized result function
            integrity_failure = bool(
                hard_requested_scope_failure
                or (
                    (
                        pagination_shortfall
                        or (initial_snapshot_consistency and duplicate_rows > 0)
                    )
                    and not sparse_cursor_scope_complete
                )
            )
            snapshot_consistency_warning = None
            if unreconciled_snapshot_drift:
                snapshot_consistency_warning = (
                    "Paginated log snapshot changed during collection; all "
                    f"{unique_rows_collected}/{expected_entries} expected records "
                    "were retained."
                    if not integrity_failure
                    else (
                        "Paginated log snapshot changed while collection coverage "
                        "was incomplete."
                    )
                )
            operation_status_list = [*status_list, *attachment_status_list]
            if snapshot_watermark_error and initial_metadata_file:
                # The initial request and bounded metadata artifact succeeded;
                # the separate watermark-validation operation failed below.
                operation_status_list.append(True)
            if integrity_failure and all(operation_status_list):
                # Count logical snapshot/coverage verification as an explicit
                # failed operation so otherwise-successful saved pages cannot
                # mask data loss. An existing failed request or persistence
                # operation already records that failure and must not be counted
                # twice.
                operation_status_list.append(False)
            successful_operations = len(
                [status for status in operation_status_list if status]
            )
            total_operations = len(operation_status_list)
            error_messages = list(attachment_error_messages)
            pagination_partial_reason = None
            policy_scope_note = (
                (
                    f"Applied the explicit {collection_level} entry window; "
                    f"{entries_omitted_by_policy} older records were outside "
                    "the requested collection scope."
                    if pagination_shortfall
                    else (
                        f"Completed the explicit {collection_level} entry window "
                        f"with {unique_rows_collected} unique records; "
                        f"{entries_omitted_by_policy} older records were outside "
                        "the requested collection scope."
                    )
                )
                if policy_limited_collection
                else None
            )
            sparse_cursor_degraded_reason = None

            # Collect specific error messages from failed pages
            for i, status in enumerate(status_list):
                if not status and i < len(page_timings):
                    page_info = page_timings[i]
                    if "error" in page_info:
                        error_msg = f"Page {page_info.get('page', i + 1)} failed: {page_info['error']}"
                        error_messages.append(error_msg)
                    else:
                        error_msg = (
                            f"Page {page_info.get('page', i + 1)} failed: Unknown error"
                        )
                        error_messages.append(error_msg)

            if integrity_failure:
                if snapshot_watermark_error:
                    watermark_description = (
                        "was absent"
                        if snapshot_watermark_error
                        == PaginationStopReason.SNAPSHOT_WATERMARK_MISSING.value
                        else "was not a bounded non-negative integer"
                    )
                    pagination_partial_reason = (
                        "Initial-snapshot pagination did not start because the "
                        "initial Redfish collection count "
                        f"{watermark_description}; stop reason was "
                        f"{snapshot_watermark_error}."
                    )
                else:
                    target_description = (
                        str(target_max_entries)
                        if target_max_entries is not None
                        else "an unknown target"
                    )
                    pagination_partial_reason = (
                        "Paginated log collection was incomplete: collected "
                        f"{unique_rows_collected}/{target_description} unique records "
                        f"from {raw_rows_collected} raw rows across {page_count} pages "
                        f"({duplicate_rows} duplicates); initial collection count was "
                        f"{total_entries}; stop reason was "
                        f"{pagination_stop_reason or 'target_not_reached'}."
                    )
                error_messages.append(pagination_partial_reason)
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    pagination_partial_reason,
                    dut_id,
                )
            elif sparse_cursor_scope_complete:
                sparse_cursor_degraded_reason = (
                    "Firmware returned sparse monotonic pagination cursors; "
                    f"followed the complete requested cursor window and collected "
                    f"{unique_rows_collected}/{expected_entries} expected unique "
                    f"records across {page_count} pages. The firmware advanced "
                    f"past {pagination_cursor_gap_positions} positions in "
                    f"{pagination_cursor_gap_count} response(s)."
                )
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    sparse_cursor_degraded_reason,
                    dut_id,
                )
                if policy_scope_note:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        policy_scope_note,
                        dut_id,
                    )
                if snapshot_consistency_warning:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        snapshot_consistency_warning,
                        dut_id,
                    )
            elif policy_limited_collection:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    policy_scope_note,
                    dut_id,
                )
                if snapshot_consistency_warning:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        snapshot_consistency_warning,
                        dut_id,
                    )
            elif snapshot_consistency_warning:
                pagination_partial_reason = snapshot_consistency_warning
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    pagination_partial_reason,
                    dut_id,
                )

            # If we have collected files but some pages failed, this should be considered partial success
            # rather than complete failure, as we did successfully collect some data
            if successful_files > 0 and successful_operations < total_operations:
                # We have some successful files but not all pages succeeded
                # This is partial success, not complete failure
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Partial success: collected {successful_files} files from {successful_operations}/{total_operations} operations for {entity_type} {entity_id}",
                    dut_id,
                )

            # Add detailed logging for status determination
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"PAGINATION_STATUS_DEBUG: {entity_type} {entity_id} - status_list={operation_status_list}, successful_operations={successful_operations}, total_operations={total_operations}, collected_files={len(collected_files)}",
                dut_id,
            )

            result_context = {
                "entity_type": entity_type,
                "entity_id": entity_id,
                "log_service": log_service,
                # Retain the legacy field while making its unique-row semantics
                # explicit through the accompanying counters.
                "total_entries_collected": total_collected,
                "raw_rows_observed": raw_rows_observed,
                "raw_rows_collected": raw_rows_collected,
                "snapshot_boundary_rows_discarded": (snapshot_boundary_rows_discarded),
                "unique_rows_collected": unique_rows_collected,
                "duplicate_rows": duplicate_rows,
                "initial_total_entries": total_entries,
                "advertised_total_entries": advertised_total_entries,
                "streaming_time_filtered": streaming_time_filtered,
                "streaming_window_count_rebased": streaming_window_count_rebased,
                "pagination_count_basis": (
                    "terminal_filtered_members"
                    if streaming_window_count_rebased
                    else "advertised_count"
                ),
                "requested_target_entries": requested_target_entries,
                "target_max_entries": target_max_entries,
                "entries_omitted_by_policy": entries_omitted_by_policy,
                "entries_not_collected": entries_not_collected,
                "collection_scope": (
                    "bounded_entry_window"
                    if policy_limited_collection
                    else "complete_initial_snapshot"
                ),
                "requested_scope_complete": requested_scope_complete,
                "requested_cursor_scope_complete": (requested_cursor_scope_complete),
                "requested_entry_target_complete": not pagination_shortfall,
                "initial_snapshot_complete": not full_snapshot_incomplete,
                "policy_scope_note": policy_scope_note,
                "max_pagination_pages": max_pages,
                "max_members_per_page": max_members_per_page,
                "page_members_omitted_by_limit": page_members_omitted_by_limit,
                "pagination_deadline_seconds": pagination_deadline_seconds,
                "pagination_consistency": pagination_consistency,
                "pagination_offset_continuity": pagination_offset_continuity,
                "pagination_sparse_cursor_detected": (pagination_cursor_gap_count > 0),
                "pagination_cursor_gap_count": pagination_cursor_gap_count,
                "pagination_cursor_gap_positions": (pagination_cursor_gap_positions),
                "pagination_cursor_gap_max_positions": (
                    pagination_cursor_gap_max_positions
                ),
                "pagination_cursor_gap_evidence": pagination_cursor_gap_evidence,
                "pagination_sparse_cursor_degraded_reason": (
                    sparse_cursor_degraded_reason
                ),
                "snapshot_boundary": (
                    "initial_odata_count"
                    if initial_snapshot_consistency and snapshot_end_offset is not None
                    else None
                ),
                "snapshot_watermark_field": snapshot_watermark_field,
                "snapshot_watermark_valid": snapshot_end_offset is not None,
                "snapshot_watermark_error": snapshot_watermark_error,
                "max_page_retries": max_page_retries,
                "page_retry_backoff_seconds": retry_delay,
                "request_timeout_seconds": request_timeout,
                "expected_entries": expected_entries,
                "observed_entry_count": unique_rows_collected,
                "pagination_shortfall": pagination_shortfall,
                "snapshot_drift": snapshot_drift,
                "snapshot_growth_observed": snapshot_growth_observed,
                "snapshot_regression_observed": snapshot_regression_observed,
                "snapshot_drift_reconciled": snapshot_drift_reconciled,
                "snapshot_drift_unreconciled": unreconciled_snapshot_drift,
                "snapshot_consistency_warning": snapshot_consistency_warning,
                "snapshot_members_error": snapshot_members_error,
                "snapshot_page_count_error": snapshot_page_count_error,
                "pagination_continuity_error": pagination_continuity_error,
                "page_count": page_count,
                "pagination_stop_reason": pagination_stop_reason,
                "pagination_complete": not full_snapshot_incomplete,
                "successful_files": successful_files,
                "additional_data_artifact": additional_data_artifact,
                "additional_data_owned_by_worker": additional_data_owned_by_worker,
                "status_list": operation_status_list,
                "page_status_list": status_list,
                "additional_data_attachment_request_limit": (
                    self.MAX_FOLLOWED_ADDITIONAL_DATA_ATTACHMENTS
                ),
                "additional_data_attachment_requests_reserved": len(
                    reserved_attachment_uris
                ),
                "additional_data_attachment_budget_used": (
                    shared_attachment_budget["used"]
                ),
                "additional_data_attachment_limit_exhausted": (
                    attachment_limit_reported
                ),
                "additional_data_attachment_invalid_uri_rejected": (
                    invalid_attachment_uri_seen
                ),
                **additional_data_metrics,
            }
            if integrity_failure and successful_operations > 0:
                result_context.update(
                    {
                        "status": "partial",
                        "reason": pagination_partial_reason,
                    }
                )
            elif sparse_cursor_degraded_reason:
                result_context.update(
                    {
                        "status": "degraded",
                        "reason": sparse_cursor_degraded_reason,
                    }
                )
            elif policy_scope_note:
                result_context.update(
                    {
                        "status": "success",
                        "reason": policy_scope_note,
                    }
                )

            result = await self._create_standardized_collector_result(
                dut_id=dut_id,
                collector_id=f"{entity_type}_{entity_id}_{log_service}",
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=collected_files,
                error_messages=error_messages,
                operation_name="pages",
                additional_context=result_context,
            )

            # Log the result from pagination function
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"PAGINATION_RESULT_DEBUG: {entity_type} {entity_id} - result={result}",
                dut_id,
            )

            return result

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in optimized paginated logs collection: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[
                    f"Exception in optimized paginated logs collection: {str(e)}"
                ],
                operation_name="paginated_logs_collection",
                additional_context={
                    "entity_type": entity_type,
                    "entity_id": entity_id,
                    "log_service": log_service,
                    "status": "error",
                    "reason": f"Exception in optimized paginated logs collection: {str(e)}",
                },
            )

    async def collect_component_integrity_data(
        self, dut_id: str, function_tag: str, **kwargs
    ) -> Dict[str, Any]:
        """
        Generic function for collecting data from ComponentIntegrity endpoints.

        This function can be used for various ComponentIntegrity operations
        including:

        - SPDM measurements.
        - Certificate collections.
        - Any other ComponentIntegrity-based data collection.

        All configuration should be provided via kwargs parameters.

        Required parameters:

        - collection_type: Type of collection ("spdm_measurements",
          "certificates", etc.).
        - member_key_config: Dict with baseboard-type-specific member keys.
        - {baseboard_type}: List of keys for that baseboard type (e.g.,
          {"NVSwitch": ["MGX"]}).
        - default_member_key: Member keys for baseboard types not in
          member_key_config.

        Optional parameters:

        - base_uri: ComponentIntegrity base URI (default: uses configured URI).
        - action_name: Action name for POST requests (e.g.,
          "#ComponentIntegrity.SPDMGetSignedMeasurements").
        - payload_template: Template for POST request payload (for
          measurements).
        - member_delay: Delay between member processing in seconds (default: 1).
        - request_delay: Delay between requests in seconds (default: 1).
        - output_pattern: File output pattern with {member_id} and other
          placeholders.
        - collection_params: Additional parameters for the specific collection
          type.
        - baseboard_manager: Baseboard manager instance for baseboard-aware
          filtering.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing component integrity data.
        """
        try:
            output_files = []
            collection_type = kwargs.get("collection_type", "spdm_measurements")
            successful_operations = 0
            total_operations = 0
            error_messages: List[str] = []

            try:
                member_key_config, default_member_key = (
                    self._normalize_component_integrity_member_key_config(
                        kwargs.get("member_key_config"),
                        kwargs.get("default_member_key"),
                    )
                )
            except ValueError as exc:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[
                        "Invalid ComponentIntegrity member-key catalog "
                        f"configuration: {exc}"
                    ],
                    operation_name=collection_type,
                    additional_context={"configuration_error": str(exc)},
                )

            # Get ComponentIntegrity information
            base_uri = kwargs.get("base_uri", "ComponentIntegrity")
            if base_uri.startswith("/"):
                # Full URI provided
                component_integrity_uri = base_uri
            else:
                # Use configured URI
                component_integrity_uri = self.get_configured_uri(dut_id, base_uri)
            success, response, _ = await self.dispatch_request(
                dut_id,
                "GET",
                component_integrity_uri,
                error_context="fetch ComponentIntegrity URIs",
            )

            if not success:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=["Failed to get ComponentIntegrity"],
                    operation_name=collection_type,
                    additional_context={},
                )

            raw_members = response.get("Members", [])
            omitted_member_count = 0
            try:
                members, source_member_count, members_truncated = (
                    bound_redfish_collection_members(
                        raw_members,
                        field_name="ComponentIntegrity Members",
                        limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                    )
                )
            except ValueError:
                members = []
                source_member_count = 0
                members_truncated = False
                error_messages.append(
                    "ComponentIntegrity returned an invalid Members list"
                )
            if members_truncated:
                omitted_member_count = source_member_count - len(members)
                error_messages.append(
                    f"ComponentIntegrity advertised {source_member_count} members; "
                    f"processing the first {self.MAX_FOLLOWED_COLLECTION_MEMBERS} "
                    "within the safe request-amplification limit"
                )

            if len(members) == 0:
                await self._log_runtime(
                    "WARN",
                    "RedfishService",
                    f"No members found under ComponentIntegrity. Skipping {collection_type}",
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1 if error_messages else 0,
                    output_files=[],
                    error_messages=(
                        error_messages or ["No ComponentIntegrity members found"]
                    ),
                    operation_name=collection_type,
                    additional_context={},
                )

            # Get baseboard-aware member key filtering
            # Use baseboard manager to determine applicable member keys
            baseboard_manager = kwargs.get("baseboard_manager")
            if baseboard_manager:
                # Get the baseboard for this DUT from DUT config
                dut_config = self.dut_manager.get_dut_config(dut_id)
                baseboard_name = dut_config.get("baseboard", "unknown")

                # Get baseboard type from BaseboardManager
                baseboard_type = baseboard_manager.get_baseboard_type(baseboard_name)
                if not baseboard_type:
                    baseboard_type = "unknown"

                # Generic logic: look up baseboard type in member_key_config, fallback to default
                if baseboard_type in member_key_config:
                    member_key = member_key_config[baseboard_type]
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Found member key for baseboard type {baseboard_type}: {member_key}",
                        dut_id,
                    )
                else:
                    # Use default for baseboard types not in config
                    member_key = default_member_key
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"No specific config for baseboard type {baseboard_type}, using default: {member_key}",
                        dut_id,
                    )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Using member key {member_key} for baseboard {baseboard_name} (type: {baseboard_type})",
                    dut_id,
                )
            else:
                member_key = default_member_key

            # Get configurable delays
            member_delay = kwargs.get("member_delay", 1)
            request_delay = kwargs.get("request_delay", 1)
            handler, expected_operations = (
                self._get_component_integrity_handler_and_expected_operations(
                    collection_type, kwargs
                )
            )
            total_operations += omitted_member_count * expected_operations

            for i, member in enumerate(members):
                # Add delay between member processing to prevent BMC overload
                if i > 0:
                    await asyncio.sleep(member_delay)

                member_uri = member.get("@odata.id", None)
                if not member_uri:
                    continue
                if not validate_redfish_uri(member_uri):
                    continue
                if not redfish_uri_is_collection_member(
                    member_uri, component_integrity_uri
                ):
                    error_messages.append(
                        "rejected advertised member outside collection "
                        f"{component_integrity_uri}"
                    )
                    continue

                # Platform-specific member key filtering
                if not any(key in member_uri for key in member_key):
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Skipping non-{','.join(member_key)} component integrity info for {member_uri}",
                        dut_id,
                    )
                    continue

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Collecting {collection_type} for {member_uri}",
                    dut_id,
                )
                total_operations += expected_operations

                # Get component integrity info
                success, component_response, _ = await self.dispatch_request(
                    dut_id,
                    "GET",
                    member_uri,
                    error_context=f"fetch component integrity info for {member_uri}",
                )

                if not success:
                    member_id = member_uri.split("/")[-1]
                    error_messages.append(
                        f"{member_id}: failed to fetch ComponentIntegrity resource"
                    )
                    continue

                member_id = member_uri.split("/")[-1]

                # Handle different collection types
                handler_result = await handler(
                    dut_id,
                    component_response,
                    member_uri,
                    member_id,
                    kwargs,
                    function_tag,
                    output_files,
                    request_delay,
                )
                successful_operations += handler_result["successful_operations"]
                error_messages.extend(handler_result.get("error_messages", []))

            return await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=output_files,
                error_messages=error_messages,
                operation_name=collection_type,
                additional_context={
                    "baseboard_name": (
                        baseboard_name if "baseboard_name" in locals() else "unknown"
                    ),
                    "member_key_used": member_key,
                    "members_processed": len(members),
                    "members_advertised": source_member_count,
                    "members_omitted_by_safe_limit": omitted_member_count,
                    "collections_completed": len(output_files),
                    "collection_type": collection_type,
                },
            )

        except Exception as e:
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[str(e)],
                operation_name=collection_type,
                additional_context={
                    "collector_name": "collect_component_integrity_data"
                },
            )

    @staticmethod
    def _normalize_component_integrity_member_key_config(
        member_key_config: Any,
        default_member_key: Any,
    ) -> Tuple[Dict[str, List[str]], List[str]]:
        """
        Validate and normalize catalog-owned ComponentIntegrity member keys.

        The implementation uses ``member_key_config`` and ``default_member_key``
        to validate and normalize catalog-owned ComponentIntegrity member keys.
        Every required invariant is checked before a successful value is
        returned; invalid input follows the function's explicit exception path.

        Args:
            member_key_config: Member key config governing and normalize
                catalog-owned ComponentIntegrity member keys.
            default_member_key: Stable default member key used for lookup and
                operator-facing diagnostics.

        Returns:
            A tuple containing ``normalized config`` and ``normalize keys`` in
            that order.

        Raises:
            ValueError: If the member_key_config is not a mapping; or the
                member_key_config keys are not non-empty strings.
        """

        def normalize_keys(value: Any, field_name: str) -> List[str]:
            """
            Normalize keys.

            The implementation uses ``value`` and ``field_name`` to normalize
            keys. The source value keeps its ownership while the normalized
            representation is returned separately. If the function cannot
            normalize keys, its exception reaches the caller instead of being
            converted into a successful result.

            Args:
                value: Entries supplied as ``value`` and processed in
                    caller-provided order.
                field_name: Field label included in validation failures for the
                    selected input.

            Returns:
                The validated ``normalized``.

            Raises:
                ValueError: If the ``field_name`` is not a non-empty list of
                    strings; or ``field_name`` must contain only non-empty
                    strings.
            """
            if not isinstance(value, list) or not value:
                raise ValueError(f"{field_name} must be a non-empty list of strings")

            normalized: List[str] = []
            seen = set()
            for key in value:
                if not isinstance(key, str) or not key.strip():
                    raise ValueError(
                        f"{field_name} must contain only non-empty strings"
                    )
                stripped_key = key.strip()
                if stripped_key not in seen:
                    seen.add(stripped_key)
                    normalized.append(stripped_key)
            return normalized

        if not isinstance(member_key_config, dict):
            raise ValueError("member_key_config must be a mapping")

        normalized_config: Dict[str, List[str]] = {}
        for baseboard_type, keys in member_key_config.items():
            if not isinstance(baseboard_type, str) or not baseboard_type.strip():
                raise ValueError("member_key_config keys must be non-empty strings")
            normalized_type = baseboard_type.strip()
            normalized_config[normalized_type] = normalize_keys(
                keys, f"member_key_config[{normalized_type!r}]"
            )

        return normalized_config, normalize_keys(
            default_member_key, "default_member_key"
        )

    def _get_component_integrity_handler_and_expected_operations(
        self, collection_type: str, kwargs: Dict[str, Any]
    ) -> Tuple[Callable[..., Awaitable[Dict[str, int]]], int]:
        """
        Select the collection handler and expected operation count per member.

        The expected count is used even when the per-member GET fails before the
        handler can run, so status accounting reflects attempted work.

        Args:
            collection_type: Text supplied as collection type in the format
                accepted by this function.
            kwargs: Mapping supplying fields for collection handler and expected
                operation count per member.

        Returns:
            A tuple containing ``metadata mapping`` and ``integer count`` in
            that order.
        """
        if collection_type == "spdm_measurements":
            measurement_indices = kwargs.get("measurement_indices", [50])
            return (
                self._handle_spdm_measurements_collection,
                len(measurement_indices),
            )
        if collection_type == "certificates":
            return (self._handle_certificate_collection, 1)
        return (self._handle_generic_collection, 1)

    async def _handle_spdm_measurements_collection(
        self,
        dut_id: str,
        component_response: Dict[str, Any],
        member_uri: str,
        member_id: str,
        kwargs: Dict[str, Any],
        function_tag: str,
        output_files: List[str],
        request_delay: int = 0,
    ) -> Dict[str, Any]:
        """
        Handle SPDM measurements collection.

        The implementation uses ``dut_id``, ``component_response``,
        ``member_uri``, ``member_id``, and ``kwargs`` to handle SPDM
        measurements collection. Terminal status is emitted only after SPDM
        measurements collection and its owned cleanup have completed. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind. The operation mutates ``output_files`` in
        place; ownership of those objects remains with the caller.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            component_response: Mapping supplying fields for SPDM measurements
                collection.
            member_uri: Validated remote resource identifier used for member
                URI.
            member_id: Stable member identifier used to correlate configuration,
                logs, and results.
            kwargs: Mapping supplying fields for SPDM measurements collection.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            output_files: Entries supplied as ``output_files`` without
                transferring container ownership.
            request_delay: Numeric request delay used while the operation
                performs bounded accounting.

        Returns:
            A mapping containing handle spdm measurements collection.
        """
        index_list = kwargs.get("measurement_indices", [50])
        collection_result = {
            "successful_operations": 0,
            "total_operations": len(index_list),
            "error_messages": [],
        }
        collector_id = kwargs.get("collector_id")
        if not isinstance(collector_id, str) or not collector_id.strip():
            reason = "collector_id is required for SPDM task and artifact ownership"
            await self._log_runtime("ERROR", "RedfishService", reason, dut_id)
            collection_result["error_messages"].append(reason)
            return collection_result
        collector_id = collector_id.strip()

        # Check for SPDM action target
        action_name = kwargs.get(
            "action_name", "#ComponentIntegrity.SPDMGetSignedMeasurements"
        )
        actions = component_response.get("Actions")
        action_data = actions.get(action_name) if isinstance(actions, Mapping) else None
        action_target = (
            action_data.get("target") if isinstance(action_data, Mapping) else None
        )

        if not action_target:
            await self._log_runtime(
                "WARN",
                "RedfishService",
                f"No SPDM action found for uri {member_uri}. Skipping...",
                dut_id,
            )
            collection_result["error_messages"].append(
                f"{member_id}: SPDM signed-measurements action is unavailable"
            )
            return collection_result

        try:
            normalized_member_uri = self._normalize_dut_response_path(
                dut_id,
                member_uri,
                context="SPDM ComponentIntegrity member URI",
            )
            normalized_action_target = self._normalize_dut_response_path(
                dut_id,
                action_target,
                context="advertised SPDM signed-measurements action target",
            )
            action_target = validate_redfish_uri_path(
                normalized_action_target,
                context="advertised SPDM signed-measurements action target",
                service_root=normalized_member_uri,
            )
        except (AttributeError, RuntimeError, TypeError, ValueError):
            # Controller-supplied; never echo the rejected value or dispatch it.
            reason = (
                f"{member_id}: SPDM signed-measurements action has an unsafe target"
            )
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                reason,
                dut_id,
            )
            collection_result["error_messages"].append(reason)
            return collection_result

        # Collect measurements for specific indices
        slot_id = kwargs.get("slot_id", 0)

        for j, index in enumerate(index_list):
            # Add delay between measurement requests to prevent BMC overload
            if j > 0:
                await asyncio.sleep(request_delay)

            payload = {"SlotId": slot_id, "MeasurementIndices": [index]}

            # Execute the SPDM measurement request
            success, measurement_response, error_details = await self.dispatch_request(
                dut_id, "POST", action_target, payload, retry_count=0
            )

            if success:
                task_id = self._bounded_response_task_id(measurement_response)
                if not task_id:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"No task ID in response for SPDM measurement index {index} from {member_uri}",
                        dut_id,
                    )
                    collection_result["error_messages"].append(
                        f"{member_id} index {index}: SPDM response did not include a task ID"
                    )
                    continue

                # Wait for task completion (like legacy implementation)
                max_retries = kwargs.get("max_retries", 50)
                task_poll_interval = kwargs.get("task_poll_interval", 30)
                entity_context = {
                    "entity_type": "ComponentIntegrity",
                    "entity_id": member_id,
                    "log_service": "spdm_measurements",
                }

                task_completed = await self._wait_for_task_completion(
                    dut_id,
                    task_id,
                    max_retries=max_retries,
                    poll_interval=task_poll_interval,
                    function_tag=function_tag,
                    entity_context=entity_context,
                    collector_id=collector_id,
                )

                if not task_completed:
                    task_failure = entity_context.get("task_failure", {})
                    failure_parts = [
                        part
                        for part in [
                            task_failure.get("state"),
                            task_failure.get("status"),
                        ]
                        if part
                    ]
                    raw_messages = task_failure.get("messages", [])
                    if raw_messages is None:
                        task_messages = []
                    elif isinstance(raw_messages, list):
                        task_messages = raw_messages
                    else:
                        task_messages = [raw_messages]
                    for message in task_messages:
                        if isinstance(message, dict):
                            text = message.get("Message") or message.get("MessageId")
                        else:
                            text = str(message)
                        if not text:
                            continue
                        text = str(text)
                        # Benign lifecycle events (e.g. TaskEvent.1.0.TaskStarted)
                        # are noise in a failure summary.
                        if re.fullmatch(
                            r"TaskEvent\.\d+\.\d+\.Task(Started|ProgressChanged)",
                            text,
                        ):
                            continue
                        failure_parts.append(text)
                    failure_detail = "; ".join(failure_parts) or "task did not complete"
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Task {task_id} did not complete for SPDM measurement index {index} from {member_uri}",
                        dut_id,
                    )
                    collection_result["error_messages"].append(
                        f"{member_id} index {index} task {task_id}: {failure_detail}"
                    )
                    continue

                # Get dump location (like legacy implementation)
                # SPDM measurements are not binary attachments, so use attachment=False
                dump_location = await self._get_dump_location(
                    task_completed, dut_id, attachment=False
                )
                if not dump_location:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"No dump location found for task {task_id} (SPDM measurement index {index})",
                        dut_id,
                    )
                    collection_result["error_messages"].append(
                        f"{member_id} index {index} task {task_id}: no measurement result location"
                    )
                    continue

                # Fetch the actual measurement results
                success, actual_results, result_metadata = await self.dispatch_request(
                    dut_id, "GET", dump_location
                )

                if success:
                    # Create kwargs without output_pattern to avoid duplication
                    save_kwargs = kwargs.copy()
                    save_kwargs["collector_id"] = collector_id
                    save_kwargs["output_pattern"] = kwargs.get("output_pattern", "")
                    save_kwargs["substitutions"] = {
                        "member_id": member_id,
                        "index": str(index),
                    }

                    file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        actual_results,
                        function_tag,
                        request_timing_operation_ids=self._request_timing_operation_id(
                            result_metadata
                        ),
                        **save_kwargs,
                    )
                    if file_path:
                        output_files.append(file_path)
                        collection_result["successful_operations"] += 1
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Successfully collected SPDM measurement index {index} from {member_uri}",
                            dut_id,
                        )
                    else:
                        await self._log_runtime(
                            "ERROR",
                            "RedfishService",
                            f"Failed to save SPDM measurement index {index} from {member_uri}",
                            dut_id,
                        )
                        collection_result["error_messages"].append(
                            f"{member_id} index {index}: failed to save measurement result"
                        )
                else:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Failed to fetch actual results from {dump_location} for task {task_id}",
                        dut_id,
                    )
                    collection_result["error_messages"].append(
                        f"{member_id} index {index} task {task_id}: "
                        f"failed to fetch result from {dump_location}: {result_metadata}"
                    )
            else:
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    f"Failed to initiate SPDM measurement for index {index} from {member_uri}",
                    dut_id,
                )
                collection_result["error_messages"].append(
                    f"{member_id} index {index}: SPDM request failed: "
                    f"{error_details or measurement_response}"
                )

        # Keep the existing successful-handler contract stable; callers only need
        # the additional field when there is actionable failure detail.
        if not collection_result["error_messages"]:
            collection_result.pop("error_messages")
        return collection_result

    async def _handle_certificate_collection(
        self,
        dut_id: str,
        component_response: Dict[str, Any],
        member_uri: str,
        member_id: str,
        kwargs: Dict[str, Any],
        function_tag: str,
        output_files: List[str],
        request_delay: int,
    ) -> Dict[str, int]:
        """
        Handle certificate collection.

        After applying local validation, the function forwards ``dut_id``,
        ``component_response``, ``member_uri``, ``member_id``, and ``kwargs`` to
        ``self._handle_generic_collection`` and preserves its return and
        exception contract. Terminal status is emitted only after certificate
        collection and its owned cleanup have completed. Owned asynchronous work
        is awaited before return, so completion does not leave an unobserved
        task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            component_response: Mapping supplying fields for certificate
                collection.
            member_uri: Validated remote resource identifier used for member
                URI.
            member_id: Stable member identifier used to correlate configuration,
                logs, and results.
            kwargs: Mapping supplying fields for certificate collection.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            output_files: Entries supplied as ``output_files`` without
                transferring container ownership.
            request_delay: Numeric request delay used while the operation
                performs bounded accounting.

        Returns:
            A mapping containing handle certificate collection.
        """
        # For certificates, we might want to collect additional certificate data
        # This is a placeholder for certificate-specific logic
        return await self._handle_generic_collection(
            dut_id,
            component_response,
            member_uri,
            member_id,
            kwargs,
            function_tag,
            output_files,
            request_delay,
        )

    async def _handle_generic_collection(
        self,
        dut_id: str,
        component_response: Dict[str, Any],
        member_uri: str,
        member_id: str,
        kwargs: Dict[str, Any],
        function_tag: str,
        output_files: List[str],
        request_delay: int = 0,
    ) -> Dict[str, int]:
        """
        Handle generic collection - just save the component response.

        The implementation uses ``dut_id``, ``component_response``,
        ``member_uri``, ``member_id``, and ``kwargs`` to handle generic
        collection - just save the component response. Terminal status is
        emitted only after generic collection - just save the component response
        and its owned cleanup have completed. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.
        The operation mutates ``output_files`` in place; ownership of those
        objects remains with the caller.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            component_response: Mapping supplying fields for generic collection
                - just save the component response.
            member_uri: Validated remote resource identifier used for member
                URI.
            member_id: Stable member identifier used to correlate configuration,
                logs, and results.
            kwargs: Mapping supplying fields for generic collection - just save
                the component response.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            output_files: Entries supplied as ``output_files`` without
                transferring container ownership.
            request_delay: Numeric request delay used while the operation
                performs bounded accounting.

        Returns:
            A mapping containing the ``successful_operations`` and
            ``total_operations`` fields.
        """
        # Create kwargs without output_pattern to avoid duplication
        save_kwargs = kwargs.copy()
        save_kwargs["output_pattern"] = kwargs.get("output_pattern", "")
        save_kwargs["substitutions"] = {
            "member_id": member_id,
        }

        file_path = await self._save_data_to_file_with_pattern(
            dut_id,
            component_response,
            function_tag,
            **save_kwargs,
        )
        if file_path:
            output_files.append(file_path)
            return {"successful_operations": 1, "total_operations": 1}

        return {"successful_operations": 0, "total_operations": 1}

    def _filter_system_dump_payloads_by_capability(
        self,
        dut_id: str,
        system_id: str,
        payloads: List[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        """
        Filter System/Dump payloads against preflight ActionInfo capabilities.

        The capability cache is deliberately optional. Older orchestration paths
        and platforms without ActionInfo retain the configured payload order
        unchanged. An authoritative cache, however, removes payloads that the
        live firmware did not advertise so collectors do not generate
        predictable HTTP 400 responses.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_id: Stable system identifier used to correlate configuration,
                logs, and results.
            payloads: Mapping supplying fields for filter System/Dump payloads
                against preflight ActionInfo capabilities.

        Returns:
            The filter system dump payloads by capability returned in
            operation-defined order.
        """

        if not payloads:
            return []

        orchestrator = getattr(self, "orchestrator", None)
        filter_payloads = getattr(
            orchestrator, "filter_supported_system_dump_payloads", None
        )
        if not callable(filter_payloads):
            return list(payloads)

        try:
            filtered = filter_payloads(
                dut_id,
                list(payloads),
                system_id=system_id,
            )
        except TypeError:
            # Compatibility with an early capability-provider implementation that did
            # not yet accept a per-system argument.
            try:
                filtered = filter_payloads(dut_id, list(payloads))
            except Exception:
                logger.exception(
                    "Failed to filter System dump payloads for %s/%s",
                    dut_id,
                    system_id,
                )
                return list(payloads)
        except Exception:
            logger.exception(
                "Failed to filter System dump payloads for %s/%s",
                dut_id,
                system_id,
            )
            return list(payloads)

        return list(payloads) if filtered is None else list(filtered)

    async def _query_exact_diagnostic_action_info(
        self,
        dut_id: str,
        entity_type: str,
        entity_id: str,
        log_service: str,
    ) -> Optional[List[str]]:
        """
        Return one strictly validated OEM diagnostic allow-list.

        ``None`` means the ActionInfo response was unavailable or malformed; an
        empty list is an authoritative response that advertises no OEM
        diagnostic values. Callers opting into this helper must fail closed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            entity_id: Stable entity identifier used to correlate configuration,
                logs, and results.
            log_service: Text supplied as log service in the format accepted by
                this function.

        Returns:
            The query exact diagnostic action info returned in operation-defined
            order, or ``None`` when the requested value is unavailable.
        """

        action_info_uri = (
            f"/redfish/v1/{entity_type}/{entity_id}/LogServices/{log_service}/"
            "CollectDiagnosticDataActionInfo"
        )
        success, response, _ = await self.dispatch_request(
            dut_id,
            "GET",
            action_info_uri,
            bypass_cache=True,
            retry_count=0,
        )
        if not success or not isinstance(response, dict):
            return None
        parameters = response.get("Parameters")
        if not isinstance(parameters, list):
            return None
        matches = [
            parameter
            for parameter in parameters
            if isinstance(parameter, dict)
            and parameter.get("Name") == "OEMDiagnosticDataType"
        ]
        if len(matches) != 1:
            return None
        allowable_values = matches[0].get("AllowableValues")
        if not isinstance(allowable_values, list) or any(
            not isinstance(value, str) or not value for value in allowable_values
        ):
            return None
        return list(allowable_values)

    async def collect_system_dump_capabilities(
        self,
        dut_id: str,
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Persist the canonical System Dump ActionInfo preflight capability map.

        R46 is a reporting collector. Discovery happens before applicability is
        resolved; this hook writes that same validated run-scoped cache instead
        of issuing a second set of requests that could diverge from preflight.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing system dump capabilities.
        """

        orchestrator = getattr(self, "orchestrator", None)
        get_capabilities = getattr(orchestrator, "get_system_dump_capabilities", None)
        if not callable(get_capabilities):
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[
                    "System Dump capability preflight is unavailable for this run"
                ],
                operation_name="system_dump_capabilities",
                additional_context={"status": "error"},
            )

        capabilities = get_capabilities(dut_id)
        if inspect.isawaitable(capabilities):
            capabilities = await capabilities
        if capabilities is None:
            capabilities = {
                "dut_id": dut_id,
                "status": "unknown",
                "systems": {},
                "reason": "System Dump capability preflight returned no data",
            }

        output_file = await self._save_data_to_file_with_pattern(
            dut_id,
            capabilities,
            function_tag,
            **kwargs,
        )
        save_succeeded = bool(output_file)
        capability_status = (
            str(capabilities.get("status", "unknown")).lower()
            if isinstance(capabilities, dict)
            else "unknown"
        )
        authoritative = (
            capabilities.get("authoritative")
            if isinstance(capabilities, dict)
            else None
        )
        discovery_complete = (
            capability_status == "available" and authoritative is not False
        )
        discovery_unsupported = (
            capability_status == "unsupported" and authoritative is True
        )
        capability_errors = (
            capabilities.get("errors", []) if isinstance(capabilities, dict) else []
        )
        if not isinstance(capability_errors, list):
            capability_errors = [capability_errors]

        if not save_succeeded:
            successful_operations = 0
            total_operations = 1
            error_messages = ["Failed to save System Dump capability artifact"]
        elif discovery_complete:
            successful_operations = 1
            total_operations = 1
            error_messages = []
        elif discovery_unsupported:
            successful_operations = 0
            total_operations = 0
            error_messages = []
        elif capability_status == "partial":
            # The artifact itself is useful, but one or more Systems could not be
            # characterized. Report partial rather than a misleading R46 success.
            successful_operations = 1
            total_operations = 2
            error_messages = ["System Dump capability discovery is partial"]
        else:
            successful_operations = 0
            total_operations = 1
            error_messages = [
                f"System Dump capability discovery is {capability_status}"
            ]
        error_messages.extend(
            str(message) for message in capability_errors if str(message).strip()
        )

        result_context = {
            "capability_status": capability_status,
            "authoritative": authoritative,
        }
        if discovery_unsupported and save_succeeded:
            result_context.update(
                {
                    "status": "skipped",
                    "reason": (
                        "No discovered System advertises System Dump ActionInfo; "
                        "capability collection is unsupported"
                    ),
                    "intentional_evidence_only_skip": True,
                }
            )

        return await self._create_standardized_collector_result(
            successful_operations=successful_operations,
            total_operations=total_operations,
            output_files=[output_file] if output_file else [],
            error_messages=error_messages,
            operation_name="system_dump_capabilities",
            additional_context=result_context,
        )

    async def collect_diagnostic_data(
        self,
        dut_id: str,
        entity_type: str,
        log_service: str,
        payload_types: List[str],
        default_payload: Dict[str, Any],
        function_tag: str,
        fallback_payloads: Optional[List[Dict[str, Any]]] = None,
        eligibility_route: Optional[str] = None,
        diagnostic_concurrency: Optional[Dict[str, Any]] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect diagnostic data based on supported diagnostic types.

        An explicit DUT/tool value is the highest-priority source.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            entity_type: Text supplied as entity type in the format accepted by
                this function.
            log_service: Text supplied as log service in the format accepted by
                this function.
            payload_types: Entries supplied as ``payload_types`` without
                transferring container ownership.
            default_payload: Mapping supplying fields for diagnostic data based
                on supported diagnostic types.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            fallback_payloads: Optional fallback payloads; ``None`` selects the
                function's default behavior.
            eligibility_route: Optional catalog DGX diagnostic route whose
                eligibility probe must succeed before entity discovery or any
                diagnostic POST. An exact eligibility miss is an intentional
                skip; an unavailable or malformed probe is an error.
            diagnostic_concurrency: Optional catalog-owned compatible cohort
                policy for the selected baseboard.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing diagnostic data.
        """
        try:
            output_files = []
            operation_results: List[Dict[str, Any]] = []
            error_messages = []
            failed_entity_contexts: Dict[str, Dict[str, Any]] = {}
            capability_skipped_entities: List[str] = []
            diagnostic_domain_blocked_entities: List[str] = []
            diagnostic_domain_block_context: Optional[Dict[str, Any]] = None
            suppressed_payload_attempts = 0
            suppressed_required_operations = 0
            required_gate_accounting_active = False
            collector_id = kwargs.get("collector_id", "")
            self._apply_diagnostic_concurrency_scope(
                dut_id,
                collector_id,
                diagnostic_concurrency,
                kwargs.get("target_baseboard"),
                kwargs,
            )

            if eligibility_route is not None:
                route_config = self._get_dgx_diagnostic_route(eligibility_route)
                (
                    is_eligible,
                    eligibility_absent,
                    eligibility_reason,
                ) = await self._probe_dgx_route_eligibility(dut_id, route_config)
                if not is_eligible:
                    if not eligibility_absent:
                        return await self._create_standardized_collector_result(
                            successful_operations=0,
                            total_operations=1,
                            output_files=[],
                            error_messages=[eligibility_reason],
                            operation_name="diagnostic_eligibility_probe",
                            additional_context={
                                "dgx_eligibility_proven": False,
                                "route": eligibility_route,
                            },
                            dut_id=dut_id,
                            collector_id=collector_id,
                        )
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"collect_diagnostic_data: {eligibility_reason}; skipping",
                        dut_id,
                    )
                    return {
                        "success": True,
                        "status": "skipped",
                        "reason": eligibility_reason,
                        "context": {
                            "successful_operations": 0,
                            "total_operations": 0,
                            "intentional_evidence_only_skip": True,
                            "skip_classification": (
                                VALID_NOT_APPLICABLE_SKIP_CLASSIFICATION
                            ),
                            "dgx_applicable": False,
                            "route": eligibility_route,
                        },
                        "output_files": [],
                    }

            payload_config_key = kwargs.get("default_payload_config_key")
            if payload_config_key:
                dut = self.dut_manager.get_dut(dut_id)
                explicit_keys = getattr(dut, "explicit_config_keys", {})
                is_explicit = (
                    bool(explicit_keys.get(payload_config_key, False))
                    if isinstance(explicit_keys, dict)
                    else (
                        payload_config_key in explicit_keys
                        if isinstance(explicit_keys, (set, frozenset, list, tuple))
                        else False
                    )
                )
                configured_payload = self.dut_manager.get_dut_config(dut_id).get(
                    payload_config_key
                )
                if is_explicit and isinstance(configured_payload, (dict, list)):
                    # An explicit DUT/tool value is the highest-priority source.
                    default_payload = copy.deepcopy(configured_payload)
                elif default_payload is None and isinstance(
                    configured_payload, (dict, list)
                ):
                    # BaseSettings environment values sit below the
                    # spreadsheet/catalog payload and win only when that
                    # higher source supplies no payload.
                    default_payload = copy.deepcopy(configured_payload)

            # Check if we have validation results with filtered entities.
            # Presence is authoritative even when validation found no entities.
            filtered_systems = kwargs.get("filtered_systems")
            filtered_managers = kwargs.get("filtered_managers")
            filtered_chassis = kwargs.get("filtered_chassis")

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"collect_diagnostic_data context: {kwargs.get('context', {})}",
                dut_id,
            )

            if filtered_systems is not None and entity_type == "Systems":
                # Use filtered systems from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_systems)} filtered systems from validation: {[sys['id'] for sys in filtered_systems]}",
                    dut_id,
                )
                entity_ids = [sys["id"] for sys in filtered_systems]

                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_system_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "system", dut_config)
                if len(entity_ids) != len(original_system_ids):
                    await log_filtered_ids(
                        original_system_ids,
                        entity_ids,
                        "system",
                        self.logger,
                        dut_id,
                    )
            elif filtered_managers is not None and entity_type == "Managers":
                # Use filtered managers from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_managers)} filtered managers from validation: {[mgr['id'] for mgr in filtered_managers]}",
                    dut_id,
                )
                entity_ids = [mgr["id"] for mgr in filtered_managers]

                # Apply ID filtering based on DUT configuration
                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_manager_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "manager", dut_config)

                # Log filtered IDs if any were filtered
                if len(entity_ids) != len(original_manager_ids):
                    await log_filtered_ids(
                        original_manager_ids,
                        entity_ids,
                        "manager",
                        self.logger,
                        dut_id,
                    )
            elif filtered_chassis is not None and entity_type == "Chassis":
                # Use filtered chassis from validation
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using {len(filtered_chassis)} filtered chassis from validation: {[chassis['id'] for chassis in filtered_chassis]}",
                    dut_id,
                )
                entity_ids = [chassis["id"] for chassis in filtered_chassis]
                dut_config = self.dut_manager.get_dut_config(dut_id)
                original_chassis_ids = entity_ids.copy()
                entity_ids = filter_ids(entity_ids, "chassis", dut_config)
                if len(entity_ids) != len(original_chassis_ids):
                    await log_filtered_ids(
                        original_chassis_ids,
                        entity_ids,
                        "chassis",
                        self.logger,
                        dut_id,
                    )
            else:
                override_key = {
                    "Systems": "SYSTEM_ID_OVERRIDE",
                    "Managers": "MANAGER_ID_OVERRIDE",
                    "Chassis": "CHASSIS_ID_OVERRIDE",
                }.get(entity_type)
                dut_config = self.dut_manager.get_dut_config(dut_id)
                id_overrides = dut_config.get(override_key, []) if override_key else []
                if not id_overrides and override_key:
                    id_overrides = (self.dut_manager.tool_config or {}).get(
                        override_key, []
                    )

                if id_overrides:
                    entity_ids = list(id_overrides)
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using {override_key}: {entity_ids}; skipping discovery",
                        dut_id,
                    )
                else:
                    # Get entities - dut_manager handles URI construction automatically
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"No filtered {entity_type.lower()} found in context, fetching all {entity_type}",
                        dut_id,
                    )
                    success, entities, _ = await self.dispatch_request(
                        dut_id, "GET", entity_type
                    )

                    if not success:
                        return await self._create_standardized_collector_result(
                            successful_operations=0,
                            total_operations=1,
                            output_files=[],
                            error_messages=[f"Failed to get {entity_type}: {entities}"],
                            operation_name="entity_discovery",
                            additional_context={"entity_type": entity_type},
                        )

                    entity_ids = [
                        entity.get("@odata.id", "").split("/")[-1]
                        for entity in entities.get("Members", [])
                    ]
                    id_type = {
                        "Systems": "system",
                        "Managers": "manager",
                        "Chassis": "chassis",
                    }.get(entity_type)
                    if id_type:
                        entity_ids = filter_ids(entity_ids, id_type, dut_config)

            if not entity_ids:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[f"No {entity_type} found"],
                    operation_name="entity_discovery",
                    additional_context={"entity_type": entity_type},
                )

            def future_required_operation_counts(
                start_index: int,
            ) -> Dict[str, int]:
                """
                Return authored required-default counts for future entities.

                System Dump payload capability filtering is cache-backed and
                synchronous at this boundary. Applying it per future System
                preserves asymmetric advertised payload cardinality without
                probing the DUT or constructing any request.

                Args:
                    start_index: First index in ``entity_ids`` to count.

                Returns:
                    Mapping from each future entity with at least one supported
                    required operation to its exact remaining cardinality.
                """
                authored_defaults = (
                    list(default_payload)
                    if isinstance(default_payload, list)
                    else [default_payload]
                )
                counts: Dict[str, int] = {}
                for future_entity_id in entity_ids[start_index:]:
                    future_defaults = list(authored_defaults)
                    if entity_type == "Systems" and log_service == "Dump":
                        future_defaults = (
                            self._filter_system_dump_payloads_by_capability(
                                dut_id,
                                future_entity_id,
                                future_defaults,
                            )
                        )
                    if future_defaults:
                        counts[future_entity_id] = len(future_defaults)
                return counts

            for k, entity_id in enumerate(entity_ids):
                # Add configurable delay between entity processing to prevent BMC overload
                if k > 0:
                    # Get sleep duration from collector definition and DUT config
                    collector_def = kwargs.get("collector_def", {})
                    dut_config = self.dut_manager.get_dut_config(dut_id)
                    sleep_duration = get_collector_sleep_duration(
                        kwargs.get("collector_id", ""),
                        collector_def,
                        dut_config,
                        1,
                    )

                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Sleeping {sleep_duration}s between {entity_type} entities",
                        dut_id,
                    )
                    await asyncio.sleep(sleep_duration)

                # Handle default_payload as either single payload or list of payloads.
                default_payloads = (
                    list(default_payload)
                    if isinstance(default_payload, list)
                    else [default_payload]
                )
                entity_fallback_payloads = list(fallback_payloads or [])

                if kwargs.get("require_exact_action_info", False):
                    action_info_values = await self._query_exact_diagnostic_action_info(
                        dut_id,
                        entity_type,
                        entity_id,
                        log_service,
                    )
                    configured_payloads = [
                        *default_payloads,
                        *entity_fallback_payloads,
                    ]
                    expected_values = [
                        payload.get("OEMDiagnosticDataType")
                        for payload in configured_payloads
                        if isinstance(payload, dict)
                        and isinstance(payload.get("OEMDiagnosticDataType"), str)
                    ]
                    if action_info_values is None:
                        capability_reason = "CollectDiagnosticDataActionInfo is unavailable or malformed"
                    elif len(expected_values) != len(configured_payloads):
                        capability_reason = (
                            "collector payload is missing OEMDiagnosticDataType"
                        )
                    else:
                        default_payloads = [
                            payload
                            for payload in default_payloads
                            if payload.get("OEMDiagnosticDataType")
                            in action_info_values
                        ]
                        entity_fallback_payloads = [
                            payload
                            for payload in entity_fallback_payloads
                            if payload.get("OEMDiagnosticDataType")
                            in action_info_values
                        ]
                        capability_reason = (
                            None
                            if default_payloads or entity_fallback_payloads
                            else "ActionInfo does not advertise the exact configured "
                            "OEMDiagnosticDataType value"
                        )

                    if capability_reason is not None:
                        capability_skipped_entities.append(entity_id)
                        expected_label = ", ".join(expected_values) or "<invalid>"
                        error_message = (
                            f"{entity_type} {entity_id}: strict ActionInfo gate "
                            f"rejected {expected_label}: {capability_reason}"
                        )
                        await self._log_runtime(
                            "ERROR",
                            "RedfishService",
                            error_message,
                            dut_id,
                        )
                        error_messages.append(error_message)
                        operation_results.append(
                            {
                                "entity_id": entity_id,
                                "payload": (
                                    configured_payloads[0]
                                    if configured_payloads
                                    else None
                                ),
                                "payload_label": expected_label,
                                "success": False,
                                "error": capability_reason,
                            }
                        )
                        failed_entity_contexts[entity_id] = {
                            "entity_type": entity_type,
                            "entity_id": entity_id,
                            "log_service": log_service,
                            "request_payload": (
                                configured_payloads[0] if configured_payloads else None
                            ),
                            "error_message": capability_reason,
                            "capability_requirement": (
                                "exact_collect_diagnostic_data_action_info"
                            ),
                        }
                        continue

                # R46 preflight capabilities are authoritative for System Dump
                # payload vocabulary.  Missing/unavailable ActionInfo is handled by
                # the orchestrator as an unknown state and leaves payloads unchanged.
                if entity_type == "Systems" and log_service == "Dump":
                    configured_defaults = list(default_payloads)
                    configured_fallbacks = list(entity_fallback_payloads)
                    default_payloads = self._filter_system_dump_payloads_by_capability(
                        dut_id, entity_id, default_payloads
                    )
                    entity_fallback_payloads = (
                        self._filter_system_dump_payloads_by_capability(
                            dut_id, entity_id, entity_fallback_payloads
                        )
                    )
                    if not default_payloads and not entity_fallback_payloads:
                        capability_skipped_entities.append(entity_id)
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            "No configured diagnostic payload is advertised by "
                            f"ActionInfo for Systems {entity_id}; skipping POST "
                            f"(configured defaults={len(configured_defaults)}, "
                            f"fallbacks={len(configured_fallbacks)})",
                            dut_id,
                        )
                        continue

                collect_all_defaults = kwargs.get("collect_all_defaults", True)
                required_payload_mode = bool(
                    kwargs.get("count_each_default_payload", False)
                )

                # Some collectors explicitly define a list as independent required
                # operations. Record each one so a success cannot hide a later
                # failure. Without that opt-in, preserve the legacy grouped/default
                # semantics (including fallback payloads).
                if required_payload_mode:
                    stop_required_payloads = False
                    blocked_required_payload = False
                    for i, payload in enumerate(default_payloads):
                        payload_label = payload.get(
                            "OEMDiagnosticDataType",
                            payload.get("DiagnosticDataType", f"default_{i + 1}"),
                        )
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Collecting required payload {i + 1}/{len(default_payloads)} "
                            f"for {entity_type} {entity_id}: {payload_label}",
                            dut_id,
                        )
                        attempt_disposition = DiagnosticAttemptDisposition()
                        attempt_kwargs = dict(kwargs)
                        attempt_kwargs["_diagnostic_attempt_disposition"] = (
                            attempt_disposition
                        )
                        status, output_file = await self._execute_redfish_dump_task(
                            dut_id=dut_id,
                            entity_type=entity_type,
                            entity_id=entity_id,
                            log_service=log_service,
                            payload=payload,
                            function_tag=function_tag,
                            **attempt_kwargs,
                        )
                        if attempt_disposition.blocked_before_post:
                            required_gate_accounting_active = True
                            future_required_counts = (
                                future_required_operation_counts(k + 1)
                                if attempt_disposition.capacity_pool is None
                                else {}
                            )
                            diagnostic_domain_block_context = (
                                attempt_disposition.as_context()
                            )
                            diagnostic_domain_blocked_entities.append(entity_id)
                            diagnostic_domain_blocked_entities.extend(
                                future_required_counts
                            )
                            if (
                                operation_results
                                or attempt_disposition.capacity_pool is not None
                            ):
                                remaining_required_operations = (
                                    len(default_payloads)
                                    - i
                                    + sum(future_required_counts.values())
                                )
                                suppressed_payload_attempts += (
                                    remaining_required_operations
                                )
                                suppressed_required_operations += (
                                    remaining_required_operations
                                )
                            blocked_required_payload = True
                            break
                        error = (
                            None
                            if status
                            else (
                                output_file
                                or f"Required payload failed for {entity_type} {entity_id}"
                            )
                        )
                        operation_results.append(
                            {
                                "entity_id": entity_id,
                                "payload_summary": (
                                    self._bounded_request_payload_summary(payload)
                                ),
                                "payload_label": str(payload_label),
                                "success": bool(status),
                                "error": error,
                            }
                        )
                        if status:
                            if output_file:
                                output_files.append(output_file)
                        else:
                            message = (
                                f"{entity_type} {entity_id} payload "
                                f"'{payload_label}': {error}"
                            )
                            error_messages.append(message)
                            failed_entity_contexts[f"{entity_id}:{payload_label}"] = {
                                "request_uri": f"{entity_type}/{entity_id}/LogServices/{log_service}/Actions/LogService.CollectDiagnosticData",
                                "request_payload_summary": (
                                    self._bounded_request_payload_summary(payload)
                                ),
                                "entity_type": entity_type,
                                "entity_id": entity_id,
                                "log_service": log_service,
                                "error_message": error,
                            }
                        if not attempt_disposition.resubmit_allowed:
                            required_gate_accounting_active = True
                            future_required_counts = (
                                future_required_operation_counts(k + 1)
                                if attempt_disposition.capacity_pool is None
                                else {}
                            )
                            diagnostic_domain_block_context = (
                                attempt_disposition.as_context()
                            )
                            remaining_required_operations = (
                                len(default_payloads)
                                - i
                                - 1
                                + sum(future_required_counts.values())
                            )
                            suppressed_payload_attempts += remaining_required_operations
                            suppressed_required_operations += (
                                remaining_required_operations
                            )
                            diagnostic_domain_blocked_entities.extend(
                                future_required_counts
                            )
                            stop_required_payloads = True
                            break
                    if blocked_required_payload or stop_required_payloads:
                        if attempt_disposition.capacity_pool is None:
                            break
                    continue

                # Legacy grouped semantics: collect every requested default when
                # configured, but treat the group as one entity. If every default
                # fails, continue through the configured fallback payloads.
                entity_success = False
                entity_output_files = []
                entity_error = None
                attempted_payload: Optional[Dict[str, Any]] = None
                entity_attempted = False
                entity_blocked_before_post = False
                entity_remote_rejection = False

                for i, payload in enumerate(default_payloads):
                    attempted_payload = payload
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Trying default payload {i + 1}/{len(default_payloads)} for {entity_type} {entity_id}",
                        dut_id,
                    )

                    attempt_disposition = DiagnosticAttemptDisposition()
                    attempt_kwargs = dict(kwargs)
                    attempt_kwargs["_diagnostic_attempt_disposition"] = (
                        attempt_disposition
                    )
                    status, output_file = await self._execute_redfish_dump_task(
                        dut_id=dut_id,
                        entity_type=entity_type,
                        entity_id=entity_id,
                        log_service=log_service,
                        payload=payload,
                        function_tag=function_tag,
                        **attempt_kwargs,
                    )
                    if attempt_disposition.blocked_before_post:
                        diagnostic_domain_block_context = (
                            attempt_disposition.as_context()
                        )
                        diagnostic_domain_blocked_entities.extend(
                            entity_ids[k:]
                            if attempt_disposition.capacity_pool is None
                            else [entity_id]
                        )
                        entity_blocked_before_post = True
                        break
                    entity_attempted = True

                    if status:
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Default payload {i + 1} succeeded for {entity_type} {entity_id}",
                            dut_id,
                        )
                        entity_success = True
                        if output_file:
                            entity_output_files.append(output_file)

                        if not collect_all_defaults:
                            break
                    else:
                        entity_error = (
                            output_file
                            if output_file
                            else f"Default payload {i + 1} failed for {entity_type} {entity_id}"
                        )
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Default payload {i + 1} failed for {entity_type} {entity_id}: {entity_error}",
                            dut_id,
                        )
                    if not attempt_disposition.resubmit_allowed:
                        diagnostic_domain_block_context = (
                            attempt_disposition.as_context()
                        )
                        suppressed_payload_attempts += (
                            len(default_payloads)
                            - i
                            - 1
                            + len(entity_fallback_payloads)
                        )
                        if attempt_disposition.capacity_pool is None:
                            diagnostic_domain_blocked_entities.extend(
                                entity_ids[k + 1 :]
                            )
                        entity_remote_rejection = True
                        break

                # If all default payloads failed and we have fallback payloads, try them
                if (
                    not entity_success
                    and entity_fallback_payloads
                    and not entity_blocked_before_post
                    and not entity_remote_rejection
                ):
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"All payload types failed for {entity_type} {entity_id}, trying {len(entity_fallback_payloads)} fallback payload(s)",
                        dut_id,
                    )

                    for i, fallback_payload in enumerate(entity_fallback_payloads, 1):
                        attempted_payload = fallback_payload
                        await self._log_runtime(
                            "INFO",
                            "RedfishService",
                            f"Trying fallback payload {i}/{len(entity_fallback_payloads)} for {entity_type} {entity_id}",
                            dut_id,
                        )

                        attempt_disposition = DiagnosticAttemptDisposition()
                        attempt_kwargs = dict(kwargs)
                        attempt_kwargs["_diagnostic_attempt_disposition"] = (
                            attempt_disposition
                        )
                        status, output_file = await self._execute_redfish_dump_task(
                            dut_id=dut_id,
                            entity_type=entity_type,
                            entity_id=entity_id,
                            log_service=log_service,
                            payload=fallback_payload,
                            function_tag=function_tag,
                            **attempt_kwargs,
                        )
                        if attempt_disposition.blocked_before_post:
                            diagnostic_domain_block_context = (
                                attempt_disposition.as_context()
                            )
                            diagnostic_domain_blocked_entities.extend(
                                entity_ids[k:]
                                if attempt_disposition.capacity_pool is None
                                else [entity_id]
                            )
                            entity_blocked_before_post = True
                            break
                        entity_attempted = True

                        if status:
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Fallback payload {i} succeeded for {entity_type} {entity_id}",
                                dut_id,
                            )
                            entity_success = True
                            if output_file:
                                entity_output_files.append(output_file)
                            break
                        else:
                            entity_error = (
                                output_file
                                if output_file
                                else f"Fallback payload {i} failed for {entity_type} {entity_id}"
                            )
                            await self._log_runtime(
                                "INFO",
                                "RedfishService",
                                f"Fallback payload {i} failed for {entity_type} {entity_id}: {entity_error}",
                                dut_id,
                            )
                        if not attempt_disposition.resubmit_allowed:
                            diagnostic_domain_block_context = (
                                attempt_disposition.as_context()
                            )
                            suppressed_payload_attempts += (
                                len(entity_fallback_payloads) - i
                            )
                            if attempt_disposition.capacity_pool is None:
                                diagnostic_domain_blocked_entities.extend(
                                    entity_ids[k + 1 :]
                                )
                            entity_remote_rejection = True
                            break

                output_files.extend(entity_output_files)
                if entity_blocked_before_post and not entity_attempted:
                    if attempt_disposition.capacity_pool is None:
                        break
                    continue
                payload_label = ""
                if attempted_payload:
                    payload_label = str(
                        attempted_payload.get(
                            "OEMDiagnosticDataType",
                            attempted_payload.get("DiagnosticDataType", ""),
                        )
                    )
                operation_results.append(
                    {
                        "entity_id": entity_id,
                        "payload": attempted_payload,
                        "payload_label": payload_label,
                        "success": entity_success and not entity_remote_rejection,
                        "error": (
                            None
                            if entity_success and not entity_remote_rejection
                            else entity_error
                        ),
                    }
                )

                # Collect error message if entity failed
                if (not entity_success or entity_remote_rejection) and entity_error:
                    error_messages.append(f"{entity_type} {entity_id}: {entity_error}")

                    # Store request context for failed entities (for detailed error logging)
                    failed_entity_contexts[entity_id] = {
                        "request_uri": f"{entity_type}/{entity_id}/LogServices/{log_service}/Actions/LogService.CollectDiagnosticData",
                        "request_payload": attempted_payload,
                        "entity_type": entity_type,
                        "entity_id": entity_id,
                        "log_service": log_service,
                        "error_message": entity_error,
                    }
                if entity_blocked_before_post or entity_remote_rejection:
                    if attempt_disposition.capacity_pool is None:
                        break

            # Use the base collector's standardized result function
            successful_operations = sum(
                1 for operation in operation_results if operation["success"]
            )
            diagnostic_domain_blocked_entities = list(
                dict.fromkeys(diagnostic_domain_blocked_entities)
            )
            blocked_operations = (
                len(diagnostic_domain_blocked_entities) if operation_results else 0
            )
            if required_gate_accounting_active:
                # Required-payload mode authors every default as an independent
                # operation.  The gate's blocked-entity list is retained as
                # evidence, but those entities are already represented by the
                # exact suppressed-operation count and must not be double-counted.
                blocked_operations = 0
                if not operation_results:
                    suppressed_required_operations = 0
            total_operations = (
                len(operation_results)
                + blocked_operations
                + suppressed_required_operations
            )

            successful_entities = sorted(
                {
                    operation["entity_id"]
                    for operation in operation_results
                    if operation["success"]
                }
            )
            failed_entities = sorted(
                {
                    operation["entity_id"]
                    for operation in operation_results
                    if not operation["success"]
                }
            )

            # Include failed entity contexts for detailed error logging
            additional_context = {
                "entity_type": entity_type,
                "log_service": log_service,
                "payload_types": payload_types,
                "entities_processed": len(entity_ids),
                "successful_entities": successful_entities,
                "failed_entities": failed_entities,
                "payload_results": operation_results,
                "capability_skipped_entities": capability_skipped_entities,
                "diagnostic_domain_blocked_entities": (
                    diagnostic_domain_blocked_entities
                ),
                "suppressed_payload_attempts": suppressed_payload_attempts,
                "suppressed_required_operations": suppressed_required_operations,
            }
            if diagnostic_domain_block_context is not None:
                additional_context["diagnostic_domain_block"] = (
                    diagnostic_domain_block_context
                )
                if operation_results and not error_messages:
                    error_messages.append(
                        diagnostic_domain_block_context.get("reason")
                        or "Diagnostic work was blocked by a prior no-resubmit rejection"
                    )

            # Add request contexts for failed entities if any exist
            if failed_entity_contexts:
                additional_context["failed_entity_contexts"] = failed_entity_contexts

            if not operation_results and capability_skipped_entities:
                additional_context.update(
                    {
                        "status": "skipped",
                        "reason": (
                            "No configured diagnostic payloads were advertised by "
                            "the live System Dump ActionInfo"
                        ),
                    }
                )

            if (
                not operation_results
                and diagnostic_domain_block_context is not None
                and not error_messages
            ):
                additional_context.update(
                    {
                        "status": "skipped",
                        "reason": (
                            diagnostic_domain_block_context.get("reason")
                            or "Diagnostic domain is blocked by a prior remote "
                            "no-resubmit rejection; no POST was sent"
                        ),
                    }
                )

            result = await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="entities",
                additional_context=additional_context,
            )
            await self._apply_dump_artifact_validation(
                result, kwargs.get("artifact_validation")
            )
            return result

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_diagnostic_data for {entity_type}/{log_service}: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Exception in collect_diagnostic_data: {str(e)}"],
                operation_name="diagnostic_data_collection",
                additional_context={
                    "entity_type": entity_type,
                    "log_service": log_service,
                    "error_type": type(e).__name__,
                },
            )

    def _get_dgx_diagnostic_route(self, route_name: str) -> Dict[str, Any]:
        """
        Return one validated catalog route through ConfigurationManager.

        Keeping this lookup in one small method gives lightweight service tests
        an injectable seam while production always uses the catalog manager.

        Args:
            route_name: Stable route name used for lookup and operator-facing
                diagnostics.

        Returns:
            A mapping containing dgx diagnostic route.

        Raises:
            ValueError: If the dgx diagnostic hook route is not a non-empty
                string; or DGX diagnostic hook route must not contain
                whitespace.
            RuntimeError: If dgx diagnostic routing lacks a validated catalog
                profile; or unknown DGX diagnostic route ``route_name``.
        """
        if not isinstance(route_name, str) or not route_name.strip():
            raise ValueError("DGX diagnostic hook route must be a non-empty string")
        if route_name != route_name.strip():
            raise ValueError("DGX diagnostic hook route must not contain whitespace")

        config_manager = getattr(self.orchestrator, "config_manager", None)
        get_route = getattr(config_manager, "get_dgx_diagnostic_route", None)
        if not callable(get_route):
            raise RuntimeError(
                "DGX diagnostic routing requires a validated catalog profile"
            )
        route = get_route(route_name)
        if not isinstance(route, Mapping):
            raise RuntimeError(f"Unknown DGX diagnostic route {route_name!r}")
        return dict(route)

    @staticmethod
    def _join_catalog_route_uri(
        parent_uri: str,
        segments: List[str],
        *,
        context: str,
    ) -> str:
        """
        Join validated catalog segments beneath an authoritative URI.

        After applying local validation, the function forwards ``parent_uri``,
        ``segments``, and ``context`` to ``validate_redfish_uri_path`` and
        preserves its return and exception contract.

        Args:
            parent_uri: Validated remote resource identifier used for parent
                URI.
            segments: Entries supplied as ``segments`` without transferring
                container ownership.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The canonical join catalog route URI text.

        Raises:
            ValueError: If the ``context`` segments are not a non-empty list; or
                ``context`` contains an invalid URI segment.
        """
        if not isinstance(segments, list) or not segments:
            raise ValueError(f"{context} segments must be a non-empty list")
        if any(
            not isinstance(segment, str)
            or not segment
            or segment != segment.strip()
            or "/" in segment
            or "\\" in segment
            for segment in segments
        ):
            raise ValueError(f"{context} contains an invalid URI segment")
        child_uri = f"{parent_uri.rstrip('/')}/{'/'.join(segments)}"
        return validate_redfish_uri_path(
            child_uri,
            context=context,
            service_root=parent_uri,
        )

    def _normalize_dut_response_path(
        self, dut_id: str, value: Any, *, context: str
    ) -> str:
        """
        Validate and rebase one response path through the DUT prefix policy.

        After applying local validation, the function forwards ``dut_id``,
        ``value``, and ``context`` to ``validate_redfish_uri_path`` and
        preserves its return and exception contract. Every required invariant is
        checked before a successful value is returned; invalid input follows the
        function's explicit exception path.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            value: Value object whose ``strip`` state is read while performing
                and rebase one response path through the DUT prefix policy.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The canonical DUT response path.

        Raises:
            ValueError: If the ``context`` is not a non-empty URI path;
                ``context`` is not a valid URI path; the ``context`` is not a
                path without authority, query, or fragment; or ``context``
                normalization returned a non-path value; or another input
                invariant is violated.
            RuntimeError: If ``context`` lacks DUT response URI normalization.
        """
        if not isinstance(value, str) or not value or value != value.strip():
            raise ValueError(f"{context} must be a non-empty URI path")
        try:
            parsed = urlsplit(value)
        except ValueError as error:
            raise ValueError(f"{context} is not a valid URI path") from error
        if (
            parsed.scheme
            or parsed.netloc
            or parsed.query
            or parsed.fragment
            or parsed.path != value
        ):
            raise ValueError(
                f"{context} must be a path without authority, query, or fragment"
            )
        validated = validate_redfish_uri_path(value, context=context)

        dut = self.dut_manager.get_dut(dut_id) if self.dut_manager else None
        normalize = getattr(dut, "normalize_redfish_uri", None)
        if not callable(normalize):
            raise RuntimeError(f"{context} requires DUT response URI normalization")
        normalized = normalize(validated)
        if not isinstance(normalized, str):
            raise ValueError(f"{context} normalization returned a non-path value")
        try:
            normalized_parts = urlsplit(normalized)
        except ValueError as error:
            raise ValueError(f"normalized {context} is not a valid URI path") from error
        if (
            normalized_parts.scheme
            or normalized_parts.netloc
            or normalized_parts.query
            or normalized_parts.fragment
            or normalized_parts.path != normalized
        ):
            raise ValueError(f"normalized {context} must remain a path-only URI")
        return validate_redfish_uri_path(normalized, context=f"normalized {context}")

    def _validate_dgx_diagnostic_action_target(
        self,
        dut_id: str,
        target: Any,
        resource_uri: str,
    ) -> str:
        """
        Accept only a normalized response path beneath DiagnosticLog.

        After applying local validation, the function forwards ``dut_id``,
        ``target``, and ``resource_uri`` to ``validate_redfish_uri_path`` and
        preserves its return and exception contract.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            target: Target consumed while the function attempts to accept only a
                normalized response path beneath DiagnosticLog.
            resource_uri: Validated remote resource identifier used for resource
                URI.

        Returns:
            The canonical dgx diagnostic action target text.
        """
        normalized = self._normalize_dut_response_path(
            dut_id,
            target,
            context="advertised DGX diagnostic action target",
        )
        return validate_redfish_uri_path(
            normalized,
            context="advertised DGX diagnostic action target",
            service_root=resource_uri,
        )

    async def _probe_dgx_route_eligibility(
        self,
        dut_id: str,
        route: Mapping[str, Any],
    ) -> Tuple[bool, bool, str]:
        """
        Return eligible, explicitly absent, and reason for one route probe.

        The implementation uses ``dut_id`` and ``route`` to produce eligible,
        explicitly absent, and reason for one route probe. Owned asynchronous
        work is awaited before return, so completion does not leave an
        unobserved task behind. Remote I/O uses the configured transport policy
        and returns only after its response or failure has been observed. If the
        function cannot produce eligible, explicitly absent, and reason for one
        route probe, its exception reaches the caller instead of being converted
        into a successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            route: Mapping supplying fields for eligible, explicitly absent, and
                reason for one route probe.

        Returns:
            A tuple containing ``success flag``, ``success flag``, and ``message
            text`` in that order.

        Raises:
            ValueError: If DGX diagnostic route is missing eligibility; or DGX
                diagnostic route eligibility is malformed.
        """
        eligibility = route.get("eligibility")
        if not isinstance(eligibility, Mapping):
            raise ValueError("DGX diagnostic route is missing eligibility")
        collection_key = eligibility.get("collection_uri_key")
        member_ids = eligibility.get("member_ids")
        if not isinstance(collection_key, str) or not isinstance(member_ids, list):
            raise ValueError("DGX diagnostic route eligibility is malformed")

        collection_uri = self.get_configured_uri(dut_id, collection_key)
        success, response, metadata = await self.dispatch_request(
            dut_id,
            "GET",
            collection_uri,
            bypass_cache=True,
            retry_count=0,
        )
        if not success:
            status = self._http_status_from_response(response, metadata)
            status_text = f"HTTP {status}" if status is not None else "request failed"
            return (
                False,
                False,
                f"{collection_key} eligibility is unavailable ({status_text})",
            )
        if not isinstance(response, Mapping) or not isinstance(
            response.get("Members"), list
        ):
            return (
                False,
                False,
                f"{collection_key} eligibility response is malformed",
            )

        expected_ids = set(member_ids)
        for member in response["Members"]:
            if not isinstance(member, Mapping):
                continue
            member_uri = member.get("@odata.id")
            if not isinstance(member_uri, str):
                continue
            try:
                normalized_member_uri = self._normalize_dut_response_path(
                    dut_id,
                    member_uri,
                    context=f"{collection_key} member URI",
                )
                normalized_member_uri = validate_redfish_uri_path(
                    normalized_member_uri,
                    context=f"{collection_key} member URI",
                    service_root=collection_uri,
                )
            except (RuntimeError, ValueError):
                continue
            parent_uri, _, member_id = normalized_member_uri.rpartition("/")
            if parent_uri == collection_uri and member_id in expected_ids:
                return True, False, f"exact {collection_key} member {member_id!r}"

        expected_names = ", ".join(sorted(repr(member) for member in expected_ids))
        return (
            False,
            True,
            (
                f"Not a DGX platform: {collection_uri} has no {expected_names} "
                "member; DGX diagnostic dump is not applicable"
            ),
        )

    def _resolve_dgx_diagnostic_resource_uri(
        self,
        dut_id: str,
        route: Mapping[str, Any],
    ) -> Tuple[str, str, str, str]:
        """
        Resolve the catalog route's DiagnosticLog resource for one DUT.

        The implementation uses ``dut_id`` and ``route`` to resolve the catalog
        route's DiagnosticLog resource for one DUT. If the function cannot
        resolve the catalog route's DiagnosticLog resource for one DUT, its
        exception reaches the caller instead of being converted into a
        successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            route: Mapping supplying fields for catalog route's DiagnosticLog
                resource for one DUT.

        Returns:
            A tuple containing ``collection key``, ``member identifier``,
            ``str``, and ``resource URI`` in that order.

        Raises:
            ValueError: If DGX diagnostic route is missing resource; or DGX
                diagnostic route resource is malformed.
        """
        resource = route.get("resource")
        if not isinstance(resource, Mapping):
            raise ValueError("DGX diagnostic route is missing resource")
        collection_key = resource.get("collection_uri_key")
        member_id = resource.get("member_id")
        relative_segments = resource.get("relative_segments")
        if (
            not isinstance(collection_key, str)
            or not isinstance(member_id, str)
            or not isinstance(relative_segments, list)
            or not relative_segments
        ):
            raise ValueError("DGX diagnostic route resource is malformed")

        collection_uri = self.get_configured_uri(dut_id, collection_key)
        resource_uri = self._join_catalog_route_uri(
            collection_uri,
            [member_id, *relative_segments],
            context="DGX diagnostic resource URI",
        )
        return collection_key, member_id, str(relative_segments[-1]), resource_uri

    async def _probe_dgx_diagnostic_action(
        self,
        dut_id: str,
        route: Mapping[str, Any],
    ) -> Tuple[bool, bool, Optional[str], str, str]:
        """
        Probe the catalog-selected DGX DiagnosticLog action.

        Returns ``(available, explicitly_absent, target, reason,
        resource_uri)``. A missing resource or unadvertised action is an
        optional route miss. Malformed metadata and request failures remain real
        failures.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            route: Mapping supplying fields for probe the catalog-selected DGX
                DiagnosticLog action.

        Returns:
            A tuple containing ``success flag``, ``success flag``, ``status or
            message text``, ``message text``, and ``resource URI`` in that
            order.

        Raises:
            ValueError: If DGX diagnostic route action is malformed.
        """
        _, _, _, resource_uri = self._resolve_dgx_diagnostic_resource_uri(dut_id, route)
        success, response, metadata = await self.dispatch_request(
            dut_id,
            "GET",
            resource_uri,
            bypass_cache=True,
            retry_count=0,
        )
        if not success:
            if self._is_redfish_resource_absent(response, metadata):
                return (
                    False,
                    True,
                    None,
                    f"{resource_uri} is not present on this platform",
                    resource_uri,
                )
            status = self._http_status_from_response(response, metadata)
            status_text = f"HTTP {status}: " if status is not None else ""
            return (
                False,
                False,
                None,
                f"Unable to probe {resource_uri}: {status_text}{response}",
                resource_uri,
            )

        if not isinstance(response, Mapping):
            return (
                False,
                False,
                None,
                f"{resource_uri} probe returned a non-object response",
                resource_uri,
            )

        action = route.get("action")
        advertised_names = (
            action.get("advertised_names") if isinstance(action, Mapping) else None
        )
        fallback_segments = (
            action.get("fallback_relative_segments")
            if isinstance(action, Mapping)
            else None
        )
        if not isinstance(advertised_names, list) or not isinstance(
            fallback_segments, list
        ):
            raise ValueError("DGX diagnostic route action is malformed")

        if "Actions" not in response:
            return (
                False,
                True,
                None,
                f"{resource_uri} does not advertise a configured diagnostic action",
                resource_uri,
            )
        actions = response["Actions"]
        if not isinstance(actions, Mapping):
            return (
                False,
                False,
                None,
                f"{resource_uri} has malformed Actions metadata",
                resource_uri,
            )

        action_name = next(
            (name for name in advertised_names if name in actions),
            None,
        )
        if action_name is None:
            return (
                False,
                True,
                None,
                f"{resource_uri} does not advertise a configured diagnostic action",
                resource_uri,
            )

        action_data = actions[action_name]
        if not isinstance(action_data, Mapping):
            return (
                False,
                False,
                None,
                f"Advertised action {action_name!r} has malformed metadata",
                resource_uri,
            )

        try:
            if "target" in action_data:
                target = self._validate_dgx_diagnostic_action_target(
                    dut_id, action_data["target"], resource_uri
                )
            else:
                fallback = self._join_catalog_route_uri(
                    resource_uri,
                    fallback_segments,
                    context="DGX diagnostic fallback action URI",
                )
                target = self._validate_dgx_diagnostic_action_target(
                    dut_id, fallback, resource_uri
                )
        except ValueError as error:
            return (
                False,
                False,
                None,
                f"Advertised action {action_name!r} has an unsafe target: {error}",
                resource_uri,
            )

        return (
            True,
            False,
            target,
            f"Catalog action {action_name!r} is advertised",
            resource_uri,
        )

    async def collect_dgx_diagnostic_data(
        self,
        dut_id: str,
        oem_types: List[str],
        function_tag: str,
        route: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Collect DGX-specific diagnostic data through a catalog-selected route.

        This hook is added to existing collectors (e.g.
        manager_on_demand_log_dump, manager_fpga_register_dump) and silently
        skips on non-DGX hardware.

        The catalog owns the eligibility collection, resource path, advertised
        action names, and target fallback. Runtime follows only that validated
        route and never probes its DiagnosticLog resource until an exact
        eligible Systems member has been observed.

        Output files are placed in a DGX/ subdirectory within the collector's
        output directory (enabled by an os.makedirs call in
        _save_data_to_file_with_pattern).

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            oem_types: Entries supplied as ``oem_types`` without transferring
                container ownership.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            route: Text supplied as route in the format accepted by this
                function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing dgx diagnostic data.
        """
        try:
            collector_id = kwargs.get("collector_id", "")
            route_config = self._get_dgx_diagnostic_route(route)
            (
                is_eligible,
                eligibility_absent,
                eligibility_reason,
            ) = await self._probe_dgx_route_eligibility(dut_id, route_config)
            if not is_eligible:
                if not eligibility_absent:
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[eligibility_reason],
                        operation_name="dgx_diagnostic_eligibility_probe",
                        additional_context={
                            "dgx_eligibility_proven": False,
                            "route": route,
                        },
                        dut_id=dut_id,
                        collector_id=collector_id,
                    )
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"collect_dgx_diagnostic_data: {eligibility_reason}; skipping",
                    dut_id,
                )
                return {
                    "success": True,
                    "status": "skipped",
                    "reason": eligibility_reason,
                    "context": {
                        "successful_operations": 0,
                        "total_operations": 0,
                        "intentional_evidence_only_skip": True,
                        "skip_classification": (
                            VALID_NOT_APPLICABLE_SKIP_CLASSIFICATION
                        ),
                        "dgx_applicable": False,
                        "route": route,
                    },
                    "output_files": [],
                }

            output_pattern = kwargs.get(
                "output_pattern",
                "DGX/Redfish_dgx_{oem_type}_BMC_{task_id}.tar.xz",
            )

            (
                action_available,
                action_absent,
                action_uri,
                probe_reason,
                resource_uri,
            ) = await self._probe_dgx_diagnostic_action(dut_id, route_config)
            entity_type, entity_id, log_service, _ = (
                self._resolve_dgx_diagnostic_resource_uri(dut_id, route_config)
            )
            if not action_available:
                if action_absent:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"collect_dgx_diagnostic_data: {probe_reason}; skipping optional DGX dump hook",
                        dut_id,
                    )
                    return {
                        "success": True,
                        "status": "skipped",
                        "reason": probe_reason,
                        "context": {
                            "successful_operations": 0,
                            "total_operations": 0,
                            "intentional_evidence_only_skip": True,
                            "dgx_applicable": True,
                            "dgx_diagnostic_action_available": False,
                            "route": route,
                            "resource_uri": resource_uri,
                        },
                        "output_files": [],
                    }

                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[probe_reason],
                    operation_name="dgx_diagnostic_action_probe",
                    additional_context={
                        "dgx_applicable": True,
                        "dgx_diagnostic_action_available": False,
                        "route": route,
                        "resource_uri": resource_uri,
                    },
                    dut_id=dut_id,
                    collector_id=collector_id,
                )

            output_files = []
            status_list = []
            error_messages = []
            diagnostic_domain_block_context: Optional[Dict[str, Any]] = None
            suppressed_oem_types = 0

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"DGX route {route!r} eligible via {eligibility_reason} — collecting {len(oem_types)} diagnostic type(s): {oem_types}",
                dut_id,
            )

            for oem_index, oem_type in enumerate(oem_types):
                payload = {
                    "DiagnosticDataType": "OEM",
                    "OEMDiagnosticDataType": oem_type,
                }
                # Substitute {oem_type} in the output_pattern for this iteration
                resolved_pattern = output_pattern.replace("{oem_type}", oem_type)

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"DGX: triggering {oem_type} dump via {resource_uri}",
                    dut_id,
                )

                # Strip all keys we pass explicitly to _execute_redfish_dump_task
                # to avoid "multiple values for keyword argument" errors from the context dict
                _explicit = {
                    "dut_id",
                    "entity_type",
                    "entity_id",
                    "log_service",
                    "payload",
                    "function_tag",
                    "output_pattern",
                    "collector_id",
                    "diagnostic_type",
                    # hook-specific params that don't belong in _execute_redfish_dump_task
                    "oem_types",
                    "route",
                    "dump_uri_override",
                }
                passthrough = {k: v for k, v in kwargs.items() if k not in _explicit}
                attempt_disposition = DiagnosticAttemptDisposition()
                passthrough["_diagnostic_attempt_disposition"] = attempt_disposition
                success, output_file = await self._execute_redfish_dump_task(
                    dut_id=dut_id,
                    entity_type=entity_type,
                    entity_id=entity_id,
                    log_service=log_service,
                    payload=payload,
                    function_tag=function_tag,
                    output_pattern=resolved_pattern,
                    collector_id=collector_id,
                    diagnostic_type=oem_type,
                    dump_uri_override=action_uri,
                    **passthrough,
                )

                if attempt_disposition.blocked_before_post:
                    diagnostic_domain_block_context = attempt_disposition.as_context()
                    suppressed_oem_types = len(oem_types) - oem_index
                    break

                status_list.append(success)
                if success and output_file:
                    output_files.append(output_file)
                if not success:
                    error_messages.append(f"DGX {oem_type}: {output_file}")
                if not attempt_disposition.resubmit_allowed:
                    diagnostic_domain_block_context = attempt_disposition.as_context()
                    suppressed_oem_types = len(oem_types) - oem_index - 1
                    break

            successful = len([s for s in status_list if s])
            total = len(status_list)
            if status_list:
                total += suppressed_oem_types

            additional_context = {
                "dgx_applicable": True,
                "oem_types": oem_types,
                "entity": resource_uri,
                "route": route,
            }
            if diagnostic_domain_block_context is not None:
                additional_context.update(
                    {
                        "diagnostic_domain_block": diagnostic_domain_block_context,
                        "suppressed_oem_types": suppressed_oem_types,
                    }
                )
                if not status_list:
                    additional_context.update(
                        {
                            "status": "skipped",
                            "intentional_evidence_only_skip": True,
                            "reason": (
                                diagnostic_domain_block_context.get("reason")
                                or "Diagnostic domain is blocked by a prior remote "
                                "no-resubmit rejection; no POST was sent"
                            ),
                        }
                    )

            result = await self._create_standardized_collector_result(
                successful_operations=successful,
                total_operations=total,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="dgx_diagnostic_data",
                additional_context=additional_context,
            )
            await self._apply_dump_artifact_validation(
                result, kwargs.get("artifact_validation")
            )
            return result

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_dgx_diagnostic_data: {e}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[f"Exception in collect_dgx_diagnostic_data: {e}"],
                operation_name="dgx_diagnostic_data",
                additional_context={"error_type": type(e).__name__, "status": "error"},
            )

    async def _query_action_info_for_systems(
        self,
        dut_id: str,
        system_ids: List[str],
        log_service: str = "Dump",
    ) -> Dict[str, List[str]]:
        """
        Return the query action info for systems.

        Prefer the canonical preflight cache used by R46 and collector gating.
        Besides avoiding duplicate BMC requests, this prevents result accounting
        from disagreeing with the exact capability decision made before POST.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_ids: Entries supplied as ``system_ids`` without transferring
                container ownership.
            log_service: Text supplied as log service in the format accepted by
                this function.

        Returns:
            The validated ``action_info_by_system``.
        """
        action_info_by_system: Dict[str, List[str]] = {}
        unresolved_system_ids = list(system_ids)

        # Prefer the canonical preflight cache used by R46 and collector gating.
        # Besides avoiding duplicate BMC requests, this prevents result accounting
        # from disagreeing with the exact capability decision made before POST.
        get_capabilities = getattr(
            getattr(self, "orchestrator", None),
            "get_system_dump_capabilities",
            None,
        )
        if callable(get_capabilities) and log_service == "Dump":
            try:
                cached_capabilities = get_capabilities(dut_id)
                if inspect.isawaitable(cached_capabilities):
                    cached_capabilities = await cached_capabilities
                cached_systems = (
                    cached_capabilities.get("systems", {})
                    if isinstance(cached_capabilities, dict)
                    else {}
                )
                if isinstance(cached_systems, dict):
                    for system_id in list(unresolved_system_ids):
                        cached_system = cached_systems.get(system_id)
                        if not isinstance(cached_system, dict):
                            continue
                        # A cached entry, available or not, means preflight already
                        # made the canonical query for this System.  Unavailable
                        # entries intentionally retain fail-open legacy behaviour.
                        unresolved_system_ids.remove(system_id)
                        if cached_system.get("status") != "available":
                            continue
                        values = cached_system.get("oem_diagnostic_data_types", [])
                        if isinstance(values, list):
                            action_info_by_system[system_id] = [
                                value for value in values if isinstance(value, str)
                            ]
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"[ActionInfo] Reusing canonical preflight values for {system_id}",
                                dut_id,
                            )
            except Exception as exc:
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    f"[ActionInfo] Failed to read preflight capability cache: {exc}",
                    dut_id,
                )

        for system_id in unresolved_system_ids:
            try:
                # Build the ActionInfo URI
                action_info_uri = f"/redfish/v1/Systems/{system_id}/LogServices/{log_service}/CollectDiagnosticDataActionInfo"

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"[ActionInfo] Querying ActionInfo for system {system_id}: {action_info_uri}",
                    dut_id,
                )

                success, response, _ = await self.dispatch_request(
                    dut_id, "GET", action_info_uri, bypass_cache=True
                )

                if not success or not response:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"[ActionInfo] Failed to query ActionInfo for {system_id}, will use fallback behavior",
                        dut_id,
                    )
                    continue

                # Parse the Parameters to find OEMDiagnosticDataType allowable values
                parameters = response.get("Parameters", [])
                oem_diagnostic_values = []

                for param in parameters:
                    if param.get("Name") == "OEMDiagnosticDataType":
                        oem_diagnostic_values = param.get("AllowableValues", [])
                        break

                if oem_diagnostic_values:
                    action_info_by_system[system_id] = oem_diagnostic_values
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[ActionInfo] System {system_id} supports {len(oem_diagnostic_values)} diagnostic types",
                        dut_id,
                    )
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"[ActionInfo] System {system_id} types: {oem_diagnostic_values}",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"[ActionInfo] No OEMDiagnosticDataType values found for {system_id}",
                        dut_id,
                    )

            except Exception as e:
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    f"[ActionInfo] Exception querying ActionInfo for {system_id}: {str(e)}",
                    dut_id,
                )
                continue

        return action_info_by_system

    def _check_diagnostic_type_in_action_info(
        self,
        oem_diagnostic_type: str,
        action_info_values: List[str],
    ) -> bool:
        """
        Check if a diagnostic type is in the ActionInfo allowable values.

        No ActionInfo available, assume it's valid (backward compatible).

        Args:
            oem_diagnostic_type: Text supplied as oem diagnostic type in the
                format accepted by this function.
            action_info_values: Entries supplied as ``action_info_values``
                without transferring container ownership.

        Returns:
            Whether the if a diagnostic type is in the ActionInfo allowable
            values operation succeeds.
        """
        if not action_info_values:
            # No ActionInfo available, assume it's valid (backward compatible)
            return True

        return oem_diagnostic_type in action_info_values

    @staticmethod
    def _parse_oem_diagnostic_value(value: Any) -> Dict[str, str]:
        """
        Parse an ActionInfo OEM diagnostic value without changing it.

        Values are semicolon-delimited key/value pairs such as
        ``DiagnosticType=NetIR;DeviceType=GPU_0``. The caller always retains the
        original string for the POST payload; this parsed view is used only to
        select the collector that owns the advertised target.

        Args:
            value: Value object whose ``split`` state is read while performing
                actionInfo OEM diagnostic value without changing it.

        Returns:
            A mapping containing oem diagnostic value.
        """
        if not isinstance(value, str):
            return {}
        parsed: Dict[str, str] = {}
        for segment in value.split(";"):
            key, separator, item_value = segment.partition("=")
            if not separator or not key.strip():
                continue
            parsed[key.strip()] = item_value.strip()
        return parsed

    @staticmethod
    def _canonical_system_dump_device_identifier(
        diagnostic_type: str, identifier: str
    ) -> str:
        """
        Normalize only known legacy System Dump aliases.

        Blackwell ActionInfo advertises the same physical network device in both
        legacy ``DeviceID`` form and newer ``NetIR`` ``DeviceType`` form. Keep
        every other identifier unchanged so distinct devices such as
        ``ConnectX_0`` are never collapsed by their numeric suffix alone.

        Args:
            diagnostic_type: Text supplied as diagnostic type in the format
                accepted by this function.
            identifier: Text supplied as identifier in the format accepted by
                this function.

        Returns:
            The canonical system dump device identifier text.
        """
        legacy_prefixes = {
            "Net_NVLinkManagementNIC": "NVLinkManagementNIC_",
            "Net_NVSwitch": "NVSwitch_",
        }
        prefix = legacy_prefixes.get(diagnostic_type)
        if prefix and re.fullmatch(r"\d+", identifier):
            return f"{prefix}{identifier}"
        return identifier

    @classmethod
    def _system_dump_capability_alias_identity(
        cls, diagnostic_type: str, identifier: str
    ) -> Optional[str]:
        """
        Return a shared identity only for a recognized legacy/NetIR alias.

        The implementation uses ``diagnostic_type`` and ``identifier`` to
        produce a shared identity only for a recognized legacy/NetIR alias.

        Args:
            diagnostic_type: Text supplied as diagnostic type in the format
                accepted by this function.
            identifier: Text supplied as identifier in the format accepted by
                this function.

        Returns:
            The canonical system dump capability alias identity text, or
            ``None`` when the requested value is unavailable.
        """
        canonical_identifier = cls._canonical_system_dump_device_identifier(
            diagnostic_type, identifier
        )
        if canonical_identifier != identifier:
            return canonical_identifier
        if diagnostic_type == "NetIR" and re.fullmatch(
            r"(?:NVLinkManagementNIC|NVSwitch)_\d+", identifier
        ):
            return identifier
        return None

    @classmethod
    def _deduplicate_system_dump_capability_aliases(
        cls,
        targets: List[Dict[str, str]],
        preferred_diagnostic_type: Optional[str] = None,
    ) -> List[Dict[str, str]]:
        """
        Return one advertised payload per physical alias-equivalent target.

        The implementation uses ``targets`` and ``preferred_diagnostic_type`` to
        produce one advertised payload per physical alias-equivalent target.

        Args:
            targets: Mapping supplying fields for one advertised payload per
                physical alias-equivalent target.
            preferred_diagnostic_type: Optional preferred diagnostic type;
                ``None`` selects the function's default behavior.

        Returns:
            The validated ``deduplicated``.
        """
        deduplicated: List[Dict[str, str]] = []
        index_by_identity: Dict[Tuple[str, str, str], int] = {}

        for raw_target in targets:
            target = dict(raw_target)
            canonical_identifier = cls._canonical_system_dump_device_identifier(
                target.get("diagnostic_type", ""),
                target.get("device_identifier", ""),
            )
            target["canonical_device_identifier"] = canonical_identifier
            filename_identifier = re.sub(
                r"[^A-Za-z0-9_.-]+", "_", canonical_identifier
            ).strip("_")
            target["filename_identifier"] = filename_identifier or "device"
            alias_identity = cls._system_dump_capability_alias_identity(
                target.get("diagnostic_type", ""),
                target.get("device_identifier", ""),
            )
            identity_token = alias_identity or (
                f"exact:{target.get('diagnostic_type', '')}:"
                f"{target.get('device_identifier', '')}"
            )
            identity = (
                target.get("system_id", ""),
                target.get("device_type", ""),
                identity_token,
            )
            existing_index = index_by_identity.get(identity)
            if existing_index is None:
                index_by_identity[identity] = len(deduplicated)
                deduplicated.append(target)
                continue

            existing = deduplicated[existing_index]
            candidate_is_preferred = (
                bool(preferred_diagnostic_type)
                and target.get("diagnostic_type") == preferred_diagnostic_type
            )
            existing_is_preferred = (
                bool(preferred_diagnostic_type)
                and existing.get("diagnostic_type") == preferred_diagnostic_type
            )
            if candidate_is_preferred and not existing_is_preferred:
                deduplicated[existing_index] = target

        return deduplicated

    @classmethod
    def _match_system_dump_capability_targets(
        cls,
        capability_snapshot: Any,
        system_ids: List[str],
        capability_targeting: Dict[str, Any],
        preferred_diagnostic_type: Optional[str] = None,
    ) -> Optional[
        Tuple[
            List[Dict[str, str]],
            Dict[str, List[str]],
            Dict[str, str],
        ]
    ]:
        """
        Return exact ActionInfo targets, or ``None`` for legacy fallback.

        Each selected System is resolved independently. Available Systems use
        their exact advertised action target, unsupported or invalid Systems are
        suppressed, and unavailable Systems remain eligible only for their own
        compatibility fallback. Returning ``None`` means no selected System had
        characterized capability evidence and preserves the all-legacy path.

        Args:
            capability_snapshot: Capability snapshot object whose ``get`` state
                is read while performing exact ActionInfo targets, or ``None``
                for legacy fallback.
            system_ids: Entries supplied as ``system_ids`` without transferring
                container ownership.
            capability_targeting: Mapping supplying fields for exact ActionInfo
                targets, or ``None`` for legacy fallback.
            preferred_diagnostic_type: Optional preferred diagnostic type;
                ``None`` selects the function's default behavior.

        Returns:
            A tuple containing deduplicated capability targets, ActionInfo values
            by characterized System, and per-System capability states. ``None``
            means capability discovery was unavailable for every selected System.
        """
        if not isinstance(capability_snapshot, dict):
            return None

        systems = capability_snapshot.get("systems")
        if not isinstance(systems, dict):
            return None
        rules = capability_targeting.get("selectors")
        logical_device_type = capability_targeting.get("device_type")
        if (
            not isinstance(rules, list)
            or not rules
            or not isinstance(logical_device_type, str)
            or not logical_device_type
        ):
            return None

        targets: List[Dict[str, str]] = []
        action_info_by_system: Dict[str, List[str]] = {}
        capability_state_by_system: Dict[str, str] = {}
        seen: set[Tuple[str, str]] = set()

        for system_id in system_ids:
            system = systems.get(system_id)
            if not isinstance(system, dict):
                capability_state_by_system[system_id] = "unavailable"
                continue
            system_status = system.get("status")
            if system_status == "unsupported":
                capability_state_by_system[system_id] = "unsupported"
                action_info_by_system[system_id] = []
                continue
            if system_status != "available":
                if system.get("action_target_state") == "invalid":
                    capability_state_by_system[system_id] = "invalid"
                    action_info_by_system[system_id] = []
                else:
                    capability_state_by_system[system_id] = "unavailable"
                continue

            raw_action_target = system.get("action_target_uri")
            if raw_action_target is None or raw_action_target == "":
                capability_state_by_system[system_id] = "unsupported"
                action_info_by_system[system_id] = []
                continue
            try:
                system_uri = validate_redfish_uri_path(
                    system.get("system_uri"),
                    context=f"System Dump capability URI for {system_id}",
                )
                action_target_uri = validate_redfish_uri_path(
                    system.get("action_target_uri"),
                    context=f"System Dump action target for {system_id}",
                    service_root=system_uri,
                )
            except (RedfishTopologyProfileError, TypeError, ValueError):
                capability_state_by_system[system_id] = "invalid"
                action_info_by_system[system_id] = []
                continue
            raw_values = system.get("oem_diagnostic_data_types", [])
            if not isinstance(raw_values, list):
                capability_state_by_system[system_id] = "invalid"
                action_info_by_system[system_id] = []
                continue
            values = [value for value in raw_values if isinstance(value, str)]
            capability_state_by_system[system_id] = "available"
            action_info_by_system[system_id] = values

            for exact_value in values:
                fields = cls._parse_oem_diagnostic_value(exact_value)
                diagnostic_type = fields.get("DiagnosticType")
                if not diagnostic_type:
                    continue

                for rule in rules:
                    if not isinstance(rule, dict):
                        continue
                    diagnostic_types = rule.get("diagnostic_types", [])
                    if isinstance(diagnostic_types, str):
                        diagnostic_types = [diagnostic_types]
                    if diagnostic_type not in diagnostic_types:
                        continue

                    identifier_keys = rule.get(
                        "identifier_keys", ["DeviceType", "DeviceID"]
                    )
                    if isinstance(identifier_keys, str):
                        identifier_keys = [identifier_keys]
                    identifier_key = next(
                        (
                            key
                            for key in identifier_keys
                            if isinstance(key, str) and fields.get(key) is not None
                        ),
                        None,
                    )
                    if identifier_key is None:
                        continue
                    identifier = fields[identifier_key]

                    identifier_patterns = rule.get("identifier_patterns", [])
                    if isinstance(identifier_patterns, str):
                        identifier_patterns = [identifier_patterns]
                    if identifier_patterns:
                        matched = False
                        for pattern in identifier_patterns:
                            if not isinstance(pattern, str):
                                continue
                            try:
                                if re.fullmatch(pattern, identifier):
                                    matched = True
                                    break
                            except re.error:
                                continue
                        if not matched:
                            continue

                    key = (system_id, exact_value)
                    if key in seen:
                        break
                    seen.add(key)
                    filename_identifier = re.sub(
                        r"[^A-Za-z0-9_.-]+", "_", identifier
                    ).strip("_")
                    targets.append(
                        {
                            "system_id": system_id,
                            "action_target_uri": action_target_uri,
                            "oem_diag_type": exact_value,
                            "diagnostic_type": diagnostic_type,
                            "device_type": logical_device_type,
                            "device_identifier": identifier,
                            "filename_identifier": filename_identifier or "device",
                        }
                    )
                    break

        if not any(
            state != "unavailable" for state in capability_state_by_system.values()
        ):
            return None

        return (
            cls._deduplicate_system_dump_capability_aliases(
                targets, preferred_diagnostic_type
            ),
            action_info_by_system,
            capability_state_by_system,
        )

    async def _get_system_dump_capability_targets(
        self,
        dut_id: str,
        system_ids: List[str],
        capability_targeting: Optional[Dict[str, Any]],
        preferred_diagnostic_type: Optional[str] = None,
    ) -> Optional[
        Tuple[
            List[Dict[str, str]],
            Dict[str, List[str]],
            Dict[str, str],
        ]
    ]:
        """
        Load the canonical R46 snapshot and select collector-owned targets.

        After applying local validation, the function forwards ``dut_id``,
        ``system_ids``, ``capability_targeting``, and
        ``preferred_diagnostic_type`` to
        ``self._match_system_dump_capability_targets`` and preserves its return
        and exception contract. Parsing or I/O must finish before the validated
        representation is made available to the caller. Owned asynchronous work
        is awaited before return, so completion does not leave an unobserved
        task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_ids: Entries supplied as ``system_ids`` without transferring
                container ownership.
            capability_targeting: Mapping supplying fields for canonical R46
                snapshot and select collector-owned targets.
            preferred_diagnostic_type: Optional preferred diagnostic type;
                ``None`` selects the function's default behavior.

        Returns:
            A tuple containing the fields that represent system dump capability
            targets, or ``None`` when the requested value is unavailable.
        """
        if not capability_targeting:
            return None
        get_capabilities = getattr(
            getattr(self, "orchestrator", None),
            "get_system_dump_capabilities",
            None,
        )
        if not callable(get_capabilities):
            return None
        try:
            snapshot = get_capabilities(dut_id)
            if inspect.isawaitable(snapshot):
                snapshot = await snapshot
            return self._match_system_dump_capability_targets(
                snapshot,
                system_ids,
                capability_targeting,
                preferred_diagnostic_type,
            )
        except Exception as exc:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"[ActionInfo] Failed to derive exact device targets: {exc}",
                dut_id,
            )
            return None

    async def _get_required_system_dump_capability_targets(
        self,
        dut_id: str,
        system_ids: List[str],
        capability_targeting: Optional[Dict[str, Any]],
        preferred_diagnostic_type: Optional[str] = None,
    ) -> Tuple[
        Optional[
            Tuple[
                List[Dict[str, str]],
                Dict[str, List[str]],
                Dict[str, str],
            ]
        ],
        Optional[str],
    ]:
        """
        Resolve targets only from a fresh complete canonical ActionInfo result.

        Unlike :meth:`_get_system_dump_capability_targets`, this helper never
        falls back to configured inventory-derived payloads. It is intended for
        collectors whose request contract is provisional: an explicit,
        authoritative advertisement is required before a diagnostic action may
        be sent. The canonical manager is force-refreshed here so an earlier
        run-scoped cache entry can never authorize this opt-in path.

        Returns the exact target resolution and ``None`` on success. A missing
        resolution is accompanied by a user-facing precondition failure reason.
        An authoritative resolution containing zero targets is successful and
        lets the caller distinguish unsupported firmware from unavailable
        capability discovery.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_ids: Entries supplied as ``system_ids`` without transferring
                container ownership.
            capability_targeting: Mapping supplying fields for targets only from
                a fresh complete canonical ActionInfo result.
            preferred_diagnostic_type: Optional preferred diagnostic type;
                ``None`` selects the function's default behavior.

        Returns:
            A tuple containing ``metadata mapping`` and ``status or message
            text`` in that order.
        """
        if not isinstance(capability_targeting, dict) or not capability_targeting:
            return None, (
                "Authoritative System Dump capability targeting is not configured"
            )

        orchestrator = getattr(self, "orchestrator", None)
        refresh_capabilities = getattr(
            orchestrator,
            "discover_system_dump_capabilities",
            None,
        )
        if not callable(refresh_capabilities):
            return None, (
                "Fresh authoritative System Dump capability discovery is unavailable "
                "for this run"
            )

        try:
            refreshed = refresh_capabilities(dut_ids=[dut_id], force=True)
            if inspect.isawaitable(refreshed):
                refreshed = await refreshed
        except Exception as exc:
            await self._log_runtime(
                "WARNING",
                "RedfishService",
                f"[ActionInfo] Fresh authoritative capability discovery failed: {exc}",
                dut_id,
            )
            return None, (
                f"Fresh authoritative System Dump capability discovery failed: {exc}"
            )

        if not isinstance(refreshed, dict) or dut_id not in refreshed:
            return None, (
                "Fresh authoritative System Dump capability discovery returned no "
                f"result for DUT {dut_id}"
            )
        snapshot = refreshed[dut_id]
        if not isinstance(snapshot, dict):
            return None, (
                "Fresh authoritative System Dump capability data is malformed"
            )
        if snapshot.get("source") != SYSTEM_DUMP_CAPABILITY_SOURCE:
            return None, ("Fresh System Dump capability data has an unexpected source")
        if snapshot.get("dut_id") != dut_id:
            return None, (
                "Fresh System Dump capability data does not match the requested DUT"
            )

        snapshot_status = str(snapshot.get("status", "unknown")).lower()
        if snapshot_status != "available":
            return None, (
                "Authoritative System Dump capability data is not available "
                f"(status={snapshot_status})"
            )
        if snapshot.get("authoritative") is not True:
            return None, (
                "System Dump capability data is not authoritative for this run"
            )

        systems = snapshot.get("systems")
        if not isinstance(systems, dict) or not systems:
            return None, (
                "Authoritative System Dump capability data has no per-System entries"
            )
        for system_id in system_ids:
            system = systems.get(system_id)
            if not isinstance(system, dict):
                return None, (
                    "Authoritative System Dump capability data is missing for "
                    f"System {system_id}"
                )
            if system.get("status") != "available":
                return None, (
                    f"System Dump capability data is unavailable for System {system_id}"
                )
            values = system.get("oem_diagnostic_data_types")
            if not isinstance(values, list) or not all(
                isinstance(value, str) for value in values
            ):
                return None, (
                    "Authoritative System Dump capability values are missing or "
                    f"malformed for System {system_id}"
                )

        resolution = self._match_system_dump_capability_targets(
            snapshot,
            system_ids,
            capability_targeting,
            preferred_diagnostic_type,
        )
        if resolution is None:
            return None, (
                "Authoritative System Dump capability targeting could not be resolved"
            )
        return resolution, None

    @staticmethod
    def _scan_stream_for_fixed_literals(
        member_stream: Any,
        literals: List[str],
        chunk_size: int,
    ) -> Tuple[set[str], int]:
        """
        Scan a binary stream completely for UTF-8 fixed strings.

        The overlap retains only enough bytes to detect a marker split across
        adjacent chunks. Continue to EOF even after every marker is found so an
        unreadable or truncated archive member cannot be accepted silently.

        Args:
            member_stream: Member stream object whose ``read`` state is read
                while performing scan a binary stream completely for UTF-8 fixed
                strings.
            literals: Entries supplied as ``literals`` without transferring
                container ownership.
            chunk_size: Numeric chunk size used by the operation's bounded
                accounting.

        Returns:
            A tuple containing ``found`` and ``bytes read`` in that order.

        Raises:
            OSError: If text member reader returned non-bytes content.
        """
        encoded_literals = {literal: literal.encode("utf-8") for literal in literals}
        found = {
            literal for literal, encoded in encoded_literals.items() if not encoded
        }
        overlap_size = max(
            (len(encoded) - 1 for encoded in encoded_literals.values()),
            default=0,
        )
        overlap_size = max(0, overlap_size)
        overlap = b""
        bytes_read = 0

        while True:
            chunk = member_stream.read(chunk_size)
            if chunk == b"":
                break
            if not isinstance(chunk, bytes):
                raise OSError("text member reader returned non-bytes content")

            bytes_read += len(chunk)
            scan_window = overlap + chunk
            for literal, encoded in encoded_literals.items():
                if literal not in found and encoded in scan_window:
                    found.add(literal)
            overlap = scan_window[-overlap_size:] if overlap_size else b""

        return found, bytes_read

    @staticmethod
    def _validate_tar_artifact_contents(
        output_files: List[str], validation_config: Dict[str, Any]
    ) -> List[str]:
        """
        Validate downloaded artifacts and, by default, their tar members.

        This is intentionally opt-in and limited to declarative checks that can
        be evaluated directly from the tar member table. No member is ever
        written to disk. Text members are scanned completely in bounded chunks;
        JSON members that exceed their configured materialization limit fail
        validation. ``archive_required=False`` limits validation to matching,
        existence, and minimum size so provisional collectors need not guess an
        artifact format.

        Catalogs may reject duplicate TAR members through the shared bounded
        inspector. Explicit ``non_tar_artifact_globs`` admit other formats
        already validated at publication; only existence and size checks apply
        to those files. Unmatched and missing artifacts remain errors.

        Args:
            output_files: Entries supplied as ``output_files`` without
                transferring container ownership.
            validation_config: Validation config governing downloaded artifacts
                and, by default, their tar members.

        Returns:
            The TAR artifact contents returned in operation-defined order.
        """
        archive_required = validation_config.get("archive_required", True)
        artifact_globs = validation_config.get("artifact_globs", ["*.tar*"])
        non_tar_artifact_globs = validation_config.get("non_tar_artifact_globs", [])
        reject_duplicate_members = validation_config.get(
            "reject_duplicate_members", False
        )
        minimum_size_bytes = validation_config.get("minimum_size_bytes", 0)
        required_nonempty_globs = validation_config.get(
            "required_nonempty_member_globs", []
        )
        text_error_literals = validation_config.get("text_member_error_literals", {})
        json_member_status_checks = validation_config.get(
            "json_member_status_checks", []
        )
        # Keep the historic configuration name for compatibility.  It controls
        # bounded scan memory, never how much of a text member is validated.
        text_scan_chunk_bytes = validation_config.get(
            "max_text_member_bytes", 64 * 1024
        )
        max_json_member_bytes = validation_config.get(
            "max_json_member_bytes", 8 * 1024 * 1024
        )

        if not isinstance(artifact_globs, list) or not all(
            isinstance(pattern, str) for pattern in artifact_globs
        ):
            return [
                "Invalid artifact validation config: artifact_globs must be a list of strings"
            ]
        if not isinstance(archive_required, bool):
            return [
                "Invalid artifact validation config: archive_required must be a boolean"
            ]
        if not isinstance(non_tar_artifact_globs, list) or not all(
            isinstance(pattern, str) for pattern in non_tar_artifact_globs
        ):
            return [
                "Invalid artifact validation config: non_tar_artifact_globs must be a list of strings"
            ]
        if not isinstance(reject_duplicate_members, bool):
            return [
                "Invalid artifact validation config: reject_duplicate_members must be a boolean"
            ]
        try:
            minimum_size_bytes = int(minimum_size_bytes)
        except (TypeError, ValueError):
            return [
                "Invalid artifact validation config: minimum_size_bytes must be an integer"
            ]
        if minimum_size_bytes < 0:
            return [
                "Invalid artifact validation config: minimum_size_bytes must be non-negative"
            ]
        if not archive_required:
            configured_member_rules = [
                key
                for key in (
                    "required_nonempty_member_globs",
                    "text_member_error_literals",
                    "json_member_status_checks",
                    "reject_duplicate_members",
                )
                if validation_config.get(key)
            ]
            if configured_member_rules:
                return [
                    "Invalid artifact validation config: tar-member rules cannot be "
                    "used when archive_required is false: "
                    + ", ".join(configured_member_rules)
                ]
        if archive_required and (
            not isinstance(required_nonempty_globs, list)
            or not all(isinstance(pattern, str) for pattern in required_nonempty_globs)
        ):
            return [
                "Invalid artifact validation config: required_nonempty_member_globs "
                "must be a list of strings"
            ]
        if archive_required and not isinstance(text_error_literals, dict):
            return [
                "Invalid artifact validation config: text_member_error_literals must be a mapping"
            ]
        if archive_required and (
            not isinstance(json_member_status_checks, list)
            or not all(isinstance(check, dict) for check in json_member_status_checks)
        ):
            return [
                "Invalid artifact validation config: json_member_status_checks "
                "must be a list of mappings"
            ]
        if archive_required:
            try:
                text_scan_chunk_bytes = int(text_scan_chunk_bytes)
            except (TypeError, ValueError):
                return [
                    "Invalid artifact validation config: max_text_member_bytes must be an integer"
                ]
            if text_scan_chunk_bytes <= 0:
                return [
                    "Invalid artifact validation config: max_text_member_bytes must be positive"
                ]
            try:
                max_json_member_bytes = int(max_json_member_bytes)
            except (TypeError, ValueError):
                return [
                    "Invalid artifact validation config: max_json_member_bytes must be an integer"
                ]
            if max_json_member_bytes <= 0:
                return [
                    "Invalid artifact validation config: max_json_member_bytes must be positive"
                ]

        for check in json_member_status_checks if archive_required else []:
            member_glob = check.get("member_glob")
            metadata_path = check.get("metadata_path")
            success_values = check.get(
                "success_values", ["success", "complete", "completed"]
            )
            configured_fields = [
                check.get("status_field", "collection_status"),
                check.get("incomplete_items_field"),
                check.get("label_field"),
                check.get("received_field"),
                check.get("expected_field"),
            ]
            if not isinstance(member_glob, str) or not member_glob:
                return [
                    "Invalid artifact validation config: each JSON status check "
                    "requires a non-empty member_glob"
                ]
            if not isinstance(metadata_path, str) or not metadata_path:
                return [
                    "Invalid artifact validation config: each JSON status check "
                    "requires a non-empty metadata_path"
                ]
            if (
                not isinstance(success_values, list)
                or not success_values
                or not all(isinstance(value, str) for value in success_values)
            ):
                return [
                    "Invalid artifact validation config: JSON status check "
                    "success_values must be a non-empty list of strings"
                ]
            if any(
                value is not None and not isinstance(value, str)
                for value in configured_fields
            ):
                return [
                    "Invalid artifact validation config: JSON status check field "
                    "names must be strings"
                ]

        normalized_text_error_literals: List[Tuple[str, List[str]]] = []
        for member_glob, configured_literals in (
            text_error_literals.items() if archive_required else []
        ):
            if not isinstance(member_glob, str):
                return [
                    "Invalid artifact validation config: text member glob must be a string"
                ]
            literals = (
                configured_literals
                if isinstance(configured_literals, list)
                else [configured_literals]
            )
            if not all(isinstance(literal, str) for literal in literals):
                return [
                    "Invalid artifact validation config: error literals for "
                    f"'{member_glob}' must be strings"
                ]
            normalized_text_error_literals.append((member_glob, literals))

        candidate_paths = [
            Path(path)
            for path in dict.fromkeys(output_files)
            if path
            and any(
                fnmatch.fnmatchcase(Path(path).name, pattern)
                for pattern in [*artifact_globs, *non_tar_artifact_globs]
            )
        ]
        if not candidate_paths:
            return [
                "No downloaded artifact matched configured globs: "
                + ", ".join([*artifact_globs, *non_tar_artifact_globs])
            ]

        def reject_duplicate(member: TarArchiveMember) -> None:
            """
            Refuse repeated canonical names before accepting the TAR artifact.

            The shared inspector owns normalization, complete content hashing,
            input bounds and source identity. This adds the collector's stricter
            uniqueness rule without rewriting or extracting the evidence.

            Args:
                member: Immutable metadata supplied by the bounded inspector.

            Raises:
                ArchivePolicyError: If a normalized member name was repeated.
            """

            if member.duplicate:
                raise ArchivePolicyError("duplicate_member")

        errors: List[str] = []
        for artifact_path in candidate_paths:
            if not artifact_path.is_file():
                errors.append(f"Artifact is missing or not a file: {artifact_path}")
                continue

            try:
                artifact_size = artifact_path.stat().st_size
            except OSError as exc:
                errors.append(
                    f"{artifact_path.name}: failed to read artifact size: {exc}"
                )
                continue
            if artifact_size < minimum_size_bytes:
                errors.append(
                    f"{artifact_path.name}: artifact is {artifact_size} bytes; "
                    f"minimum configured size is {minimum_size_bytes} bytes"
                )

            if not archive_required or any(
                fnmatch.fnmatchcase(artifact_path.name, pattern)
                for pattern in non_tar_artifact_globs
            ):
                continue

            required_matches = {
                member_glob: False for member_glob in required_nonempty_globs
            }
            text_matches = {
                member_glob: False
                for member_glob, _literals in normalized_text_error_literals
            }
            json_matches = [False] * len(json_member_status_checks)

            try:
                if reject_duplicate_members:
                    inspect_tar_archive_metadata(artifact_path, reject_duplicate)
                    if not (
                        required_nonempty_globs
                        or normalized_text_error_literals
                        or json_member_status_checks
                    ):
                        continue
                with tarfile.open(
                    artifact_path,
                    mode="r|*",
                    tarinfo=RedfishArtifactStore.bounded_tarinfo_type(),
                ) as archive:
                    for member in archive:
                        if not member.isfile():
                            continue

                        for member_glob in required_nonempty_globs:
                            if not fnmatch.fnmatchcase(member.name, member_glob):
                                continue
                            required_matches[member_glob] = True
                            if member.size == 0:
                                errors.append(
                                    f"{artifact_path.name}: member '{member.name}' is zero bytes"
                                )

                        matching_text_rules = [
                            (member_glob, literals)
                            for member_glob, literals in normalized_text_error_literals
                            if fnmatch.fnmatchcase(member.name, member_glob)
                        ]
                        for member_glob, _literals in matching_text_rules:
                            text_matches[member_glob] = True

                        matching_json_checks = [
                            (index, check)
                            for index, check in enumerate(json_member_status_checks)
                            if fnmatch.fnmatchcase(member.name, check["member_glob"])
                        ]
                        for index, _check in matching_json_checks:
                            json_matches[index] = True

                        if not matching_text_rules and not matching_json_checks:
                            continue

                        if matching_json_checks and member.size > max_json_member_bytes:
                            errors.append(
                                f"{artifact_path.name}: JSON member '{member.name}' "
                                f"exceeds {max_json_member_bytes} byte validation limit"
                            )
                            if not matching_text_rules:
                                continue

                        member_stream = archive.extractfile(member)
                        if member_stream is None:
                            if matching_text_rules:
                                errors.append(
                                    f"{artifact_path.name}: could not read text member "
                                    f"'{member.name}'"
                                )
                            if matching_json_checks:
                                errors.append(
                                    f"{artifact_path.name}: could not read JSON member "
                                    f"'{member.name}'"
                                )
                            continue

                        member_data: bytes | None = None
                        if (
                            matching_json_checks
                            and member.size <= max_json_member_bytes
                        ):
                            chunks: List[bytes] = []
                            bytes_read = 0
                            while bytes_read < member.size:
                                chunk = member_stream.read(
                                    min(64 * 1024, member.size - bytes_read)
                                )
                                if not chunk:
                                    break
                                chunks.append(chunk)
                                bytes_read += len(chunk)
                            if bytes_read != member.size:
                                errors.append(
                                    f"{artifact_path.name}: could not read complete "
                                    f"JSON member '{member.name}' (expected "
                                    f"{member.size} bytes, read {bytes_read})"
                                )
                                continue
                            member_data = b"".join(chunks)

                        if matching_text_rules:
                            text_stream = (
                                io.BytesIO(member_data)
                                if member_data is not None
                                else member_stream
                            )
                            literals = list(
                                dict.fromkeys(
                                    literal
                                    for _member_glob, rule_literals in matching_text_rules
                                    for literal in rule_literals
                                )
                            )
                            found_literals, text_bytes_read = (
                                RedfishService._scan_stream_for_fixed_literals(
                                    text_stream,
                                    literals,
                                    text_scan_chunk_bytes,
                                )
                            )
                            if text_bytes_read != member.size:
                                errors.append(
                                    f"{artifact_path.name}: could not read complete "
                                    f"text member '{member.name}' (expected "
                                    f"{member.size} bytes, read {text_bytes_read})"
                                )
                            for _member_glob, rule_literals in matching_text_rules:
                                for literal in rule_literals:
                                    if literal in found_literals:
                                        errors.append(
                                            f"{artifact_path.name}: member '{member.name}' "
                                            f"contains error marker '{literal}'"
                                        )

                        if not matching_json_checks or member_data is None:
                            continue
                        try:
                            decoded_member = json.loads(member_data)
                        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                            errors.append(
                                f"{artifact_path.name}: JSON member '{member.name}' "
                                f"could not be decoded: {exc}"
                            )
                            continue

                        for _index, check in matching_json_checks:
                            metadata: Any = decoded_member
                            for path_part in check["metadata_path"].split("."):
                                if not isinstance(metadata, dict):
                                    metadata = None
                                    break
                                metadata = metadata.get(path_part)
                            if not isinstance(metadata, dict):
                                errors.append(
                                    f"{artifact_path.name}: JSON member '{member.name}' "
                                    f"is missing metadata mapping '{check['metadata_path']}'"
                                )
                                continue

                            status_field = check.get(
                                "status_field", "collection_status"
                            )
                            status_value = metadata.get(status_field)
                            normalized_status = str(status_value or "").strip().lower()
                            success_values = {
                                value.strip().lower()
                                for value in check.get(
                                    "success_values",
                                    ["success", "complete", "completed"],
                                )
                            }
                            unhealthy = normalized_status not in success_values

                            incomplete_items_field = check.get("incomplete_items_field")
                            incomplete_items = (
                                metadata.get(incomplete_items_field)
                                if incomplete_items_field
                                else None
                            )
                            if incomplete_items:
                                unhealthy = True

                            received_field = check.get("received_field")
                            expected_field = check.get("expected_field")
                            received = (
                                metadata.get(received_field) if received_field else None
                            )
                            expected = (
                                metadata.get(expected_field) if expected_field else None
                            )
                            try:
                                if (
                                    received is not None
                                    and expected is not None
                                    and int(received) < int(expected)
                                ):
                                    unhealthy = True
                            except (TypeError, ValueError):
                                unhealthy = True

                            if not unhealthy:
                                continue

                            details = []
                            label_field = check.get("label_field")
                            if label_field and metadata.get(label_field) is not None:
                                details.append(f"{label_field}={metadata[label_field]}")
                            details.append(
                                f"{status_field}={status_value if status_value is not None else 'missing'}"
                            )
                            if received_field and expected_field:
                                details.append(
                                    f"events={received if received is not None else 'missing'}/"
                                    f"{expected if expected is not None else 'missing'}"
                                )
                            if incomplete_items_field and incomplete_items:
                                if isinstance(incomplete_items, list):
                                    rendered_items = ", ".join(
                                        str(item) for item in incomplete_items
                                    )
                                else:
                                    rendered_items = str(incomplete_items)
                                details.append(
                                    f"{incomplete_items_field}={rendered_items}"
                                )
                            errors.append(
                                f"{artifact_path.name}: JSON member '{member.name}' "
                                f"reports incomplete collection ({'; '.join(details)})"
                            )

                for member_glob, matched in required_matches.items():
                    if not matched:
                        errors.append(
                            f"{artifact_path.name}: required member matching "
                            f"'{member_glob}' is missing"
                        )
                for member_glob, matched in text_matches.items():
                    if not matched:
                        errors.append(
                            f"{artifact_path.name}: required text member matching "
                            f"'{member_glob}' is missing"
                        )
                for index, matched in enumerate(json_matches):
                    if not matched:
                        member_glob = json_member_status_checks[index]["member_glob"]
                        errors.append(
                            f"{artifact_path.name}: required JSON member matching "
                            f"'{member_glob}' is missing"
                        )
            except (OSError, tarfile.TarError, ValueError) as exc:
                errors.append(
                    f"{artifact_path.name}: failed tar content validation: {exc}"
                )

        return errors

    @staticmethod
    def _is_unattempted_blocked_dump_result(result: Dict[str, Any]) -> bool:
        """
        Recognize a diagnostic gate that prevented all artifact-producing work.

        Standardized skipped results have ``success=True``. That flag alone
        cannot establish that an archive was requested. Only a consistent typed
        pre-POST block with zero operations, no payload attempts, no outputs,
        and no errors may bypass artifact validation. Contradictory or missing
        accounting keeps the normal validation path active.

        Args:
            result: Standardized dump result to inspect without modifying it.

        Returns:
            Whether the result proves collection was blocked before any POST.
        """
        context = result.get("context")
        if not isinstance(context, dict):
            return False
        block = context.get("diagnostic_domain_block")
        if not isinstance(block, dict):
            return False

        payload_results = context.get("payload_results", [])
        empty_sources = (
            result.get("output_files"),
            context.get("output_files"),
            result.get("error_messages"),
            context.get("error_messages"),
            context.get("artifact_validation_errors"),
        )
        return bool(
            result.get("success") is True
            and result.get("status") == "skipped"
            and context.get("status") in (None, "skipped")
            and block.get("blocked_before_post") is True
            and block.get("post_sent") is False
            and block.get("resubmit_allowed") is False
            and type(context.get("successful_operations")) is int
            and context["successful_operations"] == 0
            and type(context.get("total_operations")) is int
            and context["total_operations"] == 0
            and type(payload_results) is list
            and not payload_results
            and all(
                source is None or (type(source) in {list, tuple} and not source)
                for source in empty_sources
            )
        )

    async def _apply_dump_artifact_validation(
        self,
        result: Dict[str, Any],
        validation_config: Optional[Dict[str, Any]],
    ) -> List[str]:
        """
        Apply opt-in dump validation and convert invalid content to partial.

        A proven zero-work diagnostic gate keeps its skipped result and origin
        reason because no archive was requested. Other success-bearing results
        are checked in the owned blocking worker, including partially completed
        collection and contradictory skips. Validation errors update the result
        and operation accounting in place; cancellation propagates to the caller.

        Args:
            result: Caller-owned standardized dump result to validate or retain
                unchanged when the pre-POST gate proves no work occurred.
            validation_config: Optional catalog rules for archive and content
                checks; absent rules disable this validation step.

        Returns:
            Validation errors, or an empty list when validation passes or does
            not apply to this result.
        """
        if not validation_config or not result.get("success", False):
            return []
        if self._is_unattempted_blocked_dump_result(result):
            return []

        context = result.setdefault("context", {})
        output_files = list(
            dict.fromkeys(
                result.get("output_files", []) + context.get("output_files", [])
            )
        )
        validation_errors = await self._run_blocking_redfish_operation(
            self._validate_tar_artifact_contents,
            output_files,
            validation_config,
        )
        if not validation_errors:
            return []

        successful_operations = int(context.get("successful_operations", 1))
        total_operations = max(
            successful_operations, int(context.get("total_operations", 1))
        )
        context["successful_operations"] = successful_operations
        context["total_operations"] = total_operations + 1
        context["status_list"] = [True] * successful_operations + [False] * (
            context["total_operations"] - successful_operations
        )
        context["artifact_validation_errors"] = validation_errors
        context["error_messages"] = list(
            dict.fromkeys(context.get("error_messages", []) + validation_errors)
        )
        result["status"] = "partial"
        result["success"] = False
        result["reason"] = (
            "Downloaded artifact failed content validation: "
            + "; ".join(validation_errors)
        )
        return validation_errors

    @staticmethod
    def _descriptor_selector_values(value: Any, field_name: str) -> List[str]:
        """
        Normalize one descriptor routing selector without coercion.

        The implementation uses ``value`` and ``field_name`` to normalize one
        descriptor routing selector without coercion. The source value keeps its
        ownership while the normalized representation is returned separately. If
        the function cannot normalize one descriptor routing selector without
        coercion, its exception reaches the caller instead of being converted
        into a successful result.

        Args:
            value: Value evaluated while performing one descriptor routing
                selector without coercion.
            field_name: Field label included in validation failures for the
                selected input.

        Returns:
            The descriptor selector values returned in operation-defined order.

        Raises:
            ValueError: If ``field_name`` must not be empty; or the
                ``field_name`` is not a string or list of non-empty strings.
        """

        if value is None:
            return []
        if isinstance(value, str):
            if not value:
                raise ValueError(f"{field_name} must not be empty")
            return [value]
        if not isinstance(value, (list, tuple)) or not all(
            isinstance(item, str) and item for item in value
        ):
            raise ValueError(
                f"{field_name} must be a string or list of non-empty strings"
            )
        return list(value)

    @staticmethod
    def _safe_descriptor_filename_identifier(identifier: str) -> str:
        """
        Project exact device identity into a collision-resistant filename.

        The implementation uses ``identifier`` to project exact device identity
        into a collision-resistant filename.

        Args:
            identifier: Text supplied as identifier in the format accepted by
                this function.

        Returns:
            The canonical safe descriptor filename identifier text.
        """

        safe_value = re.sub(r"[^A-Za-z0-9_.-]+", "_", identifier).strip("._-")
        if safe_value == identifier and len(safe_value) <= 96:
            return safe_value
        digest = hashlib.sha256(identifier.encode("utf-8")).hexdigest()[:12]
        prefix = safe_value[:80].rstrip("._-") or "device"
        return f"{prefix}-{digest}"

    @classmethod
    def _descriptor_matches_task_config(
        cls,
        descriptor: DeviceDescriptor,
        system_id: str,
        task_config: Dict[str, Any],
    ) -> Tuple[bool, str]:
        """
        Apply generic family, identity, system, and routing selectors.

        The implementation uses ``descriptor``, ``system_id``, and
        ``task_config`` to apply generic family, identity, system, and routing
        selectors. If the function cannot apply generic family, identity,
        system, and routing selectors, its exception reaches the caller instead
        of being converted into a successful result.

        Args:
            descriptor: Descriptor object whose ``family``, ``get``,
                ``identifier``, ``routing_hints``, and ``system_hints`` state is
                read while performing apply generic family, identity, system,
                and routing selectors.
            system_id: Stable system identifier used to correlate configuration,
                logs, and results.
            task_config: Task config governing apply generic family, identity,
                system, and routing selectors.

        Returns:
            A tuple containing ``success flag`` and ``status or message text``
            in that order.

        Raises:
            ValueError: If invalid identifier_patterns: ``exc``; the
                routing_hints are not a mapping; or the routing_hints keys are
                not non-empty strings.
        """

        if descriptor.system_hints and not any(
            fnmatch.fnmatchcase(system_id, hint) for hint in descriptor.system_hints
        ):
            return False, f"{descriptor.identifier} does not route to {system_id}"

        families = cls._descriptor_selector_values(
            task_config.get("families"),
            "families",
        )
        if families and descriptor.family not in families:
            return (
                False,
                f"{descriptor.identifier} family {descriptor.family} is not selected",
            )

        identifier_patterns = cls._descriptor_selector_values(
            task_config.get("identifier_patterns"),
            "identifier_patterns",
        )
        try:
            if identifier_patterns and not any(
                re.fullmatch(pattern, descriptor.identifier)
                for pattern in identifier_patterns
            ):
                return (
                    False,
                    f"{descriptor.identifier} does not match identifier_patterns",
                )
        except re.error as exc:
            raise ValueError(f"invalid identifier_patterns: {exc}") from exc

        requested_hints = task_config.get("routing_hints", {})
        if not isinstance(requested_hints, dict):
            raise ValueError("routing_hints must be a mapping")
        for key, expected_value in requested_hints.items():
            if not isinstance(key, str) or not key:
                raise ValueError("routing_hints keys must be non-empty strings")
            expected = set(
                cls._descriptor_selector_values(
                    expected_value,
                    f"routing_hints.{key}",
                )
            )
            actual = set(
                cls._descriptor_selector_values(
                    descriptor.routing_hints.get(key),
                    f"descriptor routing_hints.{key}",
                )
            )
            if expected and not expected.intersection(actual):
                return (
                    False,
                    f"{descriptor.identifier} routing hint {key} is not selected",
                )
        return True, ""

    @staticmethod
    def _coalesce_system_dump_device_tasks(
        device_tasks: List[Dict[str, Any]],
        action_info_values: List[str],
        default_artifact_validation: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        """
        Represent unadvertised device dumps through a checked system-level dump.

        Only a configured fallback to an already planned, exactly advertised
        system dump can replace an individual task. Each replaced descriptor
        adds a mandatory nonempty member pattern to that dump's existing TAR
        validation. Missing capability, an advertised individual action or an
        absent fallback task retains the original task. Legacy numeric discovery
        also retains its individual task when no named descriptor is available;
        malformed policies or explicitly present non-mapping descriptors are
        errors.
        No request is issued or result marked successful by this planning step.

        Args:
            device_tasks: Validated tasks for one exact System.
            action_info_values: That System's observed diagnostic payload values.
            default_artifact_validation: Collector-level artifact rules inherited
                when the selected system task has no specific validation policy.

        Returns:
            An owned task list whose system dumps carry all required device
            member checks. The caller's task and configuration objects are intact.

        Raises:
            ValueError: If a configured fallback is malformed, ambiguous, or
                would bypass required archive-member validation.
        """

        if not any(
            isinstance(task.get("device_config"), dict)
            and task["device_config"].get("system_dump_fallback") is not None
            for task in device_tasks
        ):
            return list(device_tasks)
        tasks = copy.deepcopy(device_tasks)
        replaced: set[int] = set()
        for index, task in enumerate(tasks):
            config = task.get("device_config", {})
            fallback = config.get("system_dump_fallback")
            descriptor = task.get("device_descriptor")
            if fallback is None:
                continue
            if not isinstance(fallback, dict):
                raise ValueError("system_dump_fallback must be a mapping")
            target_type = fallback.get("device_type")
            diagnostic_type = fallback.get("diagnostic_type")
            template = fallback.get("required_member_template")
            if (
                not isinstance(target_type, str)
                or not target_type
                or not isinstance(diagnostic_type, str)
                or not diagnostic_type
                or not isinstance(template, str)
                or len(template) > 4096
                or template.count("{identifier}") != 1
                or "{" in template.replace("{identifier}", "")
                or "}" in template.replace("{identifier}", "")
            ):
                raise ValueError(
                    "Invalid system_dump_fallback target or member template"
                )
            if "device_descriptor" not in task:
                # Numeric discovery is a supported builder output. It supplies
                # no exact named identity to prove system-archive coverage.
                continue
            if not isinstance(descriptor, dict):
                raise ValueError(
                    "system_dump_fallback requires a valid device_descriptor mapping"
                )
            if (
                not action_info_values
                or task.get("oem_diag_type") in action_info_values
                or task.get("is_in_action_info") is not False
            ):
                continue
            candidates = [
                candidate
                for candidate in tasks
                if candidate.get("device_type") == target_type
                and candidate.get("diagnostic_type") == diagnostic_type
                and candidate.get("is_in_action_info") is True
                and candidate.get("oem_diag_type") in action_info_values
                and "device_descriptor" not in candidate
            ]
            if not candidates:
                continue
            if len(candidates) != 1:
                raise ValueError("Ambiguous advertised system_dump_fallback target")
            parent = candidates[0]
            identifier = descriptor.get("identifier")
            if (
                not isinstance(identifier, str)
                or not identifier
                or len(identifier) > 1024
            ):
                raise ValueError("Invalid system_dump_fallback device identifier")
            member_glob = template.format(identifier=glob.escape(identifier))
            if len(member_glob) > 4096:
                raise ValueError(
                    "system_dump_fallback member pattern exceeds its bound"
                )
            # YAML anchors can share this policy with an individual task that
            # remains planned. Its validation must not acquire sibling rules.
            parent_config = copy.deepcopy(parent.get("device_config", {}))
            parent["device_config"] = parent_config
            validation = copy.deepcopy(
                parent_config.get("artifact_validation")
                or default_artifact_validation
                or {}
            )
            if (
                not isinstance(validation, dict)
                or validation.get("archive_required", True) is not True
            ):
                raise ValueError("system_dump_fallback requires archive validation")
            required = validation.get("required_nonempty_member_globs", [])
            if not isinstance(required, list) or not all(
                isinstance(value, str) for value in required
            ):
                raise ValueError(
                    "Invalid system_dump_fallback member validation policy"
                )
            validation["required_nonempty_member_globs"] = list(
                dict.fromkeys([*required, member_glob])
            )
            parent_config["artifact_validation"] = validation
            parent.setdefault("system_dump_member_requirements", []).append(
                {
                    "device_type": task["device_type"],
                    "identifier": identifier,
                    "required_member_glob": member_glob,
                }
            )
            replaced.add(index)
        return [task for index, task in enumerate(tasks) if index not in replaced]

    @staticmethod
    def _is_affirmative_capability_no_post_child(
        result: Any,
        system_id: str,
    ) -> bool:
        """
        Return whether a child proves a capability-filtered no-POST outcome.

        Artifact validation is meaningful only after an attempted diagnostic
        request can produce an artifact. A capability-filtered child may bypass
        that validation only when its standardized result consistently reports
        success-as-skip, zero operations, no payload attempts, no outputs, and
        no errors for the exact System. Any malformed or contradictory field
        fails closed and leaves the normal validation path authoritative.

        Args:
            result: Child diagnostic result considered for the no-POST
                exception.
            system_id: Exact System identifier that the capability evidence
                must name.

        Returns:
            Whether ``result`` contains affirmative, internally consistent
            capability evidence that no diagnostic POST was sent.
        """
        if type(result) is not dict:
            return False
        context = result.get("context")
        if type(context) is not dict:
            return False

        context_status = context.get("status")
        capability_skipped_entities = context.get("capability_skipped_entities")
        payload_results = context.get("payload_results")
        output_sources = (
            result.get("output_files"),
            context.get("output_files"),
        )
        error_sources = (
            result.get("error_messages"),
            context.get("error_messages"),
            context.get("artifact_validation_errors"),
        )
        return bool(
            result.get("success") is True
            and result.get("status") == "skipped"
            and (context_status is None or context_status == "skipped")
            and type(context.get("successful_operations")) is int
            and context.get("successful_operations") == 0
            and type(context.get("total_operations")) is int
            and context.get("total_operations") == 0
            and type(payload_results) is list
            and not payload_results
            and type(capability_skipped_entities) is list
            and system_id in capability_skipped_entities
            and context.get("diagnostic_domain_block") is None
            and all(
                source is None or (type(source) in {list, tuple} and not source)
                for source in output_sources
            )
            and all(
                source is None or (type(source) in {list, tuple} and not source)
                for source in error_sources
            )
        )

    @staticmethod
    async def _await_owned_device_task_results(
        tasks: List[asyncio.Task[Dict[str, Any]]],
    ) -> List[Dict[str, Any]]:
        """
        Await every owned adaptive device task and preserve cancellation.

        ``asyncio.gather`` is used with exception collection so one local child
        failure cannot leave a sibling running unobserved. The first observed
        exception is re-raised only after every sibling has reached a terminal
        local state. Caller cancellation explicitly cancels and drains all
        children before it propagates.

        Args:
            tasks: Owned asynchronous device-task handles to observe.

        Returns:
            Device task results in the same order as ``tasks``.

        Raises:
            BaseException: Re-raises a child failure after all siblings have
                been observed, including cooperative cancellation.

        Side Effects:
            Cancels and drains the supplied tasks when the caller is cancelled.
        """

        if not tasks:
            return []
        try:
            gathered = await asyncio.gather(*tasks, return_exceptions=True)
        except asyncio.CancelledError:
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            raise
        for result in gathered:
            if isinstance(result, BaseException):
                raise result
        return gathered

    async def _run_adaptive_device_task(
        self,
        *,
        dut_id: str,
        system_id: str,
        device_task: Dict[str, Any],
        action_info_values: List[str],
        use_action_info_validation: bool,
        collector_name: str,
        collector_id: str,
        kwargs: Dict[str, Any],
        attempt: DiagnosticParallelAttempt,
    ) -> Dict[str, Any]:
        """
        Execute one device through the established single-task result path.

        The existing sequential helper remains authoritative for payload
        construction, artifact validation, status metadata, and diagnostic
        domain evidence. Supplying one task prevents inter-device sleep while
        the opaque prepared attempt lets the runner admit this lifecycle inside
        the exclusively held adaptive session.

        Args:
            dut_id: Stable DUT identifier used for configuration and I/O.
            system_id: Redfish System that owns the diagnostic action.
            device_task: Fully built device diagnostic task mapping.
            action_info_values: Advertised diagnostic values for the System.
            use_action_info_validation: Whether ActionInfo metadata is active.
            collector_name: Stable operator-facing collector name.
            collector_id: Stable collector identifier for artifact ownership.
            kwargs: Original collector hook context forwarded to the child.
            attempt: Prepared adaptive child attempt owned by the runner.

        Returns:
            The one normalized device task result.

        Raises:
            RuntimeError: If the established helper does not return exactly one
                result for the supplied single task.

        Side Effects:
            May issue one diagnostic lifecycle and always resolves the attempt's
            creation event before returning or propagating an exception.
        """

        child_kwargs = dict(kwargs)
        child_kwargs["_diagnostic_parallel_attempt"] = attempt
        try:
            results = await self._collect_for_system(
                dut_id=dut_id,
                system_id=system_id,
                device_tasks=[device_task],
                action_info_values=action_info_values,
                use_action_info_validation=use_action_info_validation,
                collector_name=collector_name,
                collector_id=collector_id,
                kwargs=child_kwargs,
                adaptive_parallel=False,
                max_concurrent_device_tasks=1,
            )
        finally:
            self._diagnostic_runner().finalize_parallel_attempt_creation(attempt)
        if len(results) != 1:
            raise RuntimeError(
                "adaptive device execution did not return exactly one result"
            )
        return results[0]

    @staticmethod
    def _device_task_closes_diagnostic_domain(result: Dict[str, Any]) -> bool:
        """
        Return whether a typed child result forbids another diagnostic POST.

        Only the structured disposition produced by the diagnostic runner is
        considered. Human-readable error text and outer success booleans cannot
        close or reopen the domain at this scheduling boundary.

        Args:
            result: Normalized device task result containing optional domain
                block evidence.

        Returns:
            Whether the result carries a no-resubmit diagnostic-domain block.
        """

        block = result.get("diagnostic_domain_block")
        return bool(isinstance(block, dict) and block.get("resubmit_allowed") is False)

    async def _sleep_between_device_diagnostic_tasks(
        self,
        *,
        dut_id: str,
        system_id: str,
        collector_id: str,
        kwargs: Dict[str, Any],
    ) -> None:
        """
        Apply the established configured delay before the next serial task.

        Adaptive fallback uses the same per-DUT precedence and asynchronous
        pacing contract as the original serial device loop. No delay is added
        after the final target because the caller invokes this helper only when
        another serial attempt is about to start.

        Args:
            dut_id: Stable DUT identifier used to resolve configuration.
            system_id: Redfish System used for operator-facing diagnostics.
            collector_id: Stable collector identifier used for timing lookup.
            kwargs: Collector context containing authored definition metadata.

        Side Effects:
            Emits a runtime log record and asynchronously sleeps for the
            configured nonnegative inter-device duration.
        """

        collector_def = kwargs.get("collector_def", {})
        dut_config = self.dut_manager.get_dut_config(dut_id)
        sleep_duration = get_collector_sleep_duration(
            kwargs.get("collector_id", collector_id),
            collector_def,
            dut_config,
            5,
        )
        await self._log_runtime(
            "DEBUG",
            "RedfishService",
            f"[AdaptiveParallel] System {system_id}: Sleeping "
            f"{sleep_duration}s before the next serial device dump",
            dut_id,
        )
        await asyncio.sleep(sleep_duration)

    async def _collect_for_system_adaptive(
        self,
        *,
        dut_id: str,
        system_id: str,
        device_tasks: List[Dict[str, Any]],
        action_info_values: List[str],
        use_action_info_validation: bool,
        collector_name: str,
        collector_id: str,
        kwargs: Dict[str, Any],
        max_concurrent_device_tasks: int,
    ) -> List[Dict[str, Any]]:
        """
        Probe device concurrency and retry rejected creation serially.

        Task zero is created first. Only after firmware returns a validated task
        reference is task one admitted while task zero remains in flight. A
        catalog-authorized diagnostic scope expands the same initial window up
        to the configured limit as soon as task one's creation is accepted;
        unscoped platforms wait for both probe lifecycles before expanding. An
        exact structured ``ResourceInUse`` or create-limit rejection proves the
        attempted task was not created; after every accepted sibling reaches a
        proven terminal state, that target and all unstarted targets are retried
        serially. Payload errors, transport failures, and malformed task
        responses are never reclassified as a firmware capability signal.

        Args:
            dut_id: Stable DUT identifier used for configuration and I/O.
            system_id: Redfish System that owns the diagnostic action.
            device_tasks: Fully built tasks in deterministic target order.
            action_info_values: Advertised diagnostic values for the System.
            use_action_info_validation: Whether ActionInfo metadata is active.
            collector_name: Stable operator-facing collector name.
            collector_id: Stable collector identifier for artifact ownership.
            kwargs: Original collector hook context forwarded to each child.
            max_concurrent_device_tasks: Bounded number of overlapping device
                lifecycles admitted after initial task-creation proof.

        Returns:
            Final per-target results in original device order. Expected rejected
            probes are replaced by their serial retry results.

        Side Effects:
            Owns spawned tasks, diagnostic-domain session state, remote Redfish
            lifecycles, runtime logs, and configured serial fallback sleeps.
        """

        runner = self._diagnostic_runner()
        results_by_index: Dict[int, Dict[str, Any]] = {}
        rejection_by_index: Dict[int, str] = {}
        retry_indexes: List[int] = []
        gated_remaining_start: Optional[int] = None
        session_unavailable = False
        stop_remaining = False
        diagnostic_scope = kwargs.get("_diagnostic_domain_scope")
        scoped_initial_fanout = bool(
            isinstance(diagnostic_scope, str) and diagnostic_scope.strip()
        )

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"[AdaptiveParallel] Probing device concurrency for system "
            f"{system_id} with {len(device_tasks)} tasks "
            f"(max_concurrent={max_concurrent_device_tasks}, "
            f"scoped_initial_fanout={scoped_initial_fanout})",
            dut_id,
        )

        async with runner.parallel_diagnostic_session(
            dut_id,
            diagnostic_domain_scope=kwargs.get("_diagnostic_domain_scope"),
        ) as session:
            if session is None:
                session_unavailable = True
            else:
                first_attempt = runner.prepare_parallel_attempt(session, "probe-0")
                first_task = asyncio.create_task(
                    self._run_adaptive_device_task(
                        dut_id=dut_id,
                        system_id=system_id,
                        device_task=device_tasks[0],
                        action_info_values=action_info_values,
                        use_action_info_validation=use_action_info_validation,
                        collector_name=collector_name,
                        collector_id=collector_id,
                        kwargs=kwargs,
                        attempt=first_attempt,
                    )
                )
                try:
                    await first_attempt.creation_resolved.wait()
                except asyncio.CancelledError:
                    first_task.cancel()
                    await asyncio.gather(first_task, return_exceptions=True)
                    raise

                first_creation_accepted, _ = runner.parallel_attempt_creation_outcome(
                    first_attempt
                )
                if first_creation_accepted is not True:
                    first_result = (
                        await self._await_owned_device_task_results([first_task])
                    )[0]
                    first_result["device_task_execution_mode"] = (
                        "adaptive_probe_unavailable"
                    )
                    results_by_index[0] = first_result
                    if not runner.parallel_attempt_is_quiescent(first_attempt):
                        gated_remaining_start = 1
                    elif not self._device_task_closes_diagnostic_domain(first_result):
                        retry_indexes = list(range(1, len(device_tasks)))
                else:
                    second_attempt = runner.prepare_parallel_attempt(
                        session,
                        "probe-1",
                    )
                    second_task = asyncio.create_task(
                        self._run_adaptive_device_task(
                            dut_id=dut_id,
                            system_id=system_id,
                            device_task=device_tasks[1],
                            action_info_values=action_info_values,
                            use_action_info_validation=use_action_info_validation,
                            collector_name=collector_name,
                            collector_id=collector_id,
                            kwargs=kwargs,
                            attempt=second_attempt,
                        )
                    )
                    try:
                        await second_attempt.creation_resolved.wait()
                    except asyncio.CancelledError:
                        first_task.cancel()
                        second_task.cancel()
                        await asyncio.gather(
                            first_task,
                            second_task,
                            return_exceptions=True,
                        )
                        raise

                    second_creation_accepted, second_rejection = (
                        runner.parallel_attempt_creation_outcome(second_attempt)
                    )
                    initial_indexes = [0, 1]
                    initial_attempts = [first_attempt, second_attempt]
                    initial_tasks = [first_task, second_task]
                    if (
                        second_creation_accepted is True
                        and scoped_initial_fanout
                        and max_concurrent_device_tasks > 2
                    ):
                        initial_indexes.extend(
                            range(
                                2,
                                min(
                                    len(device_tasks),
                                    max_concurrent_device_tasks,
                                ),
                            )
                        )
                        initial_attempts.extend(
                            runner.prepare_parallel_attempt(
                                session,
                                f"parallel-{index}",
                            )
                            for index in initial_indexes[2:]
                        )
                        initial_tasks.extend(
                            asyncio.create_task(
                                self._run_adaptive_device_task(
                                    dut_id=dut_id,
                                    system_id=system_id,
                                    device_task=device_tasks[index],
                                    action_info_values=action_info_values,
                                    use_action_info_validation=(
                                        use_action_info_validation
                                    ),
                                    collector_name=collector_name,
                                    collector_id=collector_id,
                                    kwargs=kwargs,
                                    attempt=attempt,
                                )
                            )
                            for index, attempt in zip(
                                initial_indexes[2:],
                                initial_attempts[2:],
                            )
                        )

                    initial_results = await self._await_owned_device_task_results(
                        initial_tasks
                    )
                    for index, result in zip(initial_indexes, initial_results):
                        result["device_task_execution_mode"] = "adaptive_parallel"
                        results_by_index[index] = result

                    accepted_probe_domain_open = not (
                        self._device_task_closes_diagnostic_domain(initial_results[0])
                    )
                    if (
                        second_rejection
                        and accepted_probe_domain_open
                        and runner.dismiss_parallel_creation_rejections(
                            session,
                            [second_attempt],
                        )
                    ):
                        results_by_index.pop(1, None)
                        rejection_by_index[1] = second_rejection
                        retry_indexes = list(range(1, len(device_tasks)))
                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            f"[AdaptiveParallel] System {system_id} rejected the "
                            "second concurrent task creation; switching remaining "
                            "device dumps to serial execution",
                            dut_id,
                        )
                    else:
                        initial_outcomes = [
                            runner.parallel_attempt_creation_outcome(attempt)
                            for attempt in initial_attempts
                        ]
                        rejected_initial = [
                            (index, attempt, rejection)
                            for index, attempt, (_, rejection) in zip(
                                initial_indexes,
                                initial_attempts,
                                initial_outcomes,
                            )
                            if index > 1 and rejection
                        ]
                        accepted_initial = any(
                            accepted is True for accepted, _ in initial_outcomes
                        )
                        accepted_initial_domain_open = not any(
                            accepted is True
                            and self._device_task_closes_diagnostic_domain(result)
                            for result, (accepted, _) in zip(
                                initial_results,
                                initial_outcomes,
                            )
                        )
                        rejected_attempts = [
                            attempt for _, attempt, _ in rejected_initial
                        ]
                        if (
                            rejected_attempts
                            and accepted_initial
                            and accepted_initial_domain_open
                            and all(
                                accepted is True or bool(rejection)
                                for accepted, rejection in initial_outcomes
                            )
                            and runner.dismiss_parallel_creation_rejections(
                                session,
                                rejected_attempts,
                            )
                        ):
                            for index, _, rejection in rejected_initial:
                                results_by_index.pop(index, None)
                                rejection_by_index[index] = str(rejection)
                            retry_indexes = [
                                index for index, _, _ in rejected_initial
                            ] + list(range(initial_indexes[-1] + 1, len(device_tasks)))
                            await self._log_runtime(
                                "WARN",
                                "RedfishService",
                                f"[AdaptiveParallel] System {system_id} reached "
                                "a firmware task-creation limit during initial "
                                "fan-out; switching rejected and unstarted "
                                "device dumps to serial execution",
                                dut_id,
                            )
                        elif any(
                            not runner.parallel_attempt_is_quiescent(attempt)
                            for attempt in initial_attempts
                        ) or any(
                            self._device_task_closes_diagnostic_domain(result)
                            for result in initial_results
                        ):
                            gated_remaining_start = initial_indexes[-1] + 1
                        elif any(
                            accepted is not True for accepted, _ in initial_outcomes
                        ):
                            # Only an exact structured capacity rejection can
                            # authorize serial continuation. An unclassified
                            # creation failure stops this collector fail closed.
                            stop_remaining = True

                next_index = (
                    initial_indexes[-1] + 1 if first_creation_accepted is True else 1
                )
                while (
                    not retry_indexes
                    and gated_remaining_start is None
                    and not stop_remaining
                    and next_index < len(device_tasks)
                ):
                    batch_indexes = list(
                        range(
                            next_index,
                            min(
                                len(device_tasks),
                                next_index + max_concurrent_device_tasks,
                            ),
                        )
                    )
                    batch_attempts = [
                        runner.prepare_parallel_attempt(
                            session,
                            f"parallel-{index}",
                        )
                        for index in batch_indexes
                    ]
                    batch_tasks = [
                        asyncio.create_task(
                            self._run_adaptive_device_task(
                                dut_id=dut_id,
                                system_id=system_id,
                                device_task=device_tasks[index],
                                action_info_values=action_info_values,
                                use_action_info_validation=(use_action_info_validation),
                                collector_name=collector_name,
                                collector_id=collector_id,
                                kwargs=kwargs,
                                attempt=attempt,
                            )
                        )
                        for index, attempt in zip(batch_indexes, batch_attempts)
                    ]
                    batch_results = await self._await_owned_device_task_results(
                        batch_tasks
                    )
                    for index, result in zip(batch_indexes, batch_results):
                        result["device_task_execution_mode"] = "adaptive_parallel"
                        results_by_index[index] = result

                    batch_outcomes = [
                        runner.parallel_attempt_creation_outcome(attempt)
                        for attempt in batch_attempts
                    ]
                    rejected_pairs = [
                        (index, attempt, rejection)
                        for index, attempt, (_, rejection) in zip(
                            batch_indexes,
                            batch_attempts,
                            batch_outcomes,
                        )
                        if rejection
                    ]
                    accepted_in_batch = any(
                        accepted is True for accepted, _ in batch_outcomes
                    )
                    accepted_batch_domain_open = not any(
                        accepted is True
                        and self._device_task_closes_diagnostic_domain(result)
                        for result, (accepted, _) in zip(
                            batch_results,
                            batch_outcomes,
                        )
                    )
                    rejected_attempts = [attempt for _, attempt, _ in rejected_pairs]
                    if (
                        rejected_attempts
                        and accepted_in_batch
                        and accepted_batch_domain_open
                        and runner.dismiss_parallel_creation_rejections(
                            session,
                            rejected_attempts,
                        )
                    ):
                        for index, _, rejection in rejected_pairs:
                            results_by_index.pop(index, None)
                            rejection_by_index[index] = str(rejection)
                        retry_indexes = [
                            index for index, _, _ in rejected_pairs
                        ] + list(range(batch_indexes[-1] + 1, len(device_tasks)))
                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            f"[AdaptiveParallel] System {system_id} reached a "
                            "firmware task-creation limit; switching rejected and "
                            "unstarted device dumps to serial execution",
                            dut_id,
                        )
                        break

                    if any(
                        not runner.parallel_attempt_is_quiescent(attempt)
                        for attempt in batch_attempts
                    ) or any(
                        self._device_task_closes_diagnostic_domain(result)
                        for result in batch_results
                    ):
                        gated_remaining_start = batch_indexes[-1] + 1
                        break
                    next_index = batch_indexes[-1] + 1

                for serial_position, index in enumerate(retry_indexes):
                    if results_by_index or serial_position:
                        await self._sleep_between_device_diagnostic_tasks(
                            dut_id=dut_id,
                            system_id=system_id,
                            collector_id=collector_id,
                            kwargs=kwargs,
                        )
                    attempt = runner.prepare_parallel_attempt(
                        session,
                        f"serial-{index}",
                    )
                    result = await self._run_adaptive_device_task(
                        dut_id=dut_id,
                        system_id=system_id,
                        device_task=device_tasks[index],
                        action_info_values=action_info_values,
                        use_action_info_validation=use_action_info_validation,
                        collector_name=collector_name,
                        collector_id=collector_id,
                        kwargs=kwargs,
                        attempt=attempt,
                    )
                    result["device_task_execution_mode"] = "serial_fallback"
                    result["adaptive_parallel_serial_fallback"] = True
                    if index in rejection_by_index:
                        result["parallel_creation_rejection_message_id"] = (
                            rejection_by_index[index]
                        )
                    results_by_index[index] = result
                    if not runner.parallel_attempt_is_quiescent(
                        attempt
                    ) or self._device_task_closes_diagnostic_domain(result):
                        remaining_indexes = retry_indexes[serial_position + 1 :]
                        if remaining_indexes:
                            gated_remaining_start = remaining_indexes[0]
                        break

        if session_unavailable:
            return await self._collect_for_system(
                dut_id=dut_id,
                system_id=system_id,
                device_tasks=device_tasks,
                action_info_values=action_info_values,
                use_action_info_validation=use_action_info_validation,
                collector_name=collector_name,
                collector_id=collector_id,
                kwargs=kwargs,
                adaptive_parallel=False,
                max_concurrent_device_tasks=1,
            )

        if gated_remaining_start is not None and gated_remaining_start < len(
            device_tasks
        ):
            gated_results = await self._collect_for_system(
                dut_id=dut_id,
                system_id=system_id,
                device_tasks=device_tasks[gated_remaining_start:],
                action_info_values=action_info_values,
                use_action_info_validation=use_action_info_validation,
                collector_name=collector_name,
                collector_id=collector_id,
                kwargs=kwargs,
                adaptive_parallel=False,
                max_concurrent_device_tasks=1,
            )
            for index, result in enumerate(
                gated_results,
                start=gated_remaining_start,
            ):
                results_by_index[index] = result

        return [results_by_index[index] for index in sorted(results_by_index)]

    async def _collect_for_system(
        self,
        dut_id: str,
        system_id: str,
        device_tasks: List[Dict[str, Any]],
        action_info_values: List[str],
        use_action_info_validation: bool,
        collector_name: str,
        collector_id: str,
        kwargs: Dict[str, Any],
        adaptive_parallel: bool = False,
        max_concurrent_device_tasks: int = 1,
    ) -> List[Dict[str, Any]]:
        """
        Collect diagnostic data for a single system using its configured mode.

        This helper method keeps the established serial behavior unless the
        caller opts into adaptive parallel collection. The adaptive path starts
        a second device lifecycle only after the first task is accepted. A
        validated catalog scope may then fill the initial concurrency window
        without waiting for those probe lifecycles to finish; other platforms
        retain the conservative post-probe fan-out. Structured firmware
        capacity rejection triggers bounded serial fallback.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_id: Stable system identifier used to correlate configuration,
                logs, and results.
            device_tasks: Ordered device diagnostic task definitions for the
                selected system.
            action_info_values: Entries supplied as ``action_info_values``
                without transferring container ownership.
            use_action_info_validation: Whether use action info validation is
                enabled or required for this operation.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            kwargs: Additional collection options forwarded without ownership
                transfer.
            adaptive_parallel: Whether to probe bounded within-System device
                concurrency before selecting parallel or serial execution.
            max_concurrent_device_tasks: Maximum overlapping device lifecycles
                after the adaptive probe succeeds.

        Returns:
            The validated ``results``.
        """
        if (
            adaptive_parallel
            and len(device_tasks) > 1
            and max_concurrent_device_tasks > 1
        ):
            return await self._collect_for_system_adaptive(
                dut_id=dut_id,
                system_id=system_id,
                device_tasks=device_tasks,
                action_info_values=action_info_values,
                use_action_info_validation=use_action_info_validation,
                collector_name=collector_name,
                collector_id=collector_id,
                kwargs=kwargs,
                max_concurrent_device_tasks=max_concurrent_device_tasks,
            )
        results = []

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"[Parallel] Starting sequential collection for system {system_id} with {len(device_tasks)} tasks",
            dut_id,
        )

        for idx, task in enumerate(device_tasks):
            device_type = task["device_type"]
            device_id = task["device_id"]
            filename_device_id = task.get("filename_device_id", device_id)
            payload = task["payload"]
            diagnostic_type = task["diagnostic_type"]
            device_identifier = task["device_identifier"]
            filename_device_identifier = task.get(
                "filename_device_identifier",
                device_identifier,
            )
            is_in_action_info = task["is_in_action_info"]
            oem_diag_type = task["oem_diag_type"]
            device_config = task.get("device_config", {})

            # Log if attempting a task that's not in ActionInfo. The POST may
            # still work when ActionInfo is incomplete, but a real failure
            # remains part of truthful collector accounting.
            if (
                use_action_info_validation
                and action_info_values
                and not is_in_action_info
            ):
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"[ActionInfo] Attempting {device_type}_{device_id} on {system_id} - "
                    f"'{oem_diag_type}' not in ActionInfo; any attempted failure "
                    "remains status-contributing",
                    dut_id,
                )

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"[Parallel] System {system_id}: Collecting task {idx + 1}/{len(device_tasks)} - "
                f"{device_type}_{device_id}",
                dut_id,
            )

            # Create a filtered systems context for this specific system
            filtered_systems_for_device = [{"id": system_id}]

            # Create substitutions for output pattern
            device_substitutions = {
                "system_id": system_id,
                "device_id": filename_device_id,
                "device_type": device_type,
                "diagnostic_type": diagnostic_type,
                "device_identifier": filename_device_identifier,
            }

            # Create a clean kwargs dict without conflicting parameters
            clean_kwargs = {
                k: v for k, v in kwargs.items() if k not in ["function_tag"]
            }
            clean_kwargs["substitutions"] = device_substitutions
            clean_kwargs["filtered_systems"] = filtered_systems_for_device
            action_target_uri = task.get("action_target_uri")
            if action_target_uri:
                # Capability-derived tasks must use the exact advertised action
                # target. This intentionally overrides any conventional/catalog
                # URI inherited through the collector context.
                clean_kwargs["dump_uri_override"] = action_target_uri

            # Use existing collect_diagnostic_data method with custom payload
            result = await self.collect_diagnostic_data(
                dut_id=dut_id,
                entity_type="Systems",
                log_service="Dump",
                payload_types=[diagnostic_type],
                default_payload=payload,
                function_tag=f"{collector_name}_{device_type}",
                **clean_kwargs,
            )

            result_context = result.get("context", {})
            if not isinstance(result_context, dict):
                result_context = {}
            diagnostic_domain_block = result_context.get("diagnostic_domain_block")
            if not isinstance(diagnostic_domain_block, dict):
                diagnostic_domain_block = None
            diagnostic_domain_closed = bool(
                diagnostic_domain_block
                and diagnostic_domain_block.get("resubmit_allowed") is False
            )
            blocked_before_post = bool(
                diagnostic_domain_closed
                and diagnostic_domain_block.get("blocked_before_post") is True
            )
            affirmative_capability_no_post = (
                self._is_affirmative_capability_no_post_child(result, system_id)
            )

            if blocked_before_post or affirmative_capability_no_post:
                artifact_validation_errors = []
            else:
                artifact_validation_errors = await self._apply_dump_artifact_validation(
                    result,
                    device_config.get("artifact_validation")
                    or kwargs.get("artifact_validation"),
                )

            # Build result with metadata
            task_result = {
                "success": result.get("success", False),
                "output_files": result.get("output_files", []),
                "status": result.get(
                    "status",
                    "success" if result.get("success", False) else "error",
                ),
                "error_messages": result.get("error_messages", []),
                "device_type": device_type,
                "device_id": device_id,
                "system_id": system_id,
                "use_action_info_validation": use_action_info_validation,
                "is_in_action_info": is_in_action_info,
                "oem_diag_type": oem_diag_type,
                "artifact_validation_failed": bool(artifact_validation_errors),
                "artifact_validation_errors": artifact_validation_errors,
                "raw_result": result,
            }
            if diagnostic_domain_closed:
                task_result.update(
                    {
                        "diagnostic_domain_block": diagnostic_domain_block,
                        "diagnostic_domain_blocked_before_post": blocked_before_post,
                        "diagnostic_domain_suppressed_tasks": (
                            len(device_tasks) - idx - 1
                        ),
                    }
                )
            if "filename_device_id" in task:
                task_result["filename_device_id"] = filename_device_id
            if "device_descriptor" in task:
                task_result["device_descriptor"] = copy.deepcopy(
                    task["device_descriptor"]
                )
            if "system_dump_member_requirements" in task:
                task_result["system_dump_member_requirements"] = copy.deepcopy(
                    task["system_dump_member_requirements"]
                )
            results.append(task_result)

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"[Parallel] System {system_id}: Task {idx + 1}/{len(device_tasks)} complete - "
                f"{device_type}_{device_id} success={task_result['success']}",
                dut_id,
            )

            if diagnostic_domain_closed:
                await self._log_runtime(
                    "WARN",
                    "RedfishService",
                    f"[Parallel] System {system_id}: stopping diagnostic tasks "
                    f"after remote no-resubmit gate; {len(device_tasks) - idx - 1} "
                    "remaining task(s) were not attempted",
                    dut_id,
                )
                break

            # Add sleep between devices (but not after the last device)
            if idx < len(device_tasks) - 1:
                collector_def = kwargs.get("collector_def", {})
                dut_config = self.dut_manager.get_dut_config(dut_id)
                sleep_duration = get_collector_sleep_duration(
                    kwargs.get("collector_id", collector_id),
                    collector_def,
                    dut_config,
                    5,
                )
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"[Parallel] System {system_id}: Sleeping {sleep_duration}s between device dumps",
                    dut_id,
                )
                await asyncio.sleep(sleep_duration)

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"[Parallel] Completed collection for system {system_id}: "
            f"{sum(1 for r in results if r['success'])}/{len(results)} successful",
            dut_id,
        )

        return results

    async def collect_device_diagnostic_data(
        self,
        dut_id: str,
        collector_name: str,
        diagnostic_configs: Dict[str, Dict[str, Dict[str, Any]]] = None,
        discovered_devices: Dict[
            str,
            List[Union[int, DeviceDescriptor, Dict[str, Any]]],
        ] = None,
        target_baseboard: str = None,
        baseboard_config: Dict[str, Any] = None,
        capability_targeting: Optional[Dict[str, Any]] = None,
        diagnostic_concurrency: Optional[Dict[str, Any]] = None,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Generic device diagnostic data collection method.

        The implementation uses ``dut_id``, ``collector_name``,
        ``diagnostic_configs``, ``discovered_devices``, and ``target_baseboard``
        to generic device diagnostic data collection method. Owned asynchronous
        work is awaited before return, so completion does not leave an
        unobserved task behind. If the function cannot generic device diagnostic
        data collection method, its exception reaches the caller instead of
        being converted into a successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            collector_name: Stable collector name used for lookup and
                operator-facing diagnostics.
            diagnostic_configs: Optional Diagnostic configs governing generic
                device diagnostic data collection method.
            discovered_devices: Optional discovered devices; ``None`` selects
                the function's default behavior.
            target_baseboard: Optional target baseboard; ``None`` selects the
                function's default behavior.
            baseboard_config: Optional Baseboard config governing generic device
                diagnostic data collection method.
            capability_targeting: Optional capability targeting; ``None``
                selects the function's default behavior.
            diagnostic_concurrency: Optional catalog-owned compatible cohort
                policy for the selected baseboard.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing device diagnostic data.

        Raises:
            ValueError: If the supplied input cannot be used to generic device
                diagnostic data collection method; duplicate descriptor target
                would create duplicate collection tasks: ``identity``; or
                descriptor system_configs are ambiguous for ``system_id``:
                ``matching_patterns``.
        """
        try:
            # Get collector context for better logging
            collector_id = kwargs.get("collector_id", collector_name)

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"=== Starting device diagnostic data collection for {collector_name} ===",
                dut_id,
            )

            # Get discovered devices from context (passed from validation stage)
            if discovered_devices is None:
                discovered_devices = kwargs.get("discovered_devices", {})

            if target_baseboard is None:
                target_baseboard = kwargs.get("target_baseboard", "")

            if baseboard_config is None:
                baseboard_config = kwargs.get("baseboard_config", {})

            self._apply_diagnostic_concurrency_scope(
                dut_id,
                collector_id,
                diagnostic_concurrency,
                target_baseboard,
                kwargs,
            )
            if diagnostic_concurrency not in (None, "", {}):
                # The device helper delegates each target to the ordinary dump
                # hook. Forward the same catalog profile so that hook can
                # independently reconstruct (or reject) its runner scope.
                kwargs["diagnostic_concurrency"] = diagnostic_concurrency
            else:
                kwargs.pop("diagnostic_concurrency", None)

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Target baseboard: {target_baseboard}, discovered devices: {discovered_devices}",
                dut_id,
            )

            # Get baseboard-specific diagnostic configuration with fallback to default
            if not diagnostic_configs:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[
                        f"No diagnostic configuration provided for collector: {collector_name}"
                    ],
                    operation_name="device_diagnostic_data",
                    additional_context={"collector_name": collector_name},
                )

            # Try to get baseboard-specific config, fall back to 'default' key if not found
            if target_baseboard in diagnostic_configs:
                baseboard_diagnostic_config = diagnostic_configs[target_baseboard]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using diagnostic config for {target_baseboard}: {baseboard_diagnostic_config}",
                    dut_id,
                )
            elif "default" in diagnostic_configs:
                baseboard_diagnostic_config = diagnostic_configs["default"]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No specific config for {target_baseboard}, using default diagnostic config: {baseboard_diagnostic_config}",
                    dut_id,
                )
            else:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[
                        f"No diagnostic configuration found for baseboard '{target_baseboard}' and no 'default' config provided"
                    ],
                    operation_name="device_diagnostic_data",
                    additional_context={
                        "collector_name": collector_name,
                        "baseboard": target_baseboard,
                    },
                )

            # Get systems to use (could be filtered from validation)
            filtered_systems = kwargs.get("filtered_systems", [])
            if "filtered_systems" in kwargs:
                system_ids = [sys["id"] for sys in filtered_systems]
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using filtered systems: {system_ids}",
                    dut_id,
                )
            else:
                # Get all systems
                systems_uri = self.get_configured_uri(dut_id, "Systems")
                success, systems_response, _ = await self.dispatch_request(
                    dut_id, "GET", systems_uri, bypass_cache=True
                )
                if not success:
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[f"Failed to get systems: {systems_response}"],
                        operation_name="device_diagnostic_data",
                        additional_context={},
                    )
                system_members = systems_response.get("Members", [])
                system_ids = [
                    member.get("@odata.id", "").split("/")[-1]
                    for member in system_members
                ]

            # Apply ID filtering based on DUT configuration
            dut_config = self.dut_manager.get_dut_config(dut_id)
            original_system_ids = system_ids.copy()
            system_ids = filter_ids(system_ids, "system", dut_config)

            # Log filtered IDs if any were filtered
            if len(system_ids) != len(original_system_ids):
                await log_filtered_ids(
                    original_system_ids,
                    system_ids,
                    "system",
                    self.logger,
                    dut_id,
                )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Using system IDs: {system_ids}",
                dut_id,
            )

            # Query ActionInfo for validated systems if enabled
            # This provides the authoritative list of valid diagnostic types per system
            # First check baseboard_diagnostic_config, then fallback to kwargs
            use_action_info_validation = baseboard_diagnostic_config.get(
                "use_action_info_validation",
                kwargs.get("use_action_info_validation", False),
            )
            action_info_by_system: Dict[str, List[str]] = {}
            capability_state_by_system: Dict[str, str] = {}
            legacy_fallback_system_ids: List[str] = []
            preferred_diagnostic_type: Optional[str] = None
            require_authoritative_capability = kwargs.get(
                "require_authoritative_capability", False
            )
            authoritative_capability_evidence: Optional[Dict[str, Any]] = None
            if isinstance(capability_targeting, dict):
                logical_device_type = capability_targeting.get("device_type")
                device_config = baseboard_diagnostic_config.get(logical_device_type)
                if isinstance(device_config, dict):
                    configured_type = device_config.get("diagnostic_type")
                    if isinstance(configured_type, str) and configured_type:
                        preferred_diagnostic_type = configured_type
            capability_precondition_error: Optional[str] = None
            if require_authoritative_capability:
                (
                    capability_resolution,
                    capability_precondition_error,
                ) = await self._get_required_system_dump_capability_targets(
                    dut_id,
                    system_ids,
                    capability_targeting,
                    preferred_diagnostic_type,
                )
            else:
                capability_resolution = await self._get_system_dump_capability_targets(
                    dut_id,
                    system_ids,
                    capability_targeting,
                    preferred_diagnostic_type,
                )

            if capability_precondition_error:
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    (
                        "[ActionInfo] Required authoritative capability precondition "
                        f"failed for {collector_name}: {capability_precondition_error}"
                    ),
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[capability_precondition_error],
                    operation_name="device_diagnostic_data",
                    additional_context={
                        "collector_name": collector_name,
                        "target_baseboard": target_baseboard,
                        "status": "error",
                        "reason": capability_precondition_error,
                        "precondition_failed": True,
                        "capability_requirement": "authoritative_system_dump_action_info",
                    },
                )
            capability_targets: Optional[List[Dict[str, str]]] = None
            if capability_resolution is not None:
                (
                    capability_targets,
                    action_info_by_system,
                    capability_state_by_system,
                ) = capability_resolution
                legacy_fallback_system_ids = [
                    system_id
                    for system_id in system_ids
                    if capability_state_by_system.get(system_id) == "unavailable"
                ]
                if require_authoritative_capability:
                    # Persist the verified fresh snapshot values that authorized
                    # each request, not merely a boolean assertion about the path.
                    authoritative_capability_evidence = {
                        "source": SYSTEM_DUMP_CAPABILITY_SOURCE,
                        "status": "available",
                        "authoritative": True,
                        "fresh_discovery": True,
                        "dut_id": dut_id,
                        "systems": {
                            system_id: {
                                "status": "available",
                                "oem_diagnostic_data_types": list(
                                    action_info_by_system[system_id]
                                ),
                            }
                            for system_id in sorted(system_ids)
                        },
                    }
                use_action_info_validation = True
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[ActionInfo] Derived {len(capability_targets)} exact target(s) "
                    f"for {collector_name}; legacy fallback limited to "
                    f"{legacy_fallback_system_ids}",
                    dut_id,
                )

            if (
                use_action_info_validation
                and system_ids
                and not action_info_by_system
                and capability_resolution is None
            ):
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[ActionInfo] Querying ActionInfo for {len(system_ids)} systems (validation enabled)",
                    dut_id,
                )
                action_info_by_system = await self._query_action_info_for_systems(
                    dut_id, system_ids, log_service="Dump"
                )
                if action_info_by_system:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[ActionInfo] Retrieved ActionInfo for {len(action_info_by_system)} systems",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        "[ActionInfo] No ActionInfo retrieved, using fallback behavior (all failures count)",
                        dut_id,
                    )

            # If no eligible systems remain after filtering, optionally treat as complete
            # Rely on config to opt into empty-target completion behavior
            complete_on_empty_targets = kwargs.get("complete_on_empty_targets", False)
            if not system_ids:
                if complete_on_empty_targets:
                    if discovered_devices and not any(discovered_devices.values()):
                        empty_reason = (
                            f"No {list(discovered_devices.keys())} devices discovered "
                            f"for {collector_name} - nothing to collect (expected)"
                        )
                        # No systems and no devices is an expected no-op.
                        result = await self._create_standardized_collector_result(
                            successful_operations=1,
                            total_operations=1,
                            output_files=[],
                            error_messages=[],
                            operation_name="device_diagnostic_data",
                            additional_context={
                                "collector_name": collector_name,
                                "reason": empty_reason,
                                "systems_before_filter": original_system_ids,
                                "systems_after_filter": system_ids,
                                "devices_discovered": discovered_devices,
                            },
                        )
                        result["reason"] = empty_reason
                        result.setdefault("context", {})["reason"] = empty_reason
                        return result

                    device_target_count = sum(
                        len(device_ids)
                        for device_ids in discovered_devices.values()
                        if isinstance(device_ids, list)
                    )
                    error_reason = (
                        "No eligible systems remain after filtering for "
                        f"{collector_name} while {device_target_count} device "
                        "target(s) were discovered"
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=1,
                        output_files=[],
                        error_messages=[error_reason],
                        operation_name="device_diagnostic_data",
                        additional_context={
                            "collector_name": collector_name,
                            "reason": error_reason,
                            "precondition_failed": True,
                            "systems_before_filter": original_system_ids,
                            "systems_after_filter": system_ids,
                            "devices_discovered": discovered_devices,
                        },
                    )
                    result["reason"] = error_reason
                    result.setdefault("context", {})["reason"] = error_reason
                    return result

            invalid_capability_system_ids = [
                system_id
                for system_id in system_ids
                if capability_state_by_system.get(system_id) == "invalid"
            ]
            unsupported_capability_system_ids = [
                system_id
                for system_id in system_ids
                if capability_state_by_system.get(system_id) == "unsupported"
            ]
            exact_capability_system_ids = sorted(
                {target["system_id"] for target in capability_targets or []}
            )
            capability_routing_context = {
                "exact_target_systems": exact_capability_system_ids,
                "unsupported_systems": unsupported_capability_system_ids,
                "invalid_target_systems": invalid_capability_system_ids,
                "legacy_fallback_systems": legacy_fallback_system_ids,
            }

            if (
                capability_targets is not None
                and not capability_targets
                and not legacy_fallback_system_ids
            ):
                if invalid_capability_system_ids:
                    invalid_reason = (
                        "System Dump capability discovery returned invalid advertised "
                        "action targets for System(s): "
                        + ", ".join(invalid_capability_system_ids)
                    )
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=len(invalid_capability_system_ids),
                        output_files=[],
                        error_messages=[invalid_reason],
                        operation_name="device_diagnostic_data",
                        additional_context={
                            "collector_name": collector_name,
                            "target_baseboard": target_baseboard,
                            "devices_processed": 0,
                            "successful_collections": 0,
                            "total_collections": len(invalid_capability_system_ids),
                            "status": "error",
                            "reason": invalid_reason,
                            "capability_targeting": True,
                            "capability_routing": capability_routing_context,
                            "authoritative_capability_required": bool(
                                require_authoritative_capability
                            ),
                        },
                    )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="device_diagnostic_data",
                    additional_context={
                        "collector_name": collector_name,
                        "target_baseboard": target_baseboard,
                        "devices_processed": 0,
                        "successful_collections": 0,
                        "total_collections": 0,
                        "status": "skipped",
                        "reason": (
                            "Authoritative System Dump ActionInfo advertises no "
                            f"matching targets for {collector_name}"
                        ),
                        "capability_targeting": True,
                        "capability_routing": capability_routing_context,
                        "authoritative_capability_required": bool(
                            require_authoritative_capability
                        ),
                        "intentional_evidence_only_skip": True,
                    },
                )

            all_output_files = []
            all_status_list = [False] * len(invalid_capability_system_ids)
            error_messages = [
                f"System {system_id}: advertised System Dump action target is invalid"
                for system_id in invalid_capability_system_ids
            ]

            # ActionInfo-aware result tracking
            # These track whether each operation was expected based on ActionInfo
            action_info_results = {
                "expected_successes": 0,  # In ActionInfo and succeeded
                "expected_failures": 0,  # In ActionInfo and failed (counts against us)
                "expected_validation_failures": 0,  # Download succeeded but artifact was internally incomplete
                # Attempted failures outside ActionInfo remain status-contributing.
                "unexpected_failures": 0,
                "bonus_successes": 0,  # NOT in ActionInfo but succeeded
                "action_info_available": bool(action_info_by_system),
                "validated_tasks": 0,
                "unvalidated_tasks": 0,
            }

            # Parallel collection configuration (disabled by default)
            # NOTE: Cross-system parallelism remains independent. Within one
            # System LogService, execution stays serial unless the governed
            # platform policy enables the adaptive task-creation probe below.
            # First check baseboard_diagnostic_config, then fallback to kwargs
            parallel_collection = baseboard_diagnostic_config.get(
                "parallel_collection", kwargs.get("parallel_collection", False)
            )
            max_concurrent_tasks = baseboard_diagnostic_config.get(
                "max_concurrent_tasks", kwargs.get("max_concurrent_tasks", 4)
            )

            default_diagnostic_config = diagnostic_configs.get("default", {})
            default_adaptive_device_config = (
                default_diagnostic_config.get("adaptive_parallel_device_collection")
                if isinstance(default_diagnostic_config, dict)
                else None
            )
            adaptive_device_config = baseboard_diagnostic_config.get(
                "adaptive_parallel_device_collection",
                default_adaptive_device_config,
            )
            adaptive_parallel_devices = False
            adaptive_enabled = False
            requested_concurrent_device_tasks: Union[int, str] = 1
            effective_concurrent_device_tasks = 1
            if adaptive_device_config is not None:
                if not isinstance(adaptive_device_config, dict):
                    raise ValueError(
                        "adaptive_parallel_device_collection must be a mapping"
                    )
                adaptive_enabled = adaptive_device_config.get("enabled", False)
                if not isinstance(adaptive_enabled, bool):
                    raise ValueError(
                        "adaptive_parallel_device_collection.enabled must be boolean"
                    )
                if adaptive_enabled:
                    requested_concurrent_device_tasks = adaptive_device_config.get(
                        "max_concurrent_tasks",
                        "all",
                    )
                    if isinstance(requested_concurrent_device_tasks, str):
                        requested_concurrent_device_tasks = (
                            requested_concurrent_device_tasks.strip().lower()
                        )
                    if requested_concurrent_device_tasks != "all" and (
                        isinstance(requested_concurrent_device_tasks, bool)
                        or not isinstance(requested_concurrent_device_tasks, int)
                        or requested_concurrent_device_tasks < 2
                    ):
                        raise ValueError(
                            "adaptive_parallel_device_collection.max_concurrent_tasks "
                            "must be 'all' or an integer of at least 2"
                        )

            if parallel_collection:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[Parallel] Parallel collection enabled with max_concurrent_tasks={max_concurrent_tasks}. "
                    f"Note: BMC may enforce sequential collection within a single LogService.",
                    dut_id,
                )

            # ================================================================
            # PHASE 1: Build tasks grouped by system_id
            # This prepares all collection tasks before execution, enabling
            # either sequential or parallel collection strategies.
            # ================================================================
            config_keys_to_skip = {
                "use_action_info_validation",
                "parallel_collection",
                "max_concurrent_tasks",
                "adaptive_parallel_device_collection",
            }
            tasks_by_system: Dict[str, List[Dict[str, Any]]] = {}
            expected_descriptor_targets: Dict[Tuple[str, str, str], str] = {}
            routed_descriptor_targets: set[Tuple[str, str, str]] = set()

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"[TaskBuild] Building collection tasks for {len(system_ids)} systems",
                dut_id,
            )

            if capability_targets is not None:
                for target in capability_targets:
                    system_id = target["system_id"]
                    device_type = target["device_type"]
                    device_config = baseboard_diagnostic_config.get(device_type, {})
                    if not isinstance(device_config, dict):
                        device_config = {}
                    resolved_config = await self.resolve_system_config(
                        system_id, device_config, dut_id, device_type
                    )
                    exact_value = target["oem_diag_type"]
                    tasks_by_system.setdefault(system_id, []).append(
                        {
                            "device_type": device_type,
                            # Use the advertised identifier in the output name,
                            # not a reconstructed platform-specific prefix.
                            "device_id": target["filename_identifier"],
                            "action_target_uri": target["action_target_uri"],
                            "device_config": resolved_config,
                            "payload": {
                                "DiagnosticDataType": "OEM",
                                "OEMDiagnosticDataType": exact_value,
                            },
                            "oem_diag_type": exact_value,
                            "is_in_action_info": True,
                            "device_identifier": target["device_identifier"],
                            "diagnostic_type": target["diagnostic_type"],
                        }
                    )

            legacy_task_system_ids = (
                list(system_ids)
                if capability_targets is None
                else legacy_fallback_system_ids
            )
            config_items = (
                baseboard_diagnostic_config.items() if legacy_task_system_ids else []
            )
            for device_type, device_config in config_items:
                # Skip non-device configuration keys
                if device_type in config_keys_to_skip:
                    continue
                # Skip non-dict device configs (shouldn't happen but be safe)
                if not isinstance(device_config, dict):
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"Skipping non-dict config key: {device_type}",
                        dut_id,
                    )
                    continue

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Processing device type: {device_type} with config: {device_config}",
                    dut_id,
                )

                # Get legacy IDs or identity-preserving descriptors for this type.
                # device_ids_override bypasses discovery for system-level queries
                # (e.g. DiagnosticType=SMA with no per-device suffix).
                device_ids_override = device_config.get("device_ids_override")
                if device_ids_override is not None:
                    raw_device_targets = device_ids_override
                else:
                    raw_device_targets = discovered_devices.get(device_type, [])
                if not raw_device_targets:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"No devices discovered for type {device_type}, skipping",
                        dut_id,
                    )
                    continue
                if isinstance(raw_device_targets, set):
                    raw_device_targets = list(raw_device_targets)
                device_targets = validate_device_targets(raw_device_targets)
                has_descriptor_targets = any(
                    isinstance(target, DeviceDescriptor) for target in device_targets
                )
                if has_descriptor_targets and "system_configs" in device_config:
                    is_valid, validation_errors = self.validate_system_configs_schema(
                        device_config["system_configs"],
                        dut_id,
                    )
                    if not is_valid:
                        raise ValueError(
                            "invalid descriptor system_configs: "
                            + "; ".join(validation_errors)
                        )
                for target in device_targets:
                    if not isinstance(target, DeviceDescriptor):
                        continue
                    identity = (device_type, target.identifier, target.family)
                    if identity in expected_descriptor_targets:
                        raise ValueError(
                            "duplicate descriptor target would create duplicate "
                            f"collection tasks: {identity}"
                        )
                    expected_descriptor_targets[identity] = target.source

                # Build tasks for each system and device combination
                for system_id in legacy_task_system_ids:
                    if has_descriptor_targets and device_config.get("system_configs"):
                        system_configs = device_config["system_configs"]
                        if system_id not in system_configs:
                            matching_patterns = [
                                pattern
                                for pattern in system_configs
                                if fnmatch.fnmatchcase(system_id, pattern)
                            ]
                            if len(matching_patterns) > 1:
                                raise ValueError(
                                    "descriptor system_configs are ambiguous for "
                                    f"{system_id}: {matching_patterns}"
                                )
                            if not matching_patterns:
                                await self._log_runtime(
                                    "DEBUG",
                                    "RedfishService",
                                    f"[TaskBuild] No descriptor system_config routes {device_type} to {system_id}",
                                    dut_id,
                                )
                                continue
                    # Resolve system-specific configuration (supports multi-system platforms)
                    resolved_config = await self.resolve_system_config(
                        system_id, device_config, dut_id, device_type
                    )

                    # Extract diagnostic configuration from resolved config
                    diagnostic_type = resolved_config.get("diagnostic_type", "")
                    device_id_key = resolved_config.get("device_id_key", "DeviceID")
                    device_id_prefix = resolved_config.get("device_id_prefix", "")

                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"[TaskBuild] {system_id}: diagnostic_type={diagnostic_type}, "
                        f"device_id_key={device_id_key}, device_id_prefix={device_id_prefix}",
                        dut_id,
                    )

                    for device_target in device_targets:
                        descriptor = (
                            device_target
                            if isinstance(device_target, DeviceDescriptor)
                            else None
                        )
                        if descriptor is not None:
                            matches, reason = self._descriptor_matches_task_config(
                                descriptor,
                                system_id,
                                resolved_config,
                            )
                            if not matches:
                                await self._log_runtime(
                                    "DEBUG",
                                    "RedfishService",
                                    f"[TaskBuild] Skipping {device_type} descriptor for {system_id}: {reason}",
                                    dut_id,
                                )
                                continue
                            device_id = descriptor.identifier
                            template_device_id = descriptor.device_id
                            device_identifier = descriptor.identifier
                            family = descriptor.family
                            source = descriptor.source
                            routed_descriptor_targets.add(
                                (
                                    device_type,
                                    descriptor.identifier,
                                    descriptor.family,
                                )
                            )
                        else:
                            device_id = device_target
                            template_device_id = device_id
                            family = source = ""
                            if device_id_prefix:
                                device_identifier = f"{device_id_prefix}{device_id}"
                            else:
                                device_identifier = str(device_id)

                        # Create diagnostic payload using configurable template
                        payload_template = resolved_config.get(
                            "payload_template",
                            {
                                "DiagnosticDataType": "OEM",
                                "OEMDiagnosticDataType": "{diagnostic_type};{device_id_key}={device_identifier}",
                            },
                        )

                        # Substitute placeholders in the payload template
                        payload = {}
                        for key, value in payload_template.items():
                            if isinstance(value, str):
                                substituted_value = value.format(
                                    diagnostic_type=diagnostic_type,
                                    device_id_key=device_id_key,
                                    device_identifier=device_identifier,
                                    identifier=device_identifier,
                                    device_id=template_device_id,
                                    device_type=device_type,
                                    system_id=system_id,
                                    family=family,
                                    source=source,
                                )
                                payload[key] = substituted_value
                            else:
                                payload[key] = value

                        # Check if this diagnostic type is in ActionInfo (if available)
                        oem_diag_type = payload.get("OEMDiagnosticDataType", "")
                        system_action_info = action_info_by_system.get(system_id, [])
                        is_in_action_info = self._check_diagnostic_type_in_action_info(
                            oem_diag_type, system_action_info
                        )

                        if use_action_info_validation:
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"[TaskBuild] {oem_diag_type} in ActionInfo for {system_id}: {is_in_action_info}",
                                dut_id,
                            )

                        # Build task dict
                        task = {
                            "device_type": device_type,
                            "device_id": device_id,
                            "device_config": resolved_config,
                            "payload": payload,
                            "oem_diag_type": oem_diag_type,
                            "is_in_action_info": is_in_action_info,
                            "device_identifier": device_identifier,
                            "diagnostic_type": diagnostic_type,
                        }
                        if descriptor is not None:
                            filename_identifier = (
                                self._safe_descriptor_filename_identifier(
                                    descriptor.identifier
                                )
                            )
                            task["filename_device_id"] = filename_identifier
                            task["filename_device_identifier"] = filename_identifier
                            task["device_descriptor"] = descriptor.as_dict()

                        # Add to system's task list
                        if system_id not in tasks_by_system:
                            tasks_by_system[system_id] = []
                        tasks_by_system[system_id].append(task)

            unrouted_descriptor_targets = (
                set(expected_descriptor_targets) - routed_descriptor_targets
            )
            if unrouted_descriptor_targets:
                unrouted = [
                    {
                        "device_type": device_type,
                        "identifier": identifier,
                        "family": family,
                        "source": expected_descriptor_targets[
                            (device_type, identifier, family)
                        ],
                    }
                    for device_type, identifier, family in sorted(
                        unrouted_descriptor_targets
                    )
                ]
                unrouted_preview = unrouted[:25]
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[
                        f"{len(unrouted)} descriptor target(s) were discovered but "
                        "did not match any selected System/configuration; first "
                        f"{len(unrouted_preview)}: {unrouted_preview}"
                    ],
                    operation_name="device_diagnostic_data",
                    additional_context={
                        "collector_name": collector_name,
                        "target_baseboard": target_baseboard,
                        "unrouted_descriptor_target_count": len(unrouted),
                        "unrouted_descriptor_targets": unrouted_preview,
                        "unrouted_descriptor_targets_truncated": (
                            len(unrouted_preview) < len(unrouted)
                        ),
                    },
                )

            if use_action_info_validation:
                tasks_by_system = {
                    system_id: self._coalesce_system_dump_device_tasks(
                        tasks,
                        action_info_by_system.get(system_id, []),
                        kwargs.get("artifact_validation"),
                    )
                    for system_id, tasks in tasks_by_system.items()
                }

            # Log task summary
            total_tasks = sum(len(tasks) for tasks in tasks_by_system.values())
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"[TaskBuild] Built {total_tasks} tasks across {len(tasks_by_system)} systems: "
                + ", ".join(
                    f"{sid}={len(tasks)}" for sid, tasks in tasks_by_system.items()
                ),
                dut_id,
            )

            if adaptive_enabled:
                max_tasks_per_system = max(
                    (len(system_tasks) for system_tasks in tasks_by_system.values()),
                    default=0,
                )
                requested_task_limit = (
                    max_tasks_per_system
                    if requested_concurrent_device_tasks == "all"
                    else requested_concurrent_device_tasks
                )
                runtime_task_limit = self._runtime_boundary(
                    dut_id,
                    "redfish_max_concurrent_dumps",
                )
                effective_concurrent_device_tasks = (
                    min(
                        int(requested_task_limit),
                        runtime_task_limit,
                        max_tasks_per_system,
                    )
                    if max_tasks_per_system
                    else 1
                )
                adaptive_parallel_devices = effective_concurrent_device_tasks > 1
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    "[AdaptiveParallel] Device collection enabled with "
                    f"requested_concurrency={requested_concurrent_device_tasks}, "
                    f"effective_concurrency={effective_concurrent_device_tasks}, "
                    f"runtime_limit={runtime_task_limit}",
                    dut_id,
                )

            # The target count is authoritative only after discovery.  Publish
            # a topology-aware projection now, but never reinterpret it as a
            # collector-wide kill deadline.  Each diagnostic lifecycle retains
            # its own spreadsheet/configured timeout.
            diagnostic_work_projection: Dict[str, Any] = {
                "schema_version": "1.0",
                "scope": "selected_dut_discovered_targets",
                "target_count": total_tasks,
                "available": False,
                "enforced": False,
            }
            try:
                runtime_budget = self._current_runtime_budget(str(collector_id))
                runtime_remote_timeout = getattr(
                    runtime_budget, "remote_task_timeout_seconds", None
                )
                if runtime_remote_timeout is not None:
                    per_target_timeout = float(runtime_remote_timeout)
                else:
                    per_target_timeout = await self._resolve_collector_timeout(
                        dut_id,
                        kwargs,
                        default_timeout=1500,
                        collector_id=str(collector_id),
                        collector_def=kwargs.get("collector_def", {}),
                    )
                shared_hmc_serialization = (
                    self._hmc_diagnostic_lock_key(dut_id) is not None
                )
                planning_max_targets = None
                planning_profile_error = None
                try:
                    manager_getter = getattr(
                        self.dut_manager, "_get_baseboard_manager", None
                    )
                    baseboard_manager = (
                        manager_getter() if callable(manager_getter) else None
                    )
                    baseboard_config = (
                        baseboard_manager.get_baseboard_config(target_baseboard)
                        if baseboard_manager is not None
                        else None
                    )
                    planning_profile = collector_workload_profile(
                        baseboard_config,
                        str(collector_id),
                    )
                    if planning_profile is not None:
                        planning_max_targets = planning_profile[
                            PLANNING_MAX_TARGETS_PER_DUT_KEY
                        ]
                except Exception as profile_error:
                    planning_profile_error = type(profile_error).__name__
                diagnostic_work_projection = project_discovered_diagnostic_work(
                    {
                        system_id: len(system_tasks)
                        for system_id, system_tasks in tasks_by_system.items()
                    },
                    per_target_timeout,
                    parallel_systems=bool(parallel_collection),
                    max_concurrent_systems=max_concurrent_tasks,
                    shared_hmc_serialization=shared_hmc_serialization,
                    planning_max_targets_per_dut=planning_max_targets,
                )
                if adaptive_enabled:
                    diagnostic_work_projection[
                        "adaptive_parallel_device_collection"
                    ] = {
                        "enabled": True,
                        "requested_max_concurrent_tasks": (
                            requested_concurrent_device_tasks
                        ),
                        "effective_max_concurrent_tasks": (
                            effective_concurrent_device_tasks
                        ),
                        "parallel_probe_eligible": bool(
                            adaptive_parallel_devices and total_tasks > 1
                        ),
                        "critical_path_assumption": "serial_fallback",
                    }
                if planning_profile_error is not None:
                    diagnostic_work_projection["planning_profile"][
                        "unavailable_reason"
                    ] = planning_profile_error
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    (
                        "[TaskBuild] Observed-only diagnostic work projection: "
                        f"targets={diagnostic_work_projection['target_count']}, "
                        "critical_path_slots="
                        f"{diagnostic_work_projection['critical_path_target_slots']}, "
                        "per_target_timeout="
                        f"{diagnostic_work_projection['per_target_timeout_seconds']:g}s, "
                        "projected_remote_task_seconds="
                        f"{diagnostic_work_projection['projected_critical_path_seconds']:g}, "
                        f"shared_hmc={shared_hmc_serialization}, "
                        "planning_max_targets_per_dut="
                        f"{planning_max_targets}; enforced=false"
                    ),
                    dut_id,
                )
            except Exception as projection_error:
                diagnostic_work_projection["unavailable_reason"] = type(
                    projection_error
                ).__name__
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    (
                        "[TaskBuild] Diagnostic work projection unavailable "
                        f"({type(projection_error).__name__}); collection continues"
                    ),
                    dut_id,
                )

            # ================================================================
            # PHASE 2: Execute tasks (parallel or sequential)
            # Parallel: Different systems run concurrently via asyncio.gather
            # Sequential: Systems processed one at a time (original behavior)
            # Within-system execution is serial by default. Governed platform
            # configuration may opt into the bounded adaptive probe.
            # ================================================================
            all_task_results: List[Dict[str, Any]] = []

            if parallel_collection and len(tasks_by_system) > 1:
                # Parallel execution across systems
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[Parallel] Executing {len(tasks_by_system)} systems in parallel "
                    f"(max_concurrent={max_concurrent_tasks})",
                    dut_id,
                )

                semaphore = asyncio.Semaphore(max_concurrent_tasks)

                async def limited_collect_for_system(
                    sid: str, tasks: List[Dict]
                ) -> List[Dict]:
                    """
                    Wrapper to limit concurrent system collections.

                    After applying local validation, the function forwards
                    ``sid`` and ``tasks`` to ``self._collect_for_system`` and
                    preserves its return and exception contract. Owned
                    asynchronous work is awaited before return, so completion
                    does not leave an unobserved task behind.

                    Args:
                        sid: Text supplied as sid in the format accepted by this
                            function.
                        tasks: Mapping supplying fields for wrapper to limit
                            concurrent system collections.

                    Returns:
                        The limited collect for system returned in
                        operation-defined order.
                    """
                    async with semaphore:
                        system_uses_action_info = (
                            use_action_info_validation and sid in action_info_by_system
                        )
                        return await self._collect_for_system(
                            dut_id=dut_id,
                            system_id=sid,
                            device_tasks=tasks,
                            action_info_values=action_info_by_system.get(sid, []),
                            use_action_info_validation=system_uses_action_info,
                            collector_name=collector_name,
                            collector_id=collector_id,
                            kwargs=kwargs,
                            adaptive_parallel=adaptive_parallel_devices,
                            max_concurrent_device_tasks=(
                                effective_concurrent_device_tasks
                            ),
                        )

                # Run all systems in parallel
                parallel_results = await asyncio.gather(
                    *[
                        limited_collect_for_system(sid, tasks)
                        for sid, tasks in tasks_by_system.items()
                    ],
                    return_exceptions=True,
                )

                # Flatten results and handle exceptions
                for sid, result in zip(tasks_by_system.keys(), parallel_results):
                    if isinstance(result, asyncio.CancelledError):
                        # ``gather`` has already observed every sibling. Preserve
                        # cooperative cancellation instead of converting this
                        # BaseException into a collector error via ``extend``.
                        raise result
                    if isinstance(result, Exception):
                        await self._log_runtime(
                            "ERROR",
                            "RedfishService",
                            f"[Parallel] Exception collecting system {sid}: {str(result)}",
                            dut_id,
                        )
                        # Create failure results for all tasks in this system
                        for task in tasks_by_system[sid]:
                            all_task_results.append(
                                {
                                    "success": False,
                                    "output_files": [],
                                    "status": False,
                                    "error_messages": [
                                        f"System collection exception: {str(result)}"
                                    ],
                                    "device_type": task["device_type"],
                                    "device_id": task["device_id"],
                                    "system_id": sid,
                                    "use_action_info_validation": (
                                        use_action_info_validation
                                        and sid in action_info_by_system
                                    ),
                                    "is_in_action_info": task["is_in_action_info"],
                                    "oem_diag_type": task["oem_diag_type"],
                                }
                            )
                    else:
                        all_task_results.extend(result)

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[Parallel] Parallel execution complete: {len(all_task_results)} results",
                    dut_id,
                )

            else:
                # Sequential execution (original behavior or single system)
                mode = "sequential" if not parallel_collection else "single-system"
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[Sequential] Executing {len(tasks_by_system)} systems in {mode} mode",
                    dut_id,
                )

                for system_id, system_tasks in tasks_by_system.items():
                    system_uses_action_info = (
                        use_action_info_validation
                        and system_id in action_info_by_system
                    )
                    system_results = await self._collect_for_system(
                        dut_id=dut_id,
                        system_id=system_id,
                        device_tasks=system_tasks,
                        action_info_values=action_info_by_system.get(system_id, []),
                        use_action_info_validation=system_uses_action_info,
                        collector_name=collector_name,
                        collector_id=collector_id,
                        kwargs=kwargs,
                        adaptive_parallel=adaptive_parallel_devices,
                        max_concurrent_device_tasks=(effective_concurrent_device_tasks),
                    )
                    all_task_results.extend(system_results)

            adaptive_execution_evidence = diagnostic_work_projection.get(
                "adaptive_parallel_device_collection"
            )
            if isinstance(adaptive_execution_evidence, dict):
                parallel_task_results = [
                    result
                    for result in all_task_results
                    if result.get("device_task_execution_mode") == "adaptive_parallel"
                ]
                serial_fallback_results = [
                    result
                    for result in all_task_results
                    if result.get("adaptive_parallel_serial_fallback") is True
                ]
                rejection_message_ids = sorted(
                    {
                        str(result["parallel_creation_rejection_message_id"])
                        for result in serial_fallback_results
                        if result.get("parallel_creation_rejection_message_id")
                    }
                )
                adaptive_execution_evidence.update(
                    {
                        "parallel_attempted": bool(parallel_task_results),
                        "serial_fallback_used": bool(serial_fallback_results),
                        "serial_fallback_task_count": len(serial_fallback_results),
                        "creation_rejection_message_ids": rejection_message_ids,
                    }
                )

            # ================================================================
            # PHASE 3: Process all results
            # Aggregate output files, status, errors, and ActionInfo metrics
            # ================================================================
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"[Results] Processing {len(all_task_results)} task results",
                dut_id,
            )

            # Mapping: system_id -> {oem_diag_type -> [output filenames]}
            # Written as a JSON file at the end for easy query-to-file lookups.
            dump_query_map: Dict[str, Dict[str, List[str]]] = {}
            system_dump_device_coverage: Dict[str, Dict[str, Any]] = {}
            diagnostic_domain_gate_results: List[Dict[str, Any]] = []
            blocked_before_post_task_count = 0
            suppressed_device_task_count = 0
            intentional_skipped_task_count = 0
            attempted_device_task_count = 0
            degraded_device_task_count = 0
            degraded_child_reasons: List[str] = []
            blocked_after_attempt_task_count = 0
            accounted_child_unattempted_operation_count = 0
            accounted_child_unattempted_reason_counts: Dict[str, int] = {}
            omitted_accounted_child_unattempted_operations = 0
            aggregated_successful_operations = sum(all_status_list)
            aggregated_total_operations = len(all_status_list)
            unattempted_reason_counts: Dict[str, int] = {}
            omitted_unattempted_reason_tasks = 0
            unadvertised_attempted_domain_rejections = 0

            def record_unattempted_reason(
                reason: Any,
                task_count: int,
                fallback: str,
            ) -> None:
                """
                Record one bounded reason for diagnostic tasks not attempted.

                The accumulator retains only a fixed number of distinct,
                sanitizer-safe reason strings. Additional reason classes are
                represented by their total task count so result context remains
                bounded even when a platform supplies unique text per task.

                Args:
                    reason: Child or diagnostic-domain reason to retain.
                    task_count: Number of unattempted tasks explained by the
                        reason.
                    fallback: Controlled explanation used when ``reason`` is
                        absent or empty.

                Side Effects:
                    Mutates ``unattempted_reason_counts`` and
                    ``omitted_unattempted_reason_tasks`` in the enclosing
                    aggregation scope.
                """
                nonlocal omitted_unattempted_reason_tasks

                if task_count <= 0:
                    return
                reason_text = (
                    reason if isinstance(reason, str) and reason.strip() else fallback
                )
                bounded_reason = self._bounded_diagnostic_log_text(reason_text)
                if bounded_reason in unattempted_reason_counts:
                    unattempted_reason_counts[bounded_reason] += task_count
                elif len(unattempted_reason_counts) < _DIAGNOSTIC_LOG_MAX_ITEMS:
                    unattempted_reason_counts[bounded_reason] = task_count
                else:
                    omitted_unattempted_reason_tasks += task_count

            def format_unattempted_reason(prefix: str) -> str:
                """
                Render a bounded operator reason for unattempted tasks.

                Every retained reason class includes its task cardinality. The
                final text passes through the existing diagnostic sanitizer and
                fixed-width bound before becoming collector status evidence.

                Args:
                    prefix: Controlled status summary placed before the reason
                        classes.

                Returns:
                    Sanitizer-safe bounded text explaining the unattempted
                    diagnostic tasks.
                """
                reason_parts = [
                    f"{task_count} task(s): {reason}"
                    for reason, task_count in unattempted_reason_counts.items()
                ]
                if omitted_unattempted_reason_tasks:
                    reason_parts.append(
                        f"{omitted_unattempted_reason_tasks} task(s): "
                        "additional reason classes omitted"
                    )
                reason_parts.extend(
                    f"{operation_count} child operation(s): {reason}"
                    for reason, operation_count in (
                        accounted_child_unattempted_reason_counts.items()
                    )
                )
                if omitted_accounted_child_unattempted_operations:
                    reason_parts.append(
                        f"{omitted_accounted_child_unattempted_operations} child "
                        "operation(s): additional reason classes omitted"
                    )
                if not reason_parts:
                    reason_parts.append(
                        "unattempted diagnostic task reason was unavailable"
                    )
                return self._bounded_diagnostic_log_text(
                    f"{prefix} Causes: {'; '.join(reason_parts)}"
                )

            def record_accounted_child_unattempted_reason(
                reason: Any,
                operation_count: int,
                fallback: str,
            ) -> None:
                """
                Record suppressed child operations already in child totals.

                A child diagnostic result can contain completed work followed
                by a typed pre-POST domain block. Its standardized denominator
                already includes those suppressed operations, so this evidence
                is retained separately and never added to the outer denominator
                a second time.

                Args:
                    reason: Child or diagnostic-domain reason to retain.
                    operation_count: Number of child operations already present
                        in the child's standardized total.
                    fallback: Controlled explanation used when ``reason`` is
                        absent or empty.

                Side Effects:
                    Mutates the accounted-child reason accumulators in the
                    enclosing aggregation scope.
                """
                nonlocal omitted_accounted_child_unattempted_operations

                if operation_count <= 0:
                    return
                reason_text = (
                    reason if isinstance(reason, str) and reason.strip() else fallback
                )
                bounded_reason = self._bounded_diagnostic_log_text(reason_text)
                if bounded_reason in accounted_child_unattempted_reason_counts:
                    accounted_child_unattempted_reason_counts[
                        bounded_reason
                    ] += operation_count
                elif (
                    len(accounted_child_unattempted_reason_counts)
                    < _DIAGNOSTIC_LOG_MAX_ITEMS
                ):
                    accounted_child_unattempted_reason_counts[bounded_reason] = (
                        operation_count
                    )
                else:
                    omitted_accounted_child_unattempted_operations += operation_count

            def bounded_child_errors(
                raw_result: Dict[str, Any],
                raw_context: Dict[str, Any],
                wrapper_result: Dict[str, Any],
            ) -> Tuple[List[str], bool]:
                """
                Return bounded child errors and whether any error was present.

                Only built-in strings, lists, and tuples are traversed. This
                prevents result aggregation from invoking attacker-controlled
                iteration while retaining a fixed number of sanitizer-safe
                messages from both legacy top-level and standardized context
                fields.

                Args:
                    raw_result: Child collector result mapping.
                    raw_context: Validated built-in child context mapping.
                    wrapper_result: Device wrapper mapping that may carry a
                        duplicate or additional child error field.

                Returns:
                    A tuple containing bounded, deduplicated messages and a flag
                    indicating whether either child error field was non-empty.
                """
                messages: List[str] = []
                has_errors = False
                for source in (
                    raw_result.get("error_messages"),
                    raw_context.get("error_messages"),
                    (
                        wrapper_result.get("error_messages")
                        if wrapper_result is not raw_result
                        else None
                    ),
                ):
                    if type(source) is str:
                        source_items = [source]
                    elif type(source) in {list, tuple}:
                        source_items = source[:_DIAGNOSTIC_LOG_MAX_ITEMS]
                    elif source is None:
                        source_items = []
                    else:
                        source_items = []
                        has_errors = True
                    if source_items:
                        has_errors = True
                    for item in source_items:
                        bounded = self._bounded_diagnostic_log_text(item)
                        if bounded and bounded not in messages:
                            messages.append(bounded)
                            if len(messages) >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                                break
                    if len(messages) >= _DIAGNOSTIC_LOG_MAX_ITEMS:
                        break
                return messages, has_errors

            for task_result in all_task_results:
                # Extract ActionInfo-aware metadata first for conditional processing
                is_in_action_info = task_result.get("is_in_action_info", True)
                oem_diag_type = task_result.get("oem_diag_type", "")
                system_id = task_result.get("system_id", "unknown")
                task_uses_action_info = task_result.get(
                    "use_action_info_validation",
                    use_action_info_validation and system_id in action_info_by_system,
                )
                artifact_validation_failed = task_result.get(
                    "artifact_validation_failed", False
                )
                raw_result = task_result.get("raw_result", task_result)
                if not isinstance(raw_result, dict):
                    raw_result = {
                        "success": False,
                        "status": "error",
                        "reason": "Child diagnostic result is not a mapping",
                    }
                raw_context = raw_result.get("context", {})
                if not isinstance(raw_context, dict):
                    raw_context = {}
                child_error_messages, child_has_errors = bounded_child_errors(
                    raw_result,
                    raw_context,
                    task_result,
                )
                raw_status = raw_result.get(
                    "status",
                    task_result.get(
                        "status",
                        (
                            "success"
                            if raw_result.get(
                                "success",
                                task_result.get("success", False),
                            )
                            else "error"
                        ),
                    ),
                )
                diagnostic_domain_block = task_result.get("diagnostic_domain_block")
                blocked_before_post = bool(
                    isinstance(diagnostic_domain_block, dict)
                    and task_result.get("diagnostic_domain_blocked_before_post") is True
                    and diagnostic_domain_block.get("blocked_before_post") is True
                    and diagnostic_domain_block.get("post_sent") is False
                )
                attempted_domain_rejection = bool(
                    isinstance(diagnostic_domain_block, dict)
                    and diagnostic_domain_block.get("remote_rejection") is True
                    and diagnostic_domain_block.get("resubmit_allowed") is False
                    and diagnostic_domain_block.get("blocked_before_post") is False
                    and diagnostic_domain_block.get("post_sent") is True
                )

                raw_successful_operations = raw_context.get("successful_operations")
                raw_total_operations = raw_context.get("total_operations")
                payload_results = raw_context.get("payload_results")
                child_output_sources = (
                    raw_result.get("output_files"),
                    raw_context.get("output_files"),
                    task_result.get("output_files"),
                )
                child_outputs_affirmatively_empty = all(
                    source is None or (type(source) in {list, tuple} and not source)
                    for source in child_output_sources
                )
                affirmative_zero_child_work = bool(
                    type(raw_successful_operations) is int
                    and raw_successful_operations == 0
                    and type(raw_total_operations) is int
                    and raw_total_operations == 0
                    and type(payload_results) is list
                    and not payload_results
                    and child_outputs_affirmatively_empty
                    and not child_has_errors
                    and not artifact_validation_failed
                )
                pure_blocked_before_post = bool(
                    blocked_before_post
                    and raw_status == "skipped"
                    and affirmative_zero_child_work
                )
                if isinstance(diagnostic_domain_block, dict):
                    diagnostic_domain_gate_results.append(task_result)
                    suppressed_tasks = max(
                        0,
                        int(task_result.get("diagnostic_domain_suppressed_tasks", 0)),
                    )
                    suppressed_device_task_count += suppressed_tasks
                    gate_unattempted_tasks = suppressed_tasks + (
                        1 if pure_blocked_before_post else 0
                    )
                    record_unattempted_reason(
                        diagnostic_domain_block.get("reason"),
                        gate_unattempted_tasks,
                        (
                            "Diagnostic domain is blocked by a prior task; "
                            "no POST was sent"
                        ),
                    )
                if pure_blocked_before_post:
                    blocked_before_post_task_count += 1
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[Results] {task_result['device_type']}_{task_result['device_id']} "
                        f"on {system_id} was not attempted because the diagnostic "
                        "domain is blocked",
                        dut_id,
                    )
                    continue

                if blocked_before_post:
                    # A typed pre-POST block does not prove the whole child was
                    # unattempted. Required-payload children can complete one or
                    # more operations before the gate closes. Their standardized
                    # total already includes the suppressed operations, so retain
                    # the evidence without adding it to the denominator again.
                    blocked_after_attempt_task_count += 1
                    raw_suppressed_operations = raw_context.get(
                        "suppressed_required_operations"
                    )
                    if (
                        type(raw_suppressed_operations) is int
                        and raw_suppressed_operations > 0
                    ):
                        child_unattempted_operations = raw_suppressed_operations
                    else:
                        blocked_entities = raw_context.get(
                            "diagnostic_domain_blocked_entities"
                        )
                        if type(blocked_entities) is list and blocked_entities:
                            child_unattempted_operations = len(blocked_entities)
                        else:
                            # The typed block proves at least the current POST
                            # was suppressed even when an older child omitted
                            # the more precise accounting fields.
                            child_unattempted_operations = 1
                    accounted_child_unattempted_operation_count += (
                        child_unattempted_operations
                    )
                    record_accounted_child_unattempted_reason(
                        diagnostic_domain_block.get("reason"),
                        child_unattempted_operations,
                        (
                            "Diagnostic domain closed after earlier child work; "
                            "remaining child POSTs were not sent"
                        ),
                    )

                intentional_capability_skip = bool(
                    self._is_affirmative_capability_no_post_child(
                        raw_result,
                        system_id,
                    )
                    and affirmative_zero_child_work
                    and not attempted_domain_rejection
                )
                if intentional_capability_skip:
                    intentional_skipped_task_count += 1
                    skip_reason = raw_result.get("reason") or raw_context.get("reason")
                    record_unattempted_reason(
                        skip_reason,
                        1,
                        (
                            "Child diagnostic collection was intentionally "
                            "skipped; no POST was sent"
                        ),
                    )
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[Results] {task_result['device_type']}_{task_result['device_id']} "
                        f"on {system_id} was intentionally skipped before a "
                        "diagnostic POST",
                        dut_id,
                    )
                    continue

                attempted_device_task_count += 1
                result_for_processing = raw_result
                if raw_status == "skipped":
                    if child_error_messages:
                        incompatible_skip_reason = "; ".join(child_error_messages)
                    elif child_has_errors:
                        incompatible_skip_reason = (
                            "Child diagnostic collection returned non-text errors"
                        )
                    else:
                        incompatible_skip_reason = (
                            "Child diagnostic collection returned skipped without "
                            "affirmative no-POST evidence"
                        )
                    result_for_processing = {
                        **raw_result,
                        "success": False,
                        "status": "error",
                        "reason": self._bounded_diagnostic_log_text(
                            incompatible_skip_reason
                        ),
                    }
                    raw_status = "error"

                child_counts_valid = bool(
                    type(raw_successful_operations) is int
                    and type(raw_total_operations) is int
                    and raw_total_operations > 0
                    and 0 <= raw_successful_operations <= raw_total_operations
                )
                if child_counts_valid:
                    child_successful_operations = raw_successful_operations
                    child_total_operations = raw_total_operations
                elif raw_status == "partial":
                    # A partial child without usable counts still proves at
                    # least one success and one failure.
                    child_successful_operations = 1
                    child_total_operations = 2
                elif raw_status in {"success", "degraded"} and not child_has_errors:
                    child_successful_operations = 1
                    child_total_operations = 1
                else:
                    child_successful_operations = 0
                    child_total_operations = 1

                if raw_status == "degraded":
                    degraded_device_task_count += 1
                    degraded_reason = raw_result.get("reason") or raw_context.get(
                        "reason"
                    )
                    if isinstance(degraded_reason, str) and degraded_reason.strip():
                        bounded_degraded_reason = self._bounded_diagnostic_log_text(
                            degraded_reason
                        )
                        if (
                            bounded_degraded_reason not in degraded_child_reasons
                            and len(degraded_child_reasons) < _DIAGNOSTIC_LOG_MAX_ITEMS
                        ):
                            degraded_child_reasons.append(bounded_degraded_reason)

                child_failed_operations = (
                    child_total_operations - child_successful_operations
                )
                requires_non_success_accounting = bool(
                    raw_status not in {"success", "degraded"}
                    or (child_has_errors and raw_status != "degraded")
                    or artifact_validation_failed
                )
                if requires_non_success_accounting and child_failed_operations == 0:
                    # Preserve an affirmative child success count, but add one
                    # failed logical operation when terminal status, child
                    # errors, or artifact validation proves that 1/1 cannot be
                    # the complete truth. Explicit degraded results remain
                    # complete-but-degraded and are preserved below.
                    child_total_operations += 1
                    child_failed_operations = 1
                aggregated_successful_operations += child_successful_operations
                aggregated_total_operations += child_total_operations
                collection_success = bool(
                    raw_status == "success"
                    and child_successful_operations == child_total_operations
                    and not child_has_errors
                    and not artifact_validation_failed
                )

                unadvertised_attempted_failure = bool(
                    task_uses_action_info
                    and not collection_success
                    and not is_in_action_info
                    and not attempted_domain_rejection
                )

                if attempted_domain_rejection and not is_in_action_info:
                    unadvertised_attempted_domain_rejections += 1

                if unadvertised_attempted_failure:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        f"[ActionInfo] Attempted failure for {task_result['device_type']}_{task_result['device_id']} "
                        f"on {system_id} - '{oem_diag_type}' was not in ActionInfo; "
                        "the attempted POST remains status-contributing",
                        dut_id,
                    )

                # Retain common output/error-log side effects, but aggregate
                # operation counts and child errors from the standardized child
                # result rather than its lossy outer boolean projection.
                processed_output_files: List[str] = []
                processed_status_list: List[bool] = []
                processed_error_messages: List[str] = []
                await self._process_collector_result(
                    result=result_for_processing,
                    all_output_files=processed_output_files,
                    all_status_list=processed_status_list,
                    error_messages=processed_error_messages,
                    entity_type=task_result["device_type"],
                    entity_id=task_result["device_id"],
                    dut_id=dut_id,
                    collector_id=collector_id,
                )

                raw_output_files: List[str] = []
                for source in (
                    raw_result.get("output_files"),
                    raw_context.get("output_files"),
                    processed_output_files,
                ):
                    if type(source) in {list, tuple}:
                        for file_path in source:
                            if (
                                isinstance(file_path, str)
                                and file_path
                                and file_path not in raw_output_files
                            ):
                                raw_output_files.append(file_path)
                for file_path in raw_output_files:
                    if file_path not in all_output_files:
                        all_output_files.append(file_path)

                entity_prefix = (
                    f"{task_result['device_type']} {task_result['device_id']}: "
                )
                retained_processed_errors = processed_error_messages
                if attempted_domain_rejection:
                    # Preserve device provenance for the lock-winning remote
                    # rejection even when a test double or legacy processor
                    # projected its child reason without an entity prefix.
                    retained_processed_errors = [
                        message
                        for message in processed_error_messages
                        if message not in child_error_messages
                    ]
                error_messages.extend(retained_processed_errors)
                for message in child_error_messages:
                    prefixed_message = f"{entity_prefix}{message}"
                    if (
                        attempted_domain_rejection
                        or message not in retained_processed_errors
                    ) and prefixed_message not in retained_processed_errors:
                        error_messages.append(prefixed_message)
                if artifact_validation_failed:
                    artifact_validation_errors = task_result.get(
                        "artifact_validation_errors"
                    )
                    if type(artifact_validation_errors) not in {list, tuple}:
                        artifact_validation_errors = []
                    for message in artifact_validation_errors[
                        :_DIAGNOSTIC_LOG_MAX_ITEMS
                    ]:
                        validation_message = (
                            f"{entity_prefix}"
                            f"{self._bounded_diagnostic_log_text(message)}"
                        )
                        if validation_message not in error_messages:
                            error_messages.append(validation_message)

                # Track ActionInfo-aware results for metrics
                if (
                    task_uses_action_info
                    and is_in_action_info
                    and not attempted_domain_rejection
                ):
                    action_info_results["validated_tasks"] += child_total_operations
                    action_info_results[
                        "expected_successes"
                    ] += child_successful_operations
                    action_info_results["expected_failures"] += child_failed_operations
                    if artifact_validation_failed:
                        action_info_results["expected_validation_failures"] += 1
                elif task_uses_action_info and collection_success:
                    action_info_results["validated_tasks"] += child_total_operations
                    action_info_results[
                        "bonus_successes"
                    ] += child_successful_operations
                else:
                    action_info_results["unvalidated_tasks"] += child_total_operations
                    if task_uses_action_info and not is_in_action_info:
                        action_info_results["unexpected_failures"] += max(
                            1,
                            child_failed_operations,
                        )

                # Populate dump query map for successful collections
                if collection_success and oem_diag_type:
                    artifact_root = getattr(self.logger, "base_log_dir", None)
                    primary_task_files = [
                        file_path
                        for file_path in raw_output_files
                        if file_path
                        and not self._is_diagnostic_capture_file(
                            file_path,
                            bundle_root=artifact_root,
                        )
                    ]
                    if primary_task_files:
                        dump_query_map.setdefault(system_id, {})[oem_diag_type] = [
                            os.path.basename(file_path)
                            for file_path in primary_task_files
                        ]
                        requirements = task_result.get(
                            "system_dump_member_requirements"
                        )
                        if requirements:
                            system_dump_device_coverage.setdefault(system_id, {})[
                                oem_diag_type
                            ] = copy.deepcopy(requirements)

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"[Results] {task_result['device_type']}_{task_result['device_id']} "
                    f"on {system_id}: success={collection_success}",
                    dut_id,
                )

            # Write dump query map JSON if any successful collections were made
            if dump_query_map:
                map_data = {
                    "collector_id": collector_id,
                    "collector_name": collector_name
                    or kwargs.get("collector_name", ""),
                    "generated_at": datetime.now().isoformat(),
                    "mappings": dump_query_map,
                }
                if system_dump_device_coverage:
                    map_data["system_dump_device_coverage"] = (
                        system_dump_device_coverage
                    )
                if authoritative_capability_evidence is not None:
                    map_data["capability_evidence"] = authoritative_capability_evidence
                map_filename = f"{collector_id}_dump_query_map.json"
                map_file_path = await self._save_data_to_file_with_pattern(
                    dut_id,
                    map_data,
                    map_filename,
                    collector_id=collector_id,
                )
                if map_file_path:
                    all_output_files.append(map_file_path)

            # Calculate overall success
            successful_operations = aggregated_successful_operations
            total_operations = aggregated_total_operations
            unattempted_device_task_count = (
                intentional_skipped_task_count
                + blocked_before_post_task_count
                + suppressed_device_task_count
            )

            # ActionInfo-aware success calculation. Any attempted result that
            # cannot be validated against ActionInfo disables denominator
            # replacement so a real failed POST remains status-contributing.
            action_info_adjusted_success = successful_operations
            action_info_adjusted_total = total_operations

            if (
                use_action_info_validation
                and action_info_results["action_info_available"]
                and not action_info_results["unvalidated_tasks"]
                and not invalid_capability_system_ids
            ):
                # Calculate expected total (items that were in ActionInfo)
                expected_total = (
                    action_info_results["expected_successes"]
                    + action_info_results["expected_failures"]
                )

                if expected_total > 0:
                    action_info_adjusted_success = action_info_results[
                        "expected_successes"
                    ]
                    action_info_adjusted_total = expected_total

                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[ActionInfo] Adjusted success rate: {action_info_adjusted_success}/{action_info_adjusted_total} "
                        f"(original: {successful_operations}/{total_operations}, "
                        f"unexpected_failures_excluded: {action_info_results['unexpected_failures']}, "
                        f"bonus_successes: {action_info_results['bonus_successes']})",
                        dut_id,
                    )

            if total_operations and unattempted_device_task_count:
                action_info_adjusted_total += unattempted_device_task_count

            # Check whether task construction produced anything actionable.  Some
            # platform actions (for example Vera C2's system-level SMA dump) use a
            # configured ``device_ids_override`` and intentionally bypass inventory
            # discovery, so an empty ``discovered_devices`` map is not sufficient to
            # declare the collector a no-op.
            total_devices = total_tasks
            if total_tasks == 0:
                no_device_reason = f"No {list(discovered_devices.keys())} devices discovered for {collector_name}"
                if complete_on_empty_targets:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"=== Device diagnostic collection complete. {no_device_reason} - treating as complete ===",
                        dut_id,
                    )
                    result = await self._create_standardized_collector_result(
                        successful_operations=1,
                        total_operations=1,
                        output_files=[],
                        error_messages=[],
                        operation_name="device_diagnostic_data",
                        additional_context={
                            "collector_name": collector_name,
                            "target_baseboard": target_baseboard,
                            "devices_processed": 0,
                            "successful_collections": 1,
                            "total_collections": 1,
                            "reason": f"{no_device_reason} - nothing to collect (expected)",
                            "diagnostic_work_projection": diagnostic_work_projection,
                        },
                    )
                    empty_reason = f"{no_device_reason} - nothing to collect (expected)"
                    result["reason"] = empty_reason
                    result.setdefault("context", {})["reason"] = empty_reason
                    return result
                else:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"=== Device diagnostic collection complete. {no_device_reason} - treating as skipped ===",
                        dut_id,
                    )
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=0,
                        output_files=[],
                        error_messages=[],
                        operation_name="device_diagnostic_data",
                        additional_context={
                            "collector_name": collector_name,
                            "target_baseboard": target_baseboard,
                            "devices_processed": 0,
                            "successful_collections": 0,
                            "total_collections": 0,
                            "status": "skipped",
                            "reason": f"{no_device_reason} - collector skipped",
                            "diagnostic_work_projection": diagnostic_work_projection,
                        },
                    )

            # Log completion with ActionInfo-aware metrics if enabled
            if (
                use_action_info_validation
                and action_info_results["action_info_available"]
                and not action_info_results["unvalidated_tasks"]
                and not invalid_capability_system_ids
            ):
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"=== Device diagnostic collection complete. ActionInfo-adjusted: {action_info_adjusted_success}/{action_info_adjusted_total}, "
                    f"Raw: {successful_operations}/{total_operations}, Files: {len(all_output_files)} ===",
                    dut_id,
                )
            else:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"=== Device diagnostic collection complete. Success: {successful_operations}/{total_operations}, Files: {len(all_output_files)} ===",
                    dut_id,
                )

            # Build additional context with ActionInfo results if available
            additional_context = {
                "collector_name": collector_name,
                "target_baseboard": target_baseboard,
                "devices_processed": total_devices,
                "successful_collections": successful_operations,
                "total_collections": (
                    total_operations + unattempted_device_task_count
                    if total_operations
                    else 0
                ),
                "diagnostic_work_projection": diagnostic_work_projection,
            }

            if unattempted_device_task_count:
                unattempted_reason_evidence = [
                    {
                        "task_count": task_count,
                        "reason": reason,
                    }
                    for reason, task_count in unattempted_reason_counts.items()
                ]
                if omitted_unattempted_reason_tasks:
                    unattempted_reason_evidence.append(
                        {
                            "task_count": omitted_unattempted_reason_tasks,
                            "reason": "additional reason classes omitted",
                        }
                    )
                additional_context.update(
                    {
                        "unattempted_device_tasks": unattempted_device_task_count,
                        "attempted_device_tasks": attempted_device_task_count,
                        "intentional_skipped_device_tasks": (
                            intentional_skipped_task_count
                        ),
                        "unattempted_reason_evidence": unattempted_reason_evidence,
                    }
                )

            if diagnostic_domain_gate_results:
                attempted_gate_results = [
                    task_result
                    for task_result in diagnostic_domain_gate_results
                    if task_result["diagnostic_domain_block"].get("post_sent") is True
                    and task_result["diagnostic_domain_block"].get(
                        "blocked_before_post"
                    )
                    is False
                ]
                primary_gate_result = (
                    attempted_gate_results[0]
                    if attempted_gate_results
                    else diagnostic_domain_gate_results[0]
                )
                first_domain_block = primary_gate_result["diagnostic_domain_block"]
                additional_context.update(
                    {
                        "diagnostic_domain_block": first_domain_block,
                        "diagnostic_domain_blocked_before_post_tasks": (
                            blocked_before_post_task_count
                        ),
                        "diagnostic_domain_blocked_after_attempt_tasks": (
                            blocked_after_attempt_task_count
                        ),
                        "diagnostic_domain_suppressed_tasks": (
                            suppressed_device_task_count
                        ),
                    }
                )
                if accounted_child_unattempted_operation_count:
                    accounted_reason_evidence = [
                        {
                            "operation_count": operation_count,
                            "reason": reason,
                        }
                        for reason, operation_count in (
                            accounted_child_unattempted_reason_counts.items()
                        )
                    ]
                    if omitted_accounted_child_unattempted_operations:
                        accounted_reason_evidence.append(
                            {
                                "operation_count": (
                                    omitted_accounted_child_unattempted_operations
                                ),
                                "reason": "additional reason classes omitted",
                            }
                        )
                    additional_context.update(
                        {
                            "diagnostic_domain_accounted_unattempted_operations": (
                                accounted_child_unattempted_operation_count
                            ),
                            "diagnostic_domain_accounted_unattempted_reason_evidence": (
                                accounted_reason_evidence
                            ),
                        }
                    )

            if (
                attempted_device_task_count == 0
                and total_operations == 0
                and unattempted_device_task_count
            ):
                additional_context.update(
                    {
                        "status": "skipped",
                        "intentional_evidence_only_skip": True,
                        "reason": format_unattempted_reason(
                            "No device diagnostic POST was attempted; "
                            f"{unattempted_device_task_count} task(s) were "
                            "skipped before POST."
                        ),
                    }
                )
            elif (
                total_operations > 0
                and action_info_adjusted_success < action_info_adjusted_total
                and (
                    unattempted_device_task_count
                    or accounted_child_unattempted_operation_count
                )
                and not error_messages
            ):
                unattempted_summary_parts = []
                if unattempted_device_task_count:
                    unattempted_summary_parts.append(
                        f"{unattempted_device_task_count} outer task(s)"
                    )
                if accounted_child_unattempted_operation_count:
                    unattempted_summary_parts.append(
                        f"{accounted_child_unattempted_operation_count} child "
                        "operation(s) already represented in the denominator"
                    )
                additional_context.update(
                    {
                        "status": "partial",
                        "reason": format_unattempted_reason(
                            "Partial success: "
                            f"{action_info_adjusted_success}/"
                            f"{action_info_adjusted_total} device_diagnostic_data "
                            "succeeded; "
                            f"{' and '.join(unattempted_summary_parts)} were not "
                            "attempted."
                        ),
                    }
                )
            elif (
                degraded_device_task_count
                and action_info_adjusted_total > 0
                and action_info_adjusted_success == action_info_adjusted_total
                and not unattempted_device_task_count
            ):
                degraded_reason = (
                    "; ".join(degraded_child_reasons)
                    if degraded_child_reasons
                    else "Usable device diagnostic data was collected with a bounded issue"
                )
                additional_context.update(
                    {
                        "status": "degraded",
                        "reason": self._bounded_diagnostic_log_text(degraded_reason),
                        "degraded_device_tasks": degraded_device_task_count,
                    }
                )

            if use_action_info_validation:
                additional_context["action_info_validation"] = {
                    "enabled": True,
                    "action_info_available": action_info_results[
                        "action_info_available"
                    ],
                    "expected_successes": action_info_results["expected_successes"],
                    "expected_failures": action_info_results["expected_failures"],
                    "expected_validation_failures": action_info_results[
                        "expected_validation_failures"
                    ],
                    "unexpected_failures": action_info_results["unexpected_failures"],
                    "unadvertised_attempted_domain_rejections": (
                        unadvertised_attempted_domain_rejections
                    ),
                    "bonus_successes": action_info_results["bonus_successes"],
                    "intentional_skipped_tasks": intentional_skipped_task_count,
                    "validated_tasks": action_info_results["validated_tasks"],
                    "unvalidated_tasks": action_info_results["unvalidated_tasks"],
                    "adjusted_success": action_info_adjusted_success,
                    "adjusted_total": action_info_adjusted_total,
                }

            if capability_resolution is not None:
                additional_context["capability_routing"] = capability_routing_context

            return await self._create_standardized_collector_result(
                successful_operations=action_info_adjusted_success,
                total_operations=action_info_adjusted_total,
                output_files=all_output_files,
                error_messages=error_messages,
                operation_name="device_diagnostic_data",
                additional_context=additional_context,
            )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_device_diagnostic_data: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Exception in device diagnostic collection: {str(e)}"],
                operation_name="device_diagnostic_data",
                additional_context={
                    "collector_name": collector_name,
                    "error_type": type(e).__name__,
                },
            )

    async def collect_multi_step_collection(
        self,
        dut_id: str,
        function_tag: str,
        collection_config: Dict[str, Any],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Generic multi-step collection method for complex collection patterns.

        After applying local validation, the function forwards ``dut_id``,
        ``function_tag``, ``collection_config``, and ``kwargs`` to
        ``self._execute_with_error_handling`` and preserves its return and
        exception contract. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            collection_config: Collection config governing generic multi-step
                collection method for complex collection patterns.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing multi step collection.
        """

        async def _multi_step_collection():
            # Get collector context for better logging
            """
            Return the multi step collection.

            The implementation uses current instance state to produce the multi
            step collection. Owned asynchronous work is awaited before return,
            so completion does not leave an unobserved task behind.

            Returns:
                The multi step collection.

            Raises:
                ValueError: If the catalog selects an unsupported optional
                    resource policy.
            """
            collector_id = kwargs.get("collector_id", function_tag)

            await self._log_collection_start(dut_id, "multi-step", function_tag)

            # Extract configuration
            dut_config = (
                self.dut_manager.get_dut_config(dut_id) if self.dut_manager else {}
            )
            target_baseboard = dut_config.get(
                "TargetBaseboard", dut_config.get("baseboard", "")
            )
            effective_collection_config = collection_config
            baseboard_specific_config = effective_collection_config.get(
                "baseboard_specific_config", {}
            )
            if (
                baseboard_specific_config
                and target_baseboard in baseboard_specific_config
            ):
                effective_collection_config = self._deep_merge_config(
                    effective_collection_config,
                    baseboard_specific_config[target_baseboard],
                )
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using baseboard-specific multi-step config for {target_baseboard}",
                    dut_id,
                )

            entity_type = effective_collection_config.get("entity_type", "Chassis")
            base_uri_pattern = effective_collection_config.get("base_uri_pattern", "")
            steps = effective_collection_config.get("steps", [])
            skip_if_no_matching_members = bool(
                effective_collection_config.get("skip_if_no_matching_members", False)
            )
            complete_on_empty_matches = bool(
                effective_collection_config.get("complete_on_empty_matches", False)
            )

            optional_resource_policy = effective_collection_config.get(
                "optional_resource_policy"
            )
            if optional_resource_policy not in (None, "skip_missing"):
                raise ValueError("Unsupported optional resource policy")
            resource_failures: List[str] = []
            optional_resource_absences = 0

            async def _request_resource(request_dut_id, method, uri, **options):
                """
                Retain failures while permitting explicitly expected absence.

                The catalog opt-in distinguishes optional HTTP 404 probes from
                authentication, transport, malformed-body and advertised-member
                failures. Invalid resource objects retain their response evidence
                but are rejected before traversal or primary publication.

                Args:
                    request_dut_id: DUT owning the request and its diagnostics.
                    method: HTTP method passed to the transport boundary.
                    uri: Validated resource URI selected by the collection plan.
                    options: Existing request deadlines and expected statuses.

                Returns:
                    The response body and metadata with a success flag that also
                    requires a valid resource object for the opted-in policy.
                """

                nonlocal optional_resource_absences

                result = await self.dispatch_request(
                    request_dut_id, method, uri, **options
                )
                if optional_resource_policy == "skip_missing":
                    ok, payload, metadata = result
                    status = self._http_status_from_response(payload, metadata)
                    expected = options.get("expected_http_statuses") or ()
                    expected_absence = not ok and status == 404 and 404 in expected
                    if expected_absence:
                        optional_resource_absences += 1
                    if not ok and not expected_absence:
                        resource_failures.append(
                            f"Resource request failed for {uri} "
                            f"(HTTP {status if status is not None else 'unavailable'})"
                        )
                    elif ok and (not isinstance(payload, dict) or not payload):
                        resource_failures.append(
                            f"Resource request returned an invalid resource object: {uri}"
                        )
                        return False, payload, metadata
                return result

            async def _publish_resource(request_dut_id, data, tag, **options):
                """
                Prevent failed publication from becoming an absence outcome.

                Publication errors remain subject to the caller's existing
                exception handling and also enter the opted-in result evidence.

                Args:
                    request_dut_id: DUT owning the collected artifact.
                    data: Response payload passed unchanged to the publisher.
                    tag: Operation name used for the artifact's provenance.
                    options: Existing output and request-timing metadata.

                Returns:
                    The published artifact path, or the publisher's empty value.

                Raises:
                    Exception: If the existing publisher raises an error.
                """

                try:
                    published = await self._save_data_with_common_pattern(
                        request_dut_id, data, tag, **options
                    )
                except Exception:
                    if optional_resource_policy == "skip_missing":
                        resource_failures.append("Resource artifact publication failed")
                    raise
                if optional_resource_policy == "skip_missing" and not published:
                    resource_failures.append("Resource artifact was not published")
                return published

            # Apply prefix override if URI config manager is available
            if (
                base_uri_pattern
                and self.dut_manager
                and self.dut_manager.uri_config_manager
            ):
                base_uri_pattern = (
                    self.dut_manager.uri_config_manager._apply_prefix_override(
                        base_uri_pattern, dut_id
                    )
                )
            collector_id = kwargs.get(
                "collector_id", ""
            )  # Extract collector_id from kwargs

            # Prefer filtered entities from validation when available to avoid
            # probing unrelated Redfish resources during multi-step collection.
            filtered_systems = kwargs.get("filtered_systems", [])
            filtered_managers = kwargs.get("filtered_managers", [])
            filtered_chassis = kwargs.get("filtered_chassis", [])

            entity_ids = []
            success = True
            entities_response = {}

            # Get entities to process
            if entity_type == "Chassis":
                entity_key = "chassis_id"
                if filtered_chassis:
                    entity_ids = [chassis["id"] for chassis in filtered_chassis]
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using {len(entity_ids)} filtered chassis from validation: {entity_ids}",
                        dut_id,
                    )
                else:
                    chassis_uri = self.get_configured_uri(dut_id, "Chassis")
                    success, entities_response, _ = await _request_resource(
                        dut_id, "GET", chassis_uri, bypass_cache=True
                    )
            elif entity_type == "Systems":
                entity_key = "system_id"
                if filtered_systems:
                    entity_ids = [system["id"] for system in filtered_systems]
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using {len(entity_ids)} filtered systems from validation: {entity_ids}",
                        dut_id,
                    )
                else:
                    systems_uri = self.get_configured_uri(dut_id, "Systems")
                    success, entities_response, _ = await _request_resource(
                        dut_id, "GET", systems_uri, bypass_cache=True
                    )
            elif entity_type == "Managers":
                entity_key = "manager_id"
                if filtered_managers:
                    entity_ids = [manager["id"] for manager in filtered_managers]
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using {len(entity_ids)} filtered managers from validation: {entity_ids}",
                        dut_id,
                    )
                else:
                    managers_uri = self.get_configured_uri(dut_id, "Managers")
                    success, entities_response, _ = await _request_resource(
                        dut_id, "GET", managers_uri, bypass_cache=True
                    )
            else:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[f"Unsupported entity type: {entity_type}"],
                    operation_name="multi_step_collection",
                    additional_context={"entity_type": entity_type},
                )

            if not success:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=1,
                    output_files=[],
                    error_messages=[
                        f"Failed to get {entity_type}: {entities_response}"
                    ],
                    operation_name="multi_step_collection",
                    additional_context={"entity_type": entity_type},
                )

            # Extract entity IDs when validation did not already provide them.
            if not entity_ids:
                entities = entities_response.get("Members", [])
                for entity in entities:
                    entity_id = entity.get("@odata.id", "").split("/")[-1]
                    if entity_id:
                        entity_ids.append(entity_id)

            if not entity_ids:
                if complete_on_empty_matches:
                    reason = (
                        f"No {entity_type} targets found for {function_tag}; "
                        "empty discovery completed successfully"
                    )
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=0,
                        output_files=[],
                        error_messages=[],
                        operation_name="multi_step_collection",
                        additional_context={
                            "message": f"No {entity_type} found",
                            "entity_type": entity_type,
                            "status": "success",
                            "reason": reason,
                        },
                    )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="multi_step_collection",
                    additional_context={
                        "message": f"No {entity_type} found",
                        "entity_type": entity_type,
                    },
                )

            output_files = []
            status_list = []
            error_messages = []
            successful_operations = 0
            total_operations = 0
            matching_members_collected = 0
            matching_member_fetch_failures = []
            required_empty_body_failures = []

            # Process each entity
            for entity_id in entity_ids:
                entity_failure_start = len(resource_failures)
                total_operations += 1
                entity_success = True
                step_responses = {}  # Store responses for URI pattern substitution

                # Initialize step_responses with entity_id
                step_responses[entity_key] = entity_id

                # Execute each step
                for step in steps:
                    step_name = step.get("name", "unknown_step")
                    uri_pattern = step.get("uri_pattern", "")
                    output_pattern = step.get("output_pattern", "")
                    required = step.get("required", False)
                    fallback_patterns = step.get("fallback_patterns", [])
                    follow_links = step.get("follow_links", False)
                    link_path = step.get("link_path", "")
                    member_processing = step.get("member_processing", {})
                    filter_collection_members = bool(
                        member_processing.get("filter_collection_members", False)
                    )

                    # Check if required variables are available before substitution
                    missing_vars = []
                    for var_name in re.findall(r"\{([^}]+)\}", uri_pattern):
                        if var_name not in step_responses:
                            missing_vars.append(var_name)

                    if missing_vars:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Skipping {step_name} for {entity_id}: missing variables {missing_vars} (previous step likely failed)",
                            dut_id,
                        )
                        if required:
                            entity_success = False
                        continue

                    # Substitute variables in URI pattern using VariableSubstitutionService
                    try:
                        uri = await self.substitute_variables(
                            uri_pattern, step_responses, dut_id
                        )
                    except Exception as e:
                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            f"Variable substitution failed for {step_name}: {str(e)}. Skipping step.",
                            dut_id,
                        )
                        if required:
                            entity_success = False
                        continue

                    # Try main URI
                    (
                        success,
                        response_data,
                        response_request_metadata,
                    ) = await _request_resource(
                        dut_id,
                        "GET",
                        uri,
                        expected_http_statuses=[404] if not required else None,
                    )
                    # The collection that advertised the members below is the
                    # URI this step actually requested, which the fallback loop
                    # may replace.
                    collection_request_uri = uri

                    # If main URI fails and fallbacks exist, try them
                    if not success and fallback_patterns:
                        for fallback_pattern in fallback_patterns:
                            fallback_uri = await self.substitute_variables(
                                fallback_pattern, step_responses, dut_id
                            )

                            (
                                success,
                                response_data,
                                response_request_metadata,
                            ) = await _request_resource(
                                dut_id,
                                "GET",
                                fallback_uri,
                                expected_http_statuses=(
                                    [404] if not required else None
                                ),
                            )
                            if success:
                                collection_request_uri = fallback_uri
                                await self._log_runtime(
                                    "INFO",
                                    "RedfishService",
                                    f"Used fallback URI for {step_name}: {fallback_uri}",
                                    dut_id,
                                )
                                break

                    if not success:
                        if required:
                            await self._log_runtime(
                                "ERROR",
                                "RedfishService",
                                f"Required step {step_name} failed for {entity_id}: {uri}",
                                dut_id,
                            )
                            entity_success = False
                        else:
                            await self._log_runtime(
                                "WARN",
                                "RedfishService",
                                f"Optional step {step_name} failed for {entity_id}: {uri}",
                                dut_id,
                            )
                        continue

                    if not self._has_meaningful_response_body(response_data):
                        empty_body_message = (
                            f"Step {step_name} returned an empty response body "
                            f"for {entity_id}: {uri}"
                        )
                        await self._log_runtime(
                            "ERROR" if required else "WARN",
                            "RedfishService",
                            empty_body_message,
                            dut_id,
                        )
                        if required:
                            entity_success = False
                            error_messages.append(empty_body_message)
                            required_empty_body_failures.append(empty_body_message)
                        continue

                    # Store response for next steps
                    step_responses[step_name] = response_data
                    response_request_token = self._request_timing_operation_id(
                        response_request_metadata
                    )

                    # Save step response
                    final_output_pattern = None
                    if output_pattern:
                        try:
                            # Substitute variables in output pattern using VariableSubstitutionService
                            final_output_pattern = await self.substitute_variables(
                                output_pattern, step_responses, dut_id
                            )

                            if not filter_collection_members:
                                file_path = await _publish_resource(
                                    dut_id,
                                    response_data,
                                    function_tag,
                                    output_pattern=final_output_pattern,
                                    substitutions=step_responses,
                                    collector_id=collector_id,
                                    request_timing_operation_ids=(
                                        response_request_token
                                    ),
                                )
                                if file_path:
                                    output_files.append(file_path)
                                    await self._log_runtime(
                                        "DEBUG",
                                        "RedfishService",
                                        f"Saved {step_name} data to: {file_path}",
                                        dut_id,
                                    )
                        except Exception as e:
                            await self._log_runtime(
                                "ERROR",
                                "RedfishService",
                                f"Failed to save {step_name} data: {str(e)}",
                                dut_id,
                            )

                    # Follow links if configured
                    if follow_links and link_path:
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Attempting to extract link from {link_path} in response for {step_name}",
                            dut_id,
                        )
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Response data keys: {list(response_data.keys()) if isinstance(response_data, dict) else 'not dict'}",
                            dut_id,
                        )

                        link_uri = self._extract_nested_value(response_data, link_path)
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Extract result for {link_path}: {link_uri}",
                            dut_id,
                        )
                        if link_uri:
                            step_responses[f"{step_name}_link"] = link_uri
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"Extracted link for {step_name}: {link_uri}",
                                dut_id,
                            )
                        else:
                            await self._log_runtime(
                                "WARN",
                                "RedfishService",
                                f"Could not extract link from {link_path} in response for {step_name}",
                                dut_id,
                            )

                    # Process members if configured
                    if member_processing and response_data.get("Members"):
                        raw_members = response_data.get("Members", [])
                        try:
                            members, source_count, truncated = (
                                bound_redfish_collection_members(
                                    raw_members,
                                    field_name=f"multi-step {step_name} Members",
                                    limit=self.MAX_FOLLOWED_COLLECTION_MEMBERS,
                                )
                            )
                        except ValueError:
                            members = []
                            error_messages.append(
                                f"Multi-step response {step_name} returned an "
                                "invalid Members list"
                            )
                        else:
                            if truncated:
                                error_messages.append(
                                    f"Multi-step response {step_name} advertised "
                                    f"{source_count} members; processing the first "
                                    f"{self.MAX_FOLLOWED_COLLECTION_MEMBERS} within "
                                    "the safe request-amplification limit"
                                )
                        member_uris = []
                        member_filters = member_processing.get("filters", {})
                        kept_member_uris = []
                        member_request_tokens = []

                        # Extract member URIs
                        for member in members:
                            member_uri = member.get("@odata.id")
                            if not member_uri or not validate_redfish_uri(member_uri):
                                continue
                            if not redfish_uri_is_collection_member(
                                member_uri, collection_request_uri
                            ):
                                await self._log_runtime(
                                    "WARN",
                                    "RedfishService",
                                    "Skipping advertised member that is not "
                                    f"beneath {collection_request_uri} for "
                                    f"{step_name}",
                                    dut_id,
                                )
                                continue
                            member_uris.append(member_uri)

                        # If no members found, try fallback member patterns
                        if not member_uris and member_processing.get(
                            "fallback_patterns"
                        ):
                            fallback_base = member_processing.get(
                                "fallback_base_uri", ""
                            )
                            fallback_patterns = member_processing.get(
                                "fallback_patterns", []
                            )

                            for fallback_pattern in fallback_patterns:
                                fallback_uri = fallback_base + fallback_pattern

                                # Check if required variables are available for fallback
                                missing_vars = []
                                for var_name in re.findall(
                                    r"\{([^}]+)\}", fallback_uri
                                ):
                                    if var_name not in step_responses:
                                        missing_vars.append(var_name)

                                if missing_vars:
                                    await self._log_runtime(
                                        "DEBUG",
                                        "RedfishService",
                                        f"Skipping fallback pattern {fallback_pattern}: missing variables {missing_vars}",
                                        dut_id,
                                    )
                                    continue

                                fallback_uri = await self.substitute_variables(
                                    fallback_uri, step_responses, dut_id
                                )

                                (
                                    success,
                                    fallback_response,
                                    fallback_request_metadata,
                                ) = await _request_resource(
                                    dut_id,
                                    "GET",
                                    fallback_uri,
                                    expected_http_statuses=[404],
                                )
                                if success:
                                    member_uris.append(fallback_uri)
                                    # Save fallback response
                                    fallback_output_pattern = member_processing.get(
                                        "fallback_output_pattern", ""
                                    )
                                    if fallback_output_pattern:
                                        final_fallback_pattern = (
                                            await self.substitute_variables(
                                                fallback_output_pattern,
                                                step_responses,
                                                dut_id,
                                            )
                                        )

                                        file_path = await _publish_resource(
                                            dut_id,
                                            fallback_response,
                                            function_tag,
                                            output_pattern=final_fallback_pattern,
                                            substitutions=step_responses,
                                            collector_id=collector_id,
                                            request_timing_operation_ids=self._request_timing_operation_id(
                                                fallback_request_metadata
                                            ),
                                        )
                                        if file_path:
                                            output_files.append(file_path)

                        # Process each member
                        for member_uri in member_uris:
                            uri_matches = (
                                self._member_uri_matches_filters(
                                    member_uri, member_filters
                                )
                                if skip_if_no_matching_members
                                else self._member_matches_filters(
                                    member_uri, None, member_filters
                                )
                            )
                            if not uri_matches:
                                continue

                            member_id = member_uri.split("/")[-1]
                            step_responses[f"{step_name}_member_id"] = member_id

                            (
                                success,
                                member_data,
                                member_request_metadata,
                            ) = await _request_resource(dut_id, "GET", member_uri)
                            member_request_token = self._request_timing_operation_id(
                                member_request_metadata
                            )
                            if member_request_token:
                                member_request_tokens.append(member_request_token)
                            if success:
                                if not self._member_matches_filters(
                                    member_uri, member_data, member_filters
                                ):
                                    continue

                                kept_member_uris.append(member_uri)
                                matching_members_collected += 1
                                filtered_member_data = self._apply_list_filters_to_data(
                                    member_data,
                                    member_processing.get("saved_data_filters", []),
                                )
                                # Save member data
                                member_output_pattern = member_processing.get(
                                    "member_output_pattern", ""
                                )
                                if member_output_pattern:
                                    final_member_pattern = (
                                        await self.substitute_variables(
                                            member_output_pattern,
                                            step_responses,
                                            dut_id,
                                        )
                                    )

                                    file_path = await _publish_resource(
                                        dut_id,
                                        filtered_member_data,
                                        function_tag,
                                        output_pattern=final_member_pattern,
                                        substitutions=step_responses,
                                        collector_id=collector_id,
                                        request_timing_operation_ids=member_request_token,
                                    )
                                    if file_path:
                                        output_files.append(file_path)

                                linked_member_resources = member_processing.get(
                                    "linked_member_resources", []
                                )

                                for linked_resource in linked_member_resources:
                                    link_name = linked_resource.get("name", "linked")
                                    link_path = linked_resource.get("link_path")
                                    linked_output_pattern = linked_resource.get(
                                        "member_output_pattern", ""
                                    )
                                    linked_filters = linked_resource.get("filters", {})
                                    member_id_variable = linked_resource.get(
                                        "member_id_variable",
                                        f"{link_name}_member_id",
                                    )
                                    member_uri_variable = linked_resource.get(
                                        "member_uri_variable",
                                        f"{link_name}_member_uri",
                                    )
                                    member_uri_path = linked_resource.get(
                                        "member_uri_path", "@odata.id"
                                    )

                                    linked_member_uris = (
                                        self._extract_member_uris_from_data(
                                            member_data,
                                            link_path,
                                            member_uri_path,
                                            truncation_messages=error_messages,
                                            field_name=(
                                                f"multi-step {step_name} linked "
                                                f"resource {link_name} Members"
                                            ),
                                        )
                                    )

                                    for linked_member_uri in linked_member_uris:
                                        uri_matches = (
                                            self._member_uri_matches_filters(
                                                linked_member_uri,
                                                linked_filters,
                                            )
                                            if skip_if_no_matching_members
                                            else self._member_matches_filters(
                                                linked_member_uri,
                                                None,
                                                linked_filters,
                                            )
                                        )
                                        if not uri_matches:
                                            continue

                                        linked_member_id = linked_member_uri.rstrip(
                                            "/"
                                        ).split("/")[-1]
                                        linked_substitutions = dict(step_responses)
                                        linked_substitutions[member_id_variable] = (
                                            linked_member_id
                                        )
                                        linked_substitutions[member_uri_variable] = (
                                            linked_member_uri
                                        )

                                        (
                                            success,
                                            linked_member_data,
                                            linked_request_metadata,
                                        ) = await _request_resource(
                                            dut_id, "GET", linked_member_uri
                                        )
                                        if success and self._member_matches_filters(
                                            linked_member_uri,
                                            linked_member_data,
                                            linked_filters,
                                        ):
                                            matching_members_collected += 1
                                            if linked_output_pattern:
                                                final_linked_pattern = (
                                                    await self.substitute_variables(
                                                        linked_output_pattern,
                                                        linked_substitutions,
                                                        dut_id,
                                                    )
                                                )

                                                file_path = await _publish_resource(
                                                    dut_id,
                                                    linked_member_data,
                                                    function_tag,
                                                    output_pattern=final_linked_pattern,
                                                    substitutions=linked_substitutions,
                                                    collector_id=collector_id,
                                                    request_timing_operation_ids=self._request_timing_operation_id(
                                                        linked_request_metadata
                                                    ),
                                                )
                                                if file_path:
                                                    output_files.append(file_path)
                                        elif (
                                            not success and skip_if_no_matching_members
                                        ):
                                            matching_member_fetch_failures.append(
                                                f"Failed to fetch matching member resource {linked_member_uri}"
                                            )

                                # Process member-related resources if configured
                                member_resources = member_processing.get(
                                    "member_resources", []
                                )

                                for resource in member_resources:
                                    resource_name = resource.get("name", "")
                                    resource_required = bool(
                                        resource.get("required", False)
                                    )
                                    resource_uri_pattern = resource.get(
                                        "uri_pattern", ""
                                    )
                                    resource_output_pattern = resource.get(
                                        "output_pattern", ""
                                    )

                                    if resource_uri_pattern and resource_output_pattern:
                                        # Check if required variables are available for resource
                                        missing_vars = []
                                        for var_name in re.findall(
                                            r"\{([^}]+)\}",
                                            resource_uri_pattern,
                                        ):
                                            if var_name not in step_responses:
                                                missing_vars.append(var_name)

                                        if missing_vars:
                                            await self._log_runtime(
                                                "DEBUG",
                                                "RedfishService",
                                                f"Skipping resource {resource_name}: missing variables {missing_vars}",
                                                dut_id,
                                            )
                                            continue

                                        resource_uri = await self.substitute_variables(
                                            resource_uri_pattern,
                                            step_responses,
                                            dut_id,
                                        )

                                        (
                                            success,
                                            resource_data,
                                            resource_request_metadata,
                                        ) = await _request_resource(
                                            dut_id,
                                            "GET",
                                            resource_uri,
                                            expected_http_statuses=(
                                                None if resource_required else [404]
                                            ),
                                        )
                                        if success:
                                            resource_request_token = (
                                                self._request_timing_operation_id(
                                                    resource_request_metadata
                                                )
                                            )
                                            resource_member_request_tokens = []
                                            final_resource_pattern = (
                                                await self.substitute_variables(
                                                    resource_output_pattern,
                                                    step_responses,
                                                    dut_id,
                                                )
                                            )

                                            file_path = await _publish_resource(
                                                dut_id,
                                                resource_data,
                                                function_tag,
                                                output_pattern=final_resource_pattern,
                                                substitutions=step_responses,
                                                collector_id=collector_id,
                                                request_timing_operation_ids=resource_request_token,
                                            )
                                            if file_path:
                                                output_files.append(file_path)

                                            resource_member_processing = resource.get(
                                                "member_processing", {}
                                            )
                                            if resource_member_processing:
                                                resource_filters = (
                                                    resource_member_processing.get(
                                                        "filters", {}
                                                    )
                                                )
                                                filter_collection_members = (
                                                    resource_member_processing.get(
                                                        "filter_collection_members",
                                                        False,
                                                    )
                                                )
                                                resource_member_output_pattern = (
                                                    resource_member_processing.get(
                                                        "member_output_pattern", ""
                                                    )
                                                )
                                                resource_member_id_variable = (
                                                    resource_member_processing.get(
                                                        "member_id_variable",
                                                        f"{resource_name}_member_id",
                                                    )
                                                )
                                                resource_member_uri_variable = (
                                                    resource_member_processing.get(
                                                        "member_uri_variable",
                                                        f"{resource_name}_member_uri",
                                                    )
                                                )
                                                resource_member_uri_path = (
                                                    resource_member_processing.get(
                                                        "member_uri_path",
                                                        "@odata.id",
                                                    )
                                                )
                                                resource_link_path = (
                                                    resource_member_processing.get(
                                                        "link_path", "Members"
                                                    )
                                                )

                                                resource_member_uris = (
                                                    self._extract_member_uris_from_data(
                                                        resource_data,
                                                        resource_link_path,
                                                        resource_member_uri_path,
                                                        truncation_messages=(
                                                            error_messages
                                                        ),
                                                        field_name=(
                                                            f"multi-step {step_name} "
                                                            f"resource {resource_name} "
                                                            "Members"
                                                        ),
                                                    )
                                                )
                                                kept_resource_member_uris = []

                                                for (
                                                    resource_member_uri
                                                ) in resource_member_uris:
                                                    uri_matches = (
                                                        self._member_uri_matches_filters(
                                                            resource_member_uri,
                                                            resource_filters,
                                                        )
                                                        if skip_if_no_matching_members
                                                        else self._member_matches_filters(
                                                            resource_member_uri,
                                                            None,
                                                            resource_filters,
                                                        )
                                                    )
                                                    if not uri_matches:
                                                        continue

                                                    resource_member_id = (
                                                        resource_member_uri.rstrip(
                                                            "/"
                                                        ).split("/")[-1]
                                                    )
                                                    resource_substitutions = dict(
                                                        step_responses
                                                    )
                                                    resource_substitutions[
                                                        resource_member_id_variable
                                                    ] = resource_member_id
                                                    resource_substitutions[
                                                        resource_member_uri_variable
                                                    ] = resource_member_uri

                                                    (
                                                        success,
                                                        resource_member_data,
                                                        resource_member_request_metadata,
                                                    ) = await _request_resource(
                                                        dut_id,
                                                        "GET",
                                                        resource_member_uri,
                                                    )
                                                    resource_member_request_token = self._request_timing_operation_id(
                                                        resource_member_request_metadata
                                                    )
                                                    if resource_member_request_token:
                                                        resource_member_request_tokens.append(
                                                            resource_member_request_token
                                                        )
                                                    if (
                                                        success
                                                        and self._member_matches_filters(
                                                            resource_member_uri,
                                                            resource_member_data,
                                                            resource_filters,
                                                        )
                                                    ):
                                                        kept_resource_member_uris.append(
                                                            resource_member_uri
                                                        )
                                                        matching_members_collected += 1
                                                        if resource_member_output_pattern:
                                                            final_resource_member_pattern = await self.substitute_variables(
                                                                resource_member_output_pattern,
                                                                resource_substitutions,
                                                                dut_id,
                                                            )

                                                            file_path = await _publish_resource(
                                                                dut_id,
                                                                resource_member_data,
                                                                function_tag,
                                                                output_pattern=final_resource_member_pattern,
                                                                substitutions=resource_substitutions,
                                                                collector_id=collector_id,
                                                                request_timing_operation_ids=resource_member_request_token,
                                                            )
                                                            if file_path:
                                                                output_files.append(
                                                                    file_path
                                                                )
                                                    elif (
                                                        not success
                                                        and skip_if_no_matching_members
                                                    ):
                                                        matching_member_fetch_failures.append(
                                                            f"Failed to fetch matching member resource {resource_member_uri}"
                                                        )

                                                if (
                                                    filter_collection_members
                                                    and isinstance(resource_data, dict)
                                                    and "Members" in resource_data
                                                ):
                                                    filtered_members = [
                                                        member
                                                        for member in resource_data.get(
                                                            "Members", []
                                                        )
                                                        if member.get("@odata.id")
                                                        in kept_resource_member_uris
                                                    ]
                                                    filtered_resource_data = dict(
                                                        resource_data
                                                    )
                                                    filtered_resource_data[
                                                        "Members"
                                                    ] = filtered_members
                                                    if (
                                                        "Members@odata.count"
                                                        in filtered_resource_data
                                                    ):
                                                        filtered_resource_data[
                                                            "Members@odata.count"
                                                        ] = len(filtered_members)

                                                    filtered_file_path = await _publish_resource(
                                                        dut_id,
                                                        filtered_resource_data,
                                                        function_tag,
                                                        output_pattern=final_resource_pattern,
                                                        substitutions=step_responses,
                                                        collector_id=collector_id,
                                                        request_timing_operation_ids=[
                                                            token
                                                            for token in [
                                                                resource_request_token,
                                                                *resource_member_request_tokens,
                                                            ]
                                                            if token
                                                        ],
                                                    )
                                                    if (
                                                        filtered_file_path
                                                        and filtered_file_path
                                                        not in output_files
                                                    ):
                                                        output_files.append(
                                                            filtered_file_path
                                                        )

                            elif skip_if_no_matching_members:
                                matching_member_fetch_failures.append(
                                    f"Failed to fetch matching member resource {member_uri}"
                                )

                        if (
                            filter_collection_members
                            and isinstance(response_data, dict)
                            and "Members" in response_data
                            and final_output_pattern
                        ):
                            filtered_members = [
                                member
                                for member in response_data.get("Members", [])
                                if member.get("@odata.id") in kept_member_uris
                            ]
                            filtered_response_data = dict(response_data)
                            filtered_response_data["Members"] = filtered_members
                            if "Members@odata.count" in filtered_response_data:
                                filtered_response_data["Members@odata.count"] = len(
                                    filtered_members
                                )

                            # A collector that explicitly accepts an empty
                            # match set still needs durable evidence that the
                            # endpoint was queried and filtered successfully.
                            # Without this root artifact the outer outcome
                            # policy cannot distinguish valid empty data from
                            # a collector that silently produced nothing.
                            if filtered_members or complete_on_empty_matches:
                                filtered_file_path = await _publish_resource(
                                    dut_id,
                                    filtered_response_data,
                                    function_tag,
                                    output_pattern=final_output_pattern,
                                    substitutions=step_responses,
                                    collector_id=collector_id,
                                    request_timing_operation_ids=[
                                        token
                                        for token in [
                                            response_request_token,
                                            *member_request_tokens,
                                        ]
                                        if token
                                    ],
                                )
                                if (
                                    filtered_file_path
                                    and filtered_file_path not in output_files
                                ):
                                    output_files.append(filtered_file_path)

                if len(resource_failures) > entity_failure_start:
                    entity_success = False
                if entity_success:
                    successful_operations += 1
                else:
                    error_messages.append(f"Entity {entity_id} processing failed")
                status_list.append(entity_success)

            if resource_failures:
                # One entity can retain useful resources and lose another.
                # Account for the retained resource artifacts and failed
                # acquisitions rather than promoting the entire entity.
                retained_resources = len(set(output_files))
                return await self._create_standardized_collector_result(
                    successful_operations=retained_resources,
                    total_operations=retained_resources + len(resource_failures),
                    output_files=output_files,
                    error_messages=[*error_messages, *resource_failures],
                    operation_name="resource_collection",
                    additional_context={
                        "entities_processed": len(entity_ids),
                        "steps_configured": len(steps),
                        "status": "partial" if output_files else "error",
                        "reason": (
                            "Optional resource collection encountered a request "
                            "or publication failure; absence was not established"
                        ),
                    },
                )

            if skip_if_no_matching_members and matching_member_fetch_failures:
                failed_count = len(matching_member_fetch_failures)
                status = "partial" if matching_members_collected > 0 else "error"
                reason = (
                    f"Collected {matching_members_collected} matching member resource(s) "
                    f"and failed to fetch {failed_count} matching member resource(s) "
                    f"for {function_tag}"
                )
                return await self._create_standardized_collector_result(
                    successful_operations=matching_members_collected,
                    total_operations=matching_members_collected + failed_count,
                    output_files=output_files,
                    error_messages=matching_member_fetch_failures,
                    operation_name="matching_member_collection",
                    additional_context={
                        "entities_processed": len(entity_ids),
                        "steps_configured": len(steps),
                        "matching_members_collected": matching_members_collected,
                        "matching_member_fetch_failures": failed_count,
                        "status": status,
                        "reason": reason,
                    },
                )

            if skip_if_no_matching_members and matching_members_collected == 0:
                empty_status = "success" if complete_on_empty_matches else "skipped"
                empty_context = {
                    "entities_processed": len(entity_ids),
                    "steps_configured": len(steps),
                    "matching_members_collected": 0,
                    "status": empty_status,
                    "reason": (
                        f"No matching member resources found for {function_tag}; "
                        "endpoint queries completed successfully"
                    ),
                }
                if not complete_on_empty_matches:
                    empty_context["intentional_evidence_only_skip"] = True
                return await self._create_standardized_collector_result(
                    successful_operations=(
                        successful_operations if complete_on_empty_matches else 0
                    ),
                    total_operations=(
                        total_operations if complete_on_empty_matches else 0
                    ),
                    output_files=output_files,
                    error_messages=[],
                    operation_name="matching_member_collection",
                    additional_context=empty_context,
                )

            # A required step that returned an empty body is a real failure even
            # when no artifact could be saved. Optional empty steps remain a skip.
            if not output_files and required_empty_body_failures:
                return await self._create_standardized_collector_result(
                    successful_operations=successful_operations,
                    total_operations=total_operations,
                    output_files=[],
                    error_messages=error_messages,
                    operation_name="multi_step_collection",
                    additional_context={
                        "entities_processed": len(entity_ids),
                        "steps_configured": len(steps),
                    },
                )

            # Check if any files were collected
            if not output_files:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Completed multi-step collection for {function_tag} - no files collected, treating as skipped",
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="multi_step_collection",
                    additional_context={
                        "entities_processed": len(entity_ids),
                        "steps_configured": len(steps),
                        "status": "skipped",
                        "reason": f"No data collected for {function_tag} - collector skipped",
                        **(
                            {
                                "skip_classification": (
                                    VALID_NOT_APPLICABLE_SKIP_CLASSIFICATION
                                ),
                                "optional_resource_absences": optional_resource_absences,
                            }
                            if optional_resource_absences and not error_messages
                            else {}
                        ),
                    },
                )

            return await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=total_operations,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="multi_step_collection",
                additional_context={
                    "entities_processed": len(entity_ids),
                    "steps_configured": len(steps),
                    **(
                        {"matching_members_collected": matching_members_collected}
                        if skip_if_no_matching_members
                        else {}
                    ),
                },
            )

        return await self._execute_with_error_handling(
            dut_id,
            f"multi-step collection for {function_tag}",
            _multi_step_collection,
        )

    async def collect_custom_service_executor(
        self,
        dut_id: str,
        function_tag: str,
        service_config: Dict[str, Any],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Generic custom service executor for configurable service execution.

        The implementation uses ``dut_id``, ``function_tag``,
        ``service_config``, and ``kwargs`` to generic custom service executor
        for configurable service execution. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            service_config: Service config governing generic custom service
                executor for configurable service execution.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing custom service executor.
        """
        try:
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Starting custom service executor for {function_tag}",
                dut_id,
            )

            # Extract configuration
            config_key = service_config.get("config_key", "CUSTOM_DUMP_SERVICES")
            default_timeout = service_config.get("default_timeout", 1500)
            try:
                retry_interval = float(service_config.get("retry_interval", 30))
            except (TypeError, ValueError):
                retry_interval = 30.0
            if not math.isfinite(retry_interval) or retry_interval <= 0:
                retry_interval = 30.0
            output_pattern = service_config.get("output_pattern", "")

            # Get services from DUT config first, then fall back to tool config
            dut_config = await self._get_dut_config(dut_id)
            services = dut_config.get(config_key, [])

            # Check DUT-level configuration first (highest priority)
            if isinstance(services, list) and services:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Using DUT-level services from {config_key}: {len(services)} services",
                    dut_id,
                )
            elif config_key not in dut_config:
                # Fall back to tool-level configuration (medium priority)
                orchestrator = getattr(self, "orchestrator", None)
                if orchestrator and hasattr(orchestrator, "config_manager"):
                    tool_config = orchestrator.config_manager.get_tool_config()
                else:
                    tool_config = self.dut_manager.tool_config
                services = tool_config.get(config_key, [])
                if isinstance(services, list) and services:
                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"Using tool-level services from {config_key}: {len(services)} services",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "WARNING",
                        "RedfishService",
                        f"No services found for {config_key} in DUT or tool config - collector will be skipped",
                        dut_id,
                    )

            if not services:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"No services defined in config key: {config_key}. Collector will be skipped.",
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="custom_service_executor",
                    additional_context={
                        "config_key": config_key,
                        "status": "skipped",
                        "reason": f"No services defined in config key '{config_key}' - collector skipped",
                    },
                )

            output_files = []
            status_list = []
            error_messages = []
            failed_service_contexts = {}
            diagnostic_domain_block_context: Optional[Dict[str, Any]] = None
            suppressed_services = 0

            # Process each service
            for service_idx, service in enumerate(services, 1):
                uri = service.get("uri", "")
                payload = service.get("payload", {})
                timeout = self._get_positive_timeout(
                    service.get("timeout", default_timeout)
                )
                if timeout is None:
                    timeout = self._get_positive_timeout(default_timeout) or 1500

                if not uri or not payload:
                    error_msg = f"Invalid service configuration at index {service_idx}: missing uri or payload"
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        error_msg,
                        dut_id,
                    )
                    error_messages.append(error_msg)
                    status_list.append(False)

                    # Create error log file for failed service execution
                    error_log_path = await self._create_error_log_file(
                        dut_id=dut_id,
                        collector_id=kwargs.get("collector_id"),
                        error_message=error_msg,
                        context={
                            "service_idx": service_idx,
                            "uri": uri,
                            "operation": "service_execution_validation",
                        },
                    )

                    # Add error log file to output files
                    if error_log_path:
                        output_files.append(error_log_path)
                    continue

                # Calculate max retries based on timeout
                max_retries = max(1, math.ceil(timeout / retry_interval))

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Processing service {service_idx}: URI={uri}, timeout={timeout}s, max_retries={max_retries}",
                    dut_id,
                )

                # Execute the complete dump lifecycle once. A diagnostic POST is
                # not idempotent, so programming errors must not trigger a
                # second fallback POST.
                attempt_disposition = DiagnosticAttemptDisposition()
                try:
                    execution_kwargs = dict(kwargs)
                    execution_kwargs["output_pattern"] = output_pattern
                    execution_kwargs["timeout"] = timeout
                    execution_kwargs["task_poll_interval"] = retry_interval
                    execution_kwargs["substitutions"] = {
                        **execution_kwargs.get("substitutions", {}),
                        "service_id": service_idx,
                    }
                    execution_kwargs["_diagnostic_attempt_disposition"] = (
                        attempt_disposition
                    )
                    status, output_file = await self._execute_redfish_dump_task_direct(
                        dut_id=dut_id,
                        uri=uri,
                        payload=payload,
                        function_tag=function_tag,
                        **execution_kwargs,
                    )
                except Exception as e:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"Exception in custom service {service_idx}: {str(e)}",
                        dut_id,
                    )
                    status = False
                    output_file = None
                    error_messages.append(f"Service {service_idx} failed: {str(e)}")

                if attempt_disposition.blocked_before_post:
                    diagnostic_domain_block_context = attempt_disposition.as_context()
                    if attempt_disposition.capacity_pool is None:
                        suppressed_services += len(services) - service_idx + 1
                        break
                    suppressed_services += 1
                    continue

                if status and output_file:
                    output_files.append(output_file)
                elif status:
                    status = False
                    error_messages.append(
                        f"Service {service_idx} completed without a dump artifact"
                    )
                elif output_file:
                    # The dump helper's second tuple member is the failure
                    # reason when status is false, not an artifact path.
                    error_messages.append(
                        f"Service {service_idx} failed: {output_file}"
                    )

                status_list.append(status)

                # Collect error messages for failed services
                if not status:
                    error_messages.append(f"Service {service_idx} (URI: {uri}) failed")

                    # Store request context for failed services (for detailed error logging)
                    failed_service_contexts[service_idx] = {
                        "request_uri": uri,
                        "request_payload_summary": (
                            self._bounded_request_payload_summary(payload)
                        ),
                        "service_index": service_idx,
                        "timeout": timeout,
                        "max_retries": max_retries,
                        **({"failure_reason": str(output_file)} if output_file else {}),
                    }

                if not attempt_disposition.resubmit_allowed:
                    diagnostic_domain_block_context = attempt_disposition.as_context()
                    if attempt_disposition.capacity_pool is None:
                        suppressed_services += len(services) - service_idx
                        break

            successful_services = sum(status_list)
            total_services = len(status_list)
            if status_list:
                total_services += suppressed_services

            # Include failed service contexts for detailed error logging
            additional_context = {
                "services_processed": len(status_list),
                "successful_services": successful_services,
                "config_key": config_key,
            }

            if diagnostic_domain_block_context is not None:
                additional_context.update(
                    {
                        "diagnostic_domain_block": diagnostic_domain_block_context,
                        "suppressed_services": suppressed_services,
                        "services_configured": len(services),
                    }
                )
                if not status_list:
                    additional_context.update(
                        {
                            "status": "skipped",
                            "reason": (
                                diagnostic_domain_block_context.get("reason")
                                or "Diagnostic domain is blocked by a prior remote "
                                "no-resubmit rejection; no POST was sent"
                            ),
                        }
                    )

            # Add request contexts for failed services if any exist
            if failed_service_contexts:
                additional_context["failed_service_contexts"] = failed_service_contexts

            return await self._create_standardized_collector_result(
                successful_operations=successful_services,
                total_operations=total_services,
                output_files=output_files,
                error_messages=error_messages,
                operation_name="custom_service_executor",
                additional_context=additional_context,
            )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_custom_service_executor: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Exception in custom service executor: {str(e)}"],
                operation_name="custom_service_executor",
                additional_context={
                    "config_key": config_key,
                },
            )

    async def _substitute_uri_variables(
        self, dut_id: str, uri_pattern: str, context: Dict[str, Any]
    ) -> str:
        """
        Substitute variables in URI pattern using context values.

        Supports patterns like {system_id}, {chassis_id}, {device_id}, etc.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_pattern: Validated remote resource identifier used for URI
                pattern.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The validated ``uri``.

        Raises:
            ValueError: If a substituted value is not one Redfish path segment,
                or, for a pattern that is a single placeholder, not a valid
                Redfish request URI.
        """
        uri = uri_pattern

        # Simple string substitution for common variables
        # Look for {variable_name} patterns and replace with values from context
        import re

        # Find all {variable} patterns
        variables = re.findall(r"\{(\w+)\}", uri)

        for var in variables:
            # Check if variable exists in context
            if var in context:
                placeholder = f"{{{var}}}"
                value = str(context[var])
                # A value substituted into a catalog-authored path must not add
                # structure of its own: a "?", "#", "/" or control character
                # would truncate or re-target the authored suffix. A pattern
                # that is nothing but one placeholder is a whole request target
                # and is validated with the request-URI grammar instead.
                try:
                    if uri_pattern.strip() == placeholder:
                        substituted = validate_redfish_request_uri(
                            value,
                            context=f"URI variable '{var}'",
                        )
                    else:
                        substituted = validate_redfish_uri_segment(
                            value,
                            context=f"URI variable '{var}'",
                        )
                except RedfishTopologyProfileError as error:
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        f"[_substitute_uri_variables] {error}",
                        dut_id,
                    )
                    raise ValueError(f"[_substitute_uri_variables] {error}") from error
                uri = uri.replace(placeholder, substituted)
            else:
                await self._log_runtime(
                    "WARN",
                    "RedfishService",
                    f"[_substitute_uri_variables] Variable '{var}' not found in context for URI: {uri_pattern}",
                    dut_id,
                )

        return uri

    async def _substitute_payload_variables(
        self, dut_id: str, payload: Any, context: Dict[str, Any]
    ) -> Any:
        """
        Recursively substitute variables in payload using context values.

        Supports patterns like {system_id} in string values within the payload.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            payload: Payload object whose ``items`` state is read while
                performing recursively substitute variables in payload using
                context values.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The substitute payload variables value selected by the operation.
        """
        import re

        if isinstance(payload, dict):
            result = {}
            for key, value in payload.items():
                result[key] = await self._substitute_payload_variables(
                    dut_id, value, context
                )
            return result
        elif isinstance(payload, list):
            return [
                await self._substitute_payload_variables(dut_id, item, context)
                for item in payload
            ]
        elif isinstance(payload, str):
            # Find all {variable} patterns
            variables = re.findall(r"\{(\w+)\}", payload)
            result = payload
            for var in variables:
                if var in context:
                    value = context[var]
                    result = result.replace(f"{{{var}}}", str(value))
                else:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        f"[_substitute_payload_variables] Variable '{var}' not found in context for payload substitution",
                        dut_id,
                    )
            return result
        else:
            # For non-string types (int, bool, etc.), return as-is
            return payload

    async def execute_redfish_action(
        self, dut_id: str, function_tag: str = "", **kwargs
    ) -> Dict[str, Any]:
        """
        Execute Redfish action.

        The implementation uses ``dut_id``, ``function_tag``, and ``kwargs`` to
        execute Redfish action. Terminal status is emitted only after redfish
        action and its owned cleanup have completed. Owned asynchronous work is
        awaited before return, so completion does not leave an unobserved task
        behind. Remote I/O uses the configured transport policy and returns only
        after its response or failure has been observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Examples:
            # Simple POST action
            - method: execute_redfish_action
              params:
                action: POST
                uri_pattern: >-
                  /redfish/v1/Systems/{system_id}/Actions/ComputerSystem.Reset
                payload:
                  ResetType: PowerCycle

            # POST with task_id storage for next hook
            - method: execute_redfish_action
              params:
                action: POST
                uri_pattern: >-
                  /redfish/v1/Systems/{system_id}/Actions/ComputerSystem.StartIST
                payload:
                  TargetSOC: ["/redfish/v1/Systems/{system_id}/CPU_0", 1]
                store_task_id: true
                context_key: ist_task_id

        Returns:
            A mapping containing execute Redfish action.
        """
        try:
            # Extract parameters
            action = kwargs.get("action", "GET").upper()
            uri_pattern = kwargs.get("uri_pattern", "")
            payload = kwargs.get("payload", {})
            timeout = await self._resolve_collector_timeout(
                dut_id, kwargs, default_timeout=300
            )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"[execute_redfish_action] Executing {action} on {uri_pattern}",
                dut_id,
            )

            # Substitute variables in URI pattern
            uri = await self._substitute_uri_variables(dut_id, uri_pattern, kwargs)

            # Substitute variables in payload if it contains string values
            substituted_payload = await self._substitute_payload_variables(
                dut_id, payload, kwargs
            )

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"[execute_redfish_action] URI: {uri}, Payload: {substituted_payload}",
                dut_id,
            )

            # Execute the request using existing dispatch_request
            success, response, metadata = await self.dispatch_request(
                dut_id=dut_id,
                method=action,
                uri=uri,
                body=(
                    substituted_payload if action in ["POST", "PUT", "PATCH"] else None
                ),
                timeout=timeout,
                bypass_cache=True,
            )

            result = {
                "success": success,
                "context": {},
            }

            if not success:
                result["reason"] = f"{action} request to {uri} failed: {response}"
                await self._log_runtime(
                    "ERROR",
                    "RedfishService",
                    f"[execute_redfish_action] Failed: {result['reason']}",
                    dut_id,
                )
                return result

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"[execute_redfish_action] {action} succeeded on {uri}",
                dut_id,
            )

            # Store task ID if requested
            if kwargs.get("store_task_id", False):
                task_id = None

                # Try to extract task ID from various response formats
                if isinstance(response, dict):
                    # Check for @odata.id in response
                    if "@odata.id" in response:
                        task_uri = response["@odata.id"]
                        # Extract task ID from URI like "/redfish/v1/TaskService/Tasks/12345"
                        if "/Tasks/" in task_uri:
                            task_id = task_uri.split("/Tasks/")[-1]

                    # Check for Id field
                    elif "Id" in response:
                        task_id = response["Id"]

                if task_id is not None:
                    # The stored value is later substituted into a
                    # catalog-authored URI template, so it must already be one
                    # safe path segment.
                    try:
                        task_id = validate_redfish_uri_segment(
                            str(task_id),
                            context="response task identifier",
                        )
                    except RedfishTopologyProfileError as error:
                        await self._log_runtime(
                            "WARN",
                            "RedfishService",
                            "[execute_redfish_action] Rejected response task "
                            f"identifier: {error}",
                            dut_id,
                        )
                        task_id = None

                if task_id:
                    context_key = kwargs.get("context_key", "task_id")
                    result["context"][context_key] = task_id

                    await self._log_runtime(
                        "INFO",
                        "RedfishService",
                        f"[execute_redfish_action] Stored task_id '{task_id}' in context['{context_key}']",
                        dut_id,
                    )
                else:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        "[execute_redfish_action] store_task_id=True but no task ID found in response",
                        dut_id,
                    )

            # Store full response if requested
            if kwargs.get("store_response", False):
                response_key = kwargs.get("response_key", "response")
                result["context"][response_key] = response

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"[execute_redfish_action] Stored response in context['{response_key}']",
                    dut_id,
                )

            # Wait after action if requested
            wait_seconds = kwargs.get("wait_after_action")
            if wait_seconds:
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"[execute_redfish_action] Waiting {wait_seconds} seconds after action",
                    dut_id,
                )
                await asyncio.sleep(wait_seconds)

            return result

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"[execute_redfish_action] Exception: {str(e)}",
                dut_id,
            )
            return {
                "success": False,
                "context": {},
                "reason": f"Exception during execute_redfish_action: {str(e)}",
            }

    def _resolve_hook_value_from_context(
        self, value: Any, context: Dict[str, Any]
    ) -> Any:
        """
        Resolve simple ${var} placeholders for hook parameters.

        The implementation uses ``value`` and ``context`` to resolve simple
        ${var} placeholders for hook parameters.

        Args:
            value: Value evaluated while performing simple ${var} placeholders
                for hook parameters.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            The hook value from context value selected by the operation.
        """
        if isinstance(value, list):
            return [
                self._resolve_hook_value_from_context(item, context) for item in value
            ]
        return self._resolve_placeholder(value, context)

    def _extract_binary_blob_from_response(
        self,
        response: Any,
        binary_response_paths: Optional[List[Any]] = None,
    ) -> Optional[bytes]:
        """
        Extract a binary payload from bytes or a JSON/base64 response body.

        The implementation uses ``response`` and ``binary_response_paths`` to
        extract a binary payload from bytes or a JSON/base64 response body.

        Args:
            response: Transport response governed by the configured
                authentication and trust policy.
            binary_response_paths: Filesystem locations processed in
                caller-provided order.

        Returns:
            The bounded binary blob from response bytes, or ``None`` when the
            requested value is unavailable.
        """
        if isinstance(response, bytes):
            return response

        if not isinstance(response, dict):
            return None

        candidate_paths = binary_response_paths or [
            "Payload",
            "Data",
            "Binary",
            "Content",
            "Oem.Nvidia.Payload",
            "Oem.Nvidia.Data",
            "Oem.NVIDIA.Payload",
            "Oem.NVIDIA.Data",
        ]

        for path in candidate_paths:
            candidate = self._extract_nested_value(response, path)
            if candidate is None:
                continue

            if isinstance(candidate, str):
                try:
                    return base64.b64decode(candidate, validate=True)
                except (ValueError, binascii.Error):
                    continue

            if isinstance(candidate, list):
                try:
                    return bytes(candidate)
                except ValueError:
                    continue

        return None

    async def _check_power_state_off(
        self,
        dut_id: str,
        power_state_uris: List[str],
        context: Dict[str, Any],
    ) -> Tuple[bool, str]:
        """
        Require at least one configured Redfish resource to report PowerState=Off.

        The implementation uses ``dut_id``, ``power_state_uris``, and
        ``context`` to require at least one configured Redfish resource to
        report PowerState=Off. Every required invariant is checked before a
        successful value is returned; invalid input follows the function's
        explicit exception path. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind. Remote
        I/O uses the configured transport policy and returns only after its
        response or failure has been observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            power_state_uris: Validated remote resource identifier used for
                power state URIs.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            A tuple containing ``success flag`` and ``status or message text``
            in that order.
        """
        if not power_state_uris:
            return (
                False,
                "require_host_power_off enabled but no power_state_uris provided",
            )

        observations: List[str] = []
        found_non_off = False

        for uri_template in power_state_uris:
            uri = await self.substitute_variables(uri_template, context, dut_id)
            success, response, error_details = await self.dispatch_request(
                dut_id=dut_id,
                method="GET",
                uri=uri,
                bypass_cache=True,
                error_context=f"power state check for {uri}",
            )
            if not success:
                observations.append(
                    f"{uri}: request failed ({error_details or response})"
                )
                continue

            if not isinstance(response, dict):
                observations.append(
                    f"{uri}: invalid response type {type(response).__name__}"
                )
                continue

            power_state = response.get("PowerState")
            if power_state == "Off":
                return True, f"{uri}: PowerState=Off"
            if power_state:
                found_non_off = True
                observations.append(f"{uri}: PowerState={power_state}")
            else:
                observations.append(f"{uri}: PowerState missing")

        if found_non_off:
            return False, "; ".join(observations)
        return (
            False,
            "No configured power state resource reported PowerState=Off",
        )

    async def _get_redfish_power_state(
        self,
        dut_id: str,
        uri_template: str,
        context: Dict[str, Any],
    ) -> Tuple[Optional[str], str, Optional[str]]:
        """
        Read PowerState from a Redfish resource.

        The implementation uses ``dut_id``, ``uri_template``, and ``context`` to
        read PowerState from a Redfish resource. Parsing or I/O must finish
        before the validated representation is made available to the caller.
        Owned asynchronous work is awaited before return, so completion does not
        leave an unobserved task behind. Remote I/O uses the configured
        transport policy and returns only after its response or failure has been
        observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_template: Validated remote resource identifier used for URI
                template.
            context: Runtime context carrying state shared across this
                operation.

        Returns:
            A tuple containing ``status or message text``, ``URI``, and ``status
            or message text`` in that order.
        """
        try:
            uri = await self._substitute_uri_variables(dut_id, uri_template, context)
        except ValueError as error:
            return None, uri_template, str(error)
        success, response, error_details = await self.dispatch_request(
            dut_id=dut_id,
            method="GET",
            uri=uri,
            bypass_cache=True,
            error_context=f"power state read for {uri}",
        )
        if not success:
            return None, uri, str(error_details or response)
        if not isinstance(response, dict):
            return (
                None,
                uri,
                f"invalid response type {type(response).__name__}",
            )

        power_state = response.get("PowerState")
        if not isinstance(power_state, str) or not power_state:
            return None, uri, "PowerState missing"
        return power_state, uri, None

    async def _wait_for_redfish_power_state(
        self,
        dut_id: str,
        uri_template: str,
        target_power_state: str,
        context: Dict[str, Any],
        max_retries: int,
        poll_interval: int,
        action_label: str,
    ) -> Tuple[bool, str]:
        """
        Poll a Redfish resource until PowerState reaches the requested state.

        The implementation uses ``dut_id``, ``uri_template``,
        ``target_power_state``, ``context``, and ``max_retries`` to poll a
        Redfish resource until PowerState reaches the requested state. Owned
        asynchronous work is awaited before return, so completion does not leave
        an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri_template: Validated remote resource identifier used for URI
                template.
            target_power_state: Text supplied as target power state in the
                format accepted by this function.
            context: Runtime context carrying state shared across this
                operation.
            max_retries: Upper bound enforced for max retries; the consuming
                boundary rejects or truncates values that exceed it.
            poll_interval: Maximum duration in seconds allowed for poll
                interval.
            action_label: Text supplied as action label in the format accepted
                by this function.

        Returns:
            A tuple containing ``success flag`` and ``status or message text``
            in that order.
        """
        last_observation = "PowerState not read"
        attempts = max(1, int(max_retries))
        interval = max(1, int(poll_interval))

        for attempt in range(1, attempts + 1):
            power_state, uri, error = await self._get_redfish_power_state(
                dut_id, uri_template, context
            )
            if power_state == target_power_state:
                return True, f"{uri}: PowerState={target_power_state}"

            last_observation = (
                f"{uri}: PowerState={power_state}"
                if power_state
                else f"{uri}: {error or 'PowerState unavailable'}"
            )
            await self._log_runtime(
                "INFO" if attempt == 1 else "DEBUG",
                "RedfishService",
                (
                    f"[{action_label}] Waiting for PowerState={target_power_state}; "
                    f"attempt {attempt}/{attempts}; {last_observation}"
                ),
                dut_id,
            )
            if attempt < attempts:
                await asyncio.sleep(interval)

        return False, last_observation

    async def _execute_redfish_power_action(
        self,
        dut_id: str,
        action_config: Dict[str, Any],
        context: Dict[str, Any],
        action_label: str,
        before_state_change: Optional[Callable[[], None]] = None,
    ) -> Tuple[bool, str, bool]:
        """
        Execute Redfish power action.

        The implementation uses ``dut_id``, ``action_config``, ``context``,
        ``action_label``, and ``before_state_change`` to execute Redfish power
        action. Terminal status is emitted only after redfish power action and
        its owned cleanup have completed. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.
        Remote I/O uses the configured transport policy and returns only after
        its response or failure has been observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            action_config: Action config governing redfish power action.
            context: Runtime context carrying state shared across this
                operation.
            action_label: Text supplied as action label in the format accepted
                by this function.
            before_state_change: Optional before state change; ``None`` selects
                the function's default behavior.

        Returns:
            A tuple containing ``success flag``, ``message text``, and ``success
            flag`` in that order.
        """
        if not isinstance(action_config, dict):
            return (
                False,
                f"{action_label}: action_config must be a mapping",
                False,
            )

        uri_pattern = action_config.get("uri_pattern")
        if not uri_pattern:
            return False, f"{action_label}: uri_pattern missing", False

        power_state_uri = action_config.get("power_state_uri")
        target_power_state = action_config.get("target_power_state")
        max_retries = int(action_config.get("max_retries", 60))
        poll_interval = int(action_config.get("poll_interval", 10))

        if power_state_uri and target_power_state:
            current_state, state_uri, error = await self._get_redfish_power_state(
                dut_id, power_state_uri, context
            )
            if current_state == target_power_state:
                return (
                    True,
                    f"{action_label}: {state_uri} already PowerState={target_power_state}",
                    False,
                )
            if error:
                await self._log_runtime(
                    "WARN",
                    "RedfishService",
                    f"[{action_label}] Could not read initial power state: {state_uri}: {error}",
                    dut_id,
                )

        try:
            uri = await self._substitute_uri_variables(dut_id, uri_pattern, context)
        except ValueError as error:
            return False, f"{action_label}: {error}", False
        payload = await self._substitute_payload_variables(
            dut_id, action_config.get("payload", {}), context
        )

        # Transfer restoration ownership before the first state-changing
        # request so cancellation cannot strand the host in the target state.
        if before_state_change is not None:
            before_state_change()

        await self._log_runtime(
            "INFO",
            "RedfishService",
            f"[{action_label}] POST {self._diagnostic_uri_evidence(uri)} payload "
            f"summary={self._bounded_request_payload_summary(payload)}",
            dut_id,
        )
        success, response, _ = await self.dispatch_request(
            dut_id=dut_id,
            method="POST",
            uri=uri,
            body=payload,
            bypass_cache=True,
            error_context=action_label,
            retry_count=0,
        )
        if not success:
            return (
                False,
                f"{action_label}: POST {uri} failed: {response}",
                True,
            )

        if not power_state_uri or not target_power_state:
            return True, f"{action_label}: action completed", True

        wait_success, wait_reason = await self._wait_for_redfish_power_state(
            dut_id=dut_id,
            uri_template=power_state_uri,
            target_power_state=target_power_state,
            context=context,
            max_retries=max_retries,
            poll_interval=poll_interval,
            action_label=action_label,
        )
        if wait_success:
            return True, f"{action_label}: {wait_reason}", True

        fallback_payload = action_config.get("fallback_payload")
        if not fallback_payload:
            return (
                False,
                f"{action_label}: did not reach PowerState={target_power_state}: {wait_reason}",
                True,
            )

        substituted_fallback = await self._substitute_payload_variables(
            dut_id, fallback_payload, context
        )
        await self._log_runtime(
            "WARN",
            "RedfishService",
            (
                f"[{action_label}] Target power state not reached; "
                f"POST fallback payload={substituted_fallback}"
            ),
            dut_id,
        )
        fallback_success, fallback_response, _ = await self.dispatch_request(
            dut_id=dut_id,
            method="POST",
            uri=uri,
            body=substituted_fallback,
            bypass_cache=True,
            error_context=f"{action_label} fallback",
            retry_count=0,
        )
        if not fallback_success:
            return (
                False,
                f"{action_label}: fallback POST {uri} failed: {fallback_response}",
                True,
            )

        wait_success, wait_reason = await self._wait_for_redfish_power_state(
            dut_id=dut_id,
            uri_template=power_state_uri,
            target_power_state=target_power_state,
            context=context,
            max_retries=max_retries,
            poll_interval=poll_interval,
            action_label=f"{action_label} fallback",
        )
        if not wait_success:
            return (
                False,
                f"{action_label}: fallback did not reach PowerState={target_power_state}: {wait_reason}",
                True,
            )
        return True, f"{action_label}: {wait_reason}", True

    async def _resolve_oem_action_target(
        self,
        resource_data: Dict[str, Any],
        action_name_candidates: List[str],
        *,
        dut_id: str,
        resource_uri: str,
    ) -> Optional[str]:
        """
        Resolve an OEM action target from a resource's Actions block.

        The target is response-derived and drives a *mutating* POST, so it is
        held to the same contract as the DGX diagnostic twin
        (:meth:`_validate_dgx_diagnostic_action_target`): normalized to a
        response path, then required to resolve beneath the resource that
        advertised it. An unusable target is discarded rather than dispatched,
        which lets the caller fall back to the catalog-authored action URI --
        the operator-controlled value -- instead of failing the collector.

        Args:
            resource_data: Mapping supplying fields for OEM action target from a
                resource's Actions block.
            action_name_candidates: Entries supplied as
                ``action_name_candidates`` without transferring container
                ownership.
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            resource_uri: Validated remote resource identifier used for resource
                URI.

        Returns:
            The canonical oem action target text, or ``None`` when the requested
            value is unavailable.
        """
        actions = resource_data.get("Actions", {})
        if not isinstance(actions, dict):
            return None

        for candidate in action_name_candidates:
            action_data = actions.get(candidate)
            if not isinstance(action_data, dict) or not action_data.get("target"):
                continue
            try:
                normalized = self._normalize_dut_response_path(
                    dut_id,
                    action_data["target"],
                    context=f"advertised OEM action target {candidate}",
                )
                return validate_redfish_uri_path(
                    normalized,
                    context=f"advertised OEM action target {candidate}",
                    service_root=resource_uri,
                )
            except (ValueError, TypeError, AttributeError):
                # Controller-supplied; never echo the rejected value.
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    f"Discarded unusable OEM action target for {candidate} "
                    f"advertised by {resource_uri}",
                    dut_id,
                )
                continue

        return None

    @staticmethod
    def _validate_oem_response_uri(
        value: Any,
        *,
        allowed_roots: List[str],
        context: str,
        allow_query: bool = True,
    ) -> str:
        """
        Validate a response-derived URI beneath an explicitly owned root.

        The implementation uses ``value``, ``allowed_roots``, ``context``, and
        ``allow_query`` to validate a response-derived URI beneath an explicitly
        owned root. Every required invariant is checked before a successful
        value is returned; invalid input follows the function's explicit
        exception path.

        Args:
            value: Value evaluated while performing response-derived URI beneath
                an explicitly owned root.
            allowed_roots: Entries supplied as ``allowed_roots`` without
                transferring container ownership.
            context: Runtime context carrying state shared across this
                operation.
            allow_query: Whether allow query is enabled or required for this
                operation.

        Returns:
            The canonical oem response URI text.

        Raises:
            RedfishTopologyProfileError: If ``context`` must not contain a
                query; or ``context`` escaped its expected Redfish resource
                root.
        """

        validated = validate_redfish_request_uri(value, context=context)
        parsed = urlsplit(validated)
        if parsed.query and not allow_query:
            raise RedfishTopologyProfileError(f"{context} must not contain a query")
        canonical_path = unquote(parsed.path)
        for raw_root in allowed_roots:
            try:
                root = unquote(
                    validate_redfish_uri_path(
                        raw_root,
                        context=f"{context} allowed root",
                    )
                )
            except (RedfishTopologyProfileError, TypeError, ValueError):
                continue
            if canonical_path.startswith(f"{root}/"):
                return canonical_path + (f"?{parsed.query}" if parsed.query else "")
        raise RedfishTopologyProfileError(
            f"{context} escaped its expected Redfish resource root"
        )

    async def _restore_power_after_oem_action(
        self,
        *,
        dut_id: str,
        post_action: Dict[str, Any],
        context: Dict[str, Any],
        action_label: str,
        collector_label: str,
    ) -> Tuple[bool, str, bool]:
        """
        Own and finish a bounded power restore despite caller cancellation.

        The implementation uses ``dut_id``, ``post_action``, ``context``,
        ``action_label``, and ``collector_label`` to own and finish a bounded
        power restore despite caller cancellation. Owned asynchronous work is
        awaited before return, so completion does not leave an unobserved task
        behind. If the function cannot own and finish a bounded power restore
        despite caller cancellation, its exception reaches the caller instead of
        being converted into a successful result.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            post_action: Mapping supplying fields for own and finish a bounded
                power restore despite caller cancellation.
            context: Runtime context carrying state shared across this
                operation.
            action_label: Text supplied as action label in the format accepted
                by this function.
            collector_label: Text supplied as collector label in the format
                accepted by this function.

        Returns:
            A tuple containing ``post success``, ``post reason``, and ``post
            executed`` in that order.

        Raises:
            BaseException: If a delegated failure occurs while the function
                attempts to own and finish a bounded power restore despite
                caller cancellation.
        """

        async def bounded_restore() -> Tuple[bool, str, bool]:
            """
            Return the bounded restore.

            After applying local validation, the function forwards current
            instance state to ``asyncio.wait_for`` and preserves its return and
            exception contract. Owned asynchronous work is awaited before
            return, so completion does not leave an unobserved task behind.

            Returns:
                A tuple containing the fields that represent bounded restore.
            """
            return await asyncio.wait_for(
                self._execute_redfish_power_action(
                    dut_id=dut_id,
                    action_config=post_action,
                    context=context,
                    action_label=action_label,
                ),
                timeout=self.MAX_POWER_RESTORE_SECONDS,
            )

        restore_task = asyncio.create_task(
            bounded_restore(),
            name=f"redfish-power-restore-{dut_id}",
        )
        cancellation_seen = False
        try:
            while True:
                try:
                    result = await asyncio.shield(restore_task)
                    break
                except asyncio.CancelledError:
                    cancellation_seen = True
                    if restore_task.done():
                        result = restore_task.result()
                        break
        except asyncio.TimeoutError:
            result = (
                False,
                f"{action_label}: restore exceeded the bounded deadline",
                False,
            )
        except Exception as restore_error:
            result = (
                False,
                f"{action_label}: restore raised {type(restore_error).__name__}",
                False,
            )

        post_success, post_reason, post_executed = result
        await self._log_runtime(
            "INFO" if post_success else "ERROR",
            "RedfishService",
            f"[{collector_label}] {post_reason}",
            dut_id,
        )
        if cancellation_seen:
            raise asyncio.CancelledError
        return post_success, post_reason, post_executed

    async def _download_binary_from_uri(
        self,
        dut_id: str,
        uri: str,
        context: Dict[str, Any],
        function_tag: str,
        output_pattern: str,
        collector_id: str,
        raw_content_max_bytes: Optional[int] = None,
        min_size_bytes: int = 0,
    ) -> Tuple[Optional[str], Optional[Any], Optional[str]]:
        """
        Download a binary blob from a Redfish URI and persist it.

        The URI reaching this method is response-derived on the OEM
        binary-action path (TaskMonitor, @odata.id, or a nested download
        target), so it is validated against the effective service root before a
        request is issued. This is the single choke point for both branches.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            uri: Validated remote resource identifier used for URI.
            context: Runtime context carrying state shared across this
                operation.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            output_pattern: Text supplied as output pattern in the format
                accepted by this function.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            raw_content_max_bytes: Upper bound enforced for raw content max
                bytes; the consuming boundary rejects or truncates values that
                exceed it.
            min_size_bytes: Minimum accepted binary size. Undersized private
                downloads are rejected before the public output write.

        Returns:
            A tuple containing the saved path, downloaded value, and sanitized
            failure message.
        """
        # Resolve the host the request will actually be sent to. This must come
        # from the connection info, which is what builds the request URL --
        # normalize_redfish_uri only rewrites the path, so deriving a host from
        # it always yields None and would reject every absolute URI, including
        # a legitimate absolute TaskMonitor returned by some controllers.
        expected_host = self._resolve_request_host(dut_id)

        if not validate_redfish_uri(uri, expected_host=expected_host):
            # Record only a sanitized reason: the rejected value is
            # controller-supplied and must not be echoed back into evidence.
            return None, None, "rejected unsafe response-derived download URI"

        effective_max_bytes = self._clamped_attachment_limit(
            dut_id,
            raw_content_max_bytes,
            field_name="raw_content_max_bytes",
        )
        success, response, error_details = await self.dispatch_request(
            dut_id=dut_id,
            method="GET",
            uri=uri,
            get_raw_content=True,
            raw_content_max_bytes=effective_max_bytes,
            bypass_cache=True,
            error_context=f"binary download from {uri}",
        )
        if not success:
            return (
                None,
                None,
                f"Failed to download binary from {uri}: {error_details or response}",
            )

        data = response
        if not isinstance(data, (bytes, StreamedRedfishBody)):
            data = self._extract_binary_blob_from_response(data)
            if data is None:
                return (
                    None,
                    None,
                    f"Response from {uri} did not contain a binary payload",
                )

        artifact_size = len(data)
        if min_size_bytes and artifact_size < min_size_bytes:
            if isinstance(data, StreamedRedfishBody):
                data.cleanup()
            return (
                None,
                None,
                "binary artifact smaller than expected "
                f"({artifact_size} < {min_size_bytes} bytes)",
            )

        file_path = await self._save_data_to_file_with_pattern(
            dut_id,
            data,
            function_tag,
            output_pattern=output_pattern,
            substitutions=context,
            collector_id=collector_id,
        )
        if not file_path:
            if isinstance(data, StreamedRedfishBody):
                data.cleanup()
            return (
                None,
                None,
                f"Downloaded binary from {uri} but failed to save it",
            )

        return file_path, data, None

    async def _save_oem_binary_metadata(
        self,
        dut_id: str,
        metadata: Dict[str, Any],
        function_tag: str,
        metadata_output_pattern: str,
        collector_id: str,
        substitutions: Dict[str, Any],
    ) -> Optional[str]:
        """
        Persist metadata sidecar for an OEM binary action artifact.

        After applying local validation, the function forwards ``dut_id``,
        ``metadata``, ``function_tag``, ``metadata_output_pattern``, and
        ``collector_id`` to ``self._save_data_to_file_with_pattern`` and
        preserves its return and exception contract. Success is reported only
        after the owning output boundary has completed its required write or
        publication step. Owned asynchronous work is awaited before return, so
        completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            metadata: Mapping supplying fields for metadata sidecar for an OEM
                binary action artifact.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            metadata_output_pattern: Text supplied as metadata output pattern in
                the format accepted by this function.
            collector_id: Stable collector identifier used to correlate
                configuration, logs, and results.
            substitutions: Mapping supplying fields for metadata sidecar for an
                OEM binary action artifact.

        Returns:
            The canonical save oem binary metadata text, or ``None`` when the
            requested value is unavailable.
        """
        if not metadata_output_pattern:
            return None

        return await self._save_data_to_file_with_pattern(
            dut_id,
            metadata,
            function_tag,
            output_pattern=metadata_output_pattern,
            substitutions=substitutions,
            collector_id=collector_id,
        )

    async def collect_chassis_oem_binary_action(
        self,
        dut_id: str,
        function_tag: str,
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Execute a chassis OEM action that returns or stages a binary artifact.

        Supported response paths:

        - direct binary body from the action response.
        - base64 payload embedded in the action response JSON.
        - Task/TaskMonitor response followed by binary download from
          TaskMonitor.
        - explicit download URI embedded in the action or task response.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing chassis oem binary action.

        Raises:
            BaseException: If a delegated failure occurs while the function
                attempts to execute a chassis OEM action that returns or stages
                a binary artifact.
        """
        power_cycle: Dict[str, Any] = {}
        restore_power_on_completion = False
        restore_attempted = False
        try:
            collector_id = kwargs.get("collector_id", "")
            output_pattern = kwargs.get("output_pattern", "")
            metadata_output_pattern = kwargs.get("metadata_output_pattern", "")
            payload = kwargs.get("payload", {})
            action_name_candidates = kwargs.get("action_name_candidates", [])
            action_uri_fallback_pattern = kwargs.get("action_uri_fallback_pattern")
            binary_response_paths = kwargs.get("binary_response_paths")
            download_uri_paths = kwargs.get("download_uri_paths", [])
            require_host_power_off = kwargs.get("require_host_power_off", False)
            power_state_uris = kwargs.get("power_state_uris", [])
            power_cycle = kwargs.get("power_cycle") or {}
            min_size_bytes = int(kwargs.get("min_size_bytes", 0))
            hash_algorithm = kwargs.get("hash_algorithm", "sha256")
            task_max_retries = int(kwargs.get("task_max_retries", 50))
            task_poll_interval = int(kwargs.get("task_poll_interval", 30))
            action_timeout = await self._resolve_collector_timeout(
                dut_id,
                kwargs,
                default_timeout=300,
                explicit_timeout_keys=("action_timeout", "timeout"),
            )

            raw_uri_list = self._resolve_hook_value_from_context(
                kwargs.get("uri_list", []), kwargs
            )
            if isinstance(raw_uri_list, str):
                uri_list = [raw_uri_list]
            else:
                uri_list = [uri for uri in raw_uri_list if uri]

            if not uri_list:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="chassis_oem_binary_action",
                    additional_context={
                        "status": "skipped",
                        "reason": "No chassis OEM action targets provided",
                    },
                    dut_id=dut_id,
                    collector_id=collector_id,
                )

            output_files: List[str] = []
            error_messages: List[str] = []
            successful_operations = 0
            power_cycle_enabled = isinstance(power_cycle, dict) and bool(
                power_cycle.get("enabled")
            )

            if kwargs.get("state_modifying"):
                snapshot_method = getattr(
                    self.dut_manager, "get_resource_member_snapshot", None
                )
                discovery_snapshot = None
                if callable(snapshot_method):
                    snapshot_result = snapshot_method(dut_id, "Chassis")
                    discovery_snapshot = (
                        await snapshot_result
                        if inspect.isawaitable(snapshot_result)
                        else snapshot_result
                    )
                if not isinstance(discovery_snapshot, dict) or not bool(
                    discovery_snapshot.get("complete", False)
                ):
                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=len(uri_list),
                        output_files=[],
                        error_messages=[
                            "Incomplete chassis discovery; refusing state-changing OEM actions"
                        ],
                        operation_name="chassis_oem_binary_action",
                        additional_context={
                            "function_tag": function_tag,
                            "successful_targets": 0,
                            "security_status": "incomplete_discovery",
                        },
                        dut_id=dut_id,
                        collector_id=collector_id,
                    )

            try:
                chassis_collection_uri = validate_redfish_uri_path(
                    self.get_configured_uri(dut_id, "Chassis"),
                    context="chassis OEM collection URI",
                )
            except (RedfishTopologyProfileError, TypeError, ValueError):
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=len(uri_list),
                    output_files=[],
                    error_messages=["Configured chassis collection URI is invalid"],
                    operation_name="chassis_oem_binary_action",
                    additional_context={"security_status": "invalid_chassis_root"},
                    dut_id=dut_id,
                    collector_id=collector_id,
                )

            planned_actions: List[Dict[str, Any]] = []
            for raw_chassis_uri in uri_list:
                try:
                    chassis_uri = unquote(
                        validate_redfish_uri_path(
                            raw_chassis_uri,
                            context="chassis OEM action target resource",
                            service_root=chassis_collection_uri,
                        )
                    )
                except (RedfishTopologyProfileError, TypeError, ValueError):
                    error_messages.append("Rejected unsafe chassis OEM resource URI")
                    continue

                context = dict(kwargs)
                context.update(self._extract_entity_id_from_uri(chassis_uri))
                chassis_id = context.get(
                    "chassis_id"
                ) or self._extract_entity_id_from_uri(chassis_uri, "Chassis")
                context["chassis_id"] = chassis_id
                socket_match = re.search(r"ProcessorModule_(\d+)_", str(chassis_id))
                socket_id = socket_match.group(1) if socket_match else "unknown"
                context["socket_id"] = socket_id

                success, chassis_data, error_details = await self.dispatch_request(
                    dut_id=dut_id,
                    method="GET",
                    uri=chassis_uri,
                    bypass_cache=True,
                    error_context=(
                        "resolve chassis OEM action for "
                        f"{self._diagnostic_uri_evidence(chassis_uri)}"
                    ),
                )
                if not success or not isinstance(chassis_data, dict):
                    error_messages.append(
                        f"{self._diagnostic_uri_evidence(chassis_uri)}: failed to "
                        "retrieve chassis resource "
                        f"({self._bounded_response_metadata_text(chassis_data, error_details)})"
                    )
                    continue

                action_target = await self._resolve_oem_action_target(
                    chassis_data,
                    action_name_candidates,
                    dut_id=dut_id,
                    resource_uri=chassis_uri,
                )
                if not action_target and action_uri_fallback_pattern:
                    action_target = await self.substitute_variables(
                        action_uri_fallback_pattern, context, dut_id
                    )
                if not action_target:
                    error_messages.append(
                        f"{self._diagnostic_uri_evidence(chassis_uri)}: OEM action "
                        "target not found"
                    )
                    continue
                try:
                    action_target = self._validate_oem_response_uri(
                        action_target,
                        allowed_roots=[f"{chassis_uri}/Actions"],
                        context="chassis OEM action URI",
                        allow_query=False,
                    )
                except (RedfishTopologyProfileError, TypeError, ValueError):
                    error_messages.append(
                        f"{self._diagnostic_uri_evidence(chassis_uri)}: rejected OEM "
                        "action target outside the chassis Actions resource"
                    )
                    continue
                planned_actions.append(
                    {
                        "chassis_uri": chassis_uri,
                        "context": context,
                        "chassis_id": chassis_id,
                        "socket_id": socket_id,
                        "action_target": action_target,
                        "payload": await self._substitute_payload_variables(
                            dut_id, payload, context
                        ),
                    }
                )

            if error_messages or len(planned_actions) != len(uri_list):
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=len(uri_list),
                    output_files=[],
                    error_messages=error_messages
                    or ["Chassis OEM action preflight was incomplete"],
                    operation_name="chassis_oem_binary_action",
                    additional_context={
                        "function_tag": function_tag,
                        "successful_targets": 0,
                        "security_status": "preflight_failed",
                    },
                    dut_id=dut_id,
                    collector_id=collector_id,
                )

            if power_cycle_enabled:
                pre_action = power_cycle.get("pre_action")

                def claim_restore_responsibility() -> None:
                    """
                    Claim ownership of restoring the chassis state.

                    The implementation uses current instance state to claim
                    ownership of restoring the chassis state.
                    """
                    nonlocal restore_power_on_completion
                    restore_power_on_completion = bool(
                        power_cycle.get("restore_on_completion", True)
                    )

                (
                    pre_success,
                    pre_reason,
                    _,
                ) = await self._execute_redfish_power_action(
                    dut_id=dut_id,
                    action_config=(pre_action if isinstance(pre_action, dict) else {}),
                    context=kwargs,
                    action_label=f"{collector_id or function_tag} pre-action power-off",
                    before_state_change=claim_restore_responsibility,
                )
                await self._log_runtime(
                    "INFO" if pre_success else "ERROR",
                    "RedfishService",
                    f"[{collector_id or function_tag}] {pre_reason}",
                    dut_id,
                )
                if not pre_success:
                    error_messages.append(pre_reason)
                    if restore_power_on_completion:
                        post_action = power_cycle.get("post_action")
                        restore_attempted = True
                        (
                            post_success,
                            post_reason,
                            _,
                        ) = await self._restore_power_after_oem_action(
                            dut_id=dut_id,
                            post_action=(
                                post_action if isinstance(post_action, dict) else {}
                            ),
                            context=kwargs,
                            action_label=f"{collector_id or function_tag} post-action power-on",
                            collector_label=collector_id or function_tag,
                        )
                        if not post_success:
                            error_messages.append(post_reason)

                    return await self._create_standardized_collector_result(
                        successful_operations=0,
                        total_operations=len(uri_list),
                        output_files=[],
                        error_messages=error_messages,
                        operation_name="chassis_oem_binary_action",
                        additional_context={
                            "function_tag": function_tag,
                            "targets": uri_list,
                            "successful_targets": 0,
                            "power_cycle": "pre_action_failed",
                        },
                        dut_id=dut_id,
                        collector_id=collector_id,
                    )

            for planned_action in planned_actions:
                chassis_uri = planned_action["chassis_uri"]
                context = planned_action["context"]
                chassis_id = planned_action["chassis_id"]
                socket_id = planned_action["socket_id"]
                action_target = planned_action["action_target"]

                if require_host_power_off:
                    host_off, reason = await self._check_power_state_off(
                        dut_id, power_state_uris, context
                    )
                    if not host_off:
                        error_messages.append(
                            f"{chassis_id}: host power precondition failed ({reason})"
                        )
                        continue

                post_success, post_response, _ = await self.dispatch_request(
                    dut_id=dut_id,
                    method="POST",
                    uri=action_target,
                    body=planned_action["payload"],
                    timeout=action_timeout,
                    bypass_cache=True,
                    error_context=f"invoke OEM action {action_target}",
                    retry_count=0,
                )
                if not post_success:
                    error_messages.append(
                        f"{chassis_id}: OEM action failed at {action_target}: {post_response}"
                    )
                    continue

                saved_file_path: Optional[str] = None
                artifact_bytes: Optional[Any] = None
                action_response_mode = "unknown"

                direct_blob = self._extract_binary_blob_from_response(
                    post_response, binary_response_paths
                )
                if direct_blob is not None:
                    if min_size_bytes and len(direct_blob) < min_size_bytes:
                        error_messages.append(
                            f"{chassis_id}: binary artifact smaller than expected "
                            f"({len(direct_blob)} < {min_size_bytes} bytes)"
                        )
                        continue
                    action_response_mode = (
                        "direct_binary"
                        if isinstance(post_response, bytes)
                        else "direct_base64_json"
                    )
                    saved_file_path = await self._save_data_to_file_with_pattern(
                        dut_id,
                        direct_blob,
                        function_tag,
                        output_pattern=output_pattern,
                        substitutions=context,
                        collector_id=collector_id,
                    )
                    artifact_bytes = direct_blob
                else:
                    download_uri = None
                    task_id = None
                    task_monitor_uri = None

                    if isinstance(post_response, dict):
                        for path in download_uri_paths:
                            candidate_uri = self._extract_nested_value(
                                post_response, path
                            )
                            if isinstance(candidate_uri, str) and candidate_uri:
                                download_uri = candidate_uri
                                break

                        task_monitor_uri = post_response.get("TaskMonitor")
                        odata_id = post_response.get("@odata.id", "")
                        if isinstance(odata_id, str) and "/Tasks/" in odata_id:
                            task_id = odata_id.split("/Tasks/")[-1]
                        elif post_response.get("Id") and not download_uri:
                            task_id = str(post_response["Id"])

                    if task_id:
                        action_response_mode = "task"
                        monitor_result = await self.monitor_task(
                            dut_id=dut_id,
                            task_id=task_id,
                            success_states=[
                                "Completed",
                                "CompletedOK",
                                "Success",
                            ],
                            failure_states=[
                                "Exception",
                                "Cancelled",
                                "Killed",
                                "Failed",
                            ],
                            terminal_states=[
                                "Completed",
                                "CompletedOK",
                                "Success",
                                "Exception",
                                "Cancelled",
                                "Killed",
                                "Failed",
                            ],
                            max_retries=task_max_retries,
                            poll_interval=task_poll_interval,
                        )
                        if not monitor_result.get("success", False):
                            error_messages.append(
                                f"{chassis_id}: task {task_id} did not complete successfully ({monitor_result.get('reason')})"
                            )
                            continue

                        if not task_monitor_uri:
                            task_service_uri = self.get_configured_uri(
                                dut_id, "TaskService"
                            )
                            task_monitor_uri = (
                                f"{task_service_uri}/TaskMonitors/{task_id}"
                            )

                        (
                            saved_file_path,
                            artifact_bytes,
                            error_message,
                        ) = await self._download_binary_from_uri(
                            dut_id=dut_id,
                            uri=task_monitor_uri,
                            context=context,
                            function_tag=function_tag,
                            output_pattern=output_pattern,
                            collector_id=collector_id,
                            raw_content_max_bytes=self._resolved_attachment_limit(
                                dut_id
                            ),
                            min_size_bytes=min_size_bytes,
                        )
                        if error_message:
                            error_messages.append(f"{chassis_id}: {error_message}")
                            continue
                    elif download_uri:
                        action_response_mode = "download_uri"
                        (
                            saved_file_path,
                            artifact_bytes,
                            error_message,
                        ) = await self._download_binary_from_uri(
                            dut_id=dut_id,
                            uri=download_uri,
                            context=context,
                            function_tag=function_tag,
                            output_pattern=output_pattern,
                            collector_id=collector_id,
                            raw_content_max_bytes=self._resolved_attachment_limit(
                                dut_id
                            ),
                            min_size_bytes=min_size_bytes,
                        )
                        if error_message:
                            error_messages.append(f"{chassis_id}: {error_message}")
                            continue
                    else:
                        error_messages.append(
                            f"{chassis_id}: OEM action response did not contain a binary payload, task reference, or download URI"
                        )
                        continue

                if not saved_file_path or artifact_bytes is None:
                    error_messages.append(
                        f"{chassis_id}: binary artifact was retrieved but could not be saved"
                    )
                    continue

                if min_size_bytes and len(artifact_bytes) < min_size_bytes:
                    error_messages.append(
                        f"{chassis_id}: binary artifact smaller than expected ({len(artifact_bytes)} < {min_size_bytes} bytes)"
                    )
                    continue

                output_files.append(saved_file_path)
                successful_operations += 1

                artifact_hash = None
                if isinstance(artifact_bytes, StreamedRedfishBody):
                    if hash_algorithm.lower() == "sha256":
                        artifact_hash = artifact_bytes.sha256
                        hash_algorithm = "sha256"
                    else:

                        def hash_published_artifact() -> str:
                            """
                            Hash published artifact.

                            After applying local validation, the function
                            forwards current instance state to
                            ``digest.hexdigest`` and preserves its return and
                            exception contract. Filesystem effects remain
                            confined to the caller-selected paths and the owning
                            resource lifecycle.

                            Returns:
                                The canonical published artifact text.
                            """
                            digest = hashlib.new(hash_algorithm)
                            with Path(saved_file_path).open("rb") as artifact_file:
                                while True:
                                    chunk = artifact_file.read(1024 * 1024)
                                    if not chunk:
                                        break
                                    digest.update(chunk)
                            return digest.hexdigest()

                        try:
                            artifact_hash = await self._run_blocking_redfish_operation(
                                hash_published_artifact
                            )
                        except ValueError:
                            artifact_hash = artifact_bytes.sha256
                            hash_algorithm = "sha256"
                else:
                    try:
                        artifact_hash = hashlib.new(
                            hash_algorithm, artifact_bytes
                        ).hexdigest()
                    except ValueError:
                        artifact_hash = hashlib.sha256(artifact_bytes).hexdigest()
                        hash_algorithm = "sha256"

                metadata = {
                    "chassis_id": chassis_id,
                    "socket_id": socket_id,
                    "resource_uri": chassis_uri,
                    "action_target": action_target,
                    "read_method": "redfish_oem",
                    "response_mode": action_response_mode,
                    "size_bytes": len(artifact_bytes),
                    hash_algorithm: artifact_hash,
                    "artifact_path": saved_file_path,
                    "timestamp_utc": datetime.now(timezone.utc).isoformat(),
                }
                metadata_path = await self._save_oem_binary_metadata(
                    dut_id=dut_id,
                    metadata=metadata,
                    function_tag=function_tag,
                    metadata_output_pattern=metadata_output_pattern,
                    collector_id=collector_id,
                    substitutions=context,
                )
                if metadata_path:
                    output_files.append(metadata_path)

            if restore_power_on_completion:
                post_action = power_cycle.get("post_action")
                restore_attempted = True
                post_success, post_reason, _ = (
                    await self._restore_power_after_oem_action(
                        dut_id=dut_id,
                        post_action=(
                            post_action if isinstance(post_action, dict) else {}
                        ),
                        context=kwargs,
                        action_label=f"{collector_id or function_tag} post-action power-on",
                        collector_label=collector_id or function_tag,
                    )
                )
                if not post_success:
                    error_messages.append(post_reason)

            additional_context = {
                "function_tag": function_tag,
                "targets": uri_list,
                "successful_targets": successful_operations,
            }
            if power_cycle_enabled:
                additional_context["power_cycle"] = (
                    "restored" if restore_power_on_completion else "not_required"
                )

            return await self._create_standardized_collector_result(
                successful_operations=successful_operations,
                total_operations=len(uri_list),
                output_files=output_files,
                error_messages=error_messages,
                operation_name="chassis_oem_binary_action",
                additional_context=additional_context,
                dut_id=dut_id,
                collector_id=collector_id,
            )

        except BaseException as e:
            restore_error_message = None
            cleanup_cancelled = False
            if (
                restore_power_on_completion
                and not restore_attempted
                and isinstance(power_cycle, dict)
            ):
                restore_attempted = True
                try:
                    post_action = power_cycle.get("post_action")
                    (
                        post_success,
                        post_reason,
                        _,
                    ) = await self._restore_power_after_oem_action(
                        dut_id=dut_id,
                        post_action=(
                            post_action if isinstance(post_action, dict) else {}
                        ),
                        context=kwargs,
                        action_label=f"{kwargs.get('collector_id') or function_tag} post-action power-on",
                        collector_label=kwargs.get("collector_id") or function_tag,
                    )
                    if not post_success:
                        restore_error_message = post_reason
                except asyncio.CancelledError:
                    cleanup_cancelled = True
                except Exception as restore_error:
                    restore_error_message = (
                        "Exception while restoring host power: "
                        f"{type(restore_error).__name__}"
                    )
                    await self._log_runtime(
                        "ERROR",
                        "RedfishService",
                        restore_error_message,
                        dut_id,
                    )

            if isinstance(e, asyncio.CancelledError) or cleanup_cancelled:
                raise asyncio.CancelledError from e
            if not isinstance(e, Exception):
                raise

            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_chassis_oem_binary_action: {e}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=0,
                output_files=[],
                error_messages=[f"Exception in collect_chassis_oem_binary_action: {e}"]
                + ([restore_error_message] if restore_error_message else []),
                operation_name="chassis_oem_binary_action",
                additional_context={"error_type": type(e).__name__, "status": "error"},
                dut_id=dut_id,
                collector_id=kwargs.get("collector_id"),
            )

    async def monitor_task(
        self, dut_id: str, function_tag: str = "", **kwargs
    ) -> Dict[str, Any]:
        """
        Monitor a catalog task through the diagnostic orchestration boundary.

        After applying local validation, the function forwards ``dut_id``,
        ``function_tag``, and ``kwargs`` to ``monitor_task`` and preserves its
        return and exception contract. Owned asynchronous work is awaited before
        return, so completion does not leave an unobserved task behind.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing monitor task.
        """
        return await self._diagnostic_runner().monitor_task(
            dut_id, function_tag=function_tag, **kwargs
        )

    async def _wait_for_system_ready_after_reset(
        self,
        dut_id: str,
        system_id: str,
        timeout_seconds: int,
        poll_interval: int,
    ) -> Tuple[bool, str]:
        """
        Wait for a system resource to become reachable again after a reset.

        Some platforms do not expose useful power/boot indicators. A.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            system_id: Stable system identifier used to correlate configuration,
                logs, and results.
            timeout_seconds: Maximum duration in seconds allowed for timeout
                seconds.
            poll_interval: Maximum duration in seconds allowed for poll
                interval.

        Returns:
            A tuple containing ``success flag`` and ``status or message text``
            in that order.
        """
        systems_uri = self.get_configured_uri(dut_id, ResourceType.SYSTEMS.value)
        system_uri = f"{systems_uri.rstrip('/')}/{system_id}"
        deadline = time.monotonic() + max(0, timeout_seconds)
        attempt = 0
        last_observation = "system resource not reachable"

        while True:
            attempt += 1
            success, response, error_details = await self.dispatch_request(
                dut_id=dut_id,
                method="GET",
                uri=system_uri,
                bypass_cache=True,
            )
            if success and isinstance(response, dict):
                power_state = response.get("PowerState")
                boot_progress = response.get("BootProgress")
                if power_state == "On":
                    return True, "PowerState=On"
                if isinstance(boot_progress, dict):
                    last_state = boot_progress.get("LastState")
                    if last_state:
                        return True, f"BootProgress.LastState={last_state}"

                # Some platforms do not expose useful power/boot indicators. A
                # successful GET confirms the system resource is reachable again.
                return True, "system resource reachable"

            last_observation = str(error_details or response)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                (
                    f"Waiting for {system_id} to return after reset; "
                    f"attempt {attempt}, remaining={int(remaining)}s"
                ),
                dut_id,
            )
            await asyncio.sleep(min(max(1, poll_interval), remaining))

        return False, last_observation

    async def collect_command_executor(
        self,
        dut_id: str,
        function_tag: str,
        command_config: Dict[str, Any],
        **kwargs,
    ) -> Dict[str, Any]:
        """
        Generic command executor for configurable command execution.

        The implementation uses ``dut_id``, ``function_tag``,
        ``command_config``, and ``kwargs`` to generic command executor for
        configurable command execution. Owned asynchronous work is awaited
        before return, so completion does not leave an unobserved task behind.
        Filesystem effects remain confined to the caller-selected paths and the
        owning resource lifecycle. Remote I/O uses the configured transport
        policy and returns only after its response or failure has been observed.

        Args:
            dut_id: Stable DUT identifier used to correlate configuration, logs,
                and results.
            function_tag: Text supplied as function tag in the format accepted
                by this function.
            command_config: Command config governing generic command executor
                for configurable command execution.
            kwargs: Additional named values forwarded without changing their
                keys.

        Returns:
            A mapping containing command executor.
        """
        try:
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Starting command executor for {function_tag}",
                dut_id,
            )

            # Extract configuration
            base_uri = command_config.get("base_uri", "")
            device_discovery = command_config.get("device_discovery", {})
            command_groups = command_config.get("command_groups", [])

            # Define collection name for summary generation (matching host service pattern)
            collection_name = f"{function_tag} Collection"

            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"=== R42 EXECUTION START === function_tag='{function_tag}', collection_name='{collection_name}'",
                dut_id,
            )

            def _make_json_safe(value: Any) -> Any:
                """
                Return the make JSON safe.

                Sets are unordered; sort for deterministic JSON representation.

                Args:
                    value: Value object whose ``items`` state is read while
                        performing make JSON safe.

                Returns:
                    The make JSON safe.
                """
                if isinstance(value, (str, int, float, bool)) or value is None:
                    return value
                if isinstance(value, dict):
                    return {k: _make_json_safe(v) for k, v in value.items()}
                if isinstance(value, (list, tuple)):
                    return [_make_json_safe(v) for v in value]
                if isinstance(value, set):
                    # Sets are unordered; sort for deterministic JSON representation
                    return [
                        _make_json_safe(v)
                        for v in sorted(value, key=lambda item: str(item))
                    ]
                if isinstance(value, bytes):
                    try:
                        encoded = base64.b64encode(value).decode("ascii")
                    except (UnicodeDecodeError, binascii.Error):
                        encoded = str(value)
                    return {"encoding": "base64", "value": encoded}
                return str(value)

            def _nsm_completion_error(response: Any) -> Optional[str]:
                """
                Return a command-level NSM failure even when HTTP succeeded.

                The implementation uses ``response`` to produce a command-level
                NSM failure even when HTTP succeeded. Remote I/O uses the
                configured transport policy and returns only after its response
                or failure has been observed.

                Args:
                    response: Transport response governed by the configured
                        authentication and trust policy.

                Returns:
                    The canonical nsm completion error text, or ``None`` when
                    the requested value is unavailable.
                """
                if not isinstance(response, dict):
                    return "NSM response is not a JSON object"
                completion_code = response.get("CompletionCode")
                if completion_code is None:
                    return "NSM response is missing CompletionCode"
                try:
                    normalized_code = int(completion_code)
                except (TypeError, ValueError):
                    return (
                        f"NSM response has invalid CompletionCode {completion_code!r}"
                    )
                if normalized_code == 0:
                    return None
                reason_code = response.get("ReasonCode")
                reason_suffix = (
                    f" (ReasonCode {reason_code})" if reason_code is not None else ""
                )
                return f"NSM CompletionCode {normalized_code}{reason_suffix}"

            # Apply prefix override if URI config manager is available
            if base_uri and self.dut_manager and self.dut_manager.uri_config_manager:
                base_uri = self.dut_manager.uri_config_manager._apply_prefix_override(
                    base_uri, dut_id
                )

            if not base_uri:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=["No base_uri specified in command configuration"],
                    operation_name="command_executor",
                    additional_context={"command_config": command_config},
                )

            # === PRE-CHECK ENDPOINT ===
            # Verify the base endpoint exists before running commands
            # This prevents wasting time on 48+ commands if the endpoint doesn't exist
            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Pre-checking endpoint availability: {base_uri}",
                dut_id,
            )

            # For POST endpoints, we need to check if the Actions endpoint exists
            # Extract the base path without the action part
            endpoint_check_uri = base_uri
            if "/Actions/" in base_uri:
                # For action URIs, check the parent resource
                endpoint_check_uri = base_uri.split("/Actions/")[0]

            success, response, _ = await self.dispatch_request(
                dut_id, "GET", endpoint_check_uri
            )

            if not success:
                skip_message = (
                    f"Endpoint not available: {endpoint_check_uri}. "
                    f"The command executor service may not be supported on this baseboard."
                )
                await self._log_runtime(
                    "WARNING",
                    "RedfishService",
                    skip_message,
                    dut_id,
                )
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=[],
                    operation_name="command_executor",
                    additional_context={
                        "status": "skipped",
                        "reason": skip_message,
                        "endpoint_checked": endpoint_check_uri,
                    },
                    dut_id=dut_id,
                    collector_id=kwargs.get("collector_id"),
                )

            # If this is an Actions endpoint, also verify the action is supported
            if "/Actions/" in base_uri:
                actions = response.get("Actions", {})
                # Extract action name
                action_parts = base_uri.split("/Actions/")[-1].split("/")
                action_name = action_parts[0] if action_parts else ""

                if action_name:
                    oem_actions = actions.get("Oem", {})
                    action_key = f"#{action_name}"
                    if action_key not in oem_actions and action_name not in str(
                        actions
                    ):
                        skip_message = (
                            f"Action '{action_name}' not supported on this endpoint. "
                            f"Available actions: {list(actions.keys())}"
                        )
                        await self._log_runtime(
                            "WARNING",
                            "RedfishService",
                            skip_message,
                            dut_id,
                        )
                        return await self._create_standardized_collector_result(
                            successful_operations=0,
                            total_operations=0,
                            output_files=[],
                            error_messages=[],
                            operation_name="command_executor",
                            additional_context={
                                "status": "skipped",
                                "reason": skip_message,
                                "action_name": action_name,
                            },
                            dut_id=dut_id,
                            collector_id=kwargs.get("collector_id"),
                        )

            await self._log_runtime(
                "INFO",
                "RedfishService",
                f"Endpoint pre-check passed: {endpoint_check_uri}",
                dut_id,
            )

            # Get device discovery configuration
            use_firmware_inventory = device_discovery.get(
                "use_firmware_inventory", True
            )
            discovery_method = device_discovery.get("method", "firmware_inventory")
            discovery_context = dict(kwargs)
            if device_discovery.get("baseboard_specific_config") is not None:
                discovery_context["baseboard_specific_config"] = device_discovery[
                    "baseboard_specific_config"
                ]

            # Discover devices based on method
            discovered_devices = {}
            if discovery_method == "firmware_inventory":
                discovered_devices = await self._discover_chassis_devices(
                    dut_id,
                    device_types=["gpu"],
                    device_patterns={"gpu": [".*GPU.*", ".*SXM.*"]},
                    use_firmware_inventory=use_firmware_inventory,
                    **discovery_context,
                )
            elif discovery_method == "chassis_device_discovery":
                # Use chassis-based device discovery with custom patterns
                device_patterns = device_discovery.get("device_patterns", {})
                device_types = (
                    list(device_patterns.keys()) if device_patterns else ["gpu"]
                )
                discovered_devices = await self._discover_chassis_devices(
                    dut_id,
                    device_types=device_types,
                    device_patterns=device_patterns,
                    use_firmware_inventory=use_firmware_inventory,
                    **discovery_context,
                )
            elif discovery_method == "entity_collection":
                # Discover from entity collections (Systems, Chassis, Managers)
                entity_type = device_discovery.get("entity_type", "Systems")
                entity_uri = self.get_configured_uri(dut_id, entity_type)
                success, entities_response, _ = await self.dispatch_request(
                    dut_id, "GET", entity_uri
                )
                if success:
                    entities = entities_response.get("Members", [])
                    entity_ids = []
                    for entity in entities:
                        entity_id = entity.get("@odata.id", "").split("/")[-1]
                        if entity_id:
                            entity_ids.append(entity_id)
                    discovered_devices[entity_type] = entity_ids
            elif discovery_method == "static_list":
                # Use static list from configuration
                discovered_devices = device_discovery.get("static_devices", {})

            # Extract the actual discovered devices from the result
            if isinstance(discovered_devices, dict) and "context" in discovered_devices:
                discovered_devices = discovered_devices["context"].get(
                    "discovered_devices", {}
                )

            if not discovered_devices:
                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=0,
                    output_files=[],
                    error_messages=["No devices discovered for command execution"],
                    operation_name="command_executor",
                    additional_context={"device_discovery": device_discovery},
                )

            output_files = []
            status_list = []
            error_messages = []
            optional_failures = []

            # Process each command group
            dut_config = (
                self.dut_manager.get_dut_config(dut_id) if self.dut_manager else {}
            ) or {}
            target_baseboard = (
                kwargs.get("target_baseboard")
                or dut_config.get("baseboard")
                or dut_config.get("TargetBaseboard", "")
            )

            def command_applies(command: Dict[str, Any]) -> bool:
                """
                Exclude only commands denied by the exact catalog platform name.

                Filter before operation accounting so an unsupported sensor is
                not dispatched or represented as a failed or successful read.
                Unknown platforms retain the generic command list.

                Args:
                    command: Authored command with an optional exclusion list.

                Returns:
                    Whether the command applies to this resolved DUT.

                Raises:
                    ValueError: If the exclusion field is not a list of names.
                """
                excluded = command.get("exclude_baseboards", [])
                if not isinstance(excluded, list) or any(
                    not isinstance(name, str)
                    or not name.strip()
                    or name != name.strip()
                    or "|" in name
                    or "\n" in name
                    or "\r" in name
                    for name in excluded
                ):
                    raise ValueError(
                        "Command exclude_baseboards must list platform names"
                    )
                return target_baseboard not in excluded

            for group in command_groups:
                group_name = group.get("name", "unknown_group")
                device_type = group.get("device_type", "GPU")
                commands = [
                    command
                    for command in group.get("commands", [])
                    if command_applies(command)
                ]

                # Get device instances for this type (case-insensitive lookup)
                device_instances = []
                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Looking for device_type '{device_type}' in discovered_devices: {discovered_devices}",
                    dut_id,
                )
                for key, value in discovered_devices.items():
                    await self._log_runtime(
                        "DEBUG",
                        "RedfishService",
                        f"Comparing '{key.lower()}' with '{device_type.lower()}'",
                        dut_id,
                    )
                    if key.lower() == device_type.lower():
                        device_instances = value
                        await self._log_runtime(
                            "DEBUG",
                            "RedfishService",
                            f"Found match! device_instances = {device_instances}",
                            dut_id,
                        )
                        break

                if not device_instances:
                    await self._log_runtime(
                        "WARN",
                        "RedfishService",
                        f"No {device_type} devices found for command group {group_name}",
                        dut_id,
                    )
                    continue

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Processing command group {group_name} for {len(device_instances)} {device_type} devices",
                    dut_id,
                )

                # Execute commands for each device instance
                for device_instance in device_instances:
                    for command in commands:
                        task = command.get("task", "unknown_task").replace(
                            "{device_instance}", str(device_instance)
                        )
                        action = command.get("action", "POST")
                        payload_template = command.get("payload_template", {})
                        output_pattern = command.get("output_pattern", "")
                        is_long_running = command.get("is_long_running", False)
                        wait_time = command.get("wait_time", 5)
                        command_required = command.get("required", True) is not False

                        # Substitute variables in payload template
                        payload = {}
                        for key, value in payload_template.items():
                            if isinstance(value, str):
                                # Replace common placeholders
                                substituted_value = value.replace(
                                    "{device_instance}", str(device_instance)
                                )
                                substituted_value = substituted_value.replace(
                                    "{device_type}", device_type
                                )
                                substituted_value = substituted_value.replace(
                                    "{group_name}", group_name
                                )
                                payload[key] = substituted_value
                            elif isinstance(value, list):
                                # Handle list values (like Data arrays)
                                payload[key] = value
                            else:
                                payload[key] = value

                        # Special handling for DeviceInstanceId - ensure it's an integer
                        if "DeviceInstanceId" in payload and isinstance(
                            payload["DeviceInstanceId"], str
                        ):
                            try:
                                payload["DeviceInstanceId"] = int(
                                    payload["DeviceInstanceId"]
                                )
                            except (ValueError, TypeError):
                                # Keep as string if conversion fails
                                pass

                        # Execute the command
                        nsm_completion_error = None
                        (
                            success,
                            response_data,
                            error_details,
                        ) = await self.dispatch_request(
                            dut_id, action, base_uri, body=payload
                        )

                        if success:
                            request_entry = {
                                "method": action,
                                "uri": base_uri,
                                "group": group_name,
                                "device_type": device_type,
                                "device_instance": device_instance,
                                "payload": _make_json_safe(payload),
                            }
                            response_entry = _make_json_safe(response_data)
                            record = {
                                "request": request_entry,
                                "response": response_entry,
                            }

                            # Save response
                            if output_pattern:
                                final_output_pattern = output_pattern
                                # Replace variables in output pattern
                                final_output_pattern = final_output_pattern.replace(
                                    "{device_instance}",
                                    str(device_instance),
                                )
                                final_output_pattern = final_output_pattern.replace(
                                    "{task}", task
                                )
                                final_output_pattern = final_output_pattern.replace(
                                    "{device_type}", device_type
                                )
                                final_output_pattern = final_output_pattern.replace(
                                    "{group_name}", group_name
                                )

                                # Remove output_pattern from kwargs to avoid duplicate argument
                                filtered_kwargs = {
                                    k: v
                                    for k, v in kwargs.items()
                                    if k != "output_pattern"
                                }

                                file_path = await self._save_data_with_common_pattern(
                                    dut_id,
                                    record,
                                    function_tag,
                                    output_pattern=final_output_pattern,
                                    substitutions={
                                        "device_instance": device_instance,
                                        "task": task,
                                        "group_name": group_name,
                                        "device_type": device_type,
                                    },
                                    **filtered_kwargs,
                                )
                                if file_path:
                                    output_files.append(file_path)

                            # Wait for long-running commands
                            if is_long_running:
                                await asyncio.sleep(wait_time)

                            nsm_completion_error = _nsm_completion_error(response_data)
                            if nsm_completion_error:
                                success = False
                                error_details = {
                                    **(error_details or {}),
                                    "nsm_completion_error": nsm_completion_error,
                                }
                        if not success:
                            # Capture detailed error information with HTTP status codes
                            error_msg = f"Command failed: {group_name}/{task} for {device_type} device {device_instance}"

                            # Canonical request capture owns the detailed body.
                            payload_str = json.dumps(
                                self._bounded_request_payload_summary(payload),
                                sort_keys=True,
                                separators=(",", ":"),
                            )
                            await self._log_runtime(
                                "DEBUG",
                                "RedfishService",
                                f"Creating error message for failed command: {group_name}/{task}, device={device_instance}, success={success}, response_data={type(response_data)}, error_details={error_details}, payload={payload_str}",
                                dut_id,
                            )

                            # Extract HTTP status code and detailed error information
                            if error_details and error_details.get(
                                "nsm_completion_error"
                            ):
                                error_msg += (
                                    f" - {error_details['nsm_completion_error']}"
                                )
                            elif error_details and error_details.get("http_status"):
                                # Use detailed error information from DUT manager
                                http_status = error_details.get("http_status")
                                error_message = error_details.get(
                                    "error_message", response_data
                                )
                                if response_data == "retry":
                                    if len(error_message) > 4000:
                                        error_msg += f" - HTTP {http_status} Server Error (retry exhausted) - {error_message[:4000]}... [truncated]"
                                    else:
                                        error_msg += f" - HTTP {http_status} Server Error (retry exhausted) - {error_message}"
                                else:
                                    if len(error_message) > 4000:
                                        error_msg += f" - HTTP {http_status}: {error_message[:4000]}... [truncated]"
                                    else:
                                        error_msg += (
                                            f" - HTTP {http_status}: {error_message}"
                                        )
                            elif isinstance(response_data, str):
                                # Check if it's a retry response
                                if response_data == "retry":
                                    error_msg += " - HTTP 5xx Server Error (retry exhausted) - Check BMC logs for specific error details"
                                # Check if it's an HTTP error response
                                elif response_data.startswith("HTTP "):
                                    error_msg += f" - {response_data}"
                                else:
                                    error_msg += f" - Response: {response_data}"
                            elif isinstance(response_data, dict):
                                # Extract structured error information
                                if "HTTPStatus" in response_data:
                                    status = response_data.get("HTTPStatus", "Unknown")
                                    message = response_data.get(
                                        "Message", "No message provided"
                                    )
                                    error_msg += f" - HTTP {status}: {message}"
                                elif "error" in response_data:
                                    error_obj = response_data["error"]
                                    if isinstance(error_obj, dict):
                                        error_code = error_obj.get("code", "Unknown")
                                        error_message = error_obj.get(
                                            "message", str(response_data)
                                        )
                                        error_msg += f" - Code: {error_code}, Message: {error_message}"
                                    else:
                                        error_msg += f" - Error: {error_obj}"
                                else:
                                    error_msg += f" - Error: {response_data.get('error', response_data)}"

                            optional_unsupported = False
                            if (
                                not command_required
                                and error_details
                                and error_details.get("nsm_completion_error")
                                and isinstance(response_data, dict)
                            ):
                                try:
                                    optional_unsupported = int(
                                        response_data.get("CompletionCode")
                                    ) in {2, 5}
                                except (TypeError, ValueError):
                                    optional_unsupported = False

                            if optional_unsupported:
                                optional_failures.append(
                                    {
                                        "group": group_name,
                                        "task": task,
                                        "device_type": device_type,
                                        "device_instance": device_instance,
                                        "reason": error_msg,
                                    }
                                )
                                await self._log_runtime(
                                    "WARNING",
                                    "RedfishService",
                                    f"Optional NSM command was not supported: {error_msg}. POST payload sent: {payload_str}",
                                    dut_id,
                                )
                            else:
                                error_messages.append(error_msg)

                                # Log detailed error for debugging (including POST payload)
                                if response_data == "retry":
                                    await self._log_runtime(
                                        "ERROR",
                                        "RedfishService",
                                        f"Command execution failed after retries: {error_msg} - This indicates a persistent 5xx server error. Check BMC logs for detailed error information. POST payload sent: {payload_str}",
                                        dut_id,
                                    )
                                else:
                                    await self._log_runtime(
                                        "ERROR",
                                        "RedfishService",
                                        f"Command execution failed: {error_msg}. POST payload sent: {payload_str}",
                                        dut_id,
                                    )

                                # Create error log file for failed required commands.
                                error_log_path = await self._create_error_log_file(
                                    dut_id=dut_id,
                                    collector_id=kwargs.get("collector_id"),
                                    error_message=error_msg,
                                    context={
                                        "group_name": group_name,
                                        "task": task,
                                        "device_type": device_type,
                                        "device_instance": device_instance,
                                        "action": action,
                                        "uri": base_uri,
                                        "payload_summary": (
                                            self._bounded_request_payload_summary(
                                                payload
                                            )
                                        ),
                                        "http_status": (
                                            error_details.get("http_status")
                                            if error_details
                                            else None
                                        ),
                                        "error_response": (
                                            error_details.get("error_message")
                                            if error_details
                                            else response_data
                                        ),
                                        "operation": "command_executor",
                                    },
                                )

                                if error_log_path:
                                    output_files.append(error_log_path)

                        status_list.append(success)

            # Determine the status based on results
            successful_operations = sum(status_list)
            total_operations = len(status_list)
            optional_failure_count = len(optional_failures)
            optional_failure_reason = None
            if optional_failure_count and not error_messages:
                label = "command" if optional_failure_count == 1 else "commands"
                optional_failure_reason = (
                    "Required NSM command set complete: "
                    f"{successful_operations}/{total_operations} commands succeeded; "
                    f"{optional_failure_count} optional {label} unsupported"
                )

            # Create detailed failure information for failures.json
            failure_details = []
            if error_messages:
                for i, error_msg in enumerate(error_messages):
                    failure_details.append(
                        {
                            "failure_id": i + 1,
                            "error_message": error_msg,
                            "timestamp": await self._get_current_timestamp(),
                            "collector": function_tag,
                            "dut_id": dut_id,
                        }
                    )

            # Log final operation counts for debugging
            await self._log_runtime(
                "DEBUG",
                "RedfishService",
                f"Final operation counts: successful={successful_operations}, total={total_operations}, failed={len(error_messages)}, output_files={len(output_files)}",
                dut_id,
            )

            if total_operations == 0:
                complete_on_empty_targets = kwargs.get(
                    "complete_on_empty_targets", False
                )
                reason_msg = f"No operations attempted for {function_tag} - " + (
                    "treated as complete"
                    if complete_on_empty_targets
                    else "collector skipped"
                )

                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Completed command executor for {function_tag} - no operations attempted, "
                    f"treating as {'complete' if complete_on_empty_targets else 'skipped'}",
                    dut_id,
                )

                # Generate summary files
                await self._handle_collection_summary_generation(
                    dut_id=dut_id,
                    function_tag=function_tag,
                    collection_name=collection_name,
                    total_operations=0,
                    successful_operations=(1 if complete_on_empty_targets else 0),
                    failed_operations=0,
                    output_files=[],
                    additional_details={},
                    kwargs=kwargs,
                )

                # Force status/reason to reflect completion when allowed
                status_override = "success" if complete_on_empty_targets else "skipped"

                result = await self._create_standardized_collector_result(
                    successful_operations=(1 if complete_on_empty_targets else 0),
                    total_operations=1 if complete_on_empty_targets else 0,
                    output_files=[],
                    error_messages=[],
                    operation_name="command_executor",
                    additional_context={
                        "command_groups_processed": len(command_groups),
                        "total_commands": len(status_list),
                        "successful_commands": successful_operations,
                        "status": status_override,
                        "reason": reason_msg,
                    },
                )

                # Propagate overrides in the execution_result for downstream handling
                if complete_on_empty_targets:
                    result["status_override"] = "success"
                    result["reason_override"] = reason_msg

                return result
            elif successful_operations == 0 and error_messages:
                # All operations failed - treat as error
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Completed command executor for {function_tag} - all {total_operations} operations failed",
                    dut_id,
                )

                # Generate summary files and failures.json
                await self._handle_collection_summary_generation(
                    dut_id=dut_id,
                    function_tag=function_tag,
                    collection_name=collection_name,
                    total_operations=total_operations,
                    successful_operations=0,
                    failed_operations=total_operations,
                    output_files=output_files,
                    additional_details={"error_messages": error_messages},
                    kwargs=kwargs,
                )
                await self._save_failures_json(
                    dut_id,
                    function_tag,
                    failure_details,
                    kwargs.get("collector_id", ""),
                )

                return await self._create_standardized_collector_result(
                    successful_operations=0,
                    total_operations=total_operations,
                    output_files=output_files,
                    error_messages=[],
                    operation_name="command_executor",
                    additional_context={
                        "command_groups_processed": len(command_groups),
                        "total_commands": len(status_list),
                        "successful_commands": successful_operations,
                        "status": "error",
                        "reason": f"All {total_operations} operations failed for {function_tag}",
                    },
                )
            elif error_messages:
                # Some operations succeeded, some failed - treat as partial
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    f"Completed command executor for {function_tag} - {successful_operations}/{total_operations} operations succeeded (partial)",
                    dut_id,
                )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Status determination: {successful_operations}/{total_operations} -> PARTIAL status",
                    dut_id,
                )

                # Generate summary files and failures.json
                await self._handle_collection_summary_generation(
                    dut_id=dut_id,
                    function_tag=function_tag,
                    collection_name=collection_name,
                    total_operations=total_operations,
                    successful_operations=successful_operations,
                    failed_operations=total_operations - successful_operations,
                    output_files=output_files,
                    additional_details={"error_messages": error_messages},
                    kwargs=kwargs,
                )
                await self._save_failures_json(
                    dut_id,
                    function_tag,
                    failure_details,
                    kwargs.get("collector_id", ""),
                )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"=== R42 RETURNING PARTIAL RESULT === successful_operations={successful_operations}, total_operations={total_operations}, output_files={len(output_files)}, error_messages={len(error_messages)}",
                    dut_id,
                )

                return await self._create_standardized_collector_result(
                    successful_operations=successful_operations,
                    total_operations=total_operations,
                    output_files=output_files,
                    error_messages=error_messages,
                    operation_name="command_executor",
                    additional_context={
                        "command_groups_processed": len(command_groups),
                        "total_commands": len(status_list),
                        "successful_commands": successful_operations,
                        "optional_failure_count": optional_failure_count,
                        "optional_failures": optional_failures,
                    },
                )
            else:
                # Every required operation succeeded. Optional commands may be
                # unsupported on a particular NSM implementation.
                await self._log_runtime(
                    "INFO",
                    "RedfishService",
                    optional_failure_reason
                    or f"Completed command executor for {function_tag} - all {total_operations} operations succeeded",
                    dut_id,
                )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"Status determination: {successful_operations}/{total_operations} -> SUCCESS status",
                    dut_id,
                )

                # Generate summary files
                await self._handle_collection_summary_generation(
                    dut_id=dut_id,
                    function_tag=function_tag,
                    collection_name=collection_name,
                    total_operations=total_operations,
                    successful_operations=successful_operations,
                    failed_operations=0,
                    skipped_operations=optional_failure_count,
                    output_files=output_files,
                    additional_details={
                        "Optional command failures": optional_failure_count,
                        "Optional failure details": optional_failures,
                        **(
                            {"status_note_override": optional_failure_reason}
                            if optional_failure_reason
                            else {}
                        ),
                    },
                    kwargs=kwargs,
                )

                await self._log_runtime(
                    "DEBUG",
                    "RedfishService",
                    f"=== R42 RETURNING SUCCESS RESULT === successful_operations={successful_operations}, total_operations={total_operations}, output_files={len(output_files)}",
                    dut_id,
                )

                return await self._create_standardized_collector_result(
                    successful_operations=successful_operations,
                    total_operations=total_operations,
                    output_files=output_files,
                    error_messages=[],
                    operation_name="command_executor",
                    additional_context={
                        "command_groups_processed": len(command_groups),
                        "total_commands": len(status_list),
                        "successful_commands": successful_operations,
                        "optional_failure_count": optional_failure_count,
                        "optional_failures": optional_failures,
                        **(
                            {
                                "status": "success",
                                "reason": optional_failure_reason,
                            }
                            if optional_failure_reason
                            else {}
                        ),
                    },
                )

        except Exception as e:
            await self._log_runtime(
                "ERROR",
                "RedfishService",
                f"Exception in collect_command_executor: {str(e)}",
                dut_id,
            )
            return await self._create_standardized_collector_result(
                successful_operations=0,
                total_operations=1,
                output_files=[],
                error_messages=[f"Exception in command executor: {str(e)}"],
                operation_name="command_executor",
                additional_context={},
            )
